import{n as e}from"./rolldown-runtime-hePW80VL.js";var t=e({diyaloglar:()=>r,dosyalar:()=>n}),n=JSON.parse(`[{"ders":"mesleki-gelisim","sinif":9,"unite":1,"baslik":"İletişimin Gücü","onay":true,"kazanimlar":["Farklı iletişim tarzlarının mesleki başarı ve iş ilişkileri üzerindeki etkilerini karşılaştırabilme.","İletişim engellerini aşmaya yönelik çıkarım yapabilme.","İletişim stratejilerini, paydaşların beklenti ve duygusal durumlarını dikkate alarak tartışabilme.","İletişim süreçlerini etkileyen faktörleri yansıtabilme.","İletişim süreçlerinde ortaya çıkabilecek çatışmaları doğru yapılandırabilme."],"soz":"Söylediğin kadar, nasıl söylediğin ve nasıl dinlediğinle anılırsın.","dersler":[{"baslik":"Mesaj Yerine Ulaştı mı?","ilk":"mg-1-001"},{"baslik":"“Saat 12.00, Değil mi?”","ilk":"mg-1-005"},{"baslik":"Sektörün Dili: Otelde Bilgi Hangi Yoldan Akar?","ilk":"mg-1-092"},{"baslik":"Aynı Şikâyet, Dört Ayrı Cevap","ilk":"mg-1-020"},{"baslik":"Nazik Ama Net Olunur mu?","ilk":"mg-1-026"},{"baslik":"İyi Konuşan Neden İyi Çalışır?","ilk":"mg-1-030"},{"baslik":"Söyledin Ama Anlaşıldı mı?","ilk":"mg-1-034"},{"baslik":"Ortamı Okumak, Sınırını Bilmek","ilk":"mg-1-110"},{"baslik":"Söz Uçar, Yazı Kalır","ilk":"mg-1-008"},{"baslik":"Tek Kelime Etmeden Konuşmak","ilk":"mg-1-012"},{"baslik":"Bakışın, Sesin, Üniforman","ilk":"mg-1-016"},{"baslik":"Sektörün Dili: Daha Konuşmadan Tanınırsın","ilk":"mg-1-096"},{"baslik":"Mesaj Yolda Neden Kaybolur?","ilk":"mg-1-045"},{"baslik":"Kırk Misafir, Kırk Ayrı İnsan","ilk":"mg-1-052"},{"baslik":"Aynı Dil, Ayrı Kültür","ilk":"mg-1-048"},{"baslik":"Yorgun Beden, Çelişen Yüz","ilk":"mg-1-111"},{"baslik":"Ben mi, Sen mi?","ilk":"mg-1-028"},{"baslik":"Duymak Yetmez, Dinlemek Gerek","ilk":"mg-1-039"},{"baslik":"Doğru Soru, Yapıcı Söz","ilk":"mg-1-041"},{"baslik":"Kime, Ne Zaman, Nasıl?","ilk":"mg-1-055"},{"baslik":"Şikâyet Geldi: Dört Adım","ilk":"mg-1-059"},{"baslik":"Sektörün Dili: O Kısa Anda Otel Sensin","ilk":"mg-1-097"},{"baslik":"Çelişkiyi Yakalamak","ilk":"mg-1-118"},{"baslik":"Savunmaya Geçmeden","ilk":"mg-1-129"},{"baslik":"Baskı Altında Sesin Neden Değişir?","ilk":"mg-1-063"},{"baslik":"Önce Hangi İş, Öfke Gelince Ne?","ilk":"mg-1-066"},{"baslik":"Kendine Ayna Tut","ilk":"mg-1-069"},{"baslik":"Dilek mi, Hedef mi?","ilk":"mg-1-073"},{"baslik":"Yapabilir miyim, Ne Zamana Kadar?","ilk":"mg-1-077"},{"baslik":"Sözünün Arkasında Durmak","ilk":"mg-1-113"},{"baslik":"Önce Dur, Sonra Konuş","ilk":"mg-1-116"},{"baslik":"Anlaşmazlık Kötü Bir Şey mi?","ilk":"mg-1-050"},{"baslik":"Bir Tartışma, Beş Yol","ilk":"mg-1-082"},{"baslik":"İki Taraf da Kazanabilir mi?","ilk":"mg-1-087"},{"baslik":"Sektörün Dili: “Bana Kimse Söylemedi”","ilk":"mg-1-101"},{"baslik":"Bastırmak Çözüm mü?","ilk":"mg-1-120"},{"baslik":"Bu İş Kimin İşi?","ilk":"mg-1-123"}],"kavramlar":[{"id":"mg-1-001","konu":"1.1","terim":"İletişim","ingilizce":"Communication","tanim":"Duygu, düşünce ve bilgilerin kişiler arasında bir kanal aracılığıyla karşılıklı aktarılma süreci.","ornek":"Sabah 07.00, resepsiyon: gece vardiyasından çıkan görevli “312’nin kliması arızalı, teknik servis dokuzda gelecek” der; sabahçı “Tamam, misafire ben haber veririm” diye karşılık verir.","sektor":"Programın anahtar kavramlarındandır. Otelde iş, bilgi doğru kişiye doğru biçimde ulaştığında yürür. Ne söylediğin kadar nasıl söylediğin de mesajdır.","iliskili":["mg-1-009","mg-1-002","mg-1-006"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-009","konu":"1.1","terim":"İletişim bileşenleri","ingilizce":"Elements of communication","tanim":"Süreci oluşturan öğeler: gönderici, mesaj, kanal, alıcı, geri bildirim ve gürültü.","ornek":"Saat 11.00, resepsiyon: görevli (gönderici) çıkış saatini (mesaj) yüz yüze (kanal) söyler; misafir (alıcı) “Saat 12.00, değil mi?” diye sorar (geri bildirim). Lobideki uğultu ise gürültüdür.","sektor":"Bir yanlış anlaşılma yaşandığında “Zincir nerede koptu?” diye bu öğelere bakılır: mesaj mı açık değildi, kanal mı yanlıştı, geri bildirim mi alınmadı?","iliskili":["mg-1-001","mg-1-002","mg-1-003","mg-1-004","mg-1-005","mg-1-006","mg-1-007"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-002","konu":"1.1","terim":"Gönderici (kaynak)","ingilizce":"Sender","tanim":"Mesajı oluşturan ve ileten kişi. Örnek: misafire bilgi veren resepsiyonist.","ornek":"Saat 09.00, seyahat acentesi: görevli müşteriye tur programını e-postayla yazar. Bu iletişimde gönderici acente görevlisidir.","sektor":"Mesajın anlaşılır olması önce göndericinin sorumluluğundadır. “Ben söyledim, o anlamadı” demek profesyonelce değildir; anlaşılana kadar iş bitmiş sayılmaz.","iliskili":["mg-1-003","mg-1-005","mg-1-009"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-003","konu":"1.1","terim":"Mesaj (ileti)","ingilizce":"Message","tanim":"Göndericinin aktarmak istediği bilgi, duygu ya da düşünce.","ornek":"Sabah 11.15: kat görevlisinin resepsiyona telefonla söylediği “Oda 208 hazır” cümlesi bir mesajdır.","sektor":"İyi mesaj kısa, açık ve eksiksizdir: oda numarası, saat ve isim belirsiz bırakılmaz. “Odalardan biri hazır” diyen görevli resepsiyonu ikinci kez aratır.","iliskili":["mg-1-002","mg-1-004","mg-1-035"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-004","konu":"1.1","terim":"Kanal","ingilizce":"Channel","tanim":"Mesajın iletildiği yol ya da araç: yüz yüze konuşma, telefon, e-posta, anons.","ornek":"Aynı bilgi üç ayrı yoldan gidebilir: kat şefi telsizle söyler, vardiya defterine yazar ya da görevlinin yanına gidip yüz yüze anlatır.","sektor":"Kanal işe göre seçilir: acil konu e-postayla değil, telefonla ya da yüz yüze iletilir; sonradan gerekecek bilgi yazıya geçirilir. Yanlış seçilen kanal doğru mesajı da boşa çıkarır.","iliskili":["mg-1-003","mg-1-010","mg-1-011"],"kontrol":null},{"id":"mg-1-005","konu":"1.1","terim":"Alıcı","ingilizce":"Receiver","tanim":"Mesajı alan ve yorumlayan kişi.","ornek":"Akşam 20.00, restoran: garson mutfağa “Yedi numaralı masada fıstık alerjisi var” der. Bu cümleyi dinleyen aşçı o anda alıcıdır.","sektor":"Roller sürekli değişir: az önce dinleyen cevap verdiği anda gönderici olur. Alıcı yorgun, öfkeli ya da başka işle meşgulse mesaj yerine ulaşmaz.","iliskili":["mg-1-002","mg-1-006","mg-1-039"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-006","konu":"1.1","terim":"Geri bildirim","ingilizce":"Feedback","tanim":"Alıcının mesaja verdiği tepki; mesajın doğru anlaşılıp anlaşılmadığını gösterir.","ornek":"Saat 12.00, kat koridoru: kat şefi telsizle “405 öncelikli, misafir 14.00’te gelecek” der; kat görevlisi “Anlaşıldı, 405 saat 14.00’ten önce hazır olacak” diye karşılık verir.","sektor":"Geri bildirim yoksa mesajın ulaşıp ulaşmadığı bilinmez. Baş sallamak, “Anladım” demek de geri bildirimdir; staj yerinde talimatı sessizce dinleyip gitmek şefi belirsizlikte bırakır.","iliskili":["mg-1-005","mg-1-008","mg-1-044"],"kontrol":null},{"id":"mg-1-007","konu":"1.1","terim":"Gürültü","ingilizce":"Noise","tanim":"Mesajın doğru ulaşmasını engelleyen her şey: kalabalık, telefon paraziti, dikkat dağınıklığı.","ornek":"Öğlen 13.00, mutfak: davlumbazın uğultusu içinde söylenen “on iki numaralı masa” sözü “iki numaralı masa” diye duyulur ve tabak yanlış masaya gider.","sektor":"Gürültü yalnız ses değildir; dağılan dikkat de mesajı bozar. Bunu fark eden profesyonel sakin bir yere geçer, yavaşlar ve bilgiyi tekrar ettirir.","iliskili":["mg-1-008","mg-1-045","mg-1-046"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-092","konu":"1.1","terim":"Biçimsel (resmî) iletişim","ingilizce":"Formal communication","tanim":"İşletmenin kurallarına ve hiyerarşisine uygun, resmî kanallarla yapılan iletişim.","ornek":"Sabah 09.00 toplantısında ön büro müdürü yeni çıkış saatini duyurur; karar aynı gün bölümlere yazılı olarak da gönderilir.","sektor":"İzin talebi, arıza bildirimi, vardiya çizelgesi gibi işler resmî yoldan yürür: kime, nasıl bildirileceği bellidir. Kayıt kaldığı için “Ben duymadım” denemez.","iliskili":["mg-1-093","mg-1-094","mg-1-004","mg-1-011"],"kontrol":null,"kitapDisi":true},{"id":"mg-1-093","konu":"1.1","terim":"Biçimsel olmayan iletişim","ingilizce":"Informal communication","tanim":"Çalışanlar arasında resmî kurallar dışında kendiliğinden gelişen iletişim.","ornek":"Öğle arası, personel yemekhanesi: iki çalışan sohbet ederken biri ötekine “Yarın büyük bir grup geliyormuş” der.","sektor":"Ekibi yakınlaştırır ve bilgi hızlı yayılır; ama doğrulanmamış bilgi söylentiye dönüşebilir. Kulaktan duyduğun haberi misafire aktarmadan önce amirinden teyit et.","iliskili":["mg-1-092","mg-1-008","mg-1-095"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"mg-1-094","konu":"1.1","terim":"Dikey iletişim","ingilizce":"Vertical communication","tanim":"Yönetici ile çalışan arasında yukarıdan aşağıya ya da aşağıdan yukarıya yapılan iletişim.","ornek":"Ön büro müdürü vardiyaya “Bugün 12 erken giriş var” der (yukarıdan aşağıya). Stajyer de “Yazıcı arızalı” bilgisini amirine iletir (aşağıdan yukarıya).","sektor":"Talimat yukarıdan gelir, sahadaki bilgi aşağıdan çıkar. Stajyerin gördüğü bir aksaklığı amirine söylemesi şikâyetçilik değil, işin gereğidir.","iliskili":["mg-1-095","mg-1-092","mg-1-006"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"mg-1-095","konu":"1.1","terim":"Yatay iletişim","ingilizce":"Horizontal communication","tanim":"Aynı düzeydeki çalışanlar ya da bölümler arasındaki iletişim (örn. ön büro ile kat hizmetleri).","ornek":"Saat 12.10: kat görevlisi resepsiyonu arar: “305 hazır.” Resepsiyonist lobide bekleyen misafire anahtarını verir.","sektor":"Misafire verilen hizmet bölümler arasında elden ele geçer. Ön büro, kat hizmetleri ve teknik servis birbirine zamanında haber vermezse aksaklığı misafir yaşar.","iliskili":["mg-1-094","mg-1-105","mg-1-091","mg-1-008"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"mg-1-020","konu":"1.1","terim":"Hitap","ingilizce":"Form of address","tanim":"Konuşurken karşıdakine seslenme biçimi: “Efendim”, “Hanımefendi”, “Bay Yılmaz”.","ornek":"Sabah 08.30, lobi: stajyer adını bildiği misafire “Günaydın Fatma Hanım” der; adını bilmediğine “Günaydın efendim” diye seslenir.","sektor":"Hitap, saygının ilk işaretidir: misafire “abi”, “abla”, “teyze” gibi günlük sözlerle seslenilmez. Misafirin önünde ekip arkadaşlarına da “Bey” ya da “Hanım” sözüyle hitap edilir.","iliskili":["mg-1-010","mg-1-037","mg-1-038"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-022","konu":"1.1","terim":"İletişim tarzı","ingilizce":"Communication style","tanim":"Kişinin duygu ve ihtiyaçlarını ifade ederken sürekli kullandığı davranış biçimi.","ornek":"Aynı şikâyete dört ayrı cevap: biri susar, biri misafiri suçlar, biri iğneleyerek “Siz bilirsiniz” der, biri özür dileyip çözüm önerir.","sektor":"Dört tarz vardır: pasif, agresif, pasif-agresif ve atılgan. Hangi tarzı kullandığın hem misafirin memnuniyetini hem ekipteki yerini belirler.","iliskili":["mg-1-023","mg-1-024","mg-1-025","mg-1-026"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-023","konu":"1.1","terim":"Pasif iletişim","ingilizce":"Passive communication","tanim":"İhtiyacını söylemeyen, çatışmadan kaçan tarz; sorun çözülmez, kişi yıpranır.","ornek":"Akşam 19.00, resepsiyon: misafir odasının değiştirilmesini ister; görevli boş oda olup olmadığına bakmadan “Şey… Bir şey yapamam herhalde” deyip susar.","sektor":"Staj yerinde anlamadığın işi sormamak, üstüne fazla iş yüklendiğinde susmak da pasifliktir. Söylenmeyen sorun büyür; sonunda bedelini hem misafir hem sen ödersin.","iliskili":["mg-1-022","mg-1-024","mg-1-027"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-024","konu":"1.1","terim":"Agresif (saldırgan) iletişim","ingilizce":"Aggressive communication","tanim":"Suçlayan, sesini yükselten, karşısındakini ezen tarz; ilişkiler zarar görür.","ornek":"Saat 12.30, resepsiyon: geç çıkış ücretine itiraz eden misafire görevli sesini yükseltir: “Kuralları okumadınız mı? Benim suçum değil!”","sektor":"Bağırdığın anda haklıyken haksız duruma düşersin: misafir kaybedilir, gerginlik artar. Ekip içinde de agresif kişiye kimse hatasını bildirmek istemez.","iliskili":["mg-1-022","mg-1-023","mg-1-029","mg-1-017"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-025","konu":"1.1","terim":"Pasif-agresif iletişim","ingilizce":"Passive-aggressive communication","tanim":"Öfkeyi açıkça değil, dolaylı yoldan, iğneleyerek gösteren tarz; güveni yok eder.","ornek":"Öğlen 13.00, restoran: yemeğini değiştirmek isteyen misafire garson göz devirerek “Tabii efendim, siz nasıl isterseniz…” der.","sektor":"Söz naziktir, ama ses tonu ve beden dili öfkeyi ele verir; misafir bunu hemen fark eder. Yüze karşı susup arkadan söylenmek de bu tarzın işaretidir.","iliskili":["mg-1-022","mg-1-024","mg-1-012"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-026","konu":"1.1","terim":"Atılgan (güvenli) iletişim","ingilizce":"Assertive communication","tanim":"Hem kendine hem karşısındakine saygı göstererek düşünceyi açık ve net ifade eden tarz.","ornek":"Gece 23.00, resepsiyon: kliması çalışmayan misafire görevli “Yaşadığınız sorun için üzgünüm. Size iki seçenek sunabilirim: teknik servisi hemen yönlendireyim ya da sizi başka bir odaya alalım” der.","sektor":"Mesleki başarıyı güçlendiren tarz budur: sorun açıkça konuşulur, kimse ezilmez, iki taraf da kazanır. Atılgan olmak sert olmak değildir; nazik ama net olmaktır.","iliskili":["mg-1-027","mg-1-028","mg-1-022","mg-1-087"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-027","konu":"1.1","terim":"Atılganlık","ingilizce":"Assertiveness","tanim":"Başkalarının haklarını çiğnemeden kendi düşünce ve ihtiyaçlarını açıkça savunabilme.","ornek":"Saat 15.00, kat ofisi: stajyere aynı anda iki ayrı iş verilir. Stajyer “İkisini birden yetiştiremem; önce hangisini yapmamı istersiniz?” diye sorar.","sektor":"Programın anahtar kavramlarındandır. Stajda her şeye “tamam” deyip yetiştirememek de, sert çıkmak da işe yaramaz. Sınırını saygıyla söyleyebilen stajyere daha çok güvenilir.","iliskili":["mg-1-026","mg-1-023","mg-1-028"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-030","konu":"1.1","terim":"Mesleki başarı","ingilizce":"Professional success","tanim":"Kişinin mesleğinde hedeflerine ulaşması, verimli çalışması ve takdir görmesi.","ornek":"Staj sonunda şefin değerlendirme formuna “Anlamadığını sorar, misafirle güler yüzle konuşur, ekiple uyumlu çalışır” yazması.","sektor":"Turizmde iş insanla yapılır: mesleğini iyi bilen ama iletişimi zayıf olan personel misafirin karşısında zorlanır. Atılgan tarz mesleki başarıyı destekler; pasif ve agresif tarzlar zorlaştırır.","iliskili":["mg-1-026","mg-1-031","mg-1-032"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-1-031","konu":"1.1","terim":"İş ilişkileri","ingilizce":"Work relationships","tanim":"Çalışanın iş arkadaşları, yöneticiler ve misafirlerle kurduğu ilişkiler.","ornek":"Bir resepsiyon görevlisi aynı saat içinde kat şefiyle telefonda, müdürüyle toplantıda, misafirle bankoda konuşur: üç ayrı ilişki, aynı saygı.","sektor":"Misafir yalnız karşısındaki personeli görür; ama aldığı hizmet, perde arkasındaki ekibin birbiriyle nasıl konuştuğuna bağlıdır. Kendi içinde çatışan ekibin gerginliğini misafir hemen hisseder.","iliskili":["mg-1-030","mg-1-056","mg-1-091"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-032","konu":"1.1","terim":"Verimlilik","ingilizce":"Productivity","tanim":"Kullanılan emek, zaman ve malzeme ile elde edilen sonuç arasındaki oran.","ornek":"Saat 10.00, kat ofisi: kat şefi “Odaları hızlı yapın” demek yerine “405 ve 407 öncelikli, misafirler 14.00’te geliyor” der; kimse yanlış odayla vakit kaybetmez.","sektor":"Açık iletişim aynı emekle daha çok iş çıkarır: yanlış anlaşılan talimat, işin iki kez yapılması demektir. Gergin ekipte ise zaman işe değil tartışmaya gider.","iliskili":["mg-1-030","mg-1-031","mg-1-066"],"kontrol":null,"cizim":"enerji"},{"id":"mg-1-033","konu":"1.1","terim":"Kriz yönetimi","ingilizce":"Crisis management","tanim":"Beklenmedik, acil ve zor durumlarda sakin kalıp doğru kararları alma süreci.","ornek":"Akşam 21.00, dolu bir otel: elektrik kesilir. Vardiya şefi sesini yükseltmeden görev dağıtır: “Sen teknik servisi ara, sen lobideki misafirleri bilgilendir.”","sektor":"Kriz anında pasif kalan donar, agresif davranan paniği büyütür; atılgan tarz kısa ve net sözlerle ekibi toparlar. Misafir, personelin sakinliğinden güven alır.","iliskili":["mg-1-026","mg-1-017","mg-1-064"],"kontrol":null,"gorsel":"m1-gemide-yangin-tatbikati"},{"id":"mg-1-034","konu":"1.1","terim":"Etkili iletişim","ingilizce":"Effective communication","tanim":"Mesajın karşı tarafa doğru ve eksiksiz ulaştığı, amacına varan iletişim.","ornek":"Saat 10.00, resepsiyon: stajyer misafire “Kahvaltı yedinci katta, 10.30’a kadar açık” der. Misafir “Yedinci kat, on buçuğa kadar” diye tekrarlar ve asansöre yönelir; mesaj eksiksiz ulaşmıştır.","sektor":"Otelde yanlış anlaşılan tek bir saat ya da oda numarası, kaçan bir servise ya da yanlış odaya giden bir valize dönüşür. Konuşmuş olmak yetmez; iletişim, mesajın anlaşıldığından emin olunca tamamlanır.","iliskili":["mg-1-035","mg-1-039","mg-1-006","mg-1-008"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-035","konu":"1.1","terim":"Açıklık (netlik)","ingilizce":"Clarity","tanim":"Kısa, anlaşılır cümleler kurmak ve terimleri karşı tarafa açıklamak.","ornek":"Akşam 18.00, resepsiyon: görevli “Late check-out talebiniz opsiyonda” demek yerine “Odanızda saat 14.00’e kadar kalıp kalamayacağınızı yarın sabah size haber vereceğim” der.","sektor":"Meslek terimleri ekibin kendi arasında işi hızlandırır, misafirin karşısında ise duvar olur. Terimi kullanacaksan ne demek olduğunu da söyle; misafir sormaya çekinebilir.","iliskili":["mg-1-034","mg-1-047","mg-1-021"],"kontrol":null},{"id":"mg-1-037","konu":"1.1","terim":"Saygı","ingilizce":"Respect","tanim":"Hitapta, ses tonunda ve beden dilinde karşıdakinin değerini gözetmek.","ornek":"Saat 16.00, lobi: yaşlı bir misafir aynı soruyu üçüncü kez sorar. Stajyer sesini yükseltmeden, yüzünü buruşturmadan “Tabii efendim” der ve yeniden anlatır.","sektor":"Saygı yalnız misafire gösterilmez: kat görevlisiyle, bulaşıkhanedeki arkadaşla, tedarikçiyle de aynı ses tonuyla konuşulur. Misafire nazik, ekibine sert davranan personel güven kaybeder.","iliskili":["mg-1-038","mg-1-020","mg-1-017","mg-1-013"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-107","konu":"1.1","terim":"Doğruluk","ingilizce":"Accuracy","tanim":"Verilen bilginin gerçeğe uygun, eksiksiz ve yanıltmayan biçimde aktarılmasıdır.","ornek":"Saat 11.00, resepsiyon: misafir havuzun kaça kadar açık olduğunu sorar. Stajyer emin değildir; tahmin yürütmez, “Hemen öğrenip size bildireyim efendim” der ve doğru saati öğrenip söyler.","sektor":"Öğretim programı etkili iletişimin ilkelerini açıklık, doğruluk, saygı ve empati olarak sayar. Emin olmadığın bilgiyi verme: yanlış söylenen bir saat ya da fiyat, misafirin işletmeye güvenini zedeler. “Bilmiyorum, ama hemen öğreneyim” demek profesyonelce bir cevaptır.","iliskili":["mg-1-034","mg-1-035","mg-1-037","mg-1-036","mg-1-008"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-036","konu":"1.1","terim":"Empati","ingilizce":"Empathy","tanim":"Kendini karşındakinin yerine koyarak onun duygu ve düşüncelerini anlamak.","ornek":"Gece 01.00, resepsiyon: uzun bir yolculuktan gelen misafir odasının hazır olmadığını öğrenince sinirlenir. Görevli “Yorucu bir yolculuktan sonra beklemek zor, haklısınız” diyerek söze başlar.","sektor":"Programın anahtar kavramlarındandır. Misafir önce anlaşılmak ister, sonra çözüm. Empati her konuda hak vermek değildir; karşıdakinin ne hissettiğini görmek ve bunu ona göstermektir.","iliskili":["mg-1-039","mg-1-058","mg-1-049","mg-1-061"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-110","konu":"1.1","terim":"Bağlam (ortam)","ingilizce":"Context","tanim":"İletişimin gerçekleştiği fiziksel, sosyal ve psikolojik çevredir.","ornek":"Gece 23.00, sakin lobi: görevli çıkış saatini kısık sesle ve acele etmeden anlatır. Aynı bilgi cumartesi öğlen kalabalığında, ayakta ve hızlı söylenseydi mesaj daha kolay yanlış anlaşılırdı.","sektor":"Aynı bilgi lobide, telefonda ya da yazıda farklı bir üslupla verilir. Yeri, saati ve karşıdakinin ruh hâlini gözeten çalışan mesajını ona göre ayarlar; bağlam iletişimin bileşenlerinden biridir.","iliskili":["mg-1-009","mg-1-004","mg-1-007"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-128","konu":"1.1","terim":"İş doyumu","ingilizce":"Job satisfaction","tanim":"Çalışanın işinden ve çalışma ortamından duyduğu memnuniyettir.","ornek":"Sezon ortasında kat görevlisi Elif, ekibinin ona “Teşekkürler” demesi ve vardiya çizelgesinin adil olması sayesinde işini severek yapar.","sektor":"Memnun çalışan misafire de daha sıcak davranır; saygı ve açık iletişim iş doyumunu artırır (ders kitabına göre).","iliskili":["mg-1-037","mg-1-034","mg-1-030"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"mg-1-131","konu":"1.1","terim":"Sınır koyma","ingilizce":"Setting boundaries","tanim":"Kişinin kendi kapasitesini ve haklarını korumak için gerektiğinde “hayır” diyebilmesi ve kişisel sınırlarını kırıcı olmadan belirtmesidir.","ornek":"Saat 17.30, kat ofisi: şef stajyer Ali’ye aynı anda üçüncü işi de verir. Ali “İkisini yetiştirebilirim; üçüncüsü için yardım gerekir, hangisini öne alalım?” der.","sektor":"Atılgan iletişimin parçasıdır; sınırı kırıcı olmadan söylemek saldırganlık değildir. Ne kadar iş alabileceğini bilen stajyer hata ve yorgunluktan korunur.","iliskili":["mg-1-026","mg-1-027","mg-1-024"],"kontrol":null,"cizim":"pasaport"},{"id":"mg-1-008","konu":"1.2","terim":"Teyit","ingilizce":"Confirmation","tanim":"Anlaşılan bilginin karşı tarafa tekrar sorularak doğrulanması. Örnek: “Check-out saat 12.00, değil mi?”","ornek":"Saat 10.30, seyahat acentesi: müşteri telefonda tarih söyler; görevli “Yedi Mart, iki kişi, doğru mu efendim?” diye sorar.","sektor":"Oda numarası, tarih, saat ve isim gibi bilgiler tekrar edilerek doğrulanır. “Mart” ile “mayıs”ın karışması, misafir kapıya geldiğinde adına oda bulunmaması demektir.","iliskili":["mg-1-006","mg-1-007","mg-1-040"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-010","konu":"1.2","terim":"Sözlü iletişim","ingilizce":"Oral communication","tanim":"Konuşarak yapılan iletişim: yüz yüze görüşme, telefon, anons.","ornek":"Sabah 08.45, toplantı odası: ön büro müdürü günün girişlerini ve çıkışlarını ekibe anlatır, ekip sorularını o anda sorar.","sektor":"Programın anahtar kavramlarındandır. Misafirle temasın büyük bölümü sözlüdür: karşılama, bilgi verme, telefon. Hızlıdır ve sıcaktır; ama söylenen her söz işletmenin ağzından çıkmış sayılır.","iliskili":["mg-1-021","mg-1-020","mg-1-011","mg-1-012"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-021","konu":"1.2","terim":"Diksiyon","ingilizce":"Diction","tanim":"Sözcükleri doğru, açık ve anlaşılır biçimde telaffuz etme.","ornek":"Saat 09.10, santral: görevli telefonu açar; sözcükleri yutmadan, acele etmeden “İyi günler, ön büro, ben Elif. Nasıl yardımcı olabilirim?” der.","sektor":"Telefonda misafir yüzünü görmez; işletmeyi yalnız sesinden tanır. Mırıldanan ya da çok hızlı konuşan personel ne kadar bilgili olursa olsun güven vermez.","iliskili":["mg-1-010","mg-1-017","mg-1-102"],"kontrol":null,"gorsel":"m1-mikrofon-kursu"},{"id":"mg-1-011","konu":"1.2","terim":"Yazılı iletişim","ingilizce":"Written communication","tanim":"Mesajın yazıyla iletilmesi: e-posta, rezervasyon onayı, not, form.","ornek":"Gece 23.00, resepsiyon: görevli vardiya defterine “Oda 510, uyandırma 05.30” yazar; sabaha kadar görevde olan herkes aynı notu okur.","sektor":"Yazı kalıcıdır: aylar sonra bir anlaşmazlık çıktığında “Kim, ne zaman, ne dedi?” sorusunun cevabı kayıttadır. Bu yüzden rezervasyon, misafir isteği ve vardiya notu yazıya geçirilir.","iliskili":["mg-1-010","mg-1-004","mg-1-106","mg-1-103"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-012","konu":"1.2","terim":"Sözsüz iletişim","ingilizce":"Non-verbal communication","tanim":"Kelime kullanmadan beden dili, ses tonu, kişisel mesafe ve görünümle yapılan iletişim.","ornek":"Akşam 20.30, kalabalık restoran: şef garson salonun öbür ucundaki garsona başıyla boşalan masayı gösterir; tek söz edilmeden masa toplanır.","sektor":"Programın anahtar kavramlarındandır. Söz ile beden dili çelişirse mesaj inandırıcılığını yitirir: “Memnuniyetle!” derken telefonuna bakan görevlinin sözüne misafir inanmaz.","iliskili":["mg-1-013","mg-1-017","mg-1-018","mg-1-019"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-013","konu":"1.2","terim":"Beden dili","ingilizce":"Body language","tanim":"Duruş, jest, mimik ve hareketlerle duygu ve düşüncelerin aktarılması.","ornek":"Saat 14.00, lobi: bavuluyla içeri giren misafir daha tek kelime duymadan, bankodaki görevlinin dik duruşundan ve gülümsemesinden “Doğru yere geldim” diye düşünür.","sektor":"Misafir personelin beden dilini sözünden önce okur: misafire dönük duruş ve açık kollar ilgi, kavuşturulmuş kollar ve yere bakan gözler ilgisizlik izlenimi verebilir. Beden dili tek başına kesin anlam taşımaz; kişinin durumu, kültürü ve ortam birlikte değerlendirilir, bu yüzden misafire verilen mesajda söz ile beden dili uyumlu olmalıdır.","iliskili":["mg-1-012","mg-1-014","mg-1-015","mg-1-016"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-1-014","konu":"1.2","terim":"Jest","ingilizce":"Gesture","tanim":"El, kol ve baş hareketleriyle verilen mesaj.","ornek":"Saat 15.00, lobi: bellboy açık avucuyla asansörü gösterip “Buyurun efendim” der.","sektor":"Otelde yön parmakla değil açık elle gösterilir: işaret parmağı azarlar gibi durur, açık avuç davet eder. Abartılı el kol hareketi ise sinirlilik izlenimi verir.","iliskili":["mg-1-013","mg-1-015","mg-1-048"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-1-015","konu":"1.2","terim":"Mimik","ingilizce":"Facial expression","tanim":"Yüz kaslarının hareketiyle oluşan ifade: gülümseme, kaş çatma.","ornek":"Saat 11.00, çıkış işlemi: “Konaklamanız nasıldı?” sorusuna “İyiydi” diyen misafirin kaşları çatıktır. Görevli bunu fark eder ve “Eksik bulduğunuz bir şey oldu mu efendim?” diye sorar.","sektor":"Misafirin yüzünü okuyabilen personel şikâyeti söze dökülmeden fark eder. Kendi mimiğin de ölçülü olmalıdır: abartılısı yapmacık durur, ifadesiz yüz ilgisizlik olarak okunur.","iliskili":["mg-1-013","mg-1-014","mg-1-016"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-1-016","konu":"1.2","terim":"Göz teması","ingilizce":"Eye contact","tanim":"Konuşurken karşıdakinin gözüne bakmak; ilgi ve güven gösterir.","ornek":"Saat 14.20, resepsiyon: görevli oda kartını uzatırken ekrana değil misafirin yüzüne bakarak “İyi konaklamalar dilerim” der.","sektor":"Göz teması “Sizi görüyorum, sizinle ilgileniyorum” demektir. Aşırıya kaçmamak gerekir: gözünü hiç ayırmadan bakmak da misafiri rahatsız eder.","iliskili":["mg-1-013","mg-1-015","mg-1-039"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-1-017","konu":"1.2","terim":"Ses tonu","ingilizce":"Tone of voice","tanim":"Sesin yüksekliği, sıcaklığı ve vurgusu; aynı cümleye farklı anlamlar katar.","ornek":"“Buyurun” sözü sakin ve sıcak bir sesle söylenirse davettir; sert bir sesle söylenirse “Ne istiyorsun?” gibi duyulur.","sektor":"Sakin ve net ses misafire “Durum kontrol altında” der. Öfkeli misafire sesini yükselterek cevap veren personel haklıyken haksız duruma düşer.","iliskili":["mg-1-012","mg-1-021","mg-1-024"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-018","konu":"1.2","terim":"Kişisel mesafe","ingilizce":"Personal space","tanim":"Kişilerin rahat hissetmek için aralarında bıraktığı fiziksel uzaklık.","ornek":"Saat 16.00, lobi: stajyer koltukta oturan misafire yol tarif ederken üzerine eğilmez; bir adım geride durup haritayı sehpaya koyar.","sektor":"Misafire fazla yaklaşmak onu rahatsız eder, fazla uzak durmak ilgisiz gösterir. Rahat bulunan uzaklık kişiden kişiye ve kültürden kültüre değişir; misafir geri çekiliyorsa mesafeyi açarsın.","iliskili":["mg-1-012","mg-1-013","mg-1-048"],"kontrol":null,"gorsel":"m1-mesafe-isaretleri"},{"id":"mg-1-019","konu":"1.2","terim":"Görünüm","ingilizce":"Appearance","tanim":"Kişinin kıyafeti, temizliği ve bakımı; söze gerek kalmadan karşı tarafa mesaj verir.","ornek":"Sabah 07.45, personel girişi: stajyer vardiyaya başlamadan aynada ütülü üniformasını, yaka kartını ve toplu saçını kontrol eder.","sektor":"Misafir tek kelime duymadan önce üniformaya bakar: temiz ve bakımlı personel “Bu işletmede işler özenle yapılır” mesajını verir.","iliskili":["mg-1-012","mg-1-099"],"kontrol":null,"cizim":"uniforma"},{"id":"mg-1-096","konu":"1.2","terim":"İş görgüsü","ingilizce":"Business etiquette","tanim":"İş ortamında uyulması beklenen davranış ve nezaket kurallarının bütünü.","ornek":"Stajın ilk günü: Ece vardiyadan on dakika önce gelir, üniforması ütülüdür, karşılaştığı herkese “Günaydın” der, telefonunu dolabında bırakır.","sektor":"Dakiklik, selamlaşma, “siz” diye hitap, misafir alanında telefonla ilgilenmemek: bunları kimse sınavda sormaz, ama herkes fark eder. İş görgüsü bilgin görülmeden önce senin hakkında konuşur.","iliskili":["mg-1-038","mg-1-020","mg-1-019","mg-1-099"],"kontrol":null,"kitapDisi":true,"gorsel":"t13e-kartvizit-uzatma"},{"id":"mg-1-099","konu":"1.2","terim":"İlk izlenim","ingilizce":"First impression","tanim":"Misafirin bir çalışanı ya da işletmeyi ilk gördüğü anda oluşan düşünce.","ornek":"Saat 14.00, otel girişi: misafir kapıdan girer girmez resepsiyonistin başını kaldırıp gülümsediğini görür. Daha tek kelime konuşulmadan otel hakkında bir fikri oluşmuştur.","sektor":"İlk izlenim çok kısa sürede oluşur ve sonradan değiştirilmesi zordur. Onu çoğu kez söz değil, sözsüz iletişim oluşturur: temiz üniforma, dik duruş, göz teması, gülümseme.","iliskili":["mg-1-019","mg-1-013","mg-1-016","mg-1-100"],"kontrol":null,"kitapDisi":true,"gorsel":"karsilama-bankosu"},{"id":"mg-1-102","konu":"1.2","terim":"Telefon görgüsü","ingilizce":"Telephone etiquette","tanim":"Telefonu çabuk açma, kendini ve işletmeyi tanıtma, nazik ve net konuşma kuralları.","ornek":"Saat 10.15, resepsiyon: telefon çalar. Görevli bekletmeden açar, “İyi günler” der, otelin adını ve kendi adını söyler, “Nasıl yardımcı olabilirim?” diye sorar.","sektor":"Telefonda misafir yüzünü görmez; seni yalnız sesinden tanır. Arayanı uzun süre bekletmek ya da kendini tanıtmadan konuşmak otelin ilk izlenimini daha misafir gelmeden zedeler.","iliskili":["mg-1-010","mg-1-017","mg-1-021","mg-1-099"],"kontrol":null,"kitapDisi":true,"gorsel":"telefonlar"},{"id":"mg-1-103","konu":"1.2","terim":"Netiket","ingilizce":"Netiquette","tanim":"E-posta ve internet yazışmalarında uyulan görgü kuralları.","ornek":"Bir misafir e-postayla havalimanı transferini sorar. Görevli; konu satırı açık, “Sayın …” hitabıyla başlayan, tümü büyük harfle yazılmamış, sonunda adı ve görevi bulunan kısa bir cevap gönderir.","sektor":"Rezervasyon yazışmalarının büyük bölümü e-posta ve mesajla yürür. Yazım hatalı, hitapsız ya da tümü büyük harfle yazılmış bir cevap özensiz bir üniforma kadar kötü izlenim bırakır.","iliskili":["mg-1-011","mg-1-020","mg-1-096"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-1-104","konu":"1.2","terim":"Kısa sohbet","ingilizce":"Small talk","tanim":"Misafirle hava, yolculuk gibi gündelik konularda yapılan kısa ve nazik konuşma.","ornek":"Asansörü beklerken bellboy misafire sorar: “Yolculuğunuz nasıl geçti efendim?” Misafir gülümser, iki cümle konuşurlar.","sektor":"Birkaç cümlelik sohbet misafire “fark edildim” duygusu verir. Konu hafif kalır: hava, yolculuk, şehir. Özel hayata, siyasete, dine girilmez; misafir konuşmak istemiyorsa uzatılmaz.","iliskili":["mg-1-010","mg-1-038","mg-1-099"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"mg-1-108","konu":"1.2","terim":"Duruş","ingilizce":"Posture","tanim":"Ayakta ya da otururken bedenin aldığı konumdur.","ornek":"Saat 14.00, lobi: bavullu misafir girerken bankodaki görevli dik durur ve gövdesiyle misafire döner.","sektor":"Misafir duruşu sözden önce okur: misafire dönük, dik duruş ilgi ve özgüven, çökük ya da arkası dönük duruş ilgisizlik mesajı verir.","iliskili":["mg-1-013","mg-1-012","mg-1-016"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-1-038","konu":"1.2","terim":"Nezaket","ingilizce":"Courtesy","tanim":"Kibar, ince ve düşünceli davranmak; “Lütfen”, “Teşekkür ederim” gibi kalıplar.","ornek":"Sabah 08.00, kahvaltı salonu: stajyer “Buraya oturamazsınız” demez; “Bu masa ayrılmış efendim, sizi cam kenarındaki masaya alabilir miyim, lütfen?” der ve yer değiştiren misafire teşekkür eder.","sektor":"Nezaket kalıpları en yoğun saatte de atlanmaz; “lütfen” ve “teşekkür ederim” bir saniye sürer. “Hayır” demek gerektiğinde bile ret nazik bir dille ve bir seçenek sunularak söylenir.","iliskili":["mg-1-037","mg-1-020","mg-1-096"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-045","konu":"1.2","terim":"İletişim engeli","ingilizce":"Communication barrier","tanim":"Mesajın doğru gönderilmesini, alınmasını ya da anlaşılmasını zorlaştıran etken.","ornek":"Saat 19.00, kalabalık lobi: görevli servis aracının sabah 06.30’da kalkacağını söyler. O sırada telefonuna bakan misafir saati duymaz ve sabah aracı kaçırır.","sektor":"Programın anahtar kavramlarındandır. Engeller beş başlıkta toplanabilir: fiziksel, dil ve anlam, kültürel, psikolojik, algı ve ön yargı. Engelin adını koyabilen personel çözümünü de bulur; koyamayan suçu misafirde ya da arkadaşında arar.","iliskili":["mg-1-046","mg-1-047","mg-1-048","mg-1-049","mg-1-007"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-046","konu":"1.2","terim":"Fiziksel engel","ingilizce":"Physical barrier","tanim":"Ortamdan kaynaklanan engel: gürültülü lobi, bozuk telefon hattı, uzaklık.","ornek":"Cumartesi 17.00, lobide düğün kalabalığı: stajyer yol tarifini bağırarak anlatmak yerine misafiri bankonun sakin ucuna alır ve tarifi küçük bir kâğıda da yazar.","sektor":"Çözümü çoğu zaman basittir: sakin bir alana geçmek, bilgiyi yazılı olarak da vermek, hat kötüyse misafiri geri aramak. Sesi yükseltmek engeli aşmaz; misafire azarlanıyormuş duygusu verir.","iliskili":["mg-1-045","mg-1-007","mg-1-004"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-047","konu":"1.2","terim":"Dil ve anlam engeli","ingilizce":"Language and semantic barrier","tanim":"Tarafların farklı dil konuşması ya da karşı tarafın bilmediği terim ve ifadelerin kullanılması.","ornek":"Saat 12.00, resepsiyon: yabancı misafir “late check-out” sözünü anlamaz. Görevli saatin üzerinde 14.00’ü gösterir ve kâğıda “Room until 14:00” yazar.","sektor":"İki biçimde ortaya çıkar: ortak dil yoktur ya da dil aynıdır, ama terim yabancıdır. Sade dil, yazı, harita, saat ve rakam göstermek işe yarar; ekip içi kısaltmalar misafire söylenmez.","iliskili":["mg-1-035","mg-1-045","mg-1-054"],"kontrol":null,"gorsel":"m1-cok-dilli-karsilama"},{"id":"mg-1-049","konu":"1.2","terim":"Psikolojik (duygusal) engel","ingilizce":"Psychological (emotional) barrier","tanim":"Öfke, stres, korku ve yorgunluk gibi duyguların iletişimi bozması.","ornek":"Saat 23.00, resepsiyon: uçağı rötar yapmış, öfkeli misafire görevli kahvaltı saatlerini ve havuz kurallarını sıralar; misafir hiçbirini duymaz. O an ihtiyacı olan tek şey anlaşılmak ve oda anahtarıdır.","sektor":"Engel iki tarafta da olabilir: öfkeli misafir, yorgun ve stresli çalışan. Önce duygu kabul edilir, karşıdaki sakinleşince çözüme geçilir; kendi yorgunluğunu fark etmek de işin parçasıdır.","iliskili":["mg-1-058","mg-1-036","mg-1-063","mg-1-067"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-052","konu":"1.2","terim":"Varsayım","ingilizce":"Assumption","tanim":"Doğruluğu kontrol edilmeden doğru kabul edilen düşünce.","ornek":"Saat 13.00, resepsiyon: görevli “Nasılsa biliyordur” diye düşünüp kahvaltı saatini söylemez; misafir ertesi sabah kapanmış salonla karşılaşır.","sektor":"Otelde “Öyle sanmıştım” cümlesi çoğu zaman bir aksaklığın ardından söylenir. Varsayım yerine soru sorulur: “Kahvaltı saatlerimizi iletmemi ister misiniz?”","iliskili":["mg-1-050","mg-1-041","mg-1-008","mg-1-051"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-051","konu":"1.2","terim":"Ön yargı","ingilizce":"Prejudice","tanim":"Bir kişi ya da durum hakkında yeterli bilgi ve deneyime dayanmadan önceden edinilen olumlu ya da olumsuz yargı.","ornek":"Sade giyimli, sırt çantalı misafire “Bu odayı tutmaz” diye düşünüp yalnız en ucuz odayı gösteren görevli misafire ne istediğini hiç sormamıştır.","sektor":"Ön yargı olumlu da olabilir: şık giyimli misafirin her söylediğini sorgusuz doğru saymak gibi. Otelde her misafir aynı standartta karşılanır; kıyafet, yaş, dil ya da ülke farklı davranmanın gerekçesi olamaz.","iliskili":["mg-1-053","mg-1-050","mg-1-052","mg-1-048"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-053","konu":"1.2","terim":"Kalıp yargı","ingilizce":"Stereotype","tanim":"Bir grubun bütün üyelerinin aynı özellikleri taşıdığını düşünen genelleme.","ornek":"Vardiya öncesi bir görevli “Bu ülkeden gelenler hep şikâyet eder” der ve gruptaki herkese mesafeli davranır; oysa otobüsten inen kırk kişi kırk ayrı insandır.","sektor":"Misafir bir ülkenin ya da yaş grubunun temsilcisi değil, tek bir kişidir. Kalıp yargıyla karşılanan misafir bunu çoğu zaman sözden değil bakıştan ve ses tonundan anlar.","iliskili":["mg-1-051","mg-1-054","mg-1-048"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-048","konu":"1.2","terim":"Kültürel engel","ingilizce":"Cultural barrier","tanim":"Selamlaşma, mesafe ve jestlerin kültürden kültüre farklı anlam taşıması.","ornek":"Saat 15.00, otel girişi: stajyer yeni gelen misafire elini uzatır; misafir elini göğsüne koyup başıyla selam verir. Stajyer alınmaz, gülümseyerek aynı biçimde karşılık verir.","sektor":"Tokalaşma, yakın durma, göz teması ve el işaretleri her kültürde aynı anlama gelmez. Emin değilsen misafirin selamlama biçimini izle ve ona uy; ön yargıyla değil merakla yaklaş.","iliskili":["mg-1-054","mg-1-018","mg-1-014","mg-1-053"],"kontrol":null},{"id":"mg-1-054","konu":"1.2","terim":"Kültürler arası iletişim","ingilizce":"Intercultural communication","tanim":"Farklı kültürlerden kişiler arasındaki iletişim; dil, jest ve geleneklere duyarlılık gerektirir.","ornek":"Temmuz, Antalya’da bir otel: aynı sabah resepsiyona üç ayrı ülkeden misafir gelir. Görevli üçünü de güler yüzle karşılar; hitabını, mesafesini ve konuşma hızını her misafire göre ayarlar.","sektor":"Turizm, farklı kültürlerden insanlarla her gün yüz yüze gelinen bir iştir. Misafirin dilinde birkaç selamlama sözü bilmek ve geleneklerine saygı göstermek, yabancı dil bilgisi kadar değerlidir.","iliskili":["mg-1-048","mg-1-047","mg-1-053"],"kontrol":null,"gorsel":"m1-ulke-bayraklari"},{"id":"mg-1-109","konu":"1.2","terim":"Mesleki jargon","ingilizce":"Professional jargon","tanim":"Bir meslekte çalışanların kendi aralarında kullandığı, o işi bilmeyenlerin anlamakta zorlanabildiği özel sözcük ve kısaltmalardır.","ornek":"Saat 11.00, resepsiyon: görevli aileye “odanız opsiyonda, upgrade bakarız” der; aile ne dendiğini anlamaz.","sektor":"Jargon ekip içinde zaman kazandırır, ama misafire söylendiğinde iletişim engeline döner; misafire sade dil kullanılır, terim gerekiyorsa açıklanır.","iliskili":["mg-1-045","mg-1-047","mg-1-007"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-111","konu":"1.2","terim":"Fizyolojik gürültü","ingilizce":"Physiological noise","tanim":"Yorgunluk, açlık ve hastalık gibi bedensel durumların mesajın alınmasını ya da verilmesini bozmasıdır.","ornek":"Sabah 06.30, kahvaltı salonu: gece boyunca uyumamış servis görevlisi şefin masa düzenini anlatan sözlerini yarım duyar ve yanlış masayı hazırlar.","sektor":"Uzun vardiyalarda yorgunluk ve açlık dikkati dağıtır; bu yüzden mola ve yemek arası işin parçasıdır. Önemli bilgi yorgun bir arkadaşa söylenirken yazıya da dökülür.","iliskili":["mg-1-007","mg-1-045","mg-1-046"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-112","konu":"1.2","terim":"Sözlü ve sözsüz mesaj tutarsızlığı","ingilizce":"Verbal and non-verbal incongruence","tanim":"Söylenen sözlerle beden dilinin, ses tonunun ve yüz ifadesinin birbirini desteklememesidir.","ornek":"Saat 10.20, ön büro: vardiya amiri stajyere “Hiç sorun yok, sen devam et” derken kaşlarını çatar ve sesi sertleşir; stajyer sözüne değil yüzüne bakıp çekinir.","sektor":"İnsanlar söz ile beden dili çeliştiğinde çoğunlukla beden diline inanır (ders kitabına göre). Misafire söylediğin söz ile yüzünün anlattığı aynı olmalıdır.","iliskili":["mg-1-012","mg-1-013","mg-1-015","mg-1-017"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-028","konu":"1.3","terim":"Ben dili","ingilizce":"I-message","tanim":"Duygu ve isteği suçlamadan kendi adına anlatma: “Bilgi geç gelince zor durumda kalıyorum.”","ornek":"Saat 16.00, vardiya devri: “Sen hep geç kalıyorsun” yerine “Devir gecikince misafir bilgilerini aktaramıyorum, zorlanıyorum” demek.","sektor":"Ben dili kişiyi değil sorunu konuşturur; karşıdaki savunmaya geçmez, çözüm arar. Sakin bir ses tonuyla birlikte kullanıldığında işe yarar.","iliskili":["mg-1-029","mg-1-026","mg-1-044"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-029","konu":"1.3","terim":"Sen dili","ingilizce":"You-message","tanim":"Karşıdakini suçlayan, yargılayan anlatım: “Sen hep geç haber veriyorsun!” Çatışmayı büyütür.","ornek":"Saat 19.40, servis hazırlığı: bardak kırılınca şefin “Yine sen kırdın, zaten hep dikkatsizsin” demesi.","sektor":"Suçlanan kişi çözüm aramayı bırakıp kendini savunmaya başlar; hata gizlenir ve tekrarlanır. Cümlende “hep”, “hiç”, “zaten” geçiyorsa büyük olasılıkla sen dili konuşuyorsun.","iliskili":["mg-1-028","mg-1-024","mg-1-080"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-039","konu":"1.3","terim":"Aktif dinleme","ingilizce":"Active listening","tanim":"Tüm dikkatle, sözü kesmeden dinleyip anlaşılanı geri yansıtarak dinleme.","ornek":"Gece 22.30, resepsiyon: misafir sorununu anlatırken stajyer elindeki kalemi bırakır, ona döner, sözünü kesmez. Misafir bitirince sorar: “Yanlış anlamadıysam odanızda sıcak su yok ve bunu akşam da bildirdiniz, doğru mu efendim?”","sektor":"Programın anahtar kavramlarındandır. Beş adımı vardır: tam dikkat, sözü kesmeme, yeniden ifade, soru sorma, özetleme. Dinlendiğini hisseden misafir çoğu zaman sakinleşir; çözüm de tahminle değil doğru bilgiyle aranır.","iliskili":["mg-1-040","mg-1-041","mg-1-043","mg-1-036","mg-1-016"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-040","konu":"1.3","terim":"Yeniden ifade etme","ingilizce":"Paraphrasing","tanim":"Karşıdakinin söylediğini kendi cümlelerinle tekrarlamak: “Yani klimanız çalışmıyor.”","ornek":"Saat 14.00, acente bankosu: müşteri uzun uzun anlatır. Stajyer “Yani iki yetişkin ve bir çocuk için, denize yakın, sessiz bir otel arıyorsunuz” der; müşteri “Evet, tam olarak” diye başını sallar.","sektor":"Yeniden ifade, duyduğunu kelimesi kelimesine tekrarlamak değildir; kendi cümlenle söylersin, yanlış anladıysan misafir hemen düzeltir. Böylece hata, iş yapılmadan önce yakalanır.","iliskili":["mg-1-039","mg-1-008","mg-1-043","mg-1-006"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-043","konu":"1.3","terim":"Özetleme","ingilizce":"Summarising","tanim":"Konuşmanın ana noktalarını ve varılan çözümü kısaca toparlamak.","ornek":"Saat 22.45, resepsiyon: “Özetle efendim: klimanız çalışmıyor, teknik servisi şimdi odanıza yönlendiriyorum; sorun giderilemezse sizi başka bir odaya alacağız.”","sektor":"Konuşmanın sonunda yapılır: misafir neyin yapılacağını bilerek ayrılır. Aynı özet vardiya devrinde arkadaşına aktarılırsa misafir derdini ikinci kez anlatmak zorunda kalmaz.","iliskili":["mg-1-039","mg-1-040","mg-1-008","mg-1-105"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-041","konu":"1.3","terim":"Açık uçlu soru","ingilizce":"Open-ended question","tanim":"“Evet/hayır” ile cevaplanamayan, ayrıntı isteyen soru: “Ne zamandan beri?”","ornek":"Saat 11.00, acente: stajyer “Nasıl bir tatil düşünüyorsunuz?” diye sorar; müşteri denizden, çocukların yaşından, bütçeden söz etmeye başlar.","sektor":"Konuşmanın başında, ihtiyacı ya da sorunu anlamak için kullanılır: ne, nasıl, ne zamandan beri. Şikâyette ayrıntıyı tahmin etmek yerine misafire anlattırır.","iliskili":["mg-1-042","mg-1-039","mg-1-052"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-042","konu":"1.3","terim":"Kapalı uçlu soru","ingilizce":"Closed-ended question","tanim":"Kısa ya da “evet/hayır” cevabı olan soru: “Odanız 205 mi?”","ornek":"Saat 11.20, acente: görüşmenin sonunda stajyer sorar: “Gidiş 12 Temmuz, dönüş 19 Temmuz, doğru mu?” Müşteri “Evet” der.","sektor":"Bilgiyi kesinleştirmek ve teyit almak için kullanılır: tarih, oda numarası, kişi sayısı. Yalnız kapalı uçlu soru sorulursa konuşma sorguya döner, misafir asıl derdini anlatamaz.","iliskili":["mg-1-041","mg-1-008","mg-1-039"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-044","konu":"1.3","terim":"Yapıcı geri bildirim","ingilizce":"Constructive feedback","tanim":"Kişiyi değil davranışı hedef alan, somut ve gelişime yönelik geri bildirim.","ornek":"Vardiya sonu, saat 16.00: şef stajyere “Sen dikkatsizsin” demez; “Bugün iki misafirin oda numarasını yüksek sesle söyledin. Yarın numarayı kart zarfına yazıp gösterelim” der.","sektor":"Stajda en çok geri bildirim alan sensin; kişiliğine değil yaptığın işe yönelik olduğunu bilirsen savunmaya geçmeden dinlersin. Arkadaşına geri bildirim verirken de ölçü aynıdır: davranış, somut örnek, bir sonraki adım.","iliskili":["mg-1-006","mg-1-028","mg-1-029","mg-1-069"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-055","konu":"1.3","terim":"İletişim stratejisi","ingilizce":"Communication strategy","tanim":"Mesajı kime, ne zaman, hangi kanalla ve nasıl ileteceğini önceden planlamak.","ornek":"Saat 20.00: yarın sabahki tekne turu hava nedeniyle iptal olur. Görevli bilgiyi panoya asıp bırakmaz; tura yazılan misafirleri akşamdan oda telefonlarından arar ve öbür günkü turu seçenek olarak sunar.","sektor":"Dört soruya cevap verilir: kime, ne zaman, hangi kanalla, nasıl? Acil konu e-postayla değil telefonla ya da yüz yüze iletilir; kötü haber geciktirilmez ve yanında bir seçenekle verilir.","iliskili":["mg-1-004","mg-1-056","mg-1-057","mg-1-058"],"kontrol":null},{"id":"mg-1-056","konu":"1.3","terim":"Paydaş","ingilizce":"Stakeholder","tanim":"Bir işten etkilenen ya da o işi etkileyen herkes: misafir, iş arkadaşı, yönetici, tedarikçi.","ornek":"Otele gelecek 40 kişilik grubun giriş saati 14.00’ten 11.00’e çekilir. Bu değişiklik misafirleri, resepsiyonu, kat hizmetlerini, mutfağı ve grubu getiren acenteyi etkiler; hepsi bu işin paydaşıdır.","sektor":"Aynı haber her paydaşa aynı dille verilmez: misafire nazik ve sade, şefe kısa ve net, tedarikçiye yazılı ve resmî. Kimin etkilendiğini saymadan verilen haberde biri hep unutulur.","iliskili":["mg-1-055","mg-1-031","mg-1-057","mg-1-095"],"kontrol":null},{"id":"mg-1-057","konu":"1.3","terim":"Beklenti","ingilizce":"Expectation","tanim":"Kişinin bir hizmetten ya da durumdan umduğu sonuç.","ornek":"İnternet sitesinde deniz manzaralı oda fotoğrafını görüp gelen misafir otoparka bakan odaya alınınca oda ne kadar temiz olursa olsun hayal kırıklığı yaşar.","sektor":"Beklentiyi tanıtım, fiyat ve verilen sözler oluşturur. Tutamayacağın sözü verme: “Beş dakikada hazır” deyip yirmi dakika bekletmek, baştan “Yirmi dakika sürecek” demekten çok daha fazla kırar.","iliskili":["mg-1-062","mg-1-056","mg-1-050","mg-1-059"],"kontrol":null},{"id":"mg-1-058","konu":"1.3","terim":"Duygusal durum","ingilizce":"Emotional state","tanim":"Kişinin o anki duygusu: sakin, öfkeli, kaygılı, yorgun.","ornek":"Saat 05.30, resepsiyon: uçağına yetişmeye çalışan telaşlı misafirle uzun sohbete girilmez; hesap kısaca gösterilir, işlem hızla bitirilir. Aynı hesap akşam sakin bir misafire kalem kalem açıklanabilir.","sektor":"Ne söyleyeceğin kadar ne zaman ve nasıl söyleyeceğin de karşıdakinin o anki duygusuna bağlıdır. Ses tonu, yüz ifadesi ve duruş misafirin ruh hâlini çoğu zaman sözlerinden önce haber verir.","iliskili":["mg-1-036","mg-1-049","mg-1-055","mg-1-017"],"kontrol":null,"gorsel":"m1-duygu-yuzleri"},{"id":"mg-1-059","konu":"1.3","terim":"Misafir şikâyeti","ingilizce":"Guest complaint","tanim":"Misafirin hizmetten memnun kalmadığını bildirmesi.","ornek":"Sabah 09.15, resepsiyon: “Gece boyunca üst kattaki odadan gürültü geldi, hiç uyuyamadım” diyen misafir.","sektor":"Şikâyet eden misafir işletmeye sorunu düzeltme fırsatı verir; hiçbir şey söylemeden ayrılan misafirin memnuniyetsizliğini ise otel çoğu zaman öğrenemez. Şikâyet kişisel alınmaz: hedef sen değil, yaşanan sorundur.","iliskili":["mg-1-060","mg-1-061","mg-1-062","mg-1-057"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-060","konu":"1.3","terim":"Şikâyet yönetimi","ingilizce":"Complaint management","tanim":"Şikâyeti dinleyip çözüme kavuşturarak misafir memnuniyetini yeniden sağlama.","ornek":"Sabah 09.20: gürültüden yakınan misafiri dinleyen görevli özür diler, o gece için daha sessiz bir oda önerir ve durumu kayıt defterine yazar. Akşam vardiyasındaki görevli misafire yeni odasından memnun olup olmadığını sorar.","sektor":"Çözüm yetkini aşıyorsa söz verme; misafiri bekletmeden amirine ilet ve kendisine dönüş yapılacağını söyle. Şikâyet kayda geçer ki aynı sorun bir sonraki misafirin başına gelmesin.","iliskili":["mg-1-059","mg-1-061","mg-1-101","mg-1-106"],"kontrol":null},{"id":"mg-1-061","konu":"1.3","terim":"LAST yaklaşımı","ingilizce":"LAST approach","tanim":"Şikâyette dört adım: Listen (dinle), Apologise (özür dile), Solve (çöz), Thank (teşekkür et).","ornek":"Saat 20.10, restoran: çorbası soğuk gelen misafiri görevli sözünü kesmeden dinler, “Özür dilerim efendim” der, sıcak bir çorba getirir ve “Haber verdiğiniz için teşekkür ederim” diye ekler.","sektor":"Konaklama sektöründe şikâyet yönetimi eğitimlerinde yaygın kullanılan bir kısaltmadır. Sıra önemlidir: dinlemeden çözüm önermek ya da özür dilemek yerine savunmaya geçmek misafiri daha çok kızdırır.","iliskili":["mg-1-060","mg-1-039","mg-1-036","mg-1-059"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-062","konu":"1.3","terim":"Misafir memnuniyeti","ingilizce":"Guest satisfaction","tanim":"Misafirin aldığı hizmetin kendi beklentisini karşılaması ya da aşması.","ornek":"Gece 00.30: geç saatte varan aile odaya girdiğinde, rezervasyonda istedikleri bebek yatağının kurulmuş olduğunu görür. Anne “Unutmamışsınız” diye gülümser.","sektor":"Memnun misafir yeniden gelir ve oteli çevresine önerir; memnuniyet anketleri ve çevrim içi yorumlar bunu izlemenin yollarıdır. Memnuniyeti tek bir bölüm değil, misafirin karşılaştığı her çalışan birlikte oluşturur.","iliskili":["mg-1-057","mg-1-060","mg-1-098","mg-1-101"],"kontrol":null},{"id":"mg-1-097","konu":"1.3","terim":"Misafir ilişkileri","ingilizce":"Guest relations","tanim":"Misafirle olumlu ilişki kurmak, istek ve şikâyetleriyle ilgilenmek için yürütülen hizmet; otellerde ayrı bir birimdir.","ornek":"Sabah 10.00, lobi: misafir ilişkileri görevlisi bir gün önce şikâyette bulunan aileyi görünce yanlarına gider ve sorunun çözülüp çözülmediğini sorar.","sektor":"Büyük otellerde bu birim özel misafirleri karşılar, istekleri takip eder, şikâyetlerle ilgilenir. Küçük tesislerde aynı işi ön büro üstlenir.","iliskili":["mg-1-098","mg-1-060","mg-1-062","mg-1-059"],"kontrol":null,"kitapDisi":true},{"id":"mg-1-098","konu":"1.3","terim":"Misafir deneyimi","ingilizce":"Guest experience","tanim":"Misafirin rezervasyondan ayrılışına kadar işletmeyle yaşadığı her şeyin bütünü.","ornek":"Bir aile tatilini anlatırken yalnız odayı söylemez: telefondaki güler yüzlü cevabı, kapıdaki karşılamayı, kahvaltıyı ve çıkıştaki uğurlamayı birlikte hatırlar.","sektor":"Misafir bölümlere ayrı ayrı not vermez; bütünü hatırlar. Zincirin tek halkasındaki özensizlik, öteki bölümlerin emeğini de gölgeler.","iliskili":["mg-1-097","mg-1-100","mg-1-062","mg-1-057"],"kontrol":null,"kitapDisi":true},{"id":"mg-1-100","konu":"1.3","terim":"Gerçeğin anı","ingilizce":"Moment of truth","tanim":"Misafirin işletmeyle temas ettiği ve hizmet hakkında fikir edindiği her an (Jan Carlzon, 1987).","ornek":"Bir konaklamada onlarca küçük an vardır: telefonun açılması, kapıdaki selam, anahtarın verilmesi, koridorda karşılaşılan kat görevlisinin “Günaydın” demesi. Her biri bir gerçeğin anıdır.","sektor":"Misafir oteli yöneticisinden değil, karşılaştığı çalışandan tanır. O kısa anda otel sensin: stajyerin gülümsemesi de otelin hanesine yazılır.","iliskili":["mg-1-098","mg-1-099","mg-1-062"],"kontrol":null,"kitapDisi":true,"gorsel":"h5a-check-in-tezgahi"},{"id":"mg-1-118","konu":"1.3","terim":"Mantıksal çelişki","ingilizce":"Logical inconsistency","tanim":"Bir kişinin sözleriyle davranışlarının ya da ileri sürdüğü düşüncelerin kendi içinde birbiriyle uyuşmamasıdır.","ornek":"Servis toplantısında “Ekibime saygı duyarım” diyen garson her konuşmada arkadaşlarının sözünü kesiyor; sözü ile davranışı çelişiyor.","sektor":"Çelişkiyi fark eden çalışan tartışmada kişiyi değil, görüşün tutarsızlığını gösterir. Örneğin “Bağırarak saygı kazanırız” düşüncesi saygı ile bağırmanın bir arada olamayacağı için kendi içinde çelişir.","iliskili":["mg-1-119","mg-1-115"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-119","konu":"1.3","terim":"Hatalı argümanı çürütme","ingilizce":"Refuting a flawed argument","tanim":"Mantıksız ya da kendi içinde çelişen bir görüşün neden yanlış olduğunu saygılı bir dille ve gerekçeleriyle göstermektir.","ornek":"Saat 19.10, servis arası: bir garson “Misafir bağırırsa biz de bağırırız, bizi ciddiye alır” der. Arkadaşı “Bağırmak öfkeyi büyütür; sakin kalıp çözüm sunarsak misafir güvenir” diye karşılık verir.","sektor":"Çürütmenin amacı karşıdakini küçültmek değil, yapıcı ve ikna edici bir çözümü öne koymaktır. Ben dili ve nezaket bu sırada da korunur.","iliskili":["mg-1-118","mg-1-044","mg-1-130"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-1-129","konu":"1.3","terim":"Savunmacı tutum","ingilizce":"Defensiveness","tanim":"Suçlandığını düşünen kişinin kendini korumak için karşısındakini dinlemeden itiraz etmesi ya da suçu başkasına atmasıdır.","ornek":"Şef “Yedi numaralı masa neden geç servis edildi?” diye sorunca garson “Mutfak geç yolladı, benim suçum değil!” diye çıkışır.","sektor":"Sen dili savunmayı tetikler; empati ve ben dili savunmacı tutumu azaltır (ders kitabına göre). Savunmaya geçen kişi çözüm aramayı bırakır.","iliskili":["mg-1-029","mg-1-028","mg-1-036","mg-1-130"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-130","konu":"1.3","terim":"Yapıcı iletişim","ingilizce":"Constructive communication","tanim":"Karşıdakini suçlamadan, saygıyla ve çözüme odaklanarak yapılan iletişimdir.","ornek":"Saat 20.00, restoran: misafir “Siparişim çok uzun süredir gelmedi” der. Görevli “Sizi beklettiğimiz için üzgünüm; mutfağı hemen arayıp yeni süreyi size söylüyorum” der.","sektor":"Yapıcı iletişimde aktif dinleme, ben dili, açıklık, empati ve atılgan iletişim birlikte kullanılır.","iliskili":["mg-1-039","mg-1-028","mg-1-036","mg-1-026"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-063","konu":"1.4","terim":"Stres","ingilizce":"Stress","tanim":"Kişinin baskı, tehdit ya da aşırı yük karşısında yaşadığı bedensel ve zihinsel gerginlik.","ornek":"Cumartesi saat 14.00, resepsiyon: bir grup giriş için bekliyor, telefon çalıyor, bir misafir de anahtar kartının çalışmadığını söylüyor. Stajyerin kalbi hızlanır, elleri terler: bu strestir.","sektor":"Yoğun sezon, uzun vardiya ve bekleyen misafir turizmde stresin sık görülen kaynaklarıdır. Stres altındaki çalışanın ses tonu sertleşir, sabrı azalır, hata yapma olasılığı artar; bunu ilk fark eden de misafirdir.","iliskili":["mg-1-064","mg-1-065","mg-1-017","mg-1-049"],"kontrol":null,"gorsel":"m1-stres-topu"},{"id":"mg-1-064","konu":"1.4","terim":"Stres yönetimi","ingilizce":"Stress management","tanim":"Stresin kaynağını fark edip onu kontrol altına alma yöntemleri.","ornek":"Akşam 19.30, restoran dolu. Stajyer Elif bir an durup kendine sorar: “Beni geren ne? Üç masa aynı anda sipariş bekliyor.” Kaynağı bulunca şefine haber verir ve masaları sırayla alır.","sektor":"Programın anahtar kavramlarındandır. Stresi yok edemezsin, ama yönetebilirsin: kendisini neyin gerdiğini bilen çalışan misafirin karşısında sakin kalır ve dinlemeyi sürdürür.","iliskili":["mg-1-063","mg-1-065","mg-1-066","mg-1-070"],"kontrol":null},{"id":"mg-1-065","konu":"1.4","terim":"Başa çıkma yöntemi","ingilizce":"Coping strategy","tanim":"Stresi azaltmak için kullanılan yol: derin nefes, öncelik sırası, mola, yardım istemek.","ornek":"Saat 11.30, çıkış kuyruğu uzamış. Stajyer Mert iki kez derin ve yavaş nefes alır, bekleyen işleri sıraya koyar, yetişemeyeceği iş için vardiya amirinden yardım ister.","sektor":"Yöntemini önceden bilen çalışan yoğun anda donup kalmaz. Yardım istemek zayıflık değil, misafiri bekletmemenin profesyonel yoludur. Yeterli uyku, düzenli beslenme ve kısa mola da seni vardiyaya hazırlar.","iliskili":["mg-1-063","mg-1-064","mg-1-066","mg-1-067"],"kontrol":null},{"id":"mg-1-066","konu":"1.4","terim":"Zaman yönetimi","ingilizce":"Time management","tanim":"İşleri önceliğe göre sıralayıp zamanı planlı kullanmak.","ornek":"Sabah 08.00, kat ofisi: stajyer günün oda listesine bakar. Önce bugün yeni misafir bekleyen odalar, sonra ötekiler. Sıra belliyse gün koşturmacaya dönmez.","sektor":"Otelde işlerin saati vardır: giriş saati, kahvaltı saati, transfer saati. Önce hangi işin misafiri beklettiğine bakılır; önceliği doğru sıralayan çalışan hem daha az gerilir hem verdiği sözü zamanında tutar.","iliskili":["mg-1-064","mg-1-065","mg-1-079"],"kontrol":null},{"id":"mg-1-067","konu":"1.4","terim":"Öfke yönetimi","ingilizce":"Anger management","tanim":"Öfkeyi fark edip kimseye zarar vermeden, kontrollü biçimde ifade etme.","ornek":"Saat 13.00, servis geçidi: Can’ın hazırladığı tepsiyi bir arkadaşı haber vermeden alıp götürmüş. Can sesini yükseltmez; servis bitince “Tepsim haber verilmeden alınınca işim aksadı” der.","sektor":"Öfke doğal bir duygudur; sorun, onu misafirin ya da ekibin önünde patlatmaktır. Öfkesini fark edip sakinleşince konuşan çalışana güvenilir; bağıran çalışan hem misafirin hem ekibin güvenini kaybeder.","iliskili":["mg-1-065","mg-1-070","mg-1-028","mg-1-083"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-068","konu":"1.4","terim":"Tükenmişlik","ingilizce":"Burnout","tanim":"Uzun süreli iş stresi sonucu ortaya çıkan bedensel ve duygusal yorgunluk, isteksizlik.","ornek":"Sezon sonuna doğru, haftalardır dinlenemeyen bir çalışan sabah işe gitmek istemez; eskiden severek yaptığı karşılamayı artık gülümsemeden yapar.","sektor":"Turizmde yoğun sezon uzun sürer; bu yüzden izin günü ve mola lüks değil, işin parçasıdır. Stajda ya da okulda kendini uzun süre yorgun ve isteksiz hissedersen bunu içinde tutma: güvendiğin bir yetişkine ya da rehber öğretmenine anlat.","iliskili":["mg-1-063","mg-1-064","mg-1-065"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-069","konu":"1.4","terim":"Öz değerlendirme","ingilizce":"Self-assessment","tanim":"Kişinin kendi davranışlarını, güçlü ve gelişmesi gereken yönlerini incelemesi.","ornek":"Staj gününün sonunda, eve dönüş yolunda Zeynep defterine yazar: “Bugün misafiri sözünü kesmeden dinledim. Telefonda çok hızlı konuştum; yarın yavaşlayacağım.”","sektor":"İyi profesyonel, amiri söylemeden kendi eksiğini görür. Kendine sorulacak sorular bellidir: Baskın iletişim tarzım hangisi? Stresim hangi durumda yükseliyor? Stresliyken iletişimim nasıl değişiyor?","iliskili":["mg-1-070","mg-1-072","mg-1-074","mg-1-022"],"kontrol":null},{"id":"mg-1-070","konu":"1.4","terim":"Öz farkındalık","ingilizce":"Self-awareness","tanim":"Kişinin kendi duygularını, düşüncelerini ve tepkilerini fark etmesi.","ornek":"Öğle arası, personel yemekhanesi: Ali kendi kendine “Sabahki misafire kısa cevap verdim, çünkü uykusuzdum ve gerilmiştim” der. Tepkisinin nedenini fark etmiştir.","sektor":"Fark etmediğin duyguyu yönetemezsin. “Şu an gerginim” diyebilen çalışan o gerginliği misafire yansıtmadan önce durabilir.","iliskili":["mg-1-069","mg-1-071","mg-1-067","mg-1-058"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-071","konu":"1.4","terim":"Duygusal zekâ","ingilizce":"Emotional intelligence","tanim":"Kendi duygularını ve başkalarının duygularını tanıyıp yönetebilme becerisi.","ornek":"Saat 17.00, havuz başı: yoğun bir günün sonunda yorulan görevli terliğini bulamayan küçük bir çocuğun ağlamak üzere olduğunu fark eder. Kendi yorgunluğunu belli etmez, çocuğun boyuna eğilir ve “Merak etme, birlikte buluruz” der.","sektor":"Misafir çoğu zaman ne hissettiğini söylemez; yüzünden ve sesinden okunur. Hem kendi duygusunu hem karşısındakininkini tanıyan çalışan doğru sözü doğru anda söyler.","iliskili":["mg-1-070","mg-1-036","mg-1-058","mg-1-067"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-072","konu":"1.4","terim":"Kişisel değer","ingilizce":"Personal value","tanim":"Kişinin önemli ve doğru kabul ettiği, davranışlarına yön veren ilke (dürüstlük, saygı vb.).","ornek":"Akşam 21.00, lobi: stajyer koltukta unutulmuş bir cüzdan bulur. Onu kimse görmemiştir; yine de cüzdanı hemen amirine teslim eder, çünkü dürüstlük onun için tartışılmaz bir değerdir.","sektor":"Misafir eşyasını, odasını ve bilgisini sana emanet eder. Kimse bakmazken de aynı davranan çalışanı yönlendiren şey denetim değil, kendi değerleridir.","iliskili":["mg-1-069","mg-1-070","mg-1-037"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-073","konu":"1.4","terim":"Hedef","ingilizce":"Goal","tanim":"Belli bir sürede ulaşılmak istenen sonuç.","ornek":"Eylül, okulun ilk haftası: Deniz karar verir: “Bu yılın sonunda staj görüşmesinde kendimi İngilizce tanıtabilmek istiyorum.”","sektor":"Hedef gündelik koşturmaya yön verir: hangi beceriyi geliştirmek istediğini bilen stajyer vardiyadaki her işi bir alıştırmaya çevirir.","iliskili":["mg-1-074","mg-1-069","mg-1-030"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-1-074","konu":"1.4","terim":"SMART hedef","ingilizce":"SMART goal","tanim":"Spesifik, ölçülebilir, ulaşılabilir, gerçekçi ve zamana bağlı olan hedef.","ornek":"“İngilizcemi geliştireceğim” bir dilektir. “Dönem sonuna kadar her hafta resepsiyonda kullanılan 10 İngilizce kalıp cümle öğrenip arkadaşımla canlandıracağım” ise SMART bir hedeftir.","sektor":"Programın anahtar kavramlarındandır. Adı, beş ölçütün İngilizce baş harflerinden gelir: Specific, Measurable, Achievable, Realistic, Time-bound. Ders kitaplarında dördüncü harf Relevant (ilgili) diye de açılır; ikisi de hedefin işe ve kişiye uygun olmasını anlatır. Öz değerlendirmede gördüğün eksiği gidermenin yolu böyle bir hedef yazmaktır.","iliskili":["mg-1-073","mg-1-075","mg-1-076","mg-1-077","mg-1-078","mg-1-079"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-1-075","konu":"1.4","terim":"Spesifik (belirli)","ingilizce":"Specific","tanim":"Hedefte ne yapılacağının açıkça belli olması.","ornek":"“Daha iyi bir stajyer olacağım” belirsizdir. “Telefonu açarken otelin adını ve kendi adımı söyleyeceğim” belirlidir.","sektor":"Otelde görev de böyle verilir: “Odalara bak” değil, “3. kattaki çıkış odalarını kontrol et”. Ne yapılacağı açık olan iş yarım kalmaz.","iliskili":["mg-1-074","mg-1-076","mg-1-035"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-076","konu":"1.4","terim":"Ölçülebilir","ingilizce":"Measurable","tanim":"İlerlemenin sayıyla görülebilmesi.","ornek":"“Çok cümle öğreneceğim” yerine “Haftada 10 kalıp cümle öğreneceğim” diyen öğrenci cuma günü sayar: 7 tamam, 3 kaldı.","sektor":"Sayı yoksa ilerleyip ilerlemediğini bilemezsin. İşletmeler de hizmeti sayıyla izler: kaç şikâyet geldi, kaçı çözüldü.","iliskili":["mg-1-074","mg-1-075","mg-1-077"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-077","konu":"1.4","terim":"Ulaşılabilir","ingilizce":"Achievable","tanim":"Hedefin kişinin bilgi, beceri ve imkânlarıyla başarılabilir olması.","ornek":"9. sınıf öğrencisi için “Bir ayda akıcı Almanca konuşacağım” ulaşılabilir değildir; “Bir ayda Almanca selamlaşma ve karşılama cümlelerini öğreneceğim” ulaşılabilirdir.","sektor":"Gücünü aşan hedef hevesi kırar, çok kolay hedef de geliştirmez. İyi hedef seni biraz zorlar, ama bilgin, becerin ve imkânlarınla başarılabilir.","iliskili":["mg-1-074","mg-1-076","mg-1-078"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-078","konu":"1.4","terim":"Gerçekçi","ingilizce":"Realistic","tanim":"Hedefin kişinin içinde bulunduğu koşullara ve zamana uygun olması.","ornek":"Resepsiyon stajyeri Deniz hedefini “Dönem sonuna kadar her hafta resepsiyonda kullanılan 10 İngilizce karşılama cümlesini öğreneceğim” diye yazar. Hedef, staj yaptığı işe ve gelişmek istediği yöne doğrudan katkı sağladığı için gerçekçi-ilgilidir; “Haftada üç gün sinemaya gideceğim” ise mesleki gelişimine katkısı olmadığı için bu ölçütü karşılamaz.","sektor":"Kitap bu ölçütü “Gerçekçi-İlgili” diye adlandırır: hedef mesleki gelişime ve kişisel değerlere katkı sağlamalıdır. Otelde de önce işe yarayan beceriler öğrenilir: karşılama cümleleri, telefonda kendini tanıtma, misafire hitap. Hedefin koşullara uygunluğu ise kitapta “Ulaşılabilir” ölçütünün içinde anlatılır.","iliskili":["mg-1-074","mg-1-077","mg-1-079"],"kontrol":null,"cizim":"belge-form"},{"id":"mg-1-079","konu":"1.4","terim":"Zamana bağlı","ingilizce":"Time-bound","tanim":"Hedefin bir bitiş tarihinin olması.","ornek":"“Bir gün sunum yapmayı öğreneceğim” ucu açık bir sözdür. “Dönem sonuna kadar sınıfta beş dakikalık bir otel tanıtımı sunacağım” bir tarihe bağlıdır.","sektor":"Turizmde her işin bir son saati vardır: oda giriş saatine, tur kalkış saatine yetişmelidir. Bitiş tarihi olmayan hedef ise hep yarına kalır.","iliskili":["mg-1-074","mg-1-078","mg-1-066"],"kontrol":null},{"id":"mg-1-113","konu":"1.4","terim":"Mesleki ahlak","ingilizce":"Professional ethics","tanim":"Meslek yaşamında nezaket, dürüstlük ve adalet gibi değerlere dayanan, görevin doğru ve güvenilir yapılmasını sağlayan davranış ilkelerinin bütünüdür.","ornek":"Akşam 21.30, kat ofisi: stajyer yanlışlıkla başka odanın minibar ücretini misafirin hesabına yazdığını fark eder; kimse bakmasa da şefe söyler ve hesabı düzeltir.","sektor":"Misafir odasını, eşyasını ve bilgisini çalışana emanet eder. Dürüstlük ve adalet turizmde güvenin temelidir; zedelenen güveni geri kazanmak en zor iştir.","iliskili":["mg-1-115","mg-1-072","mg-1-037"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-1-114","konu":"1.4","terim":"Sosyal rol","ingilizce":"Social role","tanim":"Kişinin iş yaşamında bulunduğu konuma göre üstlendiği görev ve davranış beklentisidir (stajyer, usta, ekip lideri gibi).","ornek":"Eylülde stajyer olan Ece sezon sonunda aynı otelde yeni gelen stajyere işleri öğreten kişi olur; rolü değişmiştir, ama misafire ve ekibe nezaketi aynı kalır.","sektor":"Turizmde roller hızlı değişir: bugünün stajyeri sezon sonunda ekip içinde yeni sorumluluk alabilir. Rol değişse de kişisel değerler iletişimin sağlam temeli olmaya devam eder (ders kitabına göre).","iliskili":["mg-1-072","mg-1-113"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-115","konu":"1.4","terim":"Tutarlılık (söz ve davranış uyumu)","ingilizce":"Consistency","tanim":"Kişinin söyledikleriyle yaptıklarının birbiriyle uyumlu olmasıdır.","ornek":"Stajyer Mert “Yarın vardiyadan on dakika önce orada olacağım” der ve sabah 07.50’de üniformasıyla hazır bekler.","sektor":"Sözünü tutan çalışan ekipte ve misafirde güven kazanır; söyledikleriyle yaptıkları farklı olan kişinin güveni azalır.","iliskili":["mg-1-113","mg-1-118"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-1-116","konu":"1.4","terim":"Duyguları tanıma ve duraksama","ingilizce":"Pausing to recognise emotions","tanim":"Zorlayıcı bir anda tepki vermeden önce kısa bir süre durup o anki duyguyu fark etme tekniğidir.","ornek":"Saat 18.15, resepsiyon: yanlış faturaya kızan misafirin sesi yükselince stajyer kısa bir an durur, “Şu an gerildim” diye düşünür ve sonra sakin bir sesle cevap verir.","sektor":"Duraksamak yavaşlamak değil, söyleyeceğine karar vermektir; öfkeyle söylenen söz geri alınamaz. Bu kısa mola olası yanlış anlaşılmaların da önüne geçer (ders kitabına göre).","iliskili":["mg-1-067","mg-1-071","mg-1-117","mg-1-064"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-1-117","konu":"1.4","terim":"Nefes egzersizi","ingilizce":"Breathing exercise","tanim":"Stres anında derin ve yavaş nefes alarak bedeni ve zihni sakinleştirme yoludur.","ornek":"Saat 14.30, çıkış kuyruğu: stajyer sesinin titrediğini fark edip bankonun arkasında derin ve yavaş nefes alır, sonra misafire dönerek konuşur.","sektor":"Birkaç saniye sürer, araç istemez ve misafirin önünde bile fark edilmeden yapılabilir.","iliskili":["mg-1-064","mg-1-065","mg-1-116"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-1-127","konu":"1.4","terim":"Bireysel yol haritası","ingilizce":"Personal development roadmap","tanim":"Kişinin iletişim tarzını ve stres tepkilerini inceleyip güçlü ve gelişmesi gereken yönleri için hazırladığı gelişim planıdır.","ornek":"Zeynep dönem başında “Baskın tarzım pasif; stresli anda susuyorum” yazar ve SMART bir hedef koyar: “Dönem sonuna kadar her hafta bir toplantıda görüş bildireceğim.”","sektor":"Yol haritası öz değerlendirme ile başlar, SMART hedefle ilerler ve belli aralıklarla kontrol edilir; kontrol edilmeyen plan ertelenir.","iliskili":["mg-1-069","mg-1-070","mg-1-074","mg-1-022"],"kontrol":null,"cizim":"harita-rota"},{"id":"mg-1-050","konu":"1.5","terim":"Algı","ingilizce":"Perception","tanim":"Kişinin gördüğünü ve duyduğunu kendi deneyim ve beklentilerine göre anlamlandırması.","ornek":"Sabah 09.00, resepsiyon: görevli “Odanız birazdan hazır” der. Görevlinin aklındaki yarım saattir, misafirin anladığı beş dakika; on beşinci dakikada misafir bankoya geri gelir.","sektor":"Aynı cümleyi iki kişi farklı anlayabilir. Bu yüzden “birazdan”, “yakın”, “uygun fiyatlı” gibi yoruma açık sözler yerine saat, mesafe ve rakam söylenir.","iliskili":["mg-1-052","mg-1-051","mg-1-057","mg-1-035"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-080","konu":"1.5","terim":"Çatışma","ingilizce":"Conflict","tanim":"İki ya da daha fazla taraf arasında görüş, istek veya çıkarların uyuşmaması.","ornek":"Saat 13.30, otel: resepsiyon odaların bir an önce hazır olmasını ister, kat hizmetleri ise iyi bir temizlik için zamana ihtiyaç duyar. İkisi de haklıdır, ama istekleri uyuşmaz.","sektor":"İnsanların birlikte çalıştığı her yerde çatışma çıkar; kötü olan çatışmanın kendisi değil, kötü yönetilmesidir. Çözülmeyen anlaşmazlığın bedelini lobide bekleyen misafir öder.","iliskili":["mg-1-081","mg-1-091","mg-1-057"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-081","konu":"1.5","terim":"Çatışma yönetimi","ingilizce":"Conflict management","tanim":"Çatışmayı tanımlayıp tarafları dinleyerek yapıcı bir çözüme ulaştırma süreci.","ornek":"Vardiya amiri tartışan iki çalışanı misafirlerin göremeyeceği arka ofise alır. Önce birini, sonra ötekini dinler; ardından birlikte bir çözüm ararlar.","sektor":"Programın anahtar kavramlarındandır. Adımları bellidir: sorunu tanımla, tarafları dinle, seçenek üret, iki tarafın da kabul edeceği çözümü seç, uygula ve izle. Doğru zaman ve doğru yer de çözümün parçasıdır: çatışma misafirin önünde konuşulmaz.","iliskili":["mg-1-080","mg-1-087","mg-1-088","mg-1-039"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-091","konu":"1.5","terim":"Ekip çalışması","ingilizce":"Teamwork","tanim":"Ortak bir hedef için çalışanların görev paylaşarak birlikte çalışması.","ornek":"Pazar sabahı 09.00, kahvaltı salonu: biri misafiri karşılar, biri masaları toplar, biri büfeyi tamamlar. Kimse “O benim işim değil” demez; salon dolu olsa da servis akar.","sektor":"Misafir bölümleri görmez, tek bir otel görür. Ön büro, kat hizmetleri ve servis birbirine destek olmazsa en iyi çalışanın emeği bile misafire ulaşmaz.","iliskili":["mg-1-080","mg-1-086","mg-1-031","mg-1-105"],"kontrol":null,"cizim":"ekip"},{"id":"mg-1-082","konu":"1.5","terim":"Rekabet","ingilizce":"Competing","tanim":"Kendi isteğinde ısrar etmek; acil ve hızlı karar gereken durumlarda kullanılır.","ornek":"Gece 02.00, yangın alarmı çalıyor. Vardiya amiri tartışmaya yer bırakmaz: “Herkes şimdi acil çıkışa, asansör kullanılmayacak.” Burada ısrar etmek doğrudur.","sektor":"Güvenlik gibi hızlı karar gereken durumlarda işe yarar. Her anlaşmazlıkta kullanılırsa karşı taraf dinlenmediğini hisseder ve ilişki yıpranır.","iliskili":["mg-1-081","mg-1-083","mg-1-086","mg-1-033"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-083","konu":"1.5","terim":"Kaçınma","ingilizce":"Avoiding","tanim":"Çatışmayı ertelemek; konu önemsizse ya da öfke yatışana kadar ara vermek gerekiyorsa.","ornek":"Servis sonrası iki garson hangi masaya kimin bakacağını tartışmaya başlar; sesler yükselir. Biri “Şimdi ikimiz de gerginiz, molada konuşalım” der.","sektor":"Öfke yatışana kadar ara vermek akıllıcadır; önemsiz bir konuyu büyütmemek de öyle. Ama önemli bir sorun sürekli ertelenirse çözülmez, büyür.","iliskili":["mg-1-081","mg-1-082","mg-1-084","mg-1-067"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-084","konu":"1.5","terim":"Uyma","ingilizce":"Accommodating","tanim":"Karşı tarafın isteğini kabul etmek; ilişki konudan daha önemliyse.","ornek":"İki stajyer de cumartesi günü izin istiyor. Biri arkadaşının o gün ailesinde düğün olduğunu öğrenince “Cumartesiyi sen al, ben pazar günü kullanırım” der.","sektor":"Konu senin için küçük, ilişki büyükse geri adım atmak ekibi güçlendirir. Ama hep sen uyuyorsan kendi ihtiyacın görünmez olur; o zaman atılgan iletişim gerekir.","iliskili":["mg-1-081","mg-1-083","mg-1-085","mg-1-026"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-085","konu":"1.5","terim":"Uzlaşma","ingilizce":"Compromising","tanim":"İki tarafın da bir miktar geri adım atarak ortak noktada buluşması.","ornek":"İki kat görevlisi de sabah vardiyasında çalışmak istiyor. Amirleriyle konuşup sabah vardiyalarını haftalara bölüşürler: bir hafta biri, ertesi hafta öteki.","sektor":"İki taraf da istediğinin bir kısmından vazgeçer; çözüm çabuk bulunur, ama kimse tam istediğini almaz. Zaman dar olduğunda işi yürüten yol çoğu kez budur.","iliskili":["mg-1-081","mg-1-084","mg-1-086","mg-1-089"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-086","konu":"1.5","terim":"İş birliği","ingilizce":"Collaborating","tanim":"Herkesin ihtiyacını karşılayan ortak çözümü birlikte bulmak.","ornek":"Resepsiyon ile kat hizmetleri “Oda hazır mı?” tartışmasını bitirmek için birlikte oturur ve ortak bir yol bulur: hazır olan oda anında bildirilecek, erken gelen misafirin odası öne alınacak.","sektor":"En çok emek isteyen ama en kalıcı yoldur: kimse geri adım atmaz, sorunun kendisi çözülür. Kazan-kazan çözüm bu yaklaşımla bulunur.","iliskili":["mg-1-081","mg-1-085","mg-1-087","mg-1-091"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-087","konu":"1.5","terim":"Kazan-kazan stratejisi","ingilizce":"Win-win strategy","tanim":"İki tarafın da kazançlı çıktığı ve ikisinin de kabul ettiği çözümü arama yaklaşımı.","ornek":"Saat 10.00, resepsiyon: misafir odasına hemen çıkmak istiyor, oda ise 14.00’te hazır olacak. Görevli valizleri emanete alır, oda hazır olunca arayacağını söyler: misafir beklerken rahat eder, otel odayı hazırlamaya zaman bulur.","sektor":"Programın anahtar kavramlarındandır. Bir tarafın kaybettiği tartışmada misafir bir daha gelmez, ekip arkadaşı küser. İki tarafın da kabul ettiği çözüm, hem misafiri hem ekip arkadaşını yanında tutar.","iliskili":["mg-1-086","mg-1-081","mg-1-089","mg-1-026"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"mg-1-089","konu":"1.5","terim":"Müzakere","ingilizce":"Negotiation","tanim":"Tarafların ortak bir karara varmak için karşılıklı görüşmesi ve pazarlık etmesi.","ornek":"Bir acente görevlisi ile otelin satış sorumlusu 40 kişilik bir grup için masaya oturur: acente uygun fiyat ister, otel erken ödeme. Konuşarak ikisinin de kabul ettiği koşullarda anlaşırlar.","sektor":"Acente ile otel, otel ile tedarikçi arasındaki anlaşmalar müzakereyle kurulur. İyi müzakereci yalnız kendi isteğini değil, karşı tarafın neye ihtiyaç duyduğunu da bilir.","iliskili":["mg-1-087","mg-1-085","mg-1-090","mg-1-057"],"kontrol":null},{"id":"mg-1-090","konu":"1.5","terim":"Arabuluculuk","ingilizce":"Mediation","tanim":"Bir anlaşmazlıkta tarafsız üçüncü bir kişinin tarafların uzlaşmasına yardım etmesi.","ornek":"İki stajyer görev paylaşımı yüzünden birbiriyle konuşmuyor. Bölüm şefi ikisini de ayrı ayrı dinler, taraf tutmadan bir araya getirir ve çözümü onların bulmasına yardım eder.","sektor":"Taraflar birbirini dinleyemeyecek kadar gerginse tarafsız biri gerekir; otelde bu çoğu zaman vardiya amiri ya da bölüm şefidir. Arabulucu kararı kendisi vermez, tarafların anlaşmasını kolaylaştırır.","iliskili":["mg-1-089","mg-1-081","mg-1-039"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-1-088","konu":"1.5","terim":"Eylem planı","ingilizce":"Action plan","tanim":"Kimin, neyi, ne zaman yapacağını gösteren adım adım çözüm planı.","ornek":"“Oda hazır mı?” tartışması için yazılan plan: kat görevlisi hazır odayı hemen bildirecek, resepsiyonist bilgi gelmeden misafire saat söylemeyecek, şef bir hafta sonra sonucu kontrol edecek.","sektor":"“Bir daha olmasın” demek plan değildir. Kimin, neyi, ne zaman yapacağı yazılmazsa çatışma birkaç gün sonra aynı yerden yeniden çıkar; sonucu kontrol etmek planın son adımıdır.","iliskili":["mg-1-081","mg-1-087","mg-1-086"],"kontrol":null},{"id":"mg-1-101","konu":"1.5","terim":"Hizmet telafisi","ingilizce":"Service recovery","tanim":"Hizmette yaşanan bir aksaklığı hızla düzelterek misafirin memnuniyetini yeniden kazanma.","ornek":"Akşam 20.00, restoran: misafire yanlış yemek gelir. Garson özür diler, doğru yemeği mutfağa öncelikli olarak bildirir; yemek gelince şef garson masaya uğrar ve her şeyin yolunda olup olmadığını sorar.","sektor":"Hata her otelde olur; farkı hatadan sonra yapılan belirler. Sorunu hızla ve içtenlikle çözülen misafir çoğu zaman aksaklığı değil, gösterilen ilgiyi hatırlar.","iliskili":["mg-1-087","mg-1-059","mg-1-060","mg-1-062"],"kontrol":null,"kitapDisi":true},{"id":"mg-1-105","konu":"1.5","terim":"Vardiya devri","ingilizce":"Shift handover","tanim":"Vardiyası biten çalışanın bekleyen işleri ve önemli bilgileri sonraki vardiyaya aktarması.","ornek":"Saat 15.45, resepsiyon: sabah vardiyasındaki görevli akşam vardiyasına anlatır: “204 numaralı oda geç çıkış yapacak, 310’un taksisi 18.00’de gelecek, 112’ye ek yastık sözü verildi.”","sektor":"Otel 24 saat çalışır, ama çalışan değişir. Devirde aktarılmayan bilgi, misafire verilmiş sözün tutulmaması ve ekipte “Bana kimse söylemedi” tartışması demektir.","iliskili":["mg-1-106","mg-1-091","mg-1-095","mg-1-080"],"kontrol":null,"kitapDisi":true},{"id":"mg-1-106","konu":"1.5","terim":"Kayıt defteri","ingilizce":"Logbook","tanim":"Bölümde vardiyalar arasında bilgi aktarmak için tutulan defter ya da dijital kayıt.","ornek":"Gece vardiyasındaki görevli deftere yazar: “01.30: 215 numaralı oda üst kattan gürültü bildirdi, ilgili odaya rica edildi, sorun giderildi.” Sabah vardiyası bunu okur ve misafire gecesinin nasıl geçtiğini sorar.","sektor":"Söz uçar, yazı kalır: devirde söylenmesi unutulan bilgi defterde durur. Ön büroda “log book” adıyla da anılır; kimin, ne zaman, ne yaptığı orada yazdığı için ekip içi tartışmaları da önler.","iliskili":["mg-1-105","mg-1-011","mg-1-088"],"kontrol":null,"kitapDisi":true,"cizim":"resepsiyon"},{"id":"mg-1-120","konu":"1.5","terim":"Bastırma","ingilizce":"Forcing (suppression)","tanim":"Taraflardan birinin gücünü ya da yetkisini kullanarak kendi çözümünü karşı tarafa kabul ettirmesidir.","ornek":"Saat 11.00, kat ofisi: kat şefi iki görevlinin vardiya isteğini dinlemeden “Karar verildi, tartışma yok” der ve çizelgeyi asar.","sektor":"Kısa vadede sorun çözülmüş görünür; ama güveni zedeler, ilişkileri bozar ve kazanan-kaybeden duygusu bırakır (ders kitabına göre). Rekabet kartındaki yaklaşımla yakın anlamlıdır.","iliskili":["mg-1-082","mg-1-080","mg-1-081","mg-1-085"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-121","konu":"1.5","terim":"Çatışmanın nedenleri","ingilizce":"Causes of conflict","tanim":"İş ortamında anlaşmazlığa yol açan başlıca etkenler iletişim engelleri, amaç ve çıkar farklılıkları, rol ve görev belirsizlikleri ile kişisel özelliklerdir.","ornek":"Saat 13.30, otel: resepsiyon odaların hemen hazır olmasını ister, kat hizmetleri temizliğin zaman istediğini söyler; hangi saate kadar kimin sorumlu olduğu da yazılı değildir.","sektor":"Çözümden önce nedeni bulmak gerekir. Nedeni bilinmeyen çatışmada herkese aynı nasihat verilir ve sorun aynı yerden yeniden çıkar.","iliskili":["mg-1-080","mg-1-081","mg-1-122","mg-1-123"],"kontrol":null,"cizim":"konusma"},{"id":"mg-1-122","konu":"1.5","terim":"Amaç ve çıkar farklılığı","ingilizce":"Conflicting goals and interests","tanim":"Çalışanların hedeflerinin, önceliklerinin ya da beklentilerinin birbiriyle örtüşmemesidir.","ornek":"Satış bölümü doluluğu artırmak için çok rezervasyon almak ister; ön büro ise odalara yetişemeyeceği için sınırlı satış ister.","sektor":"Bölümlerin kendi hedefi vardır; ortak hedef misafir memnuniyeti olarak konulduğunda uzlaşmak kolaylaşır.","iliskili":["mg-1-121","mg-1-085","mg-1-087"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-1-123","konu":"1.5","terim":"Rol ve görev belirsizliği","ingilizce":"Role ambiguity","tanim":"İş yerinde kimin hangi işten sorumlu olduğunun açıkça belirlenmemesidir.","ornek":"Sabah 09.00, restoran: kirli tabakları kimin toplayacağı belli değildir; garson “Ben değil” der, komi “Ben değil” der, masalar bekler.","sektor":"Görev tanımı yazılı ve herkesçe bilinirse “O benim işim değil” tartışması azalır. Stajyer ilk günde sorumluluk alanını sormalıdır.","iliskili":["mg-1-121","mg-1-088","mg-1-091"],"kontrol":null,"cizim":"ekip"},{"id":"mg-1-124","konu":"1.5","terim":"Uygun zaman ve ortam seçimi","ingilizce":"Choosing the right time and place","tanim":"Bir sorunu, tarafların sakinleştiği ve iş akışının aksamadığı bir zamanda, sakin ve uygun bir yerde konuşma ilkesidir.","ornek":"Servis bittikten sonra saat 16.00’da, kat ofisinde iki görevli ve şef kapıyı kapatıp acele etmeden konuşur; misafir görmez, kimse işini bırakmaz.","sektor":"Çatışma ayaküstü, kalabalıkta ya da misafirin önünde konuşulmaz; ortam gergin olursa taraflar birbirini dinleyemez.","iliskili":["mg-1-081","mg-1-089","mg-1-090"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-1-125","konu":"1.5","terim":"Esneklik (esnek ve yenilikçi olma)","ingilizce":"Flexibility","tanim":"Çözüm ararken yalnız kendi görüşünde ısrar etmeyip farklı önerilere ve yeni fikirlere açık olmaktır.","ornek":"Sabah 10.00: resepsiyon ile kat hizmetleri “Oda hazır mı?” tartışmasını bitirmek için hazır odaları anında bildiren ortak bir form denemeyi kabul eder.","sektor":"Esnek çalışan iki tarafın da ihtiyacını karşılayan üçüncü bir yol arar; “Hep böyle yapıldı” demek çözümü kapatır.","iliskili":["mg-1-086","mg-1-087","mg-1-085"],"kontrol":null,"cizim":"fikir-inovasyon"}],"acikSorular":[{"id":"mg-1-y01","konu":"1.2","soru":"Bir proje ekibinin toplantısında üyelerden biri sürekli önyargılı yorumlar yapmakta, bir diğeri ise sözlerinin tersini beden diliyle göstermektedir. Bu iki durumu iletişim engeli olarak açıklayınız. Her engeli aşmak için bir çözüm öneriniz.","olcut":[{"metin":"Önyargılı yorumları bir iletişim engeli olarak açıklar (örn. psikolojik ya da algı kaynaklı engel).","puan":25},{"metin":"Sözlü ve sözsüz mesaj tutarsızlığını bir iletişim engeli olarak açıklar.","puan":25},{"metin":"Birinci engel için somut bir çözüm önerir.","puan":25},{"metin":"İkinci engel için somut bir çözüm önerir.","puan":25}],"ornek":"Önyargı, bilgi olmadan önceden edinilen yargıdır; karşıdakinin açıklamasını dinlemeyi zorlaştırır. Çözüm: yorumu kişiye değil somut bilgiye dayandırmak ve açıklayıcı soru sormak. Sözlü–sözsüz tutarsızlık, ekibin kime güveneceğini şaşırtır. Çözüm: sözlerin ve beden dilinin uyumlu olması için sorunu açıkça konuşmak ve geri bildirim istemek.","ipucu":"Her engelin adını koyun, sonra o engele özgü bir çözüm yazın."},{"id":"mg-1-y02","konu":"1.3","soru":"Bir grup çalışmasında raporunuzu hem yazılı hem sözlü olarak sunmanız istenmiştir. Yazılı ve sözlü iletişimin ayrı güçlü yanlarını açıklayınız. Sunumda dinleyiciyi dikkate almak için iki yöntem öneriniz.","olcut":[{"metin":"Yazılı iletişimin güçlü yanını açıklar.","puan":25},{"metin":"Sözlü iletişimin güçlü yanını açıklar.","puan":25},{"metin":"Birinci sunum yöntemini dinleyiciyi dikkate alarak açıklar.","puan":25},{"metin":"İkinci sunum yöntemini dinleyiciyi dikkate alarak açıklar.","puan":25}],"ornek":"Yazılı iletişim kalıcıdır ve düşünce düzenli biçimde sunulur. Sözlü iletişimde karşılıklı geri bildirim alınabilir ve ses tonu ile beden dili mesajı güçlendirir. Yöntem 1: dinleyicinin ilgisini çekmek için sunuma kısa bir soruyla başlamak. Yöntem 2: önemli noktaları kısa cümlelerle ve görsellerle tekrar etmek.","ipucu":"Güçlü yanı yazarken “neden güçlü” sorusunu da cevaplayın."}],"sorular":[{"id":"mg-1-s01","tur":"coktan-secmeli","soru":"Garson mutfağa “On iki numaralı masa” der; davlumbazın uğultusu yüzünden aşçı “iki numaralı masa” diye duyar. Yanlış masaya tabak gitmesinin nedeni iletişimin hangi öğesidir?","secenekler":["Gürültü","Kanal","Alıcı","Gönderici"],"dogru":0,"aciklama":"Mesajın doğru ulaşmasını engelleyen uğultu gürültüdür. Kanal (sözlü, yüz yüze) ve taraflar doğru çalışmıştır; bozulan şey mesajın duyulmasıdır."},{"id":"mg-1-s02","tur":"coktan-secmeli","soru":"Personel yemekhanesinde bir arkadaşın “Yarın büyük bir grup geliyormuş” dediğini duydun. Bunu misafire söylemeden önce ne yapmalısın?","secenekler":["Başka bir arkadaşa sorup ikisi aynı şeyi söylerse bilgiyi aktarmak","Misafire “Duyduğuma göre” diyerek önceden haber vermek","Amirime sorup bilginin doğru olup olmadığını teyit etmek","Ekip grubuna yazıp kimsenin itiraz etmemesini beklemek"],"dogru":2,"aciklama":"Biçimsel olmayan yoldan gelen bilgi hızlı yayılır, ama doğrulanmamış olabilir; doğru kaynak amirdir. İki arkadaşın aynı şeyi söylemesi de aynı söylentiyi tekrarlıyor olabilir."},{"id":"mg-1-s03","tur":"coktan-secmeli","soru":"Misafir ertesi sabahki transfer saatini yanlış anladı. “Ben söyledim, o anlamadı” demek neden profesyonelce değildir?","secenekler":["Sözlü mesajlar yazılı mesajlardan her zaman daha zayıftır","Yanlış anlaşılmalar yalnızca ortam gürültüsünden doğar","Alıcı mesajı kendisi doğrulamak zorunda değildir","Mesaj anlaşılana kadar iletişim tamamlanmış sayılmaz"],"dogru":3,"aciklama":"Mesajın anlaşılır olması önce göndericinin sorumluluğudur; bu yüzden anlaşıldığından emin olunur. Alıcının hiç sorumluluğu olmadığı da söylenemez, ama sorumluluğu başlatan taraf göndericidir."},{"id":"mg-1-s04","tur":"coktan-secmeli","soru":"Acente görevlisi telefonda “Yedi Mart, iki kişi” bilgisini aldı. “Mart” ile “mayıs” karışmasın diye en güvenli adım hangisidir?","secenekler":["Aynı soruyu bir kez daha, daha yüksek sesle sormak","Tarihi tekrar edip “Doğru mu efendim?” diye sormak","Müşteriye “Tamamen net duydum” deyip kaydı bitirmek","Bilgiyi kaydedip müşteriyi tekrar aramaktan kaçınmak"],"dogru":1,"aciklama":"Teyit, anlaşılan bilgiyi karşı tarafa tekrar sorarak doğrulamaktır; hata kayıttan önce yakalanır. Sesi yükseltmek ya da “Net duydum” demek anlaşıldığını kanıtlamaz."},{"id":"mg-1-s05","tur":"coktan-secmeli","soru":"Rezervasyon onayları ve vardiya notları neden yazıya geçirilir?","secenekler":["Yazı, konuşmaya göre her zaman daha hızlı iletilir","Kayıt kalıcıdır; sonradan çıkan anlaşmazlıkta dayanak olur","Misafirler yazılı mesajı sözlü mesajdan daha çok sever","Sözlü bilgi, otelde hiçbir koşulda geçerli sayılmaz"],"dogru":1,"aciklama":"Yazılı iletişimde “Kim, ne zaman, ne dedi?” sorusunun cevabı kayıttadır. Hız ise yazının değil, sözlü iletişimin avantajıdır."},{"id":"mg-1-s06","tur":"coktan-secmeli","soru":"Bellboy bagaj arabasını iterken asansörü açık avucuyla gösteriyor ve gülümsüyor. Açık avuç hareketi ve gülümseme sırasıyla hangi sözsüz iletişim öğeleridir?","secenekler":["Jest – mimik","Mimik – jest","Jest – diksiyon","Duruş – hitap"],"dogru":0,"aciklama":"El hareketiyle verilen mesaj jest, yüz ifadesiyle verilen mesaj mimiktir. Diksiyon sözcüklerin telaffuzu, hitap ise seslenme biçimidir; bunlar sözsüz değil sözlü iletişime yakındır."},{"id":"mg-1-s07","tur":"coktan-secmeli","soru":"Görevli “Memnuniyetle yardımcı olurum” diyor, ama gözü telefonunda. Söz ile beden dili çeliştiğinde misafir çoğunlukla neye inanır?","secenekler":["Söylenen sözcüklere","Hitap biçimine","Ses yüksekliğine","Beden diline"],"dogru":3,"aciklama":"Söz ile beden dili çeliştiğinde insanlar çoğunlukla beden diline güvenir; bu yüzden misafire söylenen söz ile yüzün anlattığı aynı olmalıdır. Sözcükler tek başına yeterli olsaydı çelişki fark edilmezdi."},{"id":"mg-1-s08","tur":"coktan-secmeli","soru":"Görevli amirinin verdiği ek işe “Tamam” der; ama gün boyu ona kısa ve soğuk cevaplar verir, arkadaşlarına da söylenir. Bu davranış hangi iletişim tarzıdır?","secenekler":["Pasif","Agresif","Pasif-agresif","Atılgan"],"dogru":2,"aciklama":"Öfkenin açıkça değil, dolaylı yoldan gösterilmesi pasif-agresif tarzdır. Pasif tarzda kişi hiç tepki göstermez; agresifte ise öfke açıkça, suçlayarak patlatılır."},{"id":"mg-1-s09","tur":"coktan-secmeli","soru":"Vardiya devrini geç alan görevli arkadaşına ben diliyle seslenecek. Hangi cümle ben dilidir?","secenekler":["Bilgiyi geç verdiğin için misafire yanlış cevap verdim.","Hep geç bilgi veriyorsun, bu işi hiç ciddiye almıyorsun.","Senin ihmalin yüzünden misafir bana şikâyet etti.","Bilgi geç gelince misafire yanlış cevap vermekten çekiniyorum."],"dogru":3,"aciklama":"Ben dili, duyguyu ve isteği suçlamadan kendi adına anlatır. “Verdiğin için” diye başlayan ilk çeldirici de suçlama içerir, yani sen dilidir."},{"id":"mg-1-s10","tur":"coktan-secmeli","soru":"Anlamadığı işi sormayan, üstüne fazla iş verilince susan bir stajyerin bu davranışı zamanla neye yol açar?","secenekler":["Ekipte kimse ona hata bildirmek istemez","Sorun çözülmeden kalır ve stajyer yıpranır","Öfkesini iğneleyici sözlerle dolaylı gösterir","İki taraf da saygı görür, sorun açıkça konuşulur"],"dogru":1,"aciklama":"İhtiyacını söylemeyen pasif kişinin sorunu yerinde durur, kendisi de yıprandığı için zamanla işi daha da zorlaşır. İkinci şık agresif tarzın, üçüncüsü pasif-agresif tarzın sonucudur."},{"id":"mg-1-s11","tur":"dogru-yanlis","soru":"Anlamadığı talimatı saygıyla sorup duyduğunu tekrar eden stajyer atılgan iletişim kurmuş olur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Atılgan iletişim, kendi ihtiyacını saygıyla ve açıkça söylemektir. Sormak sorunu çözer; tekrar etmek ise mesajın doğru alındığını gösterir."},{"id":"mg-1-s12","tur":"dogru-yanlis","soru":"Misafire “abla”, “abi” gibi günlük sözlerle seslenmek samimiyet kattığı için otelde tercih edilir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Hitap saygının ilk işaretidir: misafire “efendim”, “Hanım”, “Bey” gibi kalıplarla seslenilir. Günlük sözler samimi görünse de resmî bir hizmet ortamına uymaz."},{"id":"mg-1-s13","tur":"senaryo","durum":"Saat 10.00, kat ofisindesin. Şef iki odayı sayıp birinin öncelikli olduğunu söyledi, ama hangisi olduğunu duymadın; şef telsizle konuşarak koridora yürüyor.","soru":"Ne yaparsın?","secenekler":["Şefe yetişip öncelikli odayı sorar, duyduğumu tekrar ederim.","Duyduğum odalardan birini seçip önce oradan başlarım.","Şef telsizden tekrar söyler diye işe başlamadan beklerim.","Kat ofisindeki diğer stajyere şefin hep hızlı konuştuğunu söylerim."],"dogru":0,"aciklama":"Anlamadığını saygıyla sormak atılgan davranıştır; duyduğunu tekrar etmek de teyittir. Tahminle başlamak ve beklemek pasifliktir, arkadan söylenmek ise pasif-agresif tarzdır; üçünde de sorun çözülmez."},{"id":"mg-1-s14","tur":"senaryo","durum":"Saat 11.00, çıkış işlemi yapıyorsun. “Konaklamanız nasıldı?” sorusuna misafir “İyiydi” diyor, ama kaşları çatık ve bakışları kaçıyor. Kuyrukta başka misafirler de bekliyor.","soru":"Ne yaparsın?","secenekler":["“İyiydi” dediği için teşekkür edip kartı uzatırım.","İşlemi hızlandırır, kuyruk bitince konuyu kendim açarım.","Nazikçe “Eksik bir şey oldu mu efendim?” diye sorarım.","Şikâyeti varsa kendisinin söylemesi gerektiğini nazikçe ima ederim."],"dogru":2,"aciklama":"Misafirin yüzü, sözünden önce memnuniyetsizliğini ele verir; mimiği okuyan görevli şikâyeti söze dökülmeden fark eder. Sözüne bakıp geçmek ya da işlemi hızlandırmak, misafirden sorunu duyma fırsatını kaçırmak olur."},{"id":"mg-1-s15","tur":"senaryo","durum":"Saat 22.00, restoran. Siparişi yarım saattir gelmeyen bir misafir sana yüksek sesle çıkışıyor; yan masalar dönüp bakıyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Sesimi onunki kadar yükseltip mutfağın yoğun olduğunu anlatırım.","Cevap vermeden mutfağa gider, bir süre geri dönmem ve beklerim.","Özür diler, siparişi öğrenip sonucu kendisine söylerim.","Yüzüne bakmadan “Birazdan gelir” deyip başka masaya geçerim."],"dogru":2,"aciklama":"Sakin ses ve hemen başlayan çözüm atılgan tarzın göstergesidir; misafir hem saygı hem ilgi görür. Sesi yükseltmek agresif, kaçmak ve geçiştirmek pasif tarzdır; ikisi de sorunu çözmez."},{"id":"mg-1-s16","tur":"senaryo","durum":"Vardiya arkadaşın üç gündür molasından geç dönüyor; sen de bankoda tek kalıp misafirleri bekletiyorsun. Saat 15.00, arkadaşın yine on beş dakika geç geldi.","soru":"Ne yaparsın?","secenekler":["Ona “Sen hep böylesin” deyip bir daha olursa amire şikâyet ederim.","Hiçbir şey söylemem, ama bir daha ona hiçbir konuda yardım etmem.","Önce susar, sonra herkesin duyacağı yerde “Yine mi geç kaldın?” derim.","Arkadaşıma “Mola uzayınca bankoda tek kalıyorum, zorlanıyorum” derim."],"dogru":3,"aciklama":"Ben dili duyguyu, sonucu ve isteği suçlamadan anlatır; arkadaşın savunmaya geçmeden sorunu duyar. “Sen hep…” demek sen dili, susup yardımı kesmek pasif-agresif, herkesin önünde söylemek yeni bir çatışmadır."},{"id":"mg-1-s21","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi aktif dinlemede yapılan bir hatadır?","secenekler":["Anlaşılanı kendi cümleleriyle yeniden söylemek","Konuşan bitirmeden araya girip çözümü söylemek","Gerektiğinde ayrıntı için açık uçlu soru sormak","Konuşma sonunda varılan çözümü özetlemek"],"dogru":1,"aciklama":"Aktif dinlemede tüm dikkat konuşandadır ve söz kesilmez; araya girmek eksik bilgiyle çözüm üretmeye yol açar. Yeniden ifade, soru ve özetleme ise aktif dinlemenin adımlarıdır."},{"id":"mg-1-s22","tur":"coktan-secmeli","soru":"Acentede bir müşterinin ihtiyacını konuşmanın başında en iyi anlamayı sağlayan soru hangisidir?","secenekler":["Nasıl bir tatil düşünüyorsunuz?","Denize yakın bir otel mi istiyorsunuz?","Bütçeniz yirmi bin lira mı?","Çocukla mı geleceksiniz?"],"dogru":0,"aciklama":"Açık uçlu soru evet/hayırla cevaplanamaz; müşteri istediklerini kendi cümleleriyle anlatır. Diğer sorular kapalı uçludur: bilgiyi kesinleştirmeye yarar, konuşma başında ise sorguya dönüşür."},{"id":"mg-1-s23","tur":"coktan-secmeli","soru":"Şef, oda numarasını yüksek sesle söyleyen bir stajyere geri bildirim veriyor. Hangisi yapıcı geri bildirimdir?","secenekler":["Bugün iki kez oda numarasını yüksek sesle söyledin; yarın kartta gösterelim.","Diğer stajyerler bunu bir haftada öğrendi, sen hâlâ yapamıyorsun.","Bu hatayı tekrarlarsan bunu değerlendirmene yansıtırım, haberin olsun.","Biraz daha dikkatli olursan çok daha başarılı bir stajyer olursun, bence."],"dogru":0,"aciklama":"Yapıcı geri bildirim davranışı hedef alır, somuttur ve bir sonraki adımı gösterir. Diğerleri başkasıyla kıyaslar, tehdit eder ya da “dikkat et” gibi neyin değişeceğini söylemeyen genel bir öğüt verir."},{"id":"mg-1-s24","tur":"coktan-secmeli","soru":"Uçağı rötar yapmış öfkeli bir misafire görevli kahvaltı saatlerini ve havuz kurallarını sıralıyor; misafir hiçbirini duymuyor. Burada baskın iletişim engeli hangisidir?","secenekler":["Fiziksel engel","Dil ve anlam engeli","Kültürel engel","Psikolojik engel"],"dogru":3,"aciklama":"Öfke ve yorgunluk gibi duygular mesajın alınmasını bozar; misafirin o an ihtiyacı anlaşılmak ve oda anahtarıdır. Ortamda gürültü ya da ortak dil sorunu yoktur, bu yüzden diğer engeller geçerli değildir."},{"id":"mg-1-s25","tur":"coktan-secmeli","soru":"Görevli “Nasılsa kahvaltı saatini biliyordur” diye düşünüp söylemiyor; misafir ertesi sabah kapanmış salonla karşılaşıyor. Bu davranışın adı nedir?","secenekler":["Ön yargı","Kalıp yargı","Varsayım","Algı farkı"],"dogru":2,"aciklama":"Doğruluğu kontrol edilmeden doğru kabul edilen düşünce varsayımdır; çözümü sormaktır. Ortada misafire ya da bir gruba yönelik olumlu ya da olumsuz bir peşin hüküm yoktur, bu yüzden ön yargı ve kalıp yargı olmaz."},{"id":"mg-1-s26","tur":"coktan-secmeli","soru":"Görevli “Odanız birazdan hazır” diyor; misafir beş dakika, görevli yarım saat kastetmiş. Algı farkını önlemek için hangisi söylenmelidir?","secenekler":["“Odanız çok yakında hazır olacak efendim, merak etmeyin.”","“Odanız 11.30’da hazır, hazır olunca arayacağım.”","“Biraz sabredin lütfen, birazdan size haber veririm.”","“Yakın bir zamanda hazır olur efendim.”"],"dogru":1,"aciklama":"“Birazdan”, “yakında” gibi sözler kişiden kişiye farklı anlaşılır; saat ve rakam algı farkını ortadan kaldırır. Diğer üç cümle nazik görünür, ama yine yoruma açıktır."},{"id":"mg-1-s27","tur":"coktan-secmeli","soru":"Çorbası soğuk gelen misafirin şikâyetinde LAST yaklaşımına göre ilk iki adım hangisidir?","secenekler":["Özür dilemek, hemen çözmek","Dinlemek, özür dilemek","Dinlemek, çözmek","Çözmek, teşekkür etmek"],"dogru":1,"aciklama":"LAST sırası Listen – Apologise – Solve – Thank’tir; misafir önce dinlenir, sonra özür dilenir. Dinlemeden çözüme atlamak misafire anlaşılmadığını hissettirir."},{"id":"mg-1-s28","tur":"coktan-secmeli","soru":"40 kişilik grubun giriş saati 14.00’ten 11.00’e çekildi. Bu haberin paydaşlara verilmesinde hangisi doğrudur?","secenekler":["Herkese aynı cümleyle ve aynı kanaldan, aynı anda bildirmek","Yalnız resepsiyona söylemek, bölümlerin kendi öğrenmesini beklemek","Şefe kısa ve net, acenteye yazılı, misafire nazik ve sade bildirmek","Önce çalışanlara bildirmek, misafirlere giriş anında söylemek"],"dogru":2,"aciklama":"Paydaşların beklentisi farklıdır; kime, ne zaman ve hangi kanalla söyleneceği planlanır. Tek cümleyle herkese duyurmak ya da bazı paydaşları atlamak, haberin ulaşmamasına yol açar."},{"id":"mg-1-s29","tur":"coktan-secmeli","soru":"Hiçbir şey söylemeden otelden ayrılan bir misafir için hangisi doğrudur?","secenekler":["Beklentisi karşılanmadıysa memnun kalmamıştır","Şikâyet etmediği için kesinlikle memnun kalmıştır","Fiyat düşükse memnuniyeti kesinleşmiş sayılır","Memnuniyet yalnız yıldız sayısına bağlıdır"],"dogru":0,"aciklama":"Memnuniyet, misafirin beklentisiyle aldığı hizmetin karşılaştırılmasından doğar; sessizlik bunun ölçüsü değildir. Fiyat ve yıldız yalnızca beklentiyi etkiler."},{"id":"mg-1-s30","tur":"coktan-secmeli","soru":"Yarınki tur hava nedeniyle iptal oldu. Tura yazılan misafirler bu akşam otelde. En iyi iletişim stratejisi hangisidir?","secenekler":["Sabah, tur saatinde lobide toplananlara söylemek","Bilgiyi panoya asıp misafirlerin görmesini beklemek","Misafirlere e-posta gönderip okunmasını beklemek, başka işlem yapmamak","Akşam oda telefonundan arayıp haberi seçenekle vermek"],"dogru":3,"aciklama":"İletişim stratejisi mesajın kime, ne zaman, hangi kanalla ve nasıl verileceğini planlamaktır. Kötü haber geciktirilmez, acilse telefonla verilir ve yanında seçenek sunulur; pano ve e-posta mesajın ulaştığını garanti etmez."},{"id":"mg-1-s31","tur":"dogru-yanlis","soru":"Misafirin isteğini yerine getiremeyen görevli, yine de onun duygusunu anladığını gösterebilir; bu da empatidir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Empati her konuda hak vermek değil, karşıdakinin ne hissettiğini anlamak ve bunu ona göstermektir. İstek yerine getirilemese bile misafir anlaşıldığını hisseder."},{"id":"mg-1-s32","tur":"dogru-yanlis","soru":"Şık giyimli bir misafirin her söylediğini sorgusuz doğru kabul etmek ön yargı sayılmaz, çünkü yargı olumludur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Ön yargı, yeterli bilgiye dayanmadan edinilen olumlu ya da olumsuz yargıdır. Olumlu olması onu ön yargı olmaktan çıkarmaz."},{"id":"mg-1-s33","tur":"senaryo","durum":"Acentede bir müşteri aile tatilini anlatıyor: bütçesini, çocukların yaşlarını ve istediği bölgeyi sıraladı. Sen not alıyordun; müşteri sustu.","soru":"Sonraki adımın ne olur?","secenekler":["Hemen en uygun gördüğüm üç oteli fiyatlarıyla birlikte sıralamaya başlarım.","Bütçeyi bir kez daha sorar, kalan ayrıntıları sonra konuşalım derim.","Müşteri yeniden konuşsun diye sessizce ve not alarak beklerim.","Anladıklarımı kendi cümlemle söyler, eksik konuyu açık uçlu soruyla sorarım."],"dogru":3,"aciklama":"Yeniden ifade, anlaşılanı doğrular; açık uçlu soru da eksik kalan ayrıntıyı tahmin etmek yerine müşteriye anlattırır. Hemen öneri sunmak ya da sessiz kalmak, doğru bilgiye dayanmadan ilerlemektir."},{"id":"mg-1-s34","tur":"senaryo","durum":"Saat 18.00, santraldasın. Rezervasyon için arayan misafirin sesi hattaki bozukluk yüzünden kesik kesik geliyor; tarih ve isim anlaşılmıyor.","soru":"Ne yaparsın?","secenekler":["Bilgileri tekrar ederek teyit alırım, hat düzelmezse geri ararım.","Duyabildiklerime göre kaydı tamamlar, kalan kısmı tahmin ederim.","Sesimi yükselterek aynı soruyu tekrar tekrar sorarım.","Misafirden başka bir gün yeniden aramasını isterim."],"dogru":0,"aciklama":"Hattaki bozukluk fiziksel bir engeldir; teyit ve geri arama bilgiyi güvenceye alır. Tahminle kayıt yanlış rezervasyon doğurur; sesi yükseltmek hattı düzeltmez."},{"id":"mg-1-s35","tur":"senaryo","durum":"Saat 10.00, kat hizmetlerinde stajyersin. Odanın kliması çalışmıyor; tam o sırada misafir odaya dönüyor, kat şefi de koridorda.","soru":"Hangisi doğru davranıştır?","secenekler":["İkisine de aynı teknik açıklamayı yaparım.","Şefe kısa ve net bildirir, misafirden özür dilerim.","Yalnız şefe söyler, misafire bir şey söylemem ve beklerim.","Misafire arızanın ne kadar süreceğine dair tahminimi söylerim."],"dogru":1,"aciklama":"Şef ile misafir aynı işin farklı paydaşlarıdır: şef kısa ve net bilgi, misafir nazik bir açıklama bekler. Susmak misafiri habersiz bırakır; süre tahmini ise tutulamayacak bir beklenti yaratır."},{"id":"mg-1-s36","tur":"senaryo","durum":"Saat 05.30, resepsiyondasın. Uçağına yetişmeye çalışan telaşlı bir misafir hesabını kapatmak istiyor.","soru":"İlk adımın ne olur?","secenekler":["Her kalemi tek tek okuyup misafirden onay alırım, sonra imza isterim.","Uçağı kaçırmayacağını söyleyerek onu rahatlatırım.","Hesabı kısaca gösterip işlemi hızla bitirir, sorarsa açıklarım.","Kısa bir sohbetle sakinleşmesini beklerim."],"dogru":2,"aciklama":"İletişim misafirin o anki duygusal durumuna göre ayarlanır; telaşlı misafir hızlı ve kısa hizmet ister. Uçak konusunda söz vermek yetkin olmadığın bir konuda beklenti yaratır."},{"id":"mg-1-s41","tur":"coktan-secmeli","soru":"Cumartesi öğlen yoğunluğunda bir stajyerin kalbi hızlanıyor, elleri terliyor. Sezon boyunca hiç dinlenememiş bir kat görevlisi ise artık işe gitmek istemiyor. Bu iki durum sırasıyla neyi gösterir?","secenekler":["Tükenmişlik – stres","Öfke – kaçınma","Stres – tükenmişlik","Stres – öz farkındalık"],"dogru":2,"aciklama":"Stres, baskı karşısındaki anlık gerginliktir; tükenmişlik ise uzun süren iş stresinin sonunda ortaya çıkan yorgunluk ve isteksizliktir. İkisini karıştırmak, birinin nedeni diğerinin sonucu olduğu için kolaydır."},{"id":"mg-1-s42","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi yoğun vardiyada stresle başa çıkma yöntemi sayılmaz?","secenekler":["İşleri önceliğe göre sıraya koyup çalışmak","Yetişemeyen işi kimseye söylememek","Kısa bir nefes alıp biraz sakinleşmek","Gerekirse amirden yardım istemek ve işi paylaşmak"],"dogru":1,"aciklama":"Öncelik sırası, nefes ve yardım istemek stresi azaltan yollardır. Yetişemeyen işi saklamak yükü ağırlaştırır; misafir de bekletilmiş olur."},{"id":"mg-1-s43","tur":"coktan-secmeli","soru":"Sezon sonunda haftalardır dinlenemeyen bir çalışan eskiden severek yaptığı karşılamayı artık gülümsemeden yapıyor. Bu çalışan için ilk adım hangisi olmalıdır?","secenekler":["Daha çok vardiya alarak işe alışmak","Hissini kimseye belli etmeden işe devam etmek","Misafirle konuşmayı bırakıp yalnız sessiz görevlere geçmek","Güvendiği birine durumu anlatıp dinlenmeyi planlamak"],"dogru":3,"aciklama":"Bu belirtiler tükenmişliktir; çözüm yükü içte tutmak değil, güvenilen biriyle paylaşmak ve dinlenmeyi planlamaktır. Vardiya artırmak ya da yalnız çalışmak yorgunluğu azaltmaz."},{"id":"mg-1-s44","tur":"coktan-secmeli","soru":"Yorgun bir havuz görevlisi ağlamak üzere olan çocuğu fark eder; kendi yorgunluğunu belli etmeden “Birlikte buluruz” der. Hangi beceriyi göstermektedir?","secenekler":["Duygusal zekâ","Öz farkındalık","Arabuluculuk","Uzlaşma"],"dogru":0,"aciklama":"Hem kendi duygusunu yönetmek hem de karşıdakinin duygusunu tanıyıp ona göre davranmak duygusal zekâdır. Öz farkındalık yalnız kendi duygunu fark etmektir."},{"id":"mg-1-s45","tur":"coktan-secmeli","soru":"“Çok cümle öğreneceğim” yerine “Haftada 10 kalıp cümle öğreneceğim” diyen öğrenci hedefine hangi SMART ölçütünü kazandırmıştır?","secenekler":["Ölçülebilir","Zamana bağlı","Ulaşılabilir","Gerçekçi – ilgili"],"dogru":0,"aciklama":"Sayı eklemek ilerlemeyi izlenebilir yapar, yani ölçülebilirlik sağlar. Zamana bağlı ölçütü için bir bitiş tarihi gerekir; burada yalnız haftalık sayı vardır."},{"id":"mg-1-s46","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi SMART ölçütlerine en uygun hedeftir?","secenekler":["Bu yıl İngilizcemi çok daha fazla geliştireceğim.","Bir ay içinde Almancayı akıcı konuşacağım.","Dönem sonuna kadar haftada 10 İngilizce karşılama cümlesi öğreneceğim.","Her gün düzenli olarak, uzun süre İngilizce çalışacağım."],"dogru":2,"aciklama":"Bu hedefte ne yapılacağı belli, ilerleme sayılıyor, ulaşılabilir, işe katkı sağlıyor ve bitiş tarihi var. Diğerleri sayı, tarih ya da ulaşılabilirlikten en az birinden yoksundur."},{"id":"mg-1-s47","tur":"coktan-secmeli","soru":"“Bir ayda akıcı Almanca konuşacağım” diyen 9. sınıf öğrencisinin hedefinde hangi SMART ölçütü eksiktir?","secenekler":["Spesifik","Ulaşılabilir","Ölçülebilir","Zamana bağlı"],"dogru":1,"aciklama":"Bir ayda akıcı yabancı dil, 9. sınıf düzeyinde bilgi ve imkânla başarılamaz. Ne yapılacağı (Almanca konuşmak) ve süre (bir ay) belli olduğu için diğer ölçütler eksik değildir."},{"id":"mg-1-s48","tur":"coktan-secmeli","soru":"Gece 02.00’de yangın alarmı çalıyor. Vardiya amiri tartışmaya yer bırakmadan herkesi acil çıkışa yönlendiriyor. Bu hangi çatışma yaklaşımıdır?","secenekler":["Uzlaşma","İş birliği","Uyma","Rekabet"],"dogru":3,"aciklama":"Rekabet, kendi isteğinde ısrar etmektir ve güvenlik gibi hızlı karar gereken durumlarda yerindedir. Uzlaşma ve iş birliği zaman ister; acil durumda tartışacak zaman yoktur."},{"id":"mg-1-s49","tur":"coktan-secmeli","soru":"Sabah vardiyasını isteyen iki kat görevlisi vardiyaları haftalara bölüşüyor: ikisi de istediğinin bir kısmından vazgeçiyor. Bu hangi yaklaşımdır?","secenekler":["Uyma","İş birliği","Kaçınma","Uzlaşma"],"dogru":3,"aciklama":"İki tarafın da bir miktar geri adım atarak buluşması uzlaşmadır. Uymada yalnız bir taraf geri adım atar; iş birliğinde ise kimse vazgeçmez, ortak çözüm bulunur."},{"id":"mg-1-s50","tur":"coktan-secmeli","soru":"Bölüm şefi görev paylaşımı yüzünden küsen iki stajyeri dinlemeden “Karar verildi, tartışma yok” deyip çizelgeyi kendisi belirliyor. Bu hangi yaklaşımdır?","secenekler":["Arabuluculuk","Bastırma","Uzlaşma","İş birliği"],"dogru":1,"aciklama":"Yetkiyi kullanarak çözümü karşı tarafa kabul ettirmek bastırmadır; güveni zedeler. Arabulucu ise tarafsızdır ve çözümü tarafların bulmasına yardım eder."},{"id":"mg-1-s51","tur":"coktan-secmeli","soru":"Hangisi çatışma çözümü için yazılmış bir eylem planı cümlesidir?","secenekler":["Hazır odalar mümkün olduğunca erken ve düzenli biçimde bildirilecek.","Bir daha olmasın, herkes daha dikkatli olsun.","Kat görevlisi hazır odayı bildirecek, şef bir hafta sonra kontrol edecek.","Resepsiyon ve kat hizmetleri bundan sonra birbiriyle daha iyi anlaşacak."],"dogru":2,"aciklama":"Eylem planı kimin, neyi, ne zaman yapacağını söyler. Diğer cümlelerde ya sorumlu kişi ya da zaman yoktur; böyle çözümler birkaç gün sonra unutulur."},{"id":"mg-1-s52","tur":"coktan-secmeli","soru":"Çatışmada kaçınma (ertelemek) hangi durumda yanlış bir seçimdir?","secenekler":["Konu önemli olup her hafta tekrarlanıyorsa","Konu küçük ve kısa sürede unutulacaksa","Taraflar çok öfkeliyse ve ara vermek gerekiyorsa","Gerginlik misafirin önünde yaşanıyorsa, sakin yerde konuşmak için"],"dogru":0,"aciklama":"Önemli ve tekrarlayan bir sorun ertelenirse çözülmez, büyür. Diğer üç durumda kaçınma, zaman kazandırarak daha doğru bir konuşmaya zemin hazırlar."},{"id":"mg-1-s53","tur":"dogru-yanlis","soru":"Çatışmayı misafirin önünde değil, tarafların sakinleştiği bir zamanda ve sakin bir yerde konuşmak çözümün parçasıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Ortam gergin ya da kalabalıksa taraflar birbirini dinleyemez; doğru zaman ve doğru yer çözümü kolaylaştırır."},{"id":"mg-1-s54","tur":"dogru-yanlis","soru":"Üçüncü işi alamayacağını söyleyip yardım isteyen bir stajyer saldırgan davranmış sayılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sınır koymak kırıcı olmadan söylendiğinde atılgan iletişimdir. Saldırganlık karşıdakini suçlayıp ezmektir; yardım istemek ise profesyonel bir davranıştır."},{"id":"mg-1-s55","tur":"senaryo","durum":"Saat 17.30, restoran dolu; üç masa aynı anda sipariş bekliyor. Kalbinin hızlandığını ve sesinin sertleşmeye başladığını fark ediyorsun.","soru":"Ne yaparsın?","secenekler":["En kolay işleri önce bitirip yoğun masalara sonra bakarım.","Bir nefes alır, en uzun bekleyen masadan başlar, yetişemezsem yardım isterim.","Her masaya aynı anda dönmeye çalışır, olabildiğince hızlı hareket ederim.","Amirim yardım istememi söyleyene kadar işime devam ederim."],"dogru":1,"aciklama":"Stresi fark ettiğin an nefes, öncelik sırası ve yardım istemenin zamanıdır. Önceliği bekleme süresi belirler; hepsine birden yetişmeye çalışmak ise hata riskini artırır."},{"id":"mg-1-s56","tur":"senaryo","durum":"Saat 13.00, servis geçidindesin. Hazırladığın tepsiyi bir arkadaşın haber vermeden alıp götürmüş, işin aksadı. Öfkelendiğini hissediyorsun; yakında misafirler var.","soru":"Hangisi doğru davranıştır?","secenekler":["Servis bitince sakinleşip “Tepsi alınınca işim aksadı” derim.","Hemen yanına gidip sesimi yükselterek hesap sorarım.","Bir şey demem, bir sonraki sefer ben de onun tepsisini alırım.","Ona güvenilmeyeceğini servis bitince diğer arkadaşlara anlatırım."],"dogru":0,"aciklama":"Öfke yönetimi, öfkeyi fark edip uygun zamanda, ben diliyle ifade etmektir. Koridorda bağırmak misafiri rahatsız eder; karşılık vermek ve söylenmek sorunu büyütür."},{"id":"mg-1-s57","tur":"senaryo","durum":"Cumartesi saat 09.30, resepsiyondasın. Gece yolculuğundan gelen bir aile odasına hemen çıkmak istiyor; oda 13.00’te hazır olacak. Baba sesini yükseltiyor: “Üç buçuk saat lobide mi bekleyeceğiz?”","soru":"İlk adımın ne olur?","secenekler":["Giriş saatinin 14.00 olduğunu, bunun onay yazısında da belirtildiğini hatırlatırım.","Temizliği bitmemiş bir odanın anahtarını verip ailenin yerleşmesini sağlarım.","Karar yetkisi bende değil diyerek amirimin gelmesini beklemelerini rica ederim.","Yorgunluklarını anladığımı söyler, valizleri emanete alıp oda hazır olunca ararım."],"dogru":3,"aciklama":"Önce misafirin duygusu görülür, sonra iki tarafın da kabul edeceği bir çözüm sunulur: aile rahat eder, otel odayı hazırlayacak zamanı bulur. Kuralı hatırlatmak haklı çıkmaktır, hazır olmayan oda yeni şikâyet doğurur."},{"id":"mg-1-s58","tur":"senaryo","durum":"Saat 16.30, akşam vardiyasında resepsiyondasın. Bir misafir sabah söz verilen geç çıkışa rağmen odaya girildiğini söylüyor. Sabah vardiyasındaki arkadaşın sözü deftere yazmamış; bu ay üçüncü kez böyle oluyor. Misafirden özür dileyip durumu düzelttin.","soru":"Bundan sonra ne yaparsın?","secenekler":["Misafire, hatanın sabah vardiyasındaki görevliden kaynaklandığını açıklarım.","Arkadaşımla aram bozulmasın diye bu konuyu kimseyle hiç açmam.","Amirime bildirir, sözlerin deftere yazılıp devirde aktarılmasını öneririm.","Devirde herkesin önünde arkadaşıma dikkatsiz olduğunu söylerim."],"dogru":2,"aciklama":"Tekrarlayan sorun çözülmek için kimin, neyi, ne zaman yapacağı belirlenerek ele alınır: söz deftere yazılır, devirde aktarılır. Misafire suçu atmak oteli küçük düşürür; susmak sorunu sürdürür; herkesin önünde suçlamak yeni çatışma doğurur."},{"id":"mg-1-s59","tur":"coktan-secmeli","soru":"Saat 12.10’da kat görevlisi resepsiyonu arayıp “305 hazır” diyor. Bu iletişim hangi türe girer?","secenekler":["Yukarıdan aşağıya dikey iletişim","Aşağıdan yukarıya dikey iletişim","Aynı düzeyde yatay iletişim","Konukla yapılan dış iletişim"],"dogru":2,"aciklama":"Kat hizmetleri ile ön büro aynı düzeydeki iki bölümdür; aralarındaki iletişim yataydır. Dikey iletişim ise yönetici ile çalışan arasında olur."},{"id":"mg-1-s60","tur":"coktan-secmeli","soru":"Resepsiyonist konuğa kahvaltının 10.30’a kadar açık olduğunu söylüyor; konuk “Yani on buçuğa kadar, değil mi?” diye soruyor. Konuğun bu sorusu iletişimin hangi öğesidir?","secenekler":["Geri bildirim","Gürültü","İletişim kanalı","Mesaj (ileti)"],"dogru":0,"aciklama":"Alıcının mesaja verdiği tepki geri bildirimdir ve mesajın doğru anlaşılıp anlaşılmadığını gösterir. Mesaj ise resepsiyonistin aktardığı kahvaltı saatidir."},{"id":"mg-1-s61","tur":"dogru-yanlis","soru":"Stajyerin arızalı yazıcıyı amirine bildirmesi yatay iletişimdir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çalışandan yöneticiye giden bilgi aşağıdan yukarıya dikey iletişimdir. Yatay iletişim aynı düzeydeki çalışanlar ya da bölümler arasında olur."},{"id":"mg-1-s62","tur":"coktan-secmeli","soru":"Kat şefi “208 öncelikli” bilgisini görevliye önce telsizle söylüyor, sonra yanına gidip yüz yüze tekrarlıyor. İki durumda değişen öğe hangisidir?","secenekler":["Mesaj","Alıcı","Gönderici","Kanal"],"dogru":3,"aciklama":"Mesaj, gönderici ve alıcı aynı kalmıştır; yalnız mesajın iletildiği yol (telsiz, yüz yüze konuşma) değişmiştir. Bu yol kanaldır."},{"id":"mg-1-s63","tur":"coktan-secmeli","soru":"Akşam bir konuk geç çıkış isteğinin ne durumda olduğunu soruyor. Hangi cevap açıklık (netlik) ilkesine uygundur?","secenekler":["Late check-out talebiniz şu anda opsiyonda, efendim.","Saat 14.00’e kadar kalıp kalamayacağınızı sabah bildiririm.","Talebiniz sistemde kayıtlı; upgrade durumuna da bakarız efendim.","Talebinize en kısa sürede dönüş yapılacaktır, efendim."],"dogru":1,"aciklama":"Açıklık, kısa ve anlaşılır cümle kurup terimleri açıklamaktır; doğru cevap saati ve ne zaman haber verileceğini sade dille söyler. “Opsiyon”, “upgrade” gibi terimler ve belirsiz “en kısa sürede” sözü konuğu belirsizlikte bırakır."},{"id":"mg-1-s64","tur":"coktan-secmeli","soru":"Görevli bir aileye “Odanız opsiyonda, upgrade bakarız” diyor; aile ne dendiğini anlamıyor. Görevlinin hatası nedir?","secenekler":["Konuğa kapalı uçlu soru sormak","Konuşurken kişisel mesafeyi korumamak","Konuğa mesleki jargonla konuşmak","Konuğu dinlemeden konuşmak"],"dogru":2,"aciklama":"Mesleki jargon, işi bilmeyenlerin anlamakta zorlandığı özel sözcük ve kısaltmalardır; konuğa bunların sade karşılığıyla konuşulmalıdır. Görevlinin cümlesinde soru, mesafe ya da dinlememe sorunu yoktur."},{"id":"mg-1-s65","tur":"dogru-yanlis","soru":"Konuğun sesi yükselince kısa bir an durup “Şu an gerildim” diye düşünen stajyer, duygusunu fark ederek sakin cevap verme fırsatı yaratır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Duyguları tanıma ve duraksama tekniğinde kişi tepki vermeden önce kısa bir süre durup duygusunu fark eder; böylece sakin bir sesle cevap verebilir."},{"id":"mg-1-s66","tur":"coktan-secmeli","soru":"Cumartesi akşamı lobide düğün kalabalığı var. Stajyer yol tarifini bağırarak anlatmak yerine konuğu bankonun sakin ucuna alıyor ve tarifi kâğıda da yazıyor. Stajyer hangi engeli aşmaya çalışıyor?","secenekler":["Kültürel engel","Psikolojik engel","Dil ve anlam engeli","Fiziksel engel"],"dogru":3,"aciklama":"Gürültülü lobi ortamdan kaynaklanan fiziksel bir engeldir; stajyer sakin bir yer ve yazılı not kullanarak bunu aşar. Sorun konuğun duygusundan ya da dilinden değil, ortamdan kaynaklanır."},{"id":"mg-1-s67","tur":"coktan-secmeli","soru":"Otel girişinde stajyer yeni gelen konuğa elini uzatıyor; konuk elini göğsüne koyup başıyla selam veriyor. Stajyerin en doğru tepkisi hangisidir?","secenekler":["Elini uzatmayı sürdürüp konuğun tokalaşmasını beklemek","Gülümseyip aynı biçimde selamla karşılık vermek","Selamın reddedildiğini düşünüp amire bildirmek","Selamı görmezden gelip kayıt işlemine geçmek"],"dogru":1,"aciklama":"Selamlaşma biçimi kültürden kültüre değişir; konuk saygısızlık etmemiştir. Stajyerin alınmadan aynı biçimde karşılık vermesi kültürel engeli aşar."},{"id":"mg-1-s68","tur":"coktan-secmeli","soru":"Vardiya öncesi bir görevli “Bu ülkeden gelenler hep şikâyet eder” diyor ve gruptaki her konuğa mesafeli davranıyor. Görevlinin düşüncesi hangisine örnektir?","secenekler":["Kalıp yargı","Varsayım","Algı farkı","Mantıksal çelişki"],"dogru":0,"aciklama":"Kalıp yargı, bir grubun bütün üyelerinin aynı özellikleri taşıdığını düşünen genellemedir. Varsayım ise bir bilginin kontrol edilmeden doğru kabul edilmesidir; burada bir grubun tamamı hakkında yargı vardır."},{"id":"mg-1-s69","tur":"dogru-yanlis","soru":"“Bir gün otel tanıtımı sunmayı öğreneceğim” hedefi zamana bağlı bir hedeftir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Zamana bağlı hedefin bir bitiş tarihi olur; “bir gün” ucu açık bir sözdür. “Dönem sonuna kadar” gibi bir tarih eklenince hedef zamana bağlı olur."},{"id":"mg-1-s70","tur":"coktan-secmeli","soru":"Resepsiyonda telefon çalıyor; görevli bekletmeden açıyor. Telefon görgüsüne uygun ilk cümle hangisidir?","secenekler":["Alo, buyurun efendim, kimi aramıştınız acaba?","Şu an çok yoğunuz efendim, birazdan arar mısınız?","İyi günler, Mavi Otel ön büro, ben Elif, buyurun.","Evet, dinliyorum efendim; rezervasyon için mi aradınız?"],"dogru":2,"aciklama":"Telefon görgüsünde görevli selam verir, otelin ve kendi adını söyleyerek kendini tanıtır. Öteki cevaplar kendini tanıtmaz ya da arayanı bekletir."},{"id":"mg-1-s71","tur":"coktan-secmeli","soru":"Acentede müşteri isteklerini uzun uzun anlatıyor. Görevli “Yani iki yetişkin ve bir çocuk için denize yakın, sessiz bir otel arıyorsunuz” diyor. Görevli hangi tekniği kullanmıştır?","secenekler":["Kapalı uçlu soru","Ben dili","Yapıcı geri bildirim","Yeniden ifade etme"],"dogru":3,"aciklama":"Görevli müşterinin söylediklerini kendi cümleleriyle tekrarlıyor; bu yeniden ifade etmedir ve doğru anlaşıldığını gösterir. Cümle evet/hayır cevabı isteyen bir soru olarak kurulmadığı için kapalı uçlu soru değildir."},{"id":"mg-1-s72","tur":"coktan-secmeli","soru":"Koridorda karşılaştığı konuğa kat görevlisinin “Günaydın” demesi hizmet açısından neden önemlidir?","secenekler":["Konuk bu kısa temasla otel hakkında fikir edinir","Konukları karşılamak kat görevlisinin asıl işidir","Selam vermek oda temizliğini daha hızlı bitirir","Selam alan konuk sonradan şikâyet edemez"],"dogru":0,"aciklama":"Konuğun işletmeyle temas ettiği her an bir gerçeğin anıdır ve hizmet hakkındaki fikrini oluşturur. Koridordaki kısa bir selam da bu anlardan biridir."},{"id":"mg-1-s73","tur":"dogru-yanlis","soru":"Konuğa yanlış yemek geldiğinde garsonun özür dilemesi yeterlidir; doğru yemeği hızla getirmek hizmet telafisi için gerekmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Hizmet telafisi aksaklığı hızla düzelterek memnuniyeti yeniden kazanmaktır. Özrün yanında doğru yemek öncelikle getirilir ve konuğun memnun olup olmadığı sorulur."},{"id":"mg-1-s74","tur":"coktan-secmeli","soru":"Şef “Yedi numaralı masa neden geç servis edildi?” diye soruyor. Garsonun hangi cevabı savunmacı değil, yapıcıdır?","secenekler":["“Mutfak geç yolladı, benim suçum değil!”","“Siparişi geç girdim; artık hemen gireceğim.”","“Elimden geleni yaptım, başkasına sorun.”","“Bugün herkes çok yavaştı, yalnız beni sormayın.”"],"dogru":1,"aciklama":"Yapıcı iletişimde kişi suçu başkasına atmadan sorumluluğunu kabul eder ve çözüme odaklanır. Öteki cevaplar, suçlandığını düşünen kişinin kendini korumak için verdiği savunmacı cevaplardır."},{"id":"mg-1-s75","tur":"coktan-secmeli","soru":"Öğle arasında Ali kendi kendine “Sabahki konuğa kısa cevap verdim, çünkü uykusuzdum ve gerilmiştim” diyor. Ali hangi beceriyi göstermektedir?","secenekler":["Empati","Atılgan iletişim","Sınır koyma","Öz farkındalık"],"dogru":3,"aciklama":"Öz farkındalık, kişinin kendi duygularını ve tepkilerini fark etmesidir; Ali tepkisinin nedenini görmüştür. Empati ise karşıdakinin duygusunu anlamaktır."},{"id":"mg-1-s76","tur":"dogru-yanlis","soru":"Gece yaşanan bir sorunun kayıt defterine yazılması, sabah vardiyasının konuğa durumu sorabilmesini sağlar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kayıt defteri vardiyalar arasında bilgi aktarır; sabah vardiyası notu okuyunca konuğun yaşadığı sorundan haberdar olur ve onunla ilgilenebilir."},{"id":"mg-1-s77","tur":"coktan-secmeli","soru":"Kat ofisinde stajyer, başka bir odanın minibar ücretini yanlışlıkla bir konuğun hesabına yazdığını fark ediyor; bunu kimse görmemiş. Mesleki ahlaka uygun davranış hangisidir?","secenekler":["Konuk fark etmezse hesabı olduğu gibi bırakmak","Konuk itiraz ederse hesabı düzeltmek","Şefe söyleyip hesabı hemen düzeltmek","Hatayı sonraki vardiyanın düzeltmesine bırakmak"],"dogru":2,"aciklama":"Mesleki ahlak, kimse bakmasa da dürüst ve güvenilir davranmayı gerektirir; stajyer hatasını şefe söyler ve düzeltir. Konuğun fark etmesini ya da itiraz etmesini beklemek dürüstlüğe aykırıdır."},{"id":"mg-1-s78","tur":"coktan-secmeli","soru":"İki stajyer de cumartesi günü izin istiyor. Biri, arkadaşının o gün ailesinde düğün olduğunu öğrenince “Cumartesiyi sen al, bu sefer ben vazgeçiyorum” diyor. Bu hangi çatışma yaklaşımıdır?","secenekler":["Uzlaşma","Uyma","Rekabet","Kaçınma"],"dogru":1,"aciklama":"Stajyer ilişkiyi konudan önemli görüp arkadaşının isteğini kabul etmiştir; bu uymadır. Uzlaşmada iki taraf da bir miktar geri adım atar, burada ise yalnız biri vazgeçmiştir."},{"id":"mg-1-s79","tur":"coktan-secmeli","soru":"Sabah restoranda kirli tabakları kimin toplayacağı belli değil; garson da komi de “Ben değil” diyor, masalar bekliyor. Bu anlaşmazlığın nedeni hangisidir?","secenekler":["Rol ve görev belirsizliği","Amaç ve çıkar farklılığı","Tarafların kişisel özellikleri","İletişim engelleri"],"dogru":0,"aciklama":"Kimin hangi işten sorumlu olduğu açıkça belirlenmediği için anlaşmazlık çıkmıştır; bu rol ve görev belirsizliğidir. İkisinin hedefi farklı olmadığından amaç ve çıkar farklılığı değildir."}],"siralamalar":[{"id":"mg-1-r01","konu":"1.1","baslik":"Teslimat gecikecek: müşteriyi aramak","yonerge":"Arıza yüzünden ürünü söz verilen saatte teslim edemeyeceğini müşteriye telefonla bildirirken atılgan iletişimin adımlarını doğru sıraya koy.","adimlar":["Durumu açıkça tanımla, sorumluluğu üstlen ve müşterinin duygusunu dikkate aldığını söyle.","Sorunu nasıl gidereceğine dair somut bir çözüm öner.","Önerdiğin çözüm için müşteriden onay al.","Süreci takip edeceğini müşteriye belirt."],"aciklama":"Müşteri neyle karşı karşıya olduğunu bilmeden çözümü değerlendiremez; çözüm önerilmeden onay alınamaz, onaydan sonra da süreci takip edeceğini söylemek güveni pekiştirir. Atölye görevindeki atılgan iletişim akışı bu basamakları izler."},{"id":"mg-1-r02","konu":"1.2","baslik":"Yanlış anlaşılan talimatı onarmak","yonerge":"Gürültülü atölyede yarım duyulan bir talimat yüzünden hata yapıldı. Sorunu çözme adımlarını doğru sıraya koy.","adimlar":["Ne yanlış gittiğini ve hatanın nereden kaynaklandığını açıkça ortaya koy.","Stajyerin duymadığı ya da anlamadığı bilgileri, örneğin bilmediği terimleri belirle.","Talimatı sakin ve net biçimde yeniden anlat, “Doğru anladım mı?” diye geri bildirim iste.","İşin talimata uygun yapılıp yapılmadığını kontrol et.","Benzer bir hatanın tekrar yaşanmaması için önlem al."],"aciklama":"Sorun tanımlanmadan eksik bilgi bulunamaz, eksik bilgi bulunmadan doğru açıklama yapılamaz; uygulama kontrol edildikten sonra kalıcı önlem alınır. Kitaptaki beş çözüm adımı bu sırayı izler."},{"id":"mg-1-r03","konu":"1.5","baslik":"Arabulucu sensin: çatışmayı çöz","yonerge":"Takım lideri olarak iki çalışan arasındaki çatışmayı yönetirken izleyeceğin basamakları doğru sıraya koy.","adimlar":["Çatışmanın nedenini, tarafların beklenti ve duygularını ve aradaki iletişim engellerini çözümle.","Uygun çatışma çözüm stratejisini seç ve neden seçtiğini gerekçelendir.","Takım lideri ya da arabulucu olarak bir eylem planı hazırla.","Hazırladığın eylem planını kullanarak çözüm sürecini uygula ya da sınıfta canlandır."],"aciklama":"Bir çatışmayı çözmek için önce kaynağı doğru belirlemek gerekir; strateji ancak sorun anlaşıldıktan sonra seçilir, eylem planı seçilen stratejiye göre hazırlanır ve en sonda uygulanır. Kitaptaki 1.5 atölye görevi bu basamakları izler."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":10,"baslik":"Finansal Okuryazarlık","onay":true,"kazanimlar":["Mesleki hedefleri doğrultusunda finansal durumunu ekonomik veriler bağlamında tahmin edebilme.","İş fikrinin finansal uygulanabilirliğini değerlendirebilme.","Bir iş sürecinin sürdürülebilirliği için finansal bir plan yapılandırabilme."],"soz":"Parayı kazanmak emektir; yönetmek ise ayrı bir meslek becerisidir.","dersler":[{"baslik":"Paran Nereye Gidiyor?","ilk":"mg-10-001"},{"baslik":"Harçlık Ay Sonunu Görür mü?","ilk":"mg-10-006"},{"baslik":"Sezon Biter, Kış Gelir","ilk":"mg-10-009"},{"baslik":"Maaşın Neden Eksik Yattı?","ilk":"mg-10-014"},{"baslik":"Faiz: Dost mu, Tuzak mı?","ilk":"mg-10-046"},{"baslik":"Taksit mi, Peşin mi?","ilk":"mg-10-051"},{"baslik":"Yumurtalar Tek Sepette mi?","ilk":"mg-10-054"},{"baslik":"Bu Mesaj Gerçekten Bankadan mı?","ilk":"mg-10-059"},{"baslik":"Önce Plan, Sonra Harcama","ilk":"mg-10-065"},{"baslik":"Borç Alırken Kendine Sor","ilk":"mg-10-068"},{"baslik":"Para Hangi Kapıdan Girer?","ilk":"mg-10-072"},{"baslik":"Pansiyon Açmanın Başlangıç Maliyeti","ilk":"mg-10-018"},{"baslik":"Bir Odanın Maliyeti Ne?","ilk":"mg-10-022"},{"baslik":"Kaç Oda Satarsan Kurtarır?","ilk":"mg-10-028"},{"baslik":"Parayı Kimden Bulursun?","ilk":"mg-10-032"},{"baslik":"Kasa Dolu, Kâr Var mı?","ilk":"mg-10-011"},{"baslik":"Gelir Tablosu Ne Anlatır?","ilk":"mg-10-037"},{"baslik":"İşletmeyi Ayakta Tutan Plan","ilk":"mg-10-041"},{"baslik":"Büyümenin Bedeli","ilk":"mg-10-063"},{"baslik":"Paranın Değeri Erir mi?","ilk":"mg-10-045"},{"baslik":"Satış Var, Para Nerede?","ilk":"mg-10-083"},{"baslik":"Risk İçeriden mi Dışarıdan mı?","ilk":"mg-10-086"},{"baslik":"Krizde Plan B","ilk":"mg-10-089"}],"kavramlar":[{"id":"mg-10-001","konu":"10.1","terim":"Finansal okuryazarlık","ingilizce":"Financial literacy","tanim":"Parayla ilgili temel kavramları bilerek gelirini, giderini, birikimini ve borcunu bilinçli kararlarla yönetebilme becerisidir.","ornek":"İlk staj ücretini alan öğrenci parayı harcamadan önce bir kâğıda yazar: ne kadarı yola, ne kadarı yemeğe, ne kadarı kenara ayrılacak.","sektor":"Programın anahtar kavramlarındandır. Turizmde gelir çoğu zaman sezona göre iner çıkar; parasını yönetmeyi bilen çalışan kışı borçsuz geçirir, işletmeci de işini ayakta tutar.","iliskili":["mg-10-002","mg-10-003","mg-10-006"],"kontrol":null,"gorsel":"m9-piggy-bank-968302"},{"id":"mg-10-002","konu":"10.1","terim":"Gelir","ingilizce":"Income","tanim":"Bir kişinin ya da işletmenin belirli bir sürede çalışarak, satış yaparak ya da başka yollarla elde ettiği paradır.","ornek":"Bir lise öğrencisi için aylık harçlık ve yazın aldığı staj ücreti; bir pansiyon için konuklardan aldığı oda ücretleri.","sektor":"Programın anahtar kavramlarındandır. Bütçe gelirle başlar: eline gerçekte ne kadar geçtiğini bilmeden neyi harcayabileceğini bilemezsin. Gelecekte seçeceğin mesleğin başlangıç gelirini araştırmak da bu yüzden önemlidir.","iliskili":["mg-10-003","mg-10-006","mg-10-012"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-003","konu":"10.1","terim":"Gider","ingilizce":"Expense","tanim":"Bir ihtiyacı ya da isteği karşılamak için harcanan paradır.","ornek":"Staja giden öğrencinin bir haftası: otobüs kartı dolumu, öğle yemeği, telefon faturası ve hafta sonu arkadaşlarıyla içtiği kahve.","sektor":"Programın anahtar kavramlarındandır. Tek başına yaşamaya başlayan çalışanın giderleri barınma, ulaşım, yemek ve faturalardan oluşur. Küçük giderler yazılmadığında fark edilmez; ay sonunda “Param nereye gitti?” sorusunun cevabı çoğu zaman onlardır.","iliskili":["mg-10-002","mg-10-007","mg-10-008"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-004","konu":"10.1","terim":"Zorunlu ihtiyaç","ingilizce":"Essential need","tanim":"Yaşamı, eğitimi ya da işi sürdürebilmek için mutlaka karşılanması gereken gereksinimdir.","ornek":"Staja başlayacak öğrencinin eskiyen üniforma ayakkabısını yenilemesi: ayakkabı olmadan vardiyaya çıkamaz.","sektor":"Bütçede önce zorunlu ihtiyaçlar yazılır: barınma, yemek, ulaşım, işin gerektirdiği kıyafet ve ekipman. İhtiyaç karşılanmadan isteğe para ayırmak ay sonunda borçla karşılaşmanın en kısa yoludur.","iliskili":["mg-10-005","mg-10-006","mg-10-003"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-005","konu":"10.1","terim":"İstek","ingilizce":"Want","tanim":"Olmadığında yaşamın ve işin aksamadığı, ama sahip olunduğunda kişiye keyif veren şeydir.","ornek":"Aynı ay içinde çok sevdiğin bir grubun konser bileti satışa çıkar; gitmek istersin, ama gitmesen de okulun ve stajın sürer.","sektor":"İstek kötü bir şey değildir; yalnızca sırası ihtiyaçtan sonradır. İhtiyaç ile istek arasındaki ayrımı kolaylaştıran soru şudur: “Bu olmazsa ne olur?” İşletmede de aynıdır: bozuk klimayı onarmak ihtiyaç, lobiye yeni bir süs havuzu istektir.","iliskili":["mg-10-004","mg-10-006","mg-10-009"],"kontrol":null},{"id":"mg-10-006","konu":"10.1","terim":"Bütçe","ingilizce":"Budget","tanim":"Belirli bir dönemde beklenen gelirin ve yapılacak giderlerin önceden yazılıp dengelendiği plandır.","ornek":"Ayda 1.000 TL harçlığı olan öğrenci yazar: 400 TL yol, 300 TL yemek, 100 TL telefon, 200 TL birikim. Toplam 1.000 TL eder; bütçe denktir.","sektor":"Programın anahtar kavramlarındandır. Gelir giderden çoksa bütçe fazla verir, azsa açık verir; açık ya birikimden ya borçtan kapanır. Otelde de her bölümün bir bütçesi vardır: kat hizmetleri temizlik malzemesine, mutfak yiyeceğe ne kadar harcayabileceğini önceden bilir.","iliskili":["mg-10-002","mg-10-003","mg-10-007","mg-10-008"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-007","konu":"10.1","terim":"Sabit gider","ingilizce":"Fixed expense","tanim":"Her dönem aşağı yukarı aynı tutarda ödenen ve kısa sürede değiştirilmesi zor olan giderdir.","ornek":"Öğrenci için aylık servis ücreti ve telefon tarifesi; bir pansiyon için binanın kirası.","sektor":"Pansiyon hiç konuk almasa da kira ödenir. Turizmde düşük sezonu zorlaştıran şey budur: gelir azalır, ama sabit giderler yerinde durur. İşe başlamadan önce sabit giderleri bilmek ayakta kalmak için en az ne kadar kazanman gerektiğini gösterir.","iliskili":["mg-10-008","mg-10-006","mg-10-028"],"kontrol":null},{"id":"mg-10-008","konu":"10.1","terim":"Değişken gider","ingilizce":"Variable expense","tanim":"Tutarı kullanıma ya da satış miktarına göre artıp azalan giderdir.","ornek":"Otelde dolu oda sayısı arttıkça çamaşırhaneye giden çarşaf, kahvaltıda tüketilen yiyecek ve odalarda harcanan su da artar.","sektor":"Kısılabilen giderler çoğunlukla bunlardır: kişisel bütçede dışarıda yemek, işletmede boşa yanan ışık. Tasarruf ararken önce değişken giderlere bakılır; sabit gideri değiştirmek daha uzun sürer.","iliskili":["mg-10-007","mg-10-009","mg-10-043"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-009","konu":"10.1","terim":"Tasarruf","ingilizce":"Saving (thrift)","tanim":"Kaynakları israf etmeden idareli kullanmak ve gelirin bir kısmını harcamayıp gelecek için ayırmaktır.","ornek":"Harçlığını alan öğrenci 200 TL’yi daha ilk gün kumbarasına koyar; ay boyunca kalan parayla yetinir.","sektor":"Programın anahtar kavramlarındandır. “Ay sonunda kalırsa biriktiririm” diyenin elinde çoğu zaman bir şey kalmaz; ayrılacak para ay başında ayrılır. Otelde tasarruf yalnız para değildir: boş odada kapatılan klima, ölçülü kullanılan temizlik malzemesi de tasarruftur.","iliskili":["mg-10-010","mg-10-011","mg-10-005"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-010","konu":"10.1","terim":"Birikim","ingilizce":"Savings","tanim":"Gelirin harcanmayıp gelecekteki hedefler için ayrılan bölümüdür; toplam gelirden toplam gider çıkarılınca kalan tutardır.","ornek":"Her ay 200 TL ayıran öğrencinin on ay sonunda elinde 2.000 TL olur; staj için gereken ayakkabıyı ve çantayı borçlanmadan alır.","sektor":"Programın anahtar kavramlarındandır. Sezonluk çalışan için birikim kışın maaşıdır: yazın kazanılanın bir bölümü, işin durduğu aylardaki kirayı ve faturayı öder. Bir gün kendi işini kurmak isteyenin öz kaynağı da birikimden doğar.","iliskili":["mg-10-009","mg-10-011","mg-10-019"],"kontrol":null,"gorsel":"sektor-kumbara"},{"id":"mg-10-012","konu":"10.1","terim":"Düzensiz gelir","ingilizce":"Irregular income","tanim":"Tutarı ve geliş zamanı aydan aya değişen, önceden kesin olarak bilinemeyen gelirdir.","ornek":"Sahil otelinde çalışan garsonun temmuzda aldığı bahşiş ile ekimde aldığı bahşiş aynı olmaz; kasımda otel kapanınca gelir tümüyle durabilir.","sektor":"Bahşiş ve sezonluk çalışma turizmin gerçeğidir. Geliri düzensiz olan kişi bütçesini en düşük aya göre kurar, iyi aylardaki fazlayı kenara koyar. Bahşişe güvenerek kira ya da taksit gibi sabit bir yük altına girmek risklidir.","iliskili":["mg-10-002","mg-10-010","mg-10-011"],"kontrol":null},{"id":"mg-10-013","konu":"10.1","terim":"Borç","ingilizce":"Debt","tanim":"Bir kişiden ya da kurumdan alınan ve belirli bir süre içinde geri verilmesi gereken para ya da değerdir.","ornek":"Arkadaşın oyun konsolu almak için senden 500 TL ister; verirsen o ayki birikimin sıfırlanacaktır. Karar vermeden önce kendi bütçene bakarsın.","sektor":"Borç, gelecekteki gelirini bugünden harcamaktır: geri ödeme her ay bütçende sabit bir gider olarak durur. İhtiyaç için ve ödeyebileceğin kadar borçlanmak ile istek için borçlanmak aynı şey değildir. Borç verirken de kural aynıdır: geri gelmese de seni zora sokmayacak kadar.","iliskili":["mg-10-051","mg-10-052","mg-10-006"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-014","konu":"10.1","terim":"Brüt ücret","ingilizce":"Gross pay","tanim":"Çalışanın emeği karşılığında hesaplanan, vergi ve sosyal güvenlik primi gibi yasal kesintiler yapılmadan önceki toplam ücrettir.","ornek":"Bir otelin iş ilanında “brüt ücret” yazar; ilanı okuyan aday eline geçecek tutarın bundan daha az olacağını bilir.","sektor":"İş görüşmesinde konuşulan rakamın brüt mü net mi olduğunu sormak hak aramak değil, profesyonelliktir. Bütçe brüt ücrete göre değil, ele geçen net ücrete göre yapılır.","iliskili":["mg-10-015","mg-10-016","mg-10-017"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-015","konu":"10.1","terim":"Net ücret","ingilizce":"Net pay (take-home pay)","tanim":"Yasal kesintiler brüt ücretten düşüldükten sonra çalışanın eline geçen tutardır.","ornek":"Ay sonunda banka hesabına yatan ve çalışanın kirasını, yol parasını, faturasını ödeyebildiği para net ücrettir.","sektor":"Kesilen para kaybolmaz: sosyal güvenlik primi çalışanın sağlık hizmeti ve emeklilik hakkı içindir, vergi kamu hizmetlerine gider. Kesinti oranları zamanla değişir; güncel durumu bordrodan ve resmî kaynaklardan öğrenirsin.","iliskili":["mg-10-014","mg-10-016","mg-10-006"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-016","konu":"10.1","terim":"Ücret bordrosu","ingilizce":"Payslip","tanim":"Çalışanın bir aylık ücretini, eklenen ödemeleri, yapılan kesintileri ve eline geçen net tutarı satır satır gösteren belgedir.","ornek":"İlk maaşını alan resepsiyon görevlisi bordrosunu açar: en üstte brüt ücret, ortada kesintiler, en altta hesabına yatan net tutar yazar.","sektor":"Bordro, emeğinin hesabıdır: çalışılan gün, fazla mesai ve kesintiler orada görünür. Okumadan bir kenara atılmaz. Anlamadığın bir satır olursa insan kaynaklarına ya da muhasebeye sormak en doğal hakkındır.","iliskili":["mg-10-014","mg-10-015","mg-10-017"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-017","konu":"10.1","terim":"Vergi (ücret ve fiyat hesabında)","ingilizce":"Tax","tanim":"Devletin yol, okul, hastane gibi kamu hizmetlerini karşılamak için kişilerden ve işletmelerden yasaya dayanarak aldığı paradır.","ornek":"Kafede aldığın fişin alt satırında KDV (katma değer vergisi) yazar: ödediğin tutarın bir bölümü işletmenin değil, devletindir.","sektor":"Programın anahtar kavramlarındandır. Vergi kazançtan, ücretten ve harcamadan alınır. Fiyatını hesaplarken vergiyi unutan işletmeci kâr sandığı paranın bir kısmının kendisine ait olmadığını sonradan öğrenir. Fiş ya da fatura kesmek de bu yüzden zorunludur.","iliskili":["mg-10-014","mg-10-024","mg-10-025"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-062","konu":"10.1","terim":"Gelir-gider dengesi","ingilizce":"Income–expenditure balance","tanim":"Bir kişinin ya da işletmenin belirli bir dönemde harcadığı paranın kazandığı parayı aşmayacak biçimde ayarlanmasıdır.","ornek":"Ayda belli bir harçlığı olan öğrenci yol, yemek ve telefon giderlerini harçlığının içinde tutarsa gelir-gider dengesini kurmuş olur.","sektor":"Harcama gelirden fazla çıkarsa ya borçlanılır ya da birikim erir; bütçe bu dengeyi önceden planlamanın aracıdır. İşletmede de aynı ilke geçerlidir: gider gelirin üstüne çıkarsa işletme zarar eder.","iliskili":["mg-10-002","mg-10-003","mg-10-006"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-046","konu":"10.1","terim":"Satın alma gücü","ingilizce":"Purchasing power","tanim":"Belirli bir miktar parayla satın alınabilen mal ve hizmet miktarıdır.","ornek":"Geçen yıl 1.000 TL harçlıkla ayda on öğle yemeği yiyebilen öğrenci, harçlığı aynı kalıp fiyatlar arttığında sekiz yemek yiyebilir.","sektor":"Cebindeki paranın rakamı değil, o parayla ne alabildiğin önemlidir. Fiyatlar gelirden hızlı artarsa satın alma gücü düşer. Uzun süre hiç değerlendirilmeden bekleyen birikim de bu yüzden zamanla değer kaybedebilir.","iliskili":["mg-10-045","mg-10-002","mg-10-054"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-047","konu":"10.1","terim":"Banka hesabı","ingilizce":"Bank account","tanim":"Kişinin ya da işletmenin parasını bankada güvenle sakladığı, ödeme ve para transferi yapabildiği kayıttır.","ornek":"Otel, çalışanlarının ücretini ay sonunda elden vermez; her çalışanın kendi adına açılmış hesabına yatırır.","sektor":"Paranın istendiği an çekilebildiği hesaba vadesiz, belirli bir süre bekletilmek üzere yatırıldığı hesaba vadeli hesap denir. Hesap hareketleri kayıt altındadır: “Ücretim yattı mı, ne kadar yattı?” sorusunun kanıtı oradadır. Hesap bilgileri ve şifre kimseyle paylaşılmaz.","iliskili":["mg-10-048","mg-10-015","mg-10-060"],"kontrol":null},{"id":"mg-10-048","konu":"10.1","terim":"Faiz","ingilizce":"Interest","tanim":"Borç alınan ya da bankaya yatırılan paranın belirli bir süre kullanılması karşılığında ödenen ya da alınan ek bedeldir.","ornek":"Hesap kolay olsun diye yıllık oran yüzde 10 diyelim: bankadan 1.000 TL borç alan kişi bir yıl sonra 1.100 TL geri öder; aradaki 100 TL faizdir.","sektor":"Borç alan için faiz bir giderdir, parasını yatıran için gelir. Oranlar sürekli değişir; bu yüzden karar verirken güncel oran ve geri ödenecek toplam tutar bankadan öğrenilir. Katılım bankaları faiz yerine kâr payı esasına göre çalışır.","iliskili":["mg-10-049","mg-10-050","mg-10-051"],"kontrol":null},{"id":"mg-10-049","konu":"10.1","terim":"Basit faiz","ingilizce":"Simple interest","tanim":"Her dönem yalnızca başlangıçtaki ana para üzerinden hesaplanan faizdir.","ornek":"Hesap kolay olsun diye oran yine yüzde 10 olsun: 1.000 TL, yıllık yüzde 10 basit faizle iki yıl bekler; her yıl 100 TL faiz işler, iki yılın sonunda toplam 1.200 TL olur.","sektor":"Basit faizde kazanç ya da borç her dönem aynı miktarda artar; hesap düz bir çizgi gibi ilerler. Bileşik faizle farkını bilmek bir borcun ya da birikimin zaman içinde nasıl büyüyeceğini görmeni sağlar.","iliskili":["mg-10-048","mg-10-050","mg-10-051"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-050","konu":"10.1","terim":"Bileşik faiz","ingilizce":"Compound interest","tanim":"Her dönemin faizinin ana paraya eklendiği ve sonraki dönemde bu toplam üzerinden yeniden faiz hesaplandığı yöntemdir.","ornek":"Aynı örnekteki oranla 1.000 TL, yıllık yüzde 10 bileşik faizle iki yıl bekler: ilk yıl 1.100 TL olur; ikinci yıl faiz 1.100 TL üzerinden hesaplanır ve toplam 1.210 TL’ye çıkar.","sektor":"Kısaca “faizin faizi”dir. Basit faizle aradaki fark ilk yıllarda küçüktür, süre uzadıkça açılır: yukarıdaki örnekte iki yılın sonunda 10 TL’dir. Aynı mantık iki yönde de işler: faizi ana paraya eklenen birikim de borç da her dönem biraz daha hızlı büyür.","iliskili":["mg-10-048","mg-10-049","mg-10-053"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-051","konu":"10.1","terim":"Kredi","ingilizce":"Loan","tanim":"Bankanın ya da finans kuruluşunun, belirli bir süre içinde faiziyle birlikte geri ödenmek üzere verdiği borç paradır.","ornek":"Pansiyon sahibi odaları yenilemek için bankadan kredi çeker ve borcunu iki yıl boyunca her ay eşit taksitlerle öder.","sektor":"Kredide bakılacak rakam yalnız aylık taksit değil, geri ödenecek toplam tutardır. Sözleşme imzalanmadan okunur: vade, taksit, gecikme hâlinde ne olacağı. Taksit, gelirin en düşük olduğu ayda bile ödenebilecek kadar olmalıdır.","iliskili":["mg-10-013","mg-10-020","mg-10-048"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-052","konu":"10.1","terim":"Kredi kartı","ingilizce":"Credit card","tanim":"Bankanın tanıdığı limit içinde önce harcama yapıp sonra ödemeye imkân veren ödeme aracıdır.","ornek":"Konuk, otelden ayrılırken hesabını kredi kartıyla öder; harcama o an kendi parasından değil, bankanın tanıdığı limitten düşer ve dönem sonunda hesap özetine yansır.","sektor":"Kredi kartıyla harcanan para kişinin kendi parası değil, kısa süreli borçtur. Hesap özetindeki borcun tamamı son ödeme tarihine kadar ödenirse kart bir ödeme kolaylığıdır; ödenmezse faizli borca dönüşür. Otelde konuğun kart bilgisi gizlidir; not alınmaz, kimseyle paylaşılmaz.","iliskili":["mg-10-053","mg-10-013","mg-10-048"],"kontrol":null,"gorsel":"m9-paying-with-a-credit"},{"id":"mg-10-053","konu":"10.1","terim":"Asgari ödeme tutarı","ingilizce":"Minimum payment","tanim":"Kredi kartı hesap özetinde, son ödeme tarihine kadar ödenmesi zorunlu olan en düşük tutardır.","ornek":"Hesap özetinde dönem borcu 3.000 TL, asgari ödeme 600 TL yazıyor. Yalnız 600 TL ödeyen kişinin 2.400 TL borcu sonraki aya kalır ve bu tutara faiz işler.","sektor":"“Asgariyi ödedim, borcum bitti” yanılgısı asgari ödeme tuzağı olarak bilinir. Asgari tutar yalnız gecikmeye düşmeyi önler; kalan borca faiz işlemeye devam eder ve her ay yeni harcama eklendikçe borç büyür. Kart, borcun tamamı ödenebilecek kadar kullanılır.","iliskili":["mg-10-052","mg-10-048","mg-10-013"],"kontrol":null,"kitapDisi":true,"cizim":"para-kart"},{"id":"mg-10-054","konu":"10.1","terim":"Yatırım","ingilizce":"Investment","tanim":"Parayı ya da başka bir kaynağı, gelecekte daha fazla değer ya da gelir sağlaması beklentisiyle bir işe ya da varlığa bağlamaktır.","ornek":"Pansiyon sahibi biriktirdiği parayla çatıya güneş enerjisi sistemi kurdurur; bugün para harcar, sonraki yıllarda elektrik faturası düşer.","sektor":"Programın anahtar kavramlarındandır. Yatırım yalnız para araçlarıyla yapılmaz: yabancı dil kursu, meslek sertifikası ve staj deneyimi de kişinin kendine yaptığı yatırımdır. Her yatırımda kazanma ihtimali kadar kaybetme ihtimali de vardır; nasıl işlediği anlaşılmayan bir şeye para bağlanmaz.","iliskili":["mg-10-055","mg-10-056","mg-10-031"],"kontrol":null,"gorsel":"mg-altin-yatirim"},{"id":"mg-10-058","konu":"10.1","terim":"Bireysel emeklilik sistemi","ingilizce":"Private pension scheme","tanim":"Kişinin çalışma yıllarında düzenli katkı payı ödeyerek emeklilik dönemi için uzun vadeli birikim yaptığı sistemdir.","ornek":"Otelde işe başlayan genç bir aşçı her ay ücretinin küçük bir bölümünü emeklilik hesabına ayırır; para yıllar boyunca birikir.","sektor":"Kısaca BES denir. Zorunlu sosyal güvenlik sisteminin yerini tutmaz, onu tamamlar. Uzun vadeli bir birikimdir: erken başlayanın biriktirmek için daha çok yılı olur. Sistemin koşulları zamanla değişir; güncel bilgi resmî kaynaklardan ve emeklilik şirketinden alınır.","iliskili":["mg-10-010","mg-10-050","mg-10-057"],"kontrol":null,"kitapDisi":true,"cizim":"ekip"},{"id":"mg-10-059","konu":"10.1","terim":"Finansal dolandırıcılık","ingilizce":"Financial fraud","tanim":"Bir kişiyi yalan, sahte belge ya da sahte kimlikle kandırarak parasını ya da hesap bilgilerini ele geçirme suçudur.","ornek":"Sosyal medyada gerçek bir otelin adını ve fotoğraflarını kullanan sahte bir sayfa “yarı fiyatına tatil” diyerek kapora ister; para gönderilince sayfa kapanır.","sektor":"Dolandırıcı acele ettirir, korkutur ya da büyük kazanç vadeder; amaç düşünmeye zaman bırakmamaktır. Turizmde sahte rezervasyon siteleri hem konuğu hem otelin adını zedeler. Şüpheli bir durumda işlem yapılmaz; aileye, bankaya ve gerekirse polise haber verilir.","iliskili":["mg-10-060","mg-10-055","mg-10-047"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-060","konu":"10.1","terim":"Sahte banka mesajı (oltalama)","ingilizce":"Phishing","tanim":"Banka ya da tanınmış bir kurumdan geliyormuş gibi görünen sahte mesaj, e-posta ya da internet sitesiyle kişinin şifresini ve kart bilgilerini çalma yöntemidir.","ornek":"Telefonuna bir mesaj gelir: “Hesabınız kapatılacak, hemen bu bağlantıya tıklayıp bilgilerinizi güncelleyin.” Bağlantı, bankanın sitesine çok benzeyen sahte bir sayfaya açılır.","sektor":"Banka, müşterisinden telefonda ya da mesajla kart şifresini ve SMS ile gelen onay kodunu istemez. Mesajdaki bağlantıya tıklanmaz; bankaya kendi resmî uygulamasından ya da kartın arkasındaki numaradan ulaşılır. Otelde de kural aynıdır: telefonda kendini “banka görevlisi” diye tanıtan kişiye bilgi verilmez, amire haber verilir.","iliskili":["mg-10-059","mg-10-047","mg-10-052"],"kontrol":null,"kitapDisi":true},{"id":"mg-10-065","konu":"10.1","terim":"Kişisel finans planlaması","ingilizce":"Personal financial planning","tanim":"Bir kişinin gelirini, giderini, birikimini ve borcunu hedeflerine göre önceden düzenlemesidir.","ornek":"Staj ücretini alacak öğrenci, eylül başında bir sayfaya yol, yemek ve telefon giderini yazar; kalan parayla kurs birikimi planlar.","sektor":"Bütçe yapmak, veri toplamak ve yol haritası çıkarmak bu planlamanın adımlarıdır.","iliskili":["mg-10-006","mg-10-001","mg-10-062","mg-10-077"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-066","konu":"10.1","terim":"Zorunlu gider","ingilizce":"Essential expense","tanim":"Temel ihtiyaçları karşılamak için mutlaka yapılması gereken harcamadır.","ornek":"Antalya’da stajyer olan bir öğrencinin ay başında ödediği kira, servis kartı ve elektrik faturası zorunlu giderdir.","sektor":"Bütçe yaparken önce zorunlu giderler yazılır, kalan para isteğe bağlı harcamalara ve birikime ayrılır.","iliskili":["mg-10-003","mg-10-067","mg-10-007","mg-10-004"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-067","konu":"10.1","terim":"İsteğe bağlı gider","ingilizce":"Discretionary expense","tanim":"Yaşam için zorunlu olmayan, ertelenebilen harcamadır.","ornek":"Maaş günü arkadaşlarla gidilen sinema ve atıştırmalık, ertelenebildiği için isteğe bağlı giderdir.","sektor":"Satın almadan önce “Bu gerçek bir ihtiyaç mı, yoksa yalnızca bir istek mi?” diye sormak bu gideri ayırt etmeye yardım eder.","iliskili":["mg-10-066","mg-10-005","mg-10-003","mg-10-008"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-068","konu":"10.1","terim":"Planlı borçlanma","ingilizce":"Planned borrowing","tanim":"Ödeme gücüne uygun olarak eğitim, mesleki gelişim ya da üretken bir yatırım için yapılan borçlanmadır.","ornek":"Meslek lisesi mezunu bir genç, her ay ödeyebileceği taksitle mutfak kursuna yazılır ve bu borcu bütçesine baştan ekler.","sektor":"Borç alırken amaç, geri ödeme koşulları ve ödeme gücü birlikte düşünülür.","iliskili":["mg-10-013","mg-10-069","mg-10-071","mg-10-051"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-069","konu":"10.1","terim":"Riskli borçlanma","ingilizce":"Risky borrowing","tanim":"Sosyal baskı, anlık istek ya da zorunlu olmayan harcamalar için yapılan ve kişinin gelirini aşan borçlanmadır.","ornek":"Arkadaşları alıyor diye pahalı bir telefonu gelirinin üstünde taksitle alan öğrenci her ay ödemeye yetişemez.","sektor":"Kredi kartı gelirin üstünde kullanıldığında bu tür borçlanmaya dönüşebilir.","iliskili":["mg-10-068","mg-10-052","mg-10-070","mg-10-071"],"kontrol":null,"cizim":"uyari"},{"id":"mg-10-070","konu":"10.1","terim":"Borç döngüsü","ingilizce":"Debt cycle","tanim":"Geliri aşan harcamalar ya da zamanında ödenmeyen borçlar yüzünden bütçenin sürekli zorlanmasıdır.","ornek":"Kredi kartı borcunun yalnız bir kısmını her ay ödeyen çalışan, kalan tutar büyüdükçe ay sonunu getiremez hâle gelir.","sektor":"Geliri aşan harcama ve zamanında ödenmeyen borç bu döngüyü başlatır.","iliskili":["mg-10-069","mg-10-053","mg-10-013","mg-10-071"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-071","konu":"10.1","terim":"Ödeme gücü","ingilizce":"Repayment capacity","tanim":"Kişinin geliri ve giderleri hesaba katıldığında borcunu zamanında ödeyebilme durumudur.","ornek":"Aylık geliri ve giderlerini hesaplayan bir çalışan, kalan parayı aşan bir taksiti ödeyemeyeceğini görüp daha ucuz bir ürüne yönelir.","sektor":"Borçlanmadan önce aylık gelirden giderler çıkarılır, kalan tutarın taksite yetip yetmediğine bakılır.","iliskili":["mg-10-068","mg-10-013","mg-10-062"],"kontrol":null,"cizim":"para-kart"},{"id":"mg-10-072","konu":"10.1","terim":"Maaş ve ücret","ingilizce":"Salary and wages","tanim":"Çalışanın verdiği emek karşılığında düzenli aldığı paradır.","ornek":"Bir otelde işe başlayan resepsiyon görevlisi her ay sonunda hesabına yatan maaşı ana geliri olarak kullanır.","sektor":"Çalışan için gelir maaş, ücret, prim, ticari kazanç ya da serbest çalışma geliri olabilir.","iliskili":["mg-10-002","mg-10-073","mg-10-014","mg-10-075"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-073","konu":"10.1","terim":"Prim","ingilizce":"Bonus","tanim":"Çalışana maaşın üstüne, başarısına ya da satışına bağlı olarak verilen ek ödemedir.","ornek":"Bir acentede çok sayıda tur satan satış elemanı, ay sonunda maaşına ek prim alır.","sektor":"Mesleği planlarken başlangıç maaşı ve prim imkânları önceden araştırılmalıdır.","iliskili":["mg-10-072","mg-10-002","mg-10-014"],"kontrol":null,"cizim":"trofe-odul"},{"id":"mg-10-074","konu":"10.1","terim":"Burs","ingilizce":"Scholarship","tanim":"Öğrencinin eğitim giderlerine destek olmak için kurum ya da kuruluşlarca verilen paradır.","ornek":"Başarılı bir meslek lisesi öğrencisi, okul yılı boyunca her ay hesabına yatan bursu kitap ve yol giderine ayırır.","sektor":"Öğrenci için gelir kaynaklarından biridir; harçlık ve aile desteğiyle birlikte bütçeye yazılır.","iliskili":["mg-10-002","mg-10-072","mg-10-076"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-075","konu":"10.1","terim":"Ticari kazanç","ingilizce":"Business income","tanim":"Kişinin kendi işinde mal ya da hizmet satarak elde ettiği gelirdir.","ornek":"Kendi küçük pansiyonunu işleten kişinin oda satışlarından elde ettiği para ticari kazançtır.","sektor":"Çalışanın gelir türlerinden biridir; maaşlı çalışmadan farklı olarak gelir satışa bağlıdır.","iliskili":["mg-10-072","mg-10-076","mg-10-002"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"mg-10-076","konu":"10.1","terim":"Serbest çalışma geliri","ingilizce":"Freelance income","tanim":"Kişinin bir işverene bağlı olmadan, yaptığı işe göre kazandığı gelirdir.","ornek":"Yaz sezonunda iş başına ücret alan bağımsız bir turist rehberinin kazancı serbest çalışma gelirdir.","sektor":"Çalışanın gelir türlerinden biridir; işler azaldığında gelir de düşebileceği için ayrıca birikim gerekir.","iliskili":["mg-10-075","mg-10-012","mg-10-072"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-077","konu":"10.1","terim":"Finansal yol haritası","ingilizce":"Financial roadmap","tanim":"Mesleki bir hedefe ulaşmak için maliyetin, sürenin, aylık ayrılacak paranın ve acil durum önlemlerinin yazıldığı plandır.","ornek":"Aşçılık kursuna yazılmak isteyen öğrenci, kurs ücretini ve kaç ayda biriktireceğini bir tabloya yazar.","sektor":"Hedefin maliyeti, süresi, aylık birikim ve tasarruf yöntemi bu haritada birleşir.","iliskili":["mg-10-065","mg-10-006","mg-10-009","mg-10-011"],"kontrol":null,"cizim":"harita-rota"},{"id":"mg-10-018","konu":"10.2","terim":"Başlangıç sermayesi","ingilizce":"Start-up capital","tanim":"Bir işi kurmak ve iş kendi gelirini kazanmaya başlayana kadar yürütmek için ortaya konan para, mal ve araçların toplamıdır.","ornek":"Kapadokya’da küçük bir pansiyon açmak isteyen girişimcinin biriktirdiği para, aileden kalan taş ev ve satın aldığı mobilyalar onun sermayesidir.","sektor":"Sermaye programın anahtar kavramlarındandır. Yalnız açılış gününe değil, işin kendi parasını kazanmaya başlayacağı güne kadar yetmelidir. İyi fikirlerin çoğu sermayesi ilk aylarda tükendiği için kapanır.","iliskili":["mg-10-019","mg-10-020","mg-10-021"],"kontrol":null},{"id":"mg-10-019","konu":"10.2","terim":"Öz kaynak","ingilizce":"Equity (own funds)","tanim":"İşletme sahibinin ya da ortakların işe kendi varlıklarından koyduğu, kimseye geri ödenmesi gerekmeyen kaynaktır.","ornek":"İki arkadaş bir kahvaltı kafesi açar: her biri yıllarca biriktirdiği paradan 100.000 TL koyar. Bu 200.000 TL işletmenin öz kaynağıdır.","sektor":"Öz kaynağın faizi ve taksiti yoktur; iş kötü giderse kaybedilen para girişimcinin kendi parasıdır. Öz kaynağı güçlü işletme, satışların düştüğü aylarda daha rahat nefes alır.","iliskili":["mg-10-018","mg-10-020","mg-10-010"],"kontrol":null},{"id":"mg-10-020","konu":"10.2","terim":"Yabancı kaynak","ingilizce":"Borrowed funds (debt financing)","tanim":"İşletmenin banka, tedarikçi ya da başka kişilerden borç olarak sağladığı ve geri ödemek zorunda olduğu kaynaktır.","ornek":"Kafe sahibi mutfak ekipmanı için bankadan kredi çeker, kahveyi de tedarikçiden “ay sonunda öderim” diyerek alır; ikisi de yabancı kaynaktır.","sektor":"Yabancı kaynak işi büyütür, ama geri ödeme yükü getirir: taksit, satış olsa da olmasa da ödenir. Sezonluk işletmede borcun taksitleri kış aylarına denk geliyorsa plan baştan ona göre yapılır.","iliskili":["mg-10-019","mg-10-051","mg-10-038"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-021","konu":"10.2","terim":"Yatırım maliyeti (başlangıç maliyeti)","ingilizce":"Start-up costs","tanim":"Bir iş daha ilk müşterisini karşılamadan önce, kuruluş için bir kez yapılan harcamaların toplamıdır.","ornek":"Kafe açacak girişimcinin listesi: dükkânın tadilatı, kahve makinesi, masa ve sandalyeler, tabela, ilk malzeme alımı, ruhsat işlemleri.","sektor":"Programda “yatırım maliyeti” adıyla geçer. Liste yazılmadan dükkân tutulmaz: unutulan her kalem sonradan borç olarak geri döner. Deneyimli girişimci, listenin sonuna beklenmedik harcamalar için bir pay da ekler.","iliskili":["mg-10-018","mg-10-022","mg-10-031"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-022","konu":"10.2","terim":"İşletme gideri","ingilizce":"Operating expenses","tanim":"İş açıldıktan sonra faaliyeti sürdürmek için her ay yinelenen harcamalardır.","ornek":"Açılışını yapan kafenin her ay karşısına çıkanlar: kira, personel ücretleri, elektrik ve su faturası, kahve ve süt alımı.","sektor":"Başlangıç maliyeti bir kez ödenir, işletme gideri her ay gelir. İş fikrini değerlendirirken ikisi ayrı ayrı hesaplanır; yalnız açılış parasını düşünen girişimci üçüncü ayda kirayı ödeyemez duruma düşebilir.","iliskili":["mg-10-021","mg-10-007","mg-10-008"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-023","konu":"10.2","terim":"Maliyet","ingilizce":"Cost","tanim":"Bir ürünü ya da hizmeti satışa hazır hâle getirmek için yapılan harcamaların toplamıdır.","ornek":"Bir otel odasının bir gecelik maliyeti: yıkanan çarşaf ve havlular, temizlik malzemesi, banyo ürünleri, kahvaltı, elektrik ve su, odayı hazırlayan personelin emeği.","sektor":"Programın anahtar kavramlarındandır. Maliyetini bilmeyen işletme fiyatını da bilemez: “Komşu otel kaça satıyorsa ben de o kadar” diyen, belki her satışta zarar ediyordur. Kırılan her bardak, boşa yanan her lamba maliyete eklenir.","iliskili":["mg-10-024","mg-10-025","mg-10-043"],"kontrol":null,"gorsel":"t12m-fis-yigini"},{"id":"mg-10-024","konu":"10.2","terim":"Satış fiyatı","ingilizce":"Selling price","tanim":"Bir ürün ya da hizmet için müşteriden istenen tutardır.","ornek":"Kafe bir kahvaltı tabağını 150 TL’ye hazırlıyorsa ve tabak başına 50 TL kazanmak istiyorsa fiyatı 200 TL olarak belirler.","sektor":"Fiyat uzun süre maliyetin altında kalamaz, yoksa her satış zarar yazar; üst sınırı ise müşterinin ödemeye razı olduğu tutar ve rakiplerin fiyatı belirler. Otelde aynı odanın fiyatı sezona ve doluluğa göre değişir: talep yüksekken fiyat artar, düşük sezonda iner.","iliskili":["mg-10-023","mg-10-025","mg-10-027"],"kontrol":null},{"id":"mg-10-027","konu":"10.2","terim":"Kâr marjı","ingilizce":"Profit margin","tanim":"Kârın satış gelirine oranını, yani satılan her 100 liranın kaç lirasının kâr olarak kaldığını gösteren ölçüdür.","ornek":"Bir kafe 100 TL’lik satıştan giderler çıktıktan sonra 20 TL kazanıyorsa kâr marjı yüzde 20’dir.","sektor":"Çok satmak her zaman çok kazanmak değildir: marjı düşük işletme büyük cirolarla bile az kâr eder. Programda iş fikrini değerlendirme ölçütlerinden biri “hedeflenen kâr marjı”dır; girişimci bu hedefi baştan koyar, sonuçla karşılaştırır.","iliskili":["mg-10-025","mg-10-024","mg-10-036"],"kontrol":null,"gorsel":"m9-percentage-chalkboard"},{"id":"mg-10-028","konu":"10.2","terim":"Başa baş hesabı","ingilizce":"Break-even analysis","tanim":"İşletmenin zarar etmemek için en az kaç satış yapması gerektiğini bulmak üzere, sabit giderlerin bir satışın bıraktığı paya bölünmesidir.","ornek":"Bir pansiyonun aylık sabit gideri 30.000 TL. Satılan her oda gecesi kendi masrafı çıktıktan sonra 600 TL bırakıyor. 30.000 ÷ 600 = 50: ayda 50 oda gecesi satılınca başa baş gelinir, 51. geceden itibaren her satış kâr bırakır.","sektor":"Toplam gelirin toplam gidere eşitlendiği, ne kâr ne zarar edilen satış düzeyine başa baş noktası denir. Hesap, girişimcinin en yalın sorusunu cevaplar: “En az kaç satış yapmalıyım ki zarar etmeyeyim?” Çıkan sayı pazarın verebileceğinden büyükse fikir bu hâliyle yürümez; fiyat, maliyet ya da sabit giderler yeniden düşünülür.","iliskili":["mg-10-007","mg-10-025","mg-10-030"],"kontrol":null,"cizim":"grafik"},{"id":"mg-10-029","konu":"10.2","terim":"Pazar büyüklüğü","ingilizce":"Market size","tanim":"Bir ürün ya da hizmeti belirli bir yerde ve sürede satın alabilecek müşterilerin sayısı ile yapabilecekleri toplam harcamadır.","ornek":"Sahil kasabasında kahvaltı kafesi açacak girişimci sayar: yazın gelen tatilciler, hafta sonu günübirlik gelenler ve kasabada yaşayanlar; bunların kaçı dışarıda kahvaltı eder?","sektor":"Pazar programın anahtar kavramlarındandır: alıcılarla satıcıların buluştuğu ortamdır. Programdaki “pazar potansiyeli” ölçütü, bu pazarın ne kadar büyük olduğuna ve ne kadar büyüyebileceğine bakar. İş fikrine başlamadan önce sorulur: Kime satacağım, bu kişiler kaç kişi, şu an bu ihtiyacı kimden karşılıyorlar? Pazar küçükse en iyi ürün bile yeterince satılmaz.","iliskili":["mg-10-030","mg-10-024","mg-10-032"],"kontrol":null},{"id":"mg-10-030","konu":"10.2","terim":"Satış hacmi","ingilizce":"Sales volume","tanim":"İşletmenin belirli bir dönemde sattığı ürün ya da hizmet miktarıdır.","ornek":"Bir kahvaltı kafesi geçen ay 1.200 kahvaltı tabağı sattı; bu sayı kafenin o ayki satış hacmidir. Kafe açılmadan önce ise girişimci sokağın başında durup cumartesi sabahı geçen kişileri ve çevredeki dolu masaları sayarak bu sayıyı tahmin etmeye çalışmıştı.","sektor":"Satış hacmi adetle, ciro ise parayla ölçülür. İş açılmadan önce satış hacmi ancak tahmin edilir (programda “potansiyel satış hacmi”); pazarın büyüklüğü bu hacmin çıkabileceği tavanı gösterir. Tahmin sayıma ve gözleme dayanmalıdır: “Herkes gelir” bir veri değildir. Başa baş için gereken satış pazarın verebileceğinin üstündeyse hesap tutmaz.","iliskili":["mg-10-029","mg-10-028","mg-10-032"],"kontrol":null},{"id":"mg-10-031","konu":"10.2","terim":"Yatırımın geri dönüş süresi","ingilizce":"Payback period","tanim":"Bir işe başlangıçta yatırılan paranın, işin kazandırdığı kârla geri kazanılması için geçmesi gereken süredir.","ornek":"Kafe için 600.000 TL harcandı; kafe yılda 200.000 TL kâr bırakıyor. 600.000 ÷ 200.000 = 3: yatırım üç yılda kendini geri öder.","sektor":"Programdaki üç değerlendirme ölçütünden biridir. Süre uzadıkça belirsizlik de artar: beş yıl sonra kira, rakipler, müşterinin zevki değişmiş olabilir. İki iş fikri karşılaştırılırken parasını daha kısa sürede geri veren genellikle daha az riskli sayılır.","iliskili":["mg-10-021","mg-10-025","mg-10-032"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-10-032","konu":"10.2","terim":"Finansal uygulanabilirlik","ingilizce":"Financial feasibility","tanim":"Bir iş fikrinin, gereken para ve beklenen kazanç hesaplanarak mali açıdan yapılabilir olup olmadığının araştırılmasıdır.","ornek":"Dört arkadaş kafe fikrini tek sayfaya döker: başlangıç maliyeti, aylık giderler, tahmini satış, başa baş noktası ve geri dönüş süresi. Sonuçta karar verirler: yapılır ya da bu hâliyle yapılmaz.","sektor":"Programın anahtar kavramlarındandır. Fizibilite heyecanı söndürmek için değil, parayı kaybetmeden önce yanlışı kâğıt üstünde görmek için yapılır. “Yapılmaz” sonucu da değerlidir: fikir değiştirilir, küçültülür ya da başka bir yere taşınır.","iliskili":["mg-10-028","mg-10-030","mg-10-031"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-033","konu":"10.2","terim":"Hibe ve destek","ingilizce":"Grants and support","tanim":"Kamu kurumlarının ya da çeşitli kuruluşların, şartları taşıyan girişimciye ya da işletmeye belirli bir amaç için sağladığı mali yardımdır.","ornek":"Genç bir girişimci köyündeki eski evi butik pansiyona çevirmek için bir destek programına proje dosyası hazırlayıp başvurur.","sektor":"Geri ödenmesi gerekmeyen desteğe hibe denir; bazı destekler ise uygun koşullu borç biçimindedir. Türkiye’de KOSGEB ve kalkınma ajansları gibi kurumlar girişimcilere destek verir. Programlar, şartlar ve tutarlar sık değişir: güncel bilgi yalnız kurumun resmî sitesinden alınır.","iliskili":["mg-10-018","mg-10-034","mg-10-035"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-10-034","konu":"10.2","terim":"Melek yatırımcı","ingilizce":"Angel investor (business angel)","tanim":"Yeni kurulan ve gelecek vadeden bir girişime kendi parasını koyan, karşılığında işletmeden ortaklık payı alan kişidir.","ornek":"Otellere çevrim içi rezervasyon yazılımı geliştiren üç genç fikirlerini deneyimli bir iş insanına sunar; o da sermaye koyarak şirkete ortak olur.","sektor":"Melek yatırımcı çoğu zaman yalnız para getirmez; deneyimini ve çevresini de paylaşır. Karşılığında işletmenin bir bölümünün sahibi olur ve kararlarda söz ister. Bu yüzden girişimci için hem kaynak hem ortaktır.","iliskili":["mg-10-019","mg-10-033","mg-10-035"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"mg-10-035","konu":"10.2","terim":"Kitle fonlaması","ingilizce":"Crowdfunding","tanim":"Bir proje ya da girişim için gereken paranın, internet üzerindeki bir platform aracılığıyla çok sayıda kişiden küçük tutarlar hâlinde toplanmasıdır.","ornek":"Bir köy pansiyonu projesi platformda tanıtılır; yüzlerce kişi küçük tutarlarla katkı verir ve karşılığında açılışta bir gece konaklama hakkı kazanır.","sektor":"Para toplamanın yanında bir pazar testidir: kimse ilgi göstermiyorsa fikir henüz hazır değildir. Destekçiye verilen söz tutulmak zorundadır. Destek verecek kişi de platformun yetkili ve güvenilir olduğunu kontrol eder.","iliskili":["mg-10-033","mg-10-034","mg-10-029"],"kontrol":null,"kitapDisi":true,"cizim":"girisim-isletme"},{"id":"mg-10-011","konu":"10.3","terim":"Acil durum fonu","ingilizce":"Emergency fund","tanim":"Beklenmedik bir gider ya da gelir kaybı için önceden ayrılan ve günlük harcamalarda kullanılmayan birikimdir.","ornek":"Sezon ortasında telefonu bozulan garson kenarda tuttuğu parayla tamir ettirir; kimseden borç istemez.","sektor":"Hastalık, arıza, sezonun erken kapanması önceden haber vermez. Kenarda birkaç aylık gideri karşılayacak para bulunması zor günde yüksek maliyetli borca girmeyi önler. İşletmeler de aynı mantıkla kârlarının bir bölümünü zor günler için ayırır; buna yedek akçe denir.","iliskili":["mg-10-010","mg-10-012","mg-10-013"],"kontrol":null,"kitapDisi":true,"gorsel":"mg-kumbara"},{"id":"mg-10-025","konu":"10.3","terim":"Kâr","ingilizce":"Profit","tanim":"Belirli bir dönemde elde edilen gelirin, o dönemdeki giderlerden fazla olan kısmıdır.","ornek":"Küçük bir pansiyon bir ayda 80.000 TL gelir elde eder, 60.000 TL gider yapar; aradaki 20.000 TL o ayın kârıdır.","sektor":"Programın anahtar kavramlarındandır. Kâr, işletmenin yaşamını sürdürmesini sağlar: personelin ücreti, yenileme, büyüme oradan çıkar. Kasaya giren paranın tamamı kâr değildir; önce giderler düşülür.","iliskili":["mg-10-026","mg-10-027","mg-10-036"],"kontrol":null,"gorsel":"m9-stack-of-coins-0214"},{"id":"mg-10-026","konu":"10.3","terim":"Zarar","ingilizce":"Loss","tanim":"Belirli bir dönemde giderlerin geliri aşan kısmıdır.","ornek":"Aynı pansiyon kasım ayında 30.000 TL gelir elde eder, giderleri ise 50.000 TL tutar; o ayı 20.000 TL zararla kapatır.","sektor":"Programın anahtar kavramlarındandır. Sezonluk işte bazı ayların zararla kapanması olağandır; önemli olan yılın bütünüdür. Üst üste gelen zarar ise bir uyarıdır: fiyat mı düşük, maliyet mi yüksek, müşteri mi az, nedeni aranır.","iliskili":["mg-10-025","mg-10-028","mg-10-042"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-10-036","konu":"10.3","terim":"Ciro","ingilizce":"Turnover","tanim":"İşletmenin belirli bir dönemde yaptığı satışların toplam tutarıdır.","ornek":"Bir kafe gün içinde 100 kahvaltı tabağını tanesi 200 TL’den satar; o günün cirosu 20.000 TL’dir.","sektor":"Programın anahtar kavramlarındandır. Ciro kâr değildir: kasaya giren paradan malzeme, kira, ücret ve vergi çıkar. “Bugün çok satış yaptık” demek “Bugün çok kazandık” demek için yeterli değildir.","iliskili":["mg-10-025","mg-10-027","mg-10-037"],"kontrol":null},{"id":"mg-10-037","konu":"10.3","terim":"Gelir akışı","ingilizce":"Revenue stream","tanim":"İşletmeye para kazandıran kaynakların her biridir.","ornek":"Bir tatil otelinin gelir akışları: oda satışı, restoran ve bar, spa, toplantı salonu kiralama, çamaşır yıkama hizmeti.","sektor":"Programın anahtar kavramlarındandır. Tek gelir akışına bağlı işletme kırılgandır: yalnız yaz aylarında oda satan otel kışın kapanır. Toplantı, düğün ya da restoran gibi ek akışlar düşük sezonda işletmeyi ayakta tutar.","iliskili":["mg-10-036","mg-10-038","mg-10-042"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-038","konu":"10.3","terim":"Nakit akışı yönetimi","ingilizce":"Cash flow management","tanim":"İşletmeye giren ve işletmeden çıkan paranın zamanını izleyerek ödeme günlerinde kasada yeterli para bulunmasını sağlama çalışmasıdır.","ornek":"Bir acente eylülde büyük bir grubun turunu düzenler, ama parasını kasımda alacaktır; otobüs firmasına ve rehbere ise ekimde ödeme yapması gerekir.","sektor":"Nakit akışı, yani paranın işletmeye giriş ve çıkış hareketi, programın anahtar kavramlarındandır. Kâğıt üzerinde kârlı bir işletme bile ödeme günü kasasında para yoksa zor duruma düşer. Bu yüzden yalnız “Ne kadar kazandık?” değil, “Para ne zaman giriyor, ne zaman çıkıyor?” sorusu da izlenir.","iliskili":["mg-10-025","mg-10-039","mg-10-041"],"kontrol":null},{"id":"mg-10-039","konu":"10.3","terim":"Gelir tablosu","ingilizce":"Income statement (profit and loss account)","tanim":"İşletmenin belirli bir dönemdeki gelirlerini, giderlerini ve bunların sonucunda oluşan kâr ya da zararı alt alta gösteren tablodur.","ornek":"Pansiyon sahibi ay sonunda yazar: en üste oda gelirleri, altına kira, ücret, fatura ve malzeme giderleri; en alt satırda o ayın kârı ya da zararı çıkar.","sektor":"Bir çeşit karnedir: işletmenin o dönemi nasıl geçirdiğini tek bakışta gösterir. Aylar yan yana konduğunda hangi giderin büyüdüğü, hangi gelirin azaldığı görülür; düzeltme kararı buna dayanır.","iliskili":["mg-10-025","mg-10-026","mg-10-038"],"kontrol":null},{"id":"mg-10-040","konu":"10.3","terim":"Amortisman","ingilizce":"Depreciation","tanim":"Uzun süre kullanılan bir varlığın, kullanıldıkça ve eskidikçe azalan değerinin kullanım ömrüne bölünerek her yıl gider sayılmasıdır.","ornek":"Otel çamaşırhanesine 100.000 TL’ye bir yıkama makinesi alınır ve beş yıl kullanılması beklenir; her yıl 20.000 TL’si o yılın gideri olarak yazılır.","sektor":"Programın anahtar kavramlarındandır. Yatak, klima, mutfak fırını sonsuza kadar dayanmaz. Eskimeyi her yıl hesaba katan işletme, yenileme günü geldiğinde hazırlıklıdır; katmayan işletme o yıllarda olduğundan kârlı görünür.","iliskili":["mg-10-021","mg-10-023","mg-10-039"],"kontrol":null},{"id":"mg-10-041","konu":"10.3","terim":"Finansal plan","ingilizce":"Financial plan","tanim":"Bir kişinin ya da işletmenin hedeflerine ulaşmak için gelirini, giderini, birikimini, borcunu ve olası risklerini belirli bir süre için önceden düzenlediği yol haritasıdır.","ornek":"Pansiyon sahibi gelecek yılı ay ay yazar: hangi ay ne kadar gelir bekliyor, hangi ay hangi ödeme var, çatı onarımı için parayı hangi aylarda ayıracak.","sektor":"İyi plan tek bir geleceğe göre yazılmaz: “Sezon iyi geçerse, orta geçerse, kötü geçerse” diye üç olasılık düşünülür. Plan dosyada durmaz; gerçekleşenle karşılaştırılır ve koşullar değiştikçe güncellenir.","iliskili":["mg-10-006","mg-10-038","mg-10-042"],"kontrol":null},{"id":"mg-10-042","konu":"10.3","terim":"İşletme riski","ingilizce":"Business risk","tanim":"İşletmenin gelirini azaltabilecek ya da giderini artırabilecek, içeriden ya da dışarıdan kaynaklanan olumsuz olay ihtimalidir.","ornek":"Bir otel için iç risk: deneyimli personelin sezon ortasında ayrılması. Dış risk: kötü hava nedeniyle uçuşların iptal olması ve rezervasyonların düşmesi.","sektor":"İç riskler işletmenin kendi yapısından doğar ve önlem alınabilir: eğitim, bakım, düzenli kayıt. Dış riskler denetlenemez, ama hazırlık yapılabilir: birikim, sigorta, birden çok gelir akışı. Programda sorunun nedenlerini bulmak için balık kılçığı diyagramı kullanılır.","iliskili":["mg-10-044","mg-10-057","mg-10-037"],"kontrol":null,"gorsel":"f3d-selde-su-altinda-otel"},{"id":"mg-10-043","konu":"10.3","terim":"Maliyet yönetimi","ingilizce":"Cost management","tanim":"Ürün ya da hizmetin kalitesini düşürmeden giderleri izleme, israfı azaltma ve kaynakları verimli kullanma çalışmasıdır.","ornek":"Otel mutfağında şef açık büfeden her gün artan yemekleri bir hafta boyunca tartar ve ertesi haftanın üretim miktarını buna göre ayarlar.","sektor":"Maliyeti düşürmek, konuğun aldığı hizmeti kısmak değildir: havluyu inceltmek konuğu kaybettirir, boş odadaki klimayı kapatmak kimseyi kaybettirmez. İsraf edilmeyen her kaynak doğrudan kâra eklenir; bu iş yalnız müdürün değil, her çalışanın elindedir.","iliskili":["mg-10-023","mg-10-008","mg-10-009"],"kontrol":null},{"id":"mg-10-061","konu":"10.3","terim":"Finansal kurtarma stratejisi","ingilizce":"Financial turnaround strategy","tanim":"Zarar eden ya da nakit sıkıntısı çeken bir işletmenin maliyetlerini yöneterek, verimliliğini artırarak ve riske karşı önlem alarak yeniden kârlı ve ayakta kalır hâle gelmesini amaçlayan plandır.","ornek":"Düşük sezonda doluluğu azalan küçük bir pansiyon, kullanılmayan katı kapatıp enerji giderini düşürür, sezon dışı indirimli paketlerle gelir akışı yaratır ve riskine karşı sigorta yaptırır.","sektor":"Kitaba göre kurtarma planı üç alanı birleştirir: maliyet yönetimi, verimlilik artırma ve risk yönetimi. Stratejiler uygulanabilirlik, kârı artırma ve riski azaltma ölçütlerine göre karşılaştırılır; sigorta gibi riski devretme yolları performans görevinde “risk transferi” diye geçer.","iliskili":["mg-10-043","mg-10-057","mg-10-041"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-063","konu":"10.3","terim":"Yardımseverlik","ingilizce":"Charitable giving (benevolence)","tanim":"Kişinin ya da işletmenin sahip olduğu bilgi, deneyim, eşya veya parayı karşılık beklemeden ihtiyaç sahipleriyle paylaşmasıdır.","ornek":"Haziran sonunda yenileme yapan bir otel, çıkan sağlam ve temiz havlu ile çarşafları bir köy okuluna bağışlar.","sektor":"Yardımseverlik değerlidir ama ölçülü olmalıdır: işletme kendi ayakta kalmasını tehlikeye atmadan, imkânı ölçüsünde katkı verir. Bu nedenle finansal planın ve sürdürülebilirliğin bir parçası sayılır.","iliskili":["mg-10-041","mg-10-043"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-10-064","konu":"10.3","terim":"Büyüme hedefi","ingilizce":"Growth target","tanim":"İşletmenin gelecekte konuk sayısı, gelir ya da şube gibi alanlarda ne kadar büyümeyi planladığını belirten hedeftir.","ornek":"Küçük bir pansiyon, önümüzdeki iki sezonda odalarının bir bölümünü yenileyip yaz dışındaki doluluğu artırmayı hedefler.","sektor":"Büyüme hedefi finansal plana yön verir; ancak hedef işletmenin verileriyle, riskleriyle ve ekonomik dengesiyle uyumlu değilse gerçekçi olmaz ve plan çöker.","iliskili":["mg-10-041","mg-10-042","mg-10-061"],"kontrol":null,"cizim":"grafik"},{"id":"mg-10-044","konu":"10.3","terim":"Finansal risk","ingilizce":"Financial risk","tanim":"Parayla ilgili bir kararın beklenenden farklı sonuçlanması ve kişinin ya da işletmenin para kaybetmesi olasılığıdır.","ornek":"Yaz boyunca bahşişine güvenerek pahalı bir telefonu taksitle alan garson sezon erken kapanınca kalan taksitleri ödemekte zorlanır.","sektor":"Programın anahtar kavramlarındandır. Risk sıfırlanamaz, yönetilir: karar vermeden önce “En kötü ne olur, olursa karşılayabilir miyim?” diye sorulur. Cevap “hayır” ise karar küçültülür ya da ertelenir.","iliskili":["mg-10-042","mg-10-055","mg-10-057"],"kontrol":null,"gorsel":"m9-market-centre-in-tokyo"},{"id":"mg-10-045","konu":"10.3","terim":"Enflasyon","ingilizce":"Inflation","tanim":"Mal ve hizmet fiyatlarının genel düzeyinin sürekli olarak yükselmesidir.","ornek":"Geçen yıl 100 TL’ye doldurduğun market sepeti için bu yıl aynı ürünlere 120 TL ödüyorsan fiyatlar genel olarak artmış demektir.","sektor":"Tek bir ürünün zamlanması enflasyon değildir; fiyatların genelinin artmasıdır. İşletmeyi iki yandan etkiler: malzeme, enerji ve ücret maliyeti artar; fiyatı yükseltince de konuğun bütçesi zorlanır. Finansal plan yapılırken bugünün fiyatlarının aynı kalmayacağı hesaba katılır.","iliskili":["mg-10-046","mg-10-041","mg-10-023"],"kontrol":null},{"id":"mg-10-055","konu":"10.3","terim":"Risk-getiri ilişkisi","ingilizce":"Risk–return trade-off","tanim":"Bir yatırımdan beklenen kazanç yükseldikçe para kaybetme olasılığının da yükselmesini anlatan temel ilişkidir.","ornek":"Biri sana “Bir ayda paranı ikiye katlarım, hiç riski yok” diyorsa bu söz bu ilişkiyle çelişir: yüksek kazanç ile sıfır risk aynı teklifte bir arada bulunmaz.","sektor":"Getiri, yatırımın sağladığı kazançtır. “Garantili yüksek kazanç” vaadi bir fırsat değil, uyarı işaretidir. Sağlıklı karar için önce şu sorulur: Bu parayı kaybedersem yaşamım ya da işim ne kadar etkilenir?","iliskili":["mg-10-054","mg-10-056","mg-10-059"],"kontrol":null,"cizim":"uyari"},{"id":"mg-10-056","konu":"10.3","terim":"Çeşitlendirme","ingilizce":"Diversification","tanim":"Paranın ya da gelirin tek bir kaynağa bağlanmayıp birden çok farklı kaynağa bölünerek riskin azaltılmasıdır.","ornek":"Yalnız yaz aylarında tek bir ülkeden gelen turistlere çalışan otel o pazarda sorun çıkınca boş kalır; farklı ülkelerden ve farklı aylarda konuk ağırlayan otel daha az etkilenir.","sektor":"“Bütün yumurtaları aynı sepete koymamak” sözüyle anlatılır. Riski ortadan kaldırmaz, yayar: bir kaynak zarar ettiğinde ötekiler dengeyi korur. İşletmede birden çok gelir akışı kurmak da aynı düşüncenin ürünüdür.","iliskili":["mg-10-054","mg-10-055","mg-10-037"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"mg-10-057","konu":"10.3","terim":"Sigorta","ingilizce":"Insurance","tanim":"Prim adı verilen bir bedel karşılığında, belirli bir riskin doğuracağı zararın sigorta şirketince karşılanmasını sağlayan sözleşmedir.","ornek":"Pansiyon sahibi her yıl yangın ve su baskınına karşı sigorta primi öder; mutfakta yangın çıktığında onarım masrafını poliçedeki şartlar ölçüsünde sigorta şirketi karşılar.","sektor":"Programdaki “risk transferi”nin en bilinen yoludur: işletme küçük ve belli bir bedel ödeyerek büyük ve belirsiz bir zararı başkasına devreder. Sözleşmenin yazılı hâline poliçe denir; neyin kapsandığı, neyin kapsanmadığı orada yazar ve imzalamadan önce okunur.","iliskili":["mg-10-042","mg-10-044","mg-10-058"],"kontrol":null,"cizim":"sigorta-semsiye"},{"id":"mg-10-083","konu":"10.3","terim":"Nakit girişi","ingilizce":"Cash inflow","tanim":"İşletmenin kasasına giren paradır.","ornek":"Bir kafenin gün sonunda kasaya aldığı peşin satış bedelleri nakit girişidir.","sektor":"Nakit akışının giriş yönüdür; para tahsil edildiğinde oluşur, satış yapıldığında değil.","iliskili":["mg-10-084","mg-10-036"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-084","konu":"10.3","terim":"Nakit çıkışı","ingilizce":"Cash outflow","tanim":"İşletmenin yaptığı ödemelerle kasasından çıkan paradır.","ornek":"Kafenin ay sonunda ödediği kira, personel ücreti ve malzeme bedeli nakit çıkışıdır.","sektor":"Nakit akışının çıkış yönüdür; kira, ücret ve fatura gibi ödemeler buraya girer.","iliskili":["mg-10-083","mg-10-086","mg-10-022"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-085","konu":"10.3","terim":"Vadeli alacak","ingilizce":"Accounts receivable","tanim":"İşletmenin sattığı mal ya da hizmetin bedelini daha sonra tahsil edeceği paradır.","ornek":"Bir otel, şirketin toplantısı için fatura keser ama parayı ay sonunda alır; bu para vadeli alacaktır.","sektor":"Satış yapılmış ama para tahsil edilmemişse işletme nakit sıkıntısı yaşayabilir.","iliskili":["mg-10-086","mg-10-038"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-086","konu":"10.3","terim":"Kısa vadeli borç","ingilizce":"Short-term debt","tanim":"İşletmenin kısa süre, örneğin bir ay içinde ödemesi gereken borçtur.","ornek":"Kafenin bu ay içinde tedarikçiye ödemesi gereken kahve ve süt bedeli kısa vadeli borçtur.","sektor":"Kasadaki para kısa vadeli borca yetmiyorsa işletme risk altındadır.","iliskili":["mg-10-085","mg-10-042"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-10-087","konu":"10.3","terim":"İç risk","ingilizce":"Internal risk","tanim":"İşletmenin kendi yapısından ve yönetiminden doğan risklerdir.","ornek":"Bir otelde personel eğitiminin eksik olması, hatalı hizmetle konuk kaybına yol açabilir.","sektor":"Riskler iç ve dış olarak ayrılır; iç riskler yönetim sorunlarıyla bağlantılıdır.","iliskili":["mg-10-088","mg-10-042","mg-10-090"],"kontrol":null,"cizim":"uyari"},{"id":"mg-10-088","konu":"10.3","terim":"Dış risk","ingilizce":"External risk","tanim":"İşletmenin dışındaki ekonomik ve çevresel değişikliklerden doğan risklerdir.","ornek":"Bölgeye yeni rakip otellerin açılması ya da hammadde fiyatlarının aniden artması dış risktir.","sektor":"Dış çevreden gelen ekonomik değişiklikler nakit akışını bozabilir.","iliskili":["mg-10-087","mg-10-042","mg-10-045","mg-10-090"],"kontrol":null,"cizim":"uyari"},{"id":"mg-10-089","konu":"10.3","terim":"Verimlilik artırma","ingilizce":"Productivity improvement","tanim":"Eldeki sermaye, zaman, araç gereç ve iş gücünden en çok faydayı sağlamaktır.","ornek":"Bir otel, kat görevlilerinin oda temizleme sırasını düzenleyerek aynı sürede daha çok oda hazırlar.","sektor":"Aynı kaynaklarla daha fazla ve nitelikli çıktı alan işletmenin mali gücü artar.","iliskili":["mg-10-043","mg-10-061","mg-10-092"],"kontrol":null,"cizim":"enerji"},{"id":"mg-10-090","konu":"10.3","terim":"Finansal risk yönetimi","ingilizce":"Risk management","tanim":"Beklenmedik krizlere karşı önlem almaktır.","ornek":"Bir pansiyon, satışların düştüğü aylar için kâr payını acil durum fonuna ayırır.","sektor":"İşletmeyi birkaç ay ayakta tutabilecek acil durum fonu bu stratejinin parçasıdır.","iliskili":["mg-10-042","mg-10-011","mg-10-091","mg-10-061"],"kontrol":null,"cizim":"uyari"},{"id":"mg-10-091","konu":"10.3","terim":"Risk transferi","ingilizce":"Risk transfer","tanim":"İşletmenin bir riskin zararını başkasına devrederek kendi yükünü azaltmasıdır.","ornek":"Bir otel, yangın zararını karşılasın diye sigorta poliçesi yaptırır.","sektor":"Sigorta, riski başkasına devretmenin yaygın bir yoludur.","iliskili":["mg-10-090","mg-10-057","mg-10-042"],"kontrol":null,"cizim":"otobus"},{"id":"mg-10-092","konu":"10.3","terim":"Finansal sürdürülebilirlik","ingilizce":"Financial sustainability","tanim":"İşletmenin gelir, gider, nakit akışı, borç ve riskleri dengede yöneterek uzun süre ayakta kalabilmesidir.","ornek":"Yılın her ayında kirasını ve ücretlerini ödeyebilen bir pansiyon finansal olarak sürdürülebilirdir.","sektor":"Sürdürülebilirlik yalnız kâr elde etmekle sınırlı değildir.","iliskili":["mg-10-041","mg-10-061","mg-10-038","mg-10-089"],"kontrol":null,"cizim":"doga"}],"sorular":[{"id":"mg-10-s01","tur":"coktan-secmeli","soru":"Zeynep staja başlamadan önce, alacağı ücreti yol, yemek ve birikime nasıl böleceğini bir sayfaya yazdı. Bu sayfa hangisidir?","secenekler":["Ücret bordrosu","Bütçe","Gelir tablosu","Nakit çıkışı"],"dogru":1,"aciklama":"Bütçe, henüz harcama yapılmadan önce gelir ve giderlerin yazılıp dengelendiği plandır. Gelir tablosu geçmiş bir dönemin sonucunu gösterir; ücret bordrosunu ise işveren hazırlar."},{"id":"mg-10-s02","tur":"coktan-secmeli","soru":"Düşük sezonda doluluk azaldı. Pansiyon binanın kirasını aynı tutarda ödemeye devam ediyor, çamaşırhaneye giden çarşaf ise azaldı. Hangisi doğrudur?","secenekler":["Kira değişken, çarşaf gideri sabit gider","İkisi de sabit gider sayılır","İkisi de değişken gider sayılır","Kira sabit, çarşaf gideri değişken gider"],"dogru":3,"aciklama":"Sabit gider satış değişse de aşağı yukarı aynı kalır (kira); değişken gider satışla birlikte artıp azalır (çarşaf, yiyecek, su). Düşük sezonu zorlaştıran da budur: gelir azalır, kira yerinde durur."},{"id":"mg-10-s03","tur":"coktan-secmeli","soru":"Bir stajyerin ay içinde iki harcaması var: eskiyen üniforma ayakkabısını yenilemek ve sevdiği grubun konser bileti. Hangi sınıflandırma doğrudur?","secenekler":["Ayakkabı zorunlu ihtiyaç, konser bileti istektir","Ayakkabı istek, konser bileti zorunlu ihtiyaçtır","İkisi de zorunlu ihtiyaç sayılır","İkisi de istek sayılır"],"dogru":0,"aciklama":"Ayakkabı olmadan vardiyaya çıkılamaz, yani karşılanması zorunludur. Konser olmasa da okul ve staj sürer; bu bir istektir ve bütçede ihtiyaçlardan sonra gelir."},{"id":"mg-10-s04","tur":"coktan-secmeli","soru":"İş ilanında ücret “brüt” olarak yazıyor. Aday, hesabına yatacak tutarı bulmak istiyor. Ne yapmalıdır?","secenekler":["Vergi ve primi tutara eklemelidir","Tutarı olduğu gibi bütçesine yazmalıdır","Yasal kesintileri tutardan çıkarmalıdır","Bordrodaki ilk satırı esas almalıdır"],"dogru":2,"aciklama":"Net ücret, brüt ücretten vergi ve sosyal güvenlik primi gibi yasal kesintiler düşülerek bulunur. Bütçe de eline geçecek net tutara göre kurulur; brüt tutara göre kurulan bütçe ay sonunda açık verir."},{"id":"mg-10-s05","tur":"coktan-secmeli","soru":"Sezonluk çalışan bir garsonun bahşiş geliri aydan aya değişiyor. Bütçesini kurarken hangisi en sağlıklı yoldur?","secenekler":["En çok bahşiş aldığı ayı esas alıp bütçeyi ona göre kurmak","En az bahşiş aldığı ayı esas alıp fazlayı birikime ayırmak","Bahşişi geldiği gün harcayıp ay sonunda bütçeyi yenilemek","Bahşiş arttıkça sabit giderlerini de yukarı çekmek"],"dogru":1,"aciklama":"Düzensiz gelirde bütçe en düşük aya göre kurulur, iyi aylardaki fazla kenara konur. En yüksek aya göre kurulan bütçe, sezon bitince ödenemeyen sabit giderlere yol açar."},{"id":"mg-10-s06","tur":"coktan-secmeli","soru":"Üç arkadaş kafe açarken her biri 50.000 TL koyuyor, mutfak ekipmanı için de bankadan kredi çekiyor. Hangisi doğrudur?","secenekler":["Koydukları para öz kaynak, kredi yabancı kaynaktır","Koydukları para yabancı kaynak, kredi öz kaynaktır","İkisi de kafeye girdiği için öz kaynaktır","İkisi de ödenmesi gerektiği için yabancı kaynaktır"],"dogru":0,"aciklama":"Sahiplerin kendi varlıklarından koyduğu para öz kaynaktır ve kimseye geri ödenmez. Banka kredisi borçtur, faiziyle geri ödenir; yani yabancı kaynaktır."},{"id":"mg-10-s07","tur":"coktan-secmeli","soru":"Bir pansiyonun aylık sabit gideri 24.000 TL. Satılan her oda gecesi kendi masrafı çıktıktan sonra 600 TL bırakıyor. Zarar etmemek için ayda en az kaç oda gecesi satmalıdır?","secenekler":["24","36","48","40"],"dogru":3,"aciklama":"Başa baş noktası sabit gider ÷ her satışın bıraktığı pay ile bulunur: 24.000 ÷ 600 = 40. Kırk gecede sabit giderler çıkar; 36 gecede ise 2.400 TL eksik kalır."},{"id":"mg-10-s08","tur":"coktan-secmeli","soru":"İki kafenin bir aylık cirosu 100.000 TL. Giderlerden sonra A kafesi 30.000 TL, B kafesi 10.000 TL kazanıyor. Hangisi doğrudur?","secenekler":["Cirolar eşit olduğu için kârlılıkları da eşittir","B kafesinin kâr marjı daha yüksektir","A kafesinin kâr marjı yüzde 30, B’ninki yüzde 10’dur","A kafesinin kâr marjı yüzde 3, B’ninki yüzde 1’dir"],"dogru":2,"aciklama":"Kâr marjı kârın satış gelirine oranıdır: 30.000 ÷ 100.000 = yüzde 30, 10.000 ÷ 100.000 = yüzde 10. Ciro eşit olsa da kâr farklı olabilir; çünkü ciro giderlerden önceki toplamdır."},{"id":"mg-10-s09","tur":"coktan-secmeli","soru":"Genç bir girişimci köydeki eski evi butik pansiyona çevirmek için bir destek programına başvuruyor. Şartları sağlarsa ne ortaklık payı verecek ne de parayı geri ödeyecek. Bu kaynak hangisidir?","secenekler":["Banka kredisi","Melek yatırımcı ortaklığı","Hibe","Kitle fonlaması"],"dogru":2,"aciklama":"Hibe, şartları taşıyan girişimciye verilen ve geri istenmeyen mali destektir. Kredi faiziyle geri ödenir; melek yatırımcı karşılığında ortaklık payı alır; kitle fonlamasında katkı verenlere genellikle bir karşılık sözü verilir."},{"id":"mg-10-s10","tur":"coktan-secmeli","soru":"Ciro ve kâr hakkında aşağıdakilerden hangisi yanlıştır?","secenekler":["Ciro yüksek olan işletme o dönemi mutlaka kârla kapatır","Ciro, giderler düşülmeden önceki toplam satış tutarıdır","Kâr, gelirin giderlerden fazla olan kısmıdır","Giderler geliri aşarsa işletme zarar etmiş olur"],"dogru":0,"aciklama":"Ciro yalnız satışların toplamıdır; kira, ücret, malzeme gibi giderler bu tutardan çıkar. Gider ciroyu aşıyorsa işletme çok satmış olsa bile zarar eder."},{"id":"mg-10-s11","tur":"coktan-secmeli","soru":"Bir acente büyük bir grubun turunu eylülde düzenledi, parasını kasımda alacak. Otobüs firmasına ise ekimde ödeme yapması gerekiyor. Defterde kârlı olmasına rağmen ekimde zorlanmasının nedeni hangisidir?","secenekler":["Satış fiyatını rakiplerden düşük belirlemesi","Amortisman giderinin çok yüksek olması","Kâr marjının sıfıra yakın olması","Para giriş ve çıkış zamanının uyuşmaması"],"dogru":3,"aciklama":"Nakit akışı yönetimi, paranın ne zaman girip ne zaman çıktığını izlemektir. Kârlı bir işletme bile ödeme gününde kasasında para yoksa zor duruma düşer."},{"id":"mg-10-s12","tur":"coktan-secmeli","soru":"Bir otel 100.000 TL’ye aldığı yıkama makinesinin bedelini beş yıla yayıp her yıl 20.000 TL gider yazıyor. Bunun nedeni hangisidir?","secenekler":["Makine bedelinin beş yıl taksitle ödenmesi","Makinenin yıllarca kullanılıp eskimesi","Makinenin her yıl yeniden satın alınması","Makinenin ilk yıl gider sayılamaması"],"dogru":1,"aciklama":"Amortisman, uzun süre kullanılan varlığın eskimeyle azalan değerinin kullanım ömrüne bölünüp her yıl gider sayılmasıdır. Taksit bir ödeme biçimidir; amortisman ise ödeme yapılmasa da yazılan bir giderdir."},{"id":"mg-10-s13","tur":"coktan-secmeli","soru":"Harçlığı 1.000 TL olarak kalan bir öğrenci, fiyatlar arttığı için eskisinden az öğle yemeği yiyebiliyor. Bu durumu hangisi doğru açıklar?","secenekler":["Enflasyon arttı, satın alma gücü düştü","Enflasyon düştü, satın alma gücü arttı","Faiz arttı, satın alma gücü düştü","Kâr marjı düştü, enflasyon arttı"],"dogru":0,"aciklama":"Fiyatların genel düzeyi yükseldi (enflasyon); aynı parayla alınabilen mal ve hizmet azaldı (satın alma gücü düştü). Faiz ve kâr marjı bu öğrencinin yaşadığı durumla ilgili değildir."},{"id":"mg-10-s14","tur":"coktan-secmeli","soru":"1.000 TL, yıllık yüzde 10 faizle iki yıl bekletiliyor. İki yılın sonunda basit faizle ve bileşik faizle ulaşılan tutar sırasıyla nedir?","secenekler":["1.100 TL ve 1.200 TL","1.200 TL ve 1.200 TL","1.200 TL ve 1.210 TL","1.210 TL ve 1.200 TL"],"dogru":2,"aciklama":"Basit faizde her yıl 100 TL işler, toplam 1.200 TL olur. Bileşik faizde ikinci yılın faizi 1.100 TL üzerinden hesaplandığı için tutar 1.210 TL’ye çıkar."},{"id":"mg-10-s15","tur":"coktan-secmeli","soru":"Dönem borcu 3.000 TL, asgari ödeme tutarı 600 TL olan kişi yalnız 600 TL ödüyor. Kalan borçla ilgili hangisi doğrudur?","secenekler":["Kalan 2.400 TL silinir","Kalan 2.400 TL faizsiz ertelenir","Borcun tamamı ödenmiş sayılır","Kalan 2.400 TL’ye faiz işler"],"dogru":3,"aciklama":"Asgari ödeme yalnız gecikmeye düşmeyi önler. Ödenmeyen kısım sonraki aya kalır ve ona faiz işler; yeni harcamalar eklendikçe borç büyür."},{"id":"mg-10-s16","tur":"coktan-secmeli","soru":"Yalnız yaz aylarında ve tek bir ülkeden gelen turistlere çalışan bir otel, o pazarda sorun çıkınca boş kalıyor. Riski azaltmak için hangisi uygundur?","secenekler":["Reklam bütçesinin tamamını aynı ülkeye ayırmak","Farklı ülkelerden ve farklı aylarda konuk ağırlamak","Fiyatı düşürüp aynı pazara daha çok yüklenmek","Sezon dışında oteli kapatıp işletmeyi bırakmak"],"dogru":1,"aciklama":"Çeşitlendirme riski yok etmez, yayar: bir kaynak zayıfladığında ötekiler dengeyi korur. Aynı pazara daha çok yüklenmek ise bağımlılığı artırır."},{"id":"mg-10-s17","tur":"dogru-yanlis","soru":"Pansiyonun kirası, konuk sayısı artsa da azalsa da aynı kaldığı için değişken gider sayılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Konuk sayısına göre değişmeyen kira sabit giderdir. Değişken gider, satış arttıkça artan çarşaf yıkama ya da kahvaltı malzemesi gibi giderlerdir."},{"id":"mg-10-s18","tur":"dogru-yanlis","soru":"Bileşik faizde ikinci dönemin faizi, ilk dönemin faizi ana paraya eklendikten sonra çıkan toplam üzerinden hesaplanır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Bileşik faizde faiz ana paraya eklenir ve yeni toplam üzerinden işler. Basit faizde ise her dönem yalnız başlangıçtaki ana para esas alınır."},{"id":"mg-10-s19","tur":"dogru-yanlis","soru":"Beklenen kazancı çok yüksek olan bir yatırımda para kaybetme olasılığı genellikle düşüktür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Risk-getiri ilişkisine göre beklenen kazanç yükseldikçe kaybetme olasılığı da yükselir. “Garantili yüksek kazanç” vaadi bir uyarı işaretidir."},{"id":"mg-10-s20","tur":"dogru-yanlis","soru":"Banka, müşterisinden telefonda ya da mesajla kart şifresini ve SMS ile gelen onay kodunu istemez.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Şifre ve onay kodu yalnız müşterinin bilmesi gereken bilgilerdir. Bunları isteyen arama ya da mesaj oltalama girişimidir; bilgi verilmez."},{"id":"mg-10-s21","tur":"senaryo","durum":"Ağustos sonu, sahil otelindeki yaz stajın bitiyor. Staj ücretin ve biriken bahşişlerinle eline hiç olmadığı kadar para geçti. Okul açılınca gelirin yeniden harçlığa düşecek; servis ücreti ve yeni üniforma ayakkabısı seni bekliyor.","soru":"Ne yaparsın?","secenekler":["Yazın emeğimin karşılığı olarak paranın tamamıyla istediğim telefonu alırım.","Parayı çekmecede tutar, canım ne isterse aldıkça harcarım.","Okul dönemi giderlerimi yazar, önce onlara yetecek parayı ayırırım.","Telefonu taksitle alır, taksitleri kışın harçlığımdan öderim."],"dogru":2,"aciklama":"Sezonluk gelir düzensiz gelirdir: iyi ayın fazlası, gelirin düştüğü aylar için ayrılır. Önce ihtiyaçlar (servis, ayakkabı) yazılır, istek sonra gelir. Taksit ise harçlığa sabit bir yük bindirir ve finansal riski artırır."},{"id":"mg-10-s22","tur":"senaryo","durum":"Akşam 21.00, evdesin. Telefonuna bir mesaj geliyor: “Bankanızdan bildirim: hesabınız bu gece kapatılacak. Engellemek için bağlantıya tıklayıp kart bilgilerinizi girin.” Staj ücretin o hesaba yatıyor.","soru":"İlk adımın ne olur?","secenekler":["Bağlantıya tıklamam, bankanın kendi uygulamasından bakarım.","Hesabım kapanmasın diye bağlantıya tıklar, bilgileri girerim.","Bağlantıyı açar, sayfa bankaya benziyorsa işlemi tamamlarım.","Mesaja yanıt yazar, gerçek olup olmadığını gönderene sorarım."],"dogru":0,"aciklama":"Acele ettiren ve korkutan mesaj oltalamanın tipik işaretidir. Sahte sayfalar gerçeğine çok benzer; gönderene sormak da dolandırıcıyla konuşmaktır. Bankaya yalnız resmî uygulamadan ya da kartın arkasındaki numaradan ulaşılır."},{"id":"mg-10-s23","tur":"senaryo","durum":"Resepsiyonda staj yapıyorsun. Saat 15.20, şefin toplantıda. Telefon çalıyor; arayan kişi kendini banka görevlisi olarak tanıtıyor, otelin kart cihazında sorun olduğunu söylüyor ve otelin telefonuna az önce gelen onay kodunu okumanı istiyor.","soru":"Ne yaparsın?","secenekler":["İş aksamasın diye kodu okur, sonra şefime anlatırım.","Adını ve sicil numarasını sorar, söylerse kodu okurum.","Kodu vermem ama şefimi meşgul etmemek için kimseye söylemem.","Kodu vermem, görüşmeyi bitirir ve durumu şefime hemen bildiririm."],"dogru":3,"aciklama":"Banka telefonda onay kodu istemez; ad ve sicil numarası söylemek dolandırıcı için zor değildir. Kodu vermemek yetmez: aynı kişi başka bir çalışanı arayabilir, bu yüzden amir hemen haberdar edilir."},{"id":"mg-10-s24","tur":"senaryo","durum":"Arkadaşınla okul bitince sahilde küçük bir kahvaltı kafesi açmayı hayal ediyorsunuz. Arkadaşın çok heyecanlı: “Boş bir dükkân gördüm, hemen tutalım; hesabı kitabı açınca yaparız, orası hep kalabalık” diyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Fırsat kaçmasın diye dükkânı tutmayı, hesabı açılıştan sonra yapmayı kabul ederim.","Önce başlangıç maliyetini, aylık giderleri ve başa baş noktasını hesaplamayı öneririm.","Komşu kafelerin fiyatını öğrenir, her birinin biraz altına yazmayı öneririm.","Hesaptan önce bankadan ne kadar kredi çekebileceğimizi öğrenmeyi öneririm."],"dogru":1,"aciklama":"Finansal uygulanabilirlik, parayı riske atmadan önce işin yapılabilir olup olmadığını kâğıt üstünde görmektir. “Hep kalabalık” bir veri değildir; maliyeti bilmeden fiyat belirlemek her satışta zarara yol açabilir. Kredi miktarı da ancak hesap yapıldıktan sonra anlam kazanır."},{"id":"mg-10-s25","tur":"senaryo","durum":"Mezun oldun, bir otelde işe başladın ve ilk ücretin hesabına yattı. Tutar, iş görüşmesinde konuşulan rakamdan düşük. İnsan kaynakları sana o ayın bordrosunu da e-postayla göndermiş.","soru":"İlk adımın ne olur?","secenekler":["Hakkımın yendiğini düşünür, durumu sosyal medyada paylaşırım.","Bordroyu açmaz, tutar önümüzdeki ay düzelir diye beklerim.","Bordrodaki satırları okur, anlamadığım kesintiyi insan kaynaklarına sorarım.","Vardiyadaki arkadaşlarıma ne kadar aldıklarını sorar, karşılaştırırım."],"dogru":2,"aciklama":"Görüşmede konuşulan rakam brüt ücret olabilir; ele geçen net ücret kesintilerden sonra kalan tutardır. Bordro bu farkı satır satır gösterir. Önce belge okunur, anlaşılmayan yer yetkilisine sorulur; suçlamak ya da görmezden gelmek sorunu çözmez."},{"id":"mg-10-s26","tur":"senaryo","durum":"İlk kredi kartı hesap özetin geldi: dönem borcu 3.000 TL, asgari ödeme tutarı 600 TL. Hesabında 3.500 TL var. Hafta sonu arkadaşların 1.000 TL’lik bir geziye çağırıyor.","soru":"Ne yaparsın?","secenekler":["Asgari tutarı öder, kalan parayla geziye giderim.","Bu ay ödeme yapmaz, gelecek ay iki dönemi birlikte öderim.","Asgari tutarı öder, geziyi de kredi kartıyla karşılarım.","Borcun tamamını öder, geziyi başka bir hafta sonuna ertelerim."],"dogru":3,"aciklama":"Asgari tutar yalnız gecikmeye düşmeyi önler; ödenmeyen 2.400 TL’ye faiz işler ve yeni harcama eklenirse borç büyür. Gezi bir istektir, ertelenebilir; borç ise zamanında ödenmelidir."},{"id":"mg-10-s27","tur":"senaryo","durum":"Öğle arasında bir arkadaşın sana telefonundan bir ilan gösteriyor: “Bir ayda paranı ikiye katla, kazanç garantili, risk yok. Yerler dolmadan hemen para gönder.” Arkadaşın harçlığından biriktirdiği parayı yatırmak üzere, seni de çağırıyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Önce az bir para gönderip gerçekten kazandırıp kazandırmadığını denerim.","Yerler dolmadan birikimimin yarısını gönderir, yarısını saklarım.","İlandaki numarayı arayıp kazancın garantili olduğunu teyit ederim.","Para göndermem, bunun bir uyarı işareti olduğunu söyler, aileme danışırım."],"dogru":3,"aciklama":"Yüksek kazanç ile sıfır risk aynı teklifte bulunmaz; acele ettirmek de dolandırıcılığın işaretidir. Az parayla denemek ya da ilan sahibine sormak güvence sağlamaz. Para gönderilmez, bir büyüğe danışılır."},{"id":"mg-10-s28","tur":"coktan-secmeli","soru":"Bir pansiyon sahibi, ay sonunda oda gelirlerini en üste, giderlerini altına yazıp en alt satırda kâr ya da zararı görüyor. Bu kayıtla bütçe arasındaki fark hangisidir?","secenekler":["Gelir tablosu önceden yapılan plandır, bütçe sonucu gösterir","Gelir tablosu para giriş çıkış zamanını, bütçe kârı gösterir","Gelir tablosu biten dönemin sonucunu, bütçe planı gösterir","Gelir tablosu yalnız gideri, bütçe yalnız geliri yazar"],"dogru":2,"aciklama":"Gelir tablosu biten dönemin gelirlerini, giderlerini ve sonucunda kâr ya da zararı gösterir; bütçe ise dönem başlamadan yazılan plandır. Para giriş ve çıkış zamanını izlemek nakit akışı yönetimidir."},{"id":"mg-10-s29","tur":"coktan-secmeli","soru":"Kafe açacak bir girişimci listesine iki kalem yazıyor: kahve makinesinin alımı ve açılıştan sonra her ay ödenecek dükkân kirası. Hangisi doğrudur?","secenekler":["Makine işletme gideri, kira yatırım maliyetidir","Makine yatırım maliyeti, kira işletme gideridir","İkisi de bir kez ödenen yatırım maliyetidir","İkisi de her ay yinelenen işletme gideridir"],"dogru":1,"aciklama":"Kahve makinesi kafe ilk müşterisini karşılamadan bir kez alınır, bu yüzden yatırım maliyetidir. Kira ise iş açıldıktan sonra her ay yinelendiği için işletme gideridir."},{"id":"mg-10-s30","tur":"coktan-secmeli","soru":"A kafesi için 400.000 TL harcandı, kafe yılda 100.000 TL kâr bırakıyor. B kafesi için 300.000 TL harcandı, yılda 150.000 TL kâr bırakıyor. Yatırımın geri dönüş süresine göre hangisi doğrudur?","secenekler":["İkisi de üç yılda geri öder; riskleri aynı sayılır","A iki yılda, B dört yılda; A daha az riskli sayılır","A dört yılda, B iki yılda; A daha az riskli sayılır","A dört yılda, B iki yılda; B daha az riskli sayılır"],"dogru":3,"aciklama":"Yatırım yıllık kâra bölünür: A için 400.000 ÷ 100.000 = 4, B için 300.000 ÷ 150.000 = 2 yıl. Parasını daha kısa sürede geri veren fikir genellikle daha az riskli sayılır; süre uzadıkça belirsizlik artar."},{"id":"mg-10-s31","tur":"coktan-secmeli","soru":"Bir girişimci kafeyi açmadan önce cumartesi sabahı sokaktan geçen kişileri ve çevredeki dolu masaları sayarak ayda kaç kahvaltı tabağı çıkarabileceğini tahmin ediyor. Adetle ölçülen bu tahmin hangi kavrama karşılık gelir?","secenekler":["Ciro","Pazar büyüklüğü","Satış hacmi","Başa baş noktası"],"dogru":2,"aciklama":"Belirli bir dönemde satılacak ürün miktarı satış hacmidir ve iş açılmadan önce sayıma dayanarak tahmin edilir. Ciro parayla ölçülür; pazar büyüklüğü ise bu hacmin çıkabileceği tavanı gösterir."},{"id":"mg-10-s32","tur":"coktan-secmeli","soru":"Melek yatırımcı ile kitle fonlaması arasındaki fark hangisidir?","secenekler":["Melek yatırımcı ortak olur; kitle fonlamasında çok kişi küçük tutar verir","Melek yatırımcıya para faiziyle geri ödenir; kitle fonlaması bir kredidir","Melek yatırımcı bir kamu kurumudur; kitle fonlaması banka ürünüdür","Melek yatırımcı kararlara karışmaz; kitle fonlamasında destekçi ortak olur"],"dogru":0,"aciklama":"Melek yatırımcı girişime kendi parasını koyar, karşılığında ortaklık payı alır ve kararlarda söz ister. Kitle fonlamasında ise para internet platformunda çok sayıda kişiden küçük tutarlarla toplanır."},{"id":"mg-10-s33","tur":"dogru-yanlis","soru":"Başlangıç sermayesinin yalnız açılış gününe kadar yapılacak harcamaları karşılaması yeterlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sermaye, işin kendi parasını kazanmaya başlayacağı güne kadar yetmelidir. İyi fikirlerin çoğu sermayesi ilk aylarda tükendiği için kapanır."},{"id":"mg-10-s34","tur":"coktan-secmeli","soru":"Dört arkadaş kafe fikrinin maliyetini, tahmini satışını ve başa baş noktasını hesaplıyor; sonuç “bu hâliyle yapılmaz” çıkıyor. Hangisi doğru değerlendirmedir?","secenekler":["Hesap boşa gitmiştir; fikir tümüyle bırakılmalıdır","Sonuç önemsizdir; dükkân tutulur, hesap sonra yenilenir","Sonuç değerlidir; fikir küçültülebilir ya da taşınabilir","Sonuç kesindir; yalnız daha çok kredi çekmek fikri kurtarır"],"dogru":2,"aciklama":"Fizibilite, parayı kaybetmeden önce yanlışı kâğıt üstünde görmek için yapılır; “yapılmaz” sonucu da değerlidir. Fikir değiştirilir, küçültülür ya da başka bir yere taşınır."},{"id":"mg-10-s35","tur":"coktan-secmeli","soru":"Antalya’da staj yapan öğrencinin bu ay parası bütün harcamalarına yetmeyecek. Bir harcamayı sonraki aya bırakmak zorunda. Hangisini ertelemesi doğru olur?","secenekler":["Ev kirası","Servis kartı dolumu","Elektrik faturası","Arkadaşlarla sinema"],"dogru":3,"aciklama":"Sinema yaşam için zorunlu olmayan, ertelenebilen isteğe bağlı bir giderdir. Kira, servis kartı ve fatura temel ihtiyaçları karşılayan zorunlu giderlerdir ve bütçede önce yazılır."},{"id":"mg-10-s36","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi planlı borçlanmaya örnektir?","secenekler":["Arkadaşları aldı diye gelirini aşan taksitle telefon almak","Ödeyebileceği taksitle mutfak kursuna yazılmak","Kredi kartını gelirinin üstünde kullanmak","Anlık bir istekle pahalı saati taksitle almak"],"dogru":1,"aciklama":"Planlı borçlanma, ödeme gücüne uygun biçimde eğitim ya da mesleki gelişim için yapılır. Sosyal baskıyla, anlık istekle ya da geliri aşarak yapılan borçlanma risklidir."},{"id":"mg-10-s37","tur":"dogru-yanlis","soru":"Kredi kartı borcunun her ay yalnız bir kısmını ödemek, kalan tutar büyüdükçe kişiyi borç döngüsüne sokabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Zamanında ödenmeyen borç büyüdükçe bütçe sürekli zorlanır ve kişi ay sonunu getiremez hâle gelir; borç döngüsü budur."},{"id":"mg-10-s38","tur":"coktan-secmeli","soru":"Aylık geliri 20.000 TL, giderleri 17.000 TL olan bir çalışan aylık taksiti 4.000 TL olan bir ürün almak istiyor. Ödeme gücü açısından hangisi doğrudur?","secenekler":["Kalan 3.000 TL taksite yetmez; ucuz ürüne yönelmeli","Geliri taksitten büyük olduğu için taksiti rahatça öder","Giderlerini borçla kapatırsa taksiti sorunsuz öder","Taksit gelirinin yarısından az olduğu için risk yoktur"],"dogru":0,"aciklama":"Ödeme gücü için gelirden giderler çıkarılır ve kalanın taksite yetip yetmediğine bakılır: 20.000 − 17.000 = 3.000 TL, 4.000 TL’lik taksiti karşılamaz. Gelirin tamamını taksitle karşılaştırmak yanıltır."},{"id":"mg-10-s39","tur":"dogru-yanlis","soru":"Bir acentede çok tur satan satış elemanına maaşına ek olarak verilen ödemeye burs denir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Başarıya ya da satışa bağlı olarak maaşın üstüne verilen ek ödeme primdir. Burs, öğrencinin eğitim giderlerine destek olmak için verilen paradır."},{"id":"mg-10-s40","tur":"coktan-secmeli","soru":"Pansiyon sahibi odaları yenilemek için iki kredi teklifi aldı. Karar verirken neye bakması en doğrudur?","secenekler":["Yalnız aylık taksitin en düşük olduğu teklife","En uzun vadeli teklife, çünkü taksit küçük olur","Toplam geri ödemeye ve kışın ödenebilir taksite","Bankanın en yakın şubesinin bulunduğu teklife"],"dogru":2,"aciklama":"Kredide yalnız aylık taksite değil, geri ödenecek toplam tutara bakılır. Taksit, gelirin en düşük olduğu ayda bile ödenebilecek kadar olmalıdır; vade uzadıkça taksit küçülse de toplam yük gözden kaçabilir."},{"id":"mg-10-s41","tur":"dogru-yanlis","soru":"Bireysel emeklilik sistemi zorunlu sosyal güvenlik sisteminin yerini tutar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bireysel emeklilik sistemi zorunlu sosyal güvenlik sisteminin yerini tutmaz, onu tamamlayan uzun vadeli bir birikimdir."},{"id":"mg-10-s42","tur":"coktan-secmeli","soru":"Küçük bir işletmeci ürünlerinin fiyatını hesaplarken vergiyi unutuyor. Bu işletmeci hangi durumla karşılaşır?","secenekler":["Kârının bir kısmının devlete ait olduğunu sonra görür","Sattığı her üründe vergi kadar fazladan kazanç elde eder","Vergi yalnız ücretten alındığı için hiç etkilenmez","Fiş kesmediği sürece vergi yükünden kurtulmuş olur"],"dogru":0,"aciklama":"Vergi kazançtan, ücretten ve harcamadan alınır; fiyatı hesaplarken vergiyi unutan, kâr sandığı paranın bir kısmının kendisine ait olmadığını sonradan öğrenir. Fiş ya da fatura kesmek de zorunludur."},{"id":"mg-10-s43","tur":"coktan-secmeli","soru":"Bir otel, bir şirketin toplantısı için fatura kesti; parayı ay sonunda alacak. Bu tutar bugün için hangisidir?","secenekler":["Nakit girişi","Vadeli alacak","Kısa vadeli borç","Nakit çıkışı"],"dogru":1,"aciklama":"Satış yapılmış ama bedeli daha sonra tahsil edilecekse vadeli alacak oluşur. Nakit girişi satış yapıldığında değil, para kasaya girdiğinde olur."},{"id":"mg-10-s44","tur":"coktan-secmeli","soru":"Bir otelde iki sorun var: personel eğitimi eksik olduğu için hatalı hizmet veriliyor ve bölgede yeni rakip oteller açılıyor. Hangisi doğrudur?","secenekler":["Eğitim eksikliği dış risk, rakip oteller iç risktir","İkisi de işletmenin içinden doğan iç risktir","İkisi de işletmenin dışından gelen dış risktir","Eğitim eksikliği iç risk, rakip oteller dış risktir"],"dogru":3,"aciklama":"Eğitim eksikliği işletmenin kendi yapısından ve yönetiminden doğduğu için iç risktir. Yeni rakiplerin açılması ise işletmenin dışındaki değişikliklerden kaynaklanan dış risktir."},{"id":"mg-10-s45","tur":"coktan-secmeli","soru":"Gideri azaltmak isteyen otel müdürüne dört öneri geliyor. Hangisi maliyet yönetimine uygundur?","secenekler":["Konuk havlularını daha ince ve ucuz olanlarla değiştirmek","Oda temizliğini her gün yerine iki günde bir yapmak","Boş odalarda klimayı kapatıp ışıkları söndürmek","Personeli azaltıp resepsiyonda bekleme süresini uzatmak"],"dogru":2,"aciklama":"Maliyet yönetimi hizmetin kalitesini düşürmeden israfı azaltmaktır; boş odadaki klimayı kapatmak kimseyi kaybettirmez. Havluyu inceltmek ya da hizmeti kısmak ise konuğu kaybettirir."},{"id":"mg-10-s46","tur":"coktan-secmeli","soru":"Zarar eden bir pansiyon kurtarma planı hazırlıyor. Her yıl prim ödeyerek yangın zararının sigorta şirketince karşılanmasını sağlamak bu planda hangi başlığa girer?","secenekler":["Risk transferi","Verimlilik artırma","Maliyet yönetimi","Çeşitlendirme"],"dogru":0,"aciklama":"Sigorta, riskin zararını başkasına devretmenin yaygın yoludur; bu yüzden risk transferidir. Verimlilik artırma ise eldeki kaynaklardan daha çok fayda sağlamayı anlatır."},{"id":"mg-10-s47","tur":"dogru-yanlis","soru":"Yalnız yaz aylarında oda satışına dayanan bir otel, toplantı ve düğün gibi ek gelir akışları kurarsa düşük sezonda daha kolay ayakta kalır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tek gelir akışına bağlı işletme kırılgandır; toplantı, düğün ya da restoran gibi ek akışlar düşük sezonda işletmeyi ayakta tutar."}],"siralamalar":[{"id":"mg-10-r01","konu":"10.1","baslik":"Paran nereye gidiyor? Hedefe giden plan","yonerge":"Mesleki hedefin için kişisel finans planı hazırlarken izleyeceğin adımları doğru sıraya koy.","adimlar":["Gelirinin ne kadar olduğunu, hangi aralıklarla geldiğini ve temel giderlerini araştırıp yaz.","Topladığın verilerdeki gider kalemlerini ihtiyaç ve istek olarak ayır, azaltabileceğin giderleri belirle.","Ayırdığın giderlere göre toplam gelirini, toplam giderini ve aylık birikim hedefini yazarak kişisel bütçeni hazırla.","Hedefinin maliyetini, süresini ve her ay ayıracağın parayı gösteren finansal yol haritanı çıkar.","Gelir azalırsa ya da beklenmedik bir gider çıkarsa planın ne olur diye sına ve gerekirse düzelt."],"aciklama":"Bütçenin ilk adımı elindeki kaynağı tanımaktır; giderler ayrıldıktan sonra bütçe yazılır, yol haritası bu bütçeden çıkar ve en sonda risklere karşı denenir."},{"id":"mg-10-r02","konu":"10.2","baslik":"Bu iş para kazandırır mı?","yonerge":"Bir iş fikrinin finansal açıdan uygulanabilir olup olmadığını değerlendirme adımlarını doğru sıraya koy.","adimlar":["Meslek alanınla ilgili basit, somut ve hesaplanabilir bir iş fikri belirle.","Hedef kâr marjını, geri dönüş süresini ve pazar potansiyelini ölçüt olarak koy; başlangıç yatırım maliyetini, aylık işletme giderlerini ve tahminî aylık satış gelirini listele.","Listelediğin rakamlarla aylık tahminî kârı, kâr marjını ve yatırımın geri dönüş süresini hesapla.","Hesapladığın sonuçları koyduğun hedef ölçütlerle karşılaştır, güçlü ve zayıf yönleri bul.","Kanıtlara dayanarak iş fikrinin uygulanabilir olup olmadığına gerekçeli bir karar ver."],"aciklama":"Hesaplanacak bir şey olması için iş fikri net olmalıdır; ölçütler ve maliyet listesi hesaptan önce hazırlanır, çünkü hesap bu rakamlara dayanır. Sonuçlar önce hedeflerle karşılaştırılır, karar da bu kıyasa dayanır."},{"id":"mg-10-r03","konu":"10.3","baslik":"Batmak üzere olan kafeyi kurtar","yonerge":"Nakit sıkıntısı çeken bir işletme için finansal kurtarma planı hazırlama adımlarını doğru sıraya koy.","adimlar":["Giderleri toplayıp aylık toplam gideri bul, işletmenin kâr mı zarar mı ettiğini belirle.","Hesapladığın kâr ve nakit durumuna bakarak nakit sıkıntısının nedenlerini balık kılçığı diyagramında topla, riskleri iç ve dış diye ayır.","Maliyet yönetimi, verimlilik artışı ve risk transferi alanlarında kurtarma stratejileri geliştir.","Stratejileri uygulanabilirlik, kâra etkisi ve riski azaltma gücüne göre karşılaştırıp en uygununu seç.","Seçtiğin stratejiyle finansal sürdürülebilirlik planını hazırla ve sınıfa sunarak savun."],"aciklama":"Sorun ancak rakamlar incelenince görünür; nedenler bulunmadan çözüm üretilemez, çözümler karşılaştırılmadan da en uygun olanı seçilip plana dönüştürülemez."}],"acikSorular":[{"id":"mg-10-y01","konu":"10.2","soru":"Bir girişimci küçük bir pansiyon açmayı düşünmektedir. Aylık sabit gideri 30.000 TL, satılan her oda gecesinin kendi masrafı çıktıktan sonra bıraktığı pay 600 TL’dir. Başa baş hesabının ne işe yaradığını açıklayınız, bu pansiyonun başa baş satış sayısını hesaplayarak gösteriniz ve sonucun girişimcinin kararını nasıl etkileyeceğini yazınız.","olcut":[{"metin":"Başa baş hesabının, zarar etmemek için gereken en az satışı bulmaya yaradığını belirtir.","puan":20},{"metin":"Sabit giderlerin, bir satışın bıraktığı paya bölündüğünü yazar.","puan":20},{"metin":"30.000 ÷ 600 işlemini yaparak 50 oda gecesi sonucunu bulur.","puan":25},{"metin":"Sonucun, pazarın verebileceği satışla karşılaştırılarak fikrin yürüyüp yürümeyeceğine karar verilmesinde kullanıldığını nedeniyle açıklar.","puan":35}],"ornek":"Başa baş hesabı, işletmenin zarar etmemek için en az kaç satış yapması gerektiğini bulmaya yarar. Bunun için sabit giderler, bir satışın bıraktığı paya bölünür: 30.000 ÷ 600 = 50 oda gecesi. Pansiyon ayda 50 oda gecesi satarsa ne kâr ne zarar eder, 51. geceden sonra her satış kâr bırakır. Girişimci bu sayıyı pazarın verebileceği satışla karşılaştırır; sayı pazardan büyükse fikir bu hâliyle yapılmaz ve girişimci planı yeniden gözden geçirir.","ipucu":"Çıkan sayının tek başına anlamı yoktur; onu neyle karşılaştırarak karar vereceğinizi düşünün."},{"id":"mg-10-y02","konu":"10.3","soru":"Bir acente eylülde büyük bir grubun turunu düzenlemiş, parasını kasımda alacaktır; ancak otobüs firmasına ve rehbere ekimde ödeme yapması gerekmektedir. Nakit akışı kavramını açıklayınız, acentenin kâğıt üzerinde kârlı olmasına rağmen neden sıkıntı yaşayabileceğini belirtiniz ve bu sıkıntıyı azaltmak için bir önlem öneriniz.","olcut":[{"metin":"Nakit akışını, paranın işletmeye giriş ve çıkış zamanı olarak doğru tanımlar.","puan":20},{"metin":"Ekimdeki ödemeyi nakit çıkışı, kasımdaki tahsilatı vadeli alacak olarak ayırt eder.","puan":20},{"metin":"Kârlı görünen işletmenin ödeme gününde kasada para yoksa zor duruma düşebileceğini nedeniyle açıklar.","puan":35},{"metin":"Nakit girişlerini ve çıkışlarını önceden planlamak gibi, nakit sıkıntısını azaltmaya yönelik somut bir önlem önerir.","puan":25}],"ornek":"Nakit akışı, paranın işletmeye ne zaman girip ne zaman çıktığıdır. Acente parasını kasımda alacağı için bu tutar ekimde henüz vadeli alacaktır; otobüs ve rehber ödemeleri ise ekimde yapılması gereken nakit çıkışıdır. İş kâğıt üzerinde kârlı olsa bile ödeme gününde kasada para yoksa acente borcunu ödeyemez ve zor duruma düşer. Önlem olarak acente, paranın ne zaman girip ne zaman çıkacağını tarih tarih önceden yazıp izler ve ekimdeki ödemeler için kasada para ayırır.","ipucu":"Kâr ile kasadaki para aynı şey midir? Paranın hangi ayda girip çıktığına bakın."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":2,"baslik":"Meslek Etiği ve Ahilik Kültürü","onay":true,"kazanimlar":["Kuralların gerekliliğini ve işlevini değerlendirebilme.","Ahilik teşkilatının yapısını ve işleyişini çözümleyebilme.","Ahilik kültürünün toplum düzenine ve iş yaşamına katkılarını yorumlayabilme.","İş hayatındaki ahlaki bir sorun için Ahilik kültürü doğrultusunda çözümleyici bir plan yapılandırabilme."],"soz":"Kimse bakmıyorken yaptığın şey, mesleğindeki imzandır.","dersler":[{"baslik":"Kural Olmasa Ne Olurdu?","ilk":"mg-2-001"},{"baslik":"Kural Kime Yarar?","ilk":"mg-2-005"},{"baslik":"Ahlak mı, Etik mi?","ilk":"mg-2-008"},{"baslik":"Konuk Sana Neden Güvenir?","ilk":"mg-2-012"},{"baslik":"Küçük Bir Şeyden Ne Çıkar?","ilk":"mg-2-016"},{"baslik":"Sektörün Dili: Etik Sözlüğü","ilk":"mg-2-021"},{"baslik":"Kuralların Gizli İşleri","ilk":"mg-2-049"},{"baslik":"Çarşıdaki Meslek Okulu","ilk":"mg-2-026"},{"baslik":"Çıraktan Ustaya Giden Yol","ilk":"mg-2-030"},{"baslik":"Kuşak Kime Bağlanır?","ilk":"mg-2-034"},{"baslik":"Pabucu Neden Dama Atılır?","ilk":"mg-2-039"},{"baslik":"Yamaktan Ustaya Basamaklar","ilk":"mg-2-054"},{"baslik":"Çarşıda Güvenin Kuralları","ilk":"mg-2-059"},{"baslik":"Atölyede Duadan Diyagrama","ilk":"mg-2-062"},{"baslik":"Doğru Olan Kolay mı?","ilk":"mg-2-020"},{"baslik":"Esnafın Ortak Sandığı","ilk":"mg-2-043"},{"baslik":"Kazanç mı, Karakter mi?","ilk":"mg-2-066"},{"baslik":"Dört Erdemin Sırrı","ilk":"mg-2-071"},{"baslik":"Ahi Kimdir, Hile Nedir?","ilk":"mg-2-074"},{"baslik":"Bu Görevleri Eskiden Kim Yapardı?","ilk":"mg-2-079"},{"baslik":"Esnafın, İşçinin, Hayırseverin Çatısı","ilk":"mg-2-082"},{"baslik":"Gördüğün Yanlışı Ne Yaparsın?","ilk":"mg-2-018"},{"baslik":"Sorun Nereden Çıkar?","ilk":"mg-2-086"},{"baslik":"Sorunun Gizli Nedenleri","ilk":"mg-2-090"},{"baslik":"Çözüm Planı Nasıl Kurulur?","ilk":"mg-2-093"}],"kavramlar":[{"id":"mg-2-001","konu":"2.1","terim":"Kural","ingilizce":"Rule","tanim":"Bir toplulukta ya da iş yerinde düzeni, güvenliği ve adaleti sağlamak için herkesin uyması beklenen davranış ölçüsüdür.","ornek":"Sabah 07.45, otelin personel girişi: herkes kartını okutur, üniformasını giyer ve vardiyaya saatinde çıkar.","sektor":"Otelde çok sayıda kişi aynı anda çalışır; kural olmasa kimse kimin neyi ne zaman yapacağını bilemez. Bir kuralın işe yarayıp yaramadığına güvenlik, adalet, verimlilik ve hakkaniyet gibi ölçütlerle bakılır.","iliskili":["mg-2-002","mg-2-003","mg-2-004"],"kontrol":null},{"id":"mg-2-002","konu":"2.1","terim":"Yazılı kural","ingilizce":"Written rule","tanim":"İş yerinin yönetmelik, talimat ya da sözleşme gibi belgelerle açıkça duyurduğu kuraldır.","ornek":"Staja başladığın gün sana personel el kitabı verilir: mesai saatleri, kıyafet ve telefon kullanımı tek tek yazar.","sektor":"Yazılı kural herkese aynı metinle duyurulur; “Bilmiyordum” demek zorlaşır, anlaşmazlık çıktığında da ona bakılır.","iliskili":["mg-2-001","mg-2-003","mg-2-021"],"kontrol":null,"cizim":"konusma"},{"id":"mg-2-003","konu":"2.1","terim":"Yazılı olmayan kural","ingilizce":"Unwritten rule","tanim":"Hiçbir belgede geçmediği hâlde bir iş yerinde ya da toplumda herkesin uymasını beklediği davranış biçimidir.","ornek":"Personel yemekhanesinde sıraya girmek, koridorda karşılaştığın konuğa yol verip selam vermek hiçbir panoda yazmaz, ama herkes bunu bekler.","sektor":"Nezaket, saygı ve görgü çoğu zaman yazılı değildir. Konuk yönetmeliği görmez, bu davranışları görür.","iliskili":["mg-2-001","mg-2-002","mg-2-014"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-2-004","konu":"2.1","terim":"Kural ihlali","ingilizce":"Breach of rules","tanim":"Uyulması gereken bir kuralın bilerek ya da dikkatsizlikle çiğnenmesidir.","ornek":"Öğle vardiyasında bir personel uyarı levhası koymadan koridoru siler; levha koymak kuraldır ve atlanmıştır.","sektor":"İhlalin bedelini çoğu zaman başkası öder: konuk, iş arkadaşı ya da otelin adı. Bu yüzden ihlal görüldüğünde gizlenmez, amire bildirilir.","iliskili":["mg-2-001","mg-2-016","mg-2-025"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-2-005","konu":"2.1","terim":"İş disiplini","ingilizce":"Work discipline","tanim":"Çalışanın işini zamanında, kurallara uygun ve başında biri olmasa da özenle yapma alışkanlığıdır.","ornek":"Saat 08.00’de başlayan vardiyaya 07.50’de hazır gelen, molasını süresinde bitiren ve işini yarım bırakmadan devreden stajyer.","sektor":"Otel vardiyayla çalışır: bir kişi geç kalınca önceki vardiyadaki arkadaşı evine gidemez. Disiplin ekibin birbirine güvenmesini sağlar.","iliskili":["mg-2-001","mg-2-013","mg-2-019"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-2-006","konu":"2.1","terim":"Adalet","ingilizce":"Fairness (justice)","tanim":"Herkese hakkı olanı vermek ve benzer durumdaki kişilere aynı ölçüyle davranmaktır.","ornek":"Bölüm şefi hafta sonu vardiyalarını sırayla dağıtır; kimse üst üste her pazar çalışmaz.","sektor":"Bir kuralı değerlendirirken sorulan sorulardan biridir: “Bu kural herkese aynı mı uygulanıyor?” Kişinin durumunu da gözeterek hakça davranmaya hakkaniyet denir. Konuklar için de geçerlidir: sıra herkese sıradır.","iliskili":["mg-2-001","mg-2-015","mg-2-035"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-007","konu":"2.1","terim":"Toplumsal fayda","ingilizce":"Public benefit","tanim":"Bir işin ya da kuralın yalnız onu yapana değil, toplumun geneline iyilik ve yarar sağlamasıdır.","ornek":"Mutfakta hijyen kurallarına eksiksiz uyan aşçı yalnız iş yerini değil, o gün yemek yiyen bütün konukların sağlığını korur.","sektor":"Programın anahtar kavramlarındandır. Dürüst çalışan işletmede konuk, çalışan ve bulunduğu şehir birlikte kazanır; turizmde tek bir işletmenin hatası bütün bölgenin adına yazılabilir.","iliskili":["mg-2-001","mg-2-043","mg-2-044"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-046","konu":"2.1","terim":"Hakkaniyet","ingilizce":"Equity","tanim":"Kuralı uygularken kişilerin içinde bulunduğu durumu da gözeterek herkesin hakkının dengeli ve vicdana uygun biçimde karşılanmasıdır.","ornek":"Saat 16.00, otelde ertesi gün sınavı olan bir personel kuralı bozmadan erken çıkış izni alır; şef, fazla mesai yapan öteki çalışanın hakkını da başka bir gün karşılar.","sektor":"Adalet “herkese aynı ölçü”, hakkaniyet “durumu gözeten dengeli ölçü” demektir; iyi yöneticiler kuralı uygularken ikisini birlikte gözetir.","iliskili":["mg-2-006","mg-2-001","mg-2-004"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-008","konu":"2.1","terim":"Ahlak","ingilizce":"Morality","tanim":"Bir toplumda neyin iyi, neyin kötü sayıldığını gösteren ve insanların davranışlarına yön veren değerler ile kurallar bütünüdür.","ornek":"Yolda bulduğu cüzdanı sahibine ulaştıran kişiyi kimse buna zorlamaz; ama herkes doğru olanın bu olduğunu bilir.","sektor":"Programın anahtar kavramlarındandır. Ahlak aileden ve toplumdan öğrenilir; iş yerine seninle birlikte gelir. Konuk, odasını emanet ettiği kişinin ahlakına güvenir.","iliskili":["mg-2-009","mg-2-010","mg-2-012"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-009","konu":"2.1","terim":"Etik","ingilizce":"Ethics","tanim":"İnsan davranışlarında neyin doğru, neyin yanlış olduğunu sorgulayan ve buna göre ilkeler koyan düşünce alanıdır.","ornek":"Staj toplantısında şef sorar: “Konuk yanlışlıkla fazla ödeme yaparsa ne yaparız?” Ekip doğru davranışı ve nedenini konuşur; yapılan şey etik bir tartışmadır.","sektor":"Ahlak “Ne doğru?” sorusuna toplumun verdiği cevaptır; etik bu cevabın nedenini sorgular ve ilkeye bağlar. İş hayatında “etik” dendiğinde çoğu zaman bir meslekte uyulan doğru davranış ilkeleri kastedilir.","iliskili":["mg-2-008","mg-2-010","mg-2-011"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-010","konu":"2.1","terim":"Meslek etiği","ingilizce":"Professional ethics","tanim":"Bir mesleği yapan herkesin işini yaparken uyması beklenen doğru davranış ilkelerinin bütünüdür.","ornek":"Resepsiyon görevlisi konuğun oda numarasını soran yabancıya bilgi vermez; çünkü konuğun bilgisini korumak mesleğinin ilkesidir.","sektor":"Programın anahtar kavramlarındandır. Unvana bakmaz: genel müdürü de ilk günündeki stajyeri de bağlar. Mesleğe duyulan güveni ve mesleğin saygınlığını bu ilkeler korur.","iliskili":["mg-2-009","mg-2-011","mg-2-044"],"kontrol":null},{"id":"mg-2-011","konu":"2.1","terim":"Etik ilkeler","ingilizce":"Ethical principles","tanim":"Bir meslekte ya da iş yerinde doğru davranışın çerçevesini çizen dürüstlük, sorumluluk, saygı, adalet ve tarafsızlık gibi temel ölçülerdir.","ornek":"Otelin personel panosunda asılı liste: “Konuğa ve iş arkadaşına saygı gösteririz. Bulduğumuz eşyayı teslim ederiz. Hatamızı bildiririz.”","sektor":"İşletmeler bu ilkeleri çoğu zaman yazılı bir etik kurallar listesine döker. Liste, kararsız kaldığın anda “Burada doğrusu ne?” sorusunun ilk cevabıdır.","iliskili":["mg-2-010","mg-2-012","mg-2-021"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-012","konu":"2.1","terim":"Dürüstlük","ingilizce":"Honesty","tanim":"Sözde ve davranışta doğru olmak, kimseyi aldatmamak ve kendine ait olmayanı almamaktır.","ornek":"Saat 11.30, boşalan oda: kat görevlisi komodinin çekmecesinde bir saat bulur ve hemen kat şefine teslim eder.","sektor":"Programın anahtar kavramlarındandır. Konuk odasını, valizini, kredi kartını otele emanet eder; otelcilik güven üzerine kurulu bir iştir. Dürüst olmayan tek bir davranış bütün ekibin emeğini gölgeler.","iliskili":["mg-2-013","mg-2-023","mg-2-037"],"kontrol":null},{"id":"mg-2-013","konu":"2.1","terim":"Sorumluluk","ingilizce":"Responsibility","tanim":"Üstlendiği işi eksiksiz yerine getirmek ve yaptığı işin sonucunu, hatası dâhil, sahiplenmektir.","ornek":"Servis stajyeri bir tabağı düşürüp kırar; saklamak yerine şefine gidip “Ben kırdım, kusura bakmayın” der.","sektor":"Hatayı bildirmek zayıflık değil, profesyonelliktir: bildirilen hata düzeltilir, saklanan hata büyür. Şef hatasını kendisi söyleyen personele güvenir.","iliskili":["mg-2-012","mg-2-005","mg-2-043"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-014","konu":"2.1","terim":"Saygı (etik ilke)","ingilizce":"Respect","tanim":"Karşıdaki kişinin değerini, hakkını ve sınırlarını gözeterek nazik ve özenli davranmaktır.","ornek":"Kat görevlisi kapıyı çalıp “Kat hizmetleri” diye seslenir ve cevap bekler; odada biri varken izinsiz içeri girmez.","sektor":"Etik ilke olarak saygı, kişinin hakkını ve özel alanını korumaktır: konuğun odası, eşyası ve tercihleri ona aittir. Konuğun dili, inancı, kıyafeti ne olursa olsun hizmetin kalitesi değişmez; aynı özen iş arkadaşına da gösterilir.","iliskili":["mg-2-003","mg-2-015","mg-2-011"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-2-015","konu":"2.1","terim":"Tarafsızlık","ingilizce":"Impartiality","tanim":"Karar verirken ya da hizmet sunarken kişisel yakınlığa, çıkara ve ön yargıya göre değil, herkes için aynı ölçüye göre davranmaktır.","ornek":"Saat 14.00, resepsiyonda sıra var: görevli tanıdığı konuğu öne almaz; herkesi geliş sırasıyla karşılar.","sektor":"Sırada bekleyen konuk başkasının öne alındığını hemen fark eder. Herkese aynı ölçüyle davranmak otele duyulan güveni korur.","iliskili":["mg-2-006","mg-2-018","mg-2-024"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-016","konu":"2.1","terim":"Etik dışı davranış","ingilizce":"Unethical behaviour","tanim":"Meslek etiği ilkelerine aykırı olan, başkasına zarar veren ya da haksız çıkar sağlayan davranıştır.","ornek":"Konuğa söylemeden hesaba fazladan bir içecek yazmak, bulunan eşyayı teslim etmemek, işe gelmediği hâlde giriş kartını arkadaşına okutturmak.","sektor":"Rüşvet, kayırmacılık, yalan söylemek ve iş yeri kaynaklarını kendi işi için kullanmak bilinen örnekleridir. Kimse fark etmese de etik dışıdır; fark edildiğinde kişiye işini ve mesleki saygınlığını kaybettirebilir.","iliskili":["mg-2-017","mg-2-018","mg-2-019","mg-2-004"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-017","konu":"2.1","terim":"Rüşvet","ingilizce":"Bribery","tanim":"Bir görevlinin görevine aykırı bir iş yapması ya da kuralı esnetmesi için ona para, hediye ya da başka bir çıkar sağlanmasıdır.","ornek":"Bir kişi resepsiyon stajyerine para uzatıp “Şu konuğun oda numarasını söyle” der; bu para hizmete teşekkür değil, kuralı çiğnetme teklifidir.","sektor":"Bahşişle karıştırma: bahşiş, verilen hizmete teşekkür olarak ve karşılığında kural dışı bir şey istenmeden bırakılır. Rüşvette para bir kuralı çiğnetmek için verilir. Bahşişin nasıl kabul edileceğini de işletmenin kuralı belirler. Kural çiğnetmeye yönelik teklif reddedilir ve amire bildirilir.","iliskili":["mg-2-016","mg-2-024","mg-2-022"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-019","konu":"2.1","terim":"İş yeri kaynaklarının kişisel kullanımı","ingilizce":"Misuse of company resources","tanim":"İşletmeye ait malzeme, araç, zaman ya da imkânın izinsiz olarak kişinin kendi işi için kullanılmasıdır.","ornek":"Konuk odaları için alınan şampuan ve sabunları çantasına koyup eve götüren personel.","sektor":"“Küçük bir şey, kimse fark etmez” düşüncesiyle başlar. Mesai saatinde uzun süre kişisel telefonla ilgilenmek de aynı kapıya çıkar: mesai, işletmenin sana emanet ettiği zamandır.","iliskili":["mg-2-016","mg-2-005","mg-2-012"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-2-021","konu":"2.1","terim":"Davranış kuralları belgesi","ingilizce":"Code of conduct","tanim":"Bir işletmenin çalışanlarından beklediği davranışları ve yasak saydığı tutumları madde madde yazdığı belgedir.","ornek":"Uluslararası bir zincir otelde işe başlayan stajyere ilk gün okuyup imzalaması için verilen belge.","sektor":"Sektörde “code of conduct” denir. Hediye kabulü, konuk bilgisinin korunması, sosyal medya paylaşımı gibi konularda işletmenin kuralını buradan öğrenirsin.","iliskili":["mg-2-002","mg-2-011","mg-2-024"],"kontrol":null,"kitapDisi":true,"cizim":"sozlesme"},{"id":"mg-2-022","konu":"2.1","terim":"Gizlilik","ingilizce":"Confidentiality","tanim":"İş sırasında öğrenilen konuk ve işletme bilgilerinin yetkisi olmayan hiç kimseyle paylaşılmamasıdır.","ornek":"Telefonla arayan biri “Selin Hanım sizde mi kalıyor?” diye sorar; görevli konuk bilgisi veremeyeceğini nazikçe söyler.","sektor":"Sektörde “confidentiality” denir. Kimin otelde kaldığı, oda numarası, kiminle geldiği, ne harcadığı konuğun özelidir. Tanınmış bir konuğun fotoğrafını çekip paylaşmak da gizliliği çiğner.","iliskili":["mg-2-010","mg-2-038","mg-2-017"],"kontrol":null,"kitapDisi":true},{"id":"mg-2-024","konu":"2.1","terim":"Çıkar çatışması","ingilizce":"Conflict of interest","tanim":"Çalışanın kişisel çıkarının işini tarafsız ve işletme yararına yapmasını etkileyebileceği durumdur.","ornek":"Acente çalışanına bir otobüs firması “Müşterilere bizi önerirsen sana hediye veririz” der; öneri artık müşterinin değil, çalışanın çıkarına göre şekillenebilir.","sektor":"Sektörde “conflict of interest” denir. Tedarikçiden ya da konuktan gelen hediye bu yüzden kurala bağlanır: işletmenin kuralını bilmiyorsan kabul etmeden önce amirine sor.","iliskili":["mg-2-015","mg-2-017","mg-2-021"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-2-038","konu":"2.1","terim":"“Eline, beline, diline sahip ol”","ingilizce":"“Keep your hands honest, your conduct chaste and your tongue clean” (Ahi saying)","tanim":"Ahilikle birlikte anılan; kişiden başkasının malına el uzatmamasını, iffetli ve ahlaklı olmasını, yalan ile kötü sözden uzak durmasını isteyen öğüttür.","ornek":"Staj yerindeki karşılığı: konuğun eşyasına dokunmamak (el), herkese saygılı ve ölçülü davranmak (bel), konuk ve iş yeri hakkında dedikodu yapmamak (dil).","sektor":"Üç kelimelik bir meslek etiği özetidir. Otelcilikte “dil” kısmı gizlilikle birleşir: odada gördüğün, resepsiyonda duyduğun otelin dışına çıkmaz.","iliskili":["mg-2-012","mg-2-022","mg-2-028"],"kontrol":null,"cizim":"el-yikama"},{"id":"mg-2-049","konu":"2.1","terim":"Meslek ahlakı","ingilizce":"Professional morality","tanim":"Bir mesleği yaparken doğru, dürüst, adil ve sorumlu davranmayı gerektiren değerler bütünüdür.","ornek":"Saat 10.00, resepsiyondaki stajyer hızlı iş çıkarmak için kayıt adımını atlamaz; işin konuğa ve ekibe etkisini düşünüp kaydı eksiksiz yapar.","sektor":"Meslek ahlakı, çalışma yaşamında güven ortamının temelidir. Bu kartı Etik ve Meslek etiği kartlarıyla birlikte oku.","iliskili":["mg-2-008","mg-2-009","mg-2-010"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-051","konu":"2.1","terim":"Güvenlik (kuralların işlevi)","ingilizce":"Safety","tanim":"İş yerindeki kuralların çalışanların ve hizmet alanların zarar görmesini önlemesidir.","ornek":"Saat 14.00, mutfakta ıslak zemine uyarı levhası konur; kayıp düşme riski oluşmadan azaltılır.","sektor":"Kuralların ilk işlevi güvenliktir; iş sağlığı ve güvenliği 3. ünitede ayrıntılı işlenir.","iliskili":["mg-2-005"],"kontrol":null,"cizim":"tarihi-yapi"},{"id":"mg-2-052","konu":"2.1","terim":"Görev tanımı","ingilizce":"Job description","tanim":"Bir çalışanın hangi işleri yapacağını ve hangi konularda sorumlu olduğunu açıkça yazan belgedir.","ornek":"Staja başladığın gün servis stajyerine verilen görev tanımında masa kurmak, tabak toplamak ve reyon temizliği yazar.","sektor":"Görev tanımı yazılı kurallardandır. Ne yapacağını ve nerede duracağını bilmeni sağlar.","iliskili":["mg-2-002","mg-2-053"],"kontrol":null,"cizim":"ekip"},{"id":"mg-2-053","konu":"2.1","terim":"Kalite standardı","ingilizce":"Quality standard","tanim":"Bir ürünün ya da hizmetin hangi ölçütlere uyması gerektiğini belirleyen yazılı kuraldır.","ornek":"Otelin oda standardında yastık sayısı, havlu düzeni ve minibar dolumu tek tek yazılıdır; kat şefi odayı bu listeye göre kontrol eder.","sektor":"Kalite standartları yazılı kurallara örnektir; otelde oda, mutfak ve servis standartları böyle yazılır.","iliskili":["mg-2-002","mg-2-040","mg-2-052"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-2-026","konu":"2.2","terim":"Ahilik","ingilizce":"Ahi brotherhood (Akhism)","tanim":"Anadolu’da 13. yüzyılda ortaya çıkan, esnaf ve zanaatkârları bir araya getirerek meslek eğitimini ahlak eğitimiyle birlikte veren dayanışma teşkilatıdır.","ornek":"Bir Anadolu şehrinde dericiler, bakırcılar, demirciler: her meslek kendi çarşısında, aynı kurallara bağlı olarak çalışır; yapılan iş teşkilatın denetiminden geçer.","sektor":"Programın anahtar kavramlarındandır. Ahilikte iyi usta olmanın yolu iyi insan olmaktan geçerdi. Bu anlayış bugünün otelciliğinde de geçerlidir: teknik beceri öğretilir, güven ise dürüstlükle kazanılır.","iliskili":["mg-2-027","mg-2-028","mg-2-029","mg-2-030"],"kontrol":null,"gorsel":"m1-ahi-evran-turbesi"},{"id":"mg-2-027","konu":"2.2","terim":"Ahi Evran","ingilizce":"Ahi Evran (regarded as the founder of the Ahi brotherhood)","tanim":"Ahilik teşkilatının kurucusu kabul edilen, 13. yüzyılda Anadolu’da yaşamış ve dericilerin (debbağların) piri sayılan kişidir.","ornek":"Kırşehir’e giden bir okul gezisinde öğrenciler Ahi Evran’ın türbesini ziyaret eder; Kırşehir, Ahilikle birlikte anılan şehirdir.","sektor":"Kendisinin de dericilik yaptığı anlatılır. Pir, bir mesleğin kurucusu ve koruyucusu sayılan kişi demektir. Ahi Evran’ın adı, mesleği ahlakla birlikte öğretme geleneğinin simgesidir.","iliskili":["mg-2-026","mg-2-028","mg-2-045"],"kontrol":null,"gorsel":"t13d-ahi-evran-turbesi"},{"id":"mg-2-028","konu":"2.2","terim":"Fütüvvet","ingilizce":"Futuwwa","tanim":"Cömertlik, yiğitlik, yardımseverlik ve doğruluk gibi erdemleri esas alan ve Ahiliğin ahlaki temelini oluşturan anlayıştır.","ornek":"Kazancının bir kısmını zor durumdaki komşu esnafla paylaşan, yolcuya sofrasını açan usta bu anlayışla davranmış olur.","sektor":"Programın anahtar kavramlarındandır. Ahiler bu anlayışı iş hayatına taşıdı: iyi insan olmak ile iyi meslek sahibi olmak birbirinden ayrılmadı. Ahilerin yolcuyu ağırlaması, konukseverlik geleneğimizin bilinen örneklerinden sayılır.","iliskili":["mg-2-026","mg-2-036","mg-2-038"],"kontrol":null},{"id":"mg-2-029","konu":"2.2","terim":"Esnaf ve zanaatkâr","ingilizce":"Tradesman and craftsman","tanim":"Küçük sermayeyle kendi dükkânında mal satan ya da el emeği ve ustalıkla ürün ortaya koyan meslek sahipleridir.","ornek":"Çarşıda bakır tepsiyi kendi eliyle döven bakırcı zanaatkâr, onu tezgâhında satan dükkân sahibi esnaftır; çoğu zaman ikisi aynı kişidir.","sektor":"Turistin bir şehirde en iyi hatırladığı yerlerden biri çarşısıdır. Dürüst esnaf o şehrin tanıtımını yapar; turisti aldatan tek bir dükkân ise bütün çarşının adını lekeler.","iliskili":["mg-2-026","mg-2-033","mg-2-044"],"kontrol":null},{"id":"mg-2-030","konu":"2.2","terim":"Usta-çırak modeli","ingilizce":"Master–apprentice model","tanim":"Mesleğin iş başında, deneyimli bir ustanın yanında çalışıp onu izleyerek basamak basamak öğrenildiği eğitim biçimidir.","ornek":"Çömlekçi atölyesinde usta çarkı çevirir; çırak önce izler, sonra çamuru yoğurur, zamanla ilk çömleğini kendi yapar.","sektor":"Staj bu modelin bugünkü hâlidir: otelde deneyimli bir personelin yanında işi görerek öğrenirsin. Ahilikte usta yalnız işi değil, doğru davranışı da öğretirdi.","iliskili":["mg-2-031","mg-2-032","mg-2-033","mg-2-026"],"kontrol":null},{"id":"mg-2-031","konu":"2.2","terim":"Çırak","ingilizce":"Apprentice","tanim":"Ahilikte yamaklık döneminden sonra ustanın yanında mesleği öğrenmeye devam eden, gelişimi usta tarafından izlenen kişidir.","ornek":"Mutfağa ilk gün giren stajyer önce sebze yıkar, doğramayı izler, malzemelerin yerini öğrenir.","sektor":"Programın anahtar kavramlarındandır. Çıraklık küçümsenecek bir dönem değildir: her usta bir gün çıraktı. Bu dönemde en değerli beceri izlemek, sormak ve söyleneni eksiksiz yapmaktır.","iliskili":["mg-2-030","mg-2-032","mg-2-033"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-032","konu":"2.2","terim":"Kalfa","ingilizce":"Journeyman","tanim":"Çıraklığı tamamlamış, işi kendi başına yapabilen ama henüz ustalığa yükselmemiş meslek elemanıdır.","ornek":"Terzi dükkânında dikişi artık tek başına yapan, kalıbı ise hâlâ ustasına danışarak çıkaran çalışan.","sektor":"Programın anahtar kavramlarındandır. Kalfa hem öğrenir hem öğretir: ustasından işin inceliğini alırken çırağa yol gösterir. Otelde yeni stajyere işi gösteren deneyimli personel bu rolü üstlenir.","iliskili":["mg-2-031","mg-2-033","mg-2-034"],"kontrol":null,"cizim":"bavul"},{"id":"mg-2-033","konu":"2.2","terim":"Usta","ingilizce":"Master craftsman","tanim":"Mesleğinin bütün inceliklerini bilen, kendi iş yerini açabilen ve çırak ile kalfa yetiştiren kişidir.","ornek":"Yıllarını mutfakta geçirmiş aşçıbaşı hem yemeğin son hâline karar verir hem de yanındaki gençleri yetiştirir.","sektor":"Programın anahtar kavramlarındandır. Ahilikte ustalık yalnız el becerisi değildi; ahlakı ve davranışıyla örnek olmak da beklenirdi. Ustanın en kalıcı eseri yetiştirdiği insandır.","iliskili":["mg-2-031","mg-2-032","mg-2-035","mg-2-029"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-2-034","konu":"2.2","terim":"Şed kuşanma","ingilizce":"Girding ceremony (şed)","tanim":"Ahilikte meslekte bir üst basamağa yükselmeye hak kazanan kişinin beline, şed adı verilen kuşağın törenle bağlanmasıdır.","ornek":"Günümüzde Ahilik Kültürü Haftası etkinliklerinde bu tören temsilî olarak canlandırılır: usta yetiştirdiği gencin beline kuşağı herkesin önünde bağlar.","sektor":"Programın anahtar kavramlarındandır. Kuşak, “Bu kişi işini ve ahlakını kanıtladı” demenin herkesin önünde yapılan ilanıdır: yükselme kayırmayla değil, hak ederek olur. Bugün kalfalık ve ustalık belgelerinin törenle verilmesi buna benzetilebilir.","iliskili":["mg-2-032","mg-2-033","mg-2-035"],"kontrol":null},{"id":"mg-2-035","konu":"2.2","terim":"Liyakat","ingilizce":"Merit","tanim":"Bir görevin ya da unvanın o işi yapacak bilgi, beceri ve ahlaka sahip olan, yani onu hak eden kişiye verilmesidir.","ornek":"Otelde kat şefliği boşalır; görev, müdürün tanıdığına değil, işi en iyi bilen ve ekibin güvendiği personele verilir.","sektor":"Programın anahtar kavramlarındandır. Ahilikte bir üst basamağa geçmek için işini ve ahlakını kanıtlamak gerekirdi. Liyakatin olduğu iş yerinde çalışan “Emeğim görülüyor” der.","iliskili":["mg-2-018","mg-2-033","mg-2-034","mg-2-006"],"kontrol":null,"cizim":"uniforma"},{"id":"mg-2-036","konu":"2.2","terim":"Dayanışma","ingilizce":"Solidarity","tanim":"Bir topluluğun üyelerinin zor zamanda birbirine destek olması ve yükü birlikte taşımasıdır.","ornek":"Kalabalık bir grubun aynı anda geldiği akşam, işi biten garsonlar gitmeden önce bulaşıkhanedeki arkadaşlarına yardım eder.","sektor":"Programın anahtar kavramlarındandır. Ahi esnafının zor duruma düşen meslektaşına sahip çıktığı anlatılır. Otelde de departmanlar birbirine muhtaçtır: oda hazır değilse resepsiyon konuğu yerleştiremez.","iliskili":["mg-2-026","mg-2-028","mg-2-043"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-039","konu":"2.2","terim":"Kalite","ingilizce":"Quality","tanim":"Bir ürünün ya da hizmetin vaat edilen özellikleri taşıması ve kullananın beklentisini karşılamasıdır.","ornek":"İnternette “deniz manzaralı” diye satılan odanın penceresinden gerçekten deniz görünmesi.","sektor":"Programın anahtar kavramlarındandır. Ahilikte kalitesiz iş çıkarmak yalnız beceriksizlik değil, müşteriye haksızlık sayılırdı. Otelde kalite tek kişinin işi değildir; bir bölümün özensizliği herkesin emeğini boşa çıkarır.","iliskili":["mg-2-040","mg-2-041","mg-2-042"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-2-040","konu":"2.2","terim":"Kalite kontrol","ingilizce":"Quality control","tanim":"Üretilen malın ya da verilen hizmetin belirlenen standarda uyup uymadığının denetlenmesidir.","ornek":"Kat şefi temizlenen odayı konuk gelmeden önce kontrol eder: çarşaf, banyo, minibar, havlu sayısı.","sektor":"Ahi teşkilatı esnafın malını ve işçiliğini denetlerdi, kusurlu malın satılmasını hoş görmezdi. Bugün otellerde oda kontrolü, denetimler ve konuk anketleri aynı işi görür.","iliskili":["mg-2-039","mg-2-041","mg-2-042"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-2-041","konu":"2.2","terim":"Tüketiciyi koruma","ingilizce":"Consumer protection","tanim":"Mal ya da hizmet satın alan kişinin aldatılmasını ve zarara uğramasını önlemeye yönelik kural ve uygulamaların bütünüdür.","ornek":"Otelin oda fiyatını ve fiyata nelerin dâhil olduğunu rezervasyon sırasında açıkça bildirmesi.","sektor":"Ahilikte ölçüde, tartıda ve malda hile yapan esnafa yaptırım uygulanırdı; amaç müşterinin çarşıya güvenmesiydi. Güvenen müşteri yine gelir: bugün buna konuk memnuniyeti diyoruz.","iliskili":["mg-2-037","mg-2-040","mg-2-042"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-042","konu":"2.2","terim":"Pabucu dama atılmak","ingilizce":"Having one’s shoes thrown on the roof (public disgrace; Ahi idiom)","tanim":"Gözden düşmek, önemini yitirmek anlamına gelen ve Ahilikte kusurlu mal satan esnafın pabucunun dama atılması geleneğine dayandırılan deyimdir.","ornek":"Bugünkü karşılığı: konuğunu aldatan bir işletme hakkında internete yazılan düşük puanlı yorumlar; herkes görür, itibar düşer.","sektor":"Anlatılan gelenekte asıl ceza itibar kaybıdır: herkes o esnafın işini kötü yaptığını öğrenir. İnternetteki konuk puanları ve yorumları benzer bir iş görür: dürüst işletmeyi öne çıkarır, konuğun güvenini korur.","iliskili":["mg-2-040","mg-2-041","mg-2-044"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-054","konu":"2.2","terim":"Yamak","ingilizce":"Novice (yamak)","tanim":"Ahilikte mesleğe ilk adımını atan, çıraklıktan önceki en alt basamaktaki kişidir.","ornek":"Kayseri’de bir yemeni atölyesine yeni giren genç önce ortalığı toplar ve ustanın işini uzaktan izler; bu dönem yamaklıktır.","sektor":"Mesleğe başlayanlar önce yamak, sonra çırak, kalfa ve usta basamaklarından geçer; bu sıra bugünkü staj ve kıdem basamaklarına benzetilebilir.","iliskili":["mg-2-055","mg-2-031","mg-2-032"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-055","konu":"2.2","terim":"Usta-çırak hiyerarşisi","ingilizce":"Master–apprentice hierarchy","tanim":"Ahilikte yamak, çırak, kalfa ve usta basamaklarından oluşan mesleki yükselme sırasıdır.","ornek":"Bir ahi atölyesinde yamak ortalığı toplar, çırak malzemeyi hazırlar, kalfa işi tek başına yapar, usta son kararı verir.","sektor":"Her basamağa bilgi ve beceri geliştikçe çıkılır; Ahilikte yükselme yalnız zamana değil yeterlik kanıtına bağlıdır.","iliskili":["mg-2-054","mg-2-030","mg-2-033"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-056","konu":"2.2","terim":"Yaparak öğrenme","ingilizce":"Learning by doing","tanim":"Bir mesleğin inceliklerini yalnız dinleyerek değil, iş başında uygulayarak öğrenme biçimidir.","ornek":"Çırak ilk gün yalnız anlatılanı dinlemez; ustasının gözetiminde kendi eliyle bir deri parçasını keser.","sektor":"Ahilik eğitiminde yaparak öğrenme önemli yer tutar. Bugünkü staj ve atölye çalışması aynı mantığa dayanır.","iliskili":["mg-2-030","mg-2-031"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-2-057","konu":"2.2","terim":"İyi insan, iyi meslek erbabı","ingilizce":"Good person, good tradesperson","tanim":"Ahilikte bir kişinin yalnız işini iyi yapmasının yetmediği, aynı zamanda dürüst, güvenilir ve topluma yararlı olması gerektiği anlayışıdır.","ornek":"Bir usta, çırak adayını yalnız el becerisine göre değil, dürüstlüğüne ve saygısına göre de değerlendirir.","sektor":"Ahilik teşkilatının temelindeki anlayış budur; bugün işe alımda tutum ve güvenilirliğin aranmasıyla örtüşür.","iliskili":["mg-2-026","mg-2-035"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-2-058","konu":"2.2","terim":"Peştamal","ingilizce":"Peshtemal (ceremonial waist cloth)","tanim":"Şed kuşanma töreninde kuşakla birlikte anılan, kişinin meslekte yetkin kabul edildiğini simgeleyen kumaştır.","ornek":"Temsilî bir Ahilik töreninde usta kalfanın beline peştamalı herkesin önünde bağlar.","sektor":"Törende bağlanan kuşak ya da peştamal, kişinin meslekte güvenilir ve yetkin sayıldığını simgeler.","iliskili":["mg-2-034","mg-2-035"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-059","konu":"2.2","terim":"Haksız rekabet","ingilizce":"Unfair competition","tanim":"Başkasının müşterisini ya da emeğini haksız yollarla kendine çekmeye çalışarak yapılan ticari yarıştır.","ornek":"Çarşıda bir esnafın komşusunun müşterisine yanıltıcı bir fiyat söyleyerek kendi dükkânına çağırması.","sektor":"Ahilikte haksız rekabetten kaçınmak, komşu esnafın hakkını gözetmenin parçasıdır. Turizmde rakip otelin kötülenmesi aynı kapıya çıkar.","iliskili":["mg-2-041","mg-2-060"],"kontrol":null,"cizim":"festival"},{"id":"mg-2-060","konu":"2.2","terim":"Tüketici hakları","ingilizce":"Consumer rights","tanim":"Mal ya da hizmet satın alan kişinin aldatılmama ve zarar görürse hakkını arayabilme gibi korunan haklarıdır.","ornek":"Konuk, rezervasyonda gördüğü deniz manzaralı oda yerine bahçe manzaralı odaya yerleştirilince itiraz eder ve hakkını resepsiyonda arar.","sektor":"Tüketici mağdur olduğunda hakkını arayabilir; bu, Ahilikteki tüketiciyi koruma anlayışının göstergesidir.","iliskili":["mg-2-041","mg-2-061"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-061","konu":"2.2","terim":"Garanti","ingilizce":"Warranty","tanim":"Satılan ürünün ya da yapılan işin belirli süre içinde sorun çıkarırsa düzeltileceğine dair verilen güvencedir.","ornek":"Saat 15.00, otelin klima servisi yaptığı tamirde aynı arıza tekrar ederse ücretsiz düzelteceğini yazılı bildirir.","sektor":"Garanti uygulamaları, Ahilikteki tüketiciyi koruma anlayışının bugünkü karşılıklarındandır.","iliskili":["mg-2-060","mg-2-062"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-062","konu":"2.2","terim":"Müşteri memnuniyeti","ingilizce":"Customer satisfaction","tanim":"Hizmet alan kişinin aldığı ürün ya da hizmetin beklentisini karşıladığını düşünmesidir.","ornek":"Konuk, check-out sırasında odanın temizliğinden ve çalışanların ilgisinden memnun olduğunu anketle bildirir.","sektor":"Müşteri memnuniyeti, Ahilikteki tüketiciyi koruma anlayışının bugünkü karşılıklarındandır. Memnun konuk tekrar gelir ve çevresine önerir.","iliskili":["mg-2-060","mg-2-061"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"mg-2-064","konu":"2.2","terim":"Ahi Duası","ingilizce":"Ahi Prayer","tanim":"Ahilerin dürüst kazanç, ölçüye ve tartıya dikkat, başkalarına faydalı olmak gibi dileklerini anlatan manevi metindir.","ornek":"Okulda Atölye Görevi 2.2 sırasında öğrenciler duayı okur ve ölçüye ve tartıya dikkat etmenin iş yaşamındaki karşılığını tartışır.","sektor":"Dürüstlük ve helal kazanç vurgusu meslek ahlakıyla örtüşür; metin etik değerleri anlamak için kaynak olarak okunur.","iliskili":["mg-2-057","mg-2-037"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-020","konu":"2.3","terim":"Etik ikilem","ingilizce":"Ethical dilemma","tanim":"Kişinin birbiriyle çatışan iki değer ya da sorumluluk arasında kalarak doğru davranışa karar vermekte zorlandığı durumdur.","ornek":"Yakın arkadaşın olan stajyerin konuk ikramlarından aldığını görürsün: bir yanda arkadaşlık, öbür yanda dürüstlük vardır.","sektor":"İkilemde üç soru yol gösterir: Kurala ve ilkelere uygun mu? Birine zarar veriyor mu? Bunu şefimin yanında da yapar mıydım? Karar veremediğinde tek başına kalma; amirine danış.","iliskili":["mg-2-011","mg-2-025","mg-2-016"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-023","konu":"2.3","terim":"Doğruluk ve tutarlılık","ingilizce":"Integrity","tanim":"Kimse görmese ve denetlemese de doğru bildiği ilkelere uygun davranmaktır.","ornek":"Gece 03.00, boş koridor: bellboy yerde bulduğu cüzdanı açmadan resepsiyona götürüp kayıt altına aldırır.","sektor":"Sektörde “integrity” denir; iş ilanlarında ve personel değerlendirmelerinde geçer. Dürüstlüğün bir kerelik değil, her koşulda aynı kalan hâlidir; günlük dilde buna “özü sözü bir olmak” denir.","iliskili":["mg-2-012","mg-2-013","mg-2-038"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-2-047","konu":"2.3","terim":"Güvenilirlik","ingilizce":"Trustworthiness","tanim":"Söz ve davranışlarında tutarlı ve doğru olup başkalarının kendisine rahatça güvenebilmesini sağlamaktır.","ornek":"Saat 09.00, otelde kat şefi “Odayı 10.00’a kadar hazır ederim” der ve söylediği saatte hazır eder; resepsiyon ona bu yüzden işini rahatça emanet eder.","sektor":"Konuk güveni bir kez sarsılırsa yerine gelmesi zordur; ekip içinde de güvenilir kişi daha fazla sorumluluk alır.","iliskili":["mg-2-012","mg-2-023","mg-2-041"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-048","konu":"2.3","terim":"Hilesiz mal satma","ingilizce":"Honest trading","tanim":"Satılan malın kusurunu gizlemeden, ölçüsünü ve kalitesini olduğundan farklı göstermeden satmaktır.","ornek":"Ahi esnafı dükkânındaki kumaşın ölçüsünü eksiksiz keser ve lekeli parçayı lekeli olduğunu söyleyerek satar.","sektor":"Bugünkü tüketiciyi koruma anlayışının köklerinden biri sayılır; otelde odanın gerçek hâlini ve mesafeleri doğru anlatmak aynı ilkedir.","iliskili":["mg-2-041","mg-2-047","mg-2-012"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-043","konu":"2.3","terim":"Sosyal sorumluluk","ingilizce":"Social responsibility","tanim":"Kişinin ya da işletmenin kendi kazancının ötesinde topluma ve çevreye karşı da görevleri olduğunu bilerek davranmasıdır.","ornek":"Bir otelin çalışanlarıyla birlikte sahil temizliğine katılması ya da yakındaki bir okulun ihtiyacına destek olması.","sektor":"Programın anahtar kavramlarındandır. Ahilikte esnaftan kazancıyla yoksulu, yolcuyu ve zor durumdaki meslektaşını gözetmesi beklenirdi. Bugün işletmeler buna kurumsal sosyal sorumluluk der.","iliskili":["mg-2-007","mg-2-036","mg-2-013"],"kontrol":null},{"id":"mg-2-044","konu":"2.3","terim":"Mesleki saygınlık","ingilizce":"Professional reputation","tanim":"Bir mesleğin ve o mesleği yapanların toplum gözündeki güvenilirliği ve itibarıdır.","ornek":"Bir tatil beldesinde turistin aldatıldığı duyulursa dürüst esnafa da şüpheyle bakılır; dürüst davranış ise herkesin adını yükseltir.","sektor":"Saygınlığı tek tek çalışanların davranışları oluşturur. Üniformayı giydiğinde yalnız kendini değil, otelini ve turizm mesleğini temsil edersin.","iliskili":["mg-2-010","mg-2-007","mg-2-042"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-2-045","konu":"2.3","terim":"Ahilik Kültürü Haftası","ingilizce":"Ahi Culture Week","tanim":"Türkiye’de her yıl, Ahilik değerlerini tanıtmak ve yaşatmak amacıyla etkinliklerle kutlanan haftadır.","ornek":"Hafta boyunca okullarda Ahilik anlatılır, esnaf ziyaret edilir, şed kuşanma töreni temsilî olarak canlandırılır; Kırşehir kutlamalarıyla öne çıkan şehirdir.","sektor":"Yüzyıllar öncesinin değerlerinin bugün hâlâ konuşulmasının nedeni basittir: dürüstlük, kalite ve dayanışma eskimez. Okulunun o haftaki etkinliklerine turizm öğrencisi gözüyle katıl.","iliskili":["mg-2-026","mg-2-027","mg-2-034"],"kontrol":null,"gorsel":"m1-ahi-evran-gece"},{"id":"mg-2-065","konu":"2.3","terim":"Orta sandığı","ingilizce":"Ahi mutual-aid fund (orta sandığı)","tanim":"Ahilikte esnafın zor durumdaki meslektaşlarına ve ihtiyaç sahiplerine destek olmak için oluşturduğu yardımlaşma düzenidir.","ornek":"Kayseri’de bir esnafın dükkânı yanınca, çarşı esnafı orta sandığından ona yeni tezgâh ve malzeme için yardım eder.","sektor":"Bugünkü karşılığı sosyal sorumluluk çalışmaları ve çalışan dayanışmasıdır; otelde çalışanların kendi aralarında kurduğu yardımlaşma düzeni buna benzer.","iliskili":["mg-2-036","mg-2-043","mg-2-074"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-066","konu":"2.3","terim":"Siftah","ingilizce":"First sale of the day (siftah)","tanim":"Esnafın gün içindeki ilk satışına verilen addır.","ornek":"Sabah 09.00, çarşıda baharatçı ilk satışını yapar ve sonraki müşteriyi henüz satış yapmamış komşusuna yönlendirir.","sektor":"İlk satışını yapan esnafın müşteriyi henüz satış yapmamış komşusuna yönlendirmesi, dayanışma ve hakkaniyet örneğidir.","iliskili":["mg-2-036","mg-2-069"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-067","konu":"2.3","terim":"Karakter gelişimi","ingilizce":"Character development","tanim":"Kişinin doğruyu yanlıştan ayırabilmesi, davranışlarının sonuçlarını düşünebilmesi ve değerlerine uygun hareket edebilmesidir.","ornek":"Stajyer yanlışlıkla bir tabağı kırınca saklamak yerine şefine bildirir; zor olan doğruyu seçmeyi öğrenir.","sektor":"Ahilik kültürünün katkılarından biridir. Karakteri güçlü meslek elemanı iş yaşamında daha güvenilir ve saygın olur.","iliskili":["mg-2-012"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-069","konu":"2.3","terim":"Biz bilinci","ingilizce":"Sense of ‘we’","tanim":"Kişinin yalnız kendi kazancını değil, çevresindeki insanların durumunu da düşünerek davranmasıdır.","ornek":"Banket akşamı yoğunlukta mutfak, servis ve bulaşıkhane birbirini beklemeden yardım eder.","sektor":"Ahilik kültürü ben yerine biz bilincini öne çıkarır; iş yerinde iş birliğini güçlendirir.","iliskili":["mg-2-036","mg-2-066"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-071","konu":"2.3","terim":"Sabır","ingilizce":"Patience","tanim":"Öfkeye kapılmadan zorlukları ve beklemeyi ölçülü karşılamaktır.","ornek":"Saat 12.00, şikâyet eden konuğu sakin sesle sonuna kadar dinlemek ve sonra çözüm önermek.","sektor":"Sabır, Ahilik erdemlerindendir. Zor konukla çalışırken en çok işe yarayan niteliklerden biridir.","iliskili":["mg-2-072"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-2-072","konu":"2.3","terim":"Mütevazılık","ingilizce":"Modesty","tanim":"Başarılı olsa bile kendini olduğundan üstün göstermemek, alçak gönüllü davranmaktır.","ornek":"Ödüllü aşçı aldığı övgüyü ekibiyle paylaşır ve mutfağı ekip sayesinde yürüttüğünü söyler.","sektor":"Mütevazılık, Ahilik erdemlerindendir.","iliskili":["mg-2-071","mg-2-073"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-073","konu":"2.3","terim":"Güler yüzlülük","ingilizce":"Cheerful courtesy","tanim":"İnsanlarla ilişkide sıcak, yumuşak ve nazik davranmaktır.","ornek":"Resepsiyon görevlisi gece yarısı gelen yorgun konuğu gülümseyerek karşılar.","sektor":"Güler yüzlü olmak Ahilik erdemlerindendir; konuk memnuniyetinin ilk basamağıdır.","iliskili":["mg-2-072"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-2-074","konu":"2.3","terim":"Yardımlaşma","ingilizce":"Mutual aid","tanim":"İnsanların birbirinin ihtiyacına destek olmasıdır.","ornek":"Bayram yoğunluğunda bir otelin mutfak ekibi bulaşıkhanede işi yetişmeyen arkadaşlarına yardım eder.","sektor":"Yardımlaşma, Ahilik erdemlerindendir; orta sandığı bunun kurumlaşmış hâlidir.","iliskili":["mg-2-065","mg-2-036"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-076","konu":"2.3","terim":"Ahi","ingilizce":"Ahi","tanim":"Denge ve düzen kuran, dürüstlük, dayanışma ve sorumlulukla toplumun huzuruna katkı sağlayan kişidir.","ornek":"Çarşıda anlaşmazlık çıkınca araya girip esnafı uzlaştıran saygın usta ahi anlayışının örneğidir.","sektor":"Ahi dağıtan değil toparlayan, yıkan değil yapan kişidir.","iliskili":["mg-2-026","mg-2-069"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-077","konu":"2.3","terim":"Hile","ingilizce":"Fraud (deceit in trade)","tanim":"Satılan malın kusurunu ya da ölçüsünü gizleyerek müşteriyi aldatmaktır.","ornek":"Çarşıda bir tezgâhtar kumaşı eksik ölçerek satar.","sektor":"Hileli mal satmak, eksik tartmak ve müşteriyi yanıltmak Ahilik kültüründe doğru kabul edilmez.","iliskili":["mg-2-048"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-079","konu":"2.3","terim":"Çalışma ve Sosyal Güvenlik Bakanlığı","ingilizce":"Ministry of Labour and Social Security","tanim":"İşçi ve işveren ilişkilerini, çalışma koşullarını ve sosyal güvenlik düzenini yürüten bakanlıktır.","ornek":"Bir otel çalışanı çalışma koşullarıyla ilgili sorusunu bu bakanlığın birimlerine iletir.","sektor":"Bu bakanlığın görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-080","mg-2-081"],"kontrol":null,"cizim":"uyari"},{"id":"mg-2-080","konu":"2.3","terim":"Sanayi ve Teknoloji Bakanlığı","ingilizce":"Ministry of Industry and Technology","tanim":"Ülkenin sanayi ve teknoloji politikalarını yürüten bakanlıktır.","ornek":"Küçük bir üretici makine yatırımı için sanayi desteklerini bu bakanlığın birimlerinden öğrenir.","sektor":"Bu bakanlığın görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-079","mg-2-081"],"kontrol":null,"cizim":"dijital"},{"id":"mg-2-081","konu":"2.3","terim":"Ticaret ve sanayi odası","ingilizce":"Chamber of commerce and industry","tanim":"Bir şehirdeki tüccar ve sanayicileri bir araya getiren, meslek çıkarlarını koruyan kuruluştur.","ornek":"Bir otel işletmecisi yerel odanın toplantısında şehrin turizm sorunlarını anlatır.","sektor":"Odaların görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-082","mg-2-080"],"kontrol":null,"cizim":"oda"},{"id":"mg-2-082","konu":"2.3","terim":"Türkiye Esnaf ve Sanatkârlar Konfederasyonu (TESK)","ingilizce":"Confederation of Turkish Tradesmen and Craftsmen (TESK)","tanim":"Esnaf ve sanatkâr kuruluşlarının üst çatısı olarak esnafın sorunlarını temsil eden kuruluştur.","ornek":"Bir bölgenin esnaf odası başkanı sorunlarını konfederasyon aracılığıyla ülke geneline duyurur.","sektor":"TESK’in görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-081","mg-2-083"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-2-083","konu":"2.3","terim":"Sendika","ingilizce":"Trade union","tanim":"Çalışanların haklarını korumak ve çalışma koşullarını iyileştirmek için kurduğu örgüttür.","ornek":"Otel çalışanları çalışma saatleriyle ilgili ortak taleplerini sendika aracılığıyla işverene iletir.","sektor":"Sendikaların görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-082","mg-2-084"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-084","konu":"2.3","terim":"Vakıf","ingilizce":"Foundation (waqf)","tanim":"Topluma yararlı hizmetleri sürdürmek için mal ve gelir ayrılarak kurulan kuruluştur.","ornek":"Bir vakıf yaz boyunca turizm öğrencilerine burs verir.","sektor":"Vakıfların görevlerine benzer işleri eskiden Ahilik teşkilatı yürütürdü.","iliskili":["mg-2-083","mg-2-065"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-018","konu":"2.4","terim":"Kayırmacılık","ingilizce":"Favouritism","tanim":"Bir işte ya da kararda yeteneğe ve hakka değil, akrabalığa, arkadaşlığa ya da kişisel yakınlığa göre öncelik tanınmasıdır.","ornek":"Bir bölüm şefinin en rahat vardiyaları her hafta yalnız yakın arkadaşına vermesi.","sektor":"Kayırmacılık liyakatin tersidir: hak eden geride kalır, ekipte güven ve çalışma isteği azalır. Konuklar arasında yapıldığında sırada bekleyenin hakkı yenir.","iliskili":["mg-2-015","mg-2-035","mg-2-006"],"kontrol":null},{"id":"mg-2-025","konu":"2.4","terim":"Etik ihlal bildirimi","ingilizce":"Whistleblowing","tanim":"Çalışanın iş yerinde gördüğü etik dışı ya da kural dışı bir durumu yetkili kişiye ya da birime haber vermesidir.","ornek":"Bir stajyer depodan düzenli olarak izinsiz malzeme çıkarıldığını fark eder ve durumu bölüm şefine anlatır.","sektor":"Sektörde “whistleblowing” denir. Amaç kimseyi küçük düşürmek değil, konuğu, ekibi ve işletmeyi zarardan korumaktır. Bazı işletmelerde bunun için ayrı bir etik hattı bulunur.","iliskili":["mg-2-004","mg-2-016","mg-2-020"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-2-037","konu":"2.4","terim":"Helal kazanç","ingilizce":"Honest earnings","tanim":"Emeğin karşılığı olarak, kimseyi aldatmadan ve kimsenin hakkını yemeden elde edilen kazançtır.","ornek":"Pazarda terazisini doğru tartan, çürük meyveyi kasanın altına saklamayan satıcının akşam evine götürdüğü para.","sektor":"Programın anahtar kavramlarındandır. Ahilikte kazancın çokluğundan önce hilesiz olmasına önem verilirdi. Otelde karşılığı açıktır: konuğa söylenen fiyat ile hesaba yazılan aynıdır; verilmeyen hizmetin parası alınmaz.","iliskili":["mg-2-012","mg-2-038","mg-2-041"],"kontrol":null},{"id":"mg-2-086","konu":"2.4","terim":"Kul hakkı","ingilizce":"Rights of others (kul hakkı)","tanim":"Başkasının emeğine, malına ve hakkına haksız yere zarar verilmemesi gerektiği anlayışıdır.","ornek":"Stajyer arkadaşının hazırladığı raporu kendi adıyla sunmaz.","sektor":"Kul hakkını gözetmek Ahilik değerlerindendir; iş arkadaşının emeğini sahiplenmemek bunun günlük karşılığıdır.","iliskili":["mg-2-077","mg-2-012","mg-2-008"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-087","konu":"2.4","terim":"Ahlaki sorun (etik sorun)","ingilizce":"Ethical problem","tanim":"İş yaşamında doğru ile yanlış ya da çıkar ile ilke arasında kalınan ve çevreyi etkileyen sorundur.","ornek":"Atölyede ustanın standart dışı malzeme kullandırması ve çalışanların bunu bildiği hâlde susması.","sektor":"Ahlaki sorun yalnız bir kişiyi değil, güveni, kaliteyi, müşteriyi ve mesleğin itibarını da etkiler.","iliskili":["mg-2-088","mg-2-093"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-2-088","konu":"2.4","terim":"Aşırı kâr hırsı","ingilizce":"Excessive profit-seeking","tanim":"İşletmenin yalnız kazancı düşünüp kaliteyi, güvenliği ve müşterinin hakkını ikinci plana atmasıdır.","ornek":"Bir restoranın maliyeti düşürmek için bozulmaya yakın malzemeyi kullanması.","sektor":"Ahlaki sorunların başlıca nedenlerinden biridir.","iliskili":["mg-2-087"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-2-089","konu":"2.4","terim":"Sorumluluktan kaçma","ingilizce":"Evasion of responsibility","tanim":"Çalışanın gördüğü yanlışı dile getirmemesi ya da kendi görev alanındaki hatayı başkasına yüklemesidir.","ornek":"Garson, kırılan bardağı “ben değil, arkadaşım” diyerek yansıtır.","sektor":"Ahlaki sorunların başlıca nedenlerinden biridir.","iliskili":["mg-2-087","mg-2-025"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-090","konu":"2.4","terim":"Liyakat eksikliği","ingilizce":"Lack of merit","tanim":"Bir görevin bilgisi, becerisi ve ahlaki sorumluluğu olan kişiye verilmemesidir.","ornek":"Otelde şeflik, işi bilmeyen ama yöneticinin akrabası olan kişiye verilir.","sektor":"Ahlaki sorunların başlıca nedenlerinden biridir.","iliskili":["mg-2-035","mg-2-087"],"kontrol":null,"cizim":"uniforma"},{"id":"mg-2-091","konu":"2.4","terim":"Denetim yetersizliği","ingilizce":"Lack of oversight","tanim":"Üretim ya da hizmet sürecinde kalite kontrolün ve etik denetimin yapılmaması durumudur.","ornek":"Mutfakta soğuk oda ısısı hiç kontrol edilmez ve bozulan ürün konuğa servis edilir.","sektor":"Ahlaki sorunların başlıca nedenlerinden biridir.","iliskili":["mg-2-087","mg-2-040"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-2-092","konu":"2.4","terim":"Dayanışma eksikliği","ingilizce":"Lack of solidarity","tanim":"Çalışanların ortak yararı düşünmek yerine yalnız kendi çıkarını korumaya çalışmasıdır.","ornek":"Vardiya sonunda ekip kendi işini bitirip yoğunlukta olan arkadaşına yardım etmeden çıkar.","sektor":"Ahlaki sorunların başlıca nedenlerinden biridir.","iliskili":["mg-2-036","mg-2-087"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-2-093","konu":"2.4","terim":"Nedensel ilişki kurma","ingilizce":"Establishing cause and effect","tanim":"Bir sorunun hangi ilkeye aykırı olduğunu ve hangi sonuçlara yol açtığını açıklayabilmektir.","ornek":"Standart dışı malzeme kullanımı kalite ve dürüstlük ilkesine aykırıdır; müşteri mağdur olur, işletmenin güveni sarsılır.","sektor":"Ahilik temelli çözüm üretmek, değerleri saymaktan ibaret değildir; asıl iş bu neden-sonuç ilişkisini kurmaktır.","iliskili":["mg-2-087","mg-2-094"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-2-094","konu":"2.4","terim":"Etik çözüm planı (eylem planı)","ingilizce":"Ethical action plan","tanim":"Bir etik sorunun tanımını, nedenlerini, ilgili değerlerini, çözüm adımlarını ve beklenen sonuçlarını sırayla gösteren plandır.","ornek":"Bir otel stajyeri kusurlu ürün sorununu tanımlar, nedenlerini yazar, çözüm adımlarını ve sorumlularını sıralar.","sektor":"Planın bölümleri şunlardır: sorunun tanımı, nedenleri, ilgili Ahilik değerleri, çözüm adımları, paydaşların görevleri, beklenen sonuçlar ve çözümün nasıl izleneceği.","iliskili":["mg-2-093"],"kontrol":null,"cizim":"etik-terazi"}],"acikSorular":[{"id":"mg-2-y01","konu":"2.1","soru":"Yazılı olmayan kurallar ile yazılı kurallar arasındaki farkı belirtiniz. Bir esnaf odasında üyeler arasında “sözünü tutmak” yazılı olmayan bir kuraldır; bu kuralın iş yerindeki işlevini, toplumsal faydasını ve uyulmadığında doğabilecek sonucu açıklayınız.","olcut":[{"metin":"Yazılı olmayan kuralı yazılı kuraldan ayırt eder.","puan":25},{"metin":"Bu kuralın iş yerindeki işlevini açıklar.","puan":25},{"metin":"Bu kuralın toplumsal faydasını açıklar.","puan":25},{"metin":"Kuralın uyulmadığında ortaya çıkabilecek sonuçları bir örnekle açıklar.","puan":25}],"ornek":"Yazılı olmayan kural, belgede olmadığı hâlde toplulukta uyulması beklenen davranıştır. Sözünü tutmak, üyeler arasında güveni sağlar ve iş birliğini kolaylaştırır. Toplumsal fayda: ticaret daha güvenilir ve adil olur. Uyulmadığında, bir üyenin verdiği sözü tutmaması diğer üyelerin işini ve güvenini zedeler.","ipucu":"Yazılı olmayan kuralı, toplumun güvenini sağlayan bir davranış olarak düşünün."},{"id":"mg-2-y02","konu":"2.4","soru":"Bir kafede çalışan biri, kendi yaptığı hatanın sorumluluğunu bilerek iş arkadaşına yüklemiş ve müşteri bu arkadaşı suçlamıştır. Bu durumu meslek etiği ilkeleri ve Ahilik kültürü doğrultusunda değerlendiriniz. Bir çözüm planı öneriniz.","olcut":[{"metin":"Durumun etik sorununu (sorumluluk ve dürüstlük ihlali) açıklar.","puan":20},{"metin":"En az iki meslek etiği ilkesini durumla ilişkilendirir.","puan":30},{"metin":"Ahilik kültüründen bir değeri (örn. dürüstlük, dayanışma ya da “diline sahip ol”) durumla bağlar.","puan":25},{"metin":"Uygulanabilir bir çözüm planı önerir.","puan":25}],"ornek":"Sorun: sorumluluğun kasıtlı olarak başkasına yüklenmesi, dürüstlük ve sorumluluk ilkelerinin ihlalidir. İlkeler: dürüstlük, sorumluluk. Ahilik: doğruluk ve dayanışma; arkadaşını hedef göstermek bu değerlere aykırıdır. Plan: olayın yönetime sakin biçimde bildirilmesi, iki tarafın dinlenmesi ve hatanın kime ait olduğunun kanıtlarla açıklanması.","ipucu":"Çözüm planında kimin neyi, ne zaman yapacağını adım adım yazın."}],"sorular":[{"id":"mg-2-s01","tur":"coktan-secmeli","soru":"Staja yeni başlayan Elif hiçbir panoda yazmadığı hâlde koridorda karşılaştığı konuğa yol veriyor ve selam veriyor. Elif’in uyduğu kural hangi türdendir?","secenekler":["Yazılı kural","Yazılı olmayan kural","İş disiplini","Kural ihlali"],"dogru":1,"aciklama":"Belgede geçmediği hâlde herkesin uymasını beklediği davranış yazılı olmayan kuraldır. İş disiplini ise işi zamanında ve özenle yapma alışkanlığıdır; bir kural türü değildir."},{"id":"mg-2-s02","tur":"coktan-secmeli","soru":"Bölüm şefi hafta sonu vardiyalarını sırayla dağıtıyor; kimse üst üste her pazar çalışmıyor. Bu uygulama kuralların hangi işlevine örnektir?","secenekler":["Güvenliği sağlamaya","Kaliteyi yükseltmeye","Adaleti sağlamaya","Gizliliği korumaya"],"dogru":2,"aciklama":"Benzer durumdaki herkese aynı ölçüyle davranmak adalettir. Güvenlik, çalışanın ya da konuğun zarar görmesini önleyen kurallarla ilgilidir; burada zarar değil, hak dağılımı söz konusudur."},{"id":"mg-2-s03","tur":"coktan-secmeli","soru":"Bir otelin hijyen kuralları yalnız otelin itibarını değil, o gün orada yemek yiyen bütün konukların sağlığını da korur. Kuralın bu yönü hangisidir?","secenekler":["Toplumsal fayda","Liyakat","Hakkaniyet","Tarafsızlık"],"dogru":0,"aciklama":"Yararın yalnız kuralı uygulayana değil, toplumun geneline ulaşması toplumsal faydadır. Hakkaniyet ise kuralı uygularken kişinin içinde bulunduğu durumu gözetmektir."},{"id":"mg-2-s04","tur":"coktan-secmeli","soru":"Bir işi yapan herkesin o işte uyması beklenen doğru davranış ilkelerinin bütününe ne ad verilir?","secenekler":["Ahlak","İş disiplini","Davranış kuralları belgesi","Meslek etiği"],"dogru":3,"aciklama":"Bir mesleğe özgü doğru davranış ilkeleri meslek etiğidir. Ahlak toplumun genel değerleridir; davranış kuralları belgesi ise bu ilkelerin yazılı hâlidir."},{"id":"mg-2-s05","tur":"coktan-secmeli","soru":"Resepsiyonda sıra beklerken tanıdığı bir konuk gelince görevli onu öne almıyor ve herkesi geliş sırasıyla karşılıyor. Görevli hangi ilkeye uymuştur?","secenekler":["Gizlilik","Tarafsızlık","Dürüstlük","Sorumluluk"],"dogru":1,"aciklama":"Kişisel yakınlığa göre değil, herkes için aynı ölçüye göre davranmak tarafsızlıktır. Dürüstlük kimseyi aldatmamakla ilgilidir; burada konu sıra hakkıdır."},{"id":"mg-2-s06","tur":"coktan-secmeli","soru":"Bir görevli evrakı sırasından önce işleme koyması karşılığında kendisine verilen parayı alıyor. Bu davranış hangisidir?","secenekler":["Rüşvet","Kayırmacılık","Çıkar çatışması","Gizliliği çiğneme"],"dogru":0,"aciklama":"Görevine aykırı bir iş karşılığında para ya da çıkar almak rüşvettir. Kayırmacılıkta karşılık yoktur; öncelik akrabalığa ya da arkadaşlığa göre verilir."},{"id":"mg-2-s07","tur":"coktan-secmeli","soru":"Bir şef en rahat vardiyaları her hafta yalnız yakın arkadaşına veriyor; öteki personel hep zor vardiyalarda çalışıyor. Bu davranış hangisidir?","secenekler":["Rüşvet","Sorumluluktan kaçma","Kayırmacılık","Gizliliği çiğneme"],"dogru":2,"aciklama":"Hakka ve çalışmaya değil, kişisel yakınlığa göre öncelik vermek kayırmacılıktır. Rüşvet için bir karşılık alınması gerekir; burada böyle bir çıkar yoktur."},{"id":"mg-2-s08","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi iş yeri kaynaklarının izinsiz kişisel kullanımına örnektir?","secenekler":["Mola saatinde personel yemekhanesinde yemek yemek","Müdürün iznine dayanarak otel aracını bagaj taşımada kullanmak","Şefin bilgisi dâhilinde işe ait bezleri depoda kullanmak","Çalışma saatinde otel bilgisayarında kendi ödevini hazırlamak"],"dogru":3,"aciklama":"İşletmenin zamanı ve imkânı kişisel iş için izinsiz kullanılırsa kaynak kişisel amaca harcanmış olur. Diğer üç durumda ya izin vardır ya da kullanım işin kendisi içindir."},{"id":"mg-2-s09","tur":"coktan-secmeli","soru":"Ahilikte çırağa yalnız meslek bilgisi değil, ahlak da öğretilirdi. Bunun amacı hangisidir?","secenekler":["Siparişleri hızlı ve düşük maliyetle karşılayan işçi yetiştirmek","Güvenilir ve topluma yararlı meslek insanı yetiştirmek","Dükkân sayısını sınırlayarak esnafın rekabetini azaltmak","Çırakların ustalığa geçişini zorlaştırarak mesleği korumak"],"dogru":1,"aciklama":"Ahilikte hedef “iyi insan, iyi meslek erbabı” yetiştirmektir. Yalnız hız ve beceri, güvenilir bir esnaf oluşturmaya yetmez."},{"id":"mg-2-s10","tur":"coktan-secmeli","soru":"Ahilik teşkilatının kurucusu kabul edilen ve dericilerin piri sayılan kişi kimdir?","secenekler":["Yunus Emre","Hacı Bektaş Veli","Ahi Evran","Mevlana"],"dogru":2,"aciklama":"Ahi Evran, 13. yüzyılda Anadolu’da yaşamış, Ahiliğin kurucusu kabul edilen ve debbağların piri sayılan kişidir. Diğerleri aynı dönemin tanınmış Anadolu bilgeleridir, ama Ahilikle anılmazlar."},{"id":"mg-2-s11","tur":"coktan-secmeli","soru":"Ahilikte mesleğe ilk adımını atan biri ustalığa kadar hangi basamaklardan geçer?","secenekler":["Yamak – çırak – kalfa – usta","Çırak – yamak – kalfa – usta","Yamak – kalfa – çırak – usta","Çırak – kalfa – yamak – usta"],"dogru":0,"aciklama":"Yamaklık mesleğe ilk adımdır; sırasıyla çıraklık, kalfalık ve ustalık gelir. Çırak, yamaklık döneminden sonra ustanın yanında öğrenmeye devam eden kişidir."},{"id":"mg-2-s12","tur":"coktan-secmeli","soru":"Ahilikte işi kendi başına yapabilen ama kendi iş yerini açabilecek ustalığa henüz yükselmemiş kişi hangi basamaktadır?","secenekler":["Çırak","Yamak","Usta","Kalfa"],"dogru":3,"aciklama":"Kalfa, çıraklığı tamamlamış ve işi tek başına yapabilen kişidir. Usta ise bütün inceliklerini bilir, kendi iş yerini açar ve çırak ile kalfa yetiştirir."},{"id":"mg-2-s13","tur":"coktan-secmeli","soru":"Otelde boşalan kat şefliğine, en çok bilgi ve deneyime sahip personel yerine müdürün yeğeni getirilirse hangi ilke çiğnenmiş olur?","secenekler":["Gizlilik","Liyakat","Dayanışma","Sosyal sorumluluk"],"dogru":1,"aciklama":"Görevin onu hak eden, bilgisi ve becerisi olan kişiye verilmesi liyakattir. Yeğenin seçilmesi liyakati değil, kişisel yakınlığı esas alır."},{"id":"mg-2-s14","tur":"coktan-secmeli","soru":"“Eline, beline, diline sahip ol” öğüdünde “diline sahip ol” sözü aşağıdakilerden hangisini ister?","secenekler":["Başkasının malına el uzatmamayı","İffetli ve ahlaklı olmayı","Yalandan ve kötü sözden uzak durmayı","Kazancı mümkün olduğunca paylaşmayı"],"dogru":2,"aciklama":"Öğüdün üç parçası ayrı bir davranışı anlatır: el, mala; bel, iffete; dil ise yalan ve kötü sözden uzak durmaya karşılık gelir."},{"id":"mg-2-s15","tur":"coktan-secmeli","soru":"Ahilikte kusurlu mal satan esnafın pabucunun dama atılması geleneği hangi amaca hizmet ederdi?","secenekler":["Müşteriyi aldatmayı caydırıp tüketiciyi korumaya","Esnafın kazancını artırmaya","Çırakların ustalığa geçişini hızlandırmaya","Yeni dükkân açmayı kolaylaştırmaya"],"dogru":0,"aciklama":"Kusurlu mal satanın herkesin önünde gözden düşürülmesi, aldatmayı caydırıp alıcıyı korurdu. “Pabucu dama atılmak” deyimi de buradan gelir."},{"id":"mg-2-s16","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi helal kazanç anlayışına aykırıdır?","secenekler":["Satılan malın kusurunu açıkça söyleyerek satmak","Hizmet bedelini yalnız verilen hizmet kadar almak","Emeğinin karşılığını ölçüden ve kaliteden ödün vermeden almak","Konuğa söylemeden fiyata gizli ek ücret eklemek"],"dogru":3,"aciklama":"Helal kazanç, kimseyi aldatmadan ve hakkını yemeden elde edilen kazançtır. Gizli ek ücret konuğu aldatır; diğer üç davranış açıklık ve dürüstlüğe dayanır."},{"id":"mg-2-s17","tur":"dogru-yanlis","soru":"Bir kuralın hiçbir belgede yazılı olmaması, o kurala uymamayı haklı kılmaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Yazılı olmayan kurallar da iş yerinde ve toplumda uyulması beklenen davranışlardır; yazılı kural kadar bağlayıcı bir düzen kurarlar."},{"id":"mg-2-s18","tur":"dogru-yanlis","soru":"Stajyerin görevi yalnız gözlemek olduğundan meslek etiği ilkelerine uyma sorumluluğu ancak kadroya geçince başlar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Meslek etiği, işini yapan herkesi bağlar; stajyer de dürüstlük, gizlilik ve sorumluluk gibi ilkelere uymak zorundadır."},{"id":"mg-2-s19","tur":"dogru-yanlis","soru":"Ahilikte bir kişinin yalnız işini iyi yapması yetmez; dürüst, güvenilir ve topluma yararlı olması da beklenirdi.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Ahilikte meslek eğitimi ahlak eğitimiyle birlikte verilirdi; amaç “iyi insan, iyi meslek erbabı” yetiştirmekti."},{"id":"mg-2-s20","tur":"dogru-yanlis","soru":"Ahilikte esnafın sattığı malın kalitesi denetlenmez, alıcıyı korumak teşkilatın işi sayılmazdı.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Ahilikte kalite kontrol ve tüketiciyi koruma esastı; kusurlu mal satan esnaf yaptırıma uğrar, “pabucu dama atılırdı”."},{"id":"mg-2-s21","tur":"senaryo","durum":"Kat hizmetlerinde staj yapıyorsun. Saat 12.15, konuğu sabah ayrılmış bir odayı toplarken yatak ile komodinin arasına düşmüş bir cüzdan buluyorsun; içinde para var. Odada senden başka kimse yok.","soru":"Ne yaparsın?","secenekler":["Cüzdanı komodinin üstüne koyar, odayı toplamaya devam ederim.","Cüzdanı açmadan kat şefime teslim eder, kayda geçmesini isterim.","Cüzdanı açıp kimliğine bakar, konuğa kendim ulaşmaya çalışırım.","Cüzdanı dolabıma kilitler, konuk gelirse veririm."],"dogru":1,"aciklama":"Konuğa ait eşya kayıt altına alınmak üzere yetkiliye teslim edilir; böylece hem konuk hem de sen güvende olursun. Eşyayı açmak ya da kendi başına saklamak yetkisiz ve kayıtsız işlemdir; ortada bırakmak da kayba yol açar."},{"id":"mg-2-s22","tur":"senaryo","durum":"Otelin servis bölümünde stajdasın. Saat 16.00, yakın arkadaşın olan öteki stajyerin konuklar için hazırlanan ikramlardan çantasına koyduğunu görüyorsun. Sana “Sen de al, kimse saymıyor” diyor.","soru":"Nasıl davranırsın?","secenekler":["Almam, ama arkadaşıma bir daha yapmamasını söylemekle yetinirim.","Almam, ancak arkadaşımı korumak için görmemiş gibi davranırım.","Önce öteki stajyerlerle konuşup birlikte karar veririm.","Almam; gördüğüm durumu abartmadan şefime bildiririm."],"dogru":3,"aciklama":"İşletmeye ait malın izinsiz alındığını gören kişi durumu yetkiliye bildirir; bu etik ihlal bildirimidir. Yalnız uyarmak ya da görmezden gelmek ihlalin sürmesine izin verir."},{"id":"mg-2-s23","tur":"senaryo","durum":"Ön büroda staj yapıyorsun. Saat 19.30, lobide yanına gelen bir kişi “Arkadaşım Murat Bey burada kalıyor, hangi odada olduğunu söyler misin?” diyor. Resepsiyon görevlisi o an telefonda.","soru":"Ne yaparsın?","secenekler":["Oda bilgisi veremeyeceğimi söyleyip görevliye yönlendiririm.","Sistemden bakar, arkadaşı olduğunu söyleyen kişiye oda numarasını söylerim.","Öyle bir konuğumuz olmadığını söyleyip kişiyi gönderirim.","Odasını söylemem, ama hangi katta kaldığını kişiye söylerim."],"dogru":0,"aciklama":"Konuk bilgileri yetkisi olmayan kimseyle paylaşılmaz; bu gizliliktir. Kat bilgisi vermek de konuğun yerini ele verir, olmayan konuk demek ise yalandır."},{"id":"mg-2-s24","tur":"senaryo","durum":"Bir seyahat acentesinde stajdasın. Saat 11.00, bir otobüs firmasının temsilcisi sana pahalı bir kulaklık uzatıp “Müşteriler tur sorduklarında hep bizi öner, bu da senin olsun” diyor.","soru":"Nasıl davranırsın?","secenekler":["Hediyeyi alır, önerilerimi yine de kendi kararıma göre yaparım.","Hediyeyi alıp öteki stajyerlerle paylaşırım.","Hediyeyi almaz, teklifi acente yetkilisine bildiririm.","Hediyeyi nazikçe geri çevirir, konuyu kimseye açmam."],"dogru":2,"aciklama":"Müşterileri yönlendirmek karşılığı hediye teklifi çıkar çatışması yaratır; kabul etmemek ve yetkiliye bildirmek işletmeyi korur. Yalnız geri çevirmek, aynı teklifin başkalarına yapılmasını engellemez."},{"id":"mg-2-s25","tur":"senaryo","durum":"Restoranda staj yapıyorsun. Saat 21.00, bir masaya götüreceğin hesapta, o masaya hiç servis edilmemiş bir tatlının yazıldığını fark ediyorsun. Yanındaki garson “Boş ver, fark etmezler” diyor.","soru":"Ne yaparsın?","secenekler":["Hesabı öyle götürür, konuk itiraz ederse düzeltirim.","Hesabı götürmeden şefime haber verip düzeltilmesini isterim.","Tatlı bedelini kendi cebimden karşılamak üzere hesabı götürürüm.","Garson arkadaşıma hatayı söyler, hesabı onun götürmesini isterim."],"dogru":1,"aciklama":"Konuğa verilmemiş hizmetin parasını yazdırmak hiledir; hata, hesap sunulmadan yetkili aracılığıyla düzeltilmelidir. Kendi cebinden ödemek hatayı gizler, işi başkasına bırakmak sorumluluktan kaçmaktır."},{"id":"mg-2-s26","tur":"senaryo","durum":"Vardiyan 07.00’de başlıyor, ama otobüsü kaçırdın, otele 07.25’te vardın. Arkadaşın mesaj atmış: “Merak etme, kartını ben okuttum, zamanında gelmiş görünüyorsun.”","soru":"Ne yaparsın?","secenekler":["Şefime geç kaldığımı ve kartın benim yerime okutulduğunu açıklarım.","Arkadaşıma teşekkür eder, konuyu kimseye açmam.","Şef sorarsa erken geldiğimi, ama başka katta olduğumu söylerim.","Akşam yarım saat fazla kalarak gecikmeyi telafi eder, bir şey söylemem."],"dogru":0,"aciklama":"Dürüstlük, hatayı sahiplenmeyi ve gerçeği söylemeyi gerektirir. Kartın başkasınca okutulması kayıt tutmayı bozar; fazla mesaiyle telafi de gerçeği saklamayı haklı çıkarmaz."},{"id":"mg-2-s27","tur":"senaryo","durum":"Havuz barında stajdasın. Saat 15.00, tanınmış bir sanatçı otelde tatil yapıyor. Yanındaki stajyer telefonunu çıkarıp gizlice fotoğrafını çekiyor: “Hemen paylaşıyorum, sen de çek!”","soru":"Nasıl davranırsın?","secenekler":["Ben de çekerim, ama yalnız yakın arkadaşlarıma gönderirim.","Çekmem, ama arkadaşımın paylaşımına karışmam.","Çekmem; sanatçıya tanıdığımı söyleyip imza isterim.","Çekmem; paylaşmamasını söyler, durumu şefime bildiririm."],"dogru":3,"aciklama":"Konuğun izinsiz fotoğrafı özel hayatını ve gizliliğini ihlal eder. Seni bağlayan sorumluluk, yanındaki kişiyi uyarmak ve yetkiliye bildirmektir; karışmamak ihlalin sürmesine izin verir."},{"id":"mg-2-s28","tur":"senaryo","durum":"Bagaj hizmetlerinde staj yapıyorsun. Saat 10.40, bir konuğun valizini bagaj arabasından indirirken tekerleğini kırıyorsun. Konuk resepsiyonda, olayı kimse görmedi.","soru":"İlk adımın ne olur?","secenekler":["Valizi odaya götürür, kırığı görünmeyen yüze çeviririm.","Konuk sorarsa valizin böyle geldiğini söylerim.","Hemen şefime haber verir, olanı olduğu gibi anlatırım.","Tekerleği kendim yapıştırmayı dener, olmazsa söylerim."],"dogru":2,"aciklama":"Sorumluluk, hatanın sonucunu sahiplenmektir; olanı hemen bildirmek konuğun zararının giderilmesini sağlar. Gizlemek, yalan söylemek ya da kendi başına çözmeye çalışmak zararı büyütebilir."},{"id":"mg-2-s29","tur":"coktan-secmeli","soru":"Bir otel kazancının bir bölümüyle yakındaki okulun kütüphanesini yeniliyor. Bu davranış hangi kavramın örneğidir?","secenekler":["Tüketiciyi koruma","Sosyal sorumluluk","Kalite kontrol","Haksız rekabet"],"dogru":1,"aciklama":"Kişinin ya da işletmenin kendi kazancının ötesinde topluma karşı da görevi olduğunu bilmesi sosyal sorumluluktur. Tüketiciyi koruma, alıcının aldatılmasını önleyen kurallarla ilgilidir."},{"id":"mg-2-s30","tur":"coktan-secmeli","soru":"Şef, ertesi gün sınavı olan bir personele kuralı bozmadan erken çıkış izni veriyor; fazla mesai yapan öteki çalışanın hakkını da başka bir gün karşılıyor. Şefin bu yaklaşımı hangi kavrama örnektir?","secenekler":["Tarafsızlık","Hakkaniyet","Kayırmacılık","İş disiplini"],"dogru":1,"aciklama":"Hakkaniyet, kuralı uygularken kişinin durumunu da gözeterek herkesin hakkını dengeli biçimde karşılamaktır. Kayırmacılıkta öncelik yakınlığa göre verilir; burada iki çalışanın hakkı da gözetilmiştir."},{"id":"mg-2-s31","tur":"coktan-secmeli","soru":"Staj toplantısında ekip, “Konuk yanlışlıkla fazla ödeme yaparsa ne yaparız ve neden böyle yaparız?” sorusunu tartışıp doğru davranışı bir ilkeye bağlıyor. Ekibin yaptığı tartışma hangi alana girer?","secenekler":["Kalite kontrol","Görev tanımı","Ahlak","Etik"],"dogru":3,"aciklama":"Etik, neyin doğru neyin yanlış olduğunu sorgulayan ve buna göre ilke koyan düşünce alanıdır. Ahlak toplumun “Ne doğru?” sorusuna verdiği cevaptır; o cevabın nedenini sorgulamak etiğin işidir."},{"id":"mg-2-s32","tur":"coktan-secmeli","soru":"Servis stajyeri, masa kurmanın, tabak toplamanın ve reyon temizliğinin kendi işi olduğunu ilk gün kendisine verilen bir belgeden öğreniyor. Bu belge hangisidir?","secenekler":["Kalite standardı","Davranış kuralları belgesi","Görev tanımı","Etik çözüm planı"],"dogru":2,"aciklama":"Görev tanımı, çalışanın hangi işleri yapacağını ve nelerden sorumlu olduğunu yazan belgedir. Davranış kuralları belgesi ise yapılacak işleri değil, beklenen tutumları ve yasakları sıralar."},{"id":"mg-2-s33","tur":"coktan-secmeli","soru":"Kat şefi temizlenen odayı yastık sayısının, havlu düzeninin ve minibar dolumunun tek tek yazılı olduğu bir listeye göre denetliyor. Bu liste hangisine örnektir?","secenekler":["Kalite standardı","Görev tanımı","Garanti belgesi","Davranış kuralları belgesi"],"dogru":0,"aciklama":"Kalite standardı, bir hizmetin hangi ölçütlere uyması gerektiğini belirleyen yazılı kuraldır; otelin oda standardı da böyle yazılır. Görev tanımı ise bir çalışanın hangi işleri yapacağını gösterir, odanın nasıl olması gerektiğini değil."},{"id":"mg-2-s34","tur":"coktan-secmeli","soru":"Bir stajyer, iş arkadaşının uyarı levhası koymadan ıslak koridoru sildiğini görüyor. Kural ihlali karşısında doğru davranış hangisidir?","secenekler":["Otelin adı zarar görmesin diye durumu gizlemek","İhlali yapan arkadaşıyla tartışıp hesap sormak","Konuk henüz düşmediyse işine devam etmek","Gördüğü durumu gecikmeden amirine bildirmek"],"dogru":3,"aciklama":"İhlalin bedelini çoğu zaman konuk, iş arkadaşı ya da otelin adı öder; bu yüzden ihlal gizlenmez, amire bildirilir. Arkadaşla tartışmak sorunu çözmez, riski de ortadan kaldırmaz."},{"id":"mg-2-s35","tur":"dogru-yanlis","soru":"Bir stajyerin vardiyaya geç kalması yalnız kendisini değil, önceki vardiyada çalışıp onu bekleyen arkadaşını da etkiler.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Otel vardiyayla çalışır: biri geç kalınca önceki vardiyadaki arkadaşı evine gidemez. İş disiplini bu yüzden ekibin birbirine güvenmesini sağlar."},{"id":"mg-2-s36","tur":"dogru-yanlis","soru":"Hediye kabulü ve konuk bilgisinin korunması gibi konularda işletmenin kuralı, çalışanın işe başlarken okuduğu davranış kuralları belgesinde (code of conduct) yer alabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Davranış kuralları belgesi, işletmenin çalışandan beklediği davranışları ve yasak saydığı tutumları madde madde yazar. Hediye kabulü, konuk bilgisinin korunması ve sosyal medya paylaşımı bu belgede düzenlenen konulardandır."},{"id":"mg-2-s37","tur":"dogru-yanlis","soru":"Fütüvvet anlayışında iyi insan olmak ile iyi meslek sahibi olmak birbirinden ayrı tutulurdu.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Ahiler fütüvvet anlayışını iş hayatına taşıdı ve iyi insan olmak ile iyi meslek sahibi olmayı birbirinden ayırmadı. Cömertlik, yardımseverlik ve doğruluk bu yüzden mesleğin de parçası sayıldı."},{"id":"mg-2-s38","tur":"coktan-secmeli","soru":"Ahilikte meslekte üst basamağa yükselen kişinin beline kuşağın herkesin önünde bağlanması neyi gösterirdi?","secenekler":["Kişinin yükselmeyi hak ederek kazandığını","Ustanın dükkânını kalfasına devrettiğini","Kişinin mesleğe yamak olarak başladığını","Esnafın kusurlu mal satıp gözden düştüğünü"],"dogru":0,"aciklama":"Şed kuşanma töreni, kişinin işini ve ahlakını kanıtladığının herkesin önünde ilanıdır; yükselme kayırmayla değil, hak ederek olur. Kusurlu mal satan esnafın gözden düşmesi ise “pabucu dama atılmak” deyimiyle anlatılır."},{"id":"mg-2-s39","tur":"coktan-secmeli","soru":"Bir otel çalışanı, rakip otel hakkında konuklara asılsız kötü sözler söyleyerek onları kendi oteline çekmeye çalışıyor. Bu davranış hangisine örnektir?","secenekler":["Çıkar çatışması","Tüketiciyi koruma","Haksız rekabet","Kayırmacılık"],"dogru":2,"aciklama":"Başkasının müşterisini haksız yollarla kendine çekmeye çalışmak haksız rekabettir; rakip oteli kötülemek de bu kapıya çıkar. Çıkar çatışması ise çalışanın kişisel çıkarının işini tarafsız yapmasını etkilemesidir."},{"id":"mg-2-s40","tur":"coktan-secmeli","soru":"Otelin klima servisi, yaptığı tamirde aynı arıza belirli süre içinde tekrar ederse ücretsiz düzelteceğini yazılı olarak bildiriyor. Verilen bu güvence hangisidir?","secenekler":["Kalite standardı","Garanti","Müşteri memnuniyeti","Görev tanımı"],"dogru":1,"aciklama":"Garanti, yapılan iş belirli süre içinde sorun çıkarırsa düzeltileceğine dair verilen güvencedir. Müşteri memnuniyeti bir güvence değil, hizmet alanın beklentisinin karşılandığını düşünmesidir."},{"id":"mg-2-s41","tur":"dogru-yanlis","soru":"Rezervasyonda deniz manzaralı oda gördüğü hâlde bahçe manzaralı odaya yerleştirilen konuğun bu konuda hakkını araması mümkün değildir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Tüketici, aldatıldığında ya da zarar gördüğünde hakkını arayabilir. Vaat edilenden farklı odaya yerleştirilen konuk itiraz edip hakkını resepsiyonda arayabilir."},{"id":"mg-2-s42","tur":"coktan-secmeli","soru":"Etik ikilemde kalan bir stajyere doğru kararı bulmakta yol gösterecek soru hangisidir?","secenekler":["Kimse fark etmezse bunun bir sakıncası olur mu?","Bunu yaparsam bana ne kazandırır?","Bunu şefimin yanında da yapar mıydım?","Arkadaşlarım bu kararımı onaylar mı?"],"dogru":2,"aciklama":"Etik ikilemde yol gösteren sorulardan biri “Bunu şefimin yanında da yapar mıydım?” sorusudur; öbürleri kurala uygunluk ve birine zarar verip vermemektir. Fark edilip edilmemek ya da kazanç doğru davranışın ölçüsü değildir."},{"id":"mg-2-s43","tur":"coktan-secmeli","soru":"Gece 03.00’te boş koridorda cüzdan bulan bellboy, cüzdanı açmadan resepsiyona götürüp kayıt altına aldırıyor. Kimse görmese de doğru bildiği gibi davranmanın sektördeki İngilizce adı hangisidir?","secenekler":["Confidentiality","Integrity","Whistleblowing","Conflict of interest"],"dogru":1,"aciklama":"Kimse görmese ve denetlemese de doğru bildiği ilkelere uygun davranmaya doğruluk ve tutarlılık (integrity) denir. “Confidentiality” konuk ve işletme bilgisinin paylaşılmamasıdır, yani gizliliktir."},{"id":"mg-2-s44","tur":"coktan-secmeli","soru":"Ahilikte dükkânı yanan bir esnafa, çarşı esnafının kendi aralarında oluşturdukları yardım düzeninden yeni tezgâh ve malzeme için destek verilir. Bu düzen hangisidir?","secenekler":["Siftah","Şed kuşanma","Usta-çırak modeli","Orta sandığı"],"dogru":3,"aciklama":"Orta sandığı, esnafın zor durumdaki meslektaşlarına ve ihtiyaç sahiplerine destek olmak için oluşturduğu yardımlaşma düzenidir. Siftah ise esnafın gün içindeki ilk satışıdır."},{"id":"mg-2-s45","tur":"coktan-secmeli","soru":"Sabah ilk satışını yapan baharatçı, sonra gelen müşteriyi henüz satış yapmamış komşusuna yönlendiriyor. Bu davranış en çok hangi değeri yansıtır?","secenekler":["Dayanışma","Liyakat","Tarafsızlık","Garanti"],"dogru":0,"aciklama":"Siftahını yapan esnafın müşteriyi henüz satış yapmamış komşusuna göndermesi, komşu esnafın hakkını gözeten bir dayanışma örneğidir. Liyakat ise bir görevin onu hak eden kişiye verilmesidir."},{"id":"mg-2-s46","tur":"coktan-secmeli","soru":"Otel çalışanları, çalışma saatleriyle ilgili ortak taleplerini işverene iletmek için hangi kuruluşa başvurur?","secenekler":["Vakıf","Ticaret ve sanayi odası","Sendika","TESK"],"dogru":2,"aciklama":"Sendika, çalışanların haklarını korumak ve çalışma koşullarını iyileştirmek için kurduğu örgüttür. TESK ise çalışanları değil, esnaf ve sanatkâr kuruluşlarını temsil eder."},{"id":"mg-2-s47","tur":"coktan-secmeli","soru":"Bir restoran, maliyeti düşürmek için bozulmaya yakın malzemeyi yemeklerde kullanıyor. Bu ahlaki sorunun nedeni hangisidir?","secenekler":["Aşırı kâr hırsı","Liyakat eksikliği","Dayanışma eksikliği","Sorumluluktan kaçma"],"dogru":0,"aciklama":"Kaliteyi, güvenliği ve müşterinin hakkını ikinci plana atıp yalnız kazancı düşünmek aşırı kâr hırsıdır. Liyakat eksikliği ise görevin onu hak eden kişiye verilmemesidir; burada sorun bir atama değildir."},{"id":"mg-2-s48","tur":"dogru-yanlis","soru":"Etik çözüm planına yalnız çözüm adımları yazılır; sorunun nedenleri ve beklenen sonuçlar plana girmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Etik çözüm planı sorunun tanımını, nedenlerini, ilgili değerleri, çözüm adımlarını, paydaşların görevlerini, beklenen sonuçları ve izlemeyi birlikte gösterir. Nedenleri yazılmayan sorunun çözümü de eksik kalır."}],"siralamalar":[{"id":"mg-2-r01","konu":"2.1","baslik":"Atlanan kontrolün bedeli","yonerge":"Tekstil atölyesindeki kural ihlalinin nasıl büyüdüğünü gösteren olayları doğru sıraya koy.","adimlar":["Zaman baskısı yüzünden kalfa, kumaşların kalite kontrolünü atlar.","Defolu ürünler sağlam ürün gibi paketlenip piyasaya gönderilir; işletme kısa sürede kazanç sağlamış gibi görünür.","Müşteriler ürünlerdeki hataları fark eder.","Müşteri şikâyetleri artar, işletmeye duyulan güven azalır."],"aciklama":"Kuralı çiğnemek ilk anda kazanç gibi görünür; hata müşteriye ulaşıp fark edildiğinde ise bedeli güven kaybı olarak işletmeye geri döner."},{"id":"mg-2-r02","konu":"2.2","baslik":"Yamaklıktan ustalığa","yonerge":"Ahilikte mesleğe başlayan bir gencin yükseldiği basamakları doğru sıraya koy.","adimlar":["Mesleğe yamak olarak başla.","Çırak olarak ustanın yanında yaparak öğren.","Kalfa olarak mesleğini sorumlulukla yürüt.","Mesleki yeterliğini ve ahlaki olgunluğunu kanıtlayıp usta ol; çırak yetiştirme sorumluluğunu üstlen."],"aciklama":"Ahilikte meslek yamak, çırak, kalfa ve usta basamaklarıyla öğrenilir; üst basamağa geçmek için zamanın dolması yetmez, yeterliğin ve ahlaki olgunluğun kanıtlanması gerekir."},{"id":"mg-2-r03","konu":"2.4","baslik":"Ahilikle etik çözüm planı","yonerge":"İş yerindeki ahlaki bir sorun için Ahilik temelli çözüm planı hazırlama adımlarını doğru sıraya koy.","adimlar":["Yaşanan ahlaki sorunun ne olduğunu açıkça belirle.","Sorunun nedenlerini, kimleri etkilediğini ve doğurabileceği sonuçları incele.","Bulduğun nedenlerin dürüstlük, helal kazanç gibi hangi Ahilik değerlerine aykırı olduğunu göster.","Bu değerlere uyan çözüm yolunu seç ve neden-sonuç ilişkisiyle gerekçelendir.","Çözüm adımlarını, paydaşların görevlerini ve izleme yolunu içeren eylem planını hazırla."],"aciklama":"Sorun doğru tanımlanmadan nedenleri bulunamaz; nedenler Ahilik ilkeleriyle ilişkilendirilince gerçekçi bir çözüm seçilir ve eylem planına dönüştürülür."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":3,"baslik":"İş Sağlığı ve Güvenliği","onay":true,"kazanimlar":["İş sağlığı ve güvenliğini (İSG) tehdit eden riskleri ve uygulanan güvenlik tedbirlerini İSG standartları doğrultusunda gözlemleyebilme.","Meslek hastalıklarının nedenlerini ve bu hastalıkların ortaya çıkmasını önlemeye yönelik tedbirleri çözümleyebilme.","Sağlık ve güvenliği tehdit eden unsurlara yönelik bir çözüm planı yapılandırabilme.","İş sağlığı ve güvenliğine ilişkin bir probleme ve çözüm stratejilerine yönelik eleştirel düşünebilme.","Acil durumlara müdahale süreçlerinde oluşabilecek problemleri çözebilme."],"soz":"Hiçbir iş, sağlığını kaybetmeye değecek kadar acil değildir.","dersler":[{"baslik":"Tehlike mi, Risk mi?","ilk":"mg-3-001"},{"baslik":"Sarı Levha Neden Orada?","ilk":"mg-3-009"},{"baslik":"Kanun Stajyeri de Korur","ilk":"mg-3-024"},{"baslik":"Güvenliğin Sorumluları","ilk":"mg-3-028"},{"baslik":"Sessiz Tehlikeler","ilk":"mg-3-037"},{"baslik":"Renkler Ne Söyler?","ilk":"mg-3-045"},{"baslik":"Çıkış Nerede?","ilk":"mg-3-050"},{"baslik":"Gözlemci Gözüyle","ilk":"mg-3-074"},{"baslik":"Yangın ve Elektrik Tehdidi","ilk":"mg-3-077"},{"baslik":"Yıllar Sonra Gelen Fatura","ilk":"mg-3-013"},{"baslik":"Bedenin de Bir Sınırı Var","ilk":"mg-3-017"},{"baslik":"Görünmeyen Yük","ilk":"mg-3-020"},{"baslik":"Nedenin Peşinde","ilk":"mg-3-029"},{"baslik":"Etken, Maruziyet, Sorun","ilk":"mg-3-080"},{"baslik":"Güvenli Ortamın Sırrı","ilk":"mg-3-084"},{"baslik":"Kaza Olmadan Önce","ilk":"mg-3-007"},{"baslik":"Son Savunma Hattı","ilk":"mg-3-035"},{"baslik":"Kökten Çözüm","ilk":"mg-3-087"},{"baslik":"Baştan Ayağa Korunma","ilk":"mg-3-093"},{"baslik":"Riski Tartmak","ilk":"mg-3-032"},{"baslik":"Herkesi Birden Koruyanlar","ilk":"mg-3-099"},{"baslik":"Plan Önceden Yapılır","ilk":"mg-3-052"},{"baslik":"İlk Yardımda Önce Ne?","ilk":"mg-3-058"},{"baslik":"Ateşi Tanı","ilk":"mg-3-064"},{"baslik":"Gaz, Deprem, Göçük","ilk":"mg-3-069"},{"baslik":"Kriz Kapıyı Çalınca","ilk":"mg-3-104"},{"baslik":"Önce Durumu Oku","ilk":"mg-3-108"},{"baslik":"Herkesin Bir Görevi Var","ilk":"mg-3-111"},{"baslik":"Bilmeden Müdahale","ilk":"mg-3-115"}],"kavramlar":[{"id":"mg-3-001","konu":"3.1","terim":"İş sağlığı ve güvenliği (İSG)","ingilizce":"Occupational health and safety (OHS)","tanim":"Çalışanların işten kaynaklanan kaza ve hastalıklardan korunması için iş yerinde yürütülen planlı ve sürekli çalışmaların bütünüdür.","ornek":"Staja başladığın ilk sabah sana otel gezdirilir: acil çıkışlar, yangın tüpleri, kimyasal deposunun kuralları tek tek gösterilir.","sektor":"Programın anahtar kavramlarındandır. Otelde konuğun rahatı, çalışanın güvenliğiyle başlar: mutfakta bıçak ve ateş, katlarda kimyasal ve yük, havuz başında ıslak zemin vardır. Güvenli çalışan ekip, konuğa da güvenli bir otel sunar.","iliskili":["mg-3-002","mg-3-003","mg-3-024"],"kontrol":null,"gorsel":"mg-baret"},{"id":"mg-3-002","konu":"3.1","terim":"Güvenlik kültürü","ingilizce":"Safety culture","tanim":"Bir iş yerinde herkesin, başında denetleyen biri olmasa da güvenli davranmayı alışkanlık ve ortak değer hâline getirmesidir.","ornek":"Gece 23.30, mutfak kapanıyor: şef çoktan çıkmıştır, ama komi yine de ocakların vanasını tek tek kontrol eder ve zemini kuru bırakır.","sektor":"Kural panoda asılı durur, kültür davranışta görünür. “Bana bir şey olmaz” ve “Hep böyle yapıyoruz” cümleleri bu kültürün zayıfladığını gösterir. Güçlü kültürde tehlikeyi söyleyen kişi azarlanmaz, teşekkür alır.","iliskili":["mg-3-001","mg-3-007","mg-3-026"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-003","konu":"3.1","terim":"Tehlike","ingilizce":"Hazard","tanim":"Çalışana ya da iş yerine zarar verebilecek her türlü durum, madde ya da nesnedir.","ornek":"Mutfakta kızgın yağ dolu fritöz, çamaşırhanede sıcak silindir ütü, kat arabasındaki çamaşır suyu, havuz kenarındaki ıslak zemin.","sektor":"Programın anahtar kavramlarındandır. Tehlike “ne zarar verebilir?” sorusunun cevabıdır ve çoğu zaman işin doğasında vardır: bıçaksız mutfak olmaz. Yapılacak iş, tehlikeyi tanıyıp onu kontrol altında tutmaktır.","iliskili":["mg-3-004","mg-3-032","mg-3-008"],"kontrol":null},{"id":"mg-3-004","konu":"3.1","terim":"Risk","ingilizce":"Risk","tanim":"Bir tehlikenin gerçekten zarara, yaralanmaya ya da kayba yol açma ihtimalidir.","ornek":"Zemine dökülmüş yağ tehlikedir; birinin o yağa basıp kayarak yaralanma ihtimali ise risktir. Yağ hemen silinirse risk ortadan kalkar.","sektor":"Programın anahtar kavramlarındandır. Tehlike ile risk aynı şey değildir: tehlike vardır, risk ise büyür ya da küçülür. Aynı bıçak, eğitimli aşçının elinde düşük, ilk gününde acele eden stajyerin elinde yüksek risk demektir.","iliskili":["mg-3-003","mg-3-033","mg-3-032"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-005","konu":"3.1","terim":"İş kazası","ingilizce":"Occupational accident","tanim":"İş yerinde ya da işin yürütülmesi sırasında meydana gelen, çalışanın ölümüne, yaralanmasına ya da ruhen zarar görmesine yol açan olaydır.","ornek":"Öğle servisinde, saat 12.40: komi ıslak bulaşıkhane zemininde kayar ve bileğini burkar. Olay iş yerinde ve iş sırasında olmuştur; iş kazasıdır.","sektor":"Programın anahtar kavramlarındandır. İş kazası “kader” değildir; çoğunun arkasında önceden görülebilecek bir güvensiz durum ya da davranış vardır. Kaza çalışana acı, ekibe eksik eleman, işletmeye de maddi ve hukuki yük getirir.","iliskili":["mg-3-006","mg-3-013","mg-3-031"],"kontrol":null,"gorsel":"m3-anlage-zinkleimverband"},{"id":"mg-3-006","konu":"3.1","terim":"Ramak kala olay","ingilizce":"Near miss","tanim":"Zarar verme potansiyeli olduğu hâlde kimsenin yaralanmadığı ve hiçbir şeyin hasar görmediği, kıl payı atlatılan olaydır.","ornek":"Kat görevlisi yeni silinmiş koridorda kayar, son anda arabaya tutunur ve düşmez. Kimseye bir şey olmamıştır, ama olabilirdi.","sektor":"Ramak kala olay, kazanın bedava gelen uyarısıdır. “Bir şey olmadı” diye geçilirse aynı yerde bir dahaki sefer biri gerçekten düşer. Bu yüzden ramak kala olaylar da amire bildirilir ve kaydedilir.","iliskili":["mg-3-005","mg-3-031","mg-3-002"],"kontrol":null},{"id":"mg-3-009","konu":"3.1","terim":"Kayma, takılma ve düşme","ingilizce":"Slips, trips and falls","tanim":"Islak ya da kaygan zeminde kayarak, bir engele takılarak ya da yüksekte dengesini kaybederek yere düşmekle sonuçlanan kaza türüdür.","ornek":"Havuz barında yere dökülen buz erir; birkaç dakika sonra elinde tepsiyle geçen garson kayar.","sektor":"Otel ve restoranlarda sık görülen kazalardandır; hem çalışanı hem konuğu etkiler. Önlemi basittir: dökülen hemen silinir, kablo ve koli yoldan kaldırılır, kaymaz tabanlı ayakkabı giyilir, yükseğe sağlam merdivenle çıkılır.","iliskili":["mg-3-010","mg-3-011","mg-3-008"],"kontrol":null,"cizim":"bavul"},{"id":"mg-3-010","konu":"3.1","terim":"Islak zemin levhası","ingilizce":"Wet floor sign","tanim":"Yeni silinmiş ya da üzerine sıvı dökülmüş zeminin kaygan olduğunu gelip geçene haber veren, çoğunlukla sarı renkli ayaklı uyarı levhasıdır.","ornek":"Sabah 09.15, lobi: görevli paspasa başlamadan önce levhayı silineceği alanın iki ucuna koyar; zemin kuruyunca kaldırır.","sektor":"Levha silmeye başlamadan önce konur, zemin kuruyunca kaldırılır. Kuru zeminde unutulan levha zamanla ciddiye alınmaz olur. Levha zemini kurutmaz; yalnız kuruyana kadar gelip geçeni uyarır.","iliskili":["mg-3-009","mg-3-048","mg-3-011"],"kontrol":null,"kitapDisi":true,"gorsel":"t14e-yellow-wet-floor"},{"id":"mg-3-011","konu":"3.1","terim":"İş yeri düzeni","ingilizce":"Good housekeeping (workplace tidiness)","tanim":"Çalışma alanının temiz ve toplu tutulması, her malzemenin yerine konması ve geçiş yollarının boş bırakılmasıdır.","ornek":"Kat ofisinde çarşaf balyaları rafa dizilir, kimyasallar etiketli dolapta durur, kapının önünde ve koridorda hiçbir şey bırakılmaz.","sektor":"Dağınık depo ve dolu koridor, takılıp düşmenin ve yangında çıkışın kapanmasının başlıca nedenidir. Düzenli alan aynı zamanda hız kazandırır: aradığını ilk bakışta bulursun.","iliskili":["mg-3-009","mg-3-057","mg-3-012"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"mg-3-012","konu":"3.1","terim":"İSG kontrol listesi","ingilizce":"Safety checklist","tanim":"Bir çalışma alanındaki tehlikelerin ve alınan önlemlerin tek tek işaretlenerek gözden geçirildiği soru listesidir.","ornek":"Mutfak için hazırlanmış bir listeden satırlar: “Zemin kuru mu? Yangın tüpünün önü açık mı? Bıçaklar yerinde mi? Acil çıkış boş mu?”","sektor":"Liste, gözlemi kişinin hafızasına bırakmaz: her seferinde aynı noktalara bakılır ve sonuç yazılı kalır. “Hayır” işaretlenen her satır, amire bildirilecek bir iştir.","iliskili":["mg-3-008","mg-3-032","mg-3-011"],"kontrol":null},{"id":"mg-3-024","konu":"3.1","terim":"6331 sayılı İş Sağlığı ve Güvenliği Kanunu","ingilizce":"Occupational Health and Safety Law (No. 6331)","tanim":"Türkiye’de iş yerlerinde sağlık ve güvenliğin sağlanması için işverenlerin ve çalışanların görev, yetki, sorumluluk, hak ve yükümlülüklerini düzenleyen, 2012’de kabul edilen kanundur.","ornek":"Otelin personel panosunda asılı acil durum planı, sana verilen İSG eğitimi ve mutfaktaki uyarı işaretleri bu kanunun gereğidir.","sektor":"Kanun kamu ve özel sektör iş yerlerinde uygulanır; çıraklar ve stajyerler de kapsamdadır. Yani staj yaptığın otelde güvenliğin sağlanması bir iyilik değil, yasal bir zorunluluktur; senin kurallara uyman da öyle.","iliskili":["mg-3-025","mg-3-026","mg-3-001"],"kontrol":null},{"id":"mg-3-025","konu":"3.1","terim":"İşverenin İSG yükümlülüğü","ingilizce":"Employer's duties","tanim":"İşverenin, çalışanların işle ilgili sağlığını ve güvenliğini sağlamak için risk değerlendirmesi yaptırma, önlem alma, eğitim verme ve gerekli araç gereci sağlama görevidir.","ornek":"Otel yönetimi kat görevlilerine eldiven ve iş ayakkabısı verir, kimyasalların kullanımını anlatan eğitim düzenler ve bunun için çalışandan para almaz.","sektor":"İşveren, sağlık ve güvenlik önlemlerinin maliyetini çalışana yansıtamaz. Uzman ya da hekim hizmetini dışarıdan alması da sorumluluğunu ortadan kaldırmaz. Önlem almak, kazanın bedelini ödemekten her zaman daha ucuzdur.","iliskili":["mg-3-024","mg-3-026","mg-3-027"],"kontrol":null},{"id":"mg-3-026","konu":"3.1","terim":"Çalışanın İSG yükümlülüğü","ingilizce":"Employee's duties","tanim":"Çalışanın, aldığı eğitime ve talimatlara uyarak kendisinin ve yaptığı işten etkilenen başkalarının sağlık ve güvenliğini tehlikeye atmama görevidir.","ornek":"Mutfak stajyeri dilimleme makinesini eğitim almadan kullanmaz; bıçak siperinin gevşediğini görünce çalışmayı bırakıp şefine haber verir.","sektor":"Üç şeyi kapsar: araçları ve koruyucu donanımı kurallara uygun kullanmak, güvenlik donanımını çıkarmamak ya da değiştirmemek, gördüğü tehlikeyi ve eksikliği hemen bildirmek. Güvenlik yalnız işverenin işi değildir; iki tarafın ortak sorumluluğudur.","iliskili":["mg-3-025","mg-3-007","mg-3-040"],"kontrol":null,"gorsel":"m3-yellow-hard-hat"},{"id":"mg-3-027","konu":"3.1","terim":"İSG eğitimi","ingilizce":"OHS training","tanim":"İşverenin, çalışanlara işe başlamadan önce ve çalıştıkları sürece yinelenerek verdirdiği, işin tehlikelerini ve korunma yollarını öğreten eğitimdir.","ornek":"Stajın ilk günü, saat 09.00: eğitim salonunda yangın tüpünün kullanımı, kimyasal etiketleri ve acil çıkışlar anlatılır; ancak ondan sonra bölümüne gidersin.","sektor":"Eğitimde geçen süre çalışma süresinden sayılır ve maliyeti çalışana yansıtılmaz. İş ya da bölüm değiştiğinde, yeni bir makine geldiğinde eğitim yenilenir. Eğitimini almadığın işi yapmaman kural gereğidir, çekingenlik değildir.","iliskili":["mg-3-025","mg-3-026","mg-3-055"],"kontrol":null},{"id":"mg-3-028","konu":"3.1","terim":"İş güvenliği uzmanı","ingilizce":"Occupational safety specialist","tanim":"İş yerindeki tehlikeleri belirleyip önlem öneren, bu görev için ilgili bakanlıkça yetkilendirilmiş ve iş güvenliği uzmanlığı belgesi olan teknik elemandır.","ornek":"Uzman otelin mutfağını gezer, davlumbaz filtrelerinin temizliğini ve yangın tüplerinin yerini kontrol eder, eksikleri yazıp yönetime bildirir.","sektor":"Risk değerlendirmesine katılır, çalışma ortamını gözler, eğitim verir ve işverene rehberlik eder. Otelde onu gördüğünde çekinme: fark ettiğin tehlikeyi anlatabileceğin doğru kişilerden biridir.","iliskili":["mg-3-029","mg-3-032","mg-3-025"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-030","konu":"3.1","terim":"Çalışmaktan kaçınma hakkı","ingilizce":"Right to refuse unsafe work","tanim":"Ciddi ve yakın bir tehlikeyle karşılaşan çalışanın, durumun tespit edilip önlem alınmasını isteme ve başvurusu haklı bulunursa önlem alınana kadar o işi yapmama hakkıdır.","ornek":"Teknik serviste bir çalışandan, korkuluğu olmayan yüksek bir yere güvenlik donanımı olmadan çıkması istenir; çalışan durumu bildirir ve önlem alınmasını ister.","sektor":"Keyfî bir “yapmam” değildir: tehlike ciddi ve yakın olmalı, durum önce işverene ya da iş yerindeki İSG kuruluna bildirilmelidir. Tehlike önlenemeyecek kadar yakınsa çalışan önce güvenli bir yere geçer. Çalışan bu hakkı kullandığı için haklarını kaybetmez. Stajyer için pratik karşılığı: tehlikeli bulduğun işte dur ve hemen amirine söyle.","iliskili":["mg-3-024","mg-3-026","mg-3-003"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-3-031","konu":"3.1","terim":"İş kazası bildirimi","ingilizce":"Accident reporting","tanim":"İş yerinde yaşanan kazanın, ne kadar küçük görünürse görünsün amire haber verilmesi, kayda geçirilmesi ve işveren tarafından Sosyal Güvenlik Kurumuna bildirilmesidir.","ornek":"Serviste elini kesen stajyer “Küçük bir şey” deyip saklamaz; şefine söyler, şef olayı saatiyle ve yeriyle kayda geçirir.","sektor":"Çalışanın görevi kazayı hemen amirine bildirmektir; resmî bildirimi işveren yapar. Kayıt iki işe yarar: çalışanın haklarını korur ve aynı kazanın tekrarını önleyecek önlemin alınmasını sağlar. Saklanan kaza, bir sonrakini hazırlar.","iliskili":["mg-3-005","mg-3-006","mg-3-025"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"mg-3-072","konu":"3.1","terim":"İSG denetimi","ingilizce":"OHS inspection","tanim":"İş yerinde iş sağlığı ve güvenliği kurallarına uyulup uyulmadığının yetkili görevlilerce kontrol edilmesidir.","ornek":"Saat 11.00, bir otelin mutfağında yetkili görevli yangın söndürme tüplerinin, uyarı işaretlerinin ve çalışanların eldiven kullanımının kurallara uygun olup olmadığına bakar.","sektor":"Denetimin asıl amacı kazayı olmadan önlemektir: eksikler tespit edilir ve işverenin bunları gidermesi istenir.","iliskili":["mg-3-025","mg-3-026","mg-3-002"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-3-037","konu":"3.1","terim":"Kimyasalların güvenli kullanımı","ingilizce":"Safe use of chemicals","tanim":"Temizlik ve bakım kimyasallarının etiketine ve talimatına uygun, doğru ölçüde, birbirine karıştırmadan ve kendi kabında kullanılmasıdır.","ornek":"Kat görevlisi banyo temizleyicisini etiketteki ölçüyle sulandırır, eldivenini takar, banyonun kapısını açık tutar ve işi bitince şişeyi kat arabasındaki yerine koyar.","sektor":"Çamaşır suyu ile tuz ruhu karıştırılırsa zehirli klor gazı çıkar; “daha iyi temizlesin” diye kimyasal karıştırılmaz. Kimyasal içecek şişesine ya da etiketsiz kaba konmaz. Her kimyasalın tehlikesini ve kaza anında yapılacakları yazan belgeye güvenlik bilgi formu (GBF) denir.","iliskili":["mg-3-016","mg-3-041","mg-3-042"],"kontrol":null,"gorsel":"lastik-eldiven"},{"id":"mg-3-039","konu":"3.1","terim":"Elektrik güvenliği","ingilizce":"Electrical safety","tanim":"Elektrikli alet ve tesisatın çarpılmaya, yanığa ve yangına yol açmayacak biçimde kullanılması ve onarımının yalnız yetkili kişilerce yapılmasıdır.","ornek":"Kat görevlisi elektrik süpürgesinin kablosunda soyulma fark eder; süpürgeyi kullanmaz, fişini çekip kat şefine ve teknik servise bildirir.","sektor":"Temel kurallar: ıslak elle fişe ve düğmeye dokunulmaz, fiş kablosundan çekilmez, hasarlı kablo bantlanıp kullanılmaz, bir prize çok sayıda cihaz bağlanmaz. Arızayı onarmak stajyerin işi değildir; görevi kullanmamak ve bildirmektir.","iliskili":["mg-3-008","mg-3-026","mg-3-065"],"kontrol":null,"gorsel":"mg-elektrik-guvenligi"},{"id":"mg-3-045","konu":"3.1","terim":"Sağlık ve güvenlik işaretleri","ingilizce":"Safety signs","tanim":"Renk, biçim ve resimle bir tehlikeyi, yasağı, zorunluluğu ya da güvenli yolu dil bilmeyene bile anlatan levha ve işaretlerdir.","ornek":"Kimyasal deposunun kapısında üç levha yan yana durur: “Yetkisiz kişi giremez”, “Dikkat: aşındırıcı madde” ve “Eldiven tak”.","sektor":"Otelde çalışanlar da konuklar da farklı diller konuşur; işaret herkese aynı anda aynı şeyi söyler. İşaret önlemin yerini tutmaz, onu hatırlatır. Önü kapatılmış, solmuş ya da yanlış yere asılmış işaret hiç olmaması kadar zararlıdır.","iliskili":["mg-3-046","mg-3-047","mg-3-048"],"kontrol":null,"gorsel":"m3-singapore-safety-signs-01"},{"id":"mg-3-046","konu":"3.1","terim":"Güvenlik renkleri","ingilizce":"Safety colours","tanim":"İşaretlerde her birinin belirli bir anlamı olan kırmızı (yasak, tehlike alarmı ve yangınla mücadele donanımı), sarı (uyarı), mavi (zorunluluk) ve yeşil (acil çıkış, ilk yardım ve güvenli bölge) renkleridir.","ornek":"Koridorda yürürken: kırmızı dolap yangın hortumunu, yeşil ışıklı levha acil çıkışı, sarı ayaklı levha ıslak zemini gösterir.","sektor":"Renkleri bilen kişi levhadaki yazıyı okumadan ne yapacağını anlar: kırmızı “yapma” ya da “yangın donanımı burada”, sarı “dikkat et”, mavi “bunu yapmak zorundasın”, yeşil “güvenli yol burası” der.","iliskili":["mg-3-045","mg-3-049","mg-3-050"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-047","konu":"3.1","terim":"Yasaklayıcı işaret","ingilizce":"Prohibition sign","tanim":"Tehlikeye yol açabilecek bir davranışı yasaklayan; daire biçiminde, beyaz zeminli, kırmızı çerçeveli ve üzerinde kırmızı çapraz çizgi bulunan işarettir.","ornek":"Kazan dairesinin kapısındaki “Yetkisiz kimse giremez”, gaz tüplerinin durduğu alandaki “Sigara içilmez” ve “Açık alev kullanılmaz” levhaları.","sektor":"Resim siyah, çerçeve ve çapraz çizgi kırmızıdır. Yasak işareti pazarlık kabul etmez: “Bir dakikalığına” girmek de girmektir. Konuğun yasak bir alana yöneldiğini görürsen nazikçe uyarıp doğru yolu gösterirsin.","iliskili":["mg-3-045","mg-3-046","mg-3-048"],"kontrol":null,"gorsel":"mg-yasaklayici-isaret"},{"id":"mg-3-048","konu":"3.1","terim":"Uyarı işareti","ingilizce":"Warning sign","tanim":"Bir tehlikeye karşı dikkatli olunmasını isteyen; üçgen biçiminde, sarı zeminli, siyah çerçeveli ve siyah resimli işarettir.","ornek":"Elektrik panosunun kapağındaki şimşek resimli üçgen, kimyasal deposundaki “Aşındırıcı madde” ve çamaşırhanedeki “Sıcak yüzey” levhaları.","sektor":"Uyarı işareti bir şeyi yasaklamaz, “Burada şu tehlike var, ona göre davran” der. Islak zemin levhasının sarı olması da bu yüzdendir: sarı, dikkat rengidir.","iliskili":["mg-3-045","mg-3-010","mg-3-049"],"kontrol":null,"gorsel":"mg-uyari-isareti"},{"id":"mg-3-049","konu":"3.1","terim":"Emredici işaret","ingilizce":"Mandatory sign","tanim":"Uyulması zorunlu bir davranışı bildiren; daire biçiminde, mavi zeminli ve beyaz resimli işarettir.","ornek":"Kimyasal hazırlama odasının girişindeki “Eldiven tak” ve “Gözlük kullan”, tadilat alanının girişindeki “Baret tak” levhaları.","sektor":"Mavi daire bir tavsiye değil, bir talimattır: gösterdiği koruyucu takılmadan o alana girilmez, o iş yapılmaz. Yasaklayıcı işaret “yapma” derken emredici işaret “yap” der.","iliskili":["mg-3-045","mg-3-040","mg-3-047"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-050","konu":"3.1","terim":"Acil çıkış ve ilk yardım işareti","ingilizce":"Emergency escape and first-aid sign","tanim":"Kaçış yolunu, acil çıkışı ya da ilk yardım donanımının yerini gösteren; dikdörtgen ya da kare biçiminde, yeşil zeminli ve beyaz resimli işarettir.","ornek":"Kat koridorunun sonunda, kapının üstünde yanan yeşil “koşan insan ve ok” levhası; personel odasındaki ilk yardım çantasının üstündeki yeşil levha.","sektor":"Çalıştığın her alanda en yakın yeşil levhanın yerini ilk gün öğren. Duman bastığında ya da elektrik kesildiğinde konuklar yolu bilmez; onlara yönü gösterecek kişi sensin.","iliskili":["mg-3-057","mg-3-046","mg-3-063"],"kontrol":null,"gorsel":"mg-acil-cikis-isareti"},{"id":"mg-3-051","konu":"3.1","terim":"Yangınla mücadele işareti","ingilizce":"Fire-fighting sign","tanim":"Yangın söndürme tüpü, yangın hortumu ve alarm butonu gibi donanımın yerini gösteren; dikdörtgen ya da kare biçiminde, kırmızı zeminli ve beyaz resimli işarettir.","ornek":"Mutfak girişinde, duvardaki tüpün hemen üstünde asılı kırmızı zeminli beyaz tüp resmi; uzaktan bakınca tüpün yerini gösterir.","sektor":"İşaret yüksekte durur ki önüne bir şey konsa bile donanımın yeri görülsün. İşaretin altı boş kalmışsa, yani tüp yerinde değilse bu bir güvensiz durumdur ve bildirilir.","iliskili":["mg-3-066","mg-3-067","mg-3-046"],"kontrol":null,"cizim":"yangin"},{"id":"mg-3-057","konu":"3.1","terim":"Acil çıkış","ingilizce":"Emergency exit","tanim":"Tehlike anında binayı en kısa ve güvenli yoldan terk etmeyi sağlayan, yeşil işaretlerle gösterilen kapı ve kaçış yoludur.","ornek":"Kat koridorunun sonundaki yangın merdiveni kapısı: içeriden tek hareketle açılır, üstünde yeşil levha yanar, önünde hiçbir şey durmaz.","sektor":"Acil çıkışın önüne kat arabası, koli ya da çamaşır torbası “iki dakikalığına” bile bırakılmaz; kapı kilitlenmez. Önü kapalı bir acil çıkış gördüğünde engeli kaldırırsın ya da hemen amirine bildirirsin.","iliskili":["mg-3-050","mg-3-056","mg-3-011"],"kontrol":null,"gorsel":"sektor-acil-cikis"},{"id":"mg-3-074","konu":"3.1","terim":"İSG gözlem ölçütleri","ingilizce":"Safety observation criteria","tanim":"Bir iş yerinin güvenliğini değerlendirirken hangi başlıklara hangi soruyla bakılacağını önceden belirleyen kontrol başlıklarıdır.","ornek":"Sabah 09.00, otel mutfağını gözlemleyen öğrenci grubu; çalışma alanı, elektrik, makine, koruyucu donanım, kimyasal, yangın, işaret, davranış ve temizlik başlıklarını tek tek kontrol eder.","sektor":"Ölçüt belirlenirken işin türü, kullanılan araç gereç, ortamın özellikleri ve çalışanların görevleri dikkate alınır.","iliskili":["mg-3-075","mg-3-076","mg-3-012"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-075","konu":"3.1","terim":"Gözlem derecelendirme ölçeği","ingilizce":"Observation rating scale","tanim":"Her gözlem ölçütünün “uygun”, “kısmen uygun” ya da “uygun değil” diye işaretlendiği ve yanına açıklama yazıldığı kayıt tablosudur.","ornek":"Öğrenci denetçi, mutfak gözleminde “Yangın söndürücü ulaşılabilir yerde” satırına “uygun değil” yazar; açıklamaya tüpün önüne konmuş kolileri not eder.","sektor":"Bir otelin mutfağı, kat hizmetleri, çamaşırhanesi ve teknik servisi aynı ölçekle gezilirse bölümlerin durumu birbiriyle karşılaştırılabilir. “Uygun değil” yazılan her satır amire götürülecek somut bir iş olur ve bir sonraki turda düzelip düzelmediğine bakılır; ölçeğin yararı izlenimi kayda çevirmesidir.","iliskili":["mg-3-074","mg-3-076"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-3-076","konu":"3.1","terim":"Gözlem verilerini sınıflandırma","ingilizce":"Classifying observation data","tanim":"Gözlemde görülen durumun ne olduğu, nerede olduğu, kimleri etkileyebileceği ve hangi tedbirin alındığı kaydedilip risk türüne göre gruplanmasıdır.","ornek":"Kat hizmetleri gözleminde “etiketsiz temizlik maddesi” kimyasal riske, “belden eğilerek yük kaldırma” ergonomik riske yazılır; hangisinin daha acil olduğu böylece görülür.","sektor":"Sınıflandırma hangi riskin önce ele alınacağını belirlemeyi kolaylaştırır; kayıtlar eksik aramak için değil güvenli düzeni geliştirmek için tutulur.","iliskili":["mg-3-074","mg-3-075","mg-3-080"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-3-077","konu":"3.1","terim":"Güvenlik tedbiri","ingilizce":"Safety measure","tanim":"Bir tehlikenin zarara dönüşmesini önlemek ya da etkisini azaltmak için alınan her türlü önlemdir.","ornek":"Havuz başındaki kaygan zemin için kaymaz kaplama yapılması ve uyarı levhası konması birer güvenlik tedbiridir.","sektor":"Güvenlik tedbiri otelin her bölümünde başka biçimde görünür: mutfakta ocağın yanındaki yangın battaniyesi, koridorda acil çıkış levhası, çamaşırhanede makinenin koruyucusu. Tek bir tedbire güvenilmez; birkaç tedbir üst üste konunca biri aksasa bile kaza çoğu zaman önlenir ve güvenli bir işletmeyi gösteren de bu katmanlı düzendir.","iliskili":["mg-3-003","mg-3-034","mg-3-035"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-078","konu":"3.1","terim":"Yangın ve patlama riski","ingilizce":"Fire and explosion risk","tanim":"Yanıcı madde, açık alev, kıvılcım ya da uygunsuz depolamadan doğan yangın veya patlama ihtimalidir.","ornek":"Mutfak deposunda yanıcı temizlik sıvısının ocak kenarındaki rafta tutulması bu riski büyütür.","sektor":"Otelde bu risk en çok mutfakta (gaz, kızgın yağ, davlumbazda biriken yağ), çamaşırhanede (kurutma makinesinde biriken lif) ve depolarda (kimyasal ve ambalaj yığını) toplanır. Yangın konuklar uyurken de çıkabileceği için bu noktalar düzenli temizlenir; yanıcı maddeyi ısı kaynağından uzak tutmak da riski küçültmenin en basit yoludur.","iliskili":["mg-3-077","mg-3-064","mg-3-069"],"kontrol":null,"cizim":"yangin"},{"id":"mg-3-079","konu":"3.1","terim":"Elektrik riski","ingilizce":"Electrical risk","tanim":"Tesisat, kablo, priz ve cihazlardan kaynaklanan elektrik çarpması, yanık ya da yangın ihtimalidir.","ornek":"Kat koridorunda hasarlı bir uzatma kablosunun halının altından geçirilmesi elektrik riski oluşturur.","sektor":"Elektrik riski su ile elektriğin yan yana olduğu banyo, mutfak, çamaşırhane ve havuz başında en çok dikkat ister. Isınan priz, yanık kokusu ya da kıvılcım çıkaran cihaz kat görevlisinin odada fark edebileceği ilk uyarılardır; cihaz kullanılmaz ve teknik servise haber verilir, çünkü onarım yetkili kişinin işidir.","iliskili":["mg-3-077","mg-3-039","mg-3-100"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-013","konu":"3.2","terim":"Meslek hastalığı","ingilizce":"Occupational disease","tanim":"Çalışanın, yaptığı işin niteliği ya da çalışma koşulları yüzünden bir etkene tekrar tekrar maruz kalması sonucu ortaya çıkan hastalıktır.","ornek":"Yıllarca eldivensiz, güçlü temizlik maddeleriyle çalışan bir görevlinin ellerinde geçmeyen bir cilt hastalığı gelişmesi.","sektor":"Programın anahtar kavramlarındandır. İş kazası bir anda olur; meslek hastalığı sessizce, aylar ve yıllar içinde gelişir. Bu yüzden “Bugün bir şey olmadı” demek yanıltır: korunma, belirti çıkmadan önce başlar.","iliskili":["mg-3-005","mg-3-023","mg-3-016"],"kontrol":null},{"id":"mg-3-014","konu":"3.2","terim":"Fiziksel risk etkenleri","ingilizce":"Physical hazards","tanim":"Gürültü, titreşim, aşırı sıcak ya da soğuk, yetersiz aydınlatma, nem ve radyasyon gibi çalışma ortamının fiziksel koşullarından doğan sağlık tehditleridir.","ornek":"Yaz günü, saat 13.00: ızgara başındaki aşçı saatlerce yüksek sıcaklıkta çalışır; soğuk hava deposuna giren depo görevlisi ise dondurucu soğukla karşılaşır.","sektor":"Ders kitabı meslek hastalığına yol açan etkenleri beş grupta ele alır: fiziksel, kimyasal, biyolojik, ergonomik ve psikososyal. Fiziksel olanlara karşı havalandırma, yeterli ışık, mola ve uygun kıyafet gibi önlemler alınır.","iliskili":["mg-3-015","mg-3-016","mg-3-017"],"kontrol":null},{"id":"mg-3-015","konu":"3.2","terim":"İş yerinde gürültü","ingilizce":"Workplace noise","tanim":"Çalışma ortamında işitmeye zarar verebilen, dikkati dağıtan ve yorgunluğu artıran yüksek ve rahatsız edici sestir.","ornek":"Çamaşırhanede yıkama ve kurutma makineleri aynı anda çalışırken iki görevli birbirini duymak için bağırmak zorunda kalır.","sektor":"Uzun süre yüksek gürültüde çalışmak kalıcı işitme kaybına yol açabilir; ayrıca uyarı sesinin ve alarmın duyulmasını zorlaştırır. Önlem sırası: makinenin bakımı ve ses yalıtımı, gürültüde kalınan sürenin kısaltılması, gerekiyorsa kulak koruyucu.","iliskili":["mg-3-014","mg-3-013","mg-3-040"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-3-016","konu":"3.2","terim":"Kimyasal risk etkenleri","ingilizce":"Chemical hazards","tanim":"Temizlik maddeleri, dezenfektanlar, çözücüler ve havuz kimyasalları gibi maddelerin solunması, cilde ya da göze teması veya yutulmasıyla sağlığa verebileceği zararlardır.","ornek":"Havuz teknisyeni klor bidonunu açarken gözlük ve eldiven takar; kat görevlisi banyo temizleyicisini kapalı banyoda değil, kapı ve havalandırma açıkken kullanır.","sektor":"Otelin en çok kimyasal kullanan bölümleri kat hizmetleri, çamaşırhane, mutfak ve havuzdur. Kimyasal vücuda başlıca üç yoldan girer: solunum, cilt ve ağız. Korunmanın temeli etiketi okumak, doğru ölçü ve doğru koruyucudur.","iliskili":["mg-3-037","mg-3-041","mg-3-043"],"kontrol":null},{"id":"mg-3-017","konu":"3.2","terim":"Biyolojik risk etkenleri","ingilizce":"Biological hazards","tanim":"Bakteri, virüs, mantar ve parazit gibi hastalık yapan canlıların çalışana bulaşmasıyla ortaya çıkan sağlık tehditleridir.","ornek":"Çamaşırhane görevlisi katlardan gelen kirli çarşaf ve havluları eldivenle ayırır; kat görevlisi çöp torbasını, içine elini sokmadan, ağzından tutarak alır.","sektor":"Kirli çamaşır, çöp, banyo yüzeyleri ve çiğ gıda başlıca kaynaklardır. Çöpün içinde kırık cam ya da kesici bir şey olabilir; torba bastırılmaz, bedene yaslanmaz. Eldiven, el yıkama ve temiz ile kirlinin ayrı tutulması temel korunmadır.","iliskili":["mg-3-014","mg-3-041","mg-3-013"],"kontrol":null},{"id":"mg-3-018","konu":"3.2","terim":"Ergonomi","ingilizce":"Ergonomics","tanim":"İşin, araçların ve çalışma ortamının insan bedeninin ölçülerine ve sınırlarına uygun biçimde düzenlenmesidir.","ornek":"Resepsiyonda ekran göz hizasına, sandalye görevlinin boyuna göre ayarlanır; kat görevlisine boyuna uygun uzunlukta saplı paspas verilir.","sektor":"Programın anahtar kavramlarındandır. Ergonominin ilkesi “insan işe değil, iş insana uydurulur”dur. Bedene uymayan düzen önce yorar, sonra ağrıtır, yıllar içinde hastalığa dönüşür; uygun düzen aynı işi daha az yorgunlukla yaptırır.","iliskili":["mg-3-019","mg-3-038","mg-3-013"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-019","konu":"3.2","terim":"Kas-iskelet sistemi rahatsızlıkları","ingilizce":"Musculoskeletal disorders (MSDs)","tanim":"Yanlış duruş, ağır yük, tekrarlayan hareket ya da uzun süre aynı konumda çalışma yüzünden kas, eklem ve omurgada zamanla ortaya çıkan ağrı ve hasarlardır.","ornek":"Bir vardiyada onlarca yatak yapan, her birinde şilteyi kaldıran ve eğilen kat görevlisinde yıllar içinde gelişen bel ağrısı.","sektor":"Otelcilik ayakta ve bedenle yapılan bir iştir: bagaj taşıma, yatak yapma, tepsi taşıma, saatlerce ayakta durma. Doğru kaldırma tekniği, yardımcı araç (bagaj arabası, kat arabası) ve kısa esneme molaları bu rahatsızlıkların başlıca önlemidir.","iliskili":["mg-3-018","mg-3-038","mg-3-013"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-3-020","konu":"3.2","terim":"Psikososyal riskler","ingilizce":"Psychosocial risks","tanim":"İşin düzenlenme ve yönetilme biçiminden ya da iş yerindeki ilişkilerden kaynaklanan, çalışanın ruh ve beden sağlığını bozabilen etkenlerdir.","ornek":"Sezonun en yoğun haftası: resepsiyonda eksik kişiyle çalışılır, vardiyalar uzar, sırada bekleyen konuklar sabırsızlanır ve görevliye kimse destek olmaz.","sektor":"Programın anahtar kavramlarındandır. Aşırı iş yükü, düzensiz ve uzun vardiya, belirsiz görev tanımı, destek görmeme ve iş yerinde kötü muamele başlıca örnekleridir. Gözle görünmezler, ama dikkat dağınıklığı yoluyla kazaya, uzun sürerse hastalığa yol açabilirler.","iliskili":["mg-3-021","mg-3-022","mg-3-014"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-3-021","konu":"3.2","terim":"İş stresi","ingilizce":"Work-related stress","tanim":"İşin istedikleri çalışanın gücünü, zamanını ya da imkânlarını aştığında ortaya çıkan bedensel ve zihinsel gerginliktir.","ornek":"Akşam 20.00, restoran dolu: tek başına on masaya bakan stajyer siparişleri karıştırmaya, elindeki tabakları düşürmeye başlar.","sektor":"Programdaki anahtar kavram “stres”tir. Kısa süreli gerginlik insanı toparlayabilir; uzun süren stres ise dikkati, uykuyu ve sağlığı bozar, kaza ihtimalini artırır. Çözümü yalnız kişinin “dayanması” değildir: iş yükü ve vardiya düzeni de gözden geçirilir.","iliskili":["mg-3-020","mg-3-022","mg-3-007"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-3-022","konu":"3.2","terim":"Mobbing (psikolojik taciz)","ingilizce":"Mobbing (workplace bullying)","tanim":"İş yerinde bir çalışanın, bir ya da birkaç kişi tarafından sistemli ve sürekli biçimde aşağılanması, dışlanması ya da yıldırılmasıdır.","ornek":"Bir çalışana aylardır kimse selam vermez, yaptığı her iş herkesin önünde küçümsenir, toplantılardan bilerek haberdar edilmez.","sektor":"Programın anahtar kavramlarındandır. Tek seferlik bir tartışma ya da haklı bir uyarı mobbing değildir; mobbingi ayıran şey süreklilik ve yıldırma amacıdır. Yaşayan kişi olanları tarihleriyle not eder, tek başına katlanmaz, güvendiği bir amire ya da insan kaynaklarına bildirir.","iliskili":["mg-3-020","mg-3-021","mg-3-002"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-023","konu":"3.2","terim":"Sağlık gözetimi","ingilizce":"Health surveillance","tanim":"Çalışanın sağlığının, işe girerken ve çalıştığı sürece belirli aralıklarla yapılan muayenelerle izlenmesidir.","ornek":"Çamaşırhaneye yeni alınan görevli işe başlamadan önce muayeneden geçer; sonraki dönemlerde kontrolleri yinelenir.","sektor":"İşveren sağlar, iş yeri hekimi yürütür. Amaç çalışanın işe uygunluğunu görmek ve meslek hastalığını daha başlangıcında yakalamaktır. Çalışan da şikâyetini saklamaz: “Elim kızarıyor, kulağım çınlıyor” demek erken uyarıdır.","iliskili":["mg-3-029","mg-3-013","mg-3-025"],"kontrol":null,"gorsel":"m3-esfigmomanometro"},{"id":"mg-3-029","konu":"3.2","terim":"İş yeri hekimi","ingilizce":"Occupational physician","tanim":"Çalışanların sağlığını izleyen, işe giriş ve periyodik muayenelerini yapan, bu görev için yetkilendirilmiş ve iş yeri hekimliği belgesi olan hekimdir.","ornek":"Kat görevlisi ellerindeki kızarıklığı iş yeri hekimine gösterir; hekim kullanılan kimyasalı ve eldiveni sorar, önlem önerir.","sektor":"Görevi yalnız hastayı tedavi etmek değil, çalışanı hasta etmeyecek çalışma koşullarını gözetmektir. İş güvenliği uzmanı ortama, iş yeri hekimi insana bakar; ikisi birlikte çalışır.","iliskili":["mg-3-028","mg-3-023","mg-3-013"],"kontrol":null},{"id":"mg-3-036","konu":"3.2","terim":"Balık kılçığı diyagramı","ingilizce":"Fishbone diagram (cause-and-effect diagram)","tanim":"Bir sorunun ya da kazanın olası nedenlerini insan, makine, çevre, ekipman, yöntem ve yönetim gibi başlıklar altında dallara ayırarak gösteren neden-sonuç şemasıdır.","ornek":"“Komi bulaşıkhanede düştü” sorununun kılçıkları: insan (acele), çevre (ıslak zemin, zayıf ışık), malzeme (kaymayan ayakkabı yok), yöntem (levha koyma alışkanlığı yok).","sektor":"Kazayı tek bir kişinin dikkatsizliğine bağlamak kolaydır ama eksiktir. Bu şema asıl nedeni, yani kök nedeni bulmaya yarar; kök neden giderilmezse aynı kaza başka birinin başına gelir. Ishikawa diyagramı olarak da bilinir.","iliskili":["mg-3-032","mg-3-034","mg-3-005"],"kontrol":null,"cizim":"grafik"},{"id":"mg-3-038","konu":"3.2","terim":"Elle taşıma işleri","ingilizce":"Manual handling","tanim":"Bir yükün makine kullanmadan, insan gücüyle kaldırılması, indirilmesi, itilmesi, çekilmesi ya da taşınmasıdır.","ornek":"Sabah 08.30, depo: iki stajyer içecek kolilerini taşıma arabasına yükler; ağır koliyi dizlerini bükerek ve gövdelerine yakın tutarak kaldırırlar.","sektor":"Bagaj, içecek kolisi, çarşaf balyası, şilte: otelde her bölüm yük taşır. Kural sırası şudur: önce yükü tart (gözünle), ağırsa araba kullan ya da yardım iste, kaldıracaksan dizlerini bük, belini dik tut, yükle birlikte belini burma.","iliskili":["mg-3-019","mg-3-018","mg-3-034"],"kontrol":null,"cizim":"bavul"},{"id":"mg-3-080","konu":"3.2","terim":"Risk etkeni","ingilizce":"Risk factor","tanim":"Çalışanın sağlığını bozabilecek fiziksel, kimyasal, biyolojik, ergonomik ya da psikososyal herhangi bir etkendir.","ornek":"Çamaşırhanede çalışan biri her gün saatlerce yüksek sese maruz kalıyorsa gürültü onun için bir risk etkenidir.","sektor":"Etken kontrol altına alınmazsa sıra şöyle gelişir: risk etkeni, maruziyet, sağlık sorunu.","iliskili":["mg-3-081","mg-3-014","mg-3-013"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-081","konu":"3.2","terim":"Maruziyet","ingilizce":"Exposure","tanim":"Çalışanın bir risk etkeniyle temas etmesi ya da onun etkisi altında kalmasıdır.","ornek":"Havuz teknisyeni her gün uzun süre klor buharının bulunduğu kapalı makine dairesinde çalışıyorsa klora maruz kalıyordur.","sektor":"Maruziyet süresi ve yoğunluğu arttıkça sağlık sorunu ihtimali de artar.","iliskili":["mg-3-080","mg-3-013","mg-3-082"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-082","konu":"3.2","terim":"Radyasyon","ingilizce":"Radiation","tanim":"Ortamda yayılan ve fazla maruz kalındığında vücut dokularına zarar verebilen ışın enerjisidir.","ornek":"Yaz sezonunda saat 11.00-16.00 arasında plajda çalışan cankurtaran, güneşin zararlı ışınlarına maruz kalır; şapka, gözlük ve gölgelik bu etkiyi azaltır.","sektor":"Gürültü, titreşim ve aşırı sıcak gibi etkenlerle birlikte fiziksel risk etkenleri arasında sayılır.","iliskili":["mg-3-014","mg-3-081","mg-3-080"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-084","konu":"3.2","terim":"Ortamda alınacak önlemler","ingilizce":"Environmental (collective) controls","tanim":"Tehlike tamamen ortadan kaldırılamıyorsa, onun çalışma ortamına yayılmasını engelleyen ve aynı anda birçok kişiyi koruyan önlemlerdir.","ornek":"Çamaşırhaneye güçlü bir havalandırma sistemi kurulması ve gürültülü makinelerin ses yalıtımlı bir bölmeye alınması, o bölümdeki herkesi aynı anda korur.","sektor":"Otelde mutfaktaki davlumbaz ve havalandırma, jeneratör dairesinin ses yalıtımı ve havuz kimyasal deposunun havalandırması bu gruptandır. Bir kez kurulunca vardiya değişse de yeni bir stajyer gelse de aynı anda herkesi korur; kişinin dikkatine ve hatırlamasına bağlı olmaması en büyük üstünlüğüdür.","iliskili":["mg-3-088","mg-3-085","mg-3-035"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-085","konu":"3.2","terim":"Kişiye yönelik önlemler","ingilizce":"Personal controls","tanim":"Kaynakta ve ortamda alınan önlemlere rağmen kalan risk için çalışana uygulanan, kişisel koruyucu donanım ve eğitim gibi önlemlerdir.","ornek":"Tozlu bir tadilat alanında çalışan teknik servis görevlisine uygun filtreli bir maske verilir ve nasıl takılacağı gösterilir.","sektor":"Bu önlemler diğerlerinin yerine geçmez, onları tamamlar; maske de işe uygun seçilmeli, doğru takılmalı ve düzenli değiştirilmelidir.","iliskili":["mg-3-084","mg-3-040","mg-3-089"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-3-086","konu":"3.2","terim":"Güvenli çalışma ortamı","ingilizce":"Safe working environment","tanim":"Risk etkenlerinin kontrol altında olduğu, çalışanların eğitim aldığı, riskleri bildirebildiği ve uygun ekipmanla çalıştığı ortamdır.","ornek":"Otel mutfağında zemin kuru, ocak vanaları kontrol edilmiş, çalışanlar eğitim almış ve gördükleri tehlikeyi şeflerine rahatça söyleyebiliyor.","sektor":"Güvenli ortam yalnız temiz ve düzenli olmak demek değildir.","iliskili":["mg-3-080","mg-3-081","mg-3-013"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-3-007","konu":"3.3","terim":"Güvensiz davranış","ingilizce":"Unsafe act","tanim":"Çalışanın güvenlik kuralına uymayarak kendisini ya da başkasını tehlikeye atan hareketidir.","ornek":"Yetişmek için merdivenden koşarak inmek, eldiven takmadan kimyasal kullanmak, yüksek rafa sandalyeye çıkarak uzanmak.","sektor":"Çoğu zaman kötü niyetten değil, aceleden ve alışkanlıktan doğar. Kazaların nedeni yalnız çalışanın dikkatsizliği değildir; yine de kendi davranışın, elindeki en güçlü önlemdir.","iliskili":["mg-3-008","mg-3-002","mg-3-026"],"kontrol":null},{"id":"mg-3-008","konu":"3.3","terim":"Güvensiz durum","ingilizce":"Unsafe condition","tanim":"Çalışma ortamında, araçta ya da donanımda bulunan ve kazaya zemin hazırlayan eksiklik ya da bozukluktur.","ornek":"Koridorda kenarı kıvrılıp kalkmış halı, kablosu soyulmuş elektrik süpürgesi, ampulü yanmayan depo, önüne koli yığılmış acil çıkış kapısı.","sektor":"Güvensiz davranış kişiden, güvensiz durum ortamdan kaynaklanır; kazaların çoğunda ikisi bir aradadır. Güvensiz durumu gören kişi “Nasılsa biri söyler” demez: kendisi bildirir.","iliskili":["mg-3-007","mg-3-003","mg-3-012"],"kontrol":null,"gorsel":"m3-dual-light-switches-with-exposed-w"},{"id":"mg-3-033","konu":"3.3","terim":"Olasılık ve sonuç","ingilizce":"Likelihood and consequence","tanim":"Bir riskin büyüklüğünü belirleyen iki ölçüdür: zararın gerçekleşme ihtimali ile gerçekleşirse ortaya çıkacak sonucun, yani yaralanma, hastalık, maddi kayıp ya da iş aksamasının ağırlığıdır.","ornek":"Lobide kâğıt kesiği: olabilir ama hafiftir. Fritözde kızgın yağ sıçraması: hem olabilir hem ağır yanık bırakır. İkincisine önce önlem alınır.","sektor":"İkisi birlikte düşünülür: çok seyrek ama çok ağır sonuçlu bir tehlike (yangın gibi) de, sık ama hafif sonuçlu bir tehlike de ciddiye alınır. Bu sıralama, sınırlı zamanın ve paranın önce nereye harcanacağını gösterir.","iliskili":["mg-3-004","mg-3-032","mg-3-035"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-034","konu":"3.3","terim":"Riski kaynağında önleme","ingilizce":"Control at source","tanim":"Tehlikeyle, insanlara ulaşmasını beklemeden ortaya çıktığı yerde mücadele ederek onu ortadan kaldırmak ya da azaltmaktır.","ornek":"Bulaşıkhanede zemin sürekli ıslanıyorsa herkese “Dikkat edin” demek yerine sızdıran hortum onarılır ve zemine kaymaz kaplama yapılır.","sektor":"Sorunun kendisini çözmek, insanlardan sürekli dikkat beklemekten daha güvenilirdir; çünkü insan yorulur, unutur, acele eder. Kaynağında çözülemeyen risk için etkisini azaltacak önlemler sırayla devreye girer.","iliskili":["mg-3-035","mg-3-032","mg-3-036"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-035","konu":"3.3","terim":"Kontrol hiyerarşisi","ingilizce":"Hierarchy of controls","tanim":"Önlemlerin en etkiliden en zayıfa doğru sıralanmasıdır: tehlikeyi ortadan kaldırma, daha az tehlikelisiyle değiştirme, teknik önlem, kural ve eğitim, en son kişisel koruyucu donanımdır.","ornek":"Güçlü bir temizlik kimyasalı için sırayla sorulur: Hiç kullanmasak olur mu? Daha zararsızı var mı? Havalandırma yeterli mi? Talimat ve eğitim var mı? En son: eldiven ve gözlük.","sektor":"Uluslararası iş güvenliği literatüründe kullanılan sıralamadır. Herkesi birden koruyan önlem (korkuluk, havalandırma) kişiyi tek tek koruyan donanımdan önce gelir. Koruyucu donanım son basamaktır, çünkü tehlikeyi yok etmez; yalnız seninle tehlike arasına girer.","iliskili":["mg-3-034","mg-3-040","mg-3-032"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-3-040","konu":"3.3","terim":"Kişisel koruyucu donanım (KKD)","ingilizce":"Personal protective equipment (PPE)","tanim":"Çalışanı işteki sağlık ve güvenlik risklerinden korumak için giydiği, taktığı ya da tuttuğu eldiven, gözlük, maske, baret ve iş ayakkabısı gibi donanımlardır.","ornek":"Otelin teknik servis görevlisi tadilat alanına baretini takarak girer; mutfakta aşçı ısıya dayanıklı eldivenle fırından tepsi çıkarır.","sektor":"Programın anahtar kavramlarındandır. İşveren ücretsiz verir, çalışan doğru ve sürekli kullanır. Bedenine uymayan, yırtılmış ya da kirlenmiş donanım korumaz; değiştirilmesi için amire bildirilir. “Bir kereden bir şey olmaz” diyerek takmamak bilinen bir kaza başlangıcıdır.","iliskili":["mg-3-041","mg-3-042","mg-3-035"],"kontrol":null,"gorsel":"baret"},{"id":"mg-3-041","konu":"3.3","terim":"Koruyucu eldiven","ingilizce":"Protective gloves","tanim":"Elleri kimyasala, sıcağa, kesilmeye ya da kirli yüzeye karşı koruyan ve yapılan işe göre seçilen eldivendir.","ornek":"Kat görevlisi banyo temizliğinde kimyasala dayanıklı lastik eldiven, bahçe görevlisi budama yaparken kalın iş eldiveni giyer.","sektor":"Her eldiven her işe uymaz: ince temizlik eldiveni sıcak tepsiyi tutmaya, kumaş eldiven kimyasala karşı korumaya yaramaz. Delinmiş eldiven içine kimyasal alır ve cilde daha uzun süre temas ettirir; atılır, yenisi istenir.","iliskili":["mg-3-040","mg-3-037","mg-3-017"],"kontrol":null,"gorsel":"is-eldiveni"},{"id":"mg-3-042","konu":"3.3","terim":"Koruyucu gözlük","ingilizce":"Safety goggles","tanim":"Gözleri sıçrayan kimyasala, toza ve parçacığa karşı koruyan, yanları da kapalı olan gözlüktür.","ornek":"Havuz görevlisi kimyasalı bidondan ölçü kabına aktarırken koruyucu gözlüğünü takar; bir damla sıçrasa bile göze ulaşmaz.","sektor":"Göz, kimyasala karşı vücudun en savunmasız yerlerinden biridir. Kimyasal, baş hizasından yukarıya püskürtülürken ya da bir kaptan ötekine aktarılırken sıçrama ihtimali en yüksektir; gözlük tam o anlar için vardır.","iliskili":["mg-3-040","mg-3-037","mg-3-016"],"kontrol":null,"gorsel":"m3-laser-goggles-eagle-pair-ep-3-190"},{"id":"mg-3-043","konu":"3.3","terim":"Solunum koruyucu maske","ingilizce":"Respirator (respiratory protection)","tanim":"Toz, duman ve kimyasal buharın solunmasını azaltmak için ağız ile burnu kapatan koruyucu donanımdır.","ornek":"Tadilat yapılan katta zımpara tozu havada uçuşurken teknik servis görevlisi filtreli maskesini takarak çalışır.","sektor":"Her maske her şeye karşı korumaz: toz maskesi kimyasal buharı tutmaz. Hangi iş için hangi maskenin gerektiğini iş güvenliği uzmanı ve kimyasalın etiketi söyler. Maske yüze tam oturmuyorsa kenarından hava girer ve koruma azalır.","iliskili":["mg-3-040","mg-3-016","mg-3-028"],"kontrol":null,"gorsel":"toz-maskesi"},{"id":"mg-3-087","konu":"3.3","terim":"Kök neden","ingilizce":"Root cause","tanim":"Bir kazanın görünen olayının ve doğrudan nedeninin arkasında yatan, giderilmezse olayın tekrarına yol açan asıl nedendir.","ornek":"Komi bulaşıkhanede kayıp düşer (olay); neden ıslak zemindir (doğrudan neden); kök neden, hortum sızdırdığı hâlde bakım yapılmamasıdır.","sektor":"Otelde aynı yerde ikinci kez kaza oluyorsa çoğunlukla kök neden bulunmamış, olay “dikkatsizlik” denerek geçilmiştir. Oysa arkasında günlerce bekleyen bir arıza kaydı, eksik bir eğitim ya da yetişmeyen bir iş yükü olabilir; ekibin işi suçlu aramak değil, nedeni bulmaktır.","iliskili":["mg-3-005","mg-3-098","mg-3-092"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-088","konu":"3.3","terim":"Toplu korunma ve mühendislik önlemleri","ingilizce":"Collective protection and engineering controls","tanim":"Tehlikenin çalışanlara ulaşmasını havalandırma, koruyucu kapak ya da korkuluk gibi teknik düzenlemelerle engelleyen, aynı anda birçok kişiyi koruyan önlemlerdir.","ornek":"Otel çamaşırhanesinde silindir ütüye, el sıkışmasını önleyen bir koruma çubuğu takılır; ütüyü kullanan herkes korunur.","sektor":"Kişisel önlemlerden önce düşünülür, çünkü herkesi birden korur.","iliskili":["mg-3-084","mg-3-099","mg-3-100"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-089","konu":"3.3","terim":"İdari önlemler","ingilizce":"Administrative controls","tanim":"İşin düzenlenmesi ve çalışan davranışlarının güvenli hâle getirilmesiyle ilgili önlemlerdir.","ornek":"Otel müdürü vardiyaları yorgunluğu azaltacak biçimde planlar, yeni gelen personele İSG eğitimi verir ve uyarı levhalarını asar.","sektor":"Otelde vardiya planı, bölümlerin iş talimatları, işe yeni başlayanlara verilen oryantasyon eğitimi ve düzenli tatbikatlar bu gruptadır. Bunlar insanın uymasına dayandığı için kâğıtta kalırsa işe yaramaz; bu yüzden kontrol edilmeli ve düzenli olarak tekrarlanmalıdır.","iliskili":["mg-3-088","mg-3-085","mg-3-027"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-090","konu":"3.3","terim":"Tehlikeyi ortadan kaldırma","ingilizce":"Elimination","tanim":"Kontrol basamaklarının en etkilisi olan, tehlikenin kaynağıyla birlikte tamamen yok edilmesidir.","ornek":"Otelde sürekli ıslanan bir geçit yerine kuru bir güzergâh yapılarak kaygan zemin tehlikesinin hiç oluşmaması.","sektor":"Kat hizmetleri deposunda sık kullanılan temizlik malzemesini yüksek raf yerine bel hizasındaki rafa koymak kat görevlisini merdivene çıkma ihtiyacından kurtarır; yani tehlike azaltılmaz, hiç oluşmaz. Önlemlerin en etkilisi bu olduğu için çözüm ararken ilk bakılacak şey tehlikenin tamamen kaldırılıp kaldırılamayacağıdır.","iliskili":["mg-3-034","mg-3-091","mg-3-035"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-091","konu":"3.3","terim":"Daha az tehlikeli olanla değiştirme","ingilizce":"Substitution","tanim":"Tehlike tamamen yok edilemiyorsa, daha az tehlikeli bir madde, yöntem ya da araç kullanmaktır.","ornek":"Kat hizmetlerinde çok aşındırıcı bir kireç çözücü yerine daha hafif bir temizleyici kullanmak.","sektor":"Otel odalarının yenilenmesi sırasında çözücü bazlı boya yerine su bazlı boya seçmek buna iyi bir örnektir: boyayı uygulayan teknik servis personeli daha az zararlı buhar solur, odaya yerleşen konuk da keskin boya kokusuyla karşılaşmaz. Değiştirmenin üstünlüğü çalışanı da konuğu da aynı anda korumasıdır.","iliskili":["mg-3-090","mg-3-034","mg-3-035"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-092","konu":"3.3","terim":"Çözüm planı","ingilizce":"Action plan","tanim":"Belirlenen bir riskin tehlikesini, nedenini, olasılığını, olası sonucunu ve alınacak önlemi, sorumlu kişiyle birlikte yazıya döken plandır.","ornek":"Havuz kenarı kayma riski için plan: tehlike kaygan zemin; neden eksik drenaj; önlem kaymaz kaplama; sorumlu teknik servis şefi.","sektor":"Planda hem kaynağında önleme hem etkiyi azaltma adımları bulunur.","iliskili":["mg-3-087","mg-3-035","mg-3-097"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-3-093","konu":"3.3","terim":"Baret","ingilizce":"Hard hat","tanim":"Başa düşen ya da çarpan cisimlere karşı koruyan sert kasktır.","ornek":"Otelin yeni kat inşaatında çalışan teknik servis görevlisi, üstte iş yapılan alana girerken baretini takar.","sektor":"Otel yenilenirken ya da yeni bir kat eklenirken şantiye alanına giren herkes, otel çalışanı da olsa, baret takar; çünkü yukarıda iş yapılan yerin altında bir alet ya da malzeme saniyeler içinde düşebilir. Baret yalnız başa uyduğunda ve sağlam olduğunda koruyucudur.","iliskili":["mg-3-040","mg-3-041","mg-3-094"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-094","konu":"3.3","terim":"Kulak koruyucu","ingilizce":"Ear protectors","tanim":"Yüksek sesin kulağa zarar vermesini önleyen kulaklık ya da tıkaçtır.","ornek":"Otel çamaşırhanesinde makineler çalışırken görevli kulak koruyucusunu takar.","sektor":"Kazan dairesi, jeneratör odası ve bulaşıkhane gibi gürültülü yerlerde çalışan personelin işitmesini koruyan basit ama vazgeçilmez donanım kulak koruyucudur. Gürültü kulağı sessizce yıprattığı için “kısa sürecek” diye koruyucu takmamanın bedeli yıllar sonra kalıcı işitme kaybıdır.","iliskili":["mg-3-040","mg-3-015","mg-3-093"],"kontrol":null,"cizim":"kulak-dinleme"},{"id":"mg-3-095","konu":"3.3","terim":"İş ayakkabısı","ingilizce":"Safety footwear","tanim":"Ayağı kayma, ezilme ya da düşen cisimlere karşı koruyan, işe uygun seçilmiş ayakkabıdır.","ornek":"Mutfak personeli, ıslak zeminde kaymasın diye kaymaz tabanlı iş ayakkabısı giyer.","sektor":"Mal kabulde koli ve palet taşıyanın ayağı ezilebilir, banyoda ıslak zeminde çalışan kat görevlisi ise kayabilir; ikisinin ayakkabıda aradığı özellik farklıdır. Bu yüzden iş ayakkabısı rahat olduğu kadar o işe uygun da olmalıdır.","iliskili":["mg-3-040","mg-3-096","mg-3-010"],"kontrol":null,"cizim":"el-yikama"},{"id":"mg-3-096","konu":"3.3","terim":"Koruyucu giysi","ingilizce":"Protective clothing","tanim":"Vücudu sıcak, kimyasal, kir ya da kesilme gibi tehlikelerden koruyan, işe uygun iş elbisesidir.","ornek":"Çamaşırhane görevlisi, kirli çarşafları ayırırken koruyucu önlük giyer.","sektor":"Aşçı ceketi ve önlüğü yalnız düzgün görünmek için değildir; kaynar su ya da sıcak yağ sıçradığında vücutla arasına bir koruma katmanı koyar. Havuz kimyasalını hazırlayan teknik personel ya da kirli çamaşırla çalışan görevli de işine uygun giysi giyer, çünkü her tehlikenin giysisi farklıdır.","iliskili":["mg-3-040","mg-3-095","mg-3-041"],"kontrol":null,"cizim":"uniforma"},{"id":"mg-3-032","konu":"3.4","terim":"Risk değerlendirmesi","ingilizce":"Risk assessment","tanim":"İş yerindeki tehlikelerin belirlenmesi, bunlardan doğan risklerin derecelendirilmesi ve alınacak önlemlerin kararlaştırılması için yapılan çalışmadır.","ornek":"Ekip çamaşırhaneyi adım adım gezer: sıcak ütü, ıslak zemin, ağır çamaşır arabası, kimyasal bidonları not edilir; her biri için önlem ve sorumlu yazılır.","sektor":"Programın anahtar kavramlarındandır. Yaptırmak işverenin yükümlülüğüdür; işi yapan çalışanların görüşü de alınır, çünkü tehlikeyi en iyi o işi her gün yapan bilir. Bir kez yapılıp rafa kaldırılmaz: iş, makine ya da ortam değişince yenilenir.","iliskili":["mg-3-033","mg-3-035","mg-3-003"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-044","konu":"3.4","terim":"Makine koruyucusu","ingilizce":"Machine guard","tanim":"Makinenin kesen, dönen ya da ezen hareketli parçasına elin ya da giysinin ulaşmasını engelleyen kapak ya da siperdir.","ornek":"Mutfaktaki dilimleme makinesinin bıçağını örten siper; çamaşırhanedeki silindir ütünün el sıkışmasını önleyen koruma çubuğu.","sektor":"“İşi yavaşlatıyor” diye koruyucu sökülmez, bağlanmaz, devre dışı bırakılmaz. Makine temizlenmeden önce kapatılır ve fişi çekilir. Eğitimini almadığın makineyi kullanmazsın; bol kollu giysi ve sarkan takı dönen parçaya kapılabilir.","iliskili":["mg-3-026","mg-3-035","mg-3-040"],"kontrol":null,"gorsel":"mg-makine-koruyucusu"},{"id":"mg-3-097","konu":"3.4","terim":"Risk yönetimi","ingilizce":"Risk management","tanim":"İş yerindeki tehlikelerin belirlenmesi, risklerin değerlendirilmesi, önlemlerin uygulanması ve bu önlemlerin izlenmesi sürecidir.","ornek":"Otel yönetimi her yıl risk listesini günceller, alınan önlemlerin iş yerinde uygulanıp uygulanmadığını kat kat dolaşarak kontrol eder.","sektor":"Yazılı belge tek başına yetmez; önlemlerin gerçekten uygulandığı da izlenir.","iliskili":["mg-3-032","mg-3-092","mg-3-031"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-098","konu":"3.4","terim":"Eleştirel düşünme","ingilizce":"Critical thinking","tanim":"Bir durumu yalnızca kabul etmek ya da reddetmek yerine kanıtlara dayanarak incelemek, eksik ve güçlü yönlerini görmek ve çözümlerin uygulanabilirliğini sorgulamaktır.","ornek":"Kayıp düşen bir çalışan için “Dikkatsizdi” demek yerine “Levha vardı mı, zemin neden ıslaktı, ayakkabı uygun muydu?” diye sorulması.","sektor":"Bir kazadan sonra “çalışan dikkatsizdi” demek kolaydır; eleştirel düşünen otel yöneticisi levhaya, zemine, ayakkabıya ve vardiya süresine de bakar. Aynı kazanın bir başkasının başına gelmemesini sağlayan yol da budur.","iliskili":["mg-3-087","mg-3-032","mg-3-033"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-099","konu":"3.4","terim":"Toplu korunma donanımları","ingilizce":"Collective protective equipment","tanim":"Makine koruyucusu, havalandırma, toz emiş düzeneği, korkuluk, acil durdurma düğmesi ve yangın söndürme sistemi gibi aynı anda birçok kişiyi koruyan donanımlardır.","ornek":"Mutfak davlumbazı ve yangın söndürme sistemi mutfaktaki bütün çalışanları aynı anda korur.","sektor":"Donanımın bulunması kadar doğru seçilmesi, doğru kullanılması ve düzenli denetlenmesi önemlidir.","iliskili":["mg-3-088","mg-3-044","mg-3-100"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-100","konu":"3.4","terim":"Acil durdurma düğmesi","ingilizce":"Emergency stop button","tanim":"Tehlike anında makineyi hemen durdurmak için basılan, genellikle kırmızı ve kolay ulaşılır düğmedir.","ornek":"Çamaşırhanedeki silindir ütüde bir görevlinin kolu sıkışırken yanındaki arkadaşı düğmeye basarak makineyi durdurur.","sektor":"Büyük mutfak makinelerinde ve çamaşırhanedeki ütü hatlarında bulunan bu düğme, el ya da kol sıkışırsa makineyi bir anda durdurmak içindir. Çalışmaya başlamadan önce yerini öğrenmek ve önünü koliyle ya da arabayla kapatmamak saniyelerin önem taşıdığı bir kazada en hızlı çaredir.","iliskili":["mg-3-044","mg-3-099","mg-3-101"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-101","konu":"3.4","terim":"Korkuluk","ingilizce":"Guardrail","tanim":"Yüksek bir yerden düşmeyi önlemek için kenara yapılan koruyucu bariyerdir.","ornek":"Otel çatı terasında çalışan teknik servis personelini düşmeden koruyan teras kenarı korkuluğu.","sektor":"Balkon, teras bar ve merdiven boşluğundaki korkuluk yalnız çalışanı değil, otelin çocuklar dâhil bütün konuklarını da korur. Gevşemiş ya da paslanmış bir korkuluk “nasılsa dayanır” denilerek geçilmez; teknik servise bildirmek ve onarılana kadar o bölümü kapatmak güvenliğin gereğidir.","iliskili":["mg-3-099","mg-3-102","mg-3-100"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-102","konu":"3.4","terim":"Emniyet kemeri","ingilizce":"Safety harness","tanim":"Yüksekte çalışırken düşmeyi önleyen ya da durduran, sağlam bir noktaya bağlanan koruyucu kemerdir.","ornek":"Otel cephesindeki tabelayı onaran görevli, çalışmaya başlamadan önce emniyet kemerini sağlam bir bağlantı noktasına bağlar.","sektor":"Otelin çatısındaki klima ve güneş paneli bakımı ya da dış cephe cam temizliği gibi yüksekte yapılan işlerde tek bir hata ağır sonuç doğurur. Kemer yalnız sağlam bir noktaya bağlanıp işi bilen biri tarafından kullanıldığında korur; eğitimi olmayan kimsenin, stajyer dâhil, o yükseklikte işi yoktur.","iliskili":["mg-3-101","mg-3-099","mg-3-040"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-103","konu":"3.4","terim":"Uyarı işaretinin etkili olma koşulları","ingilizce":"Conditions for effective warning signs","tanim":"Bir işaretin işe yaraması için görünür, anlaşılır, doğru yerde ve uygun biçimde yerleştirilmiş olması gerektiğini anlatan koşullardır.","ornek":"“Gözlük kullanınız” levhası malzeme dolabının arkasında kalmışsa kimse görmez ve işaret görevini yapamaz.","sektor":"Levha kirliyse ya da çalışanın göremeyeceği yerdeyse etkili uyarı sayılmaz.","iliskili":["mg-3-045","mg-3-048","mg-3-049"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-052","konu":"3.5","terim":"Acil durum","ingilizce":"Emergency","tanim":"İş yerinde yangın, patlama, tehlikeli kimyasal yayılması, doğal afet ya da ağır yaralanma gibi hemen müdahale, ilk yardım ya da tahliye gerektiren olaydır.","ornek":"Gece 02.10, üçüncü katta duman dedektörü alarm verir; resepsiyon, güvenlik ve kat görevlisi dakikalar içinde plana göre harekete geçer.","sektor":"Acil durumda zaman dardır ve düşünmeye vakit kalmaz; insanlar o an ne öğrendilerse onu yapar. Otelde ayrıca binayı tanımayan, uykudaki, belki dil bilmeyen konuklar vardır: onların güvenliği personelin hazırlığına bağlıdır.","iliskili":["mg-3-053","mg-3-054","mg-3-056"],"kontrol":null,"gorsel":"m3-fire-alarm"},{"id":"mg-3-053","konu":"3.5","terim":"Acil durum planı","ingilizce":"Emergency plan","tanim":"Bir iş yerinde yaşanabilecek acil durumlarda kimin ne yapacağını, nasıl haber verileceğini, hangi yoldan çıkılacağını ve nerede toplanılacağını önceden yazıya döken plandır.","ornek":"Personel koridorundaki panoda kat krokisi asılıdır: kaçış yolları yeşil oklarla, yangın tüpleri kırmızıyla, toplanma alanı ve ekiplerin adları ayrı ayrı gösterilmiştir.","sektor":"Programın anahtar kavramlarındandır. Plan olay anında yazılmaz, olaydan önce yazılır ve herkese öğretilir. İyi bir plan şu sorulara cevap verir: Kim haber verir? Kim müdahale eder? Kim konukları yönlendirir? Nerede toplanılır?","iliskili":["mg-3-052","mg-3-054","mg-3-055"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-054","konu":"3.5","terim":"Acil durum ekibi","ingilizce":"Emergency response team","tanim":"Yangınla mücadele, arama-kurtarma, tahliye ve ilk yardım gibi görevleri bir olay anında yürütmek üzere önceden seçilmiş ve eğitilmiş çalışanlardan oluşan ekiptir.","ornek":"Alarm çalınca teknik servisten iki kişi yangın tüpüyle olay yerine gider, kat şefi konukları merdivene yönlendirir, ilk yardımcı çantasıyla hazır bekler.","sektor":"Görev paylaşımı karışıklığı önler: biri haber verir, biri müdahale eder, biri yol gösterir. Ekipte olmayan çalışanın görevi de bellidir: kahramanlık yapmaz, talimata uyar, konuklara sakin biçimde yardım eder ve toplanma alanına gider.","iliskili":["mg-3-053","mg-3-061","mg-3-055"],"kontrol":null,"gorsel":"m3-pompiers-ste-anne-de-beaupre-2012"},{"id":"mg-3-055","konu":"3.5","terim":"Tatbikat","ingilizce":"Emergency drill","tanim":"Acil durum planının işleyip işlemediğini görmek için, gerçek bir olay yaşanıyormuş gibi yapılan uygulamalı denemedir.","ornek":"Salı sabahı 10.00’da otelde alarm çalar; personel planlandığı gibi katları boşaltır, toplanma alanında sayım yapılır ve süre not edilir.","sektor":"Kâğıt üzerindeki plan ancak denenince öğrenilir. Tatbikat eksikleri gösterir: kilitli kalan kapı, duyulmayan alarm, yerini bilmeyen personel. Tatbikatı “Nasılsa gerçek değil” diye hafife alan kişi, gerçek olayda ne yapacağını bilemez.","iliskili":["mg-3-053","mg-3-056","mg-3-058"],"kontrol":null,"gorsel":"t14za-yangin-tatbikati"},{"id":"mg-3-056","konu":"3.5","terim":"Tahliye","ingilizce":"Evacuation","tanim":"Tehlike altındaki bir binanın ya da alanın, içindeki herkes güvenli bir yere çıkarılarak düzenli biçimde boşaltılmasıdır.","ornek":"Yangın alarmı çalar; kat görevlisi koridordaki konuklara “Lütfen beni izleyin” diyerek merdivene yönelir; asansöre yürüyenlere de merdiveni gösterir.","sektor":"Programın anahtar kavramlarındandır. Tahliyede asansör kullanılmaz, koşulmaz, itişilmez, eşya almak için geri dönülmez. Personelin sakin sesi ve net cümleleri konuklardaki paniği azaltır; yürümekte zorlanan konuklara öncelikle yardım edilir.","iliskili":["mg-3-057","mg-3-058","mg-3-053"],"kontrol":null,"gorsel":"m3-finnish-emergency-exit-sign"},{"id":"mg-3-058","konu":"3.5","terim":"Toplanma alanı","ingilizce":"Assembly point","tanim":"Tahliye edilen kişilerin binadan uzakta, güvenli bir açık yerde bir araya geldiği ve sayımın yapıldığı önceden belirlenmiş noktadır.","ornek":"Otelin otoparkının uzak köşesindeki yeşil levhalı alan: tahliyeden sonra her bölüm şefi kendi ekibini orada sayar.","sektor":"Sayım, içeride kalan olup olmadığını anlamanın tek yoludur. Bu yüzden kimse toplanma alanından haber vermeden ayrılmaz ve “tehlike geçti” denmeden binaya dönmez; yoksa ekipler olmayan birini içeride aramak zorunda kalır.","iliskili":["mg-3-056","mg-3-053","mg-3-055"],"kontrol":null,"gorsel":"sektor-toplanma-noktasi"},{"id":"mg-3-059","konu":"3.5","terim":"112 Acil Çağrı Merkezi","ingilizce":"Emergency call centre (112)","tanim":"Türkiye’de ambulans, itfaiye, polis ve jandarma gibi acil yardım ekiplerine tek numaradan ulaşılan çağrı merkezidir.","ornek":"Arayan kişi sakin bir sesle söyler: “Otelin mutfağında bir çalışan bayıldı. Adres şu. Bir kişi. Ben mutfak şefiyim.” Görevli “Kapatabilirsiniz” diyene kadar hatta kalır.","sektor":"Aramada olayın türü, açık adres, kat ya da bölüm, yaralı veya mahsur kalan kişi olup olmadığı, yangın-duman-patlama-elektrik riski ve arayanın adı ile telefonu söylenir (ders kitabına göre). Telefon, görevli söylemeden kapatılmaz. Otelde durum aynı anda amire ya da resepsiyona da bildirilir ki ekipleri girişte karşılayıp olay yerine götürecek biri olsun.","iliskili":["mg-3-062","mg-3-060","mg-3-052"],"kontrol":null,"gorsel":"mg-112-ambulans"},{"id":"mg-3-060","konu":"3.5","terim":"İlk yardım","ingilizce":"First aid","tanim":"Bir kaza ya da ani hastalıkta, sağlık ekibi gelene kadar hayatı korumak ve durumun kötüleşmesini önlemek için olay yerinde eldeki imkânlarla yapılan ilaçsız uygulamalardır.","ornek":"Havuz başında bir konuk fenalaşır; ilk yardım eğitimi almış cankurtaran yanına gider, bir garson 112’yi arar, bir diğeri çevreyi boşaltır.","sektor":"Programın anahtar kavramlarındandır. İlk yardım tedavi değildir ve ilaç verilmez; amaç sağlık ekibi gelene kadar zaman kazanmaktır. Sıra hep aynıdır: önce kendi can güvenliğin, sonra haber verme, sonra eğitimli kişinin müdahalesi.","iliskili":["mg-3-061","mg-3-062","mg-3-059"],"kontrol":null},{"id":"mg-3-061","konu":"3.5","terim":"İlk yardımcı","ingilizce":"First aider","tanim":"Yetkili bir kurumda ilk yardım eğitimini tamamlayıp sınavını geçerek ilk yardımcı belgesi almış, bu uygulamaları yapmaya yetkili kişidir.","ornek":"Vardiya çizelgesinde bazı adların yanında küçük bir işaret vardır: o vardiyada görevli ilk yardımcıları gösterir. Mutfakta biri yaralanınca önce o kişi çağrılır.","sektor":"Eğitimin yoksa yapacakların bellidir: ortamı güvenli hâle getir, 112’nin aranmasını sağla, ilk yardımcıyı ve amirini çağır, hastanın yanında kal. Yaralıyı gereksiz yere hareket ettirmezsin, bir şey yedirip içirmezsin, kulaktan dolma yöntem denemezsin.","iliskili":["mg-3-060","mg-3-054","mg-3-063"],"kontrol":null},{"id":"mg-3-062","konu":"3.5","terim":"Koruma, Bildirme, Kurtarma (KBK)","ingilizce":"Protect, Call, Rescue (first aid steps)","tanim":"İlk yardımın sırayla uygulanan üç temel adımıdır: olay yerini güvenli hâle getirme, 112’ye haber verme ve eğitimli kişinin müdahalesidir.","ornek":"Çamaşırhanede bir görevli yerde hareketsiz yatıyor ve yanında kopuk bir kablo var: önce kimse ona ve kabloya dokunmaz, elektrik şalterden kestirilir (koruma), sonra 112 aranır (bildirme), ardından ilk yardımcı müdahale eder (kurtarma).","sektor":"Sıra değişmez, çünkü yardıma koşarken yaralanan kişi ikinci bir hasta olur ve artık kimseye yardım edemez. Koruma adımında yeni bir kaza ihtimali ortadan kaldırılır: elektrik kesilir, gaz kapatılır, meraklılar uzaklaştırılır.","iliskili":["mg-3-060","mg-3-059","mg-3-061"],"kontrol":null,"gorsel":"m3-jasdf-automatic-cardiopulmonary-re"},{"id":"mg-3-063","konu":"3.5","terim":"İlk yardım çantası","ingilizce":"First aid kit","tanim":"İçinde sargı bezi, steril gazlı bez, yara bandı, eldiven ve makas gibi temel ilk yardım malzemelerinin bulunduğu, yeri herkesçe bilinen çantadır.","ornek":"Mutfağın girişinde, yeşil levhanın altında duvara asılı çanta; küçük bir kesikte şef çantayı açar, kullanılan malzemeyi sonra listeye yazar.","sektor":"Çantanın yerini ilk gün öğren; aranırken geçen her dakika kayıptır. Çanta kilitli dolaba konmaz, önü kapatılmaz. Eksilen ya da tarihi geçen malzeme sorumlusuna bildirilir; boş çanta, olmayan çantadır.","iliskili":["mg-3-060","mg-3-061","mg-3-050"],"kontrol":null,"gorsel":"sektor-ilk-yardim"},{"id":"mg-3-064","konu":"3.5","terim":"Yangın üçgeni","ingilizce":"Fire triangle","tanim":"Yanmanın gerçekleşmesi için bir arada bulunması gereken üç şeyi, yani yanıcı maddeyi, ısıyı ve oksijeni gösteren modeldir.","ornek":"Tavadaki alev almış yağın üstüne kapak kapatılır: oksijen kesilir ve alev söner. Ocağın kapatılması ısıyı keser.","sektor":"Üçgenin bir kenarı kaldırılırsa yangın söner: soğutarak ısıyı, örterek oksijeni, uzaklaştırarak yanıcı maddeyi yok edersin. Bütün söndürme yöntemleri bu üç yoldan birine dayanır.","iliskili":["mg-3-065","mg-3-066","mg-3-068"],"kontrol":null,"gorsel":"m3-candle-flame-closeup"},{"id":"mg-3-065","konu":"3.5","terim":"Yangın sınıfları","ingilizce":"Classes of fire","tanim":"Yangınların, yanan maddenin türüne göre harflerle ayrılmasıdır: A katı maddeler, B yanıcı sıvılar, C yanıcı gazlar, D yanabilen metallerdir.","ornek":"Çamaşırhanede tutuşan çarşaf A sınıfı, depoda alev alan boya incelticisi B sınıfı, mutfakta tüpten sızan gazın tutuşması C sınıfı yangındır.","sektor":"Sınıf, yangının neyle söndürüleceğini belirler; yanlış söndürücü yangını büyütebilir. Avrupa standardında mutfaktaki kızgın yemeklik yağ yangını ayrıca F sınıfı sayılır ve üzerine su dökülmez. Elektrikli cihaz yangınında da su kullanılmaz; önce elektrik kesilir.","iliskili":["mg-3-064","mg-3-066","mg-3-068"],"kontrol":null},{"id":"mg-3-066","konu":"3.5","terim":"Yangın söndürme tüpü","ingilizce":"Fire extinguisher","tanim":"Başlangıç hâlindeki küçük bir yangını söndürmek için kullanılan; içinde kuru kimyevi toz, karbondioksit, köpük ya da su bulunan taşınabilir basınçlı cihazdır.","ornek":"Büroda çöp kovası tutuşur; eğitim almış görevli duvardaki tüpü alır, pimini çeker, hortumu alevin dibine tutar ve tetiğe basarak sağa sola süpürür.","sektor":"Tüpün etiketi hangi yangın sınıflarında kullanılacağını gösterir. Kullanım sırası: pimi çek, alevin dibine nişan al, tetiğe bas, süpür. Tüp yalnız küçük yangında, kaçış yolun arkandayken ve eğitimin varsa kullanılır; yangın büyüyorsa uğraşma: alarm ver, çık, kapıyı arkandan kapat.","iliskili":["mg-3-065","mg-3-051","mg-3-067"],"kontrol":null,"gorsel":"t14e-sondurme-tupleri"},{"id":"mg-3-067","konu":"3.5","terim":"Yangın dolabı","ingilizce":"Fire hose cabinet","tanim":"Koridor ve ortak alanlarda duvarda bulunan, içinde su tesisatına bağlı sarılı yangın hortumu olan kırmızı dolaptır.","ornek":"Her kat koridorunda, asansörün yakınında duran kırmızı kapaklı dolap; kat görevlisi arabasını onun önüne park etmez.","sektor":"Dolabın önü her zaman açık tutulur; içine temizlik malzemesi konmaz. Hortumdan su çıkar: elektrikli cihaz ve kızgın yağ yangınında kullanılmaz. Hortumu kullanmak eğitim ve güç ister; bu iş acil durum ekibinin ve itfaiyenin işidir.","iliskili":["mg-3-066","mg-3-051","mg-3-054"],"kontrol":null,"gorsel":"yangin-dolabi"},{"id":"mg-3-068","konu":"3.5","terim":"Yangın battaniyesi","ingilizce":"Fire blanket","tanim":"Aleve örtülerek havasını kesen ve yangını boğarak söndüren, yanmaz kumaştan yapılmış örtüdür.","ornek":"Mutfakta tavadaki yağ alev alır; aşçı ocağı kapatır, duvardaki kutudan battaniyeyi çekip tavanın üstüne örter ve soğuyana kadar kaldırmaz.","sektor":"Mutfakların vazgeçilmezidir. Alev almış kızgın yağa su dökülmez: su yağı sıçratır ve alevi büyütür; doğrusu ocağı kapatmak ve alevin üstünü örtmektir. Battaniye, giysisi tutuşan bir kişiyi sarmak için de kullanılır.","iliskili":["mg-3-064","mg-3-065","mg-3-066"],"kontrol":null,"kitapDisi":true,"cizim":"yangin"},{"id":"mg-3-069","konu":"3.5","terim":"Gaz sızıntısı","ingilizce":"Gas leak","tanim":"Doğal gazın ya da tüp gazın tesisattan, vanadan ya da cihazdan kontrolsüz biçimde ortama yayılmasıdır.","ornek":"Sabah 06.30, mutfağa ilk giren komi gaz kokusu alır; ışığı açmadan dışarı çıkar ve uzaklaşıp şefine ve teknik servise haber verir.","sektor":"Gaz kokusu alındığında elektrik düğmesine, prize ve cihazlara dokunulmaz, ateş yakılmaz; küçücük bir kıvılcım patlamaya yeter. Güvenliyse vana kapatılır, kapı ve pencere açılır, ortam boşaltılır ve haber, kokunun olmadığı bir yerden verilir.","iliskili":["mg-3-052","mg-3-065","mg-3-056"],"kontrol":null},{"id":"mg-3-070","konu":"3.5","terim":"Çök-Kapan-Tutun","ingilizce":"Drop, Cover and Hold On","tanim":"Deprem anında sarsıntı geçene kadar sağlam bir eşyanın yanına çökmek, başı ve enseyi koruyarak kapanmak ve sabit bir yere tutunmaktan oluşan korunma hareketidir.","ornek":"Sarsıntı başladığında restorandaki garson camdan ve asılı avizeden uzaklaşır, sağlam bir masanın yanına çöker, başını ve ensesini koruyarak tutunur.","sektor":"Sarsıntı sürerken koşmak, merdivene ya da asansöre yönelmek, balkona çıkmak yaralanmaların başlıca nedenidir. Sarsıntı durunca plana göre sakin biçimde tahliye edilir ve toplanma alanına gidilir; konuklara da aynı hareket kısa ve net cümlelerle söylenir.","iliskili":["mg-3-052","mg-3-056","mg-3-058"],"kontrol":null,"kitapDisi":true,"cizim":"uyari"},{"id":"mg-3-071","konu":"3.5","terim":"Göçük","ingilizce":"Collapse (cave-in)","tanim":"Toprağın, kayanın ya da yapı parçalarının aniden çökmesi ve insanların altında kalma tehlikesi doğurmasıdır.","ornek":"Saat 10.00, otelin yeni kat inşaatında eski duvarın bir bölümü çöker; çalışma alanındaki kişiler tahliye edilir ve 112 aranır.","sektor":"Turizm yapılarının onarım ve inşaat işlerinde görülebilir; göçükte altında kalanı kendi başına çekmeye çalışmak yerine 112 aranır ve eğitimli ekibin gelmesi beklenir.","iliskili":["mg-3-052","mg-3-056","mg-3-059"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-073","konu":"3.5","terim":"Acil durum müdahale evreleri","ingilizce":"Phases of emergency response","tanim":"Bir acil durumun kriz öncesi, kriz süreci, müdahale aşaması ve kriz sonrası olmak üzere dört evrede ele alınmasıdır.","ornek":"Otel yangın tatbikatında önce plan ve tüpler hazırlanır (öncesi), alarm çalar (süreç), ekip tahliye ve ilk yardım yapar (müdahale), sonra eksikler toplantıda konuşulur (sonrası).","sektor":"Hazırlıksız yakalanan işletme yalnız müdahaleye bakar; iyi işletme öncesine ve sonrasına da yatırım yapar.","iliskili":["mg-3-052","mg-3-053","mg-3-055"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-104","konu":"3.5","terim":"Kriz","ingilizce":"Crisis","tanim":"Acil durum doğru yönetilmediğinde olayın kontrolünü zorlaştıran, can güvenliğini tehdit eden ve daha büyük kayıplara yol açabilen durumdur.","ornek":"Otel mutfağındaki küçük yangında kimse görev almaz, herkes farklı yöne koşar ve yangın koridora yayılır.","sektor":"Otelde kriz yalnız binayı değil, konuğun güvenini ve otelin adını da sarsar: yangın alarmının çaldığı bir gecede kimin ne yapacağı belli değilse küçük bir olay kısa sürede kontrolden çıkar. Krizi önleyen şey görevlerin önceden belirlenip tatbikatla denenmesidir.","iliskili":["mg-3-052","mg-3-105","mg-3-106"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-105","konu":"3.5","terim":"Zaman baskısı","ingilizce":"Time pressure","tanim":"Acil durumda karar vermek ve harekete geçmek için çok az sürenin bulunmasıdır.","ornek":"Mutfakta yağ yangını başladığında alev büyümeden ocağın kapatılması ve yangın battaniyesinin hemen örtülmesi gerekir.","sektor":"Gece vardiyasında alarm çaldığında resepsiyon görevlisinin düşünmeye vakti yoktur; bu yüzden acil durum adımları önceden öğrenilir ve telefon numaraları masada hazır tutulur. Zaman baskısı altında doğru davranışı getiren şey o anda verilen karar değil, önceden yapılan hazırlıktır.","iliskili":["mg-3-104","mg-3-106","mg-3-107"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-3-106","konu":"3.5","terim":"Belirsizlik","ingilizce":"Uncertainty","tanim":"Olayın nasıl gelişeceğinin, kimleri etkileyeceğinin ve hangi riskleri doğuracağının ilk anda tam bilinememesidir.","ornek":"Gaz kokusu alınan mutfakta kaçağın hangi cihazdan geldiği hemen anlaşılmaz.","sektor":"Yangın alarm panelinde bir bölgenin ışığı yandığında yangının gerçek mi, yanlış alarm mı olduğu ilk anda belli olmayabilir; otelde elektrik kesildiğinde asansörde kimsenin kalıp kalmadığı da bilinmez. Belirsizlikte doğru tutum tahmin yürütmek yerine bilgiyi sistemli biçimde toplamak ve alarmı gerçek sayarak hazırlıklı davranmaktır.","iliskili":["mg-3-104","mg-3-105","mg-3-108"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-107","konu":"3.5","terim":"İkincil riskler","ingilizce":"Secondary risks","tanim":"Acil durumun kendisi dışında, onun yüzünden ortaya çıkan yeni tehlikelerdir.","ornek":"Yangın sırasında depodaki boya tenekesinin ya da elektrik panosunun ikinci bir tehlike oluşturması.","sektor":"Depremden sonra otel mutfağında açık kalan ocak ya da kopan bir gaz borusu ikinci bir yangına dönüşebilir; tahliyede merdivende itişmek de yeni yaralanmalara yol açar. Bu yüzden iyi bir acil durum planı yalnız ilk tehlikeyi değil, onun doğuracağı yeni tehlikeleri de hesaba katar; bunu düşünmek plan hazırlayanın görevidir.","iliskili":["mg-3-104","mg-3-069","mg-3-078"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-108","konu":"3.5","terim":"Acil durumu problem olarak yapılandırma","ingilizce":"Framing an emergency as a problem","tanim":"Olayın nerede olduğunu, kimleri etkilediğini, hangi riskleri taşıdığını, hangi kaynakların kullanılabileceğini ve hangi sınırlılıkların bulunduğunu belirleyerek müdahaleyi planlamaktır.","ornek":"“Yangın çıktı” demek yetmez: Mutfakta, saat 12.30, iki kişi içeride, yağ var, tüp kapının yanında, çıkış kapısı bir tane.","sektor":"Gece resepsiyonuna gelen “bir katta sorun var” haberi yönetici ve itfaiye için yeterli değildir; “üçüncü kattaki odada duman var, içeride iki konuk bulunuyor, söndürücü koridorun sonunda” denirse herkes ne yapacağını bilir. Olayı yer, kişi, risk ve imkân olarak sıralamak otelde paniğin yerine planı getiren yöntemdir.","iliskili":["mg-3-106","mg-3-109","mg-3-052"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-109","konu":"3.5","terim":"Olay yeri güvenliğini değerlendirme","ingilizce":"Scene safety assessment","tanim":"Müdahaleden önce ortamın güvenli olup olmadığına bakmaktır; ortam güvenli değilse tehlikeli alandan uzaklaşılması, çevredekilerin uyarılması ve yetkililere haber verilmesi gerekir.","ornek":"Dumanlı depoya ilk giren kişi önce kendi güvenliğini düşünür, içeri dalmaz, kapıda durup amirine haber verir.","sektor":"Bilinçsiz müdahale tehlikeyi büyütebilir ve yaralıya zarar verebilir.","iliskili":["mg-3-108","mg-3-110","mg-3-116"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-3-110","konu":"3.5","terim":"Yardım zinciri","ingilizce":"Chain of help","tanim":"Olayın doğru kişilere ve kurumlara zamanında bildirilmesini sağlayan haber verme sürecidir.","ornek":"Resepsiyon, kazayı duyar duymaz önce 112’yi arar, sonra yönetici ve ilk yardımcıya haber verir.","sektor":"Yardım zinciri otelde olayı gören çalışandan başlar; 112’ye, bölüm amirine, ilk yardımcıya ve güvenliğe uzanır. Numara listesi eskimişse ya da kimse amire haber vermemişse zincir kopar, bu yüzden her bölümde güncel bir liste asılı olmalıdır.","iliskili":["mg-3-059","mg-3-109","mg-3-111"],"kontrol":null,"cizim":"otel-bina"},{"id":"mg-3-111","konu":"3.5","terim":"Acil durumda görev dağılımı ve ekip ruhu","ingilizce":"Task allocation and team spirit in emergencies","tanim":"Karışıklığı önlemek için görevlerin kişilerin bilgi, beceri ve sınırlarına göre açıkça paylaşılmasıdır.","ornek":"Alarm çalınca biri 112’yi arar, biri konukları merdivene yönlendirir, biri ilk yardım çantasını getirir; kimse aynı işi tekrarlamaz.","sektor":"Gece vardiyasında otelde az kişi çalıştığı için alarm anında kimin 112’yi arayacağı, kimin konukları yönlendireceği ve kimin ilk yardım çantasını getireceği vardiya başlamadan bilinmelidir. Herkes kendi görevini yapıp ötekinin işine karışmadığında kalabalık içinde bile düzen bozulmaz; ekip ruhu da budur.","iliskili":["mg-3-112","mg-3-110","mg-3-054"],"kontrol":null,"cizim":"doga"},{"id":"mg-3-112","konu":"3.5","terim":"Acil durum rolleri","ingilizce":"Emergency roles","tanim":"Haberci, güvenlik ve tahliye sorumlusu, ilk yardımcı, ekipman sorumlusu ve gözlemci gibi kriz anında paylaşılan görevlerdir.","ornek":"Okul atölyesindeki yangın canlandırmasında bir öğrenci 112’yi arayan haberci, bir öğrenci tahliyeyi yöneten güvenlik sorumlusu olur.","sektor":"Otel tatbikatında rolleri bölümlerin doğal işine göre dağıtmak mantıklıdır: ihbarı resepsiyon yapar, konukları çıkışa kat görevlileri yönlendirir, ilk yardımı eğitim almış çalışanlar üstlenir. Rolünü önceden bilen çalışan alarm anında kararsız kalmaz; rollerin tatbikatla denenmesinin amacı da zaman kazanmaktır.","iliskili":["mg-3-111","mg-3-054","mg-3-061"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-113","konu":"3.5","terim":"Ekipman yönetimi","ingilizce":"Equipment management","tanim":"Acil durumda araç gerecin nerede olduğunun, hangi olayda kullanılacağının, kullanılabilir olup olmadığının ve kimin kullanacağının önceden bilinmesidir.","ornek":"Otelin personel girişindeki panoda, tüplerin ve ilk yardım çantasının yeri ile kontrol tarihleri yazılıdır.","sektor":"Ekipman aramakla geçen süre müdahaleyi geciktirir.","iliskili":["mg-3-063","mg-3-066","mg-3-114"],"kontrol":null,"cizim":"ekip"},{"id":"mg-3-114","konu":"3.5","terim":"Acil durum iletişim ağı","ingilizce":"Emergency communication network","tanim":"Kriz anında bilginin kısa, açık ve doğru biçimde kimden kime iletileceğinin belirlenmesidir.","ornek":"Kat görevlisi amirine “Üçüncü kat, 312 numaralı odanın yanında duman var” der; amir resepsiyona, resepsiyon 112’ye haber verir.","sektor":"Eksik ya da yanlış bilgi yardımın gecikmesine neden olabilir.","iliskili":["mg-3-110","mg-3-113","mg-3-059"],"kontrol":null,"cizim":"uyari"},{"id":"mg-3-115","konu":"3.5","terim":"Güvenli müdahale akışı","ingilizce":"Safe emergency response sequence","tanim":"Acil durumda olayı fark etme, olay yeri güvenliğini değerlendirme, yardım zincirini başlatma, ilk yardımı eğitimli kişiye bırakma, tahliye ve kayıt-değerlendirme adımlarını sırayla izleyen akıştır.","ornek":"Atölyede kıvılcım çıkınca öğrenci önce kendi güvenliğine bakar, sonra öğretmene haber verir, 112 aranır, ilk yardımcı yaralıyla ilgilenir, herkes toplanma alanına çıkar.","sektor":"Her olayda aynı ayrıntılarla uygulanmayabilir; genel yaklaşımı gösterir.","iliskili":["mg-3-109","mg-3-110","mg-3-062"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-3-116","konu":"3.5","terim":"Bilinçsiz müdahale","ingilizce":"Untrained intervention","tanim":"Eğitimi ve yetkisi olmayan kişinin, acil durumda durumu yeterince değerlendirmeden yaptığı ve yaralıya ya da kendisine zarar verebilen müdahaledir.","ornek":"Yaralanan arkadaşını panikle yerinden kaldırıp sürükleyen öğrenci, omurgası zarar görmüş kişinin durumunu ağırlaştırabilir.","sektor":"İlk yardım eğitimi olmayan kişi ortam güvenliğini sağlar, 112’yi arar, kalabalığı uzaklaştırır ve ilk yardımcıya yardım eder.","iliskili":["mg-3-109","mg-3-060","mg-3-061"],"kontrol":null,"cizim":"tren"}],"sorular":[{"id":"mg-3-s01","tur":"coktan-secmeli","soru":"Havuz kenarındaki zemin ıslaktır ve çevrede koşuşturan çocuklar vardır. Bu durumda “risk” hangisidir?","secenekler":["Havuz kenarındaki ıslak zemin","Zeminin pürüzsüz taşla kaplı olması","Birinin kayıp yaralanma ihtimali","Zemin için konacak uyarı levhası"],"dogru":2,"aciklama":"Risk, tehlikenin gerçekten zarar verme ihtimalidir. Islak zemin tehlikenin kendisidir; levha ise riski azaltan bir önlemdir, risk değildir."},{"id":"mg-3-s02","tur":"coktan-secmeli","soru":"Kat görevlisi kaygan koridorda kayıp düşer ve bileğini burkar. Aynı kayma, görevli son anda tutunup düşmeseydi olay hangi adla anılırdı?","secenekler":["Ramak kala olay","İş kazası","Meslek hastalığı","Güvensiz davranış"],"dogru":0,"aciklama":"Ramak kala olayda zarar verme potansiyeli vardır ama kimse yaralanmaz. Bileğin burkulduğu hâl iş kazasıdır; ikisini ayıran şey sonuçtur. Güvensiz davranış ise olayın adı değil, nedenlerinden biridir."},{"id":"mg-3-s03","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi güvensiz durum değil, güvensiz davranıştır?","secenekler":["Koridorda kenarı kıvrılıp kalkmış bir halı","Kablosu soyulmuş bir elektrik süpürgesi","Önüne koli yığılmış bir acil çıkış kapısı","Eldiven takmadan kimyasal temizleyici kullanmak"],"dogru":3,"aciklama":"Güvensiz davranış çalışanın kurala uymayan hareketidir; eldivensiz çalışmak bunun örneğidir. Halı, kablo ve kapalı çıkış ise ortamdaki bozukluklardır, yani güvensiz durumdur."},{"id":"mg-3-s04","tur":"dogru-yanlis","soru":"Bulaşıkhanede ıslak zeminde kayıp bileğini burkan komi iş kazası geçirmiştir; yıllarca eldivensiz güçlü temizlik maddeleriyle çalışan görevlinin ellerinde gelişen geçmeyen cilt hastalığı ise meslek hastalığıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kaza ani bir olaydır; meslek hastalığı aynı etkene tekrar tekrar maruz kalınması sonucu zamanla ortaya çıkar. Bu iki örnek ayrımı doğru yansıtıyor."},{"id":"mg-3-s05","tur":"coktan-secmeli","soru":"Bir otelde şef gittikten sonra kimse denetlemese de herkes eldivenini takıyor, zemini kuru bırakıyor ve ocak vanalarını kontrol ediyor. Bu durum en çok hangi kavramla açıklanır?","secenekler":["Risk değerlendirmesi","Güvenlik kültürü","Sağlık gözetimi","İSG denetimi"],"dogru":1,"aciklama":"Güvenlik kültüründe güvenli davranış, başında denetleyen biri olmasa da alışkanlık ve ortak değerdir. İSG denetimi ise dışarıdan yapılan kontroldür; burada kontrol eden kimse yoktur."},{"id":"mg-3-s06","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi fiziksel risk etkenine örnektir?","secenekler":["Dezenfektan buharının solunması","Kirli çarşaftaki bakterilerin bulaşması","Çalışan makinelerin sürekli yüksek sesi","Vardiyaların düzensiz ve uzun olması"],"dogru":2,"aciklama":"Gürültü; titreşim, sıcak, soğuk ve aydınlatma gibi ortamın fiziksel koşullarındandır. Buhar kimyasal, bakteri biyolojik, düzensiz vardiya ise psikososyal risk etkenidir."},{"id":"mg-3-s07","tur":"coktan-secmeli","soru":"Sezonun en yoğun haftasında resepsiyonda eksik kişiyle çalışılıyor, vardiyalar uzuyor ve görevliye kimse destek olmuyor. Bu durum hangi risk grubuna girer?","secenekler":["Psikososyal riskler","Ergonomik riskler","Fiziksel risk etkenleri","Kimyasal risk etkenleri"],"dogru":0,"aciklama":"İşin düzenlenme biçiminden ve iş yerindeki ilişkilerden doğan etkenler psikososyal risktir. Ergonomik risk ise araç ve ortamın bedene uymamasıyla ilgilidir; burada sorun beden ölçüsü değil iş yükü ve destek eksikliğidir."},{"id":"mg-3-s08","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi mobbing sayılır?","secenekler":["Şefin, işe geç kalan bir personeli odasına çağırıp bir kez uyarması","İki çalışanın vardiya değişimi yüzünden bir gün tartışması","Yoğun bir bayram haftasında bütün ekibin fazla çalışması","Bir çalışanın aylarca sistemli biçimde dışlanıp küçümsenmesi"],"dogru":3,"aciklama":"Mobbing sistemli ve sürekli yıldırmadır. Tek seferlik uyarı, bir günlük tartışma ve herkesi eşit etkileyen yoğunluk bu tanıma girmez; hedef alınan tek kişi ve süreklilik yoktur."},{"id":"mg-3-s09","tur":"coktan-secmeli","soru":"Bir kat görevlisinin sırtı ağrıyor; nedeni kendi boyuna göre çok kısa saplı bir paspas kullanması. Sorunu ergonomi ilkesine göre hangisi çözer?","secenekler":["Görevlinin temizliği daha hızlı yapması","Paspası görevlinin boyuna uygun saplı olanla değiştirmek","Görevliden temizlik süresini yarım saat kısaltmasını istemek","Görevlinin bel ağrısı için yılda bir muayene edilmesi"],"dogru":1,"aciklama":"Ergonomi, işin ve aracın insan bedenine uydurulmasıdır; çözüm paspası görevliye uydurmaktır. Muayene sağlık gözetimidir, ağrının nedenini ortadan kaldırmaz."},{"id":"mg-3-s10","tur":"dogru-yanlis","soru":"6331 sayılı Kanun yalnızca işverene görev yükler; çalışanın uyması gereken bir İSG yükümlülüğü yoktur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kanun hem işverenlerin hem çalışanların görev ve yükümlülüklerini düzenler. Çalışan, aldığı eğitime ve talimatlara uymak, kendisini ve başkalarını tehlikeye atmamakla yükümlüdür."},{"id":"mg-3-s11","tur":"coktan-secmeli","soru":"Bir otel, kat görevlilerine kimyasala dayanıklı eldiven ve iş ayakkabısı veriyor, İSG eğitimi düzenliyor. Bu uygulamanın bedeli konusunda hangisi doğrudur?","secenekler":["Bedelin yarısı çalışanın maaşından kesilir","Bedeli, kullanan çalışan olduğu için kendisi öder","Bedel çalışana yansıtılmaz, işveren karşılar","Bedeli otelin iş güvenliği uzmanı kendisi öder"],"dogru":2,"aciklama":"Koruyucu araç gereç ve eğitim işverenin yükümlülüğüdür; çalışandan para alınmaz. Uzman tehlikeleri belirleyen teknik elemandır, masrafı üstlenen kişi değildir."},{"id":"mg-3-s12","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi işverenin değil, çalışanın İSG yükümlülüğüdür?","secenekler":["Dilimleme makinesini eğitim almadan kullanmamak","Risk değerlendirmesi yaptırmak","Kat görevlisine eldiven ve iş ayakkabısı sağlamak","Yeni gelenlere İSG eğitimi verdirmek"],"dogru":0,"aciklama":"Eğitime ve talimata uymak çalışanın görevidir. Risk değerlendirmesi, donanım sağlama ve eğitim vermek ise işverene aittir."},{"id":"mg-3-s13","tur":"coktan-secmeli","soru":"Aşağıdaki görevlerden hangisi iş yeri hekiminin işidir?","secenekler":["Mutfakta davlumbaz filtrelerini ve tüp yerlerini gezip eksikleri yönetime yazmak","Havuz başında fenalaşan konuğa ilk yardım uygulamak","Tatbikatta toplanma alanında sayım yapmak","Çalışanların işe giriş ve periyodik muayenelerini yapmak"],"dogru":3,"aciklama":"İş yeri hekimi çalışanların sağlığını izler ve muayenelerini yapar. İlk şık iş güvenliği uzmanının, ikincisi ilk yardımcının, üçüncüsü acil durum ekibinin işidir."},{"id":"mg-3-s14","tur":"coktan-secmeli","soru":"Lobide bir kâğıt kesiği ile fritözde kızgın yağ sıçraması karşılaştırılıyor. Önce hangisine önlem alınır?","secenekler":["Kâğıt kesiğine; çünkü daha sık yaşanır","Kızgın yağa; çünkü hem olabilir hem ağır yanık bırakır","İkisine de aynı sırayla; risk yalnız olasılığa bağlıdır","Fark etmez; riskler tehlikenin türüne göre sıralanır"],"dogru":1,"aciklama":"Risk büyüklüğü olasılık ve sonuca birlikte bakılarak belirlenir. Kâğıt kesiği olası ama hafiftir; kızgın yağda ise sonuç ağırdır, önce oraya önlem alınır."},{"id":"mg-3-s15","tur":"coktan-secmeli","soru":"Güçlü bir temizlik kimyasalı için kontrol hiyerarşisine göre ilk sorulması gereken soru hangisidir?","secenekler":["Bu kimyasalı hiç kullanmasak olur mu?","Çalışanlara kimyasala uygun eldiven verildi mi?","Odada yeterli havalandırma var mı?","Kullanım talimatı ve eğitimi var mı?"],"dogru":0,"aciklama":"Hiyerarşi en etkili önlemden başlar: önce tehlike ortadan kaldırılmaya çalışılır. Havalandırma teknik önlem, talimat ve eğitim idari önlem, eldiven ise en son basamak olan koruyucu donanımdır."},{"id":"mg-3-s16","tur":"dogru-yanlis","soru":"Kişisel koruyucu donanım, kontrol hiyerarşisinin en son basamağıdır; çünkü önce tehlikenin kendisi ortadan kaldırılmaya ya da azaltılmaya çalışılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Eldiven ve maske tehlikeyi yok etmez, yalnızca çalışanla tehlike arasına girer. Bu yüzden en etkili önlemler tehlikeyi kaynağında ortadan kaldıranlardır."},{"id":"mg-3-s17","tur":"coktan-secmeli","soru":"Kimyasal hazırlama odasının girişine “Gözlük kullan” levhası asılacak. Levha hangi biçim ve renkte olmalıdır?","secenekler":["Üçgen biçiminde, sarı zeminli, siyah resimli","Daire biçiminde, beyaz zeminli, kırmızı çerçeveli","Daire biçiminde, mavi zeminli, beyaz resimli","Dikdörtgen biçiminde, yeşil zeminli, beyaz resimli"],"dogru":2,"aciklama":"Zorunlu bir davranışı bildiren emredici işaret mavi zeminli, daire biçimli ve beyaz resimlidir. Sarı üçgen uyarır, kırmızı çerçeveli daire yasaklar, yeşil dikdörtgen çıkış ve ilk yardımı gösterir."},{"id":"mg-3-s18","tur":"coktan-secmeli","soru":"Kimyasal deposunun kapısındaki “Aşındırıcı madde” levhası hangi türdendir ve ne anlatır?","secenekler":["Yasaklayıcı işaret; maddeye dokunmak yasaktır","Emredici işaret; maddenin yanında eldiven giymek zorunludur","Yangınla mücadele işareti; madde yanıcıdır, yakında tüp vardır","Uyarı işareti; bu maddeye karşı dikkatli olunmalıdır"],"dogru":3,"aciklama":"Sarı üçgen uyarı işaretidir: orada bir tehlike olduğunu bildirir, bir şeyi yasaklamaz ya da zorunlu kılmaz. Eldiven zorunluluğunu mavi daire levha bildirir."},{"id":"mg-3-s19","tur":"coktan-secmeli","soru":"Güvenlik işaretlerindeki renk–anlam eşleşmelerinden hangisi yanlıştır?","secenekler":["Kırmızı – yasak, tehlike alarmı ve yangınla mücadele donanımı","Yeşil – uyulması zorunlu davranış","Sarı – uyarı","Mavi – zorunluluk"],"dogru":1,"aciklama":"Zorunlu davranışın rengi mavidir. Yeşil güvenli durumu gösterir: acil çıkış, ilk yardım ve güvenli bölge."},{"id":"mg-3-s20","tur":"dogru-yanlis","soru":"Yangın alarmında koridorda toplanan konuklar asansör kuyruğuna girerse kat görevlisi onlara katılmaz, ama kuyruk kısaysa asansörün kullanılmasına izin verir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Tahliyede asansör kullanılmaz; asansör elektrik kesilince ya da duman dolunca mahsur kalma tehlikesi taşır. Görevli konukları merdivene yönlendirir."},{"id":"mg-3-s21","tur":"coktan-secmeli","soru":"Tahliye tamamlandı ve ekip toplanma alanına geldi. Bölüm şefinin ilk yapacağı iş hangisidir?","secenekler":["Ekibini sayıp eksik olan var mı kontrol etmek","Ekibini kontrol için hemen odalara geri göndermek","Yangın tüplerinin yeniden doldurulmasını istemek","Konuklara yeni oda numaraları dağıtmak"],"dogru":0,"aciklama":"Toplanma alanının amacı sayım yapmaktır; eksik biri varsa kurtarma ekibine hemen bildirilir. Binaya geri dönmek tahliyeyi boşa çıkarır ve kişiyi tehlikeye atar."},{"id":"mg-3-s22","tur":"coktan-secmeli","soru":"Tavadaki yağ alev aldı. Aşçı ocağı kapatıp tavanın üstünü kapakla örtüyor. Bu iki hareket yangın üçgeninin hangi kenarlarını ortadan kaldırır?","secenekler":["Ocak oksijeni, kapak ısıyı keser","Ocak yanıcı maddeyi, kapak ısıyı keser","Ocak ısıyı, kapak oksijeni keser","Ocak yanıcı maddeyi, kapak oksijeni keser"],"dogru":2,"aciklama":"Ocağı kapatmak ısı kaynağını keser, kapak havayı yani oksijeni keser. Yanıcı madde olan yağ tavada kalmaya devam eder; üçgenin bir kenarı yok olunca yangın söner."},{"id":"mg-3-s23","tur":"coktan-secmeli","soru":"Mutfakta tavadaki kızgın yağ alev aldı. Aşağıdakilerden hangisi yapılması yanlış olan harekettir?","secenekler":["Ocağın altını kapatmak","Tavanın üstünü kapakla örtmek","Üzerine yangın battaniyesi örtmek","Üzerine su dökmek"],"dogru":3,"aciklama":"Su kızgın yağı sıçratır ve alevi büyütür. Diğer üçü ısıyı ya da havayı keserek yangını güvenle söndürür."},{"id":"mg-3-s24","tur":"coktan-secmeli","soru":"Çamaşırhanede bir görevli yerde hareketsiz yatıyor ve yanında kopuk bir elektrik kablosu duruyor. İlk adım hangisidir?","secenekler":["Görevliyi hemen kolundan çekip kablodan uzaklaştırmak","Elektriği şalterden kestirip ortamı güvenli hâle getirmek","Görevlinin ayılması için ağzına su vermek","Eğitimin olmasa da hemen kalp masajına başlamak"],"dogru":1,"aciklama":"İlk yardımın sırası koruma, bildirme, kurtarmadır. Önce olay yeri güvenli olmalı; kabloya dokunan kurtarıcı da çarpılabilir. Şalter kapatılıp 112 aranır, müdahaleyi eğitimli kişi yapar."},{"id":"mg-3-s25","tur":"senaryo","durum":"Kat hizmetlerinde stajdasın. Saat 10.20, ikinci kat koridorunda bir konuğun döktüğü su zemini kaygan yapmış. Ortada levha yok, asansörden yeni konuklar çıkıyor.","soru":"İlk adımın ne olur?","secenekler":["Başında durup gelenleri uyarır, levha ve paspas istetirim.","Kat ofisine gidip paspas arar, bulunca dönüp silerim.","Burası benim alanım olmadığı için işime devam ederim.","Kat şefini bulana kadar katları dolaşıp durumu anlatırım."],"dogru":0,"aciklama":"Dökülen sıvı kontrol altına alınmazsa birinin düşme riski sürer. Yerinden ayrılmak ya da görmezden gelmek güvensiz durumu olduğu gibi bırakır; önce uyarı, sonra levha ve silme gelir."},{"id":"mg-3-s26","tur":"senaryo","durum":"Banyo temizliğindesin. Saat 11.00, küvetteki kireç lekesi çıkmıyor. Yanındaki görevli “Çamaşır suyuna biraz tuz ruhu kat, hemen çıkar” diyerek şişeyi uzatıyor.","soru":"Ne yaparsın?","secenekler":["Az miktarda karıştırır, pencereyi açarak çalışırım.","Karıştırırım ama maske takıp işi hızlıca bitiririm.","Karıştırmam; etikete uyar, çözümü şefime sorarım.","Karışımı arkadaşıma hazırlatır, ben dışarıda beklerim."],"dogru":2,"aciklama":"Çamaşır suyu ile tuz ruhu karışınca zehirli klor gazı çıkar; az miktar, havalandırma ya da maske bunu güvenli yapmaz. Doğrusu kimyasalı karıştırmamak, etikete uymak ve şefe sormaktır."},{"id":"mg-3-s27","tur":"senaryo","durum":"Depoda staj yapıyorsun. Saat 08.40, şef restorana hemen bir koli içecek götürmeni istiyor. Koli tek başına kaldıramayacağın kadar ağır; taşıma arabası deponun öbür ucunda.","soru":"Nasıl davranırsın?","secenekler":["Vakit kaybetmemek için belimi eğip koliyi kucaklarım.","Koliyi yerde sürükleyerek restorana kadar götürürüm.","Koliyi açıp şişeleri kucağımda birkaç seferde taşırım.","Taşıma arabasını getirir ya da yardım isterim."],"dogru":3,"aciklama":"Ağır yükü tek başına kaldırmak bel ve omurgaya zarar verir. Elle taşıma işinde araç ya da yardım kullanılır; zaman kazanmak için bedeni riske atmak doğru değildir."},{"id":"mg-3-s28","tur":"senaryo","durum":"Mutfakta stajdasın. Saat 12.15, yanındaki stajyer soğan doğrarken parmağını derin biçimde kesiyor; kan durmuyor ve yüzü sararıyor. İlk yardım eğitimin yok, şef iki tezgâh ötede.","soru":"İlk adımın ne olur?","secenekler":["Evde duyduğum bir yöntemi yaranın üstüne uygularım.","Şefe seslenir, ilk yardımcının çağrılmasını sağlarım.","Servis yoğun olduğu için çalışmaya devam etmesini söylerim.","Onu tek başına personel odasına dinlenmeye gönderirim."],"dogru":1,"aciklama":"Eğitimsiz müdahale yaralıya zarar verebilir. Yardım zincirini başlatmak, yani şefe haber verip ilk yardımcıyı çağırtmak ilk adımdır. Yaralıyı yalnız göndermek ise onu denetimsiz bırakır."},{"id":"mg-3-s29","tur":"senaryo","durum":"Öğleden sonra 15.30, dördüncü katta oda hazırlıyorsun. Yangın alarmı çalmaya başlıyor. Koridora çıkan birkaç konuk telaşla asansör düğmesine basıyor.","soru":"Ne yaparsın?","secenekler":["Sakin sesle konuklara merdiveni gösterir, birlikte aşağı ineriz.","Asansör gelince konukların hızla binmesine yardım ederim.","Alarmın gerçek olup olmadığı anlaşılana kadar beklerim.","Önce arabamı ve malzemelerimi toplayıp odayı kilitlerim."],"dogru":0,"aciklama":"Tahliyede asansör kullanılmaz ve eşya için oyalanılmaz. Personelin sakin sesi ve net cümleleri konuklardaki paniği azaltır; alarm gerçek kabul edilip hemen merdivene yönlendirilir."},{"id":"mg-3-s30","tur":"senaryo","durum":"Kat hizmetlerinde çalışıyorsun. Saat 13.10, elektrik süpürgesinin kablosunda bir yerin soyulduğunu ve içindeki tellerin göründüğünü fark ediyorsun. Bitirmen gereken üç oda daha var, kat şefi başka katta.","soru":"Hangisi doğru davranıştır?","secenekler":["Soyulan yere dikkat ederek üç odayı da bitiririm.","Soyulan yeri bantla sarıp süpürmeye devam ederim.","Fişini çeker, şefime bildirir, süpürgeyi kullanmam.","Süpürgeyi başka bir görevlinin arabasına bırakırım."],"dogru":2,"aciklama":"Hasarlı kablo çarpılma ve yangın riski taşır; onarım yalnız yetkili kişilerce yapılır. Bantlamak geçici çözümdür, başkasına bırakmak ise riski ona devreder. Kullanmayıp bildirmek doğrudur."},{"id":"mg-3-s31","tur":"senaryo","durum":"Akşam servisinde, saat 20.45, bulaşıkhane girişinde ayağın kayıyor; tezgâha tutunup düşmekten kurtuluyorsun. Elindeki tabaklar sağlam, kimse görmedi. Zemin o noktada hep ıslak oluyor.","soru":"Ne yaparsın?","secenekler":["Bir şey olmadığı için kimseye söylemeden işime dönerim.","Bundan sonra o noktadan geçerken ben dikkat ederim.","Mesai bitince bulaşıkçı arkadaşıma zemini iyi silmesini söylerim.","Olanı şefime anlatır, zemin için önlem isterim."],"dogru":3,"aciklama":"Bu bir ramak kala olaydır; bu sefer kimse yaralanmadı ama sonraki sefer yaralanabilir. Bildirilirse kök neden bulunup giderilebilir. Kişisel dikkat ya da sözlü uyarı sorunu çözmez."},{"id":"mg-3-s32","tur":"senaryo","durum":"Kahvaltı hazırlığı için sabah 06.15’te mutfağa ilk giren sensin. Kapıyı açar açmaz keskin bir gaz kokusu alıyorsun. İçerisi karanlık, kimse yok.","soru":"İlk adımın ne olur?","secenekler":["Işığı açıp kokunun hangi ocaktan geldiğine bakarım.","Işığa dokunmadan uzaklaşır, şefime haber veririm.","Kokuyu dağıtmak için davlumbazı ve havalandırmayı açarım.","Bir ocağı yakıp gazın gelip gelmediğine bakarım."],"dogru":1,"aciklama":"Gaz kokusunda elektrik düğmesi, ocak ya da davlumbaz gibi kıvılcım çıkarabilecek hiçbir şeye dokunulmaz. Uzaklaşıp yetkililere haber vermek hem kendini hem başkalarını korur."},{"id":"mg-3-s33","tur":"coktan-secmeli","soru":"Kat hizmetlerinde stajdasın. Saat 09.30, banyodaki kireci çözmek için kimyasal bir temizleyiciyi bidondan kovaya aktaracaksın; dökerken sıçrayabilir. Gözlerini korumak için ne yaparsın?","secenekler":["Yanları kapalı koruyucu gözlüğümü takar, sonra aktarırım.","Yanımdaki güneş gözlüğünü takarım, göz için o da yeterlidir.","Başımı yana çevirip yavaşça dökerim, böylece hiç sıçramaz.","Solunum maskemi takarım, o da yüzümü tümüyle korur."],"dogru":0,"aciklama":"Kimyasal bir kaptan ötekine aktarılırken sıçrama ihtimali en yüksektir. Yanları kapalı koruyucu gözlük sıçramayı tutar; sıradan gözlük, başı çevirmek ya da solunum maskesi gözü yeterince korumaz."},{"id":"mg-3-s34","tur":"coktan-secmeli","soru":"Teknik servisteki bir çalışandan, korkuluğu olmayan yüksek bir yere güvenlik donanımı olmadan çıkması isteniyor. Çalışmaktan kaçınma hakkını doğru kullanmak için önce ne yapmalıdır?","secenekler":["Hiçbir şey söylemeden işi bırakıp eve gitmeli","Durumu bildirip önlem alınmasını istemeli","Bir ip bulup işi kendi önlemiyle yapmalı","İşi yapıp tehlikeyi sonradan amirine anlatmalı"],"dogru":1,"aciklama":"Bu hak keyfî bir “yapmam” değildir: ciddi ve yakın tehlike önce işverene ya da İSG kuruluna bildirilir, önlem istenir. Sessizce işi bırakmak da tehlikeyi göze alıp işi yapmak da hakkın doğru kullanımı değildir."},{"id":"mg-3-s35","tur":"dogru-yanlis","soru":"Serviste elini hafifçe kesen stajyer, yara küçük olduğu için olayı şefine söylemek zorunda değildir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kaza ne kadar küçük görünürse görünsün amire bildirilir ve kayda geçer. Kayıt çalışanın haklarını korur ve aynı kazanın tekrarını önleyecek önlemin alınmasını sağlar."},{"id":"mg-3-s36","tur":"coktan-secmeli","soru":"Kat görevlisi yangın merdiveni kapısının önüne çamaşır torbalarını “iki dakikalığına” bırakmış. Bunu gören stajyer ne yapmalıdır?","secenekler":["Torbaları kaldırır ya da hemen amirine bildirir","İki dakika sonra kaldırılacağı için bir şey yapmaz","Torbalar çalınmasın diye kapıyı kilitler","Durumu ay sonundaki toplantıda dile getirir"],"dogru":0,"aciklama":"Acil çıkışın önüne kısa süreliğine bile bir şey bırakılmaz ve kapı kilitlenmez. Önü kapalı çıkışı gören kişi engeli kaldırır ya da hemen amirine bildirir; beklemek tehlikeyi sürdürür."},{"id":"mg-3-s37","tur":"coktan-secmeli","soru":"Öğrenci denetçi mutfak gözleminde yangın söndürücünün önüne koli konduğunu görüyor. Gözlem derecelendirme ölçeğinde bu satıra ne yazar?","secenekler":["“Uygun” işaretler, açıklamayı boş bırakır","“Kısmen uygun” işaretler, açıklamaya bir şey yazmaz","“Uygun değil” işaretler, kolileri açıklamaya yazar","Ölçeğe yazmaz, durumu yalnız arkadaşına söyler"],"dogru":2,"aciklama":"Tüpe ulaşılamıyorsa ölçüt karşılanmamıştır, satır “uygun değil” işaretlenir ve nedeni açıklamaya yazılır. Ölçeğin yararı izlenimi kayda çevirmesidir; açıklamasız işaret amire götürülecek somut işi göstermez."},{"id":"mg-3-s38","tur":"coktan-secmeli","soru":"Kat hizmetleri gözleminde bir görevlinin belden eğilerek yük kaldırdığı görüldü. Gözlem verileri sınıflandırılırken bu durum hangi risk türüne yazılır?","secenekler":["Kimyasal risk","Biyolojik risk","Psikososyal risk","Ergonomik risk"],"dogru":3,"aciklama":"Yanlış duruşla yük kaldırmak bedenin sınırlarını zorlar; bu yüzden ergonomik riske yazılır. Etiketsiz temizlik maddesi gibi bir gözlem ise kimyasal riske girerdi."},{"id":"mg-3-s39","tur":"dogru-yanlis","soru":"Havuz başındaki kaygan zemine kaymaz kaplama yapıldıysa ayrıca uyarı levhası koymak gereksizdir; tek bir güçlü tedbir yeterlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Tek bir tedbire güvenilmez. Birkaç tedbir üst üste konunca biri aksasa bile kaza çoğu zaman önlenir; kaplama ile levha birlikte bu katmanlı düzeni oluşturur."},{"id":"mg-3-s40","tur":"coktan-secmeli","soru":"Yetkili bir görevli otel mutfağında yangın tüplerine, uyarı işaretlerine ve çalışanların eldiven kullanımına bakıyor. Bu İSG denetiminin asıl amacı hangisidir?","secenekler":["Kazayı olmadan önlemek için eksikleri ortaya çıkarmak","Kaza olduktan sonra kusurlu çalışanı belirleyip cezalandırmak","Mutfakta pişen yemeklerin lezzetini değerlendirmek","Çalışanların işe giriş sağlık muayenelerini yapmak"],"dogru":0,"aciklama":"Denetimde eksikler tespit edilir ve işverenden bunları gidermesi istenir; amaç kazayı olmadan önlemektir. Muayene ise iş yeri hekiminin yürüttüğü sağlık gözetiminin konusudur."},{"id":"mg-3-s41","tur":"coktan-secmeli","soru":"Çamaşırhanede makineler çok gürültülü çalışıyor. Önlem sırasına göre ilk düşünülmesi gereken hangisidir?","secenekler":["Görevlilere kulak koruyucu dağıtmak","Makinelerin bakımını ve ses yalıtımını yapmak","Görevlilerin birbirine bağırarak konuşmasını sağlamak","Gürültülü bölümde kalınan süreyi kısaltmak"],"dogru":1,"aciklama":"Gürültüde önlem sırası makinenin bakımı ve ses yalıtımıyla başlar, sonra kalınan süre kısaltılır, en son gerekiyorsa kulak koruyucu kullanılır. Koruyucu dağıtmak gürültünün kaynağını değiştirmez."},{"id":"mg-3-s42","tur":"dogru-yanlis","soru":"Uzun süren iş stresinin çözümü yalnız çalışanın daha çok dayanmasıdır; iş yükü ve vardiya düzeninin bunda payı yoktur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İş stresi, işin istekleri çalışanın gücünü ve zamanını aştığında doğar. Bu yüzden çözüm yalnız kişinin dayanması değildir; iş yükü ve vardiya düzeni de gözden geçirilir."},{"id":"mg-3-s43","tur":"coktan-secmeli","soru":"Kontrol altına alınmayan bir risk etkeninin sağlık sorununa dönüşme sırası hangisinde doğru verilmiştir?","secenekler":["Maruziyet → risk etkeni → sağlık sorunu","Risk etkeni → maruziyet → sağlık sorunu","Sağlık sorunu → risk etkeni → maruziyet","Risk etkeni → sağlık sorunu → maruziyet"],"dogru":1,"aciklama":"Önce ortamda bir risk etkeni vardır, çalışan onunla temas edince maruziyet başlar, kontrol edilmezse sağlık sorunu ortaya çıkar. Maruziyet, etken olmadan başlayamaz."},{"id":"mg-3-s44","tur":"dogru-yanlis","soru":"Yaz sezonunda öğle saatlerinde plajda çalışan cankurtaranın maruz kaldığı güneşin zararlı ışınları, fiziksel risk etkenleri arasında sayılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Güneşin zararlı ışınları radyasyondur ve radyasyon gürültü, titreşim, aşırı sıcak gibi fiziksel risk etkenleri arasında yer alır. Şapka, gözlük ve gölgelik bu etkiyi azaltır."},{"id":"mg-3-s45","tur":"coktan-secmeli","soru":"Çamaşırhaneye güçlü bir havalandırma sistemi kurulması, görevlilere tek tek maske verilmesine göre hangi üstünlüğü taşır?","secenekler":["Herkesi aynı anda, dikkate bağlı olmadan korur","Kurulduktan sonra hiç bakım ve kontrol gerektirmez","Yalnız onu kullanmayı bilen kişiyi korur","Tehlikeyi kaynağıyla birlikte tamamen yok eder"],"dogru":0,"aciklama":"Ortamda alınan önlem bir kez kurulunca vardiya değişse de o bölümdeki herkesi aynı anda korur ve kişinin hatırlamasına bağlı kalmaz. Tehlikeyi tamamen yok etmez; tehlike yok edilemediği için ortama yayılmasını engeller."},{"id":"mg-3-s46","tur":"coktan-secmeli","soru":"“Komi bulaşıkhanede düştü” sorunu için balık kılçığı diyagramı hazırlanıyor. “Zayıf ışık” hangi başlığın altına yazılır?","secenekler":["İnsan","Yöntem","Çevre","Yönetim"],"dogru":2,"aciklama":"Islak zemin ve zayıf ışık çalışma ortamına ait koşullardır, bu yüzden çevre dalına yazılır. Acele etmek insan, levha koyma alışkanlığının olmaması ise yöntem dalına girer."},{"id":"mg-3-s47","tur":"coktan-secmeli","soru":"Komi bulaşıkhanede kayıp düşüyor. Zemin ıslaktır, çünkü hortum günlerdir sızdırdığı hâlde bakım yapılmamıştır. Bu olayda kök neden hangisidir?","secenekler":["Kominin kayıp düşmesi","Zeminin ıslak olması","Sızdıran hortuma bakım yapılmaması","Kominin o sırada dikkatsiz ve aceleci olması"],"dogru":2,"aciklama":"Düşme olayın kendisi, ıslak zemin doğrudan nedenidir; giderilmezse kazayı tekrarlatacak asıl neden bakımı yapılmayan hortumdur. Olayı “dikkatsizlik” deyip geçmek kök nedeni gizler."},{"id":"mg-3-s48","tur":"coktan-secmeli","soru":"Oda yenilemesinde çözücü bazlı boya yerine su bazlı boya seçiliyor. Bu karar kontrol hiyerarşisinin hangi basamağına örnektir?","secenekler":["Tehlikeyi ortadan kaldırma","Daha az tehlikeli olanla değiştirme","Kişisel koruyucu donanım kullanma","Toplu korunma ve mühendislik önlemi"],"dogru":1,"aciklama":"Boya işi yine yapılır, ama daha az zararlı buhar çıkaran bir boya kullanılır; bu değiştirme basamağıdır. Tehlikeyi ortadan kaldırmada ise tehlike hiç oluşmaz."},{"id":"mg-3-s49","tur":"coktan-secmeli","soru":"Kat görevlileri sık kullandıkları temizlik malzemesine ulaşmak için depoda yüksek rafa merdivenle çıkıyor. Tehlikeyi tamamen ortadan kaldıran çözüm hangisidir?","secenekler":["Merdivene çıkılırken birinin merdiveni tutması","Görevlilere kaymaz tabanlı iş ayakkabısı vermek","Rafa “Dikkat, yüksek” levhası asmak","Malzemeyi bel hizasındaki bir rafa taşımak"],"dogru":3,"aciklama":"Malzeme bel hizasına alınınca merdivene çıkma ihtiyacı kalmaz; tehlike azaltılmaz, hiç oluşmaz. Merdiveni tutmak, ayakkabı ve levha ise tehlike dururken etkisini azaltmaya çalışır."},{"id":"mg-3-s50","tur":"dogru-yanlis","soru":"Delinmiş koruyucu eldiven atılır ve yenisi istenir; çünkü delik eldiven içine kimyasal alır ve onu cilde daha uzun süre temas ettirir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Delinmiş eldiven korumaz, hatta içine giren kimyasalı cilde hapseder. Bu yüzden kullanılmaz; atılır ve yenisi istenir."},{"id":"mg-3-s51","tur":"coktan-secmeli","soru":"Teknik servis görevlisi, kimyasal buharın yoğun olduğu bir depoda toz maskesiyle çalışmak istiyor. Bu konuda hangisi doğrudur?","secenekler":["Her maske her şeye karşı korur, toz maskesi yeterlidir","Kısa işte toz maskesi buharı da tutar","Maskenin yüze oturması önemsizdir, takılması yeterlidir","Toz maskesi buharı tutmaz; işe uygun maske seçilir"],"dogru":3,"aciklama":"Her maske her şeye karşı korumaz; toz maskesi kimyasal buharı tutmaz. Hangi işte hangi maskenin gerektiğini iş güvenliği uzmanı ve kimyasalın etiketi söyler, maske de yüze tam oturmalıdır."},{"id":"mg-3-s52","tur":"coktan-secmeli","soru":"Otelin çamaşırhanesine yeni bir kurutma makinesi alındı. Risk değerlendirmesi konusunda hangisi doğrudur?","secenekler":["Bir kez yapıldığı için yenilenmesine gerek yoktur","Yalnız yönetim yapar, çalışana sorulmaz","Makine değiştiği için değerlendirme yenilenir","Yaptırmak makineyi kullanan çalışanın yükümlülüğüdür"],"dogru":2,"aciklama":"Risk değerlendirmesi bir kez yapılıp rafa kaldırılmaz; iş, makine ya da ortam değişince yenilenir. Yaptırmak işverenin yükümlülüğüdür ve işi yapan çalışanların görüşü de alınır."},{"id":"mg-3-s53","tur":"coktan-secmeli","soru":"Mutfaktaki dilimleme makinesi temizlenecek. Temizliğe başlamadan önce ilk yapılacak iş hangisidir?","secenekler":["Makineyi kapatıp fişini çekmek","Siperi söküp kenara koymak","Bıçağı makine çalışırken bezle silmek","Makineyi en düşük hızda çalıştırmak"],"dogru":0,"aciklama":"Makine temizlenmeden önce kapatılır ve fişi çekilir; böylece bıçak yanlışlıkla dönemez. Koruyucu siper ise hiçbir gerekçeyle devre dışı bırakılmaz."},{"id":"mg-3-s54","tur":"dogru-yanlis","soru":"Teras barında gevşemiş bir korkuluk fark edildiğinde teknik servise bildirilir ve korkuluk onarılana kadar o bölüm kapatılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Gevşemiş ya da paslanmış korkuluk “nasılsa dayanır” denip geçilmez. Bildirmek ve onarılana kadar bölümü kapatmak, çalışanı da konukları da düşmeye karşı korur."},{"id":"mg-3-s55","tur":"coktan-secmeli","soru":"Büroda çöp kovası tutuştu ve eğitim almış bir görevli yangın söndürme tüpünü aldı. Tüpün doğru kullanım sırası hangisidir?","secenekler":["Tetiğe bas, pimi çek, alevin tepesine tut, bekle","Alevin tepesine nişan al, pimi çek, tetiğe bas, süpür","Pimi çek, alevin dibine nişan al, tetiğe bas, süpür","Pimi çek, tetiğe bas, alevin tepesine tut, süpür"],"dogru":2,"aciklama":"Tüp kullanılırken önce pim çekilir, hortum alevin dibine tutulur, tetiğe basılır ve sağa sola süpürülür. Alevin tepesine sıkmak yanan maddeye ulaşmadığı için yangını söndürmez."},{"id":"mg-3-s56","tur":"coktan-secmeli","soru":"Çamaşırhanede elektrikli bir cihaz alev aldı. Koridordaki yangın dolabının hortumu bu yangında neden kullanılmaz?","secenekler":["Hortum su püskürtür; elektrikli cihazda su kullanılmaz","Hortum yalnız C sınıfı gaz yangınları için üretilmiştir","Dolabın içinde temizlik malzemesi saklandığı için","Hortumun suyu yalnız dış alandaki yangına yetişir"],"dogru":0,"aciklama":"Yangın dolabının hortumu su tesisatına bağlıdır ve elektrikli cihaz yangınında su kullanılmaz; önce elektrik kesilir. Dolaba temizlik malzemesi konmaması ayrı bir kuraldır, hortumun bu yangında kullanılmama nedeni değildir."},{"id":"mg-3-s57","tur":"coktan-secmeli","soru":"Restoranda servis sırasında deprem sarsıntısı başladı. Sarsıntı sürerken garson için doğru davranış hangisidir?","secenekler":["Konuklardan önce asansöre binip zemin kata inmek","Balkona çıkıp açık havaya ulaşmak","Konukları merdivene doğru koşturmak","Camdan uzak, sağlam bir masanın yanına çökmek"],"dogru":3,"aciklama":"Sarsıntı sürerken cam ve asılı eşyadan uzaklaşılır, sağlam bir eşyanın yanına çökülür, baş ve ense korunarak tutunulur. Koşmak, merdivene, asansöre ya da balkona yönelmek yaralanmaların başlıca nedenidir."},{"id":"mg-3-s58","tur":"coktan-secmeli","soru":"Mutfakta bir çalışan bayıldı ve şef 112’yi aradı. Bu görüşmede telefon ne zaman kapatılır?","secenekler":["Adresi söyledikten hemen sonra","Ambulansın siren sesi uzaktan duyulunca","Bir dakika konuşulunca","Görevli “Kapatabilirsiniz” deyince"],"dogru":3,"aciklama":"112 görüşmesinde telefon, görevli kapatılabileceğini söyleyene kadar açık tutulur. Yalnız adresi verip kapatmak; olay türü, yaralı sayısı ve arayanın bilgisi gibi gereken bilgilerin eksik kalmasına yol açar."},{"id":"mg-3-s59","tur":"coktan-secmeli","soru":"Kat görevlisi koridorda bir sorun görüp telsizle amirine haber veriyor. Hangisi acil durum iletişim ağına en uygun bildirimdir?","secenekler":["“Katlardan birinde bir sorun var, hemen gelin lütfen.”","“Üçüncü kat, 312 numaralı odanın yanında duman var.”","“Galiba bir yerden yanık kokusu geliyor, ama emin değilim.”","“Koridor çok kalabalık oldu, şimdi ne yapalım?”"],"dogru":1,"aciklama":"Kriz anında bilgi kısa, açık ve doğru iletilir: yer ve olay net söylenince yardım gecikmez. “Bir yerde sorun var” gibi eksik bilgi, ekiplerin nereye gideceğini bilmemesine yol açar."},{"id":"mg-3-s60","tur":"coktan-secmeli","soru":"Otelde yapılan yangın tatbikatından sonra eksiklerin bir toplantıda konuşulması, acil durum müdahalesinin hangi evresine girer?","secenekler":["Kriz öncesi","Kriz süreci","Müdahale aşaması","Kriz sonrası"],"dogru":3,"aciklama":"Olay bittikten sonra eksiklerin değerlendirilmesi kriz sonrası evresidir. Plan ve tüplerin önceden hazırlanması ise kriz öncesine aittir."}],"siralamalar":[{"id":"mg-3-r01","konu":"3.1","baslik":"Mutfağa müfettiş gözüyle bakmak","yonerge":"Bir otel mutfağında İSG gözlemi yaparken izleyeceğin adımları doğru sıraya koy.","adimlar":["İşin türüne, araç gerece ve ortama bakarak elektrik, yangın, düzen gibi gözlem ölçütlerini belirle.","Mutfağı bu ölçütlere göre gözlemle; her riskin ne olduğunu, nerede olduğunu ve kimleri etkileyebileceğini kaydet.","Topladığın verileri fiziksel, kimyasal, ergonomik gibi risk türlerine göre sınıflandır.","En acil risklerden başlayarak alınacak güvenlik tedbirlerini öncelik sırasına koy."],"aciklama":"Ölçüt olmadan gözlem dağınık kalır; ölçütle yapılan gözlem kayda geçer, kayıtlar sınıflandırılınca hangi riskin daha acil olduğu görülür ve tedbirler buna göre sıralanır."},{"id":"mg-3-r02","konu":"3.3","baslik":"Güçlü kimyasala karşı beş basamak","yonerge":"Kat hizmetlerinde kullanılan güçlü bir temizlik kimyasalının riskini azaltırken önlemleri en etkiliden en zayıfa doğru sıraya koy.","adimlar":["Bu kimyasal hiç kullanılmadan işin yapılıp yapılamayacağına bak; mümkünse tehlikeyi tamamen kaldır.","Yerine daha az tehlikeli bir madde ya da yöntem seç.","Havalandırma gibi teknik bir düzenlemeyle buharın çalışanlara ulaşmasını engelle.","Kullanım talimatı hazırla ve çalışanlara güvenli kullanım eğitimi ver.","Çalışana koruyucu eldiven ve gözlük ver."],"aciklama":"Kontrol hiyerarşisinde öncelik tehlikeyi kaynağında yok etmektir; toplu korunma kişisel önlemden önce gelir, kişisel koruyucu donanım ise tehlikeyi kaldırmadığı için diğer önlemleri tamamlayan son basamaktır."},{"id":"mg-3-r03","konu":"3.5","baslik":"Kriz anında soğukkanlı akış","yonerge":"Otelin teknik servisinde bir çalışan düşüp yaralandı. Güvenli müdahale adımlarını doğru sıraya koy.","adimlar":["Olayı fark et ve paniğe kapılmadan durumu anlamaya çalış.","Kendi güvenliğini ve olay yerinin güvenli olup olmadığını kontrol et.","112 Acil Çağrı Merkezini ara; sorulara kısa, açık ve doğru cevap ver.","Yaralıya ilk yardımın eğitim almış bir kişi tarafından yapılmasını sağla.","Olayı kayıt altına al ve müdahale sürecini değerlendir."],"aciklama":"Güvenli olmayan ortamda müdahale tehlikeyi büyütür; bu yüzden olay yeri güvenliği yardım zincirinden, yardım zinciri ilk yardımdan önce gelir. Kayıt ve değerlendirme süreci kapatır."}],"acikSorular":[{"id":"mg-3-y01","konu":"3.3","soru":"Otelin bulaşıkhanesinde zemin sürekli ıslanıyor ve çalışanlar sık sık kayıyor. Amir yalnızca “Dikkat edin” diyor. Riski kaynağında önleme kavramını açıklayarak bu sorun için kaynakta alınabilecek iki önlem yazınız ve bu önlemlerin neden uyarıdan daha güvenilir olduğunu açıklayınız.","olcut":[{"metin":"Riski kaynağında önlemenin, tehlikeyle ortaya çıktığı yerde mücadele etmek olduğunu belirtir.","puan":20},{"metin":"Kaynakta alınabilecek birinci önlemi yazar (örneğin sızdıran hortumun onarılması).","puan":20},{"metin":"Kaynakta alınabilecek ikinci önlemi yazar (örneğin zemine kaymaz kaplama yapılması).","puan":20},{"metin":"Yalnızca uyarmanın neden yetersiz kaldığını, önlemin neden daha güvenilir olduğunu insanın yorulması, unutması ve acele etmesiyle ilişkilendirerek açıklar.","puan":40}],"ornek":"Riski kaynağında önleme, tehlikeyle, insanlara ulaşmasını beklemeden ortaya çıktığı yerde mücadele ederek onu ortadan kaldırmak ya da azaltmaktır. Bulaşıkhanede birinci önlem olarak zemini ıslatan hortum onarılır. İkinci önlem olarak zemine kaymaz kaplama yapılır. Yalnızca “Dikkat edin” demek yetersizdir, çünkü insan yorulur, unutur ve acele eder. Sorunun kendisi çözülürse kayma tehlikesi kişinin dikkatine bağlı kalmaz.","ipucu":"Sorunu insanların dikkatine bırakmakla sorunun kaynağını ortadan kaldırmak arasındaki farkı düşünün."},{"id":"mg-3-y02","konu":"3.5","soru":"Otelin çamaşırhanesinde bir çarşaf tutuşuyor ve yangın henüz başlangıç hâlinde. Yangın üçgenini açıklayarak yangını söndürmenin üç yolunu yazınız ve yangın büyüyorsa görevlinin ne yapması gerektiğini nedeniyle birlikte belirtiniz.","olcut":[{"metin":"Yangın üçgeninin yanıcı madde, ısı ve oksijenden oluştuğunu belirtir.","puan":20},{"metin":"Üçgenin bir kenarı kaldırılırsa yangının söneceğini açıklar.","puan":20},{"metin":"Söndürmenin üç yolunu örnekle yazar: soğutarak ısıyı kesmek, örterek oksijeni kesmek, uzaklaştırarak yanıcı maddeyi yok etmek.","puan":25},{"metin":"Yangın büyüyorsa söndürmeye uğraşmayıp alarm vererek binayı terk etmesi gerektiğini ve bunun nedenini (can güvenliği) açıklar.","puan":35}],"ornek":"Yangın üçgeni, yanmanın olması için bir arada bulunması gereken yanıcı madde, ısı ve oksijeni gösterir. Bu kenarlardan biri kaldırılırsa yangın söner. Isıyı soğutarak, oksijeni yangın battaniyesiyle örterek, yanıcı maddeyi de uzaklaştırarak yok edebiliriz. Yangın büyüyorsa görevli söndürmeye uğraşmaz; alarm verir, çıkar ve kapıyı arkasından kapatır, çünkü can güvenliği malzemeden önce gelir.","ipucu":"Üçgenin her kenarını bir söndürme yöntemiyle eşleştirin; sonra yangın kontrolden çıkınca neyin öncelik kazandığını düşünün."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":4,"baslik":"Çevre Koruma","onay":true,"kazanimlar":["Atık oluşumunu ve atık yönetimi uygulamalarını gözlemleyebilme.","İnsan faaliyetlerinin çevre üzerindeki etkilerini çözümleyebilme.","Küresel çevre sorunlarını yeşil dönüşüm ilkeleri bağlamında değerlendirebilme.","Çevre kirliliği ile ilgili bir probleme yönelik çözüm stratejileri yapılandırabilme.","İşletmelerde kaynak kullanımı ve atık yönetimi problemlerini döngüsel ekonomi stratejileri çerçevesinde çözebilme."],"soz":"Konuk denizi, ormanı ve temiz havayı görmeye gelir; onları korumak işimizin kendisidir.","dersler":[{"baslik":"Çevre Kimin Emaneti?","ilk":"mg-4-001"},{"baslik":"Çöp mü, Kaynak mı?","ilk":"mg-4-006"},{"baslik":"Önce Hangisi?","ilk":"mg-4-011"},{"baslik":"Ayır, Kazan, Sıfırla","ilk":"mg-4-016"},{"baslik":"Boşa Giden Her Şey","ilk":"mg-4-030"},{"baslik":"Kutuların Sırrı","ilk":"mg-4-070"},{"baslik":"Atığı Tanı, Sınıfla","ilk":"mg-4-075"},{"baslik":"Doğaya Sahip Çık","ilk":"mg-4-079"},{"baslik":"Kirlilik Nereden Gelir?","ilk":"mg-4-020"},{"baslik":"Ayak İzin Ne Kadar Büyük?","ilk":"mg-4-025"},{"baslik":"Yarına Kalan Otel","ilk":"mg-4-064"},{"baslik":"Kirliliğin Yolculuğu","ilk":"mg-4-083"},{"baslik":"Kirlenmeden Önle","ilk":"mg-4-088"},{"baslik":"Dünya Neden Isınıyor?","ilk":"mg-4-032"},{"baslik":"Yeşile Dönüş","ilk":"mg-4-037"},{"baslik":"Ormandan Kıtlığa","ilk":"mg-4-093"},{"baslik":"Sofradan Topluma","ilk":"mg-4-097"},{"baslik":"Sorunu Kılçığına Ayır","ilk":"mg-4-027"},{"baslik":"Etiket mi, Gerçek mi?","ilk":"mg-4-050"},{"baslik":"Kanun Ne Diyor?","ilk":"mg-4-061"},{"baslik":"Şapkanı Tak, Çözümü Kur","ilk":"mg-4-104"},{"baslik":"Al, Yap, At Devri Bitti","ilk":"mg-4-066"},{"baslik":"Verimli Olmanın Sırrı","ilk":"mg-4-056"},{"baslik":"Tamir Et, Uzat","ilk":"mg-4-109"}],"kavramlar":[{"id":"mg-4-001","konu":"4.1","terim":"Çevre","ingilizce":"Environment","tanim":"İnsanların ve öteki canlıların içinde yaşadığı; hava, su, toprak, bitki ve hayvanlarla birlikte bütün ortamdır.","ornek":"Sabah 08.00, sahil otelinin terası: konuk kahvesini içerken denize, çam ağaçlarına ve temiz havaya bakar; gördüğü her şey otelin çevresidir.","sektor":"Turizmde çevre yalnız yaşadığımız yer değil, konuğa sunduğumuz şeyin kendisidir. Denizi kirlenen, ormanı yanan bir bölgeye konuk gelmez.","iliskili":["mg-4-002","mg-4-003","mg-4-027"],"kontrol":null,"gorsel":"t13a-oludeniz-koy"},{"id":"mg-4-002","konu":"4.1","terim":"Çevre koruma","ingilizce":"Environmental protection","tanim":"Havanın, suyun, toprağın ve canlıların zarar görmesini önlemek, bozulanı iyileştirmek için yapılan çalışmaların bütünüdür.","ornek":"Otel, bahçe sulamasını sabah erken saate alır, atıklarını türüne göre ayırır ve plajını her sabah temizler.","sektor":"Programın anahtar kavramlarındandır. Çevre koruma ayrı bir bölümün işi değildir; mutfakta, katta, bahçede çalışan herkesin günlük işinin parçasıdır.","iliskili":["mg-4-001","mg-4-031","mg-4-042"],"kontrol":null},{"id":"mg-4-003","konu":"4.1","terim":"Doğal kaynak","ingilizce":"Natural resource","tanim":"Doğada kendiliğinden bulunan ve insanın ihtiyaçlarını karşılamak için kullandığı su, toprak, orman, maden ve enerji kaynakları gibi varlıklardır.","ornek":"Bir otel odasında akan su, yanan lamba, yatağın pamuklu çarşafı ve ahşap masa; hepsi bir doğal kaynaktan gelir.","sektor":"Doğal kaynaklar sınırsız değildir. Otel her gün çok su ve enerji kullanır; bu yüzden kaynağı özenli kullanmak hem doğayı hem işletmenin bütçesini korur.","iliskili":["mg-4-001","mg-4-055","mg-4-056"],"kontrol":null,"gorsel":"m3-rogue-river-oregon-usa"},{"id":"mg-4-004","konu":"4.1","terim":"Atık","ingilizce":"Waste","tanim":"Üretim ya da kullanım sonunda ortaya çıkan ve sahibinin artık işine yaramadığı için elden çıkardığı maddedir.","ornek":"Saat 10.30, kahvaltı salonu toplanıyor: boş yoğurt kapları, cam şişeler, kâğıt peçeteler ve tabaklarda kalan yemek artıkları.","sektor":"Programın anahtar kavramlarındandır. Her atık çöp değildir: doğru ayrılırsa çoğu yeniden hammaddeye dönüşür. Atığı “yanlış yerde duran kaynak” gibi görmek mesleki bakışı değiştirir.","iliskili":["mg-4-005","mg-4-006","mg-4-016"],"kontrol":null,"gorsel":"mg-atik"},{"id":"mg-4-005","konu":"4.1","terim":"Atık yönetimi","ingilizce":"Waste management","tanim":"Atığın azaltılması, türüne göre ayrı toplanması, taşınması, yeniden değerlendirilmesi ve çevreye zarar vermeden ortadan kaldırılması işlerinin planlı biçimde yürütülmesidir.","ornek":"Otelin arka avlusunda her atık türü için ayrı bir toplama alanı vardır; bölümler atıklarını gün sonunda buraya getirir, yetkili firmalar belirli günlerde alır.","sektor":"Programın anahtar kavramlarındandır. İyi atık yönetimi kötü kokuyu, haşereyi ve gereksiz masrafı önler. Konuk arka avluyu görmez ama sonucunu temiz bir otel olarak hisseder.","iliskili":["mg-4-004","mg-4-011","mg-4-016"],"kontrol":null,"gorsel":"sektor-atik-kutulari"},{"id":"mg-4-006","konu":"4.1","terim":"Organik atık","ingilizce":"Organic waste","tanim":"Yemek artığı, sebze-meyve kabuğu, çay posası ve bahçe budama artığı gibi doğada kendiliğinden çürüyebilen atıktır.","ornek":"Sabah 06.30, otel mutfağı: kahvaltı için soyulan salatalık, domates ve portakalların kabukları ayrı bir kovada toplanır.","sektor":"Otel ve restoranlarda en çok oluşan atık türlerinden biridir. Öteki atıklarla karışırsa onları da kirletir ve geri dönüşümü zorlaştırır; ayrı toplanırsa komposta dönüşebilir.","iliskili":["mg-4-004","mg-4-019","mg-4-058"],"kontrol":null,"gorsel":"sektor-kompost-kovasi"},{"id":"mg-4-007","konu":"4.1","terim":"Ambalaj atığı","ingilizce":"Packaging waste","tanim":"Bir ürünü taşımak, korumak ya da sunmak için kullanılan kâğıt, karton, plastik, cam ve metal ambalajların kullanıldıktan sonra atığa dönüşmüş hâlidir.","ornek":"Saat 09.00, otelin mal kabul kapısı: tedarikçiden gelen koliler açılır; geriye karton kutular, streç filmler ve plastik kasalar kalır.","sektor":"Kâğıt, plastik, cam ve metal geri dönüştürülebilen ambalajlardır. Temiz ve kuru ayrıldıklarında değer taşırlar; yemek artığıyla karışınca bu değer kaybolur.","iliskili":["mg-4-004","mg-4-015","mg-4-016"],"kontrol":null,"gorsel":"mg-ambalaj-atigi"},{"id":"mg-4-008","konu":"4.1","terim":"Tehlikeli atık","ingilizce":"Hazardous waste","tanim":"İçindeki zehirli, yanıcı ya da aşındırıcı maddeler yüzünden insan sağlığına ve çevreye zarar verebilen atıktır.","ornek":"Teknik servis görevlisi koridordaki bozuk floresan lambayı değiştirir; eskisini çöp kovasına değil, teknik depodaki özel kutuya koyar.","sektor":"Otelde floresan lamba, atık pil, boya ve çözücü artığı, havuz ve temizlik kimyasallarının boş kapları bu gruptadır. Öteki atıklara karıştırılmaz; ayrı toplanır ve yetkili firmaya teslim edilir.","iliskili":["mg-4-004","mg-4-009","mg-4-018"],"kontrol":null,"gorsel":"m3-kontejner-na-nebezpecny-odpad-bate"},{"id":"mg-4-009","konu":"4.1","terim":"Elektronik atık","ingilizce":"Electronic waste (e-waste)","tanim":"Bozulan ya da kullanım ömrü dolan elektrikli ve elektronik cihazların oluşturduğu atıktır.","ornek":"Seyahat acentesinde eski yazıcı ve bozuk bir bilgisayar ekranı yenilenir; eskileri depoda biriktirilir ve yetkili toplama noktasına verilir.","sektor":"Sektörde kısaca “e-atık” denir. İçinde hem değerli metaller hem zararlı maddeler bulunur; çöpe atılırsa ikisi de toprağa gider. Otelde televizyon, telefon, kart okuyucu ve kablolar bu gruptadır.","iliskili":["mg-4-008","mg-4-015","mg-4-017"],"kontrol":null,"gorsel":"mg-elektronik-atik"},{"id":"mg-4-010","konu":"4.1","terim":"Bitkisel atık yağ","ingilizce":"Waste cooking oil","tanim":"Kızartma ve pişirmede kullanıldıktan sonra artık kullanılamayacak duruma gelen bitkisel yağdır.","ornek":"Saat 23.00, restoran mutfağı kapanıyor: fritözdeki yağ soğuduktan sonra ağzı kapaklı atık yağ bidonuna süzülür.","sektor":"Lavaboya ya da gidere dökülmez: boruları tıkar, suyu kirletir. Ayrı kapta biriktirilir ve yetkili toplayıcıya teslim edilir; toplanan yağ başka ürünlerin üretiminde değerlendirilir.","iliskili":["mg-4-006","mg-4-023","mg-4-016"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-011","konu":"4.1","terim":"Atık hiyerarşisi","ingilizce":"Waste hierarchy","tanim":"Oluşan ya da oluşacak bir atık için hangi yolun önce deneneceğini gösteren öncelik sıralamasıdır.","ornek":"Otel yönetimi toplantıda önce “Bu atığı hiç oluşturmayabilir miyiz?” diye sorar; olmuyorsa yeniden kullanmayı, o da olmuyorsa geri dönüştürmeyi konuşur.","sektor":"Programda “atık yönetimi öncelik basamakları” diye geçer. Sıra şöyledir: önce azalt, sonra yeniden kullan, sonra geri dönüştür; hiçbirine uymayan atık en son çevreye zarar vermeden ortadan kaldırılır.","iliskili":["mg-4-012","mg-4-013","mg-4-018"],"kontrol":null},{"id":"mg-4-012","konu":"4.1","terim":"3R ilkesi","ingilizce":"The 3Rs (reduce, reuse, recycle)","tanim":"Atığı ve kaynak israfını önlemek için sırasıyla azaltmayı, yeniden kullanmayı ve geri dönüştürmeyi öneren ilkedir.","ornek":"Otel kahvaltıda tek kullanımlık reçel paketlerini kaldırır (azalt), cam kavanozları yıkayıp yeniden doldurur (yeniden kullan), kırılan kavanozları cam kutusuna atar (geri dönüştür).","sektor":"Programın anahtar kavramlarındandır. Adını İngilizce üç sözcüğün baş harfinden alır: reduce, reuse, recycle. Sıra önemlidir: en iyi atık, hiç oluşmamış atıktır.","iliskili":["mg-4-013","mg-4-014","mg-4-015"],"kontrol":null,"gorsel":"m3-recycling-sign"},{"id":"mg-4-013","konu":"4.1","terim":"Azaltma (atık önleme)","ingilizce":"Reduce (waste prevention)","tanim":"Daha az tüketerek ve gereksiz kullanımı keserek atığın hiç oluşmamasını sağlamaktır.","ornek":"Banyodaki kartta “Havlunuzu yeniden kullanmak isterseniz askıya asınız” yazar; askıdaki havlu o gün yıkanmaz, su ve deterjan harcanmaz.","sektor":"3R’nin ilk ve en etkili adımıdır. Azaltmak hizmetten kısmak değildir: konuğun konforu aynı kalır, gereksiz olan çıkar. İşletme hem atık masrafından hem satın almadan kazanır.","iliskili":["mg-4-012","mg-4-011","mg-4-030"],"kontrol":null},{"id":"mg-4-014","konu":"4.1","terim":"Yeniden kullanım","ingilizce":"Reuse","tanim":"Bir ürünün atılmadan, aynı ya da benzer bir iş için tekrar tekrar kullanılmasıdır.","ornek":"Otel, odalara plastik şişe yerine cam sürahi koyar; sürahi her gün yıkanır, yeniden doldurulur ve yıllarca kullanılır.","sektor":"Yeniden kullanımda ürün şeklini değiştirmez; geri dönüşümde ise hammaddeye çevrilip yeniden üretilir. Bu yüzden yeniden kullanım daha az enerji ister ve sıralamada geri dönüşümden önce gelir.","iliskili":["mg-4-012","mg-4-015","mg-4-059"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-015","konu":"4.1","terim":"Geri dönüşüm","ingilizce":"Recycling","tanim":"Kâğıt, plastik, cam ve metal gibi atıkların işlenerek yeniden hammaddeye ve yeni ürünlere dönüştürülmesidir.","ornek":"Otelin kafesinden toplanan boş cam şişeler cam kutusunda birikir; tesiste eritilir ve yeniden şişe olur.","sektor":"Programın anahtar kavramlarındandır. Geri dönüşüm fabrikada yapılır ama otelde başlar: atık doğru kutuya atılmazsa zincir daha ilk halkada kopar. Geri kazanılan her atık, doğadan alınacak hammaddeyi azaltır.","iliskili":["mg-4-012","mg-4-016","mg-4-017"],"kontrol":null,"gorsel":"sektor-geri-donusum"},{"id":"mg-4-016","konu":"4.1","terim":"Kaynağında ayrıştırma","ingilizce":"Source separation","tanim":"Atığın, oluştuğu yerde ve oluştuğu anda türüne göre ayrı kaplara konulmasıdır.","ornek":"Saat 13.00, kat görevlisi odayı toplarken arabasındaki ayrı torbaları kullanır: gazeteler bir torbaya, plastik şişeler ötekine, kalan çöp üçüncüsüne.","sektor":"Karışmış atığı sonradan ayırmak zor, pahalı ve çoğu zaman imkânsızdır. Ayrıştırma mutfakta, barda, ofiste, yani atığın çıktığı noktada yapılır; bu yüzden her çalışanın işidir.","iliskili":["mg-4-005","mg-4-015","mg-4-020"],"kontrol":null,"gorsel":"sektor-atik-ayristirma"},{"id":"mg-4-017","konu":"4.1","terim":"Geri kazanım","ingilizce":"Recovery","tanim":"Atığın geri dönüşüm, kompost ya da enerji elde etme gibi yollarla yeniden işe yarar duruma getirilmesidir.","ornek":"Otelin kâğıt atığı yeni kâğıda, mutfak atığı komposta dönüşür; ikisi de geri kazanımdır.","sektor":"Geri dönüşümden daha geniş bir kavramdır: geri dönüşüm, geri kazanım yollarından yalnızca biridir. Programdaki “geri kazanım potansiyeli” sözü, bir atığın yeniden değerlendirilip değerlendirilemeyeceğini anlatır.","iliskili":["mg-4-015","mg-4-019","mg-4-018"],"kontrol":null,"gorsel":"mg-geri-donusum-kutulari"},{"id":"mg-4-018","konu":"4.1","terim":"Bertaraf","ingilizce":"Disposal","tanim":"Hiçbir yolla yeniden değerlendirilemeyen atığın, çevreye ve insan sağlığına zarar vermeyecek biçimde ortadan kaldırılmasıdır.","ornek":"Otelin ayrıştırma sonunda geriye kalan, değerlendirilemeyen çöpünü belediye alır ve düzenli depolama alanına götürür.","sektor":"Atık hiyerarşisinin son basamağıdır; öteki yollar denendikten sonra başvurulur. Bertarafa giden atık ne kadar azsa işletmenin atık yönetimi o kadar başarılıdır.","iliskili":["mg-4-011","mg-4-017","mg-4-020"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-019","konu":"4.1","terim":"Kompost","ingilizce":"Compost","tanim":"Sebze-meyve kabuğu, çay posası ve bahçe artığı gibi organik atıkların çürütülmesiyle elde edilen doğal gübredir.","ornek":"Otelin bahçıvanı, mutfaktan gelen sebze kabuklarını ve budanan dalları bahçenin köşesindeki kompost kabında bekletir; oluşan gübreyi çiçek tarhlarına serer.","sektor":"Mutfağın atığı bahçenin besini olur: işletme hem çöpe giden atığı hem gübre masrafını azaltır. Konuğa anlatıldığında otelin çevreye verdiği önemi gösteren güzel bir hikâyedir.","iliskili":["mg-4-006","mg-4-017","mg-4-054"],"kontrol":null,"gorsel":"sektor-kompost"},{"id":"mg-4-030","konu":"4.1","terim":"İsraf","ingilizce":"Wastefulness","tanim":"Bir kaynağın ihtiyaçtan fazla, özensiz ya da boş yere harcanmasıdır.","ornek":"Boş toplantı salonunda saatlerce çalışan klima, açık unutulan musluk, yarısı yenmeden çöpe giden tabaklar.","sektor":"Kültürümüzde israf hoş karşılanmaz; doğa insana bir emanet sayılır. İş yerinde israf iki kez kaybettirir: boşa harcanan kaynağın parası ödenir, oluşan atığın masrafı da üstüne eklenir.","iliskili":["mg-4-013","mg-4-056","mg-4-058"],"kontrol":null,"gorsel":"sektor-damlayan-musluk"},{"id":"mg-4-044","konu":"4.1","terim":"Sürdürülebilirliğin üç boyutu","ingilizce":"Three pillars of sustainability","tanim":"Bir işin kalıcı olabilmesi için birlikte gözetilmesi gereken çevresel, ekonomik ve sosyal yönlerdir.","ornek":"Bir otel suyu ve enerjiyi özenli kullanır (çevresel), kâr edip ayakta kalır (ekonomik), çalışanına adil davranır ve bölge halkından personel alır (sosyal).","sektor":"Üçü bir masanın ayakları gibidir: biri eksik kalırsa masa devrilir. Yalnız kârı düşünen işletme doğayı tüketir; yalnız doğayı düşünüp para kazanamayan işletme de kapanır ve kimseye iş veremez.","iliskili":["mg-4-042","mg-4-043","mg-4-050"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-067","konu":"4.1","terim":"Çöp","ingilizce":"Rubbish (refuse)","tanim":"Artık kullanılamayan ve geri kazanılması mümkün olmayan karışık artıklara verilen addır.","ornek":"Saat 15.00, otelin servis koridoru: yemek artığına bulaşıp birbirine karışmış kâğıt ve plastikler tek torbaya girer; bunlar artık çöptür.","sektor":"Atıkla çöp aynı şey değildir: doğru ayrılan atık değer taşır, karışıp kirlenen atık çöpe dönüşür.","iliskili":["mg-4-004","mg-4-015"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-068","konu":"4.1","terim":"Geri kazanım potansiyeli","ingilizce":"Recovery potential","tanim":"Bir atığın yeniden kullanılma, geri dönüştürülme ya da başka bir üretimde hammadde olma olasılığının ne kadar yüksek olduğudur.","ornek":"Saat 17.00, otel kafesi: temiz alüminyum içecek kutusunun geri kazanım potansiyeli yüksektir; yağa bulaşmış peçetenin potansiyeli çok düşüktür.","sektor":"Bir otelde mal kabulden çıkan temiz koli ile mutfaktan çıkan yağlı karton aynı malzemedir, ama potansiyelleri farklıdır: temiz olan geri kazanılabilir, yağa bulaşan değerini kaybeder. Atığı ayıran personel kendine bu parçanın yeniden değerlendirilip değerlendirilemeyeceğini sorar; ayırma işinin ölçütü bu sorudur.","iliskili":["mg-4-015","mg-4-017"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"mg-4-069","konu":"4.1","terim":"Kâğıt ve karton atıkları","ingilizce":"Paper and cardboard waste","tanim":"Defter yaprağı, karton kutu ve gazete gibi kâğıt temelli ürünlerden oluşan, ayrı toplandığında geri dönüştürülebilen atıklardır.","ornek":"Saat 09.00, otelin mal kabulü: boşalan karton koliler katlanıp kâğıt-karton kutusuna konur.","sektor":"Mal kabulden çıkan koliler ve ofisteki kullanılmış kâğıtlar bu gruptadır; kuru ve temiz kaldıkları sürece geri dönüşüme gider. Konuğun adının ya da oda bilgisinin yazılı olduğu kâğıt ise kutuya atılmadan önce parçalanır, çünkü konuğun bilgisi çöpte de korunmalıdır.","iliskili":["mg-4-015","mg-4-016"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-070","konu":"4.1","terim":"Plastik atıklar","ingilizce":"Plastic waste","tanim":"PET şişe, plastik kap, poşet ve ambalaj gibi plastik malzemelerden oluşan, türüne ve temizliğine bağlı olarak geri dönüştürülebilen atıklardır.","ornek":"Saat 19.00, otel restoranı: içecek servisinden toplanan boş PET şişeler durulanıp plastik kutusuna atılır.","sektor":"Minibar şişeleri, küçük banyo ürünlerinin ambalajı ve kahvaltıdaki tek kullanımlık kaplar kat ve servis ekiplerinin sık topladığı plastiklerdendir. İçi boşaltılıp ayrı kutuya atılan plastik geri dönüşüme girebilir, yemek artığıyla karışan plastik ise bu imkânı yitirir; ayırma işinin kazancı da buradadır.","iliskili":["mg-4-015","mg-4-016","mg-4-014"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-071","konu":"4.1","terim":"Cam atıkları","ingilizce":"Glass waste","tanim":"Cam şişe ve kavanoz gibi cam malzemelerden oluşan, uygun toplamayla geri dönüştürülebilen atıklardır.","ornek":"Gece 23.30, otel barı kapanıyor: boş cam şişeler ayrı cam kutusuna konur.","sektor":"Bar ve restoran otelde çok cam şişe toplanan yerlerdendir; şişeler çöp torbasına değil ayrı cam kutusuna atılır. Bu hem geri dönüşümü sağlar hem de torbayı taşıyan meslektaşının eline kırık cam batmasını önler, yani cam atığını ayırmak aynı zamanda bir iş güvenliği önlemidir.","iliskili":["mg-4-015","mg-4-016"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-072","konu":"4.1","terim":"Metal atıkları","ingilizce":"Metal waste","tanim":"Alüminyum kutu, konserve kutusu ve metal parça gibi metal içerikli, geri dönüşüm değeri yüksek atıklardır.","ornek":"Saat 10.00, otel mutfağı: boşalan konserve kutuları yıkanıp metal atık kutusuna atılır.","sektor":"Mutfaktan çıkan konserve kutuları, bardan gelen içecek kutuları ve teknik servisin değiştirdiği boru ile musluk parçaları metal atık grubundadır. Çoğu metal defalarca geri dönüştürülebildiği için çöpe karışması doğadan yeniden hammadde çıkarılması anlamına gelir; ayrı kutu bu yüzden herkesin yapabileceği kolay bir katkıdır.","iliskili":["mg-4-015","mg-4-016"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-073","konu":"4.1","terim":"Atık piller","ingilizce":"Waste batteries","tanim":"Kumanda, saat ya da şarjlı pil gibi kullanım ömrünü tamamlamış, ayrı toplanması gereken özel atıklardır.","ornek":"Saat 11.00, resepsiyon: bitmiş kumanda pilleri çöpe atılmaz, ön büronun pil kutusunda biriktirilir.","sektor":"Kat hizmetlerinin değiştirdiği televizyon ve klima kumandası pilleri ile teknik servisin değiştirdiği kapı kilidi pilleri otelde birikir. Bunlar çöpe değil pil kutusuna atılır, çünkü pilin içindeki metaller çöp alanında toprağa ve suya karışabilir; ayrı kutu küçük ama gerekli bir alışkanlıktır.","iliskili":["mg-4-008","mg-4-078"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-074","konu":"4.1","terim":"Tıbbi atık","ingilizce":"Medical waste","tanim":"Sağlık hizmeti sırasında oluşan, enjektör, kanla temas etmiş malzeme ve pansuman atığı gibi riskli atıklardır.","ornek":"Saat 14.00, otelin ilk yardım odası: bir konuğun yarasına pansuman yapılır; kanlı gazlı bez normal çöpe değil, kapaklı özel kutuya atılır.","sektor":"Özel toplama ve bertaraf gerektirir.","iliskili":["mg-4-008","mg-4-078"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-075","konu":"4.1","terim":"Evsel atık","ingilizce":"Household waste","tanim":"Evlerde günlük yaşam sırasında oluşan yemek artığı, ambalaj ve benzeri atıklardır.","ornek":"Pazar sabahı bir ailenin mutfağında kahvaltı sonrası biriken peçete, yoğurt kabı ve kabuklar evsel atıktır.","sektor":"Bir otelin konuk odaları, lobisi ve restoranı evle aynı türden atık üretir: yemek artığı, ambalaj, peçete. Fark bunun çok sayıda kişi için aynı anda oluşmasıdır; miktar büyüdüğü için kaynağında ayrıştırmanın değeri de büyüktür.","iliskili":["mg-4-004","mg-4-076"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-076","konu":"4.1","terim":"Sanayi atığı","ingilizce":"Industrial waste","tanim":"Fabrika ve atölye gibi üretim yerlerinde üretim sırasında oluşan atıklardır.","ornek":"Saat 10.00, bir mobilya atölyesinde ahşap kesilirken talaş ve küçük ahşap parçalar oluşur; bunlar sanayi atığıdır.","sektor":"Otelin satın aldığı mobilya, çarşaf, havlu ve paketli gıda üretildikleri fabrikalarda sanayi atığı bırakır; yani otelin çevre etkisi kendi kapısında bitmez. Büyük bir otelin teknik servis atölyesinde çıkan talaş ve metal parçalar da bu gruba girer ve evsel atıkla karıştırılmamalıdır.","iliskili":["mg-4-004","mg-4-075"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-077","konu":"4.1","terim":"Atık sınıflandırması","ingilizce":"Waste classification","tanim":"Atıkların oluştuğu yere, içeriğine, çevresel etkisine ve geri kazanım olasılığına göre türlere ayrılmasıdır.","ornek":"Otel çevre sorumlusu saat 16.00’da arka avludaki kutuları türüne göre gruplar: kâğıt, cam, organik ve tehlikeli.","sektor":"Doğru yönetimin ilk adımıdır; sınıflandırılmayan atık kirlenir, tehlikeli atık çevreye zarar verir.","iliskili":["mg-4-016","mg-4-078"],"kontrol":null,"cizim":"kalite-yildiz"},{"id":"mg-4-078","konu":"4.1","terim":"Özel toplama","ingilizce":"Separate (special) collection","tanim":"Tehlikeli atık, atık pil ve atık yağ gibi atıkların öteki atıklardan ayrı ve özel kurallara göre toplanmasıdır.","ornek":"Saat 23.00, restoran mutfağı: atık yağ, yemek artığı kovasına değil, kapaklı atık yağ bidonuna konur.","sektor":"Atık yağ, pil, floresan lamba ve boş kimyasal kapları otelde genel çöp kutusuna değil, etiketli ve kapaklı özel kaplara konur; sonra yetkili firmaya teslim edilir. Bu kural yalnız doğayı değil, torbayı taşıyan çalışanı da korur, çünkü yağ ya da kimyasal bulaşmış torba onun için de risktir.","iliskili":["mg-4-008","mg-4-074"],"kontrol":null,"cizim":"grafik"},{"id":"mg-4-079","konu":"4.1","terim":"Atık yönetiminin etkileri","ingilizce":"Impacts of waste management","tanim":"Toplama, ayırma ve geri kazanım uygulamalarının çevreye, ekonomiye ve topluma olan olumlu ya da olumsuz sonuçlarıdır.","ornek":"Saat 18.00, bir otel yönetimi atıkları ayrı toplamaya başlayınca çöp masrafı düşer (ekonomik), kıyıdaki kirlilik azalır (çevresel) ve personel sorumluluk duygusu kazanır (sosyal).","sektor":"Etkiler çevresel, ekonomik ile sosyal ve ahlaki olmak üzere üç grupta incelenir.","iliskili":["mg-4-005","mg-4-044"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-080","konu":"4.1","terim":"Doğanın emanet olduğu bilinci","ingilizce":"Stewardship of nature","tanim":"Doğayı insana verilmiş bir emanet saymak, onu korumak ve kaynakları israf etmemektir.","ornek":"Sabah 07.30, bir otel çalışanı boş salonda açık kalmış ışığı ve akan musluğu kimse söylemeden kapatır.","sektor":"Din Kültürü ve Ahlak Bilgisi dersinde de vurgulanan bir anlayıştır.","iliskili":["mg-4-002","mg-4-030"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-081","konu":"4.1","terim":"Saha gözlemi","ingilizce":"Field observation","tanim":"Atıkları ve atık yönetimi uygulamalarını bulundukları yerde inceleyip bir kontrol listesiyle kaydetme çalışmasıdır.","ornek":"Saat 12.00, öğrenci okul kantininde hangi atıkların oluştuğunu, geri dönüşüm kutusunun nerede durduğunu ve atıkların ayrılıp ayrılmadığını listeye işler.","sektor":"Saha gözleminin başlıca durakları otelde mutfağın arka kapısı, kat servis odaları ve çöp odasıdır; kutuların yerinde ve etiketli olup olmadığı, atıkların karışıp karışmadığı kontrol listesine işlenir. Notlar kimseyi suçlamak için değil, düzeni geliştirmek için tutulur ve bulgular yönetime saygılı bir dille aktarılır; iyi bir gözlemcinin tutumu budur.","iliskili":["mg-4-077","mg-4-004"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-082","konu":"4.1","terim":"Fire (üretim atığı)","ingilizce":"Production waste (scrap)","tanim":"Üretim sırasında kesme, soyma ya da dökülme gibi nedenlerle ortaya çıkan ve ürüne girmeyen kısımdır.","ornek":"Saat 06.30, otel mutfağında sebzeler soyulurken kabuklar ve atılan uçlar fire olarak ayrılır.","sektor":"Otel mutfağında aşçı, sebzenin kabuğunun ve ucunun, balığın kılçığının, etin yağının fire olacağını bilerek alım yapar; çünkü satın alınan malın tamamı tabağa çıkmaz. Fireyi azaltmak, yani doğru soymak ve kesmek, hem çöpe giden atığı hem de boşa ödenen parayı küçültmenin ilk adımıdır.","iliskili":["mg-4-004","mg-4-013"],"kontrol":null,"cizim":"yangin"},{"id":"mg-4-020","konu":"4.2","terim":"Sıfır atık","ingilizce":"Zero waste","tanim":"İsrafı önlemeyi, atığı azaltmayı ve oluşan atığı kaynağında ayrı toplayıp yeniden değerlendirmeyi amaçlayan atık yönetimi yaklaşımıdır.","ornek":"Otel, personel yemekhanesinden lobiye kadar her alana ayrı atık kutuları koyar, personelini eğitir ve toplanan atık miktarını düzenli olarak kaydeder.","sektor":"Programın anahtar kavramlarındandır. “Sıfır” bir hedeftir: amaç çöpe giden atığı olabildiğince azaltmaktır. Türkiye’de kurumlar ve işletmeler için sıfır atık sistemi kurma çalışmaları yürütülür.","iliskili":["mg-4-016","mg-4-012","mg-4-063"],"kontrol":null},{"id":"mg-4-021","konu":"4.2","terim":"Çevre kirliliği","ingilizce":"Pollution","tanim":"Havaya, suya ya da toprağa karışan zararlı maddelerin ve etkilerin çevrenin doğal dengesini bozmasıdır.","ornek":"Yaz sonunda bir koy: kıyıya vurmuş plastik şişeler, suyun üstünde ince bir yağ tabakası ve kumda izmaritler.","sektor":"Programın anahtar kavramlarındandır. Kirliliğin büyük bölümü insan faaliyetlerinden doğar; her mesleğin de buna bir katkısı ve bir çözümü vardır. Turizm, temiz çevreye en çok ihtiyaç duyan sektörlerdendir.","iliskili":["mg-4-022","mg-4-023","mg-4-024"],"kontrol":null,"gorsel":"m3-cairo-in-smog"},{"id":"mg-4-022","konu":"4.2","terim":"Hava kirliliği","ingilizce":"Air pollution","tanim":"Baca dumanı, egzoz gazı ve toz gibi zararlı maddelerin havaya karışarak canlıların sağlığını tehdit edecek düzeye gelmesidir.","ornek":"Sabah 09.00, otelin giriş kapısı: tur otobüsü yolcularını beklerken motoru çalışır durumda bırakılmış, egzoz gazı lobiye doluyor.","sektor":"Otelde kazan dairesi, jeneratör, mutfak bacası ve araç trafiği başlıca kaynaklardır. Bakımlı cihaz, temiz filtre ve bekleyen aracın motorunu kapatması basit ama etkili önlemlerdir.","iliskili":["mg-4-021","mg-4-033","mg-4-037"],"kontrol":null,"gorsel":"mg-hava-kirliligi"},{"id":"mg-4-023","konu":"4.2","terim":"Su kirliliği","ingilizce":"Water pollution","tanim":"Denize, göle, akarsuya ya da yer altı suyuna karışan atıkların ve kimyasalların suyu canlılar için zararlı duruma getirmesidir.","ornek":"Kıyıdaki bir işletme atık suyunu arıtmadan denize verirse suyun rengi ve kokusu değişir, o koyda kimse denize girmek istemez.","sektor":"Deniz turizminin sermayesi temiz sudur. Gidere dökülen atık yağ ve gereğinden fazla kullanılan temizlik kimyasalı suya karışır; ölçülü kullanım ve atık suyun arıtılması bu yüzden önemlidir.","iliskili":["mg-4-021","mg-4-010","mg-4-026"],"kontrol":null,"gorsel":"mg-su-kirliligi"},{"id":"mg-4-024","konu":"4.2","terim":"Toprak kirliliği","ingilizce":"Soil pollution","tanim":"Toprağa karışan çöp, kimyasal madde ve zehirli atıkların toprağın yapısını ve verimini bozmasıdır.","ornek":"Otelin bahçe deposunun arkasına bırakılan eski boya kutuları yağmurda sızdırır; boya toprağa ve oradan yer altı suyuna karışır.","sektor":"Toprağa giren zararlı madde orada kalmaz: suya ve yetişen ürüne geçer. Atık pil, boya ve kimyasal kabı gibi tehlikeli atıkların ayrı toplanmasının nedeni budur.","iliskili":["mg-4-021","mg-4-008","mg-4-027"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-025","konu":"4.2","terim":"Gürültü kirliliği","ingilizce":"Noise pollution","tanim":"İnsanların ve öteki canlıların sağlığını, huzurunu ve dinlenmesini bozan rahatsız edici ses düzeyidir.","ornek":"Gece 01.00, sahildeki otelin açık hava eğlencesi sürüyor: müzik hem odalardaki konukları hem çevredeki evleri uyutmuyor.","sektor":"Kirlilik yalnız gözle görülen atık değildir. Otelde müzik, jeneratör, klima dış ünitesi ve servis araçları ses kaynağıdır; eğlence saatine ve ses düzeyine uymak hem konuğa hem komşuya saygıdır.","iliskili":["mg-4-021","mg-4-028","mg-4-031"],"kontrol":null,"gorsel":"m3-permanent-noise-control-barrier-al"},{"id":"mg-4-026","konu":"4.2","terim":"Tek kullanımlık plastik","ingilizce":"Single-use plastic","tanim":"Bir kez kullanılıp atılmak üzere üretilen pipet, bardak, poşet ve küçük ambalaj gibi plastik ürünlerdir.","ornek":"Havuz barında her içecek plastik bardak ve pipetle verilir; akşam olduğunda çöp kovaları ağzına kadar plastikle doludur.","sektor":"Plastik doğada çok uzun süre yok olmaz; rüzgârla denize taşınır ve deniz canlılarına zarar verir. Birçok otel pipeti, küçük şampuan şişesini ve plastik bardağı yeniden kullanılabilir ürünlerle değiştirir.","iliskili":["mg-4-007","mg-4-013","mg-4-023"],"kontrol":null,"gorsel":"mg-tek-kullanimlik-plastik"},{"id":"mg-4-028","konu":"4.2","terim":"Çevresel etki","ingilizce":"Environmental impact","tanim":"Bir faaliyetin, ürünün ya da işletmenin hava, su, toprak ve canlılar üzerinde yarattığı olumlu ya da olumsuz değişikliktir.","ornek":"Yeni açılan bir otel bölgeye iş getirir ama su tüketimini, atığı ve trafiği de artırır; bunların hepsi otelin çevresel etkisidir.","sektor":"Her mesleki faaliyetin havaya, suya ve toprağa bir etkisi vardır. Profesyonel çalışan “Bu işi yaparken çevreye ne bırakıyorum?” diye sorar ve olumsuz etkiyi küçültmenin yolunu arar.","iliskili":["mg-4-029","mg-4-031","mg-4-021"],"kontrol":null},{"id":"mg-4-029","konu":"4.2","terim":"Ekolojik ayak izi","ingilizce":"Ecological footprint","tanim":"Bir kişinin, işletmenin ya da toplumun tükettiği kaynakları üretmek ve çıkardığı atığı gidermek için doğadan ne kadar alana ihtiyaç duyduğunu gösteren ölçüdür.","ornek":"Her gün çarşaf değiştiren, bütün ışıkları açık bırakan ve yiyeceğini çok uzaklardan getirten bir otelin ekolojik ayak izi aynı büyüklükteki özenli bir otelinkinden daha büyüktür.","sektor":"Programın anahtar kavramlarındandır. Ayak izi ne kadar büyükse doğadan o kadar çok alınıyor demektir. İşletmeler su, enerji ve atık miktarını izleyerek ayak izini küçültmeye çalışır.","iliskili":["mg-4-028","mg-4-038","mg-4-056"],"kontrol":null},{"id":"mg-4-031","konu":"4.2","terim":"Mesleki sorumluluk","ingilizce":"Professional responsibility","tanim":"Bir meslek sahibinin, işini yaparken insanlara, topluma ve çevreye zarar vermeme ve işinin sonuçlarını sahiplenme yükümlülüğüdür.","ornek":"Kat görevlisi boş odadan çıkarken klimayı ve ışıkları kapatır, damlatan musluğu teknik servise bildirir; kimse söylemeden yapar.","sektor":"Programın anahtar kavramlarındandır. Çevreyi korumak mesleki kimliğin parçasıdır: iyi otelci yalnız konuğu değil, konuğun görmeye geldiği doğayı da gözetir. Masrafı kısmak için atık yönetimini ihmal etmek meslek etiğine aykırıdır.","iliskili":["mg-4-002","mg-4-028","mg-4-062"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-4-064","konu":"4.2","terim":"Ağır metaller","ingilizce":"Heavy metals","tanim":"Kurşun, cıva ve kadmiyum gibi yoğunluğu yüksek olan ve çevreye karıştıklarında canlıların vücudunda birikerek zehirleyici etki yapabilen metallerdir.","ornek":"Saat 16.00, otelin teknik servisinde bozuk floresan lambalar ve bitmiş piller normal çöpe atılmaz; içlerindeki cıva ve kadmiyum gibi metaller toprağa ve suya karışmasın diye ayrı toplanır.","sektor":"Otelde atık pil, floresan lamba ve boya kutuları tehlikeli atık olarak ayrı toplanır; ağır metal kirliliği yıllarca toprakta ve suda kalabilir.","iliskili":["mg-4-008","mg-4-009","mg-4-021"],"kontrol":null,"cizim":"uyari"},{"id":"mg-4-042","konu":"4.2","terim":"Sürdürülebilirlik","ingilizce":"Sustainability","tanim":"Bugünün ihtiyaçlarını karşılarken doğal kaynakları tüketmeden, gelecekte de aynı imkânların var olmasını sağlayacak biçimde yaşamak ve çalışmaktır.","ornek":"Bir balıkçı köyündeki pansiyon yalnız mevsiminde ve yasal boydaki balığı alır; böylece koyda gelecek yıl da balık olur, pansiyon da açık kalır.","sektor":"Programın anahtar kavramlarındandır. Sürdürülebilir olmayan süreç, kaynağını yenilenme hızından daha hızlı tüketen süreçtir. Otel için soru şudur: “Bu işi yirmi yıl sonra da aynı yerde, aynı güzellikle yapabilecek miyiz?”","iliskili":["mg-4-043","mg-4-044","mg-4-045"],"kontrol":null,"gorsel":"m3-as-solar-firmengebaude"},{"id":"mg-4-043","konu":"4.2","terim":"Sürdürülebilir kalkınma","ingilizce":"Sustainable development","tanim":"Bugünün ihtiyaçlarını, gelecek kuşakların kendi ihtiyaçlarını karşılama imkânını elinden almadan karşılayan kalkınma anlayışıdır.","ornek":"Bir ilçe turizmle büyümek ister; kıyıyı baştan sona betonla doldurmak yerine doğal alanları korur, yapılaşmayı sınırlar ve yerel halkı işin içine katar.","sektor":"Kalkınma, bir ülkenin ya da bölgenin ekonomik ve sosyal olarak gelişmesidir. Sürdürülebilir kalkınma, “büyüyelim ama yarını harcamadan büyüyelim” der; uluslararası kuruluşların ortak hedefidir.","iliskili":["mg-4-042","mg-4-044","mg-4-061"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-045","konu":"4.2","terim":"Turizmde sürdürülebilirlik","ingilizce":"Sustainable tourism","tanim":"Turizmin; çevre, kültür ve ekonomi arasındaki dengeyi gözeterek, doğal ve kültürel değerleri gelecek kuşaklara bırakacak biçimde yürütülmesidir.","ornek":"Bir doğa yürüyüşü rehberi grubunu işaretli patikadan çıkarmaz, çöplerin geri taşınmasını sağlar ve mola için köydeki aile işletmesini seçer.","sektor":"Genel Turizm dersinde “sürdürülebilir turizm” adıyla geçen kavramın kendisidir. Turizm, kendi kaynağını tüketebilen bir sektördür: konuğu çeken koy, kalabalık ve kirlilikle güzelliğini yitirebilir. Otelcinin, rehberin ve acentecinin görevi konuğa bu güzelliği bozmadan göstermek, yöre halkının da bundan kazanç sağlamasına katkıda bulunmaktır.","iliskili":["mg-4-042","mg-4-039","mg-4-046"],"kontrol":null},{"id":"mg-4-049","konu":"4.2","terim":"Önleyici ve düzeltici çözüm","ingilizce":"Preventive and corrective action","tanim":"Bir sorunun hiç ortaya çıkmaması için önceden alınan önlem ile ortaya çıkmış sorunu gidermek için sonradan yapılan işlemdir.","ornek":"Mutfak giderine yağ tutucu taktırmak ve personeli eğitmek önleyici; tıkanan gideri açtırmak düzeltici çözümdür.","sektor":"Önlemek, düzeltmekten hem ucuz hem temizdir. Çevre sorunlarında zarar çoğu zaman geri alınamaz; bu yüzden asıl hedef önleyici çözümdür.","iliskili":["mg-4-047","mg-4-048","mg-4-013"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-4-083","konu":"4.2","terim":"Atık oluşum süreci","ingilizce":"Waste generation process","tanim":"Üretim ve tüketimin hangi aşamasında, hangi faaliyetten atık çıktığını gösteren aşamalar bütünüdür.","ornek":"Saat 08.00, otel mutfağı: satın alma, depolama, hazırlık ve servis aşamalarının her birinde ayrı bir atık çıkar; çevre sorumlusu bunları tek tek not eder.","sektor":"Otel atığı yalnız çöp odasında oluşmaz: mal kabulde ambalaj, mutfakta fire, büfede tabakta kalan yemek, oda temizliğinde boş ürün kutusu ve yıkama suyu sürecin farklı aşamalarında ortaya çıkar. Atığı azaltmanın ilk yolu bu aşamaları sırayla görüp atığı doğduğu yerde yakalamaktır.","iliskili":["mg-4-004","mg-4-013","mg-4-090"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-084","konu":"4.2","terim":"Mikroplastik","ingilizce":"Microplastic","tanim":"Plastik atıkların zamanla küçük parçalara ayrılması sonucu oluşan; suya, toprağa ve besin zincirine karışabilen çok küçük plastik parçalarıdır.","ornek":"Yaz sonunda kıyıda bırakılan plastik şişeler dalgalarla ve güneşle parçalanır; ufak parçalar denizde balıkların yiyeceğine karışır.","sektor":"Kıyıdaki bir otel için mikroplastik plajdaki her plastik parçasıyla başlayan görünmez bir sorundur; pipet, bardak ve şişe kapağı denize ulaşmadan toplanırsa küçük parçalara ayrılmaz. Deniz ürünü sunan restoranlar için temiz deniz yalnız manzara değil, mutfağın hammaddesidir.","iliskili":["mg-4-024","mg-4-085"],"kontrol":null,"cizim":"mikrop"},{"id":"mg-4-085","konu":"4.2","terim":"Besin zinciri","ingilizce":"Food chain","tanim":"Canlıların birbirini yiyerek enerji ve besin aktardığı, halkalarla birbirine bağlı dizidir.","ornek":"Denize karışan zararlı madde önce küçük balığa, sonra onu yiyen büyük balığa ve en sonunda sofradaki konuğa kadar ulaşabilir.","sektor":"Otel mutfağı besin zincirinin son halkalarından biridir: yöreden alınan balık, sebze ve et o bölgenin suyuna ve toprağına bağlıdır. Bu yüzden atık suyu, kimyasalı ve plastiği doğaya karıştırmamak sonunda konuğun tabağına gelecek ürünü korumaktır.","iliskili":["mg-4-084","mg-4-023"],"kontrol":null,"cizim":"otel-bina"},{"id":"mg-4-086","konu":"4.2","terim":"Emisyon kontrolü","ingilizce":"Emission control","tanim":"Baca, egzoz ve üretim sürecinden havaya verilen zararlı gaz ve parçacıkların ölçülüp sınırlı tutulmasıdır.","ornek":"Saat 08.00, otelin kazan dairesinde teknik servis bacadan çıkan gazı ölçtürür ve kazanın bakımını yaptırır.","sektor":"Kazan ve jeneratör bacaları, mutfak bacası ve havalimanı transferini yapan servis araçlarının egzozu otelin emisyon kaynaklarıdır. Düzenli bakım ve ölçüm yaptırmak yalnız çevreyi değil, çalışanın soluduğu havayı ve komşu yerleşimin yaşam kalitesini de korumanın yoludur.","iliskili":["mg-4-022","mg-4-090"],"kontrol":null,"cizim":"kurallar-liste"},{"id":"mg-4-087","konu":"4.2","terim":"Atık su arıtma","ingilizce":"Wastewater treatment","tanim":"Kullanılmış suyun içindeki kirleticilerin, doğaya verilmeden önce temizlenmesidir.","ornek":"Kıyıdaki bir otelin atık suyu arıtma tesisinden geçirilir; temizlenmeden denize verilmez.","sektor":"Otel mutfağında yağ, arıtma sistemine ulaşmadan yağ tutucuyla ayrılır; gidere dökülen bir kova yağ bu ilk basamağı zorlar. Konuk arıtma sistemini görmez, ama yüzdüğü denizin temizliği de bu sistemin sağlıklı çalışmasına bağlıdır.","iliskili":["mg-4-023","mg-4-090"],"kontrol":null,"cizim":"cop-atik"},{"id":"mg-4-088","konu":"4.2","terim":"Kaynak tasarrufu","ingilizce":"Resource saving","tanim":"Su, enerji ve malzemeyi gereğinden fazla kullanmamak, harcamayı ölçülü tutmaktır.","ornek":"Otel çamaşırhanesi saat 10.00’da makineleri yarım değil tam dolu çalıştırarak su ve elektrikten tasarruf eder.","sektor":"Otelde tasarruf konuğa hizmetten kısmak demek değildir; boş salonun ışığını ve klimasını kapatmak, damlayan musluğu bildirmek, makineyi tam dolu çalıştırmak gibi konuğun fark etmediği alışkanlıklarla yapılır. Ay sonu su ve elektrik faturasındaki düşüş bu küçük alışkanlıkların toplamıdır.","iliskili":["mg-4-057","mg-4-056"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-4-089","konu":"4.2","terim":"Temiz üretim","ingilizce":"Cleaner production","tanim":"Üretimde daha az kaynak ve daha az zararlı madde kullanarak atığı ve kirliliği daha oluşmadan azaltma yaklaşımıdır.","ornek":"Bir otel çamaşırhanesi, yüksek kimyasal kullanan deterjanı bırakıp daha az kimyasallı bir ürüne geçer ve yıkama suyunu azaltan makine alır.","sektor":"Temiz üretim kirliliği oluştuktan sonra temizlemek yerine hiç oluşturmamaktır: otelde kat hizmetleri kimyasalı göz kararı dökmek yerine dozaj sistemiyle ölçülü kullanırsa kimyasalın kanalizasyona karışması da azalır. Önce kaynağa bakan bu yaklaşım sonradan temizlemekten genellikle daha ucuz ve daha kalıcı bir çözümdür.","iliskili":["mg-4-090","mg-4-013"],"kontrol":null,"cizim":"hijyen-damla"},{"id":"mg-4-090","konu":"4.2","terim":"Kirliliği kaynağında önleme","ingilizce":"Pollution prevention","tanim":"Kirlilik oluştuktan sonra temizlemek yerine, kirliliğin hiç oluşmaması için kaynağında önlem almaktır.","ornek":"Saat 09.00, otel mutfağında atık yağın lavaboya dökülmesini engellemek için gidere yağ tutucu takılır.","sektor":"Kirlilikle mücadelenin en etkili yoludur.","iliskili":["mg-4-089","mg-4-043"],"kontrol":null,"cizim":"festival"},{"id":"mg-4-091","konu":"4.2","terim":"İşletmenin çevresel sorumluluğu","ingilizce":"Corporate environmental responsibility","tanim":"Bir kuruluşun çevreye verdiği etkiyi azaltma, kaynakları verimli kullanma ve atığını doğru yönetme yükümlülüğüdür.","ornek":"Saat 10.00, bir otel yönetimi yıllık raporunda su ve enerji tüketimini, atık miktarını ve aldığı önlemleri açıklar.","sektor":"Otel, bulunduğu yörenin suyunu, havasını ve denizini kullandığı için bunları temiz bırakmak bir iyilik değil, işletmenin sorumluluğudur. Bu sorumluluk yönetim odasında değil mutfakta, katta ve bahçede yerine getirilir; atığı ayıran, kaçağı bildiren ve israf etmeyen her çalışan bu sorumluluğun ortağıdır.","iliskili":["mg-4-045","mg-4-089"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-4-092","konu":"4.2","terim":"Kavram haritası","ingilizce":"Concept map","tanim":"Kavramların aralarındaki ilişkileri oklar, kutular ve kısa bağlantı cümleleriyle gösteren şemadır.","ornek":"Öğrenci tahtaya “sürdürülebilirlik”i yazar; ona sıfır atık, geri dönüşüm ve ekolojik ayak izini oklarla bağlar.","sektor":"Su tüketimi arttığında bir otelin mutfağı, çamaşırhanesi, havuzu ve kat hizmetleri aynı sorunun parçalarıdır; bunları bir kavram haritasında oklarla bağlamak kimin neyi etkilediğini toplantıda herkese tek bakışta gösterir. Harita bilgiyi aralarındaki ilişkiyle birlikte görmeyi sağladığı için hem sınavda hem iş toplantısında işe yarayan bir araçtır.","iliskili":["mg-4-042","mg-4-020"],"kontrol":null,"cizim":"harita-rota"},{"id":"mg-4-032","konu":"4.3","terim":"Küresel çevre sorunları","ingilizce":"Global environmental problems","tanim":"Tek bir ülkeyle sınırlı kalmayan, bütün dünyayı etkileyen ve çözümü ülkelerin birlikte çalışmasını gerektiren çevre sorunlarıdır.","ornek":"İklim değişikliği, okyanuslardaki plastik kirliliği, ormanların azalması ve canlı türlerinin yok olması bu sorunların başlıcalarıdır.","sektor":"Turizm bu sorunlardan doğrudan etkilenir: kar yağmazsa kayak sezonu kısalır, orman yanarsa bölgeye konuk gelmez. Bu yüzden küresel sorun, otelin kapısına kadar gelen yerel bir sorundur.","iliskili":["mg-4-035","mg-4-036","mg-4-039"],"kontrol":null},{"id":"mg-4-033","konu":"4.3","terim":"Sera gazı","ingilizce":"Greenhouse gas","tanim":"Atmosferde ısıyı tutarak yeryüzünün ısınmasına yol açan karbondioksit ve metan gibi gazlardır.","ornek":"Otelin kazanında yakılan yakıt, konukları taşıyan otobüsün egzozu ve çöplükte çürüyen yemek artıkları atmosfere sera gazı verir.","sektor":"Karbondioksit en çok kömür, petrol ve doğal gaz yakıldığında; metan ise çöp alanlarında çürüyen organik atıklardan ve hayvancılıktan çıkar. Enerjiyi ve gıda israfını azaltmak bu gazları da azaltır.","iliskili":["mg-4-034","mg-4-037","mg-4-038"],"kontrol":null,"gorsel":"mg-sera-gazi-baca"},{"id":"mg-4-034","konu":"4.3","terim":"Sera etkisi","ingilizce":"Greenhouse effect","tanim":"Atmosferdeki bazı gazların güneşten gelen ısının bir bölümünü tutarak yeryüzünü sıcak tutması olayıdır.","ornek":"Güneşte bırakılmış kapalı bir arabanın içi dışarıdan çok daha sıcak olur; camlar ısıyı içeride tutar. Atmosferdeki sera gazları da buna benzer bir iş görür.","sektor":"Sera etkisi doğal ve gerekli bir olaydır; o olmasa dünya yaşanamayacak kadar soğuk olurdu. Sorun, insan faaliyetleriyle sera gazlarının artması ve tutulan ısının fazlalaşmasıdır.","iliskili":["mg-4-033","mg-4-035","mg-4-036"],"kontrol":null,"gorsel":"m3-small-greenhouse-with-grapevines-e"},{"id":"mg-4-035","konu":"4.3","terim":"Küresel ısınma","ingilizce":"Global warming","tanim":"Atmosferde sera gazlarının artması sonucu dünyanın ortalama sıcaklığının uzun yıllar içinde yükselmesidir.","ornek":"Bir kayak merkezinin yaşlı çalışanları anlatır: eskiden pistler daha erken açılırmış; şimdi kar daha geç yağıyor, yapay karlama makineleri daha çok çalışıyor.","sektor":"Küresel ısınma iklim değişikliğinin nedenidir; ikisi aynı şey değildir. Isınma sıcaklık artışını, iklim değişikliği bu artışın yağış, mevsim ve hava olaylarında yol açtığı değişmeleri anlatır.","iliskili":["mg-4-034","mg-4-036","mg-4-033"],"kontrol":null,"gorsel":"m3-perito-moreno-glacier-patagonia-ar"},{"id":"mg-4-036","konu":"4.3","terim":"İklim değişikliği","ingilizce":"Climate change","tanim":"Sıcaklık, yağış ve mevsimlerin uzun yıllar içinde alışılmış düzeninden kalıcı biçimde sapmasıdır.","ornek":"Kıyıdaki bir tatil beldesinde yazlar daha sıcak ve kurak geçmeye başlar; orman yangını riski artar, su kesintileri sıklaşır.","sektor":"Günümüzdeki değişikliğin başlıca nedeni insan faaliyetleridir: fosil yakıt kullanımı ve ormanların azalması. Kuraklık, sel, aşırı sıcak ve yangın turizm sezonunu, konuğun güvenliğini ve işletmenin gelirini doğrudan etkiler.","iliskili":["mg-4-035","mg-4-037","mg-4-040"],"kontrol":null,"gorsel":"m3-drought-land-dry-mud-bouhanifia-al"},{"id":"mg-4-037","konu":"4.3","terim":"Fosil yakıt","ingilizce":"Fossil fuel","tanim":"Milyonlarca yıl önce yaşamış canlıların kalıntılarından yer altında oluşan kömür, petrol ve doğal gaz gibi yakıtlardır.","ornek":"Otelin kazanında yanan doğal gaz, transfer aracının deposundaki motorin ve uçağın yakıtı fosil yakıttır.","sektor":"Yakıldıklarında havaya karbondioksit verirler ve yenilenemezler: tükenince yerine yenisi gelmez. Yeşil dönüşümün ana hedeflerinden biri bu yakıtlara bağımlılığı azaltmaktır.","iliskili":["mg-4-033","mg-4-041","mg-4-038"],"kontrol":null,"gorsel":"mg-fosil-yakit"},{"id":"mg-4-038","konu":"4.3","terim":"Karbon ayak izi","ingilizce":"Carbon footprint","tanim":"Bir kişinin, ürünün ya da işletmenin faaliyetleri yüzünden atmosfere verilen sera gazı miktarını gösteren ölçüdür.","ornek":"Bir tatilin karbon ayak izini yolculukta yakılan yakıt, odada harcanan elektrik ve sofraya gelen yiyeceğin kat ettiği yol birlikte oluşturur.","sektor":"Ekolojik ayak izinin yalnız sera gazlarıyla ilgili bölümüdür. Ulaşım, ısıtma-soğutma ve elektrik otelin karbon ayak izindeki büyük kalemlerdir; bazı işletmeler bunu hesaplar ve azaltma hedefi koyar.","iliskili":["mg-4-029","mg-4-033","mg-4-057"],"kontrol":null,"gorsel":"f3e-ucak-izi"},{"id":"mg-4-039","konu":"4.3","terim":"Biyoçeşitlilik kaybı","ingilizce":"Biodiversity loss","tanim":"Bir bölgedeki bitki, hayvan ve öteki canlı türlerinin sayısının ve çeşidinin azalmasıdır.","ornek":"Deniz kaplumbağalarının yumurta bıraktığı bir kumsalda gece boyunca güçlü ışıklar yanar ve şezlonglar toplanmazsa yavrular denize ulaşamaz.","sektor":"Canlı çeşitliliği doğa turizminin kaynağıdır: kuş gözlemcisi, dalgıç ve doğa yürüyüşçüsü onu görmeye gelir. Kıyıdaki işletmeler yuvalama alanlarında ışık, gürültü ve şezlong kurallarına uymakla yükümlüdür.","iliskili":["mg-4-027","mg-4-032","mg-4-045"],"kontrol":null},{"id":"mg-4-040","konu":"4.3","terim":"Yeşil dönüşüm","ingilizce":"Green transition","tanim":"Üretimin, enerjinin, ulaşımın ve tüketimin çevreye daha az zarar verecek, kaynakları daha verimli kullanacak biçimde yeniden düzenlenmesidir.","ornek":"Otel çatısına güneş paneli kurar, ampullerini tasarruflu olanlarla değiştirir, transfer için elektrikli araç alır ve atıklarını ayrı toplamaya başlar.","sektor":"Programın anahtar kavramlarındandır. Yalnız teknoloji değişimi değil, iş yapma biçiminin değişmesidir; her meslekte yeni bilgi ve beceri gerektirir. Çevreye duyarlı konuk ve tur şirketi, bu adımları atan işletmeyi tercih eder.","iliskili":["mg-4-041","mg-4-042","mg-4-046"],"kontrol":null,"gorsel":"mg-yesil-donusum"},{"id":"mg-4-041","konu":"4.3","terim":"Yenilenebilir enerji","ingilizce":"Renewable energy","tanim":"Güneş, rüzgâr, akarsu ve yer altı sıcaklığı gibi doğada kendini sürekli yenileyen kaynaklardan elde edilen enerjidir.","ornek":"Güney kıyılarındaki pek çok otelin çatısında güneş kolektörleri vardır; konukların duş suyu güneşle ısınır.","sektor":"Kullanırken sera gazı çıkarmaz ya da çok az çıkarır, kaynağı da tükenmez. Güneşi bol bir ülkede otel için hem çevreci hem uzun vadede ekonomik bir seçimdir.","iliskili":["mg-4-037","mg-4-040","mg-4-057"],"kontrol":null,"gorsel":"t13e-denizde-ruzgar-turbini"},{"id":"mg-4-046","konu":"4.3","terim":"Yeşil iş","ingilizce":"Green job","tanim":"Çevrenin korunmasına ya da iyileştirilmesine doğrudan katkı sağlayan ve insana yakışır çalışma koşulları sunan iştir.","ornek":"Büyük bir tatil köyünde çevre görevlisi çalışır: atık kayıtlarını tutar, personele eğitim verir, su ve enerji tüketimini izler.","sektor":"Sektörde “green job” denir. Yeşil dönüşüm bazı meslekleri değiştirir, yenilerini doğurur; çevre bilgisi olan aşçı, kat şefi ya da teknik personel iş başvurusunda bir adım öne geçer.","iliskili":["mg-4-040","mg-4-031","mg-4-045"],"kontrol":null,"kitapDisi":true,"gorsel":"m3-begutachtung-eines-rotorblattes"},{"id":"mg-4-093","konu":"4.3","terim":"Ormansızlaşma","ingilizce":"Deforestation","tanim":"Ormanların kesilme, yanma ya da yapılaşma nedeniyle azalması ve yok olmasıdır.","ornek":"Bir kıyı kasabasında yeni tatil sitesi için çam ormanı açılır; ağaçlar azalınca yağmur suyu toprağı tutamaz.","sektor":"Orman kıyısındaki bir otelin konuğa sattığı şeyler serin gölge, temiz hava ve yürüyüş yollarıdır; orman azaldıkça otelin çekiciliği de azalır. Bu yüzden ağaç kesmeden büyümek ya da yeni ağaç dikmek doğa turizmi yapan bir işletmenin kendi geleceğine yaptığı yatırımdır.","iliskili":["mg-4-039","mg-4-035"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-094","konu":"4.3","terim":"Diazot monoksit","ingilizce":"Nitrous oxide","tanim":"Atmosferde ısıyı tutan, karbondioksit ve metanla birlikte anılan bir sera gazıdır.","ornek":"Antalya’da bir seracı toprağa gereğinden fazla azotlu gübre atar; ziraat mühendisi fazla gübrenin topraktan havaya diazot monoksit olarak karıştığını söyleyip gübreyi ihtiyaç kadar kullanmasını önerir.","sektor":"Bu gazla ilgili en doğrudan karar otelin bahçesinde verilir: çime ve çiçeğe gereğinden fazla azotlu gübre verilirse fazlası topraktan havaya diazot monoksit olarak karışabilir. Bahçıvanın gübreyi ihtiyaç kadar kullanması hem masrafı hem sera gazı salımını azalttığı için küçük görünen bu karar da iklimle ilgilidir.","iliskili":["mg-4-033","mg-4-034"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-095","konu":"4.3","terim":"Aşırı hava olayları","ingilizce":"Extreme weather events","tanim":"Sel, fırtına, kuraklık, orman yangını ve aşırı sıcak gibi alışılmışın dışında şiddetli hava olaylarıdır.","ornek":"Temmuzda kıyı bölgesinde orman yangını çıkar; otel konukları tahliye edilir ve rezervasyonlar iptal olur.","sektor":"Fırtına uyarısı geldiğinde otelin teras mobilyaları, şemsiyeleri ve plaj ekipmanı toplanır; aşırı sıcakta ise havuz başındaki çocuklara ve yaşlı konuklara su ve gölge hatırlatılır. Bu olaylar arttıkça iptaller, tahliyeler ve onarım masrafları da artar; önceden hazırlanmış bir plan bu zararı küçültmenin en etkili yoludur.","iliskili":["mg-4-036","mg-4-035"],"kontrol":null,"cizim":"festival"},{"id":"mg-4-096","konu":"4.3","terim":"Su kıtlığı","ingilizce":"Water scarcity","tanim":"Bir bölgede su ihtiyacının eldeki su kaynaklarıyla karşılanamaz hâle gelmesidir.","ornek":"Yaz sonunda bir tatil beldesinde havuz ve bahçe sulaması kısıtlanır; otel suyu tankerle getirtmek zorunda kalır.","sektor":"Yazın nüfusun arttığı tatil beldelerinde su azaldığında otelin duş, çamaşırhane, mutfak, havuz ve bahçe sulaması gibi büyük su kalemleri bundan etkilenir. Damlayan musluğu ve kaçak boruyu hemen bildirmek suyu en kolay kurtaran davranış olduğundan her çalışanın görevidir.","iliskili":["mg-4-036","mg-4-023"],"kontrol":null,"cizim":"su-tasarrufu"},{"id":"mg-4-097","konu":"4.3","terim":"Gıda güvenliği","ingilizce":"Food security","tanim":"Herkesin her zaman yeterli, sağlıklı ve ulaşabileceği fiyatta gıdaya erişebilmesidir.","ornek":"Kuraklık yüzünden buğday verimi düşünce un ve ekmek pahalanır; otel mutfağı da maliyet artışını yaşar.","sektor":"Otel mutfağı bu sorunu önce tedarikte ve fiyatta hisseder: kuraklıkta un, sebze ve yağ pahalanır, bazı ürünler bulunamaz, menü planı değişir. Burada gıda güvenliği, mutfaktaki hijyen kuralları (food safety) değil, yeterli gıdaya ulaşabilmek (food security) anlamındadır.","iliskili":["mg-4-036","mg-4-095"],"kontrol":null,"cizim":"gastronomi"},{"id":"mg-4-098","konu":"4.3","terim":"Temiz enerji","ingilizce":"Clean energy","tanim":"Kullanılırken çevreye çok az zarar veren ya da hiç zarar vermeyen güneş ve rüzgâr gibi kaynaklardan elde edilen enerjidir.","ornek":"Bir otel çatısına güneş paneli kurar ve sıcak su ihtiyacının bir bölümünü buradan karşılar.","sektor":"Temiz enerji otelde en çok çatıdaki güneş sistemiyle görünür; konuk bunu fark edince “Sıcak su nereden geliyor?” diye sorabilir. Resepsiyon ve satış ekibi yalnız gerçeği söyler: sıcak suyun bir bölümü güneşten geliyorsa “bir bölümü” denir, “tamamı” denmez; abartılı söz yeşil yıkamadır.","iliskili":["mg-4-041","mg-4-040"],"kontrol":null,"cizim":"enerji"},{"id":"mg-4-099","konu":"4.3","terim":"Mesleki etik","ingilizce":"Professional ethics","tanim":"Bir mesleği yaparken doğru, dürüst ve topluma zarar vermeyecek biçimde davranmayı gerektiren ilkelerdir.","ornek":"Maliyeti düşürmek isteyen bir işletme atık yönetimini ihmal ederse çevreye zarar verir; mesleki etik bunu doğru bulmaz.","sektor":"Gece kapanışında kimse bakmıyorken atık yağı gidere dökmemek mesleki etiğin en sade örneğidir. Etik konuk ya da denetçi görsün diye değil, doğru olduğu için doğru davranmaktır.","iliskili":["mg-4-031","mg-4-091"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-4-027","konu":"4.4","terim":"Ekosistem","ingilizce":"Ecosystem","tanim":"Belirli bir alandaki canlıların birbirleriyle ve hava, su, toprak gibi cansız çevreleriyle kurduğu dengeli bütündür.","ornek":"Bir sulak alan: sazlıklar, balıklar, kuşlar, böcekler ve su birbirine bağlıdır; su kirlenince önce balık, sonra kuş azalır.","sektor":"Ekosistemde bir halka zarar görürse ötekiler de etkilenir. Programda sık geçen “ekosistemin dengesini gözetmek” sözü, bir işi yaparken doğadaki bu bağı hesaba katmak demektir.","iliskili":["mg-4-001","mg-4-039","mg-4-028"],"kontrol":null,"gorsel":"m3-coral-reef-plos"},{"id":"mg-4-065","konu":"4.4","terim":"Çevre bilinci","ingilizce":"Environmental awareness","tanim":"Kişinin çevreyi korumanın kendi sorumluluğu olduğunu bilmesi ve günlük davranışlarında bunu gözetmesidir.","ornek":"Saat 22.00, restoran mutfağında kapanış yapan stajyer, kimse denetlemese de cam ve plastiği ayrı kutulara koyar ve musluğu tam kapatır.","sektor":"Çevre bilinci olan personel, otelin su, enerji ve atık giderini kendiliğinden azaltır; konuk da bu özeni fark eder.","iliskili":["mg-4-002","mg-4-029","mg-4-012"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-047","konu":"4.4","terim":"Çevresel çözüm stratejisi","ingilizce":"Environmental action plan","tanim":"Bir çevre sorununu gidermek için nedenleri belirlenerek hazırlanan, adımları ve sorumluları belli olan eylem planıdır.","ornek":"Otel mutfağı çok ekmek attığını fark eder: nedenini araştırır, masalara küçük sepetle servise geçer, artanı galeta ununa çevirir ve sonucu bir ay boyunca tartarak izler.","sektor":"İyi bir çözüm üç ölçütü birlikte karşılar: sürdürülebilir olmalı, maliyeti karşılanabilmeli ve topluma yarar sağlamalıdır. Çözüm ayrıca yasalara ve meslek etiğine uygun olmalıdır.","iliskili":["mg-4-048","mg-4-049","mg-4-050"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-048","konu":"4.4","terim":"Çevre sorununda balık kılçığı analizi","ingilizce":"Fishbone analysis of an environmental problem","tanim":"Sorunu balığın başına, nedenlerini insan, malzeme, yöntem, makine ve ekipman, ortam ve yönetim kılçıklarına yazarak gösteren neden-sonuç şemasıdır.","ornek":"Saat 21.30, otel mutfağında şef balığın başına “Açık büfede çok yemek artıyor” yazar; kılçıkları insan (porsiyonu gözle ayarlayan personel), malzeme, yöntem, makine ve ekipman, ortam ve yönetim başlıklarına ayırır ve her başlığın altına nedenleri ekler.","sektor":"Sektörde “neden-sonuç diyagramı” da denir. Sorunun yalnız görünen sonucuna değil, asıl nedenine inmeyi sağlar; nedeni bulunmayan sorun, çözüldü sanılsa da geri gelir.","iliskili":["mg-4-047","mg-4-049","mg-4-058"],"kontrol":null,"cizim":"grafik"},{"id":"mg-4-050","konu":"4.4","terim":"Maliyet etkinliği","ingilizce":"Cost-effectiveness","tanim":"Bir çözümün, harcanan paraya ve emeğe değecek ölçüde yarar sağlamasıdır.","ornek":"Otel ampullerini tasarruflu olanlarla değiştirir: başta para harcar ama düşen elektrik faturası bu harcamayı zamanla geri kazandırır.","sektor":"Programda çözümleri karşılaştırma ölçütlerindendir; yanında “uygulanabilirlik” ve “ekolojik fayda” da sayılır. Çevreci çözüm pahalı olmak zorunda değildir: israfı kesen her adım aynı zamanda masrafı keser.","iliskili":["mg-4-047","mg-4-044","mg-4-056"],"kontrol":null},{"id":"mg-4-051","konu":"4.4","terim":"Çevre etiketi","ingilizce":"Eco-label","tanim":"Bir ürünün ya da işletmenin belirli çevre ölçütlerini karşıladığını gösteren, bağımsız bir kuruluşun denetim sonunda verdiği belge ya da işarettir.","ornek":"Bir plajın girişinde dalgalanan Mavi Bayrak, o plajın deniz suyu temizliği ve çevre yönetimi ölçütlerini karşıladığını gösterir.","sektor":"Sektörde “eco-label” denir. Konuk için güven işaretidir; işletmeye de tanıtımda üstünlük sağlar. Etiket bir kez alınıp unutulmaz: ölçütler sürdürülmezse geri alınır.","iliskili":["mg-4-052","mg-4-045","mg-4-047"],"kontrol":null,"kitapDisi":true,"cizim":"kalite-yildiz"},{"id":"mg-4-052","konu":"4.4","terim":"Yeşil yıkama","ingilizce":"Greenwashing","tanim":"Bir işletmenin, gerçekte yapmadığı ya da çok az yaptığı hâlde kendini çevreci gibi tanıtarak müşteriyi yanıltmasıdır.","ornek":"Bir işletme broşürüne “doğa dostu otel” yazar, yeşil yaprak resimleri koyar; ama atıklarını ayırmaz, atık suyunu arıtmaz.","sektor":"Sektörde “greenwashing” denir. Dürüstlük ilkesine aykırıdır ve fark edildiğinde güveni yıkar. Doğrusu, yapılanı olduğu kadar anlatmaktır: az ama gerçek bir adım, büyük ama boş bir sözden değerlidir.","iliskili":["mg-4-051","mg-4-031","mg-4-047"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"mg-4-060","konu":"4.4","terim":"Çevre mevzuatı","ingilizce":"Environmental legislation","tanim":"Çevrenin korunması için çıkarılan kanun, yönetmelik ve öteki yasal düzenlemelerin bütünüdür.","ornek":"Yeni açılan bir restoran atık yağını nasıl toplayacağını, atık suyunu nereye vereceğini ve çöpünü nasıl ayıracağını bu düzenlemelere bakarak öğrenir.","sektor":"Çevreyi korumak yalnız iyi niyet değil, yasal yükümlülüktür. İşletme kurallara uymazsa idari para cezası alabilir, hatta faaliyeti durdurulabilir. Çalışan olarak işletmenin atık talimatına uymak bu yükümlülüğün senin payına düşen kısmıdır.","iliskili":["mg-4-061","mg-4-062","mg-4-063"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-4-061","konu":"4.4","terim":"Çevre Kanunu","ingilizce":"Environment Law","tanim":"Türkiye’de çevrenin korunmasına ilişkin temel kuralları koyan 2872 sayılı kanundur.","ornek":"Atığını izinsiz biçimde doğaya bırakan ya da atık suyunu arıtmadan denize veren bir işletmeye bu kanuna göre yaptırım uygulanır.","sektor":"Kanun, bütün canlıların ortak varlığı olan çevrenin sürdürülebilir çevre ve sürdürülebilir kalkınma ilkeleri doğrultusunda korunmasını amaçlar. Çevreyi korumak herkesin görevidir; işletmeler de bu görevin içindedir.","iliskili":["mg-4-060","mg-4-062","mg-4-043"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-4-062","konu":"4.4","terim":"Kirleten öder ilkesi","ingilizce":"Polluter pays principle","tanim":"Çevreyi kirleten ya da bozan kişinin ve işletmenin, kirliliği önleme ve giderme masraflarını kendisinin karşılaması gerektiğini söyleyen ilkedir.","ornek":"Atık suyuyla dereyi kirleten bir tesis, derenin temizlenmesi için yapılan harcamayı ödemek zorunda kalır.","sektor":"Çevre Kanunu’nun temel ilkelerindendir. İşletmeye verdiği mesaj açıktır: kirliliği önlemek, sonradan bedelini ödemekten daha akılcıdır. Atık yönetimini “masraf” diye ihmal eden işletme sonunda daha fazlasını öder.","iliskili":["mg-4-061","mg-4-031","mg-4-049"],"kontrol":null,"gorsel":"m3-factory-in-azerbaijan-2008"},{"id":"mg-4-063","konu":"4.4","terim":"Sıfır Atık Yönetmeliği","ingilizce":"Zero Waste Regulation","tanim":"Türkiye’de atıkların kaynağında ayrı toplanmasına ve sıfır atık yönetim sisteminin kurulmasına ilişkin kuralları belirleyen yasal düzenlemedir.","ornek":"Bir otel sıfır atık sistemini kurarken sorumlu kişiyi belirler, ayrı toplama kutularını yerleştirir, personelini eğitir ve topladığı atıkları kayıt altına alır.","sektor":"Sistemini kuran işletmeler Sıfır Atık Belgesi için başvurabilir. Stajda göreceğin ayrı atık kutuları ve geçici depolama alanı yöneticinin kişisel tercihi değil, bu düzenlemenin gereğidir.","iliskili":["mg-4-020","mg-4-060","mg-4-016"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-101","konu":"4.4","terim":"Çevre sorunu analizi","ingilizce":"Environmental problem analysis","tanim":"Bir çevre sorununun kaynağını, nedenlerini, etkilediği çevre unsurunu ve doğaya verdiği zararı belirlemektir.","ornek":"Plajda sürekli biriken çöpün nedenini araştıran öğrenci, kovaların az olduğunu ve personelin saatlerini görür.","sektor":"Otelin su ya da atık faturası bir ay birden arttığında önce kaynağa bakılır: hangi bölümden, hangi saatte ve hangi nedenle? Çözüm bu sorular yanıtlanmadan seçilirse yanlış yere para harcanır; analiz doğru çözümün başlangıç noktasıdır.","iliskili":["mg-4-047","mg-4-048"],"kontrol":null,"cizim":"grafik"},{"id":"mg-4-102","konu":"4.4","terim":"Görüntü kirliliği","ingilizce":"Visual pollution","tanim":"Çevrede dağınık duran atık ve düzensiz yapıların doğal ve temiz görünümü bozmasıdır.","ornek":"Otelin arka bahçesinde yığılı duran eski mobilya ve boş kasalar yoldan geçenlere kötü görüntü verir.","sektor":"Giriş yolu, bahçe, plaj ve balkondan görünen alanlar konuğun ilk ve son izlenimini belirler; biriken kasa, eski mobilya ya da taşan çöp konteyneri bu izlenimi bozar. Böyle bir görüntü fotoğrafla çevrim içi yorumlara girdiğinde otelin temizlik iddiası da sorgulanır; depolama ve çöp alanlarının düzeni bu yüzden görüntü kirliliğine karşı ilk önlemdir.","iliskili":["mg-4-021","mg-4-101"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-104","konu":"4.4","terim":"Çözümün dört temel sütunu","ingilizce":"Four pillars of a solution strategy","tanim":"Çevre kirliliğine karşı strateji kurarken gözetilen yasal düzenlemeler, tüketici eğitimi, teknolojik inovasyon ve sıfır atık politikalarıdır.","ornek":"Bir belediye plastik kirliliğine karşı kural koyar, halka eğitim verir, akıllı çöp kutuları kurar ve ayrı toplamayı yaygınlaştırır.","sektor":"Aynı dört sütun otel ölçeğinde de kurulabilir: kurallara uyum, konuk ve personeli bilgilendirme, enerji izleme gibi teknolojik araçlar ve mutfaktan kata kadar sıfır atık hedefi. Biri eksik kalırsa çözüm yarım kalır; örneğin cihaz alınır, ama personele anlatılmazsa cihaz boşa durur, bu yüzden dört sütun birlikte düşünülmelidir.","iliskili":["mg-4-105","mg-4-106","mg-4-061"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-4-105","konu":"4.4","terim":"Tüketici eğitimi","ingilizce":"Consumer education","tanim":"Toplumun çevre bilincini artırmak, gereksiz tüketimden kaçınıp bez çanta ve tekrar kullanılabilir ürünleri seçtirmektir.","ornek":"Bir otel kahvaltı salonuna küçük kartlar koyarak konuklardan yemeği ihtiyaçları kadar almalarını ister.","sektor":"Konuk ağırlanan kişi olduğu için otelde bu eğitim ders vermek gibi değil, nazik bir davet gibi yapılır: banyodaki küçük bir kart, odadaki geri dönüşüm kutusu ya da resepsiyondaki kısa bir bilgi yeterlidir. Konuğa suçluluk hissettirmeden seçenek sunmak hizmet kalitesini koruyarak çevre davranışını yaygınlaştırmanın yoludur.","iliskili":["mg-4-104","mg-4-052"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-4-106","konu":"4.4","terim":"Teknolojik inovasyon","ingilizce":"Technological innovation","tanim":"Akıllı atık toplama, doluluk algılama sensörü, robotlu ayrıştırma ve temiz üretim gibi çevre dostu teknolojilerin kullanılmasıdır.","ornek":"Kalabalık bir tatil sitesi, dolan çöp konteynerlerini sensörle algılayıp çöp aracını yalnız gerektiğinde çağırır.","sektor":"Bazı otel mutfaklarında atılan yemeği tartıp kaydeden sistemler ya da boş odanın enerjisini kesen sensörler çevre sorununa teknolojiyle yaklaşmanın günlük örnekleridir. Teknoloji kendi başına çözüm değildir; onu kuran kadar kullanan personel de ne yaptığını bilmelidir.","iliskili":["mg-4-104","mg-4-089"],"kontrol":null,"cizim":"dijital"},{"id":"mg-4-107","konu":"4.4","terim":"Altı şapkalı düşünme","ingilizce":"Six Thinking Hats","tanim":"Bir fikri, altı renkli şapkayla gösterilen bakıştan (beyaz bilgi, kırmızı duygu, siyah risk, sarı yarar, yeşil yeni fikir, mavi karar) sırayla değerlendirme tekniğidir.","ornek":"Saat 11.00, otel yönetimi plastik pipeti kaldırma önerisini önce bilgiyle (beyaz), sonra riskle (siyah) ve sonunda karar planıyla (mavi) tartışır.","sektor":"Bir öneri, örneğin otel büfesindeki tabak boyutunu küçültmek, bölüm şefleri toplantısında herkesin aynı anda aynı şapkayla bakmasıyla değerlendirilirse tartışma karışmaz: önce bilgi, sonra yarar, risk ve yeni fikir sırayla konuşulur. Böylece “olmaz” diyenle “harika” diyen sırasını bekler ve toplantı karara ulaşır; tekniğin amacı budur.","iliskili":["mg-4-047","mg-4-104"],"kontrol":null,"cizim":"geri-donusum"},{"id":"mg-4-108","konu":"4.4","terim":"Çevre hakkı","ingilizce":"Right to a healthy environment","tanim":"Herkesin sağlıklı ve temiz bir çevrede yaşama hakkıdır; çevrenin korunması anayasal bir haktır.","ornek":"Bir mahalle sakini yakındaki tesisin atık suyundan şikâyet eder ve temiz bir çevrede yaşama hakkına dayanır.","sektor":"Otelin gece müziği, jeneratör sesi, kokusu ya da atık suyu çevrede yaşayanları rahatsız ederse onlar da temiz ve sağlıklı çevre hakkına dayanarak şikâyet edebilir. Yöre halkıyla iyi geçinen otel hem şikâyetten hem yasal sorundan uzak durur; çevre hakkı konuk kadar komşu için de geçerlidir.","iliskili":["mg-4-061"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-4-066","konu":"4.5","terim":"Ekolojik fayda","ingilizce":"Ecological benefit","tanim":"Bir çözümün doğaya, yani hava, su, toprak ve canlılara sağladığı olumlu katkıdır.","ornek":"Otelin çarşaf yıkamasını azaltması, daha az su ve deterjan kullanıldığı için akarsulara karışan kirliliği de azaltır.","sektor":"Çevresel bir çözüm yalnız ucuz olduğu için değil, doğaya sağladığı yarar gözetilerek de seçilir; maliyet etkinliği ile birlikte değerlendirilir.","iliskili":["mg-4-050","mg-4-047"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-053","konu":"4.5","terim":"Doğrusal ekonomi","ingilizce":"Linear economy","tanim":"Hammaddenin doğadan alındığı, ürüne dönüştürüldüğü ve kullanıldıktan sonra atıldığı “al, yap, at” düzenidir.","ornek":"Plastik bir su şişesi: petrolden üretilir, birkaç dakikada içilir ve çöpe gider; aynı yol her şişe için baştan başlar.","sektor":"Bu düzen iki uçtan sorun çıkarır: bir yanda kaynak tükenir, öte yanda atık birikir. Döngüsel ekonomi bu düz çizgiyi kapalı bir halkaya çevirmeyi önerir.","iliskili":["mg-4-054","mg-4-055","mg-4-030"],"kontrol":null},{"id":"mg-4-054","konu":"4.5","terim":"Döngüsel ekonomi","ingilizce":"Circular economy","tanim":"Ürünlerin ve malzemelerin olabildiğince uzun süre kullanıldığı, atığın yeniden hammaddeye dönüştürüldüğü ekonomi düzenidir.","ornek":"Otel eskiyen çarşaflarını atmaz: önce temizlik bezi yapar, bezler de yıprandığında tekstil geri dönüşümüne verir.","sektor":"Programın anahtar kavramlarındandır. Programda stratejileri 3R ile aynı sayılır: azalt, yeniden kullan, geri dönüştür. Bir işletmenin atığı başka bir işletmenin hammaddesi olabilir; döngü böyle kapanır.","iliskili":["mg-4-053","mg-4-012","mg-4-056"],"kontrol":null},{"id":"mg-4-055","konu":"4.5","terim":"Hammadde","ingilizce":"Raw material","tanim":"Bir ürünü üretmek için kullanılan, henüz işlenmemiş ya da az işlenmiş temel maddedir.","ornek":"Kâğıdın hammaddesi ağaçtan elde edilen selülozdur; atık kâğıt geri dönüştürüldüğünde yeni kâğıt için daha az ağaç kesilir.","sektor":"Geri kazanılan her atık, doğadan alınacak hammaddeyi azaltır. Programdaki “hammadde tasarrufu” sözü bunu anlatır: ayrı toplanan cam, kâğıt ve metal ekonomiye hammadde olarak geri döner.","iliskili":["mg-4-003","mg-4-015","mg-4-054"],"kontrol":null,"gorsel":"m3-braga-pedagogical-farm-algodao"},{"id":"mg-4-056","konu":"4.5","terim":"Kaynak verimliliği","ingilizce":"Resource efficiency","tanim":"Aynı işi daha az su, enerji ve malzeme harcayarak, kaliteyi düşürmeden yapabilmektir.","ornek":"Çamaşırhane, makineleri yarım değil tam dolu çalıştırır; aynı miktarda çamaşır daha az su, elektrik ve deterjanla yıkanır.","sektor":"Programın anahtar kavramlarındandır. Verimlilik kısıtlama demek değildir: konuk aynı temiz havluyu alır, işletme daha az kaynak harcar. Sayaçları düzenli okumak ve kaçağı hemen bildirmek ilk adımdır.","iliskili":["mg-4-057","mg-4-030","mg-4-003"],"kontrol":null},{"id":"mg-4-057","konu":"4.5","terim":"Enerji verimliliği","ingilizce":"Energy efficiency","tanim":"Aynı ısıtma, aydınlatma ya da çalışma sonucunu daha az enerji harcayarak elde etmektir.","ornek":"Konuk odadan çıkarken kartını yuvadan alır; odanın elektriği kendiliğinden kesilir, boş odada lamba ve klima çalışmaz.","sektor":"Enerji, otelin en büyük gider kalemlerindendir. Tasarruflu ampul, yalıtım, bakımlı klima ve kapalı tutulan kapı-pencere hem faturayı hem karbon ayak izini küçültür.","iliskili":["mg-4-056","mg-4-038","mg-4-041"],"kontrol":null,"cizim":"enerji"},{"id":"mg-4-058","konu":"4.5","terim":"Gıda israfı","ingilizce":"Food waste","tanim":"Yenebilecek durumdaki yiyeceğin fazla hazırlandığı, yanlış saklandığı ya da tabakta bırakıldığı için çöpe gitmesidir.","ornek":"Saat 21.30, açık büfe kapanıyor: tepsilerde dokunulmamış yemekler, masalarda yarısı yenmiş tabaklar kalmıştır.","sektor":"Çöpe giden yemekle birlikte onu üretmek için harcanan su, enerji, emek ve para da çöpe gider. Konuk sayısına göre planlama, küçük tepsiyle sık yenileme ve doğru saklama mutfağın başlıca önlemleridir.","iliskili":["mg-4-030","mg-4-006","mg-4-048"],"kontrol":null,"cizim":"gastronomi"},{"id":"mg-4-059","konu":"4.5","terim":"İleri dönüşüm","ingilizce":"Upcycling","tanim":"Atılacak bir ürünün ya da malzemenin, yaratıcı bir tasarımla daha değerli ve yeni bir kullanıma kavuşturulmasıdır.","ornek":"Butik bir otel, eski ahşap paletleri zımparalayıp boyar ve bahçesine oturma köşesi yapar; boş cam şişeleri masa lambasına çevirir.","sektor":"Sektörde “upcycling” denir. Geri dönüşümden farkı, malzemenin fabrikada hammaddeye çevrilmeden yeni bir ürüne dönüşmesidir. Konuğun dikkatini çeken, otelin hikâyesine değer katan bir uygulamadır.","iliskili":["mg-4-014","mg-4-015","mg-4-054"],"kontrol":null,"kitapDisi":true,"gorsel":"m3-europaletten-sitzbank-in-raabs-ad"},{"id":"mg-4-109","konu":"4.5","terim":"Uygulanabilirlik","ingilizce":"Feasibility","tanim":"Bir çözümün işletmede eldeki imkânlarla gerçekten hayata geçirilebilmesidir.","ornek":"Küçük bir pansiyon, pahalı bir atık ayrıştırma makinesi yerine ayrı kutu koymayı seçer; çünkü kutu uygulanabilirdir.","sektor":"Otel mutfağına kompost makinesi almadan önce yerinin, elektriğinin ve bakımını yapacak kişinin olup olmadığına bakılır; biri eksikse çözüm kâğıt üzerinde güzel görünse de uygulamada işlemez. Uygulanabilirlik fikri hayata geçirecek imkânları baştan sorgulamaktır.","iliskili":["mg-4-050","mg-4-104"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-110","konu":"4.5","terim":"Problem yapılandırma","ingilizce":"Problem structuring","tanim":"Bir sorunun özelliklerini, sınırlarını, risklerini ve kimleri etkilediğini sistemli biçimde belirleyerek çözüme hazır hâle getirmektir.","ornek":"Otelin çamaşırhanesinde “çok su harcanıyor” sorunu; hangi makine, hangi vardiya ve hangi maliyet olduğu yazılarak netleştirilir.","sektor":"“Kahvaltıda çok yemek çöpe gidiyor” cümlesi bir otel için henüz bir sorun tanımı değildir. Hangi ürünün, hangi saatte ve kaç konuğa göre hazırlandığında çöpe gittiği yazılınca sorun çözüme hazır hâle gelir; bu yüzden iyi yapılandırılmış sorun yarı yarıya çözülmüştür.","iliskili":["mg-4-101","mg-4-047"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-111","konu":"4.5","terim":"Onarım","ingilizce":"Repair","tanim":"Bozulan ya da eskiyen ürünü atmak yerine tamir edip kullanım ömrünü uzatmaktır.","ornek":"Saat 15.00, otelin teknik servisi kırılan sandalye ayağını yapıştırıp sandalyeyi yeniden kullanıma verir.","sektor":"Ders kitabı ve program döngüsel ekonomi stratejilerini üç adımda verir (azalt, yeniden kullan, geri dönüştür); uluslararası literatürde bu liste genişletilir ve onarım da bunlardan biri sayılır.","iliskili":["mg-4-014","mg-4-054"],"kontrol":null,"cizim":"doga"},{"id":"mg-4-112","konu":"4.5","terim":"Ürün yaşam döngüsü","ingilizce":"Product life cycle","tanim":"Bir ürünün hammaddesinin alınmasından üretimine, kullanımına ve kullanım sonrası akıbetine kadar geçirdiği aşamaların bütünüdür.","ornek":"Bir plastik şişenin hikâyesi: petrolden üretim, doldurma, taşıma, içme ve sonunda geri dönüşüm ya da çöp.","sektor":"Bir otelin satın alma sorumlusu iki havludan ucuz olanını seçmeden önce kaç yıkamaya dayanacağına ve ömrü bitince ne olacağına da bakar; çünkü ürünün etkisi satın alındığı anla bitmez. Üretimden atılışa kadar bütün aşamaları hesaba katmak yaşam döngüsü düşüncesidir.","iliskili":["mg-4-054","mg-4-059"],"kontrol":null,"cizim":"saglik-kalp"}],"sorular":[{"id":"mg-4-s01","tur":"coktan-secmeli","soru":"Otel yönetimi, kahvaltıda artan tek kullanımlık reçel paketleri sorununu atık hiyerarşisine göre çözecek. Önce hangi soruyu sormalıdır?","secenekler":["Bu paketleri hangi geri dönüşüm kutusuna atacağız?","Bu paketleri kullanmadan işi nasıl yürütebiliriz?","Bu paketleri yıkayıp tekrar kullanabilir miyiz?","Bu paketleri hangi bertaraf alanına göndereceğiz?"],"dogru":1,"aciklama":"Hiyerarşide önce atığın hiç oluşmaması denenir; paketi kaldırmak atığı kaynağında bitirir. Geri dönüşüm ve yeniden kullanım sonraki basamaklardır, bertaraf en sondur."},{"id":"mg-4-s02","tur":"coktan-secmeli","soru":"Aşağıdaki atık yağ uygulamalarından hangisi yanlıştır?","secenekler":["Soğuyan yağı ağzı kapaklı bidona süzmek","Dolan bidonu yetkili toplayıcıya vermek","Az miktardaki yağı bol deterjanla lavaboya dökmek","Yağı başka atıklarla karıştırmadan ayrı biriktirmek"],"dogru":2,"aciklama":"Yağ lavaboya dökülürse borularda birikip gideri tıkar ve suyu kirletir; miktarın az olması bunu değiştirmez. Öbür üç uygulama atık yağın özel toplama kuralına uyar."},{"id":"mg-4-s03","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi içindeki zehirli madde yüzünden ayrı toplanması gereken tehlikeli atıktır?","secenekler":["Kullanım ömrü dolan floresan lamba","Boşalan konserve kutusu","Yağa bulaşmış kâğıt peçete","Soyulan sebze kabukları"],"dogru":0,"aciklama":"Floresan lambanın içindeki zararlı maddeler toprağa ve suya karışabilir, bu yüzden özel kutuda toplanır. Konserve kutusu metal atık, sebze kabuğu organik atıktır; yağlı peçete ise geri kazanılamayan çöptür."},{"id":"mg-4-s04","tur":"coktan-secmeli","soru":"Kat görevlisi arabasındaki ayrı torbalara kâğıdı, plastiği ve kalan çöpü ayrı koyuyor. Atığı oluştuğu anda ayırmanın en önemli yararı hangisidir?","secenekler":["Toplama ve taşıma masrafı tamamen ortadan kalkar.","Yemek artığı bulaşmadığı için kâğıt ve plastik geri dönüştürülebilir kalır.","Geri dönüşüm firmaları atığı ücret almadan teslim alır.","Tehlikeli atık da normal çöp sayılarak aynı torbaya konabilir."],"dogru":1,"aciklama":"Atık karışmadan ayrılırsa temiz kalır ve geri dönüşüme girebilir; yemek artığına bulaşıp karışan kâğıt ve plastik çöpe dönüşür. Ayırma masrafı sıfırlamaz, tehlikeli atığın özel toplanma kuralını da değiştirmez."},{"id":"mg-4-s05","tur":"dogru-yanlis","soru":"3R ilkesine göre kullanılabilir durumdaki bir cam kavanozu yıkayıp yeniden doldurmak, kırıp geri dönüşüm kutusuna atmaktan önce gelen çözümdür.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Sıra azalt, yeniden kullan, geri dönüştür biçimindedir. Yeniden kullanımda ürün hiç işlenmeden iş görmeye devam eder; geri dönüşüm ise ek enerji ve işlem gerektirir."},{"id":"mg-4-s06","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi geri dönüşüme değil, yeniden kullanıma örnektir?","secenekler":["Boş şişelerin tesiste eritilip yeni şişe yapılması","Odalardaki cam sürahinin yıkanıp tekrar doldurulması","Atık kâğıdın işlenip yeni kâğıda dönüşmesi","Sebze kabuklarının çürütülüp gübre elde edilmesi"],"dogru":1,"aciklama":"Yeniden kullanımda ürün şeklini değiştirmeden aynı iş için tekrar kullanılır. Şişenin eritilmesi ve kâğıdın yeniden işlenmesi geri dönüşüm, kabukların gübreye dönüşmesi ise kompostlamadır."},{"id":"mg-4-s07","tur":"coktan-secmeli","soru":"Hangi otel sıfır atık yaklaşımını en eksiksiz uygulamaktadır?","secenekler":["Her alana ayrı kutu koyan, personeli eğiten ve toplanan atığı kaydeden otel","Atığı tek noktada toplayıp günde bir kez belediyeye teslim eden otel","Yalnız kâğıt ve camı ayırıp kalan atığı tek torbada atan otel","Tek kullanımlık ürünleri azaltıp oluşan atığı ayırmadan atan otel"],"dogru":0,"aciklama":"Sıfır atık hem atığı azaltmayı hem oluşanı kaynağında ayrı toplayıp yeniden değerlendirmeyi kapsar. Kısmi ayırma ya da yalnız azaltma, yaklaşımın bir yarısını eksik bırakır."},{"id":"mg-4-s08","tur":"coktan-secmeli","soru":"Bir otel bütün ışıkları açık bırakıyor ve yiyeceğini çok uzaktan getirtiyor. Tükettiği kaynakları üretmek ve atığını gidermek için doğadan ne kadar alana gerek olduğunu hangi kavram gösterir?","secenekler":["Karbon ayak izi","Çevresel etki","Geri kazanım potansiyeli","Ekolojik ayak izi"],"dogru":3,"aciklama":"Ekolojik ayak izi, tüketilen kaynak ve çıkan atık için gereken doğal alanı ölçer. Karbon ayak izi yalnız atmosfere verilen sera gazına bakar; çevresel etki ise olumlu ya da olumsuz her değişikliği anlatır, alan ölçmez."},{"id":"mg-4-s09","tur":"coktan-secmeli","soru":"Aşağıdaki davranışlardan hangisi çevre konusundaki mesleki sorumlulukla bağdaşmaz?","secenekler":["Boş odadan çıkarken klimayı ve ışıkları kapatmak","Kapanışta atıkları kimse bakmasa da ayrı kutulara koymak","Atık ayırmayı yalnız çevre görevlisinin işi saymak","Boş salonda açık kalmış ışığı söylenmeden kapatmak"],"dogru":2,"aciklama":"Mesleki sorumluluk, her çalışanın işini yaparken çevreye zarar vermemesini ve sonucunu sahiplenmesini gerektirir. Atık ayırma sadece bir görevliye bırakılırsa atığın oluştuğu yerde kimse sorumluluk almaz."},{"id":"mg-4-s10","tur":"dogru-yanlis","soru":"Atmosferde sera gazları arttıkça tutulan ısı da artar; küresel ısınma bu artışın sonucudur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Karbondioksit ve metan gibi sera gazları güneşten gelen ısının bir bölümünü tutar. Gaz miktarı arttıkça daha fazla ısı tutulur ve dünyanın ortalama sıcaklığı uzun yıllar içinde yükselir."},{"id":"mg-4-s11","tur":"coktan-secmeli","soru":"Bir otel, ısıtma için yaktığı doğal gaz gibi fosil yakıtların kullanımını azaltmak istiyor. Hangi adım bunu doğrudan sağlar?","secenekler":["Çatıya güneş kolektörü kurup sıcak suyu güneşle ısıtmak","Bacadan çıkan gazı düzenli olarak ölçtürmek","Kâğıt ve cam atığını ayrı toplamak","Atık yağı ağzı kapaklı bidonda biriktirmek"],"dogru":0,"aciklama":"Güneş kolektörü, yakılacak doğal gazın yerini yenilenebilir enerjiye bırakır. Baca gazını ölçtürmek yalnız çıkan gazı sınırlı tutar, yakıt tüketimini azaltmaz; atık ayırma ve atık yağ toplama ise atık yönetimi uygulamalarıdır."},{"id":"mg-4-s12","tur":"coktan-secmeli","soru":"Bir işletme, faaliyetleri yüzünden atmosfere verdiği sera gazı miktarını belirlemek istiyor. Hangi ölçüyü kullanır?","secenekler":["Ekolojik ayak izi","Karbon ayak izi","Geri kazanım potansiyeli","Çevresel etki"],"dogru":1,"aciklama":"Karbon ayak izi, bir kişinin, ürünün ya da işletmenin atmosfere verdiği sera gazı miktarını gösterir. Ekolojik ayak izi ise tüketimin ve atığın gerektirdiği toplam doğal alanı ölçer."},{"id":"mg-4-s13","tur":"coktan-secmeli","soru":"Bir otel enerjisini yenilenebilir kaynaklardan karşılamak istiyor. Aşağıdakilerden hangisi bu amaca uymaz?","secenekler":["Çatıya güneş paneli kurmak","Duş suyunu güneş kolektörüyle ısıtmak","Kazanı kömürle çalıştırmak","Yer altı sıcaklığından yararlanmak"],"dogru":2,"aciklama":"Kömür bir fosil yakıttır; tükenince yerine yenisi gelmez ve yanarken sera gazı çıkarır. Güneş ve yer altı sıcaklığı doğada kendini sürekli yeniler."},{"id":"mg-4-s14","tur":"coktan-secmeli","soru":"Bir ilçe turizmle büyümek istiyor. Hangi plan sürdürülebilir kalkınmaya en uygundur?","secenekler":["Kıyıyı yapılaşmaya açıp en kısa sürede çok yatak kurmak","Doğal alanları korumak, yapılaşmayı sınırlamak ve yerel halkı işe katmak","Çevre zarar görmesin diye bölgeye hiçbir turizm yatırımı yapmamak","Maliyet düşsün diye personeli bölge dışından getirmek"],"dogru":1,"aciklama":"Sürdürülebilir kalkınma bugünün ihtiyacını karşılarken gelecek kuşakların imkânını tüketmez; bu planda çevresel, ekonomik ve sosyal yönler birlikte gözetilir. Hiç yatırım yapmamak gelişmeyi tümüyle durdurur, bölge dışından personel getirmek yerel halkı dışarıda bırakır."},{"id":"mg-4-s15","tur":"dogru-yanlis","soru":"Doğal kaynaklara zarar vermeden kâr eden bir işletme, çalışanlarına adil davranmasa bile sürdürülebilirliğin üç boyutunu karşılamış sayılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sürdürülebilirlik çevresel, ekonomik ve sosyal boyutların birlikte gözetilmesini ister. Çalışanına adil davranmayan işletme sosyal boyutu eksik bıraktığı için sürdürülebilir sayılmaz."},{"id":"mg-4-s16","tur":"coktan-secmeli","soru":"Bir otel çalışanına adil davranıyor ve kâr ederek ayakta kalıyor. Bu iki davranış sırasıyla sürdürülebilirliğin hangi boyutlarına örnektir?","secenekler":["Sosyal – ekonomik","Ekonomik – sosyal","Çevresel – ekonomik","Sosyal – çevresel"],"dogru":0,"aciklama":"Çalışana ve bölge halkına adil davranmak sosyal, kâr edip ayakta kalmak ekonomik boyuttur. Çevresel boyut ise suyu, enerjiyi ve doğal alanı korumakla ilgilidir."},{"id":"mg-4-s17","tur":"coktan-secmeli","soru":"Bir işletme broşüründe kendini “doğa dostu” diye tanıtıyor ama atıklarını ayırmıyor, atık suyunu arıtmıyor. Bu duruma ne ad verilir?","secenekler":["Çevre etiketi","Yeşil yıkama","Yeşil dönüşüm","Çevre mevzuatı"],"dogru":1,"aciklama":"Yeşil yıkama, gerçekte yapılmayan çevrecilik iddiasıyla müşteriyi yanıltmaktır. Çevre etiketi ise ölçütleri karşılayan işletmeye bağımsız bir kuruluşun denetim sonunda verdiği belgedir; yalnız broşürde yazılan söz etiket sayılmaz."},{"id":"mg-4-s18","tur":"coktan-secmeli","soru":"Şef, “açık büfede çok yemek artıyor” sorununun nedenlerini insan, malzeme, yöntem, makine ve ekipman, ortam ve yönetim başlıkları altında arıyor. Hangi aracı kullanıyordur?","secenekler":["Kavram haritası","Saha gözlemi","Balık kılçığı analizi","Altı şapkalı düşünme"],"dogru":2,"aciklama":"Balık kılçığı, sorunu balığın başına, nedenlerini başlıklara göre kılçıklara yazan neden-sonuç şemasıdır. Altı şapka ise bir fikre altı farklı bakıştan bakar; neden aramaz, değerlendirir."},{"id":"mg-4-s19","tur":"coktan-secmeli","soru":"Otel, eskiyen çarşaflarını önce temizlik bezi yapıyor, bezler de yıprandığında tekstil geri dönüşümüne veriyor. Bu uygulama hangi anlayışa uyar?","secenekler":["Doğrusal ekonomi","Temiz üretim","Kaynağında ayrıştırma","Döngüsel ekonomi"],"dogru":3,"aciklama":"Döngüsel ekonomide ürün olabildiğince uzun kullanılır, sonunda atık yeniden hammaddeye dönüşür. Doğrusal ekonomi ise al, yap, at düzenidir; ürün kullanıldıktan sonra doğrudan çöpe gider."},{"id":"mg-4-s20","tur":"dogru-yanlis","soru":"“Kirleten öder” ilkesine göre çevreyi kirleten işletmenin kirliliği giderme masrafını devlet bütçesi, yani toplum karşılar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İlke tam tersini söyler: kirliliği önleme ve giderme masrafı kirleten kişiye ya da işletmeye aittir. Bedelin topluma yüklenmesi kirletmeyi ucuzlatır, bu yüzden kirliliği baştan önlemek işletmeye de daha ucuza gelir."},{"id":"mg-4-s21","tur":"senaryo","durum":"Restoran mutfağında stajdasın. Saat 23.00, kapanış temizliği yapılıyor. Fritözdeki kullanılmış yağı boşaltma işi sana verildi; yanındaki komi “Sıcak suyla lavaboya dök, en hızlısı bu” diyor.","soru":"Ne yaparsın?","secenekler":["Soğuyan yağı atık yağ bidonuna süzerim.","Yağı borulara yapışmasın diye sıcak suyla az az lavaboya dökerim.","Yağı kalın bir poşete doldurup yemek artığı kovasına atarım.","Yağı iz kalmasın diye arka bahçede toprağa dökerim."],"dogru":0,"aciklama":"Bitkisel atık yağ gidere dökülmez; boruları tıkar ve suyu kirletir. Çöpe ya da toprağa karışması da kirliliktir; doğru yol yağı ayrı biriktirip yetkili toplayıcıya vermektir."},{"id":"mg-4-s22","tur":"senaryo","durum":"Kat hizmetlerinde stajdasın. Saat 11.00, konuğun kaldığı odaya giriyorsun. Banyoda havlular düzgünce askıya asılmış; aynadaki kartta “Havlunuzu yeniden kullanmak isterseniz askıya asınız” yazıyor. Araban temiz havluyla dolu.","soru":"Hangisi doğru davranıştır?","secenekler":["Konuk memnun kalsın diye bütün havluları yenisiyle değiştiririm.","Askıdaki havluları değiştirmez, yalnız düzeltirim.","Havlulardan yalnız birini değiştirir, ötekileri askıda bırakırım.","Havluları değiştirir, kat şefi sorarsa kartı görmediğimi söylerim."],"dogru":1,"aciklama":"Konuk kartla havlusunu yeniden kullanmak istediğini bildirmiştir. Değiştirmek su, enerji ve deterjanı boşa harcar ve tercihini yok sayar; azaltma 3R’nin ilk adımıdır ve konforu eksiltmez."},{"id":"mg-4-s23","tur":"senaryo","durum":"Tatil köyünün ana restoranında stajdasın. Bir haftadır her akşam 21.30’da büfe kapanırken aynı iki yemeğin tepsilerinin neredeyse dokunulmadan çöpe gittiğini görüyorsun.","soru":"Ne yaparsın?","secenekler":["Menü benim işim değil; servisime devam ederim.","Ertesi akşam o iki yemeği sormadan büfeye çıkarmam.","Gözlemimi şefe anlatır, tepsileri küçültmeyi öneririm.","Artan yemekleri izin almadan paketleyip eve götürürüm."],"dogru":2,"aciklama":"Gıda israfında yemekle birlikte su, enerji ve emek de çöpe gider; gözleyen çalışan bunu amirine iletir. Menüyü kendi başına değiştirmek ya da yemek götürmek yetkisiz davranıştır, görmezden gelmek ise mesleki sorumluluğa uymaz."},{"id":"mg-4-s24","tur":"senaryo","durum":"Otelin teknik servisinde stajdasın. Saat 16.00, depo toplanıyor. Bir kolinin içinde bozuk floresan lambalar ve bir avuç bitmiş pil buluyorsun. En yakın çöp konteyneri kapının hemen önünde.","soru":"İlk adımın ne olur?","secenekler":["Koliyi kapının önündeki çöp konteynerine atarım.","Lambaları kırıp küçültür, pillerle çöp torbasına koyarım.","Koliyi deponun en arka rafına iter, sonraya bırakırım.","Bunları ayrı tutar, teslim yerini teknik şefe sorarım."],"dogru":3,"aciklama":"Floresan lamba ve atık pil zararlı madde içerir; çöpe karışırsa toprağı ve suyu kirletir. Lambayı kırmak ayrıca sağlığın için tehlikelidir; bu atıklar ayrı toplanıp yetkili firmaya verilir."},{"id":"mg-4-s25","tur":"senaryo","durum":"Bir seyahat acentesinde stajdasın. Saat 10.15, tur programını yazıcıdan çıkarırken yanlış dosyayı gönderdiğini fark ediyorsun: tek yüzü basılı bir tomar kâğıt çıkmış.","soru":"Ne yaparsın?","secenekler":["Boş yüzlerini müsvedde yapar, sonra kâğıt kutusuna atarım.","Bütün kâğıtları hemen genel çöp kovasına atarım.","Bütün kâğıtları plastik atık kutusuna atarım.","Bütün kâğıtları parçalama makinesinden geçirip genel çöpe atarım."],"dogru":0,"aciklama":"3R sırası azalt, yeniden kullan, geri dönüştür biçimindedir: boş yüzü müsvedde olarak kullanmak yeniden kullanımdır, ardından kutuya atmak geri dönüşümdür. Kâğıdı plastik kutusuna atmak geri dönüşümü bozar; genel çöpe giden kâğıt da hammaddeye dönemez."},{"id":"mg-4-s26","tur":"senaryo","durum":"Sahil otelinin plaj barında stajdasın. Saat 17.30, rüzgâr çıkıyor; şezlongların yanındaki ağzına kadar dolu kovadan plastik bardaklar ve pipetler kuma, oradan denize doğru uçuşuyor.","soru":"Nasıl davranırsın?","secenekler":["Plaj temizliği sabah yapılıyor; işime devam ederim.","Uçanları toplar, kovayı boşaltır, kovanın yetmediğini şefe bildiririm.","Kovanın ağzını kapatıp toplamayı sabaha bırakırım.","Yakındaki konuklardan kendi bardaklarını toplamalarını isterim."],"dogru":1,"aciklama":"Denize ulaşan plastik uzun süre yok olmaz ve deniz canlılarına zarar verir. Önce kirliliği durdurursun (düzeltici), sonra kovanın yetmediğini bildirirsin (önleyici). Toplamayı sabaha bırakmak plastiğin denize ulaşmasına yol açar."},{"id":"mg-4-s27","tur":"senaryo","durum":"Otelin mutfağında stajdasın. Saat 15.00, gün sonu atıklarını arka avluya taşıyacaksın. Cam ve plastik kutuları dolmuş. Yanındaki stajyer “Hepsini tek torbaya dolduralım, kimse bakmıyor, erken çıkarız” diyor.","soru":"Ne yaparsın?","secenekler":["Bu seferlik tek torbaya doldurur, yarın ayırmaya başlarım.","Karışmam; sorulursa haberim olmadığını söylerim.","Atıkları ayrı torbalarla taşır, kutuların dolduğunu amirime bildiririm.","Dolu kutuları yerinde bırakır, taşımayı sonraki vardiyaya devrederim."],"dogru":2,"aciklama":"Karışan atık sonradan kolay ayrılmaz ve gün boyu verilen emek boşa gider. Mesleki sorumluluk kimse bakmıyorken de geçerlidir; kutuların dolması ise amire iletilecek bir sorundur."},{"id":"mg-4-s28","tur":"senaryo","durum":"Otelin mutfağında stajdasın. Saat 14.00, mutfak gideri yağ yüzünden bu ay üçüncü kez tıkandı ve her seferinde tamirci çağrıldı. Şef “Bunu kalıcı çözmek için önerisi olan var mı?” diye soruyor.","soru":"Ne önerirsin?","secenekler":["Gider tıkandıkça tamirci çağırmaya devam etmeyi öneririm.","Mutfak ekibine tıkanıklığı açacak özel bir alet almayı öneririm.","Gidere her gün bol kimyasal temizleyici dökmeyi öneririm.","Gidere yağ tutucu taktırıp ekibe yağ eğitimi vermeyi öneririm."],"dogru":3,"aciklama":"Önleyici çözüm, sorun ortaya çıkmadan alınan önlemdir; yağ tutucu ve eğitim tıkanıklığı baştan engeller. Tamirci çağırmak ve aletle açmak sonradan yapılan düzeltici çözümdür; kimyasal dökmek de gideri açmaz, suyu daha çok kirletir."},{"id":"mg-4-s29","tur":"coktan-secmeli","soru":"Geri kazanım ile geri dönüşüm arasındaki ilişki için hangisi doğrudur?","secenekler":["Geri kazanım, geri dönüşümün yalnızca bir alt basamağıdır.","İkisi aynı işlemin iki farklı adıdır.","Geri dönüşüm, geri kazanım yollarından yalnızca biridir.","Kompost geri kazanım sayılmaz, yalnız geri dönüşüm sayılır."],"dogru":2,"aciklama":"Geri kazanım daha geniş bir kavramdır; geri dönüşüm, kompost ve enerji elde etme onun yollarıdır. İlişkiyi tersine çeviren şık bu yüzden yanlıştır."},{"id":"mg-4-s30","tur":"dogru-yanlis","soru":"Yemek artığına bulaşıp birbirine karışmış kâğıt ve plastikler geri kazanılamayacak hâle geldiği için artık çöp sayılır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru ayrılan atık değer taşır; karışıp kirlenen ve geri kazanılamayan atık ise çöpe dönüşür. Atıkla çöp bu yüzden aynı şey değildir."},{"id":"mg-4-s31","tur":"coktan-secmeli","soru":"Otel kafesinde toplanan atıklardan hangisinin geri kazanım potansiyeli en düşüktür?","secenekler":["Yağa bulaşmış kâğıt peçete","Temiz alüminyum içecek kutusu","Katlanmış temiz karton koli","Durulanmış boş PET şişe"],"dogru":0,"aciklama":"Yağa bulaşan kâğıt değerini kaybeder ve yeniden değerlendirilemez. Temiz karton koli de kâğıt temellidir ama temiz kaldığı için geri kazanılabilir."},{"id":"mg-4-s32","tur":"coktan-secmeli","soru":"Ön büroda konukların adının ve oda numarasının yazılı olduğu eski bir liste atılacak. Doğru davranış hangisidir?","secenekler":["Listeyi katlayıp doğrudan kâğıt-karton kutusuna atmak","Listeyi önce parçalayıp kâğıt-karton kutusuna atmak","Listeyi buruşturup genel çöp kovasına atmak","Listeyi tehlikeli atık kutusunda biriktirmek"],"dogru":1,"aciklama":"Konuk bilgisi taşıyan kâğıt geri dönüşüme gider ama önce parçalanır, çünkü konuğun bilgisi çöpte de korunmalıdır. Doğrudan kutuya atmak bu bilgiyi açıkta bırakır."},{"id":"mg-4-s33","tur":"coktan-secmeli","soru":"Kumandalardan çıkan bitmiş pillerin çöpe değil pil kutusuna atılmasının nedeni hangisidir?","secenekler":["Pillerin çöp torbasında çok yer kaplaması","Pillerin yemek artığı gibi çürüyüp kötü koku yayması","Pillerin kâğıtla birlikte geri dönüştürülmesi","İçindeki metallerin toprağa ve suya karışabilmesi"],"dogru":3,"aciklama":"Pilin içindeki metaller çöp alanında toprağa ve suya karışabilir; bu yüzden pil ayrı kutuda toplanır. Piller organik değildir, çürüyüp koku yapmaz."},{"id":"mg-4-s34","tur":"coktan-secmeli","soru":"Otelin ilk yardım odasında bir konuğun yarasına pansuman yapıldı. Kanlı gazlı bez nereye atılmalıdır?","secenekler":["Organik atık kovasına","Kapaklı özel tıbbi atık kutusuna","Odadaki genel çöp kovasına","Kâğıt-karton geri dönüşüm kutusuna"],"dogru":1,"aciklama":"Kanla temas etmiş malzeme tıbbi atıktır ve özel toplama gerektirir. Gazlı bez kâğıda benzese de geri dönüşüm kutusuna atılmaz, çünkü risk taşır."},{"id":"mg-4-s35","tur":"coktan-secmeli","soru":"Otel mutfağında sebzeler soyulurken çıkan kabuklar ve kesilip atılan uçlar hangi kavramla anlatılır?","secenekler":["Gıda israfı","Ambalaj atığı","Tehlikeli atık","Üretim firesi"],"dogru":3,"aciklama":"Üretim sırasında soyma ve kesmeyle çıkan, ürüne girmeyen kısım firedir. Gıda israfı ise yenebilecek durumdaki yiyeceğin çöpe gitmesidir."},{"id":"mg-4-s36","tur":"coktan-secmeli","soru":"Öğrencinin otelde atık uygulamalarını yerinde inceleyip not tuttuğu saha gözleminde notların amacı hangisidir?","secenekler":["Düzeni geliştirmek için durumu kontrol listesine işlemek","Atığı yanlış ayıran personeli bulup yönetime bildirmek","Atık miktarına göre aylık atık faturasını yeniden hesaplamak","Kutuların renklerini yeniden boyamak için listelemek"],"dogru":0,"aciklama":"Saha gözleminde notlar kimseyi suçlamak için değil, düzeni geliştirmek için tutulur. Bu yüzden suçlu personel aramak gözlemin amacı değildir."},{"id":"mg-4-s37","tur":"dogru-yanlis","soru":"Kompost, plastik ve cam atıkların çürütülmesiyle elde edilen doğal gübredir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kompost sebze-meyve kabuğu, çay posası ve bahçe artığı gibi organik atıklardan elde edilir. Plastik ve cam çürümez; bunlar geri dönüşüm kutusuna gider."},{"id":"mg-4-s38","tur":"coktan-secmeli","soru":"Tur otobüsü otel girişinde yolcularını beklerken motoru çalışıyor ve egzoz gazı lobiye doluyor. En basit ve etkili önlem hangisidir?","secenekler":["Lobi kapısını sürekli açık tutmak","Lobiye koku giderici sprey sıkmak","Bekleyen aracın motorunu kapatması","Otobüsün motoru çalışır hâlde biraz ileride beklemesi"],"dogru":2,"aciklama":"Bekleyen aracın motorunu kapatması hava kirliliğini kaynağında keser. Aracı biraz ileri çekmek egzozu durdurmaz, yalnız yerini değiştirir."},{"id":"mg-4-s39","tur":"dogru-yanlis","soru":"Kirlilik yalnız gözle görülen atıklardan oluşur; otelin gece müziği ya da jeneratör sesi kirlilik sayılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Canlıların sağlığını, huzurunu ve dinlenmesini bozan ses düzeyi gürültü kirliliğidir. Müzik, jeneratör ve klima dış ünitesi otelde bu kirliliğin kaynaklarıdır."},{"id":"mg-4-s40","tur":"coktan-secmeli","soru":"Otelin bahçe deposunun arkasına bırakılan eski boya kutuları yağmurda sızdırıyor. Bu durumun sonucu için hangisi doğrudur?","secenekler":["Boya yalnız toprağın yüzeyinde kalır, suya geçmez.","Boya güneşte buharlaşıp kendiliğinden yok olur.","Boya toprağı besleyip verimini artırır.","Boya toprağa, oradan da yer altı suyuna karışır."],"dogru":3,"aciklama":"Toprağa giren zararlı madde orada kalmaz, suya ve yetişen ürüne geçer. Boyanın yalnız yüzeyde kalacağını düşünmek bu yüzden yanlıştır."},{"id":"mg-4-s41","tur":"coktan-secmeli","soru":"Plajda bırakılan plastik bardak ve pipetlerin denize ulaşmadan toplanması en doğrudan hangi sorunu önler?","secenekler":["Gürültü kirliliğinin artmasını","Mikroplastik oluşumunu","Ormansızlaşmayı","Su kıtlığını"],"dogru":1,"aciklama":"Plastik denizde dalga ve güneşle küçük parçalara ayrılır ve besin zincirine karışır; denize ulaşmadan toplanırsa mikroplastiğe dönüşmez. Öteki sorunlar plastikle doğrudan ilgili değildir."},{"id":"mg-4-s42","tur":"coktan-secmeli","soru":"Kat hizmetleri temizlik kimyasalını göz kararı dökmek yerine dozaj sistemiyle ölçülü kullanmaya başlıyor. Bu uygulama hangi yaklaşıma örnektir?","secenekler":["Temiz üretim","Atık su arıtma","İleri dönüşüm","Bertaraf"],"dogru":0,"aciklama":"Temiz üretim, kirliliği sonradan temizlemek yerine daha az zararlı madde kullanarak hiç oluşturmamaktır. Atık su arıtma ise kirlenmiş suyu sonradan temizler."},{"id":"mg-4-s43","tur":"coktan-secmeli","soru":"Bir doğa yürüyüşü rehberinin hangi davranışı turizmde sürdürülebilirlik anlayışına en uygundur?","secenekler":["Daha çok manzara görülsün diye grubu işaretli patikanın dışına çıkarmak","Çöpleri taşıma zahmeti olmasın diye mola yerinde bırakmak","Grubu işaretli patikada tutup köydeki aile işletmesinde mola vermek","Molayı köy yerine şehirden getirilen paket yemekle vermek"],"dogru":2,"aciklama":"Patikada kalmak doğayı korur, köydeki aile işletmesini seçmek yöre halkına kazanç sağlar. Patika dışına çıkmak daha çok manzara gösterse de doğaya zarar verir."},{"id":"mg-4-s44","tur":"dogru-yanlis","soru":"Sera etkisi tamamen zararlı bir olaydır; o olmasaydı dünya daha yaşanabilir bir yer olurdu.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sera etkisi doğal ve gereklidir; o olmasa dünya yaşanamayacak kadar soğuk olurdu. Sorun, insan faaliyetleriyle sera gazlarının artıp tutulan ısının fazlalaşmasıdır."},{"id":"mg-4-s45","tur":"coktan-secmeli","soru":"Küresel ısınma ile iklim değişikliği arasındaki ilişki için hangisi doğrudur?","secenekler":["İklim değişikliği, küresel ısınmanın nedenidir.","Küresel ısınma, iklim değişikliğinin nedenidir.","İkisi aynı olayın iki farklı adıdır.","İkisi birbirinden tamamen bağımsız iki ayrı olaydır."],"dogru":1,"aciklama":"Isınma sıcaklık artışıdır; bu artışın yağış, mevsim ve hava olaylarında yol açtığı değişme iklim değişikliğidir. Bu yüzden ikisi aynı şey değildir ve neden-sonuç sırası tersine çevrilemez."},{"id":"mg-4-s46","tur":"coktan-secmeli","soru":"Gıda israfını azaltmak sera gazı salımını da azaltır. Bunun nedeni hangisidir?","secenekler":["Yemek artıklarının denizde mikroplastiğe dönüşmesi","Yemek artıklarının içinde yüksek oranda ağır metal bulunması","Yemek artıklarının yakıldığında oksijen üretmesi","Çöp alanında çürüyen organik atıktan metan çıkması"],"dogru":3,"aciklama":"Metan, çöp alanlarında çürüyen organik atıklardan çıkan bir sera gazıdır; çöpe giden yemek azaldıkça metan da azalır. Mikroplastik plastikten oluşur, yemek artığından değil."},{"id":"mg-4-s47","tur":"coktan-secmeli","soru":"Deniz kaplumbağalarının yumurta bıraktığı kumsaldaki bir otel, geceleri güçlü ışıkları söndürüyor ve şezlongları topluyor. Otel hangi sorunu önlemeye çalışıyor?","secenekler":["Biyoçeşitlilik kaybını","Gürültü kirliliğini","Görüntü kirliliğinin artmasını","Ormansızlaşmayı"],"dogru":0,"aciklama":"Işık ve şezlong yüzünden yavrular denize ulaşamazsa kaplumbağa sayısı azalır; bu biyoçeşitlilik kaybıdır. Şezlongları toplamak görüntüyü de düzeltir ama asıl amaç yavruların yoludur."},{"id":"mg-4-s48","tur":"coktan-secmeli","soru":"Otelin sıcak suyunun bir bölümü çatıdaki güneş sisteminden geliyor. Konuk “Sıcak su nereden geliyor?” diye sorduğunda resepsiyonun en doğru yanıtı hangisidir?","secenekler":["“Sıcak suyumuzun tamamı güneşten geliyor.”","“Sıcak suyumuz rüzgâr enerjisiyle ısıtılıyor.”","“Sıcak suyumuzun bir bölümü güneşten geliyor.”","“Bunu bilmiyorum, lütfen teknik servise sorar mısınız?”"],"dogru":2,"aciklama":"Resepsiyon yalnız gerçeği söyler: suyun bir bölümü güneşten geliyorsa “bir bölümü” denir. “Tamamı” demek kulağa daha iyi gelse de abartılı sözdür ve yeşil yıkama sayılır."},{"id":"mg-4-s49","tur":"dogru-yanlis","soru":"Bu ünitede gıda güvenliği, mutfaktaki hijyen kurallarını değil, herkesin yeterli ve sağlıklı gıdaya ulaşabilmesini anlatır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Küresel çevre sorunlarıyla ilgili gıda güvenliği, yeterli gıdaya ulaşabilmektir (food security). Mutfaktaki hijyen kuralları ise başka bir kavramdır (food safety)."},{"id":"mg-4-s50","tur":"coktan-secmeli","soru":"Bir plaja verilen Mavi Bayrak gibi çevre etiketleri için hangisi doğrudur?","secenekler":["Bir kez alınan etiket süresiz geçerli kalır.","İşletme etiketi kendi kendine verebilir.","Etiket yalnız tanıtım amaçlı bir işarettir.","Ölçütler sürdürülmezse etiket geri alınır."],"dogru":3,"aciklama":"Çevre etiketini bağımsız bir kuruluş denetimle verir; ölçütler sürdürülmezse geri alınır. Bu yüzden bir kez alınıp unutulan bir belge değildir."},{"id":"mg-4-s51","tur":"dogru-yanlis","soru":"Stajda görülen ayrı atık kutuları ve geçici depolama alanı, yöneticinin kişisel tercihi değil, Sıfır Atık Yönetmeliği’nin gereğidir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Sıfır Atık Yönetmeliği atıkların kaynağında ayrı toplanması ve sistemin kurulması için kurallar koyar. Ayrı kutular bu yasal düzenlemenin gereğidir."},{"id":"mg-4-s52","tur":"coktan-secmeli","soru":"Otelin su faturası bir ay birden arttı. Çözüm seçmeden önce ilk yapılması gereken hangisidir?","secenekler":["Pahalı bir su tasarruf cihazını hemen satın almak","Artışın hangi bölümde, hangi saatte ve neden olduğunu bulmak","Bütün bölümlerde suyu belirli saatlerde kesmek","Hiçbir şey yapmadan faturanın bir sonraki ay kendiliğinden düşmesini beklemek"],"dogru":1,"aciklama":"Çevre sorunu analizi önce kaynağı ve nedeni belirler; çözüm buna göre seçilir. Analiz yapmadan cihaz almak yanlış yere para harcamak olabilir."},{"id":"mg-4-s53","tur":"coktan-secmeli","soru":"Plastik pipeti kaldırma önerisi altı şapkalı düşünmeyle tartışılıyor. Bir şef “Konuklar şikâyet edebilir, maliyet artabilir.” diyor. Şef hangi şapkayla konuşuyor?","secenekler":["Siyah","Kırmızı","Sarı","Mavi"],"dogru":0,"aciklama":"Siyah şapka riskleri dile getirir; şefin söyledikleri önerinin olası riskleridir. Kırmızı şapka duyguyu anlatır, risk değerlendirmesi yapmaz."},{"id":"mg-4-s54","tur":"coktan-secmeli","soru":"Bir otel enerji izleme cihazı alıyor ama personele nasıl kullanılacağını anlatmıyor. Çözümün dört temel sütunundan hangisi eksik kalmıştır?","secenekler":["Teknolojik inovasyon","Yasal düzenleme","Tüketici eğitimi","Sıfır atık politikaları"],"dogru":2,"aciklama":"Cihaz alındığı için teknoloji sütunu vardır; eksik olan bilgilendirme, yani eğitim sütunudur. Bu yüzden dört sütun birlikte düşünülmezse cihaz boşa durur."},{"id":"mg-4-s55","tur":"coktan-secmeli","soru":"Butik bir otel eski ahşap paletleri zımparalayıp boyuyor ve bahçesine oturma köşesi yapıyor. Bu uygulamayı geri dönüşümden ayıran özellik hangisidir?","secenekler":["Malzeme eritilip yeniden aynı ürün olarak üretilir.","Malzeme bir kompost kabında çürütülerek doğal gübreye dönüştürülür.","Malzeme düzenli depolama alanında ortadan kaldırılır.","Malzeme hammaddeye çevrilmeden yeni bir ürüne dönüşür."],"dogru":3,"aciklama":"İleri dönüşümde malzeme fabrikada hammaddeye çevrilmeden yaratıcı bir tasarımla yeni bir kullanıma kavuşur. Eritilip yeniden üretilmek ise geri dönüşümün kendisidir."},{"id":"mg-4-s56","tur":"coktan-secmeli","soru":"Konuk odadan çıkarken kartını yuvadan alıyor ve odanın elektriği kendiliğinden kesiliyor. Bu uygulama hangi kavrama örnektir?","secenekler":["Enerji verimliliği","Yenilenebilir enerji","Temiz üretim","İleri dönüşüm"],"dogru":0,"aciklama":"Boş odada lamba ve klima çalışmadığı için aynı konfor daha az enerjiyle sağlanır; bu enerji verimliliğidir. Yenilenebilir enerji ise güneş ve rüzgâr gibi kaynaktan elde edilen enerjidir."},{"id":"mg-4-s57","tur":"coktan-secmeli","soru":"Küçük bir pansiyonun atık ayrıştırma makinesini koyacak yeri ve bakımını yapacak kişisi yok; bu yüzden ayrı atık kutuları koyuyor. Bu seçimde hangi ölçüt öne çıkar?","secenekler":["Ekolojik fayda","Uygulanabilirlik","Maliyet etkinliği","Yeşil dönüşüm"],"dogru":1,"aciklama":"Uygulanabilirlik, çözümün işletmenin eldeki imkânlarıyla (yer, kişi, bakım) gerçekten hayata geçirilebilmesidir. Maliyet etkinliği harcamanın yarara değip değmediğine bakar; burada belirleyici olan imkân eksikliğidir."},{"id":"mg-4-s58","tur":"dogru-yanlis","soru":"Çevresel bir çözüm yalnız ucuz olduğu için seçilir; doğaya sağladığı yarar karar verirken hesaba katılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çözüm seçilirken doğaya sağladığı yarar, yani ekolojik fayda da gözetilir ve maliyet etkinliğiyle birlikte değerlendirilir."}],"siralamalar":[{"id":"mg-4-r01","konu":"4.1","baslik":"Atığın yolu: hangi kapı önce denenir?","yonerge":"Atık yönetiminin öncelik basamaklarını en çok istenenden en az istenene doğru sıraya koy.","adimlar":["Gereksiz tüketimi kes, atığın hiç oluşmamasını ya da azalmasını sağla.","Ürünü atma; aynı ya da farklı bir iş için tekrar kullan.","Atığı türüne göre ayır, işlenip yeni hammaddeye dönüşmesi için geri dönüşüme gönder.","Hiçbir yolla değerlendirilemeyen atığı çevreye ve insan sağlığına zarar vermeden bertaraf et."],"aciklama":"En iyi atık hiç oluşmayan atıktır; geri dönüşüm de enerji ve taşıma gerektirdiği için azaltma ve yeniden kullanmadan sonra gelir. Bertaraf, başka hiçbir yol kalmadığında başvurulan son basamaktır."},{"id":"mg-4-r02","konu":"4.3","baslik":"Egzozdan sele uzanan zincir","yonerge":"İnsan faaliyetinden iklim değişikliğine giden neden-sonuç zincirini doğru sıraya koy.","adimlar":["Enerji üretiminde, ulaşımda ve sanayide fosil yakıtlar kullanılır.","Atmosfere salınan karbondioksit, metan gibi sera gazlarının miktarı artar.","Atmosferde biriken sera gazları yeryüzündeki ısının daha fazlasını tutar.","Dünya’nın ortalama sıcaklığı uzun yıllar içinde yükselir.","Sıcaklık ve yağış düzeni bozulur; kuraklık, sel ve orman yangını gibi etkiler görülür."],"aciklama":"Fosil yakıt kullanımı sera gazını artırır, biriken gazlar doğal sera etkisini güçlendirip küresel ısınmaya yol açar. İklim değişikliği bu ısınmanın sıcaklık, yağış ve hava olaylarındaki uzun süreli sonucudur."},{"id":"mg-4-r03","konu":"4.4","baslik":"Görünmeyen zarar: atölyeden sofraya","yonerge":"Etrafa atılan bir atığın insan sağlığına uzanan etki zincirini doğru sıraya koy.","adimlar":["Atölyede oluşan kimyasal içerikli atıklar gelişigüzel etrafa atılır.","Atıklardaki kimyasallar toprağa sızar.","Toprağa geçen kimyasallar yer altı sularını kirletir.","Kirlilik besin zinciri yoluyla insanlara kadar ulaşır.","İnsanlarda hastalıklar ortaya çıkar."],"aciklama":"Etrafa atılan atık ilk bakışta yalnızca görüntü kirliliği sanılır; asıl zarar toprak, su ve besin zinciri üzerinden adım adım insana ulaşır. Bu yüzden çevre sorunu yüzeydeki görüntüyle değil nedenleri ve uzun vadeli etkileriyle değerlendirilir."},{"id":"mg-4-r04","konu":"4.5","baslik":"İsraf eden işletmeye döngüsel çözüm","yonerge":"Bir işletmenin atık sorununa döngüsel ekonomiyle çözüm bulma görevinin işlem basamaklarını doğru sıraya koy.","adimlar":["İşletmedeki kaynak israfı ya da atık sorununu yaz, neden çözülmesi gerektiğini açıkla.","Sorunun sınırlarını ve risklerini belirle, nedenlerini balık kılçığı diyagramına yerleştir.","Azalt, yeniden kullan, geri dönüştür kuralına göre çözüm önerileri geliştir.","Önerileri maliyet etkinliği, uygulanabilirlik, ekolojik ve toplumsal fayda açısından tartıp en uygununu seç.","Seçtiğin çözümü görsellerle desteklenmiş bir dijital sunuma dönüştür.","Sunumunu sınıfta paylaş, çözümün işletmeye, doğaya ve topluma katkısını anlat.","Öz, akran ve grup değerlendirme formlarını doldur."],"aciklama":"Sorun tanımlanmadan nedenleri, nedenler görülmeden çözümü bulunamaz; öneriler ölçütlerle karşılaştırılıp en uygunu seçildikten sonra sunulur ve çalışma değerlendirmeyle kapanır."}],"acikSorular":[{"id":"mg-4-y01","konu":"4.1","soru":"Bir otelin mutfağında her gün sebze-meyve kabuğu, kullanılmış kızartma yağı ve plastik ambalaj atığı oluşuyor. Bu üç atığın türünü yazınız ve atıkların oluştuğu yerde türüne göre ayrı kaplara konulmasının (kaynağında ayrıştırmanın) neden önemli olduğunu açıklayınız.","olcut":[{"metin":"Sebze-meyve kabuğunu organik atık olarak sınıflandırır.","puan":15},{"metin":"Kullanılmış kızartma yağını bitkisel atık yağ olarak, plastik ambalajı plastik (ambalaj) atığı olarak sınıflandırır.","puan":20},{"metin":"Kaynağında ayrıştırmanın atığın oluştuğu yerde ve anda türüne göre ayrı kaplara konulması olduğunu belirtir.","puan":20},{"metin":"Ayrı toplanan atığın geri dönüşüm, kompost gibi yollarla yeniden değerlendirilebildiğini açıklar.","puan":20},{"metin":"Atıklar karışırsa geri kazanımın zorlaşacağını ve çöpe gidecek miktarın artacağını belirterek ayrıştırmanın nedenini açıklar.","puan":25}],"ornek":"Sebze-meyve kabuğu organik atıktır, kızartma yağı bitkisel atık yağdır, plastik ambalaj ise plastik (ambalaj) atığıdır. Kaynağında ayrıştırma, atığın oluştuğu yerde ve anında türüne göre ayrı kaplara konulması demektir. Ayrı toplanan organik atıktan kompost, plastikten geri dönüşüm yoluyla yeni ürün elde edilebilir. Atıklar birbirine karışırsa yeniden değerlendirmek zorlaşır ve çöpe giden miktar artar; bu yüzden atıklar kaynağında ayrılmalıdır.","ipucu":"Atık karışınca geri kazanıma ne olacağını düşünün; yalnızca “çevre temiz kalır” demek yetmez."},{"id":"mg-4-y02","konu":"4.5","soru":"Bir otel, kullandığı malzemeleri satın alıp kullandıktan sonra çöpe atmaktadır. Otelin bu düzenini döngüsel ekonomiyle karşılaştırınız ve aynı otelde atığı azaltmak için uygulanabilecek iki öneriyi gerekçesiyle yazınız.","olcut":[{"metin":"Doğrusal ekonomiyi “al, yap, at” düzeni olarak tanımlar.","puan":15},{"metin":"Döngüsel ekonomiyi ürün ve malzemelerin uzun süre kullanıldığı, atığın yeniden hammaddeye dönüştüğü düzen olarak tanımlar.","puan":20},{"metin":"Birinci öneriyi (örneğin azaltma, yeniden kullanma ya da geri dönüştürme) otel örneğiyle yazar.","puan":20},{"metin":"İkinci öneriyi otel örneğiyle yazar.","puan":20},{"metin":"Önerilerin neden atığı ve kaynak israfını azalttığını açıklar.","puan":25}],"ornek":"Otelin şimdiki düzeni doğrusal ekonomidir: hammadde alınır, ürün yapılır, kullanılır ve atılır. Döngüsel ekonomide ürünler olabildiğince uzun süre kullanılır ve atık yeniden hammaddeye dönüştürülür. Otel azaltma ilkesiyle gereksiz tek kullanımlık ürün almayarak atığı oluşmadan önleyebilir. Yeniden kullanma ilkesiyle de cam su sürahileri gibi tekrar kullanılabilen ürünleri tercih edebilir. Bu önerilerde malzeme çöpe gitmeden kullanıldığı için hem atık hem kaynak israfı azalır.","ipucu":"Atığın otelde hiç oluşmamasını ya da oluşan şeyin yeniden işe yaramasını sağlayan yolları düşünün."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":5,"baslik":"Girişimcilik: Fikirler, İş Kurma ve Yürütme","onay":true,"kazanimlar":["Girişimcilik süreçleri ile ekonomi arasındaki ilişkiyi yorumlayabilme.","Başarılı iş fikirlerinin özelliklerini çözümleyebilme.","Tasarım odaklı düşünme yaklaşımının girişimcilikteki işlevini değerlendirebilme.","Özgün bir iş modeli yapılandırabilme.","İşletme kurma ve yürütme süreçlerini yansıtabilme."],"soz":"İyi iş fikri, birinin derdine çare olan fikirdir.","dersler":[{"baslik":"Kendi İşinin Patronu Olmak","ilk":"mg-5-001"},{"baslik":"Keşke Şöyle Bir Yer Olsa","ilk":"mg-5-007"},{"baslik":"Fiyatı Kim Belirler?","ilk":"mg-5-009"},{"baslik":"Para Tek Başına Yetmez","ilk":"mg-5-015"},{"baslik":"Değer Sadece Para mı?","ilk":"mg-5-079"},{"baslik":"Ya Olmazsa?","ilk":"mg-5-003"},{"baslik":"Yeniliğin Dört Yüzü","ilk":"mg-5-020"},{"baslik":"İyi Fikir Nasıl Tanınır?","ilk":"mg-5-026"},{"baslik":"Güven Veren Lider","ilk":"mg-5-073"},{"baslik":"Önce İnsan, Sonra Ürün","ilk":"mg-5-031"},{"baslik":"Karşındakinin Yerine Geçmek","ilk":"mg-5-035"},{"baslik":"Kartondan Bir Deneme","ilk":"mg-5-038"},{"baslik":"Doğru Soruyu Sormak","ilk":"mg-5-085"},{"baslik":"Kime, Ne Sunuyorsun?","ilk":"mg-5-041"},{"baslik":"Tek Sayfada Bir İşletme","ilk":"mg-5-045"},{"baslik":"Hesap Tutuyor mu?","ilk":"mg-5-050"},{"baslik":"Kapısı Çalınacak Yerler","ilk":"mg-5-055"},{"baslik":"Fikir Hangi Süzgeçten Geçer?","ilk":"mg-5-089"},{"baslik":"Sermaye Nereden Gelir?","ilk":"mg-5-017"},{"baslik":"Tek Başına mı, Ortakla mı?","ilk":"mg-5-057"},{"baslik":"Kapıyı Açmadan Önce","ilk":"mg-5-061"},{"baslik":"Açmak Kolay, Yürütmek Emek","ilk":"mg-5-067"},{"baslik":"Kuruluştan Uzun Yola","ilk":"mg-5-091"}],"kavramlar":[{"id":"mg-5-001","konu":"5.1","terim":"Girişimcilik","ingilizce":"Entrepreneurship","tanim":"Bir ihtiyacı ya da fırsatı fark edip risk alarak kaynakları bir araya getirme ve bundan değer üreten bir iş kurma sürecidir.","ornek":"Bir kasabada hafta sonu gelen gezginlerin kahvaltı edecek yer bulamadığını gören biri, bahçeli evini yöresel kahvaltı salonuna çevirir.","sektor":"Programın anahtar kavramlarındandır. Turizm, küçük girişimlerin çok olduğu bir alandır: pansiyon, kahvaltı salonu, küçük acente, tur rehberliği. Girişimcilik yalnız girişimciye kazandırmaz; iş alanı açar, yöredeki üreticiye de pazar sağlar.","iliskili":["mg-5-002","mg-5-003","mg-5-014"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-002","konu":"5.1","terim":"Girişimci","ingilizce":"Entrepreneur","tanim":"Bir fırsatı görüp emeğini, parasını ve zamanını ortaya koyarak iş kuran ve bu işin riskini üstlenen kişidir.","ornek":"Otelde birkaç yıl çalıştıktan sonra birikimiyle memleketinde üç odalı bir butik pansiyon açan eski resepsiyon görevlisi.","sektor":"Programın anahtar kavramlarındandır. Girişimci olmak için önce işi bilmek gerekir: otelde öğrendiğin konuk karşılama, maliyet ve temizlik standardı, bir gün kendi işini kurarsan en büyük sermayen olur.","iliskili":["mg-5-001","mg-5-003","mg-5-017"],"kontrol":null},{"id":"mg-5-004","konu":"5.1","terim":"Ticari girişimcilik","ingilizce":"Commercial entrepreneurship","tanim":"Bir mal ya da hizmeti satarak kâr elde etmeyi amaçlayan girişimcilik türüdür.","ornek":"Sahil kasabasında bisiklet kiralayan ve rehberli bisiklet turu satan küçük bir işletme.","sektor":"En yaygın girişimcilik türüdür. Kâr amacı toplumsal faydayı dışlamaz: dürüst çalışan pansiyon hem sahibine kazandırır hem yöreye konuk getirir. Kolay yoldan, konuğu yanıltarak kazanmak ise işletmenin adını kısa sürede bitirir.","iliskili":["mg-5-001","mg-5-005","mg-5-013"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-005","konu":"5.1","terim":"Sosyal girişimcilik","ingilizce":"Social entrepreneurship","tanim":"Asıl amacı toplumsal ya da çevresel bir sorunu çözmek olan, elde ettiği geliri de bu amacı sürdürmek için kullanan girişimcilik türüdür.","ornek":"Bir köyde kadınların ürettiği el işlerini ve yöresel ürünleri gezginlere satan, gelirini yine üreten kadınlara aktaran bir girişim.","sektor":"Girişimcilik yalnız kâr demek değildir; bir sorunu çözmek de girişimciliğin işidir. Turizmde yöre halkını işin içine katan girişimler konuğa gerçek bir deneyim, yöreye de gelir bırakır.","iliskili":["mg-5-001","mg-5-004","mg-5-006"],"kontrol":null},{"id":"mg-5-006","konu":"5.1","terim":"İç girişimcilik","ingilizce":"Intrapreneurship","tanim":"Bir çalışanın, çalıştığı işletmenin içinde girişimci gibi düşünerek yeni bir fikir geliştirmesi ve yönetimin onayıyla hayata geçirmesidir.","ornek":"Bir otelin servis elemanı, konukların yöresel lezzet sorduğunu fark eder ve şefine haftada bir “yöre gecesi” yapılmasını önerir; öneri kabul edilir.","sektor":"Girişimci düşünmek için iş yeri sahibi olmak gerekmez. Stajyerken bile gördüğün bir aksaklığa çözüm önerebilirsin; doğru yolu fikrini önce amirine götürmektir.","iliskili":["mg-5-002","mg-5-005","mg-5-021"],"kontrol":null,"kitapDisi":true,"cizim":"girisim-isletme"},{"id":"mg-5-007","konu":"5.1","terim":"İhtiyaç","ingilizce":"Need","tanim":"İnsanın yaşamını sürdürmek ya da daha rahat ve mutlu yaşamak için karşılanmasını istediği eksikliktir.","ornek":"Uzun yoldan gelen gezgin acıkır, yorulur ve geceyi geçirecek güvenli bir yer arar: yemek, dinlenme ve barınma ihtiyacı.","sektor":"Her iş fikri bir ihtiyaçla başlar. “Keşke burada şöyle bir yer olsa” cümlesi, karşılanmamış bir ihtiyacın işaretidir; girişimci bu cümleyi duyan kişidir.","iliskili":["mg-5-008","mg-5-026","mg-5-028"],"kontrol":null},{"id":"mg-5-008","konu":"5.1","terim":"Mal ve hizmet","ingilizce":"Goods and services","tanim":"İhtiyaçları karşılayan elle tutulur ürünlere mal, bir kişinin başkası için yaptığı ve elle tutulmayan işlere hizmet denir; ikisi birlikte ekonominin sunduğu şeylerdir.","ornek":"Kahvaltı salonunda masaya gelen peynir ve reçel maldır; masanın hazırlanması, güler yüzlü servis ve temizlik hizmettir.","sektor":"Turizm ağırlıklı olarak hizmet satar. Hizmet depolanamaz: bu gece boş kalan oda yarın satılamaz. Bu yüzden turizm girişimcisi yalnız ürünü değil, konuğun yaşadığı anı da tasarlar.","iliskili":["mg-5-007","mg-5-009","mg-5-010"],"kontrol":null},{"id":"mg-5-071","konu":"5.1","terim":"Üretim","ingilizce":"Production","tanim":"İhtiyaçları karşılayacak mal ve hizmetlerin emek, malzeme ve bilgi kullanılarak ortaya konmasıdır.","ornek":"Sabah 06.00, kahvaltı salonunun mutfağında usta hamuru açar, gözlemeyi pişirir; konuk geldiğinde masa hazırdır.","sektor":"Turizmde hizmet çoğu zaman konuğun gözü önünde üretilir: tur, konuk katılırken; servis, konuk masadayken ortaya çıkar. Bu yüzden hatayı sonradan düzeltmek zordur; iş ilk seferde doğru yapılır.","iliskili":["mg-5-008","mg-5-072","mg-5-014"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-072","konu":"5.1","terim":"Ticaret","ingilizce":"Trade","tanim":"Mal ve hizmetlerin kazanç elde etmek amacıyla alınıp satılmasıdır.","ornek":"Kahvaltı salonu sahibi peyniri ve balı köydeki üreticiden satın alır, hazırladığı kahvaltıyı konuğuna satar.","sektor":"Ticaret, üreten ile ihtiyacı olanı buluşturur. Temeli güvendir: sözünde duran, doğru tartan, zamanında ödeyen işletmeyle herkes yeniden çalışmak ister.","iliskili":["mg-5-008","mg-5-071","mg-5-009"],"kontrol":null},{"id":"mg-5-009","konu":"5.1","terim":"Pazar","ingilizce":"Market","tanim":"Bir mal ya da hizmeti satmak isteyenlerle almak isteyenlerin karşılaştığı ve fiyatın oluştuğu ortamdır.","ornek":"Bir tatil beldesindeki bütün pansiyonlar ile orada kalacak yer arayan gezginler birlikte o beldenin konaklama pazarını oluşturur.","sektor":"Pazar yalnız çarşıdaki tezgâh değildir; internetteki rezervasyon siteleri de bir pazardır. Girişimci işe başlamadan önce pazarını tanır: kimler satıyor, kimler alıyor, kaça alıyor?","iliskili":["mg-5-010","mg-5-011","mg-5-029"],"kontrol":null,"gorsel":"carsi"},{"id":"mg-5-010","konu":"5.1","terim":"Arz","ingilizce":"Supply","tanim":"Satıcıların belirli bir fiyattan satmaya hazır olduğu mal ya da hizmet miktarıdır.","ornek":"Bir kasabadaki pansiyonların bir gecede satabileceği toplam oda sayısı, o kasabanın konaklama arzıdır.","sektor":"Turizmde arz kısa sürede artırılamaz: yeni oda yapmak zaman ister. Girişimci, arzın az olduğu yerde ve zamanda fırsat arar.","iliskili":["mg-5-011","mg-5-012","mg-5-009"],"kontrol":null,"gorsel":"m3-fruit-stall-in-shashemene"},{"id":"mg-5-011","konu":"5.1","terim":"Talep","ingilizce":"Demand","tanim":"Alıcıların belirli bir fiyattan satın almak istediği ve parasını ödemeye hazır olduğu mal ya da hizmet miktarıdır.","ornek":"Bayram tatilinde bir sahil kasabasında oda arayanların sayısı birden artar: talep yükselmiştir.","sektor":"İstemek yetmez; talep, istek ile ödeme gücünün birleşmesidir. Turizmde talep mevsime, tatil günlerine ve havaya göre hızla değişir; işletme planını buna göre yapar.","iliskili":["mg-5-010","mg-5-012","mg-5-029"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-012","konu":"5.1","terim":"Fiyat","ingilizce":"Price","tanim":"Bir mal ya da hizmeti satın almak için ödenen para miktarıdır.","ornek":"Aynı pansiyon odasının yaz ortasındaki gecelik ücreti, kasım ayındakinden yüksektir.","sektor":"Fiyat yalnız arz ve talebe bağlı değildir; üretim maliyeti, rekabet ve ekonomik gelişmeler de fiyatı etkiler. Diğer koşullar aynı kalırsa talep artınca fiyat yükselir, sunulan miktar artınca fiyat düşebilir. Girişimci fiyat koyarken maliyetine, rakibine ve konuğun ödemeye razı olduğu tutara birlikte bakar.","iliskili":["mg-5-010","mg-5-011","mg-5-013"],"kontrol":null},{"id":"mg-5-013","konu":"5.1","terim":"Kâr ve zarar","ingilizce":"Profit and loss","tanim":"Bir işletmenin geliri giderinden fazlaysa aradaki fark kâr, gideri gelirinden fazlaysa aradaki fark zarardır.","ornek":"Ay sonunda kahvaltı salonunun sahibi satışlarını toplar; kira, malzeme ve ücretleri düşer. Elinde para kaldıysa kâr etmiştir.","sektor":"Kâr, işletmenin ayakta kalmasını ve büyümesini sağlar; ama tek amaç değildir. Konuğu memnun etmeden, çalışanın hakkını vermeden elde edilen kâr uzun sürmez.","iliskili":["mg-5-012","mg-5-049","mg-5-052"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-015","konu":"5.1","terim":"Girişimin kaynakları","ingilizce":"Business resources","tanim":"Bir işin kurulması ve yürütülmesi için gereken para, mekân, araç gereç ve insan gücünün bütünüdür.","ornek":"Deneyim atölyesi açmak isteyen biri liste yapar: başlangıç parası, bir atölye mekânı, tezgâh ve malzeme, işi bilen bir usta.","sektor":"Kaynaklar üç başlıkta toplanır: finansal, fiziksel ve beşerî. Üçü birbirine bağlıdır; biri eksik kalırsa diğerleri de işe yaramaz. Girişimci kaynağı israf etmeden kullanan kişidir.","iliskili":["mg-5-016","mg-5-018","mg-5-019"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-016","konu":"5.1","terim":"Finansal kaynak","ingilizce":"Financial resources","tanim":"Bir girişimin kurulması ve günlük giderlerinin karşılanması için gereken paradır.","ornek":"Pansiyon açacak kişinin kendi birikimi, ailesinden aldığı borç ve bankadan kullandığı kredi finansal kaynaklarıdır.","sektor":"Para yalnız açılış günü için gerekmez; ilk konuk gelene kadar kira, fatura ve ücretler de ödenir. Bu yüzden girişimci açılıştan sonraki ilk ayların giderini de baştan hesaplar.","iliskili":["mg-5-015","mg-5-017","mg-5-051"],"kontrol":null,"gorsel":"m3-1-turkish-lira-03"},{"id":"mg-5-018","konu":"5.1","terim":"Fiziksel kaynak","ingilizce":"Physical resources","tanim":"Bir işletmenin işini yaparken kullandığı bina, mekân, makine, araç gereç ve malzeme gibi elle tutulur varlıklardır.","ornek":"Bisiklet turu işletmesinin bisikletleri, kaskları, tamir takımı ve bisikletleri sakladığı depo.","sektor":"Turizmde konuk fiziksel kaynağı doğrudan görür ve kullanır: yatak, havlu, bisiklet, masa. Bakımsız bir araç gereç yalnız görüntüyü değil, güvenliği de bozar.","iliskili":["mg-5-015","mg-5-019","mg-5-070"],"kontrol":null},{"id":"mg-5-019","konu":"5.1","terim":"Beşerî kaynak","ingilizce":"Human resources","tanim":"Bir işletmede çalışan insanlar ile onların bilgi, beceri ve emeğidir.","ornek":"Kahvaltı salonunun hamuru açan ustası, servisi yapan garsonu ve hesabı tutan sahibi o işletmenin beşerî kaynağıdır.","sektor":"Hizmet işinde en değerli kaynak insandır: en güzel pansiyon bile ilgisiz bir karşılamayla kötü hatırlanır. Doğru kişiyi bulmak, yetiştirmek ve hakkını vermek girişimcinin en önemli işlerindendir.","iliskili":["mg-5-015","mg-5-018","mg-5-066"],"kontrol":null,"cizim":"ekip"},{"id":"mg-5-075","konu":"5.1","terim":"Girişimcilik ekosistemi","ingilizce":"Entrepreneurship ecosystem","tanim":"Girişimcilerin, müşterilerin, yatırımcıların, destek kuruluşlarının ve yasal düzenlemelerin birbirini etkileyerek oluşturduğu çevredir.","ornek":"Bir kasabada kahvaltı salonu açan girişimci malzemeyi yerel üreticiden alır, destek için KOSGEB’e başvurur, müşterisini çevrim içi sitelerden bulur ve ruhsatını belediyeden alır.","sektor":"Girişimci tek başına var olmaz; yerel üretici, destek kuruluşu ve müşteri ağı güçlüyse yeni işler daha kolay kurulur ve yaşar.","iliskili":["mg-5-001","mg-5-002","mg-5-055"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-079","konu":"5.1","terim":"Değer oluşturma","ingilizce":"Value creation","tanim":"İnsanların bir ihtiyacını karşılayan, bir sorununu çözen ve kullanıcıya fayda sağlayan ürün, hizmet ya da çözüm geliştirme sürecidir.","ornek":"Cumartesi sabahı 09.00’da köy meydanında kahvaltı salonu açan Ayşe, gezginlerin saatlerce yemek aradığını görür; hızlı ve sıcak bir kahvaltı sunarak onların zamanını kazandırır.","sektor":"Değer yalnız para kazanmak demek değildir; güvenliği artırmak, zaman kaybını azaltmak ya da bir hizmete erişimi kolaylaştırmak da değer oluşturur.","iliskili":["mg-5-001","mg-5-007","mg-5-016"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-081","konu":"5.1","terim":"Arz, talep ve fiyat ilişkisi","ingilizce":"Relationship between supply, demand and price","tanim":"Diğer koşullar aynı kalırsa talep arttıkça fiyatın yükselme, sunulan miktar arttıkça fiyatın düşme eğiliminde olduğunu gösteren ilişkidir.","ornek":"Bayramda sahildeki otellere gelen rezervasyon talebi artar ve boş oda sayısı azalır; gecelik fiyatlar yükselir.","sektor":"Fiyat yalnız arza ve talebe bağlı değildir; maliyet, rekabet ve ekonomik gelişmeler de etkiler.","iliskili":["mg-5-010","mg-5-011","mg-5-012"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-082","konu":"5.1","terim":"Girişimde balık kılçığı analizi","ingilizce":"Fishbone diagram","tanim":"Bir ana sorunun nedenlerini finansal, fiziksel, beşerî kaynak ile planlama ve yönetim gibi başlıklara ayırarak kılçık biçiminde gösteren çözümleme şemasıdır.","ornek":"Atölyesinde üretim duran Ali’nin hikâyesini sınıfta çalışan grup, tahtaya önce “üretim durdu” ana sorununu yazar; sonra para, makine, çalışan, planlama ve yönetim kılçıklarına olası nedenleri ekler.","sektor":"Ana sorun tek bir kaynaktan geliyormuş gibi görünse de kılçıklar, nedenlerin birden fazla başlıkta toplanabileceğini gösterir.","iliskili":["mg-5-015","mg-5-019","mg-5-018"],"kontrol":null,"cizim":"gastronomi"},{"id":"mg-5-003","konu":"5.2","terim":"Girişimcilikte risk","ingilizce":"Business risk","tanim":"Bir işte istenmeyen bir sonucun ortaya çıkma ve bu yüzden para, zaman ya da emek kaybetme ihtimalidir.","ornek":"Kış aylarında konuk gelmeyebileceğini bilen pansiyon sahibi, yaz gelirinin bir bölümünü kış giderleri için ayırır.","sektor":"Programın anahtar kavramlarındandır. Girişimci riskten kaçamaz, ama onu hesaplayabilir: önce araştırır, küçük başlar, olası kaybı baştan düşünür. Turizmde mevsim, hava ve ekonomik dalgalanma başlıca risklerdir.","iliskili":["mg-5-002","mg-5-050","mg-5-053"],"kontrol":null,"cizim":"uyari"},{"id":"mg-5-014","konu":"5.2","terim":"Katma değer","ingilizce":"Added value","tanim":"Bir ürüne ya da hizmete emek, bilgi ve fikir katılarak onun değerinin artırılması ve bu yolla eklenen değerdir.","ornek":"Köyden alınan süt peynire dönüşür; peynir, bahçede serpme kahvaltı tabağında sunulur. Her adımda ürünün değeri artar.","sektor":"Girişimcinin ekonomiye katkısı budur: var olanı alıp daha değerli bir şeye çevirir. Turizmde katma değer çoğu zaman deneyimdir; aynı çay, manzaralı bir bahçede ve güler yüzle sunulduğunda başka bir değer taşır.","iliskili":["mg-5-001","mg-5-013","mg-5-043"],"kontrol":null},{"id":"mg-5-020","konu":"5.2","terim":"İcat","ingilizce":"Invention","tanim":"Daha önce var olmayan bir aracın, yöntemin ya da ürünün ilk kez ortaya konmasıdır.","ornek":"Kapıyı anahtar yerine kartla açan kilit düzeneğinin ilk kez tasarlanması bir icattır.","sektor":"İcat tek başına iş değildir; rafta kalan bir buluş kimseye değer katmaz. İcadı kullanılır ve satılır hâle getirmek inovasyonun işidir.","iliskili":["mg-5-021","mg-5-022","mg-5-027"],"kontrol":null,"gorsel":"m3-edison-incandescent-light-bulb-enc"},{"id":"mg-5-021","konu":"5.2","terim":"İnovasyon","ingilizce":"Innovation","tanim":"Yeni ya da belirgin biçimde iyileştirilmiş bir ürünün, hizmetin ya da çalışma yönteminin hayata geçirilip değer üretmesidir; Türkçede yenilik de denir.","ornek":"Kartlı kilidin otellerde kullanılmaya başlanması ve konuğun kayıp anahtar derdinden kurtulması bir inovasyondur.","sektor":"Programın anahtar kavramlarındandır. İnovasyon için büyük bir buluş gerekmez; bilinen bir şeyi yeni bir yerde, yeni bir biçimde kullanmak da inovasyondur. Yaygın bir sınıflandırma dört tür sayar: ürün, süreç, pazarlama ve organizasyonel inovasyon; başka kaynaklar türleri farklı gruplayabilir.","iliskili":["mg-5-020","mg-5-022","mg-5-023"],"kontrol":null,"gorsel":"m3-itb2016-hotel-robot-1-travelarz"},{"id":"mg-5-022","konu":"5.2","terim":"Ürün inovasyonu","ingilizce":"Product innovation","tanim":"Müşteriye yeni ya da belirgin biçimde iyileştirilmiş bir mal ya da hizmet sunulmasıdır.","ornek":"Bir pansiyon, yalnız oda satmak yerine konuklarına köy fırınında ekmek yapma deneyimi sunmaya başlar.","sektor":"Turizmde ürün çoğu zaman hizmettir; yeni bir tur, yeni bir kahvaltı sunumu, yeni bir atölye birer ürün inovasyonudur. Konuğa “başka yerde yaşamadığım bir şey” dedirtir.","iliskili":["mg-5-021","mg-5-023","mg-5-043"],"kontrol":null},{"id":"mg-5-023","konu":"5.2","terim":"Süreç inovasyonu","ingilizce":"Process innovation","tanim":"Bir ürünün ya da hizmetin hazırlanma ve sunulma yönteminin yenilenerek işin daha hızlı, daha ucuz ya da daha kaliteli yapılmasıdır.","ornek":"Bir pansiyon kâğıt kayıt defterini bırakır; konuk, gelmeden önce bilgilerini telefonundan gönderir ve kapıda beklemez.","sektor":"Konuk çoğu zaman süreci görmez, sonucunu hisseder: daha az bekler, daha az hata yaşar. İşletme de zamandan ve malzemeden kazanır.","iliskili":["mg-5-021","mg-5-022","mg-5-025"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-5-024","konu":"5.2","terim":"Pazarlama inovasyonu","ingilizce":"Marketing innovation","tanim":"Bir ürünün tanıtımında, sunumunda, ambalajında ya da satış yolunda yeni bir yöntem kullanılmasıdır.","ornek":"Yöresel reçellerini yalnız tezgâhta satan bir kahvaltı salonu, küçük kavanozlarda “yolluk” paketi hazırlayıp konuklara çıkışta sunar.","sektor":"Ürün aynı kalır, müşteriye ulaşma biçimi değişir. Küçük işletmeler için büyük fırsattır: az parayla, yaratıcı bir sunumla fark edilmek mümkündür.","iliskili":["mg-5-021","mg-5-047","mg-5-068"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-025","konu":"5.2","terim":"Organizasyonel inovasyon","ingilizce":"Organisational innovation","tanim":"Bir işletmenin iş bölümünde, çalışma düzeninde ya da başka kurumlarla ilişkilerinde yeni bir yöntem uygulamasıdır.","ornek":"Küçük bir otel, her sabah beş dakikalık ekip toplantısı başlatır; herkes o günün gelen ve giden konuklarını birlikte gözden geçirir.","sektor":"Dışarıdan görünmez, ama hizmete yansır: bilgi ekip içinde daha hızlı dolaşır, işler aksamaz. Komşu işletmelerle iş birliği kurmak da bu türe girer.","iliskili":["mg-5-021","mg-5-023","mg-5-067"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-026","konu":"5.2","terim":"Fırsat","ingilizce":"Opportunity","tanim":"Karşılanmamış bir ihtiyacın ya da çözülmemiş bir sorunun, yeni bir iş için elverişli bir ortam oluşturmasıdır.","ornek":"Yürüyüş yolu açılan bir köye gezginler gelmeye başlar, ama köyde kalacak yer yoktur; bu durum pansiyon açmak isteyen biri için fırsattır.","sektor":"Programın anahtar kavramlarındandır. Fırsat çoğu zaman bir şikâyetin içinde saklıdır. Herkesin “Burada hiçbir şey yok” dediği yerde girişimci “Burada ne eksik?” diye sorar.","iliskili":["mg-5-007","mg-5-027","mg-5-028"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-027","konu":"5.2","terim":"İş fikri","ingilizce":"Business idea","tanim":"Bir ihtiyacı karşılamak ya da bir sorunu çözmek için hangi ürünün ya da hizmetin kime, nasıl sunulacağını anlatan düşüncedir.","ornek":"“Kasabamıza gelen gezginlere, yerel bir rehberle yarım günlük bisiklet turu satacağım.”","sektor":"Programın anahtar kavramlarındandır. Başarılı iş fikrinin ortak özellikleri vardır: gerçek bir sorunu çözer, katma değer üretir, yeterince müşterisi vardır, uzun süre sürdürülebilir ve bir yenilik taşır.","iliskili":["mg-5-026","mg-5-028","mg-5-029"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-028","konu":"5.2","terim":"Müşteri problemi","ingilizce":"Customer problem","tanim":"Müşterinin bir işi yaparken yaşadığı zorluk, eksiklik ya da hoşnutsuzluktur; iyi bir iş fikri bu soruna çözüm getirir.","ornek":"Sabah erken yola çıkacak gezgin, kasabada o saatte açık bir kahvaltı yeri bulamaz.","sektor":"“Benim fikrim çok güzel” demek yetmez; “Kimin, hangi derdini çözüyor?” sorusunun cevabı olmalıdır. Çözdüğü sorun ne kadar gerçekse fikrin tutma ihtimali o kadar yüksektir.","iliskili":["mg-5-007","mg-5-027","mg-5-037"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-029","konu":"5.2","terim":"Pazar potansiyeli","ingilizce":"Market potential","tanim":"Bir ürünü ya da hizmeti satın alabilecek müşterilerin ne kadar çok olduğunu ve işin ne kadar büyüyebileceğini gösteren özelliktir.","ornek":"Yılın büyük bölümünde gezgin alan bir kasabada açılan kahvaltı salonunun pazar potansiyeli, kimsenin uğramadığı bir yerdekinden yüksektir.","sektor":"Çok iyi bir fikir, alacak kişi yoksa iş olmaz. Girişimci “Bunu kaç kişi ister, kaç kişi parasını öder?” sorusunu açılıştan önce sorar.","iliskili":["mg-5-011","mg-5-027","mg-5-041"],"kontrol":null},{"id":"mg-5-030","konu":"5.2","terim":"İş fikrinin sürdürülebilirliği","ingilizce":"Business sustainability","tanim":"Bir işin kaynaklarını tüketmeden, çevresine ve itibarına zarar vermeden uzun yıllar ayakta kalabilmesidir.","ornek":"Doğa yürüyüşü turu yapan işletme, grupları küçük tutar ve patikaya çöp bırakmaz; çünkü doğa bozulursa satacak tur da kalmaz.","sektor":"Kolay yoldan, konuğu yanıltarak para kazanmak bir sezon sürer; sonra kötü yorumlar gelir ve işletme itibarını yitirir. Uzun ömürlü iş dürüstlük, kalite ve doğaya saygı üzerine kurulur.","iliskili":["mg-5-003","mg-5-027","mg-5-029"],"kontrol":null,"gorsel":"m3-eco-lodge-pisang-4560844138"},{"id":"mg-5-073","konu":"5.2","terim":"Liderlik","ingilizce":"Leadership","tanim":"Bir topluluğu ortak bir amaca doğru yönlendirmek için insanları etkileme, motive etme ve onlara örnek olma becerisidir.","ornek":"Saat 08.00, yeni açılan yöresel kahvaltı salonunda kurucu, ekibe günün hedefini anlatır, görevleri paylaştırır ve ilk müşteriyi kendisi karşılar.","sektor":"Küçük işletmede girişimci aynı zamanda ekibin lideridir; ekip, kurucunun tutumunu izler ve ona göre davranır.","iliskili":["mg-5-002","mg-5-001","mg-5-067"],"kontrol":null,"cizim":"lider"},{"id":"mg-5-083","konu":"5.2","terim":"Yenilikçilik","ingilizce":"Innovativeness","tanim":"Bir iş fikrinin mevcut çözümlere göre anlamlı bir farklılık ya da belirgin bir iyileştirme sunmasıdır.","ornek":"Bir kafe, sabah 07.30’da işe giden çalışanlara önceden sipariş verilen ve kapıda hazır bekleyen kahvaltı paketi hazırlar; yakındaki öteki yerlerde bu hizmet yoktur.","sektor":"Yenilikçilik tek başına başarı getirmez; kullanıcının ihtiyaç duymadığı ya da uygulanamayan fikir güçlü iş modeline dönüşmeyebilir.","iliskili":["mg-5-021","mg-5-026","mg-5-027"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-084","konu":"5.2","terim":"Girişimcilikte etik davranış","ingilizce":"Business ethics in entrepreneurship","tanim":"Girişimcinin müşterilerine, çalışanlarına ve diğer paydaşlarına karşı dürüst ve güvenilir davranmasıdır.","ornek":"Küçük bir pansiyonun sahibi, broşürde yazdığı kahvaltıyı her sabah gerçekten verir; bir gün malzeme yetmeyince konuklara durumu açıkça anlatır ve ücret iadesi yapar.","sektor":"Müşteriyi yanıltarak elde edilen kısa vadeli kazanç güven kaybına ve itibarın zarar görmesine yol açar.","iliskili":["mg-5-003","mg-5-073","mg-5-005"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-5-031","konu":"5.3","terim":"Tasarım odaklı düşünme","ingilizce":"Design thinking","tanim":"Bir sorunu çözerken kullanıcıyı merkeze alan, onu anlamakla başlayıp çözümü küçük denemelerle geliştiren düşünme ve çalışma yaklaşımıdır.","ornek":"Pansiyon açmadan önce girişimci, yöreye gelen gezginlerle konuşur, neye ihtiyaç duyduklarını öğrenir ve odasını ona göre döşer.","sektor":"Beş aşamada anlatılır: empati kurma, problemi tanımlama, fikir üretme, prototip ve test. Yalnız bir yöntem değil, bir bakış açısıdır: “Ben ne satmak istiyorum?” yerine “Konuk neye ihtiyaç duyuyor?” diye sorar.","iliskili":["mg-5-032","mg-5-033","mg-5-035"],"kontrol":null,"gorsel":"m3-edulabsbe-meetup1-design-thinking"},{"id":"mg-5-032","konu":"5.3","terim":"İnsan merkezlilik","ingilizce":"Human-centred approach","tanim":"Bir ürün ya da hizmet tasarlanırken onu kullanacak kişinin ihtiyaçlarının, duygularının ve alışkanlıklarının her kararın merkezine konmasıdır.","ornek":"Kahvaltı salonu sahibi masa yüksekliğini seçerken küçük çocuklu aileleri düşünür ve birkaç mama sandalyesi bulundurur.","sektor":"Otelciliğin özüyle aynıdır: konuğu merkeze almak. Kaliteli bir ürün, kullanıcının ihtiyacına uymuyorsa satılmaz; önce insan anlaşılır, sonra ürün yapılır.","iliskili":["mg-5-031","mg-5-035","mg-5-036"],"kontrol":null},{"id":"mg-5-033","konu":"5.3","terim":"Geleneksel girişimcilik yaklaşımı","ingilizce":"Traditional approach to entrepreneurship","tanim":"Girişimcinin önce kendi düşündüğü ürünü baştan sona hazırladığı, müşterinin ne dediğini ise ancak satışa çıktıktan sonra öğrendiği çalışma biçimidir.","ornek":"Biri bütün birikimiyle büyük bir restoran açar; açılıştan sonra yöreye gelenlerin çoğunun yalnız kahvaltı aradığını görür.","sektor":"Bu yolda hata geç fark edilir ve pahalıya patlar. Tasarım odaklı düşünme ise kullanıcıyı baştan sürece katar, fikri küçük denemelerle sınar; değer, müşteriyle birlikte oluşur.","iliskili":["mg-5-031","mg-5-034","mg-5-040"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-034","konu":"5.3","terim":"Hata maliyeti","ingilizce":"Cost of failure","tanim":"Yanlış bir kararın işletmeye kaybettirdiği para, zaman ve emeğin toplamıdır.","ornek":"Konuklara sormadan alınan pahalı bir kahve makinesi, konuklar çay istediği için köşede kullanılmadan durur.","sektor":"Hata ne kadar erken fark edilirse o kadar ucuza düzeltilir. Fikri kâğıt üstünde ya da küçük bir denemeyle sınamak, büyük yatırımdan sonra yanıldığını anlamaktan çok daha ucuzdur.","iliskili":["mg-5-033","mg-5-039","mg-5-040"],"kontrol":null,"gorsel":"m3-treasure-trove-of-wasted-food"},{"id":"mg-5-035","konu":"5.3","terim":"Empati kurma","ingilizce":"Empathise","tanim":"Tasarım odaklı düşünmenin ilk aşamasıdır; kullanıcıyı gözlemleyerek, dinleyerek ve kendini onun yerine koyarak ihtiyacını anlamaya çalışmaktır.","ornek":"Bir grup öğrenci cumartesi sabahı çarşıdaki kahvaltı salonunda oturur; müşterilerin nerede beklediğini, neyi sorduğunu, neye söylendiğini not eder.","sektor":"Bu aşamada çözüm aranmaz, yalnız anlaşılır. Yerinde yapılan gözleme saha gözlemi denir. İyi otelci bunu her gün yapar: konuğu izler, söylemediği ihtiyacını fark eder.","iliskili":["mg-5-031","mg-5-036","mg-5-037"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-5-036","konu":"5.3","terim":"Empati haritası","ingilizce":"Empathy map","tanim":"Kullanıcının ne gördüğünü, ne söylediğini, ne yaptığını ve ne hissettiğini tek bir sayfada bir araya getiren çalışma kâğıdıdır.","ornek":"Öğrenciler “bisikletle gezen genç gezgin” için bir harita doldurur: “Bisikletimi nereye bırakacağım?” der, sırt çantasını yanından ayırmaz, hırsızlıktan endişe eder.","sektor":"Gözlem notlarını düzenler ve kullanıcının gerçek ihtiyacını görünür kılar. Dolduran kişi kendi tahminini değil, gördüğünü ve duyduğunu yazar.","iliskili":["mg-5-032","mg-5-035","mg-5-037"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-5-037","konu":"5.3","terim":"Problemi tanımlama","ingilizce":"Define","tanim":"Tasarım odaklı düşünmenin ikinci aşamasıdır; toplanan gözlemlerden yola çıkarak çözülecek asıl sorunun açık ve tek bir cümleyle ortaya konmasıdır.","ornek":"“Kasabaya bisikletle gelen gezginler, bisikletlerini güvenle bırakacak yer bulamadıkları için çarşıda uzun süre kalamıyor.”","sektor":"Yanlış tanımlanan sorun, yanlış çözüme götürür. “Müşteri az” bir tanım değildir; “Kim, neyi, neden yapamıyor?” sorusuna cevap veren cümle iyi bir tanımdır.","iliskili":["mg-5-028","mg-5-035","mg-5-038"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-038","konu":"5.3","terim":"Fikir üretme","ingilizce":"Ideate","tanim":"Tasarım odaklı düşünmenin üçüncü aşamasıdır; tanımlanan sorun için eleştirmeden, olabildiğince çok ve farklı çözüm önerisi ortaya atılmasıdır.","ornek":"Grup, bisikletli gezginler için on dakikada fikirlerini tahtaya yazar: kilitli park yeri, emanet dolabı, bisiklet tamir köşesi, bisikletliye özel kahvaltı.","sektor":"Bu aşamada “Olmaz” denmez; önce çok fikir toplanır, sonra en uygunu seçilir. Sınıfta bunun için beyin fırtınası yapılır.","iliskili":["mg-5-037","mg-5-039","mg-5-044"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-039","konu":"5.3","terim":"Prototip","ingilizce":"Prototype","tanim":"Bir fikrin nasıl çalışacağını görmek için hızlı ve ucuz biçimde hazırlanan ilk örneğidir.","ornek":"Öğrenciler bisiklet turu fikrini denemek için kartona rota haritası çizer, örnek bir bilet ve bir günlük program hazırlar.","sektor":"Prototip güzel olmak zorunda değildir; karton, kâğıt ya da eski malzemeyle yapılabilir. Hizmet işinde prototip bir canlandırma da olabilir: karşılama sahnesini sınıfta oynayıp aksayan yeri görmek gibi.","iliskili":["mg-5-034","mg-5-038","mg-5-040"],"kontrol":null,"gorsel":"sektor-3b-yazici"},{"id":"mg-5-040","konu":"5.3","terim":"Test etme","ingilizce":"Test","tanim":"Tasarım odaklı düşünmenin son aşamasıdır; prototipin gerçek kullanıcılar tarafından denenip onların görüşüne göre düzeltilmesidir.","ornek":"Pansiyon sahibi yeni kahvaltı menüsünü önce bir hafta sonu birkaç konuğa sunar, ne dediklerini dinler ve menüyü ona göre değiştirir.","sektor":"Kullanıcının söylediğine geri bildirim denir. Test bir sınav değil, öğrenme fırsatıdır; eleştiri fikri güçlendirir. Gerekirse önceki aşamalara dönülür ve prototip yenilenir.","iliskili":["mg-5-034","mg-5-039","mg-5-033"],"kontrol":null},{"id":"mg-5-076","konu":"5.3","terim":"Özgünlük","ingilizce":"Originality","tanim":"Bir ürünün, hizmetin ya da iş fikrinin benzerlerinden ayrılan, kendine özgü ve taklit olmayan yönünün bulunmasıdır.","ornek":"Kasabadaki öteki kahvaltı salonlarından farklı olarak, sofrasını köyün kadınlarının el emeği peynir ve reçelleriyle kuran bir salon özgündür.","sektor":"Özgün olmayan işletme yalnız fiyatla yarışabilir; özgün işletme değer önerisiyle müşteriyi kendine çeker.","iliskili":["mg-5-043","mg-5-033","mg-5-028"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-085","konu":"5.3","terim":"Kullanıcı ihtiyaçlarına uygunluk","ingilizce":"Fit with user needs","tanim":"Geliştirilen çözümün kullanıcının gerçek ihtiyacını karşılaması ölçütüdür.","ornek":"Bir öğrenci grubu kantin için sipariş uygulaması yapmadan önce 10.00 teneffüsünde kuyruğu gözlemler ve asıl sorunun ödeme noktasındaki yığılma olduğunu görür.","sektor":"Kullanıcının ihtiyaç duymadığı ürün, teknik olarak başarılı olsa bile yeterli değer oluşturmaz.","iliskili":["mg-5-035","mg-5-036","mg-5-088"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-086","konu":"5.3","terim":"Probleme çözüm geliştirme","ingilizce":"Problem-focused solution development","tanim":"Çözüme ürünle değil, çözülmesi gereken doğru problemi belirleyerek başlama ve ardından probleme uygun çözüm üretme ölçütüdür.","ornek":"Okul kütüphanesinde kitap bulunamıyor; grup önce “Öğrenciler raflarda kitabı bulamıyor” problemini yazar, sonra raf işaretleme ve ödünç takip fikirlerini üretir.","sektor":"Önce doğru problem belirlenir; “Ne üretebiliriz?” yerine “Hangi sorunu çözmeliyiz?” sorusu sorulur.","iliskili":["mg-5-037","mg-5-088","mg-5-031"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-5-088","konu":"5.3","terim":"Görünen sorun ve asıl problem","ingilizce":"Apparent problem and root problem","tanim":"Kullanıcının dile getirdiği ya da dışarıdan görünen sorunun, gözlem ve verilerle ortaya çıkan gerçek sorundan farklı olabileceğini anlatan ayrımdır.","ornek":"Otel resepsiyonunda “Check-in çok yavaş” şikâyeti gelir; müdür 14.00’te gelen gruplara bakınca asıl sorunun odaların hazır olmaması olduğunu görür.","sektor":"Problem cümlesi “Kim, neyi, neden yapamıyor?” sorusuna cevap verecek açıklıkta yazılır.","iliskili":["mg-5-037","mg-5-085","mg-5-086"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-041","konu":"5.4","terim":"Pazar araştırması","ingilizce":"Market research","tanim":"Bir işe başlamadan önce müşteriler, rakipler ve fiyatlar hakkında düzenli biçimde bilgi toplanmasıdır.","ornek":"Küçük acente açmak isteyen girişimci, ilçedeki öteki acenteleri gezer, hangi turları kaça sattıklarını not eder ve çevresindekilere hangi turu aradıklarını sorar.","sektor":"Programın anahtar kavramlarındandır. Tahminle değil bilgiyle karar vermeyi sağlar. Birkaç gün süren bir araştırma, yıllarca birikmiş paranın yanlış işe gitmesini önleyebilir.","iliskili":["mg-5-029","mg-5-042","mg-5-050"],"kontrol":null,"cizim":"grafik"},{"id":"mg-5-042","konu":"5.4","terim":"Hedef kitle","ingilizce":"Target market","tanim":"Bir işletmenin ürününü ya da hizmetini öncelikle sunmayı seçtiği, ortak özellikleri olan müşteri grubudur.","ornek":"Bir yöresel kahvaltı salonu, hafta sonu şehirden arabayla gelen çocuklu aileleri hedef kitle olarak belirler.","sektor":"Programın anahtar kavramlarındandır. “Herkese satarım” diyen kimseye tam uyamaz. Hedef kitle belli olunca fiyat, sunum, tanıtım ve hatta masa düzeni ona göre seçilir.","iliskili":["mg-5-041","mg-5-043","mg-5-046"],"kontrol":null},{"id":"mg-5-043","konu":"5.4","terim":"Değer önerisi","ingilizce":"Value proposition","tanim":"Bir işletmenin müşterisine sunduğu ve onu rakiplerinden ayıran yararın kısa ve açık anlatımıdır.","ornek":"“Kahvaltınızdaki her şey bu köyde üretildi; masanız bahçede, çocuklarınız gözünüzün önünde oynar.”","sektor":"Programın anahtar kavramlarındandır. “Müşteri neden rakibi değil beni seçsin?” sorusunun cevabıdır. Verilen söz tutulmalıdır: değer önerisi konuğa verilmiş bir sözdür.","iliskili":["mg-5-014","mg-5-042","mg-5-045"],"kontrol":null},{"id":"mg-5-044","konu":"5.4","terim":"Altı şapkalı düşünme tekniği","ingilizce":"Six Thinking Hats","tanim":"Bir konuya sırayla altı ayrı açıdan bakmayı sağlayan, her açının bir şapka rengiyle gösterildiği grup düşünme tekniğidir.","ornek":"İş fikrini tartışan grup önce yeşil şapkayla yeni fikirler üretir, sonra sarı şapkayla yararlarını, siyah şapkayla risklerini konuşur.","sektor":"Beyaz şapka bilgi ve verilere, kırmızı duygulara, siyah risklere ve zayıf yanlara, sarı yararlara, yeşil yeni fikirlere bakar; mavi şapka süreci yönetir ve kararı toparlar. Herkes aynı anda aynı açıdan baktığı için tartışma kavgaya dönmez.","iliskili":["mg-5-003","mg-5-038","mg-5-027"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-5-045","konu":"5.4","terim":"İş modeli","ingilizce":"Business model","tanim":"Bir işletmenin kime, hangi değeri, nasıl sunacağını ve bundan nasıl para kazanacağını gösteren genel düzendir.","ornek":"Bisiklet turu işletmesi: gezginlere rehberli tur satar, satışı pansiyonlar ve sosyal medya üzerinden yapar, kişi başı ücret alır, bisiklet bakımı ve rehber ücreti öder.","sektor":"Programın anahtar kavramlarındandır. İş fikri “Ne yapacağım?” sorusuna, iş modeli “Bu iş nasıl dönecek?” sorusuna cevap verir. Aynı fikir farklı modellerle yürütülebilir.","iliskili":["mg-5-027","mg-5-046","mg-5-048"],"kontrol":null},{"id":"mg-5-046","konu":"5.4","terim":"İş modeli kanvası","ingilizce":"Business Model Canvas","tanim":"Bir iş fikrinin ihtiyacını, hedef kitlesini, değer önerisini, kaynaklarını, maliyetini, finansmanını, gelirini ve risklerini tek bir tabloda toplayan çalışma şablonudur.","ornek":"Öğrenciler büyük bir kâğıdı dokuz kutuya böler ve deneyim atölyesi fikirlerini yapışkan notlarla kutulara yerleştirir.","sektor":"Ders kitabındaki kanvas ihtiyaç, hedef kitle, ürün veya hizmet, değer önerisi, yenilikçi yön, fayda, kaynaklar, maliyet yapısı, finansman kaynağı, gelir modeli ve riskleri satır satır doldurtur. Dünyada yaygın kullanılan Business Model Canvas ise dokuz kutuludur: müşteri grupları, değer önerisi, kanallar, müşteri ilişkileri, gelir akışları, temel kaynaklar, temel faaliyetler, temel ortaklar ve maliyet yapısı. Eksik kalan kutu, düşünülmemiş bir konuyu ele verir.","iliskili":["mg-5-045","mg-5-047","mg-5-049"],"kontrol":null,"kitapDisi":true,"cizim":"grafik"},{"id":"mg-5-047","konu":"5.4","terim":"Kanallar","ingilizce":"Channels","tanim":"Bir işletmenin müşterisine ulaşmak, ürününü tanıtmak ve satmak için kullandığı yollardır.","ornek":"Butik pansiyonun kanalları: kendi internet sayfası, çevrim içi rezervasyon siteleri, telefon ve anlaştığı küçük bir acente.","sektor":"İş modeli kanvasının kutularından biridir. Hedef kitle nerede ise kanal da orada olmalıdır: gençlere sosyal medyadan, yabancı konuğa uluslararası rezervasyon sitelerinden ulaşılır.","iliskili":["mg-5-042","mg-5-046","mg-5-068"],"kontrol":null,"kitapDisi":true,"cizim":"girisim-isletme"},{"id":"mg-5-048","konu":"5.4","terim":"Gelir modeli","ingilizce":"Revenue model","tanim":"Bir işletmenin parayı hangi yollarla ve kimden kazanacağını gösteren düzendir.","ornek":"Deneyim atölyesi katılımcıdan kişi başı ücret alır; ayrıca atölyede yapılan ürünlerin malzemesini ve hediyelik paketlerini satar.","sektor":"Programın anahtar kavramlarındandır. Satış, kiralama, komisyon ve üyelik başlıca gelir yollarıdır; küçük acente çoğu zaman sattığı turdan komisyon kazanır. Tek gelir yoluna bağlı işletme kırılgandır.","iliskili":["mg-5-045","mg-5-049","mg-5-013"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-049","konu":"5.4","terim":"Maliyet yapısı","ingilizce":"Cost structure","tanim":"Bir işletmenin işini yürütmek için katlandığı gider kalemlerinin ve bunların toplam gider içindeki ağırlığının bütünüdür.","ornek":"Kahvaltı salonunun giderleri: kira, personel ücreti, mutfak malzemesi, elektrik, su ve vergi.","sektor":"Programın anahtar kavramlarındandır. Kira gibi satış olsa da olmasa da ödenen giderlere sabit, malzeme gibi satışla birlikte artan giderlere değişken maliyet denir. Turizmde sezon dışında da süren sabit giderler baştan hesaba katılır.","iliskili":["mg-5-013","mg-5-048","mg-5-052"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-050","konu":"5.4","terim":"Finansal fizibilite","ingilizce":"Financial feasibility","tanim":"Bir iş fikrinin gerçekten yapılabilir ve kazançlı olup olmadığının işe başlamadan önce araştırılıp hesaplanmasıdır; yapılabilirlik de denir.","ornek":"Pansiyon açmayı düşünen kişi kuruluş giderini, aylık giderini ve beklediği geliri alt alta yazar; işin kendini çevirip çevirmeyeceğine bakar.","sektor":"Programın anahtar kavramlarındandır. Bu çalışmanın yazıya dökülmüş hâline fizibilite raporu denir. Rapor iyimser tahminle değil, pazar araştırmasından gelen gerçek bilgiyle doldurulur; “Bu iş olmaz” sonucu da değerli bir sonuçtur.","iliskili":["mg-5-003","mg-5-041","mg-5-054"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-051","konu":"5.4","terim":"Finansman","ingilizce":"Financing","tanim":"Bir işin kurulması ve yürütülmesi için gereken paranın bulunması ve sağlanmasıdır.","ornek":"Girişimci, bisiklet turu işi için paranın bir bölümünü birikiminden, kalanını banka kredisinden karşılamayı planlar.","sektor":"Girişimcinin kendi parasına öz kaynak, kredi gibi geri ödenecek paraya borç denir. Borçla kurulan işte geri ödeme de her ayın gideridir; plan buna göre yapılır.","iliskili":["mg-5-016","mg-5-017","mg-5-056"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-052","konu":"5.4","terim":"Başa baş noktası","ingilizce":"Break-even point","tanim":"Bir işletmenin toplam gelirinin toplam giderine eşit olduğu, ne kâr ne zarar ettiği satış düzeyidir.","ornek":"Kahvaltı salonu sahibi hesaplar: ayda belli sayıda kahvaltı satarsa giderlerini tam karşılar; o sayının üstündeki her satış kâr getirir.","sektor":"Girişimciye “En az ne kadar satmalıyım?” sorusunun cevabını verir. Bu noktaya ulaşmak gerçekçi görünmüyorsa fiyat, gider ya da fikir yeniden düşünülür.","iliskili":["mg-5-013","mg-5-049","mg-5-050"],"kontrol":null,"kitapDisi":true,"cizim":"girisim-isletme"},{"id":"mg-5-053","konu":"5.4","terim":"SWOT analizi","ingilizce":"SWOT analysis","tanim":"Bir işletmenin ya da iş fikrinin güçlü ve zayıf yönleri ile önündeki fırsatları ve tehditleri dört kutuda inceleyen değerlendirme yöntemidir.","ornek":"Butik pansiyon için: güçlü yön manzara, zayıf yön az oda, fırsat yeni açılan yürüyüş yolu, tehdit kışın kapanan yol.","sektor":"Güçlü ve zayıf yönler işletmenin kendi içinden, fırsatlar ve tehditler dış çevreden gelir. Adı İngilizce dört sözcüğün baş harfleridir: Strengths, Weaknesses, Opportunities, Threats.","iliskili":["mg-5-003","mg-5-026","mg-5-054"],"kontrol":null,"kitapDisi":true,"cizim":"grafik"},{"id":"mg-5-054","konu":"5.4","terim":"İş planı","ingilizce":"Business plan","tanim":"Bir girişimin ne yapacağını, kime satacağını, nasıl yürütüleceğini ve gelir ile giderinin ne olacağını adım adım anlatan yazılı belgedir.","ornek":"Küçük acente açacak girişimcinin dosyası: iş fikri, hedef kitle, rakipler, tanıtım yolu, kuruluş gideri ve ilk yılın gelir-gider tahmini.","sektor":"Programın anahtar kavramlarındandır. Girişimcinin yol haritasıdır; destek ya da kredi için başvurulan kurumlar da iş planı ister. Plan yazmak, fikrin boşluklarını para harcamadan önce gösterir.","iliskili":["mg-5-045","mg-5-050","mg-5-055"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-055","konu":"5.4","terim":"KOSGEB","ingilizce":"Small and Medium Enterprises Development Organisation of Türkiye (KOSGEB)","tanim":"Küçük ve Orta Ölçekli İşletmeleri Geliştirme ve Destekleme İdaresi Başkanlığının kısa adıdır; küçük ve orta ölçekli işletmeleri ve girişimcileri destekleyen kamu kurumudur.","ornek":"Yöresel kahvaltı salonu açmak isteyen genç girişimci, başvurmadan önce KOSGEB’in internet sayfasından güncel destek programlarını ve koşullarını okur.","sektor":"Küçük ve orta ölçekli işletmelere kısaca KOBİ denir; turizmdeki pansiyon, küçük otel ve acentelerin çoğu KOBİ’dir. Destek programları ve koşulları zamanla değişir; güncel bilgi her zaman kurumun kendi sayfasından alınır.","iliskili":["mg-5-051","mg-5-054","mg-5-056"],"kontrol":null,"cizim":"ekip"},{"id":"mg-5-074","konu":"5.4","terim":"KOBİ (küçük ve orta ölçekli işletme)","ingilizce":"SME (small and medium-sized enterprise)","tanim":"Çalışan sayısı ve yıllık geliri belirli sınırların altında kalan küçük ve orta büyüklükteki işletmelerdir.","ornek":"Aile işletmesi olarak çalışan küçük bir butik pansiyon ve birkaç kişilik bir seyahat acentesi birer KOBİ’dir.","sektor":"Turizmde pansiyon, küçük otel, acente ve restoran gibi pek çok işletme bu ölçektedir; KOSGEB destekleri KOBİ’lere yöneliktir.","iliskili":["mg-5-055","mg-5-050","mg-5-058"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-068","konu":"5.4","terim":"Pazarlama","ingilizce":"Marketing","tanim":"Müşterinin ihtiyacını anlayıp ona uygun ürünü hazırlama, doğru fiyatla sunma, tanıtma ve müşteriye ulaştırma çalışmalarının bütünüdür.","ornek":"Bisiklet turu işletmesi, turun gerçek fotoğraflarını sosyal medyada paylaşır ve çevredeki pansiyonlara broşür bırakır.","sektor":"Programın anahtar kavramlarındandır. Pazarlama yalnız reklam değildir; ürünün kendisinden, fiyatından ve satıldığı yerden başlar. Tanıtımda olmayan bir şeyi vaat etmek konuğu bir kez getirir, kötü yorumla geri gönderir; en güçlü pazarlama memnun ayrılan konuktur.","iliskili":["mg-5-024","mg-5-042","mg-5-047"],"kontrol":null,"gorsel":"m3-old-tourist-brochures"},{"id":"mg-5-089","konu":"5.4","terim":"İş fikrini değerlendirmenin dört bakış açısı","ingilizce":"Four perspectives for evaluating a business idea","tanim":"Bir iş fikri geliştirilirken yenilikçilik, fayda, risk ve karar açılarından seçeneklerin karşılaştırılmasıdır.","ornek":"Bir grup, bisiklet turu fikrini önce yenilik ve fayda yönünden tartar, sonra riskini yazar ve en uygun seçeneği seçer.","sektor":"Bu bakış açıları ilk akla gelen çözümü değil, en uygulanabilir çözümü seçmeyi sağlar.","iliskili":["mg-5-027","mg-5-026","mg-5-050"],"kontrol":null,"cizim":"beden-dili"},{"id":"mg-5-090","konu":"5.4","terim":"Kuruluş maliyeti","ingilizce":"Start-up cost","tanim":"Bir işletmeyi açmak için faaliyete başlamadan önce yapılması gereken harcamaların toplamıdır.","ornek":"Bir grup, fizibilite tablosunda küçük bir kahvaltı salonu için tezgâh, masa, ruhsat ve ilk malzeme giderini tahmini olarak yazar.","sektor":"Kuruluş maliyeti gerçekçi hesaplanmazsa işletmenin faaliyetleri olumsuz etkilenir.","iliskili":["mg-5-049","mg-5-050","mg-5-051"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-017","konu":"5.5","terim":"Sermaye","ingilizce":"Capital","tanim":"Bir işi kurmak ve yürütmek için ortaya konan para ile paraya çevrilebilen mal varlığıdır.","ornek":"Küçük bir acente açan girişimcinin kuruluş için ayırdığı para, büro eşyaları ve bilgisayarı sermayesini oluşturur.","sektor":"Programın anahtar kavramlarındandır. Sermaye yalnız para değildir: işi bilmek, tanınmak ve güvenilir olmak da girişimcinin görünmeyen sermayesidir. Parası az ama bilgisi çok olan girişimci küçük başlar ve adım adım büyür.","iliskili":["mg-5-002","mg-5-016","mg-5-051"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-056","konu":"5.5","terim":"Yatırımcı","ingilizce":"Investor","tanim":"Kazanç beklentisiyle bir girişime para koyan kişi ya da kurumdur.","ornek":"Sınıftaki girişimcilik zirvesinde bir grup iş fikrini kısa bir sunumla anlatır; yatırımcı rolündeki arkadaşları maliyeti ve riskleri sorar.","sektor":"Yatırımcı fikre değil, fikrin hesabına ve arkasındaki kişiye güvenir. Bu yüzden girişimci fikrini kısa, açık ve dürüst rakamlarla anlatmayı öğrenir; abartılı söz ilk soruda ortaya çıkar.","iliskili":["mg-5-051","mg-5-054","mg-5-003"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-057","konu":"5.5","terim":"İşletme","ingilizce":"Business","tanim":"İnsanların ihtiyaçlarını karşılamak üzere mal ya da hizmet üreten ve satan ekonomik birimdir.","ornek":"Üç odalı aile pansiyonu da yüzlerce odalı tatil köyü de birer işletmedir.","sektor":"İşletme kurulurken bir hukuki yapı seçilir: tek kişinin kurduğu şahıs işletmesi ya da limited ve anonim gibi şirket türleri. Seçim, kimin neden ve ne kadar sorumlu olacağını belirler.","iliskili":["mg-5-058","mg-5-059","mg-5-067"],"kontrol":null},{"id":"mg-5-058","konu":"5.5","terim":"Şahıs işletmesi","ingilizce":"Sole trader","tanim":"Tek bir kişinin kendi adına kurduğu, kazancın da sorumluluğun da tümüyle o kişiye ait olduğu işletme türüdür.","ornek":"Kendi evinin alt katında tek başına yöresel kahvaltı salonu açan girişimci.","sektor":"Kurması ve yürütmesi görece basittir; küçük işlerin çoğu böyle başlar. İşletme sahibi işin borçlarından kendi mal varlığıyla sorumludur; bu yüzden hesabını dikkatle tutar.","iliskili":["mg-5-057","mg-5-059","mg-5-060"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-059","konu":"5.5","terim":"Limited şirket","ingilizce":"Private limited company","tanim":"Bir ya da birkaç ortağın sermaye koyarak kurduğu, ortakların sorumluluğunun kural olarak koymayı üstlendikleri sermaye ile sınırlı olduğu şirket türüdür.","ornek":"İki arkadaş birikimlerini birleştirip bir seyahat acentesi kurar ve işletmeyi limited şirket olarak tescil ettirir.","sektor":"Küçük ve orta ölçekli ortaklıklarda en sık seçilen türdür. Şirket, ortaklarından ayrı bir kişiliktir: sözleşmeyi şirket imzalar, borç şirketin borcudur. Kuruluş kuralları ayrıntılıdır; girişimci bu aşamada uzman desteği alır.","iliskili":["mg-5-058","mg-5-060","mg-5-064"],"kontrol":null},{"id":"mg-5-060","konu":"5.5","terim":"Anonim şirket","ingilizce":"Joint-stock company","tanim":"Sermayesi paylara bölünmüş olan ve pay sahiplerinin yalnız üstlendikleri sermaye payı kadar sorumlu olduğu şirket türüdür.","ornek":"Birçok şehirde oteli bulunan büyük bir otel grubunun anonim şirket olarak kurulması.","sektor":"Büyük yatırım gerektiren işlere uygundur; çok sayıda ortak bir araya gelebilir, pay el değiştirebilir. Büyük otel zincirleri ve hava yolu şirketleri çoğunlukla bu türdedir.","iliskili":["mg-5-057","mg-5-059","mg-5-056"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-061","konu":"5.5","terim":"Yasal yükümlülük","ingilizce":"Legal obligation","tanim":"Bir işletmenin kurulurken ve çalışırken yasalar gereği yerine getirmek zorunda olduğu iş ve sorumluluklardır.","ornek":"Kahvaltı salonu açan girişimci vergi kaydını yaptırır, ruhsatını alır, çalışanını sigortalı olarak bildirir ve her satışa fiş keser.","sektor":"Başlıca üç kapı vardır: vergi dairesi, belediye ve SGK. İşin türüne göre başka belgeler de gerekir; örneğin seyahat acentesi açmak için Kültür ve Turizm Bakanlığından işletme belgesi alınır ve Türkiye Seyahat Acentaları Birliğine (TÜRSAB) üye olunur. Kurallar değişebildiği için güncel bilgi ilgili kurumdan öğrenilir.","iliskili":["mg-5-062","mg-5-065","mg-5-066"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-5-062","konu":"5.5","terim":"Vergi","ingilizce":"Tax","tanim":"Devletin, kamu hizmetlerini karşılamak üzere kişilerden ve işletmelerden yasayla aldığı paradır.","ornek":"Pansiyon sahibi işe başlarken vergi dairesine kaydolur; her konaklama için fatura ya da fiş düzenler ve kazancını beyan eder.","sektor":"Yol, okul ve hastane gibi kamu hizmetleri vergilerle karşılanır; turizm de bu altyapıyı kullanır. İşletmenin vergi işleri vergi dairesinde yürür. Fiş ya da fatura vermeden satış yapmak hem yasaya aykırıdır hem de dürüst çalışan işletmeye haksızlıktır. Vergisini ödeme sorumluluğunu taşımaya vergi bilinci denir.","iliskili":["mg-5-061","mg-5-063","mg-5-064"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-063","konu":"5.5","terim":"Vergi levhası","ingilizce":"Tax certificate","tanim":"Bir işletmenin vergi kaydının bulunduğunu, bağlı olduğu vergi dairesini, vergi numarasını ve faaliyet konusunu gösteren belgedir.","ornek":"Küçük acente, bir otelle anlaşma yaparken otelin muhasebesi acentenin vergi levhasının bir örneğini ister.","sektor":"İşletmenin kayıtlı ve yasal çalıştığının göstergesidir. Yeni bir iş ortağıyla çalışmaya başlarken karşılıklı olarak istenen ilk belgelerdendir.","iliskili":["mg-5-061","mg-5-062","mg-5-064"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-064","konu":"5.5","terim":"Ticaret sicili","ingilizce":"Trade register","tanim":"Ticari işletmelerin ve şirketlerin kuruluş, ortak, adres ve yetkili bilgilerinin resmî olarak kaydedildiği ve herkesin öğrenebildiği sicildir.","ornek":"İki ortağın kurduğu acente, ticaret sicili müdürlüğüne kaydedilir; şirketin adı, ortakları ve adresi sicile işlenir.","sektor":"Şirketler sicile kaydolarak resmen kurulmuş olur; bu işleme tescil denir. Sicil sayesinde bir işletmeyle iş yapacak kişi, karşısındakinin gerçekten var olduğunu ve kimin yetkili olduğunu öğrenebilir. Küçük esnaf ve sanatkârların ayrı bir sicili vardır.","iliskili":["mg-5-059","mg-5-061","mg-5-063"],"kontrol":null,"gorsel":"m3-ankara-ticaret-odas"},{"id":"mg-5-065","konu":"5.5","terim":"İş yeri açma ve çalışma ruhsatı","ingilizce":"Business opening and operating licence","tanim":"Bir iş yerinin yapacağı işe, sağlık ve güvenlik kurallarına uygun olduğunu gösteren ve yetkili idarenin verdiği izin belgesidir.","ornek":"Kahvaltı salonu açacak girişimci belediyeye başvurur; mutfak, havalandırma ve yangın önlemleri uygun bulunursa ruhsatını alır.","sektor":"Çoğunlukla belediyeden alınır. Ruhsat bir formalite değil, konuğun güvenliğinin güvencesidir: yangın çıkışı, hijyen ve binanın uygunluğu bu aşamada denetlenir.","iliskili":["mg-5-061","mg-5-066","mg-5-070"],"kontrol":null,"cizim":"sozlesme"},{"id":"mg-5-066","konu":"5.5","terim":"SGK (Sosyal Güvenlik Kurumu)","ingilizce":"Social Security Institution","tanim":"Çalışanların sigorta, sağlık ve emeklilik haklarını yürüten kamu kurumudur; işveren çalıştırdığı her kişiyi bu kuruma sigortalı olarak bildirmek zorundadır.","ornek":"Pansiyon sahibi, yaz sezonu için işe aldığı kat görevlisini işe başlatmadan önce SGK’ya bildirir ve primini düzenli öder.","sektor":"Sigortasız çalıştırmak yasaya aykırıdır ve çalışanı iş kazasında, hastalıkta ve emeklilikte korumasız bırakır. Mevsimlik çalışanın çok olduğu turizmde bu sorumluluk özellikle önemlidir; sen de çalışırken sigortanın yapıldığını bilmelisin.","iliskili":["mg-5-019","mg-5-061","mg-5-065"],"kontrol":null,"cizim":"uyari"},{"id":"mg-5-067","konu":"5.5","terim":"İşletme yönetimi","ingilizce":"Business management","tanim":"Bir işletmenin amaçlarına ulaşması için işlerin planlanması, görevlerin dağıtılması, ekibin yönlendirilmesi ve sonuçların denetlenmesidir.","ornek":"Pansiyon sahibi pazar akşamı haftayı planlar: hangi oda ne zaman boşalıyor, kim hangi gün çalışıyor, hangi malzeme alınacak.","sektor":"İşi kurmak başlangıçtır; asıl sınav onu her gün aynı kalitede yürütmektir. İyi kurulmuş ama kötü yönetilen işletme, kaynaklarını ve konuğunu kısa sürede kaybeder.","iliskili":["mg-5-025","mg-5-057","mg-5-069"],"kontrol":null,"cizim":"lider"},{"id":"mg-5-069","konu":"5.5","terim":"Nakit akışı","ingilizce":"Cash flow","tanim":"Belirli bir sürede işletmenin kasasına giren ve kasasından çıkan paranın hareketidir.","ornek":"Küçük otel, grubun ödemesini ay sonunda alacaktır, ama personel ücretlerini ve faturaları ay ortasında ödemek zorundadır.","sektor":"Kâğıt üzerinde kârlı görünen işletme bile ödeme günü kasasında para yoksa zora girer. Her gelirin ve giderin belgesiyle kaydedilmesi, paranın ne zaman girip çıkacağını önceden görmeyi sağlar.","iliskili":["mg-5-013","mg-5-049","mg-5-067"],"kontrol":null,"kitapDisi":true},{"id":"mg-5-070","konu":"5.5","terim":"Teknik altyapı","ingilizce":"Technical infrastructure","tanim":"Bir işletmenin mal üretmesi ya da hizmet sunması için ihtiyaç duyduğu fiziksel ve teknolojik unsurların (alan, araç gereç, makine, yazılım, ağ ve veri sistemleri) bütünüdür.","ornek":"Butik pansiyon açılmadan önce sıcak su sistemi, internet bağlantısı, yangın algılama düzeni ve rezervasyon programı kurulur.","sektor":"Konuk altyapıyı ancak aksadığında fark eder: sıcak su akmaz, internet çekmez. Altyapı işe başlamadan önce planlanır; sonradan düzeltmek hem pahalıdır hem hizmeti durdurur.","iliskili":["mg-5-018","mg-5-065","mg-5-067"],"kontrol":null},{"id":"mg-5-077","konu":"5.5","terim":"Vergi dairesi","ingilizce":"Tax office","tanim":"İşletmelerin ve kişilerin vergi kaydının tutulduğu, vergi beyanlarının verildiği ve vergilerin ödendiği kamu kurumudur.","ornek":"Kahvaltı salonu açan girişimci, iş yerini açarken vergi dairesine giderek vergi kaydını yaptırır.","sektor":"Her işletmenin bağlı olduğu bir vergi dairesi vardır; vergi levhası bu kaydın belgesidir.","iliskili":["mg-5-062","mg-5-063","mg-5-065"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-5-078","konu":"5.5","terim":"Belediye","ingilizce":"Municipality","tanim":"Bir şehir ya da kasabanın yerel hizmetlerini yürüten ve iş yeri açma ve çalışma ruhsatı gibi izinleri de veren yerel yönetim birimidir.","ornek":"Kahvaltı salonu açacak girişimci, iş yeri açma ve çalışma ruhsatı için belediyeye başvurur.","sektor":"Turizmde ruhsat, terasa masa koyma ve tabela gibi pek çok işlem belediyeyle yürür; belediyeyle iyi ilişki yerel işletmenin işini kolaylaştırır.","iliskili":["mg-5-065","mg-5-066","mg-5-067"],"kontrol":null,"cizim":"otel-bina"},{"id":"mg-5-091","konu":"5.5","terim":"İşletme kuruluşu","ingilizce":"Business formation","tanim":"Geliştirilen iş fikrinin faaliyete geçirilmesi için gerekli hazırlıkların ve işlemlerin yapılmasıdır.","ornek":"Pazartesi sabahı 10.00’da iki arkadaş, kuracakları seyahat acentesi için ofis yerini, personel ihtiyacını, ruhsat başvurusunu ve başlangıç giderlerini listeler.","sektor":"Kuruluş işlemleri her işletmede aynı değildir; hukuki yapı, faaliyet alanı ve personel sayısı işlemleri etkiler.","iliskili":["mg-5-057","mg-5-061","mg-5-092"],"kontrol":null,"cizim":"girisim-isletme"},{"id":"mg-5-092","konu":"5.5","terim":"İşletmenin sürdürülebilirliği","ingilizce":"Business sustainability","tanim":"Bir işletmenin değişen koşullara uyum sağlayarak faaliyetlerini uzun vadede devam ettirebilmesidir.","ornek":"Küçük bir otel, kuruluş kararlarını, yönetimi ve finansmanı birlikte gözden geçirerek kış aylarında da açık kalacak plan yapar.","sektor":"Kuruluş süreci, yönetim biçimi ve finansal durum birbirini doğrudan etkiler.","iliskili":["mg-5-067","mg-5-069","mg-5-091"],"kontrol":null,"cizim":"doga"},{"id":"mg-5-093","konu":"5.5","terim":"İş yeri bildirgesi","ingilizce":"Workplace declaration (SGK)","tanim":"İşverenin iş yeri ve çalışanlarla ilgili bilgileri Sosyal Güvenlik Kurumuna bildirdiği belgedir.","ornek":"Bir pansiyon sahibi, sezon öncesinde iş yerini bildirgeyle SGK’ya tanıtır ve ardından kat görevlisini işe başlatır.","sektor":"SGK bu bildirimleri elektronik ortamda yürütür.","iliskili":["mg-5-066","mg-5-094","mg-5-061"],"kontrol":null,"cizim":"grafik"},{"id":"mg-5-094","konu":"5.5","terim":"İşe giriş ve işten ayrılış bildirimi","ingilizce":"Employee registration and termination notification","tanim":"İşverenin çalışanın işe başlama ve işten ayrılma bilgilerini SGK’ya elektronik ortamda bildirmesidir.","ornek":"Bir otelde 1 Haziran’da başlayan mevsimlik garsonun girişi, 30 Eylül’de çıkışı SGK’ya bildirilir.","sektor":"Sigortalı çalışan istihdam eden her işveren için bildirim sorumluluğu doğar.","iliskili":["mg-5-093","mg-5-066","mg-5-067"],"kontrol":null,"cizim":"resepsiyon"},{"id":"mg-5-095","konu":"5.5","terim":"Görev dağılımı","ingilizce":"Division of duties","tanim":"Bir işletmedeki işlerin kim tarafından, hangi sorumlulukla yapılacağının açık biçimde belirlenmesidir.","ornek":"Yeni açılan bir kafede müdür, kasayı kimin tutacağını, servisi kimin yapacağını ve malzeme siparişini kimin vereceğini yazılı bir çizelgeyle belirler.","sektor":"Görev dağılımı açık değilse aynı iş birden fazla kişi tarafından yapılır ya da bazı görevler unutulur.","iliskili":["mg-5-067","mg-5-070","mg-5-091"],"kontrol":null,"cizim":"doga"}],"sorular":[{"id":"mg-5-s01","tur":"coktan-secmeli","soru":"Bir otelde yıllarca çalışan resepsiyon görevlisi, birikimiyle kendi butik pansiyonunu açıyor. Onu yatırımcıdan ayıran özellik hangisidir?","secenekler":["Yalnızca kazanç beklentisiyle para koyması","İşi kurması ve işin riskini kendisinin üstlenmesi","Yönetimin onayıyla işletme içinde yeni fikir geliştirmesi","Asıl amacının toplumsal bir sorunu çözmek olması"],"dogru":1,"aciklama":"Girişimci emeğini, parasını ve zamanını koyup işi kurar ve riskini üstlenir. Yatırımcı kazanç beklentisiyle yalnız para koyar; işi kurup yürütme yükü ondan değil, girişimciden beklenir."},{"id":"mg-5-s02","tur":"coktan-secmeli","soru":"Bir otelin servis elemanı, konukların yöresel lezzet sorduğunu fark eder ve şefine haftada bir “yöre gecesi” yapılmasını önerir; yönetim öneriyi kabul eder. Bu hangi girişimcilik türüdür?","secenekler":["Ticari girişimcilik","Sosyal girişimcilik","Şahıs işletmeciliği","İç girişimcilik"],"dogru":3,"aciklama":"Çalışan, çalıştığı işletmenin içinde girişimci gibi düşünüp fikrini yönetimin onayıyla hayata geçirdiği için bu iç girişimciliktir. Ticari girişimcilikte kişi kendi işini kurar; burada iş kurulmamış, mevcut işletme içinde yenilik yapılmıştır."},{"id":"mg-5-s03","tur":"coktan-secmeli","soru":"Kasım ayında sahil kasabasında oda arayanların sayısı azalır, pansiyonların oda sayısı aynı kalır. Diğer koşullar sabitken fiyatların düşme eğilimine girmesinin nedeni hangisidir?","secenekler":["Talep azaldığı için boş kalan odaları doldurmak isteyen pansiyonlar fiyat indirir.","Arz arttığı için piyasada fazla oda oluşur ve fiyatlar kendiliğinden düşer.","Pansiyonların giderleri talebe göre aynı oranda azaldığı için fiyat da düşer.","Fiyat yalnız rakip pansiyonlara bakılarak belirlendiği için düşüş yaşanır."],"dogru":0,"aciklama":"Arz aynı kalırken talep azalınca satılamayan oda çoğalır ve satıcılar fiyat indirir. Odaların sayısı değişmediği için arz artmamıştır; maliyet ve rekabet fiyatı etkiler, ama bu durumda değişen şey talepteki düşüştür."},{"id":"mg-5-s04","tur":"coktan-secmeli","soru":"Köyden alınan süt peynire, peynir de bahçede serpme kahvaltı tabağına dönüşüyor. Her aşamada ürüne emek, bilgi ve fikir eklenerek değerinin artmasına ne ad verilir?","secenekler":["Sermaye","Nakit akışı","Katma değer","Finansman"],"dogru":2,"aciklama":"Ürüne emek, bilgi ve fikir katılarak değerinin artırılması katma değerdir. Sermaye işe konan paradır; nakit akışı kasaya giren ve çıkan paranın hareketidir; finansman da işe gereken paranın sağlanmasıdır."},{"id":"mg-5-s05","tur":"coktan-secmeli","soru":"Bir mühendis kartla açılan yeni bir kilit sistemi tasarlıyor, ama sistem hiçbir otelde kullanılmadan dolapta kalıyor. Bu durum için hangisi doğrudur?","secenekler":["Yeni olduğu için bu bir inovasyondur.","İcattır; inovasyon için hayata geçip değer üretmesi gerekir.","Bir süreç inovasyonudur, çünkü kapı açma yöntemini değiştirir.","Pazarlama inovasyonudur, çünkü kilit konuklara gösterilecektir."],"dogru":1,"aciklama":"İcat, daha önce olmayan bir şeyin ilk kez ortaya konmasıdır; inovasyon ise yeniliğin kullanılır hâle gelip değer üretmesidir. Kilit otellerde kullanılıp konuğun anahtar derdini çözdüğünde inovasyon olur; dolapta kalan buluş sadece icattır."},{"id":"mg-5-s06","tur":"coktan-secmeli","soru":"Reçellerini yalnız tezgâhta satan bir kahvaltı salonu, aynı reçelleri küçük kavanozlardan oluşan “yolluk” paketi yapıp çıkışta konuklara sunmaya başlıyor. Reçelin kendisi değişmedi; yalnız sunum ve satış yolu yenilendi. Bu hangi inovasyon türüdür?","secenekler":["Pazarlama inovasyonu","Ürün inovasyonu","Süreç inovasyonu","Organizasyonel inovasyon"],"dogru":0,"aciklama":"Ürünün tanıtımında, ambalajında, sunumunda ya da satış yolunda yeni bir yöntem kullanmak pazarlama inovasyonudur. Ürün inovasyonunda mal ya da hizmetin kendisi yenilenir; burada reçel aynı kalmıştır."},{"id":"mg-5-s07","tur":"coktan-secmeli","soru":"Girişimci, açmayı düşündüğü kahvaltı salonunun önünden bir hafta boyunca geçen gezgin sayısını sayıyor. Bu çalışma iş fikrinin hangi özelliğini değerlendirir?","secenekler":["Hata maliyetini","Özgünlüğünü","İnsan merkezliliğini","Pazar potansiyelini"],"dogru":3,"aciklama":"Pazar potansiyeli, ürünü satın alabilecek müşterilerin ne kadar çok olduğunu ve işin ne kadar büyüyebileceğini gösterir; geçen gezgin sayısı bunun ölçüsüdür. Özgünlük fikrin benzerlerinden farkını, hata maliyeti yanlış kararın kaybettireceği değeri ölçer."},{"id":"mg-5-s08","tur":"coktan-secmeli","soru":"Bir grup, bisiklet turu fikrini az masrafla denemek istiyor. Prototip aşamasına en uygun çalışma hangisidir?","secenekler":["Bisikletleri satın alıp ruhsat için başvurmak","Üç yıllık gelir-gider tablosu hazırlamak","Kartondan harita ve bilet yapıp denemek","Broşür bastırıp kasabaya dağıtmak"],"dogru":2,"aciklama":"Prototip, fikrin nasıl çalışacağını görmek için hızlı ve ucuz hazırlanan ilk örnektir; kartondan harita ve bilet bunu sağlar. Bisikletleri satın almak ve ruhsat başvurusu büyük harcamadır, denemeden önce yapılırsa hata maliyetini artırır; broşür fikri denemez, yalnız duyurur; gelir-gider tablosu ise finansal fizibilitenin işidir."},{"id":"mg-5-s09","tur":"coktan-secmeli","soru":"Bir grup, empati haritasından topladığı gözlemlerden yola çıkarak çözülecek asıl sorunu tek cümleyle yazdı. Tasarım odaklı düşünmede sıradaki aşama hangisidir?","secenekler":["Test etme","Fikir üretme","Prototip","Empati kurma"],"dogru":1,"aciklama":"Aşamalar sırasıyla empati kurma, problemi tanımlama, fikir üretme, prototip ve testtir. Sorun tanımlandıktan sonra o sorun için çok sayıda çözüm önerisi üretilir; prototip bu fikirlerden seçilenle hazırlanır, test en sonda gelir."},{"id":"mg-5-s10","tur":"coktan-secmeli","soru":"Bir yöresel kahvaltı salonu, “hafta sonu şehirden arabayla gelen çocuklu aileler”e odaklanmaya karar veriyor. Bu ifade işletmenin hangi özelliğini tanımlar?","secenekler":["Hedef kitle","Değer önerisi","Gelir modeli","Maliyet yapısı"],"dogru":0,"aciklama":"Hedef kitle, işletmenin ürününü öncelikle sunmayı seçtiği, ortak özellikleri olan müşteri grubudur. Değer önerisi müşteriye sunulan yararı, gelir modeli paranın nereden kazanılacağını, maliyet yapısı giderleri anlatır."},{"id":"mg-5-s11","tur":"coktan-secmeli","soru":"Bir kafe ilanında “Her şey bu köyde üretildi, çocuklarınız bahçede güvenle oynar” yazıyor ve müşteriye neden rakiplerini değil kendisini seçmesi gerektiğini anlatıyor. Bu cümle iş modelinin hangi öğesine aittir?","secenekler":["Kanallar","Gelir modeli","Finansman","Değer önerisi"],"dogru":3,"aciklama":"Değer önerisi, işletmenin müşteriye sunduğu ve onu rakiplerinden ayıran yararın kısa ve açık anlatımıdır. Kanallar müşteriye ulaşma yollarıdır; gelir modeli ve finansman ise paranın nereden geleceğiyle ilgilidir."},{"id":"mg-5-s12","tur":"coktan-secmeli","soru":"İş fikrini tartışan grupta biri, “Kışın hiç konuk gelmezse bu işletme nasıl ayakta kalır?” diye soruyor. Altı şapkalı düşünme tekniğinde hangi şapkayla konuşuyor?","secenekler":["Yeşil şapka","Kırmızı şapka","Siyah şapka","Beyaz şapka"],"dogru":2,"aciklama":"Siyah şapka riskleri ve zayıf yanları arar; kışın gelmeyen konuk bir risktir. Yeşil şapka yeni fikir üretir, kırmızı şapka duyguları söyler, beyaz şapka ise eldeki bilgi ve verileri ortaya koyar."},{"id":"mg-5-s13","tur":"coktan-secmeli","soru":"Butik pansiyon için SWOT analizi yapılıyor. Aşağıdakilerden hangisi işletmenin dışından gelen ve işine yarayacak bir durumdur?","secenekler":["Bölgede yeni bir yürüyüş yolunun açılması","Pansiyonun manzarasının güzel olması","Pansiyonda oda sayısının az olması","Kışın yolun kapanması"],"dogru":0,"aciklama":"Fırsatlar ve tehditler dış çevreden gelir; yeni yürüyüş yolu gezgin getireceği için fırsattır. Manzara güçlü yön, az oda zayıf yön olarak işletmenin içindendir; kışın yolun kapanması dış çevreden gelse de tehdittir."},{"id":"mg-5-s14","tur":"coktan-secmeli","soru":"Bir kahvaltı salonu ayda 800 kahvaltı sattığında giderlerini tam karşılıyor; 801. kahvaltıdan itibaren kâr etmeye başlıyor. Bu satış düzeyine ne denir?","secenekler":["Nakit akışı","Başa baş noktası","Kuruluş maliyeti","Finansal fizibilite"],"dogru":1,"aciklama":"Toplam gelirin toplam gidere eşit olduğu, ne kâr ne zarar edilen satış düzeyi başa baş noktasıdır; bunun üstündeki satışlar kâr getirir. Kuruluş maliyeti açılış harcamasıdır, fizibilite ise fikrin kazançlı olup olmadığının hesaplanmasıdır."},{"id":"mg-5-s15","tur":"coktan-secmeli","soru":"Yöresel kahvaltı salonu açmak isteyen genç, girişimcilere verilen destek programlarını öğrenmek için hangi kurumun internet sayfasına bakmalıdır?","secenekler":["Sosyal Güvenlik Kurumu","Ticaret sicili müdürlüğü","Vergi dairesi","KOSGEB"],"dogru":3,"aciklama":"KOSGEB, küçük ve orta ölçekli işletmeleri ve girişimcileri destekleyen kamu kurumudur. SGK sigorta işlerini yürütür, ticaret sicili şirket bilgilerini kaydeder, vergi dairesi vergi kaydı ve beyanlarla ilgilenir."},{"id":"mg-5-s16","tur":"coktan-secmeli","soru":"Tek başına kahvaltı salonu açan biri şahıs işletmesi kuruyor. Bu işletme türünde sorumluluk nasıl işler?","secenekler":["Yalnız işe koyduğu sermaye ile sınırlı sorumludur.","Sorumluluk çalışanlarla paylaşılır.","Kazanç ve sorumluluk tümüyle kendisine aittir.","İşletme, sahibinden ayrı bir kişi olarak sorumlu olur."],"dogru":2,"aciklama":"Şahıs işletmesini tek kişi kendi adına kurar; kazancın da sorumluluğun da tümü ona aittir. Sorumluluğu koyulan sermayeyle sınırlı olan türler limited ve anonim şirketlerdir."},{"id":"mg-5-s17","tur":"coktan-secmeli","soru":"Pansiyon sahibi, yaz sezonu için işe aldığı kat görevlisini ne zaman ve hangi kuruma bildirmelidir?","secenekler":["İşe başlatmadan önce Sosyal Güvenlik Kurumuna","İlk maaşı ödedikten sonra Sosyal Güvenlik Kurumuna","Sezon sonunda vergi dairesine","Ruhsat yenilenirken belediyeye"],"dogru":0,"aciklama":"İşveren çalıştırdığı her kişiyi işe başlatmadan önce SGK’ya sigortalı olarak bildirmek zorundadır. Vergi dairesi vergi kaydını, belediye ruhsatı ilgilendirir; sigorta bildirimi bu kurumlara yapılmaz."},{"id":"mg-5-s18","tur":"coktan-secmeli","soru":"Yeni iş kuran bir girişimcinin yasal yükümlülükleriyle ilgili hangisi yanlıştır?","secenekler":["Her satış için fiş ya da fatura düzenler.","Çalışanını işe başlatmadan önce SGK’ya bildirir.","Ruhsatı ticaret sicili müdürlüğünden alır.","İşe başlarken vergi dairesine kaydolur."],"dogru":2,"aciklama":"İş yeri açma ve çalışma ruhsatı çoğunlukla belediyeden alınır; iş yerinin sağlık ve güvenlik kurallarına uygunluğu bu aşamada denetlenir. Ticaret sicili ise şirketlerin kuruluş, ortak ve adres bilgilerinin kaydedildiği sicildir."},{"id":"mg-5-s19","tur":"coktan-secmeli","soru":"Kâğıt üzerinde kârlı görünen küçük bir otel, grubun ödemesi ay sonunda geleceği için ay ortasındaki personel ücretlerini ve faturalarını ödemekte zorlanıyor. Otelin sorunu hangi kavramla ilgilidir?","secenekler":["Değer önerisi","Nakit akışı","Pazar potansiyeli","Ürün inovasyonu"],"dogru":1,"aciklama":"Nakit akışı, kasaya giren ve çıkan paranın zamanlamasıdır. Kârlı bir işletme bile ödeme günü kasasında para yoksa zora girer; sorun fikrin değerinde ya da müşteri sayısında değil, paranın geliş ve çıkış zamanındadır."},{"id":"mg-5-s20","tur":"dogru-yanlis","soru":"Sosyal girişimde elde edilen gelirin asıl amacı girişimcinin kişisel kazancını olabildiğince artırmaktır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sosyal girişimde asıl amaç toplumsal ya da çevresel bir sorunu çözmektir; elde edilen gelir de bu amacı sürdürmek için kullanılır. Kişisel kazanç amaçlayan ticari girişimciliktir."},{"id":"mg-5-s21","tur":"dogru-yanlis","soru":"Empati haritasına, kullanıcıyı gözlemleyerek ve dinleyerek öğrenilenler yazılır; girişimcinin tahminleri yazılmaz.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Harita kullanıcının ne gördüğünü, söylediğini, yaptığını ve hissettiğini bir araya getirir. Tahminle doldurulursa gerçek ihtiyaç görünmez ve harita amacına hizmet etmez."},{"id":"mg-5-s22","tur":"dogru-yanlis","soru":"Prototip denemesinde kullanıcılardan olumsuz görüş gelirse fikir hemen tümüyle bırakılmalıdır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Test, geri bildirime göre prototipi düzeltmek için yapılır. Olumsuz görüş fikrin hangi yanının değişmesi gerektiğini gösterir; erken fark edilen hata az masrafla düzeltilir, bu yüzden fikir hemen bırakılmaz."},{"id":"mg-5-s23","tur":"dogru-yanlis","soru":"Limited şirkette ortaklar kural olarak koymayı üstlendikleri sermaye kadar sorumlu olurken, şahıs işletmesinde sorumluluğun tümü sahibine aittir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Limited şirketin ortaklardan ayrı bir kişiliği vardır ve ortakların sorumluluğu kural olarak sermaye ile sınırlıdır. Şahıs işletmesinde işletme ile sahibi ayrılmaz; kazanç da sorumluluk da ona aittir."},{"id":"mg-5-s24","tur":"senaryo","durum":"Bir butik pansiyonda stajdasın. Saat 10.00, pansiyon sahibi konuklara rehberli bisiklet turu satmayı düşündüğünü söylüyor ve senin fikrini soruyor. Geçen hafta iki konuğun sana bisiklet kiralanacak yer sorduğunu hatırlıyorsun.","soru":"Ne dersin?","secenekler":["Bu işin kesin tutacağını, vakit kaybetmeden hemen bisiklet satın almasını söylerim.","İki konuğun sorduğunu aktarır, önce konuklara sorulmasını öneririm.","Bütün konukların bisiklet turu istediğini, her gün sorduklarını söylerim.","Stajyer olduğum için fikrimin olmadığını söyler, konuyu kapatırım."],"dogru":1,"aciklama":"Gördüğünü olduğu gibi aktarmak dürüstlüktür; iki konuğun sorması bir işarettir, ama kanıt değildir. Karardan önce konuklara sormak pazar araştırmasıdır ve hata maliyetini düşürür. “Kesin tutar” demek ya da gözlemi abartmak sahibini yanıltır; susmak ise işe yarayacak bir bilgiyi saklamaktır."},{"id":"mg-5-s25","tur":"senaryo","durum":"Girişimcilik projesinde grubunla çarşıdaki kahvaltı salonunun müşterilerini gözlemleyip empati haritası dolduracaksınız. Cuma akşamı bir grup arkadaşın “Gitmeye gerek yok, müşteri ne düşünür biz biliriz; haritayı evde doldururuz” diyor. Teslim pazartesi.","soru":"Nasıl davranırsın?","secenekler":["Kabul ederim; tahminlerimizi gözlem gibi yazarız.","Haritayı tek başıma internetten bulduğum bir örnekten kopyalarım.","Hiçbir şey demem, pazartesi öğretmene arkadaşımı şikâyet ederim.","Gözlemin şart olduğunu söyler, cumartesi birlikte gitmeyi öneririm."],"dogru":3,"aciklama":"Empati haritasına tahmin değil, görülen ve duyulan yazılır; gözlem yapılmadan doldurulan harita uydurma veridir. Kopyalamak da aynı yanlıştır. Sorunu zamanında, grupla konuşarak çözmek doğrusudur; susup sonradan şikâyet etmek işi de ekibi de kurtarmaz."},{"id":"mg-5-s26","tur":"senaryo","durum":"Grubun “yöresel sabun yapım atölyesi” fikrinin prototipini sınıfta denedi. Deneyen dört arkadaşın üçü atölyenin çok uzun sürdüğünü, sonunda sıkıldıklarını söyledi. Sunum yarın sabah 09.00’da.","soru":"Ne yaparsın?","secenekler":["Geri bildirimi not eder, grupla süreyi kısaltıp değişikliği sunumda anlatırım.","Arkadaşlarımın atölyeyi anlamadığını düşünür, hiçbir şeyi değiştirmem.","Fikrin tutmadığına karar verir, akşam baştan yeni bir fikir bulmaya çalışırım.","Sunumda testten hiç söz etmem, atölyeyi herkes beğenmiş gibi anlatırım."],"dogru":0,"aciklama":"Test bir sınav değil, öğrenme fırsatıdır: geri bildirime göre prototip düzeltilir. Eleştiriyi yok saymak testi anlamsız kılar; tek bir eleştiriyle fikri tümden bırakmak da gereksizdir. Sonucu saklamak ise dürüst değildir; neyi neden değiştirdiğini anlatmak sunumu güçlendirir."},{"id":"mg-5-s27","tur":"senaryo","durum":"Sınıftaki girişimcilik zirvesinde grubunuz küçük bir pansiyon projesi sunacak. Sunumdan yarım saat önce hesap tablosuna bakarken kira giderini yazmayı unuttuğunuzu fark ediyorsun. Kira eklenince proje ilk yıl kâr değil, zarar gösteriyor.","soru":"Ne yaparsın?","secenekler":["Kimse kirayı sormaz diye düşünür, tabloyu düzeltmeden sunarım.","Kârlı görünsün diye gelir tahminini biraz yükseltirim.","Grubuma söyler, tabloyu düzeltir ve gerçek sonucu sunarım.","Projeyi teslim etmeyip sunumdan çekilmeyi öneririm."],"dogru":2,"aciklama":"Fizibilite iyimser tahminle değil, gerçek giderlerle yapılır; “Bu hâliyle zarar ediyor” sonucu da değerli bir sonuçtur. Eksik gideri saklamak ya da geliri şişirmek yatırımcıyı yanıltmaktır. Hatayı düzeltip dürüstçe sunmak, girişimciye duyulan güvenin temelidir."},{"id":"mg-5-s28","tur":"senaryo","durum":"Hafta sonu bir yöresel kahvaltı salonunda kasada stajyersin. Saat 11.30, hesabını ödeyen bir müşteri sana eğilip “Fiş kesme, sen de bana biraz indirim yap” diyor. İşletme sahibi o sırada mutfakta.","soru":"Ne yaparsın?","secenekler":["Müşteri memnun ayrılsın ve yeniden gelsin diye fiş kesmeden küçük bir indirim yaparım.","Nazikçe fişini keserim; ısrar ederse işletme sahibine yönlendiririm.","Fişi keser, müşteriye vergi kaçırmaya çalıştığını herkesin duyacağı biçimde söylerim.","Parayı alır, fişi müşteri gittikten sonra keserim."],"dogru":1,"aciklama":"Her satış için fiş ya da fatura düzenlemek işletmenin yasal yükümlülüğüdür; fişsiz satış yasaya aykırıdır. İndirim kararı da stajyerin değil, işletme sahibinin yetkisindedir. Müşteriyi azarlamak hizmete yakışmaz; nazikçe kuralı uygulamak ve gerekirse sorumluya yönlendirmek doğrusudur."},{"id":"mg-5-s29","tur":"senaryo","durum":"Küçük bir seyahat acentesinde stajdasın. Saat 15.00, telefonla arayan biri tur satın almadan önce acentenin belgeli olup olmadığını ve belge numarasını soruyor. Acentenin belgelerini hiç görmedin; sorumlu müdür yan odada.","soru":"Ne yaparsın?","secenekler":["Acentenin belgeli olduğunu söyler, aklıma gelen bir numara veririm.","Bu bilginin gizli olduğunu, veremeyeceğimi söylerim.","Stajyer olduğumu, bilmediğimi söyleyip telefonu kapatırım.","Kısa bir süre beklemesini rica eder, doğru bilgiyi müdürden alırım."],"dogru":3,"aciklama":"Seyahat acentesi Kültür ve Turizm Bakanlığından işletme belgesi alır ve TÜRSAB’a üye olur; müşterinin bunu sorması yerindedir ve belge bilgisi gizli değildir. Bilmediğin bir şeyi tahminle söylemek müşteriyi yanıltır; soruyu cevapsız bırakmak da güveni sarsar. Doğrusu bilgiyi yetkiliden alıp aktarmaktır."},{"id":"mg-5-s30","tur":"senaryo","durum":"Bir aile pansiyonunda stajdasın. Saat 19.00, pansiyon sahibi o günün alışveriş fişlerini gider defterine yazman için sana verdi. Yazarken manavdan alınan sebzelerin fişinin eksik olduğunu fark ediyorsun; tutarını hatırlamıyorsun.","soru":"Ne yaparsın?","secenekler":["Fişin eksik olduğunu pansiyon sahibine hemen söylerim.","Aşağı yukarı bir tutar tahmin edip deftere yazarım.","Küçük bir tutar olduğu için o alışverişi deftere hiç yazmam.","Öteki fişlerden birinin tutarını yükselterek farkı kapatırım."],"dogru":0,"aciklama":"Her gelir ve gider belgesiyle kaydedilir; işletme parasının nereye gittiğini bu kayıtlardan görür. Tahmini rakam yazmak, kalemi atlamak ya da başka fişi değiştirmek kaydı yanlış kılar. Eksikliği zamanında bildirmek sorumluluktur; nasıl düzeltileceğine işletme sahibi karar verir."},{"id":"mg-5-s31","tur":"senaryo","durum":"Sınıf projesinde grubunla bir pansiyon için tanıtım broşürü hazırlıyorsun. Pansiyon denize yürüyerek yirmi dakika uzakta. Bir arkadaşın “Başlığa denize sıfır yazalım, kimse ölçmez; böyle daha çok satar” diyor.","soru":"Ne önerirsin?","secenekler":["Tanıtımda biraz abartı olur diye düşünür, “denize sıfır” yazmayı kabul ederim.","Uzaklığı hiç yazmamayı, deniz fotoğrafını büyük koymayı öneririm.","Gerçek uzaklığı yazıp gerçek güçlü yanı öne çıkarmayı öneririm.","Broşür işinden çekilir, kararı öteki arkadaşlara bırakırım."],"dogru":2,"aciklama":"Tanıtımda olmayan bir şeyi vaat etmek konuğu bir kez getirir, kötü yorumla geri gönderir; değer önerisi konuğa verilmiş bir sözdür. Uzaklığı gizleyip fotoğrafla yanıltmak da aynı sonuca çıkar. Dürüst tanıtım, gerçek güçlü yanı öne çıkarır ve işin sürdürülebilirliğini korur."},{"id":"mg-5-s32","tur":"coktan-secmeli","soru":"Bir pansiyonda bu gece boş kalan oda, yarın iki kez satılamaz; o gecenin geliri geri gelmez. Bu durum hizmetin hangi özelliğini gösterir?","secenekler":["Elle tutulur bir mal olmasını","Depolanamamasını","Ucuz olmasını","Fiyatının hep aynı kalmasını"],"dogru":1,"aciklama":"Hizmet depolanamaz: satılmayan gece saklanıp sonra satılamaz. Hizmet elle tutulur bir mal değildir; bu yüzden ilk şık yanlıştır."},{"id":"mg-5-s33","tur":"coktan-secmeli","soru":"Bir pansiyon sahibi, deneyimli bir kat görevlisini işe alıyor ve ona konuk karşılama eğitimi aldırıyor. Pansiyon sahibi girişiminin hangi kaynağını güçlendirmektedir?","secenekler":["Finansal kaynak","Fiziksel kaynak","Beşerî kaynak","Doğal kaynak"],"dogru":2,"aciklama":"Çalışanlar ve onların bilgi, beceri ve emeği beşerî kaynaktır. Fiziksel kaynak ise bina, araç gereç ve malzeme gibi elle tutulur varlıklardır."},{"id":"mg-5-s34","tur":"dogru-yanlis","soru":"Bir ay boyunca kahvaltı salonunun giderleri gelirinden fazla olduysa salon o ay zarar etmiştir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Gider gelirden fazlaysa aradaki fark zarardır; gelir giderden fazla olsaydı kâr edilmiş olurdu."},{"id":"mg-5-s35","tur":"coktan-secmeli","soru":"Atölyede üretimin neden durduğunu bulmak isteyen grup, tahtaya önce ana sorunu yazıyor; sonra olası nedenleri para, makine, çalışan, planlama ve yönetim başlıkları altında ana sorundan çıkan dallara ekliyor. Grup hangi yöntemi kullanmaktadır?","secenekler":["SWOT analizi","Empati haritası","Altı şapkalı düşünme tekniği","Balık kılçığı analizi"],"dogru":3,"aciklama":"Balık kılçığı analizi, bir ana sorunun nedenlerini kaynak, planlama ve yönetim gibi başlıklara ayırarak gösterir. SWOT ise nedenleri değil, güçlü ve zayıf yönler ile fırsat ve tehditleri inceler."},{"id":"mg-5-s36","tur":"coktan-secmeli","soru":"Bir otel, konukların kayıt bilgilerini gelmeden önce telefondan göndermesini sağlıyor; konuk artık resepsiyonda uzun süre beklemiyor. Bu yenilik hangi inovasyon türüdür?","secenekler":["Ürün inovasyonu","Pazarlama inovasyonu","Süreç inovasyonu","Organizasyonel inovasyon"],"dogru":2,"aciklama":"Sunulan hizmet aynı kalmış, hizmetin sunulma yöntemi hızlanmıştır; bu süreç inovasyonudur. Ürün inovasyonunda ise konuğa yeni bir mal ya da hizmet sunulur."},{"id":"mg-5-s37","tur":"dogru-yanlis","soru":"Küçük bir otelin her sabah kısa bir ekip toplantısı başlatması gibi çalışma düzenindeki yenilikler, konuk tarafından görülmediği için inovasyon sayılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Çalışma düzenindeki yeni yöntem organizasyonel inovasyondur. Dışarıdan görünmese de bilgi ekipte daha hızlı dolaştığı için hizmete yansır."},{"id":"mg-5-s38","tur":"coktan-secmeli","soru":"Bir kasabada yeni bir tren durağı açılıyor ve hafta sonları gezginler gelmeye başlıyor; ancak çarşıda bisiklet kiralanacak bir yer yok. Bisiklet kiralama işi kurmak isteyen biri için bu durum neyi ifade eder?","secenekler":["Fırsat","Risk","Hata maliyeti","Arz"],"dogru":0,"aciklama":"Karşılanmamış bir ihtiyaç yeni bir iş için elverişli ortam oluşturuyorsa bu bir fırsattır. Risk ise istenmeyen bir sonucun ortaya çıkma ihtimalidir."},{"id":"mg-5-s39","tur":"coktan-secmeli","soru":"Kano turu yapan bir işletme grupları küçük tutuyor ve koylara çöp bırakmamaya özen gösteriyor; çünkü doğa bozulursa satacak tur kalmayacağını biliyor. İşletme bu davranışla iş fikrinin hangi özelliğini korur?","secenekler":["Pazar potansiyelinin büyüklüğünü","Sürdürülebilirliğini","Özgünlüğünü","Yenilikçiliğini"],"dogru":1,"aciklama":"Kaynaklarını tüketmeden ve çevresine zarar vermeden uzun yıllar ayakta kalabilmek sürdürülebilirliktir. Pazar potansiyeli ise işi satın alabilecek müşteri sayısıyla ilgilidir."},{"id":"mg-5-s40","tur":"coktan-secmeli","soru":"Pansiyon açmayı düşünen bir girişimci, olası bir yanlış kararın kendisine en az kaybettirmesini istiyor. Hangi yolu seçmelidir?","secenekler":["Fikri küçük bir denemeyle sınamak","Bütün birikimi tek seferde yatırmak","Rakibi birebir taklit etmek","Pahalı ekipmanı açılıştan önce almak"],"dogru":0,"aciklama":"Hata ne kadar erken fark edilirse o kadar ucuza düzeltilir; küçük bir deneme bunu sağlar. Ekipmanı baştan almak ise yanılınca kaybı büyütür."},{"id":"mg-5-s41","tur":"dogru-yanlis","soru":"Tasarım odaklı düşünmenin empati kurma aşamasında amaç, kullanıcının sorununa hemen bir çözüm bulmaktır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Empati kurma aşamasında çözüm aranmaz; kullanıcı gözlenir, dinlenir ve ihtiyacı anlaşılır. Çözümler fikir üretme aşamasında ortaya atılır."},{"id":"mg-5-s42","tur":"coktan-secmeli","soru":"Bir otelde konuklar “Kahvaltı servisi çok yavaş.” diye şikâyet ediyor. Müdür sabah salonu gözlemleyince bütün tur gruplarının aynı saatte kahvaltıya indiğini ve masaların yetmediğini görüyor. Bu durum hangi ayrıma örnektir?","secenekler":["Görünen sorun ile asıl problem","Ürün inovasyonu ile süreç inovasyonu","Güçlü yön ile zayıf yön","Geleneksel yaklaşım ile tasarım odaklı düşünme"],"dogru":0,"aciklama":"Konuğun dile getirdiği sorun ile gözlemle ortaya çıkan gerçek sorun farklı olabilir; burada asıl problem aynı saatteki yığılmadır. Doğru çözüm, gözlemle bulunan asıl probleme göre geliştirilir."},{"id":"mg-5-s43","tur":"coktan-secmeli","soru":"Bisiklet turu işletmesi turlarını anlaştığı pansiyonlar, sosyal medya hesabı ve telefon aracılığıyla satıyor. Bu yollar iş modeli kanvasında hangi kutuya yazılır?","secenekler":["Gelir modeli","Değer önerisi","Pazar","Kanallar"],"dogru":3,"aciklama":"İşletmenin müşterisine ulaşmak, ürününü tanıtmak ve satmak için kullandığı yollar kanallardır. Gelir modeli ise paranın hangi yollarla ve kimden kazanılacağını gösterir."},{"id":"mg-5-s44","tur":"coktan-secmeli","soru":"Küçük bir acente, başka şirketlerin hazırladığı turları satıyor ve sattığı her turdan komisyon kazanıyor. Bu bilgi iş modelinin hangi öğesini anlatır?","secenekler":["Maliyet yapısı","Gelir modeli","Finansman kaynağı","Kanallar"],"dogru":1,"aciklama":"Komisyon, acentenin parayı hangi yolla kazandığını gösterir; bu gelir modelidir. Finansman kaynağı ise işi kurmak için gereken paranın nereden bulunduğudur."},{"id":"mg-5-s45","tur":"coktan-secmeli","soru":"Kahvaltı salonunun giderlerinden hangisi, o ay hiç satış olmasa da ödenmesi gereken sabit maliyete örnektir?","secenekler":["Gözleme için alınan un","Aylık dükkân kirası","Çay şekeri","Satılan reçel kavanozları"],"dogru":1,"aciklama":"Kira, satış olsa da olmasa da ödenen sabit maliyettir. Un, şeker ve reçel gibi malzemeler satışla birlikte arttığı için değişken maliyettir."},{"id":"mg-5-s46","tur":"dogru-yanlis","soru":"Finansal fizibilite çalışmasının “Bu iş olmaz.” sonucuna varması da girişimci için değerli bir sonuçtur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Fizibilite, işe başlamadan önce işin yapılabilir ve kazançlı olup olmadığını gösterir. Olmayacak bir işi baştan görmek, birikimin boşa gitmesini önler."},{"id":"mg-5-s47","tur":"coktan-secmeli","soru":"Bir otel grubu birçok şehirde otel açmak için çok sayıda ortağı bir araya getirecek ve anonim şirket kuracak. Bu tercihin nedeni olarak hangisi doğrudur?","secenekler":["Tek bir kişinin kurduğu, sorumluluğun tümüyle sahibine ait olduğu tür olması","Ortakların kişisel mal varlığıyla sınırsız sorumlu olduğu tür olması","Sermayesinin paylara bölünmesi ve çok sayıda ortağın pay alabilmesi","Yalnız iki ortakla kurulup büyüyemeyen bir tür olması"],"dogru":2,"aciklama":"Anonim şirketin sermayesi paylara bölünür ve çok sayıda ortak bir araya gelebilir; bu yüzden büyük yatırımlara uygundur. Sorumluluğun tümüyle sahibinde olması ise şahıs işletmesinin özelliğidir."},{"id":"mg-5-s48","tur":"coktan-secmeli","soru":"İki arkadaşın kurduğu acentenin adı, ortakları ve adresi resmî olarak kaydediliyor ve şirket bu kayıtla resmen kurulmuş oluyor. Bu kayıt nerede yapılır?","secenekler":["Ticaret sicili müdürlüğü","Belediye","Sosyal Güvenlik Kurumu","Kültür ve Turizm Bakanlığı"],"dogru":0,"aciklama":"Şirketin kuruluş, ortak ve adres bilgileri ticaret siciline işlenir; bu tescille şirket resmen kurulur. Bakanlıktan ise acentenin işletme belgesi alınır."},{"id":"mg-5-s49","tur":"coktan-secmeli","soru":"Küçük bir acente bir otelle çalışmaya başlarken otelin muhasebesi, acentenin bağlı olduğu daireyi, kayıt numarasını ve faaliyet konusunu gösteren belgenin bir örneğini istiyor. Bu belge hangisidir?","secenekler":["İş yeri açma ve çalışma ruhsatı","İş yeri bildirgesi","İş planı","Vergi levhası"],"dogru":3,"aciklama":"Vergi levhası, işletmenin bağlı olduğu vergi dairesini, vergi numarasını ve faaliyet konusunu gösterir. Ruhsat ise iş yerinin sağlık ve güvenlik kurallarına uygun olduğunu gösteren izindir."},{"id":"mg-5-s50","tur":"dogru-yanlis","soru":"Bir otelde mevsimlik çalışan garsonun yalnız işe girişi SGK’ya bildirilir; sezon sonunda işten ayrılışının bildirilmesi gerekmez.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"İşveren, çalışanın hem işe başlamasını hem de işten ayrılmasını SGK’ya elektronik ortamda bildirir."}],"siralamalar":[{"id":"mg-5-r02","konu":"5.3","baslik":"Kantin kuyruğunu tasarımla çözmek","yonerge":"Okul kantinindeki uzun bekleme sorununu tasarım odaklı düşünmeyle çözerken izlenen adımları doğru sıraya koy.","adimlar":["Kantinde öğrencileri ve çalışanları gözlemle, beklemenin hangi saatlerde arttığını araştır.","Topladığın bilgileri inceleyip çözülmesi gereken asıl sorunu açıkça yaz.","Bu sorun için birden çok farklı çözüm seçeneği üret ve bunları karşılaştır.","Seçtiğin sipariş fikrinin ekranlarını kâğıda çizerek basit bir taslak hazırla.","Kâğıt taslağı öğrencilerin denemesini sağla ve geri bildirimlerini topla.","Gelen geri bildirimlere göre çözümünü yeniden düzenle."],"aciklama":"Tasarım odaklı düşünme Anla → Tanımla → Fikir üret → Prototip oluştur → Test et → Öğren ve geliştir sırasıyla ilerler. Gerekirse önceki aşamalara dönülür, ama kullanıcıyı anlamadan sorun tanımlanamaz, denenecek bir taslak olmadan da test yapılamaz."}],"acikSorular":[{"id":"mg-5-y01","konu":"5.3","soru":"Bir otelde çalışan arkadaşınız, konukların odada şarj noktası bulamadığından yakındığını duyuyor ve bir çözüm geliştirmek istiyor. Tasarım odaklı düşünmenin empati kurma, problemi tanımlama ve prototip oluşturma aşamalarını bu örnek üzerinden açıklayınız. Konuk ihtiyacından yola çıkmanın neden önemli olduğunu belirtiniz.","olcut":[{"metin":"Empati kurma aşamasını konukları gözlemleyip dinleyerek ihtiyacı anlamak olarak açıklar.","puan":20},{"metin":"Problemi tanımlama aşamasını toplanan gözlemlerden açık ve tek bir sorun cümlesi yazmak olarak örneğe uygular.","puan":20},{"metin":"Prototip aşamasını çözümün hızlı ve ucuz bir ilk örnekle denenmesi olarak örneğe uygular.","puan":20},{"metin":"Kullanıcı ihtiyacından yola çıkmanın neden önemli olduğunu (ihtiyaç duyulmayan ürün değer üretmez, yanlış karar hata maliyetini artırır) nedeniyle açıklar.","puan":40}],"ornek":"Empati kurmada konukların odada telefonlarını nasıl şarj ettiğini gözlemler ve onlarla konuşurum. Problemi tanımlamada örneğin “konuklar yatak başında şarj noktası bulamıyor” diye tek bir cümle yazarım. Prototip aşamasında kâğıt ya da basit bir model hazırlayıp bir odada denerim. Konuğun ihtiyacından başlamak önemlidir, çünkü konuğun ihtiyaç duymadığı bir çözüm değer üretmez; ürünü kendi varsayımımıza göre hazırlarsak yanlış karar vermiş oluruz ve para, zaman ve emek kaybederiz, yani hata maliyeti artar.","ipucu":"Her aşamayı yalnız tanımlamayın, örnekteki konuğa göre ne yapılacağını yazın; sonra yanlış kararın neye mal olduğunu düşünün."},{"id":"mg-5-y02","konu":"5.5","soru":"Bir arkadaşınız mezun olunca kendi küçük pansiyonunu açmak istiyor. İşletmeyi kurarken yerine getirmesi gereken iki yasal yükümlülüğü yazınız, her birinin ne işe yaradığını açıklayınız. Kuruluştan sonra nakit akışını takip etmenin neden gerekli olduğunu belirtiniz.","olcut":[{"metin":"Birinci yasal yükümlülüğü (örneğin vergi kaydı ya da ticaret sicili) doğru yazar ve işlevini açıklar.","puan":25},{"metin":"İkinci yasal yükümlülüğü (örneğin iş yeri açma ve çalışma ruhsatı ya da SGK bildirimi) doğru yazar ve işlevini açıklar.","puan":25},{"metin":"Nakit akışını işletmeye giren ve çıkan paranın hareketi olarak tanımlar.","puan":15},{"metin":"Nakit akışının takip edilmesinin işletmenin ödemelerini yapıp ayakta kalmasıyla bağlantısını nedeniyle açıklar.","puan":35}],"ornek":"Yasal yükümlülüklerden biri vergi kaydıdır; işletme vergi dairesine kaydolur ve vergisini öder. Bir diğeri iş yeri açma ve çalışma ruhsatıdır; belediyenin verdiği bu izin, iş yerinin sağlık ve güvenlik kurallarına uygun olduğunu gösterir. Nakit akışı, işletmenin kasasına giren ve çıkan paranın hareketidir. Bunu takip etmek gerekir, çünkü gelirler gelmeden kira, maaş ve fatura gibi giderler önce ödenebilir; para akışı izlenmezse işletme ödemelerini yapamaz ve sürdürülemez.","ipucu":"Belgeyi hangi kurumun verdiğini ve işletmeye ne sağladığını düşünün; nakit akışında gelir ile giderin zamanlamasına bakın."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":6,"baslik":"Fikrî ve Sınai Mülkiyet Hakları","onay":true,"kazanimlar":["Fikrî ve sınai mülkiyet haklarını ürün ve hizmet örnekleri ile çözümleyebilme.","Özgün bir fikrin veya ürünün korunmasının önemini değerlendirebilme.","Patent bilgi kaynaklarını kullanarak bir buluşun mevcut teknolojilerle ilişkisini ve ekonomik etkilerini sorgulayabilme.","Fikrî veya sınai mülkiyet hakkı başvuru sürecini yapılandırabilme."],"soz":"Fikir de emektir; izinsiz alınan fikir, izinsiz alınan eşyadan farksızdır.","dersler":[{"baslik":"Fikrin Sahibi Olur mu?","ilk":"mg-6-001"},{"baslik":"Eser Sahibinin İki Hakkı","ilk":"mg-6-005"},{"baslik":"Buluş Kimin, Patent Ne?","ilk":"mg-6-008"},{"baslik":"Tabeladaki İsim, Raftaki Biçim","ilk":"mg-6-014"},{"baslik":"Baklava Neden Antep’in?","ilk":"mg-6-018"},{"baslik":"Bir Üründe Kaç Hak Saklı?","ilk":"mg-6-022"},{"baslik":"Lobide Çalan Şarkı Kimin?","ilk":"mg-6-035"},{"baslik":"Serbest Kullanımın Kuralları","ilk":"mg-6-039"},{"baslik":"Hakkı Kim Kayda Geçirir?","ilk":"mg-6-041"},{"baslik":"Yeni mi, Ayırt Edici mi?","ilk":"mg-6-051"},{"baslik":"Kopyala-Yapıştırın Bedeli","ilk":"mg-6-011"},{"baslik":"Taklidin Bedeli","ilk":"mg-6-027"},{"baslik":"İzin Almanın Yolu: Lisans","ilk":"mg-6-031"},{"baslik":"Yaratıcılığı Kim Korur?","ilk":"mg-6-034"},{"baslik":"Adil Rekabet, Uzun Ömür","ilk":"mg-6-070"},{"baslik":"Koruma Nerede Biter?","ilk":"mg-6-042"},{"baslik":"Sınırı Aşan Koruma","ilk":"mg-6-046"},{"baslik":"Patent Dedektifliği","ilk":"mg-6-052"},{"baslik":"Belgenin Satır Arası","ilk":"mg-6-058"},{"baslik":"Başvuru Yol Haritası","ilk":"mg-6-059"},{"baslik":"Başvurudan Sonra Ne Olur?","ilk":"mg-6-062"},{"baslik":"Fikirden Eylem Planına","ilk":"mg-6-065"}],"kavramlar":[{"id":"mg-6-001","konu":"6.1","terim":"Fikrî mülkiyet","ingilizce":"Intellectual property","tanim":"İnsanın zihin emeğiyle ortaya koyduğu eser, buluş, marka ve tasarım gibi ürünler üzerindeki haklarının genel adıdır.","ornek":"Bir otelin adı ve logosu, tanıtım filmi, internet sitesindeki fotoğrafları ve yazıları: hiçbiri elle tutulmaz, ama hepsinin bir sahibi vardır.","sektor":"Programın anahtar kavramlarındandır. İki ana kolu vardır: fikir ve sanat eserleri üzerindeki haklar (telif hakkı) ile sınai mülkiyet hakları. Dar anlamda yalnız telif hakkı için de kullanılır. Turizmde ürün çoğu zaman bir deneyimdir; onu rakipten ayıran şey de çoğunlukla bu görünmeyen varlıklardır.","iliskili":["mg-6-002","mg-6-008","mg-6-023"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-002","konu":"6.1","terim":"Telif hakkı","ingilizce":"Copyright","tanim":"Bir fikir ya da sanat eserini meydana getiren kişinin, o eser üzerinde kanunla korunan haklarının bütünüdür.","ornek":"Bir fotoğrafçı Kapadokya’da gün doğumunda balonları çeker; fotoğraf çekildiği anda hak onundur, kimse izinsiz broşürüne basamaz.","sektor":"Programın anahtar kavramlarındandır. Telif hakkı eser ortaya çıktığı anda kendiliğinden doğar; bir kuruma başvurmak gerekmez. Türkiye’de koruma eser sahibinin yaşamı boyunca ve ölümünden sonra 70 yıl sürer. Korunan şey fikrin kendisi değil, o fikrin ifade ediliş biçimidir.","iliskili":["mg-6-003","mg-6-004","mg-6-005"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-003","konu":"6.1","terim":"Eser","ingilizce":"Work","tanim":"Sahibinin kişisel özelliğini taşıyan ve kanunun saydığı türlerden birine giren fikir ve sanat ürünüdür.","ornek":"Bir otelin tanıtım filmi, lobide asılı yağlı boya tablo, restoranda çalan şarkı ve rezervasyon için yazılmış bilgisayar programı birer eserdir.","sektor":"Programın anahtar kavramlarındandır. Kanun eserleri dört grupta toplar: ilim ve edebiyat eserleri (bilgisayar programları dâhil), müzik eserleri, güzel sanat eserleri (fotoğraf dâhil) ve sinema eserleri. Otelde her gün kullandığın pek çok şey bu gruplardan birine girer.","iliskili":["mg-6-002","mg-6-004","mg-6-037"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-004","konu":"6.1","terim":"Eser sahibi","ingilizce":"Author","tanim":"Bir eseri kendi emeği ve yaratıcılığıyla meydana getiren kişidir.","ornek":"Okulun gezi kulübü için çektiğin ve kurguladığın kısa videonun eser sahibi sensin; videoyu izinsiz kendi adıyla paylaşan kişi hakkını çiğnemiş olur.","sektor":"Programın anahtar kavramlarındandır. Yazar, besteci, fotoğrafçı, ressam, yazılımcı: hepsi eser sahibidir. Bir fotoğrafı satın almak ya da internette bulmak seni onun sahibi yapmaz; kullanmak için eser sahibinin izni gerekir.","iliskili":["mg-6-003","mg-6-006","mg-6-007"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-005","konu":"6.1","terim":"Fikir ve Sanat Eserleri Kanunu","ingilizce":"Law on Intellectual and Artistic Works (Law No. 5846)","tanim":"Türkiye’de eserleri ve eser sahiplerinin haklarını koruyan, 1951 tarihli ve 5846 sayılı kanundur.","ornek":"Bir otel, tanıtım broşüründe bir fotoğrafçının karesini izinsiz kullanırsa fotoğrafçı haklarını bu kanuna dayanarak arar.","sektor":"Telif hakkıyla ilgili işlerde yetkili kurum Kültür ve Turizm Bakanlığına bağlı Telif Hakları Genel Müdürlüğüdür. Eser sahibinin haklarını kanun iki grupta toplar: manevi haklar ve mali haklar.","iliskili":["mg-6-002","mg-6-006","mg-6-007"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-006","konu":"6.1","terim":"Manevi haklar","ingilizce":"Moral rights","tanim":"Eser sahibinin eseriyle arasındaki kişisel bağı koruyan; eserin kamuya sunulup sunulmayacağına karar verme, adının belirtilmesini isteme ve eserin izinsiz değiştirilmesini önleme haklarıdır.","ornek":"Bir otel, parasını ödeyip aldığı fotoğrafı internet sitesinde kullanırken fotoğrafçı izin vermedikçe onun adını silemez ve fotoğrafı özünü bozacak biçimde değiştiremez.","sektor":"Manevi haklar eser sahibine bağlıdır; başkasına devredilemez. Bu yüzden bir görseli kullanma izni almış olsan bile, aksi kararlaştırılmadıkça sahibinin adını anmak ve eseri bozmamak gerekir.","iliskili":["mg-6-004","mg-6-007","mg-6-026"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-007","konu":"6.1","terim":"Mali haklar","ingilizce":"Economic rights","tanim":"Eser sahibinin eserinden gelir elde etmesini sağlayan; eseri çoğaltma, yayma, temsil etme, işleme ve kamuya iletme haklarıdır.","ornek":"Bir besteci, şarkısının otellerde ve restoranlarda çalınmasına izin verir ve bunun karşılığında bedel alır.","sektor":"Mali haklar sözleşmeyle başkasına devredilebilir ya da lisansla kullandırılabilir. Otelin broşüre bir fotoğraf basması eseri çoğaltmak, lobide müzik çalması eseri halka açık yerde kullanmaktır; ikisi de izne bağlıdır.","iliskili":["mg-6-006","mg-6-031","mg-6-036"],"kontrol":null,"cizim":"doga"},{"id":"mg-6-008","konu":"6.1","terim":"Sınai mülkiyet","ingilizce":"Industrial property","tanim":"Sanayi ve ticaret alanındaki buluşlar, markalar, tasarımlar ve coğrafi işaretler üzerindeki hakların genel adıdır.","ornek":"Bir bavul üreticisi kilit düzeneği için patent, bavulun görünümü için tasarım, üstündeki ad için marka tescili alır: üçü de sınai mülkiyet hakkıdır.","sektor":"Programın anahtar kavramlarındandır. Kabaca ayrım şöyledir: telif hakkı yazarın ve sanatçının emeğini, sınai mülkiyet ise sanayi ve ticaretteki buluş, tasarım ve markaları korur. Telif hakkından farklı olarak koruma kural olarak tescille elde edilir.","iliskili":["mg-6-001","mg-6-009","mg-6-041"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-009","konu":"6.1","terim":"Sınai Mülkiyet Kanunu","ingilizce":"Industrial Property Law (Law No. 6769)","tanim":"Türkiye’de marka, coğrafi işaret, tasarım, patent, faydalı model ve geleneksel ürün adlarını koruyan, 2017’de yürürlüğe giren 6769 sayılı kanundur.","ornek":"Yeni açılan bir butik otel adını marka olarak tescil ettirmek istediğinde başvurusu bu kanuna göre incelenir.","sektor":"Bu kanundan önce her hak türü ayrı düzenlemelerle korunuyordu; kanun hepsini tek metinde topladı. Başvuruları alan ve tescili yapan kurum Türk Patent ve Marka Kurumudur.","iliskili":["mg-6-008","mg-6-042","mg-6-044"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-010","konu":"6.1","terim":"Buluş","ingilizce":"Invention","tanim":"Teknik bir soruna getirilen, daha önce bilinmeyen yeni bir çözümdür.","ornek":"Bavulun altına tekerlek takmak bir zamanlar bir buluştu: “Ağır bavul nasıl kolay taşınır?” sorusuna teknik bir cevap verdi.","sektor":"Buluş ile keşif karıştırılmamalıdır: doğada zaten var olan bir şeyi bulmak keşiftir ve patentle korunmaz. Bilimsel kuramlar, matematik yöntemleri ve yalnızca bir fikir olarak kalan düşünceler de patent alamaz.","iliskili":["mg-6-011","mg-6-012","mg-6-051"],"kontrol":null,"gorsel":"m6-ucan-araba"},{"id":"mg-6-012","konu":"6.1","terim":"Patent","ingilizce":"Patent","tanim":"Bir buluşun sahibine, o buluşu belirli bir süre boyunca yalnız kendisinin üretmesi, kullanması ve satması için devletin verdiği hak ve bu hakkı gösteren belgedir.","ornek":"Bir firma, otel odaları için kartı çıkarınca elektriği kesen yeni bir enerji tasarrufu düzeneği geliştirir ve patentini alır; rakipleri bunu izinsiz üretemez.","sektor":"Programın anahtar kavramlarındandır. Türkiye’de patent koruması başvuru tarihinden başlayarak 20 yıldır ve uzatılamaz. Karşılığında buluş herkesin okuyabileceği biçimde yayımlanır: süre dolunca herkes serbestçe kullanır, böylece bilgi topluma kalır.","iliskili":["mg-6-010","mg-6-013","mg-6-051"],"kontrol":null,"gorsel":"m6-benz-motorwagen"},{"id":"mg-6-013","konu":"6.1","terim":"Faydalı model","ingilizce":"Utility model","tanim":"Var olan bir ürüne kullanım kolaylığı ya da pratik bir yarar katan yeni teknik çözümlere verilen, patente göre daha kısa süreli korumadır.","ornek":"Kat arabasına, havluların düşmesini önleyen katlanır bir raf eklenir; sıfırdan bir buluş değil, mevcut araçta pratik bir iyileştirmedir.","sektor":"Programın anahtar kavramlarındandır. Türkiye’de koruma süresi 10 yıldır. Patentten farkı: yenilik ve sanayiye uygulanabilirlik aranır, buluş basamağı aranmaz. Üretim yöntemleri faydalı modelle korunmaz.","iliskili":["mg-6-012","mg-6-052","mg-6-053"],"kontrol":null},{"id":"mg-6-014","konu":"6.1","terim":"Marka","ingilizce":"Trade mark","tanim":"Bir işletmenin mal ya da hizmetlerini başka işletmelerinkinden ayırmaya yarayan ad, sözcük, şekil, renk, ses gibi işaretlerdir.","ornek":"Otelin tabeladaki adı, havlulara işlenen logosu ve broşürdeki sloganı: konuk bunları görünce hangi otelde olduğunu bilir.","sektor":"Programın anahtar kavramlarındandır. Logo, markanın şekille gösterilen hâlidir ve o da tescil ettirilebilir. Türkiye’de marka tescili 10 yıl korur ve onar yıllık dönemlerle yenilenebilir; yenilendikçe süresiz yaşar. Otelin en değerli varlıklarından biri adıdır: konuk o ada güvenerek rezervasyon yapar.","iliskili":["mg-6-015","mg-6-016","mg-6-061"],"kontrol":null,"cizim":"marka"},{"id":"mg-6-015","konu":"6.1","terim":"Hizmet markası","ingilizce":"Service mark","tanim":"Bir işletmenin sunduğu hizmetleri başka işletmelerin hizmetlerinden ayırt etmeye yarayan markadır.","ornek":"Otel, seyahat acentesi, hava yolu ve restoran adları birer hizmet markasıdır; raftaki bir meyve suyunun adı ise ticaret markasıdır.","sektor":"Turizm işletmeleri mal değil hizmet sattığı için markaları hizmet markasıdır. Marka başvurusunda hangi hizmetler için koruma istendiği ayrıca belirtilir: konaklama, yiyecek içecek, seyahat düzenleme gibi.","iliskili":["mg-6-014","mg-6-016","mg-6-061"],"kontrol":null},{"id":"mg-6-016","konu":"6.1","terim":"Ayırt edici nitelik","ingilizce":"Distinctiveness","tanim":"Bir markanın ya da tasarımın, benzerlerinden kolayca ayrılmasını sağlayan kendine özgü olma özelliğidir.","ornek":"Bir otele yalnızca “Güzel Otel” ya da “Deniz Manzaralı Otel” adını vermek onu öbürlerinden ayırmaz; herkesin kullanabileceği bir tanıtım sözüdür.","sektor":"Yalnızca hizmetin türünü ya da niteliğini anlatan, herkesin kullandığı sözler tek başına marka olarak tescil edilmez. Ad seçerken soru şudur: konuk bu adı duyunca yalnız bizi mi hatırlar?","iliskili":["mg-6-014","mg-6-017","mg-6-061"],"kontrol":null,"cizim":"marka"},{"id":"mg-6-017","konu":"6.1","terim":"Endüstriyel tasarım","ingilizce":"Industrial design","tanim":"Bir ürünün ya da ürün parçasının çizgi, biçim, renk, doku gibi özelliklerinden oluşan dış görünümüdür.","ornek":"Bir otelin kendine özel çizdirdiği lobi koltuğu, çay bardağı ya da buklet şampuan şişesinin biçimi.","sektor":"Programın anahtar kavramlarındandır. Kanunda kısaca “tasarım” diye geçer. Tasarım, ürünün nasıl çalıştığını değil, nasıl göründüğünü korur. Tescil için yeni olması ve ayırt edici nitelik taşıması gerekir; tescil beşer yıllık dönemlerle yenilenerek toplam 25 yıla kadar korur.","iliskili":["mg-6-016","mg-6-012","mg-6-023"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-018","konu":"6.1","terim":"Coğrafi işaret","ingilizce":"Geographical indication","tanim":"Belirgin bir niteliği, ünü ya da başka özelliği bakımından kökeninin bulunduğu yöreyle özdeşleşmiş ürünü gösteren işarettir.","ornek":"Antep baklavası, Aydın inciri ve Malatya kayısısı coğrafi işaretle korunan ürünlerdir.","sektor":"Programın anahtar kavramlarındandır. Markadan farkı: tek bir kişiye ya da firmaya ait değildir; ürünü tescildeki şartlara uygun üreten herkes kullanabilir. Menşe adı ve mahreç işareti olarak ikiye ayrılır; koruması bir süreyle sınırlı değildir. Gastronomi turizminde bir yörenin en güçlü tanıtım aracıdır.","iliskili":["mg-6-019","mg-6-020","mg-6-021"],"kontrol":null},{"id":"mg-6-019","konu":"6.1","terim":"Menşe adı","ingilizce":"Designation of origin","tanim":"Bütün özelliklerini belirli bir yörenin doğasından ve insanından alan, üretimi, işlenmesi ve diğer işlemlerinin tamamı o yörede yapılan ürünleri gösteren coğrafi işarettir.","ornek":"Aydın inciri ve Malatya kayısısı menşe adıdır: meyve o yörenin toprağında ve ikliminde yetişir, başka yerde yetişen ürün bu adı taşıyamaz.","sektor":"Menşe adı taşıyan ürün yöresinden koparılamaz; onu yerinde görmek ve tatmak isteyen ziyaretçi için başlı başına bir seyahat nedenidir. Otelin kahvaltısında yörenin tescilli ürününü adıyla sunmak konuğa bir hikâye anlatır.","iliskili":["mg-6-018","mg-6-020","mg-6-021"],"kontrol":null,"gorsel":"m6-malatya-kayisisi"},{"id":"mg-6-020","konu":"6.1","terim":"Mahreç işareti","ingilizce":"Protected geographical indication (PGI)","tanim":"Bir yöreyle özdeşleşmiş olan ve üretim, işleme ya da diğer işlemlerinden en az biri o yörede yapılan ürünleri gösteren coğrafi işarettir.","ornek":"Antep baklavası mahreç işaretidir: ürün Gaziantep’le özdeşleşmiştir ve tescilde yazılı malzeme ile yönteme uyularak yapılır.","sektor":"Menşe adından farkı, işlemlerin tamamının yörede yapılmasının şart olmamasıdır. Menüye bir ürünü tescilli adıyla yazıyorsan sunduğun ürün gerçekten o tescile uygun olmalıdır; değilse konuk yanıltılmış olur.","iliskili":["mg-6-018","mg-6-019","mg-6-028"],"kontrol":null},{"id":"mg-6-021","konu":"6.1","terim":"Geleneksel ürün adı","ingilizce":"Traditional product name","tanim":"Belirli bir yöreye bağlı olmayan ama geleneksel malzeme ya da geleneksel yöntemle üretildiği için uzun yıllardır aynı adla anılan ürünlerin adına verilen korumadır.","ornek":"Kuşaklardır aynı yöntemle yapılan bir tatlının tarifi ve yapım yöntemi tescil edilir; adı, o tarife uygun yapılan ürünü anlatır.","sektor":"Coğrafi işaretten farkı, ürünü bir yöreye değil, bir geleneğe bağlamasıdır. Mutfak kültürünün kuşaktan kuşağa bozulmadan aktarılmasına yardım eder.","iliskili":["mg-6-018","mg-6-019","mg-6-020"],"kontrol":null,"gorsel":"m6-ramazan-pidesi"},{"id":"mg-6-022","konu":"6.1","terim":"Ticari sır","ingilizce":"Trade secret","tanim":"Bir işletmeye rekabette üstünlük sağlayan, herkesçe bilinmeyen ve işletmenin gizli tutmak için önlem aldığı bilgidir.","ornek":"Bir otel restoranının yıllardır aynı lezzette çıkan imza sosunun tarifi yalnız aşçıbaşı ve yardımcısı tarafından bilinir.","sektor":"Sektörde “trade secret” denir. Tescil edilmez; gizli kaldığı sürece korunur, açıklandığında değerini yitirir. Staj yerinde öğrendiğin tarif, fiyat anlaşması ve konuk listesi gibi bilgileri dışarıda anlatmamak meslek etiğinin gereğidir.","iliskili":["mg-6-001","mg-6-012","mg-6-023"],"kontrol":null,"kitapDisi":true,"cizim":"veri-guvenlik"},{"id":"mg-6-023","konu":"6.1","terim":"Korunmaya değer bileşen","ingilizce":"Protectable element","tanim":"Bir ürün ya da hizmetin, özgün olduğu için bir fikrî ya da sınai mülkiyet hakkıyla korunabilecek parçasıdır.","ornek":"Bir akıllı telefonda logo markayla, dış görünüm tasarımla, işletim sistemi telif hakkıyla, içindeki teknik yenilikler patentle korunur.","sektor":"Tek bir üründe birden çok hak bir arada bulunur. Otelde de öyledir: ad ve logo marka, broşürdeki yazı ve fotoğraflar telif hakkı, özel çizdirilen mobilya tasarım konusudur. Doğru soru şudur: bu parçayı özgün yapan ne, ad mı, görünüm mü, teknik çözüm mü, ifade mi?","iliskili":["mg-6-001","mg-6-008","mg-6-065"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-035","konu":"6.1","terim":"Meslek birliği","ingilizce":"Collecting society","tanim":"Eser sahiplerinin ve bağlantılı hak sahiplerinin haklarını onlar adına izleyen, kullanım izni veren ve toplanan bedeli üyelerine dağıtan kuruluştur.","ornek":"Bir restoran, salonda müzik çalabilmek için bestecilerle tek tek anlaşmaz; onları temsil eden meslek birlikleriyle sözleşme yapar.","sektor":"Türkiye’de müzik alanında MESAM, MSG ve MÜ-YAP gibi meslek birlikleri vardır. Binlerce şarkının sahibine tek tek ulaşmak mümkün olmadığı için sistem bu kuruluşlar üzerinden işler.","iliskili":["mg-6-036","mg-6-007","mg-6-031"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-036","konu":"6.1","terim":"Otelde müzik yayını izni","ingilizce":"Music licence","tanim":"Otel, restoran, kafe gibi halka açık yerlerde müzik çalınabilmesi için hak sahiplerini temsil eden meslek birliklerinden alınması gereken izindir.","ornek":"Saat 20.00, otelin restoranı: hoparlörden hafif bir müzik çalıyor. Bu yayın için otel yönetimi ilgili meslek birlikleriyle sözleşme yapmıştır.","sektor":"Lobi, restoran, havuz başı, spor salonu ve asansör konukların ortak kullandığı, halka açık alanlardır; buralarda müzik çalmak kişisel dinleme sayılmaz, izne bağlıdır. Kişisel dinleme için alınmış bir müzik uygulaması üyeliği işletmede yayın yapma izni vermez.","iliskili":["mg-6-035","mg-6-007","mg-6-029"],"kontrol":null},{"id":"mg-6-037","konu":"6.1","terim":"İzinsiz görsel kullanımı","ingilizce":"Unauthorised use of images","tanim":"Başkasına ait fotoğraf, çizim ya da videonun, sahibinden izin alınmadan menü, broşür, internet sitesi ya da sosyal medya paylaşımında kullanılmasıdır.","ornek":"Bir kafe, menüsüne koymak için internette arama yapıp bulduğu yemek fotoğraflarını indirir ve bastırır; fotoğrafların sahibi başka biridir.","sektor":"“İnternette buldum” demek “kullanabilirim” demek değildir: internetteki fotoğrafların çoğu telif hakkıyla korunur. Güvenli yol üçtür: fotoğrafı kendin çekmek, sahibinden izin ya da lisans almak, kullanımı açıkça serbest bırakılmış görselleri koşullarına uyarak kullanmak. Üstelik başka yerin fotoğrafı konuğu yanıltır.","iliskili":["mg-6-003","mg-6-039","mg-6-029"],"kontrol":null,"cizim":"marka"},{"id":"mg-6-038","konu":"6.1","terim":"Konuk fotoğrafı paylaşımı","ingilizce":"Sharing photographs of guests","tanim":"Konuğun tanınabildiği bir fotoğraf ya da videonun otelin sosyal medya hesabında yayımlanmasıdır; ancak konuğun açık izniyle yapılabilen bir işlemdir.","ornek":"Otelin sosyal medya sorumlusu, havuz başındaki kutlamada çektiği kareyi paylaşmadan önce karede görünen konuklara sorar; izin vermeyenin görüntüsü kullanılmaz.","sektor":"Burada iki ayrı hak vardır: fotoğrafı çekenin telif hakkı ve fotoğrafta görünen kişinin kendi görüntüsü üzerindeki hakkı. Fotoğrafı senin çekmiş olman paylaşma hakkı vermez. Stajyer, konukları kendi telefonuyla çekip kişisel hesabında paylaşmaz.","iliskili":["mg-6-037","mg-6-029","mg-6-024"],"kontrol":null},{"id":"mg-6-039","konu":"6.1","terim":"Creative Commons lisansı","ingilizce":"Creative Commons licence","tanim":"Eser sahibinin, eserini herkesin belirli koşullarla ve ayrıca izin istemeden kullanabileceğini önceden ilan ettiği açık lisans türüdür.","ornek":"Bu uygulamadaki fotoğraflar böyle seçildi: sahibinin “adımı belirterek kullanabilirsiniz” dediği (CC BY) kareler alındı ve “Görsel künyesi” ekranında fotoğrafçıların adı yazıldı.","sektor":"Kısaca “CC” denir. Koşullar lisansa göre değişir: genel olarak eser sahibinin adını belirtmek gerekir, bazıları ticari kullanıma ya da eseri değiştirmeye izin vermez. Broşüre ya da menüye koymadan önce lisansın koşulu okunur.","iliskili":["mg-6-031","mg-6-037","mg-6-026"],"kontrol":null,"kitapDisi":true},{"id":"mg-6-040","konu":"6.1","terim":"Kamu malı eser","ingilizce":"Public domain work","tanim":"Koruma süresi dolduğu için mali hakları sona ermiş ve herkesin izin almadan kullanabildiği eserdir.","ornek":"Yüzyıllar önce yaşamış bir bestecinin eseri kamu malıdır; ama o eseri bugün çalıp kaydeden orkestranın kaydı üzerinde ayrı haklar vardır.","sektor":"Sektörde “public domain” denir. Eserin kendisi serbest olsa bile yeni yapılmış kaydı, çevirisi ya da fotoğrafı ayrıca korunuyor olabilir; kullanmadan önce buna bakılır.","iliskili":["mg-6-002","mg-6-039","mg-6-044"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-6-041","konu":"6.1","terim":"Tescil","ingilizce":"Registration","tanim":"Bir sınai mülkiyet hakkının yetkili kurum tarafından incelenip resmî sicile kaydedilmesidir.","ornek":"Otel adını ve logosunu tescil ettirir; birkaç yıl sonra başka bir işletme aynı adı kullanmaya kalktığında hakkını tescil kaydıyla kanıtlar.","sektor":"Programın anahtar kavramlarındandır. Marka, patent, faydalı model ve coğrafi işarette koruma tescille elde edilir. Telif hakkı ise tescil gerektirmez; eser ortaya çıktığı anda doğar. Tescilsiz ad, yıllarca emek verilip tanıtıldıktan sonra kaybedilebilir.","iliskili":["mg-6-042","mg-6-043","mg-6-059"],"kontrol":null},{"id":"mg-6-044","konu":"6.1","terim":"Koruma süresi","ingilizce":"Term of protection","tanim":"Bir fikrî ya da sınai mülkiyet hakkının sahibine yalnız ona ait yetkiler tanıdığı zaman aralığıdır.","ornek":"Türkiye’de patent 20 yıl, faydalı model 10 yıl korunur; marka 10 yıl korunur ve yenilenebilir; telif hakkı eser sahibinin ölümünden sonra 70 yıl sürer.","sektor":"Sürelerin farklı olmasının bir mantığı vardır: buluş bir süre sonra herkesin kullanımına açılmalıdır ki teknoloji ilerlesin; marka ise kullanıldıkça ve yenilendikçe yaşar, çünkü konuğun kimden hizmet aldığını bilmesini sağlar.","iliskili":["mg-6-012","mg-6-014","mg-6-063"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-6-045","konu":"6.1","terim":"Marka ve telif simgeleri (®, ™, ©)","ingilizce":"Trade mark and copyright symbols (®, ™, ©)","tanim":"Bir adın ya da eserin korunduğunu göstermek için yanına konan uluslararası işaretlerdir.","ornek":"Bir otel zincirinin logosunun sağ üst köşesindeki küçük ® işareti ya da bir internet sitesinin en altındaki © işareti.","sektor":"® tescilli markayı, ™ marka olarak kullanılan işareti, © telif hakkını gösterir. Türkiye’de bu simgeleri kullanmak zorunlu değildir; simge olmaması, o adın ya da görselin serbest olduğu anlamına gelmez.","iliskili":["mg-6-014","mg-6-002","mg-6-041"],"kontrol":null,"kitapDisi":true,"cizim":"marka"},{"id":"mg-6-051","konu":"6.1","terim":"Patentlenebilirlik ölçütleri","ingilizce":"Patentability criteria","tanim":"Bir buluşa patent verilebilmesi için birlikte aranan yenilik, buluş basamağı ve sanayiye uygulanabilirlik şartlarıdır.","ornek":"Bir öğrenci grubunun geliştirdiği valiz taşıma düzeneği üç soruyla sınanır: daha önce yapılmış mı, uzman için sıradan bir adım mı, üretilip kullanılabilir mi?","sektor":"Üçünden biri eksikse patent verilmez. Bu yüzden başvurudan önce patent veri tabanlarında araştırma yapılır: emek ve para, zaten bilinen bir şey için harcanmasın.","iliskili":["mg-6-052","mg-6-053","mg-6-054"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-053","konu":"6.1","terim":"Buluş basamağı","ingilizce":"Inventive step","tanim":"Buluşun, o teknik alanda uzman bir kişinin bilinen bilgilerden kolayca ve kendiliğinden çıkarabileceği bir şey olmamasıdır.","ornek":"Bilinen bir servis arabasının yalnızca rengini ya da boyutunu değiştirmek uzman için sıradan bir adımdır; buluş basamağı taşımaz.","sektor":"Yeni olmak yetmez; bilinenin açık bir devamı olmayan bir adım atılmış olmalıdır. Faydalı modelde bu şart aranmaz; küçük ama yararlı iyileştirmeler bu yüzden faydalı modelle korunur.","iliskili":["mg-6-051","mg-6-013","mg-6-055"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-054","konu":"6.1","terim":"Sanayiye uygulanabilirlik","ingilizce":"Industrial applicability","tanim":"Buluşun sanayinin herhangi bir dalında üretilebilir ya da kullanılabilir olmasıdır.","ornek":"Hiç enerji almadan sonsuza kadar çalıştığı öne sürülen bir makine doğa yasalarına aykırı olduğu için üretilemez; bu şartı karşılamaz.","sektor":"Buradaki “sanayi” geniş anlamdadır; tarım da içindedir. Kâğıt üzerinde kalan, gerçekte yapılamayan ya da kullanılamayan bir fikir patent alamaz.","iliskili":["mg-6-051","mg-6-052","mg-6-053"],"kontrol":null},{"id":"mg-6-069","konu":"6.1","terim":"Slogan","ingilizce":"Slogan","tanim":"Bir ürün ya da hizmeti kısa ve akılda kalır bir sözle tanıtan, ayırt edici olduğunda marka olarak da korunabilen ifadedir.","ornek":"Bir otel “Kaliteli hizmet” gibi herkesin kullandığı bir sözü marka olarak tescil ettirmek isterse reddedilebilir; yalnız o oteli akla getiren özgün bir söz tescil edilebilir.","sektor":"Günlük dilde herkesin kullandığı sıradan sözler (“Kaliteli hizmet” gibi) ayırt edici olmadığı için marka korumasına girmez.","iliskili":["mg-6-014","mg-6-016","mg-6-015"],"kontrol":null,"cizim":"marka"},{"id":"mg-6-011","konu":"6.2","terim":"Mucit","ingilizce":"Inventor","tanim":"Bir buluşu kendi fikrî emeğiyle gerçekleştiren kişidir.","ornek":"Bir meslek lisesi öğrencisi, servis tepsisinin kaymasını önleyen yeni bir tutma düzeneği geliştirir; bu buluşun mucidi odur.","sektor":"Programın anahtar kavramlarındandır. Kanunda “buluşu yapan” diye geçer. Patent isteme hakkı kural olarak buluşu yapana ya da bu hakkı ondan devralana aittir; patent bir şirket adına alınsa bile başvuruda buluşu yapanın kim olduğu bildirilir.","iliskili":["mg-6-010","mg-6-012","mg-6-060"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-024","konu":"6.2","terim":"Emeğe saygı","ingilizce":"Respect for others' work","tanim":"Başkasının bilgi, zaman ve çabayla ortaya koyduğu ürünü onun hakkı olarak görmek ve izinsiz kullanmamaktır.","ornek":"Sunum ödevinde arkadaşının hazırladığı slaytları kullanmak isteyen öğrenci önce ondan izin ister ve sunumda adını anar.","sektor":"Bir fikri çalmak ile bir eşyayı çalmak arasındaki tek fark fikrin elle tutulmamasıdır; ikisinde de emeğin karşılığı sahibinden alınır. Emeğe saygı, dürüstlükle birlikte bu ünitenin etik temelidir.","iliskili":["mg-6-025","mg-6-026","mg-6-030"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-6-025","konu":"6.2","terim":"İntihal","ingilizce":"Plagiarism","tanim":"Başkasına ait yazıyı, fikri ya da çalışmayı kaynak göstermeden kendi ürünüymüş gibi sunmaktır.","ornek":"Staj dosyasına, internette bulduğu bir otel tanıtım yazısını olduğu gibi yapıştırıp altına kendi adını yazan öğrenci.","sektor":"Önce bir dürüstlük sorunudur: okulda notu, iş hayatında güveni kaybettirir. İşletme için de risklidir: rakibin internet sitesindeki tanıtım metnini kopyalamak hem itibarı zedeler hem telif hakkını çiğneyebilir.","iliskili":["mg-6-024","mg-6-026","mg-6-029"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-026","konu":"6.2","terim":"Kaynak gösterme","ingilizce":"Citing sources","tanim":"Yararlanılan bilginin, yazının ya da görselin kime ait olduğunu ve nereden alındığını açıkça belirtmektir.","ornek":"Öğrenci, turizm sunumunun son slaytına yararlandığı kitabı ve internet sayfalarını yazar; fotoğrafların altına çekenin adını ekler.","sektor":"Kaynak göstermek intihali önler, ama her zaman kullanım izni yerine geçmez: bir fotoğrafı ticari bir broşürde kullanmak için çekenin adını yazmak yetmez, iznini de almak gerekir.","iliskili":["mg-6-025","mg-6-006","mg-6-039"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-6-027","konu":"6.2","terim":"Korsan","ingilizce":"Piracy","tanim":"Telif hakkıyla korunan kitap, müzik, film ya da yazılımın hak sahibinden izin alınmadan çoğaltılması, dağıtılması ya da kullanılmasıdır.","ornek":"Lisansı satın alınmamış bir programın kopyasını bilgisayara kurmak ya da bir filmi izinsiz paylaşan siteden indirmek.","sektor":"Programın anahtar kavramlarındandır. Otelde lisanssız yazılım kullanmak hukuki sorumluluk doğurur; ayrıca güncelleme ve destek alınamadığı için konuk bilgilerinin tutulduğu sistemi güvenlik açığına karşı korumasız bırakır.","iliskili":["mg-6-028","mg-6-029","mg-6-031"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-028","konu":"6.2","terim":"Taklit","ingilizce":"Counterfeiting","tanim":"Tescilli bir markanın ya da tasarımın, hak sahibinden izin alınmadan aynısı ya da ayırt edilemeyecek kadar benzeri yapılarak ürün üretilmesi ve satılmasıdır.","ornek":"Bir turistik çarşıda, ünlü bir markanın logosu basılmış ama o markanın üretmediği çantaların satılması.","sektor":"Programın anahtar kavramlarındandır. Taklit ürün turisti aldatır, gerçek üreticinin emeğini çalar ve çarşının adını lekeler. Turisti böyle dükkânlara yönlendirmek ya da taklit ürünü gerçekmiş gibi tanıtmak meslek etiğine aykırıdır.","iliskili":["mg-6-027","mg-6-029","mg-6-014"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-029","konu":"6.2","terim":"Hak ihlali","ingilizce":"Infringement","tanim":"Korunan bir eserin, markanın, buluşun ya da tasarımın hak sahibinin izni olmadan kullanılmasıdır.","ornek":"Yeni açılan bir pansiyonun tanınmış bir otelin tescilli adını ve logosunu tabelasında kullanması.","sektor":"Hak sahibi ihlalin durdurulmasını ve zararının karşılanmasını mahkemeden isteyebilir; bazı ihlaller ayrıca suç sayılır. “Bilmiyordum” demek ihlali ortadan kaldırmaz; bu yüzden kullanmadan önce sormak gerekir.","iliskili":["mg-6-027","mg-6-028","mg-6-030"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-030","konu":"6.2","terim":"Haksız kazanç","ingilizce":"Unfair gain","tanim":"Başkasının emeğinden, adından ya da buluşundan izinsiz yararlanarak hak edilmeden elde edilen gelirdir.","ornek":"Bir işletme, başka bir firmanın yıllarca çalışıp geliştirdiği ürünü kopyalayıp hiçbir araştırma masrafı yapmadan daha ucuza satar.","sektor":"Kopyalayan kazanır, üreten kaybeder; bu sürerse kimse yeni bir şey geliştirmek için emek ve para harcamak istemez. Bu yüzden korumanın zayıf olduğu yerde yalnız mucit değil, sektörün geleceği ve toplumun kalkınması da zarar görür.","iliskili":["mg-6-024","mg-6-028","mg-6-034"],"kontrol":null,"cizim":"ilk-yardim"},{"id":"mg-6-031","konu":"6.2","terim":"Lisans","ingilizce":"Licence","tanim":"Hak sahibinin, eserini, markasını ya da buluşunu belirli koşullarla ve çoğunlukla bir bedel karşılığında başkasının kullanmasına verdiği izindir.","ornek":"Otel, ön büro programını satın aldığında aslında programın sahibi olmaz; onu belirli sayıda bilgisayarda kullanma lisansı almış olur.","sektor":"Programın anahtar kavramlarındandır. Lisansla hak el değiştirmez, yalnız kullanma izni verilir. Lisansın koşulları önemlidir: kaç bilgisayarda, ne kadar süreyle, hangi amaçla. Koşulun dışına çıkmak izinsiz kullanım sayılır.","iliskili":["mg-6-032","mg-6-033","mg-6-027"],"kontrol":null,"cizim":"sozlesme"},{"id":"mg-6-032","konu":"6.2","terim":"Telif ücreti","ingilizce":"Royalty","tanim":"Bir eseri, markayı ya da buluşu izinle kullanan kişinin, bu kullanım karşılığında hak sahibine ödediği bedeldir.","ornek":"Bir yayınevi kitabı bastıkça yazarına, bir işletme başkasının markasını kullandıkça marka sahibine ödeme yapar.","sektor":"Sektörde “royalty” denir. Hak sahibinin emeğinin karşılığını almasını ve yeni işler üretmeyi sürdürmesini sağlar. Otelcilikte zincir markasının adını kullanan işletmelerin marka sahibine yaptığı ödemeler için de bu sözcük kullanılır.","iliskili":["mg-6-031","mg-6-033","mg-6-007"],"kontrol":null,"kitapDisi":true,"cizim":"etik-terazi"},{"id":"mg-6-033","konu":"6.2","terim":"İsim hakkı (franchise)","ingilizce":"Franchise","tanim":"Tanınmış bir markanın sahibinin, adını ve iş yapma biçimini belirli kurallara uyması koşuluyla ve bedel karşılığında başka bir işletmeye kullandırmasıdır.","ornek":"Bir yatırımcı kendi binasında, uluslararası bir otel zincirinin adını ve standartlarını kullanarak otel işletir.","sektor":"Sektörde “franchise” denir; birçok zincir otel ve restoran markası bu yolla yayılır. Konuk tabeladaki adı gördüğünde her şehirde aynı standardı bekler; standart tutmazsa zarar gören markanın kendisidir.","iliskili":["mg-6-031","mg-6-032","mg-6-014"],"kontrol":null,"kitapDisi":true},{"id":"mg-6-034","konu":"6.2","terim":"İnovasyonun korunması","ingilizce":"Protecting innovation","tanim":"Yeni bir fikrin ürüne ya da hizmete dönüşmüş hâlinin, yani inovasyonun, patent, tasarım ve marka gibi haklarla güvence altına alınmasıdır.","ornek":"Genç bir girişimci yeni ürününü korumaya almadan tanıtır; büyük bir firma aynısını üretip piyasaya sürer ve girişimci emeğinin karşılığını alamaz.","sektor":"İnovasyon programın anahtar kavramlarındandır: yeni ya da geliştirilmiş bir ürünü, hizmeti ya da yöntemi hayata geçirip değere dönüştürmektir. Koruma varsa girişimci araştırmaya para ve zaman ayırmayı göze alır, yatırımcı bulur, iş kurar ve insan çalıştırır; koruma yoksa kazanan kopyalayan olur.","iliskili":["mg-6-012","mg-6-030","mg-6-065"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-068","konu":"6.2","terim":"Yaratıcılık","ingilizce":"Creativity","tanim":"Alışılmış yolların dışına çıkarak yeni fikir, ürün ya da çözüm üretebilme gücüdür.","ornek":"Az kullanılan çatı katını gün batımı manzaralı bir kahve terasına çevirmeyi düşünen kafe sahibi yaratıcı bir çözüm üretmiştir.","sektor":"Yaratıcılık yeni fikir doğurur; fikrin korunması ise emeğe saygı ve dürüstlük meselesidir. Yaratıcılığın ürünü fikrî ve sınai mülkiyet hakkıyla güvence altına alınır.","iliskili":["mg-6-024","mg-6-034","mg-6-010"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-070","konu":"6.2","terim":"Dürüst rekabet","ingilizce":"Fair competition","tanim":"İşletmelerin birbirinin adını, tasarımını ve emeğini taklit etmeden, kendi bilgi ve yenilikleriyle müşteri kazanmasıdır.","ornek":"Yeni açılan bir pansiyonun, komşu otelin logosunu andıran bir tabela asmak yerine kendi özgün adını ve görünümünü oluşturması dürüst rekabettir.","sektor":"Bir acentenin rakibinin tur programını kopyalamak yerine kendi güzergâhını tasarlaması ve bir otelin komşusunun fotoğraflarını kullanmak yerine kendi odalarını çektirmesi dürüst rekabettir. Kopyayı fark eden müşteri güvenini yitirir; özgünlük kalıcı bir ad kazanmanın yoludur.","iliskili":["mg-6-028","mg-6-029","mg-6-024"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-071","konu":"6.2","terim":"Sektörel sürdürülebilirlik","ingilizce":"Sector sustainability","tanim":"Bir sektörde yeni ürün geliştirmeye emek ve para ayıranlar kopyalanarak zarar görmediği için yeniliğin ve gelişimin uzun süre devam etmesidir.","ornek":"Rezervasyon yazılımı geliştiren küçük bir firma ürünü sürekli kopyalansaydı yatırım yapmayı bırakırdı; koruma sayesinde yeni sürümler çıkarmayı sürdürür.","sektor":"Otellerin kullandığı dijital anahtar, enerji izleme ve çevrim içi rezervasyon sistemleri geliştiricilerinin emeği korunduğu için sürekli yenilenir. Bu durum sektörün yarın da daha iyi araçlarla çalışabilmesinin güvencesidir.","iliskili":["mg-6-034","mg-6-068","mg-6-030"],"kontrol":null,"cizim":"doga"},{"id":"mg-6-072","konu":"6.2","terim":"Toplumsal kalkınma","ingilizce":"Social development","tanim":"Yeni ürün, teknoloji ve hizmetlerin yalnız onları geliştirenlere değil bütün topluma yarar sağlayarak ekonomik ve toplumsal gelişmeyi desteklemesidir.","ornek":"Enerji tasarrufu sağlayan bir otel sistemi yaygınlaştıkça hem otellerin giderleri hem ülkenin enerji tüketimi azalır.","sektor":"Engelli konukların rahat kullanabildiği erişilebilir oda ve rampa tasarımları yaygınlaştıkça kazanan yalnız ilk geliştiren otel olmaz; seyahat edebilen yeni konuklar ve daha nitelikli hizmet veren bütün sektör de kazanır. Yeniliğin toplumsal kalkınmaya katkısı bilginin paylaşılıp yaygınlaşmasının sonucudur.","iliskili":["mg-6-034","mg-6-066","mg-6-071"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-042","konu":"6.3","terim":"Türk Patent ve Marka Kurumu (TÜRKPATENT)","ingilizce":"Turkish Patent and Trademark Office (TÜRKPATENT)","tanim":"Türkiye’de patent, faydalı model, marka, tasarım ve coğrafi işaret başvurularını alan, inceleyen ve tescil eden, merkezi Ankara’da bulunan kamu kurumudur.","ornek":"Yöresel ürünlerini korumak isteyen bir belediye ya da ticaret odası, coğrafi işaret başvurusunu TÜRKPATENT’e yapar.","sektor":"Eski adı Türk Patent Enstitüsüdür; bugünkü adını 2017’de Sınai Mülkiyet Kanunu ile almıştır. Başvurular internet üzerinden yapılabilir; tescilli marka, patent ve coğrafi işaretler kurumun sitesinden ücretsiz sorgulanabilir.","iliskili":["mg-6-009","mg-6-041","mg-6-056"],"kontrol":null,"gorsel":"m6-turkpatent-enstitu"},{"id":"mg-6-043","konu":"6.3","terim":"Ülkesellik ilkesi","ingilizce":"Principle of territoriality","tanim":"Bir sınai mülkiyet hakkının yalnızca tescil edildiği ülkenin sınırları içinde koruma sağlamasıdır.","ornek":"Adını yalnız Türkiye’de tescil ettiren bir otel zinciri yurt dışında otel açmak istediğinde, o ülkede aynı adın başkası adına tescilli olduğunu görebilir.","sektor":"“Dünya patenti” ya da “dünya markası” diye tek bir belge yoktur. Başka ülkelerde koruma isteyen, o ülkelerde de başvuru yapar; uluslararası sistemler bu işi kolaylaştırır.","iliskili":["mg-6-041","mg-6-046","mg-6-050"],"kontrol":null,"cizim":"dunya-global"},{"id":"mg-6-046","konu":"6.3","terim":"Dünya Fikrî Mülkiyet Örgütü (WIPO)","ingilizce":"World Intellectual Property Organization (WIPO)","tanim":"Fikrî mülkiyetin dünya genelinde korunmasını geliştirmek için çalışan, merkezi Cenevre’de bulunan Birleşmiş Milletler uzmanlık kuruluşudur.","ornek":"Markasını birçok ülkede korumak isteyen bir Türk firması, WIPO’nun yürüttüğü uluslararası marka tescil sistemi (Madrid Sistemi) üzerinden tek başvuruyla birden çok ülke seçebilir.","sektor":"Uluslararası patent başvuru sistemini (PCT) ve uluslararası marka tescil sistemini yürütür; PATENTSCOPE adlı ücretsiz patent veri tabanını sunar. Ülkeler arasında ortak kurallar oluşmasına yardım eder.","iliskili":["mg-6-047","mg-6-050","mg-6-056"],"kontrol":null,"gorsel":"mg-wipo-binasi"},{"id":"mg-6-047","konu":"6.3","terim":"Avrupa Patent Ofisi (EPO)","ingilizce":"European Patent Office (EPO)","tanim":"Tek bir başvuruyla, Avrupa Patent Sözleşmesi’ne taraf ülkelerde geçerli olabilecek patentleri inceleyip veren ve merkezi Münih’te bulunan kuruluştur.","ornek":"Bir Türk firması buluşunu Almanya, Fransa ve İtalya’da korumak ister; üç ülkeye ayrı ayrı başvurmak yerine EPO’ya tek başvuru yapar.","sektor":"Türkiye bu sözleşmeye taraftır. EPO bir Avrupa Birliği kurumu değildir. Espacenet adlı ücretsiz patent veri tabanını da EPO sunar.","iliskili":["mg-6-046","mg-6-050","mg-6-056"],"kontrol":null,"gorsel":"m6-avrupa-patent-ofisi"},{"id":"mg-6-048","konu":"6.3","terim":"Paris Sözleşmesi","ingilizce":"Paris Convention","tanim":"Sınai mülkiyet haklarının ülkeler arasında korunmasının temel kurallarını koyan, 1883 tarihli uluslararası anlaşmadır.","ornek":"Türkiye’de marka başvurusu yapan bir firma, sözleşmeye taraf başka bir ülkede o ülkenin vatandaşlarıyla aynı koşullarda başvuru yapabilir.","sektor":"Sözleşmenin getirdiği iki temel kural: üye ülkelerin birbirinin vatandaşlarına kendi vatandaşları gibi davranması ve rüçhan hakkı. Türkiye sözleşmeye taraftır.","iliskili":["mg-6-049","mg-6-046","mg-6-043"],"kontrol":null},{"id":"mg-6-049","konu":"6.3","terim":"Rüçhan hakkı","ingilizce":"Right of priority","tanim":"Bir ülkede başvuru yapan kişinin, belirli bir süre içinde başka ülkelerde yapacağı başvurularda ilk başvurunun tarihinden yararlanmasını sağlayan öncelik hakkıdır.","ornek":"Bir mucit önce Türkiye’de patent başvurusu yapar, birkaç ay sonra yurt dışında başvurur; yurt dışındaki başvurusu Türkiye’deki ilk tarihte yapılmış gibi değerlendirilir.","sektor":"Programın anahtar kavramlarındandır. “Rüçhan” öncelik demektir. Başvuru sahibine zaman kazandırır: aradaki sürede bir başkası aynı buluş ya da marka için başvursa bile öncelik ilk başvuranındır.","iliskili":["mg-6-048","mg-6-060","mg-6-050"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-050","konu":"6.3","terim":"Patent İş Birliği Antlaşması (PCT)","ingilizce":"Patent Cooperation Treaty (PCT)","tanim":"Tek bir uluslararası başvuruyla birçok ülkede aynı anda patent başvurusu yapılmış sayılmasını sağlayan, WIPO’nun yürüttüğü sistemdir.","ornek":"Buluşunu birçok ülkede korumak isteyen girişimci tek bir PCT başvurusu yapar; sonra hangi ülkelerde devam edeceğine karar verir.","sektor":"PCT tek bir “uluslararası patent” vermez: başvuruyu kolaylaştırır, ama patenti verip vermemeye yine her ülkenin ya da bölgenin kendi ofisi karar verir.","iliskili":["mg-6-046","mg-6-043","mg-6-049"],"kontrol":null,"gorsel":"m6-wipo-binasi-bahce"},{"id":"mg-6-052","konu":"6.3","terim":"Yenilik","ingilizce":"Novelty","tanim":"Buluşun, başvuru tarihinden önce dünyanın hiçbir yerinde yazılı, sözlü ya da kullanım yoluyla kamuya açıklanmamış olmasıdır.","ornek":"Bir firmanın “yeni” diye başvurduğu bavul kilidinin aynısı yıllar önce başka bir ülkede yayımlanmış bir patent belgesinde anlatılmışsa yenilik şartı karşılanmaz.","sektor":"Yenilik yalnız Türkiye’ye göre değil, bütün dünyaya göre değerlendirilir. Mucidin buluşunu başvurudan önce sosyal medyada, fuarda ya da yarışmada ayrıntısıyla açıklaması da yeniliği tehlikeye atabilir.","iliskili":["mg-6-051","mg-6-055","mg-6-059"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-055","konu":"6.3","terim":"Tekniğin bilinen durumu","ingilizce":"State of the art (prior art)","tanim":"Başvuru tarihinden önce dünyanın herhangi bir yerinde kamuya açıklanmış bütün bilgilerin toplamıdır.","ornek":"Daha önce yayımlanmış patent belgeleri, bilimsel makaleler, ürün katalogları ve fuarda sergilenmiş ürünler tekniğin bilinen durumuna girer.","sektor":"Bir buluşun yeni olup olmadığına ve buluş basamağı taşıyıp taşımadığına bununla karşılaştırılarak karar verilir. Patent araştırmasının amacı, kendi fikrinin bu birikimin neresinde durduğunu görmektir.","iliskili":["mg-6-052","mg-6-053","mg-6-057"],"kontrol":null,"cizim":"kat-hizmeti"},{"id":"mg-6-056","konu":"6.3","terim":"Patent veri tabanı","ingilizce":"Patent database","tanim":"Yayımlanmış patent başvurularının ve belgelerinin toplandığı, internet üzerinden aranabilen kaynaktır.","ornek":"TÜRKPATENT’in çevrim içi araştırma sayfası ulusal; Avrupa Patent Ofisinin Espacenet’i ve WIPO’nun PATENTSCOPE’u uluslararası veri tabanlarıdır.","sektor":"Bu veri tabanları ücretsizdir ve herkese açıktır. Patent belgeleri dünyanın en büyük teknik bilgi kaynaklarından biridir: bir sorunu senden önce kimin, nasıl çözdüğünü gösterir.","iliskili":["mg-6-057","mg-6-042","mg-6-047"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-057","konu":"6.3","terim":"Patent araştırması","ingilizce":"Patent search","tanim":"Bir fikrin daha önce başkası tarafından bulunup bulunmadığını anlamak için patent veri tabanlarında anahtar sözcüklerle yapılan taramadır.","ornek":"Otel odaları için yeni bir kart okuyucu fikri olan grup, veri tabanına “otel”, “kart”, “enerji tasarrufu” sözcüklerini yazar ve çıkan belgeleri kendi fikriyle karşılaştırır.","sektor":"Araştırma üç işe yarar: aynı şeyi yeniden icat etmeyi önler, fikrin yenilik düzeyini gösterir ve o alanda hangi firmaların çalıştığını ortaya koyar. Bulunan bilgi tek kaynaktan alınmaz; birden çok belgeyle karşılaştırılarak değerlendirilir.","iliskili":["mg-6-056","mg-6-055","mg-6-058"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-058","konu":"6.3","terim":"İstemler","ingilizce":"Claims","tanim":"Patent belgesinde, buluşun hangi teknik özellikleri için koruma istendiğini madde madde belirten bölümdür.","ornek":"Bir bavul kilidi patentinin istemlerinde kilidin hangi parçalardan oluştuğu ve bu parçaların nasıl birlikte çalıştığı tek tek yazılır.","sektor":"Patentin koruma sınırını istemler çizer: istemlerde yazmayan özellik korunmaz. Patent belgesinde ayrıca buluşu ayrıntısıyla anlatan tarifname, çizimler ve kısa bir özet bulunur; araştırmada ilk bakılan yer özettir.","iliskili":["mg-6-057","mg-6-012","mg-6-059"],"kontrol":null,"cizim":"dijital"},{"id":"mg-6-066","konu":"6.3","terim":"Patent sisteminin ekonomik etkisi","ingilizce":"Economic impact of the patent system","tanim":"Buluş sahibine bir süre tek başına kullanma hakkı tanıyarak araştırmaya harcanan emeğin ve paranın geri dönmesini sağlayan, böylece yeniliği, girişimciliği ve ekonomik büyümeyi destekleyen etkidir.","ornek":"Otel odaları için enerji tasarruflu yeni bir düzenek geliştiren küçük bir firma patent aldığı için yatırımcı bulur, üretime geçer ve yeni iş yeri açar.","sektor":"Patent, buluşu herkesin okuyabileceği belgeye dönüştürdüğü için başkalarının da aynı bilgiden yola çıkıp daha ileri gitmesini sağlar. Turizm teknolojilerinde (rezervasyon yazılımı, akıllı oda sistemleri) yatırım yapan firmalar bu güvenceye dayanır.","iliskili":["mg-6-012","mg-6-034","mg-6-056"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-6-073","konu":"6.3","terim":"Yenilik düzeyi","ingilizce":"Level of novelty","tanim":"Bir buluşun, mevcut teknolojiyle karşılaştırıldığında ne kadar yeni bir teknik çözüm getirdiğini gösteren derecedir.","ornek":"Güneş paneli sabit durur; yeni buluş güneşin konumunu algılayıp yönünü kendisi değiştirir. Aradaki temel fark yenilik düzeyini gösterir.","sektor":"Otelin teknik servisinde geliştirilen bir fikir piyasada zaten bulunan bir kart anahtar sistemine küçük bir ekleme yapıyorsa yenilik düzeyi düşüktür; daha önce hiç denenmemiş bir yöntemle çalışıyorsa yüksektir. Fikrin bu ölçekte nereye düştüğünü patent araştırması gösterir; bu yüzden araştırma başvurudan önce yapılmalıdır.","iliskili":["mg-6-052","mg-6-055","mg-6-053"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-6-074","konu":"6.3","terim":"Patent belgesi","ingilizce":"Patent document","tanim":"Bir patent başvurusunun ya da patentin başlığı, teknik özeti, başvuru sahibi ve buluşçusu, tarihleri ve teknik açıklamaları ile birlikte yayımlandığı belgedir.","ornek":"Okul grubu, veri tabanında bulduğu belgenin başlığına, özetine ve başvuru tarihine bakarak kendi fikriyle karşılaştırma tablosu doldurur.","sektor":"Otel için bir bagaj taşıma düzeneği ya da enerji tasarruf sistemi geliştirmek isteyen girişimci benzerini daha önce kimin nasıl çözdüğünü patent belgelerinden öğrenir. Belgedeki başvuru tarihi ve istemler fikrin gerçekten yeni olup olmadığını ve neyin başkasına ait olduğunu gösteren resmî kayıtlardır.","iliskili":["mg-6-056","mg-6-057","mg-6-058"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-059","konu":"6.4","terim":"Başvuru","ingilizce":"Application","tanim":"Bir buluş, marka ya da tasarım için koruma elde etmek amacıyla gerekli bilgi ve belgelerin yetkili kuruma sunulmasıdır.","ornek":"Girişimci, yeni kafesinin adını ve logosunu, hangi hizmetlerde kullanacağını da belirterek TÜRKPATENT’e internet üzerinden bildirir.","sektor":"Başvurunun yapıldığı tarih çok önemlidir: öncelik bu tarihe göre belirlenir. Başvuru yapmak tescil almak demek değildir; kurum önce inceler, şartları taşımayan başvuru reddedilir.","iliskili":["mg-6-060","mg-6-061","mg-6-062"],"kontrol":null,"cizim":"sozlesme"},{"id":"mg-6-060","konu":"6.4","terim":"İlk başvuran ilkesi","ingilizce":"First-to-file principle","tanim":"Aynı buluş ya da aynı marka için birden çok kişi başvurduğunda hakkın, başvurusunu daha önce yapana tanınmasıdır.","ornek":"İki arkadaş, henüz hiç kullanılmamış aynı kafe adını düşünür; kural olarak adı ilk düşünen değil, başvuruyu ilk yapan tescil alır.","sektor":"Bu yüzden korumaya değer bir fikir bekletilmez. Fikrini başvurudan önce herkese anlatmak iki açıdan risklidir: başkası senden önce başvurabilir, buluş ise yenilik şartını yitirebilir.","iliskili":["mg-6-059","mg-6-049","mg-6-052"],"kontrol":null,"cizim":"belge-form"},{"id":"mg-6-061","konu":"6.4","terim":"Marka ön araştırması","ingilizce":"Trade mark search","tanim":"Seçilen adın ya da logonun aynısının veya benzerinin daha önce başkası adına tescil edilip edilmediğinin, başvuru yapılmadan önce kontrol edilmesidir.","ornek":"Pansiyon açacak aile, tabelayı bastırmadan önce düşündüğü adı TÜRKPATENT’in marka araştırma sayfasında sorgular.","sektor":"Markalar, kullanılacakları mal ve hizmetlere göre sınıflara ayrılarak tescil edilir; araştırma ilgili sınıflarda yapılır. Tabela, broşür ve internet sitesi hazırlandıktan sonra adın başkasına ait çıkması işletmeye pahalıya mal olur.","iliskili":["mg-6-014","mg-6-016","mg-6-059"],"kontrol":null,"cizim":"marka"},{"id":"mg-6-062","konu":"6.4","terim":"Yayın ve itiraz","ingilizce":"Publication and opposition","tanim":"İncelemeden geçen başvurunun resmî bültende herkese duyurulması ve bu başvurudan hakkı zarar görecek kişilere karşı çıkma imkânı tanınmasıdır.","ornek":"Bir otel, kendi adına çok benzeyen bir markanın bültende yayımlandığını görür ve tescil edilmemesi için kuruma itiraz eder.","sektor":"Marka başvurularında işleyiş böyledir; itiraz için belirli bir süre tanınır. Hak sahibi için çıkarılacak ders şudur: tescil almak yetmez, markana benzer başvuruları izlemek de senin işindir.","iliskili":["mg-6-059","mg-6-041","mg-6-064"],"kontrol":null,"cizim":"konusma"},{"id":"mg-6-063","konu":"6.4","terim":"Yenileme","ingilizce":"Renewal","tanim":"Koruma süresi dolan marka ya da tasarım tescilinin, ücreti ödenerek yeni bir dönem için uzatılmasıdır.","ornek":"On yıl önce adını tescil ettiren otel, süre dolmadan yenileme işlemini yapar; yapmazsa tescilin koruması sona erer.","sektor":"Marka tescili onar yıllık dönemlerle yenilenir. Patent ve faydalı modelde süre uzatılamaz; ama korumanın süre boyunca devam etmesi için yıllık ücret ödenir. Takvimi izlemek hak sahibinin sorumluluğudur.","iliskili":["mg-6-044","mg-6-014","mg-6-065"],"kontrol":null,"cizim":"sozlesme"},{"id":"mg-6-064","konu":"6.4","terim":"Patent ve marka vekili","ingilizce":"Patent and trade mark attorney","tanim":"Başvuru sahiplerini TÜRKPATENT önünde temsil eden, başvuruyu hazırlayan ve süreci izleyen yetkili uzmandır.","ornek":"Buluşunu korumak isteyen girişimci bir patent vekiline gider; vekil araştırmayı yapar, tarifnameyi ve istemleri yazar, başvuruyu takip eder.","sektor":"Türkiye’de yaşayan kişiler başvuruyu kendileri de yapabilir; vekil tutmak zorunlu değildir. Ancak özellikle patentte istemlerin yanlış yazılması korumayı daraltabileceği için uzman desteği önerilir.","iliskili":["mg-6-058","mg-6-059","mg-6-062"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-6-065","konu":"6.4","terim":"Başvuru eylem planı","ingilizce":"Application action plan","tanim":"Korumaya değer bir fikir ya da ürün için hangi hakkın, hangi sırayla, kim tarafından ve ne zaman isteneceğini adım adım gösteren plandır.","ornek":"Grup planını yazar: özgün yanı belirle, uygun hak türünü seç, veri tabanında araştır, belgeleri hazırla, başvur, incelemeyi ve yayını izle, tescilden sonra yenileme tarihini not et.","sektor":"Planın ilk sorusu “Bu fikri özgün yapan ne?” sorusudur: teknik bir çözümse patent ya da faydalı model, görünümse tasarım, adsa marka, yazı ya da görsel ise telif hakkı. Plana maliyet ve takvim de yazılır; başvuru yapılana kadar fikrin ayrıntısı paylaşılmaz.","iliskili":["mg-6-023","mg-6-059","mg-6-057"],"kontrol":null,"cizim":"sozlesme"},{"id":"mg-6-075","konu":"6.4","terim":"Sorun, ihtiyaç ve çözüm fikri","ingilizce":"Problem, need and solution idea","tanim":"Bir ürün geliştirme sürecinin ilk üç basamağıdır: önce sorun fark edilir, sonra bunun yarattığı ihtiyaç belirlenir, ardından bu ihtiyacı karşılayacak özgün çözüm düşünülür.","ornek":"Otel mutfağında tepsilerin kayması sorundur; güvenli taşıma ihtiyaçtır; kaymayan yeni bir tutma düzeneği çözüm fikridir.","sektor":"Kat görevlisinin yatak yaparken bel ağrısı çekmesi bir sorun, bedenini yormadan çalışmak ihtiyaç, şilteyi kolayca kaldıran bir tutamak tasarlamak da çözüm fikridir. Turizmde iyi fikirler çoğu zaman masada değil katta, mutfakta ve resepsiyonda gözlenen küçük sorunlardan doğar; bu yüzden sorunu fark etmek çözüme giden yolun başlangıcıdır.","iliskili":["mg-6-065","mg-6-076","mg-6-068"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-6-076","konu":"6.4","terim":"Gelir beklentisi","ingilizce":"Expected revenue","tanim":"Fizibilite çalışmasında bir ürün ya da hizmetin hangi yoldan ve ne kadar gelir getirmesinin umulduğunun değerlendirilmesidir.","ornek":"Bir grup, akıllı takım askısını okul atölyelerine satarak ve bakım hizmeti sunarak gelir elde edeceğini hesaba katar.","sektor":"Bir iş fikrinin fizibilitesinde gelir beklentisi, hedef kitle, maliyet ve finansmanla birlikte düşünülür; bunlar Ünite 5’te anlatılır.","iliskili":["mg-6-065","mg-6-075","mg-6-059"],"kontrol":null,"cizim":"para-butce"}],"sorular":[{"id":"mg-6-s01","tur":"coktan-secmeli","soru":"Bir fotoğrafçı balon fotoğrafını çekti ama henüz hiçbir kuruma başvurmadı. Fotoğraf üzerindeki hakkı için hangisi doğrudur?","secenekler":["Hak, TÜRKPATENT’e başvurduğunda doğar.","Hak, fotoğraf çekildiği anda kendiliğinden doğar.","Hak, fotoğrafın altına © simgesi koyduğunda doğar.","Hak, fotoğraf ilk kez satıldığında doğar."],"dogru":1,"aciklama":"Telif hakkı eser ortaya çıktığı anda doğar; başvuru ya da simge gerekmez. © yalnızca eserin korunduğunu gösterir, hakkı doğurmaz."},{"id":"mg-6-s02","tur":"coktan-secmeli","soru":"Bir otel, fotoğrafçıdan izin alarak fotoğrafı internet sitesinde kullanıyor. Fotoğrafçı adının yazılmasını ve fotoğrafın özünün bozulmamasını istiyor. Bu istek eser sahibinin hangi haklarına dayanır?","secenekler":["Mali haklar","Rüçhan hakkı","Marka hakkı","Manevi haklar"],"dogru":3,"aciklama":"Adın belirtilmesi ve eserin izinsiz değiştirilmesinin önlenmesi manevi haklardır. Mali haklar eserden gelir elde etmeyi (çoğaltma, yayma gibi) sağlar."},{"id":"mg-6-s03","tur":"coktan-secmeli","soru":"Bir firma kat arabasına havluların düşmesini önleyen katlanır bir raf ekledi. Bu, sıfırdan bir buluş değil, var olan araçta pratik bir iyileştirmedir. En uygun koruma hangisidir?","secenekler":["Faydalı model","Patent","Endüstriyel tasarım","Hizmet markası"],"dogru":0,"aciklama":"Var olan ürüne kullanım kolaylığı katan çözümler faydalı modelle korunur. Patent sıfırdan, yeni bir teknik çözüm içindir; tasarım ise yalnız dış görünümü korur."},{"id":"mg-6-s04","tur":"coktan-secmeli","soru":"Koruma süreleri bakımından hangi eşleştirme doğrudur?","secenekler":["Patent 10 yıl, faydalı model 20 yıl","Patent 70 yıl, marka 10 yıl","Patent 20 yıl, faydalı model 10 yıl","Faydalı model 70 yıl, marka 20 yıl"],"dogru":2,"aciklama":"Patent 20 yıl, faydalı model 10 yıl korunur. 70 yıl, telif hakkının eser sahibinin ölümünden sonraki süresidir; patent ve faydalı modelle karıştırılmamalıdır."},{"id":"mg-6-s05","tur":"coktan-secmeli","soru":"Bir otelin tabeladaki adı ve logosu ile otelin kendine özel çizdirdiği lobi koltuğunun biçimi hangi haklarla korunabilir?","secenekler":["Ad ve logo patentle, koltuk faydalı modelle","Ad ve logo markayla, koltuk tasarımla","Ad ve logo tasarımla, koltuk markayla","Ad ve logo coğrafi işaretle, koltuk patentle"],"dogru":1,"aciklama":"Ad ve logo işletmeyi başkalarından ayırdığı için marka, koltuğun biçimi dış görünüm olduğu için tasarımdır. Patent teknik çözümleri korur, görünümü değil."},{"id":"mg-6-s06","tur":"coktan-secmeli","soru":"Pansiyon açacak bir aile, tabelayı bastırmadan önce düşündüğü adı TÜRKPATENT’in marka araştırma sayfasında sorguluyor. Bunun amacı nedir?","secenekler":["Adı başvuru yapmadan kendi adına tescil ettirmek","Adın patent şartlarını taşıyıp taşımadığını ölçmek","Tabela asmak için kurumdan izin belgesi almak","Benzer bir adın daha önce tescil edilip edilmediğini görmek"],"dogru":3,"aciklama":"Marka ön araştırması, aynı ya da benzer adın başkası adına tescilli olup olmadığını başvurudan önce gösterir; böylece sonradan ad değiştirme zorunluluğu ya da hak ihlali riski doğmaz. Sorgulamak tescil sayılmaz."},{"id":"mg-6-s07","tur":"coktan-secmeli","soru":"Antep baklavası bir coğrafi işaret, bir otelin adı ise markadır. Coğrafi işareti markadan ayıran özellik hangisidir?","secenekler":["Bir yöreyle özdeşleşmiş ürünü göstermesi","Yalnızca hizmetleri kapsaması","Yalnızca yurt dışında geçerli olması","Hak sahibinin adı belirtilmeden kullanılması"],"dogru":0,"aciklama":"Coğrafi işaret tek bir işletmeyi değil, kökeni bir yöreyle özdeşleşmiş ürünü gösterir. Marka ise bir işletmenin mal ya da hizmetini başkalarınınkinden ayırır."},{"id":"mg-6-s08","tur":"coktan-secmeli","soru":"Aydın inciri menşe adı, Antep baklavası ise mahreç işaretidir. Mahreç işaretini menşe adından ayıran özellik hangisidir?","secenekler":["Ürünün yöreyle bağının hiç aranmaması","Bütün aşamaların yörede yapılma şartı","En az bir aşamanın yörede yapılması yeterli","Tescil ettirilmesinin zorunlu olmaması"],"dogru":2,"aciklama":"Mahreç işaretinde üretim, işleme ya da diğer işlemlerden en az biri o yörede yapılır. Menşe adında ise bütün işlemler yörede yapılır ve ürün özelliklerini yörenin doğasından alır."},{"id":"mg-6-s09","tur":"coktan-secmeli","soru":"Bir öğrenci staj dosyasına internetten bulduğu otel tanıtım yazısını kaynak göstermeden yapıştırıp kendi adıyla teslim ediyor. Bu davranış nedir?","secenekler":["Korsan","İntihal","Taklit","Lisans"],"dogru":1,"aciklama":"Başkasının yazısını kaynak göstermeden kendi ürünüymüş gibi sunmak intihaldir. Korsan, telifli eserlerin (film, yazılım, müzik) izinsiz çoğaltılıp dağıtılmasıdır."},{"id":"mg-6-s10","tur":"coktan-secmeli","soru":"Turistik bir çarşıda, ünlü bir markanın logosu basılmış ama o markanın üretmediği çantalar satılıyor. Bu durum hangi kavramla anlatılır?","secenekler":["İntihal","Franchise","Korsan","Taklit"],"dogru":3,"aciklama":"Tescilli bir markanın izinsiz benzerini yapıp satmak taklittir. Franchise, marka sahibinin izin verip bedel aldığı yasal kullanımdır."},{"id":"mg-6-s11","tur":"coktan-secmeli","soru":"Bir otelin satın aldığı ön büro programının lisansı beş bilgisayar için verilmiş. Otel altıncı bilgisayara da kurmak istiyor. Doğru davranış hangisidir?","secenekler":["Ek lisans için program sahibiyle anlaşmak","Programın sahibi olduğu için kurmak","Kurulumu yapıp ek ücreti sonra konuşmak","Kurulum için TÜRKPATENT’ten izin almak"],"dogru":0,"aciklama":"Program satın alan otel sahibi olmaz, yalnız belirli koşullarla kullanma lisansı almış olur. Koşulu aşmak için hak sahibinin izni gerekir."},{"id":"mg-6-s12","tur":"coktan-secmeli","soru":"Bir otelin restoranı akşamları hoparlörden müzik yayını yapacak. Otel yönetimi bunun için kiminle sözleşme yapar?","secenekler":["Patent ve marka tescili yapan TÜRKPATENT","Müziği seçen vardiya personeli","Hak sahiplerini temsil eden meslek birlikleri","Merkezi Münih’te olan Avrupa Patent Ofisi"],"dogru":2,"aciklama":"Halka açık yerde müzik çalmak için hak sahiplerini temsil eden meslek birliklerinden izin alınır. TÜRKPATENT patent, marka ve tasarım başvurularıyla ilgilenir, müzik izniyle değil."},{"id":"mg-6-s13","tur":"coktan-secmeli","soru":"Bir belediye yöresel ürününü coğrafi işaretle korumak, bir mucit de buluşuna patent almak istiyor. İkisi başvurusunu Türkiye’de hangi kuruma yapar?","secenekler":["WIPO","TÜRKPATENT","EPO","Telif Hakları Genel Müdürlüğü"],"dogru":1,"aciklama":"Patent, faydalı model, marka, tasarım ve coğrafi işaret başvurularını Türkiye’de TÜRKPATENT alır ve inceler. WIPO ve EPO uluslararası kuruluşlardır."},{"id":"mg-6-s14","tur":"coktan-secmeli","soru":"Bir mucit önce Türkiye’de patent başvurusu yapıyor, birkaç ay sonra yurt dışında başvuruyor. Yurt dışındaki başvuru, Türkiye’deki ilk başvurunun tarihinde yapılmış gibi sayılıyor. Bu hak nedir?","secenekler":["Ülkesellik ilkesi","PCT başvurusu","Yenileme","Rüçhan hakkı"],"dogru":3,"aciklama":"İlk başvurunun tarihinden yararlanma, rüçhan (öncelik) hakkıdır. Ülkesellik ilkesi ise hakkın yalnız tescil edildiği ülkede geçerli olmasını anlatır."},{"id":"mg-6-s15","tur":"coktan-secmeli","soru":"Bir buluşa patent verilebilmesi için aranan şartlarla ilgili hangisi yanlıştır?","secenekler":["Buluşun yalnızca Türkiye’de yeni olması yeterlidir.","Buluşun uzman için sıradan bir adım olmaması gerekir.","Buluşun sanayide üretilebilir ya da kullanılabilir olması gerekir.","Buluşun başvuru tarihinden önce kamuya açıklanmamış olması gerekir."],"dogru":0,"aciklama":"Yenilik şartında bakılan, buluşun dünyanın hiçbir yerinde daha önce açıklanmamış olmasıdır. Yeni olma, buluş basamağı ve sanayiye uygulanabilirlik birlikte aranır."},{"id":"mg-6-s16","tur":"coktan-secmeli","soru":"Ali ile Ece birbirinden habersiz aynı kafe adını düşünüyor. Ali adı bir yıl önce düşündü ve logosunu çizdirdi ama başvuru yapmadı; Ece geçen hafta başvurdu. Kural olarak adı kim tescil ettirir?","secenekler":["Ali; adı daha önce düşündüğü için","Ali; logoyu önce çizdirdiği için","Ece; başvuruyu ilk yaptığı için","İkisi; ad ortak tescil edilir"],"dogru":2,"aciklama":"İlk başvuran ilkesine göre hak, başvuruyu daha önce yapana tanınır. Adı ya da logoyu önce hazırlamak ona öncelik vermez."},{"id":"mg-6-s17","tur":"dogru-yanlis","soru":"Bir otelin marka tescilinin süresi dolduğunda yenileme yapılmazsa marka koruması kendiliğinden devam eder.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Marka 10 yıl korunur; süre dolmadan yenileme yapılmazsa koruma sona erer. Yenileme için ücret ödenir."},{"id":"mg-6-s18","tur":"dogru-yanlis","soru":"Bir fotoğrafçı fotoğrafını CC BY lisansıyla paylaştıysa otel, adını belirterek ayrıca izin istemeden kullanabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Creative Commons, eser sahibinin belirli koşullarla (burada adının belirtilmesi) kullanıma önceden izin verdiğini gösterir. Koşul yerine getirilince ayrı izin gerekmez."},{"id":"mg-6-s19","tur":"dogru-yanlis","soru":"Adını yalnız Türkiye’de tescil ettiren bir otel zinciri, yurt dışında da aynı adla kendiliğinden korunur.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Sınai mülkiyet hakları ülkesellik ilkesine göre yalnız tescil edildiği ülkede korur. Yurt dışında koruma için o ülkede ya da uluslararası sistemle başvuru gerekir."},{"id":"mg-6-s20","tur":"dogru-yanlis","soru":"Bir ürünün başvuru tarihinden önce fuarda sergilenmesi, patent başvurusunda onun tekniğin bilinen durumuna girmesine yol açar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Tekniğin bilinen durumu, başvurudan önce kamuya açıklanmış her şeyi (belgeler, makaleler, fuarda sergilenen ürünler) kapsar; bu da yenilik şartını etkiler."},{"id":"mg-6-s21","tur":"senaryo","durum":"Otelin satış ofisinde stajdasın. Saat 10.00, şefin senden yeni spa broşürü için görsel bulmanı istiyor. İnternette çok güzel bir masaj odası fotoğrafı buluyorsun; kimin çektiği ve kullanım koşulu yazmıyor.","soru":"Ne yaparsın?","secenekler":["Fotoğrafı indirir, altına kaynağını yazarak kullanırım.","Fotoğrafı kırpıp rengini değiştirerek kullanırım.","İzninin belirsiz olduğunu şefime söyler, başka görsel isterim.","Fotoğrafı taslağa koyarım, şefim itiraz ederse çıkarırım."],"dogru":2,"aciklama":"İzni belirsiz görsel kullanılmaz; çoğu internet fotoğrafı telif hakkıyla korunur. Kırpmak ya da kaynak yazmak izin yerine geçmez, kullanıp sonra çıkarmak da hak ihlalini önlemez."},{"id":"mg-6-s22","tur":"senaryo","durum":"Havuz barında stajdasın. Saat 16.00, müzik sistemi bozuluyor. Bir iş arkadaşın “Telefonundaki müzik uygulamasını hoparlöre bağla, akşama kadar idare ederiz” diyor.","soru":"Nasıl davranırsın?","secenekler":["Arızayı şefime bildirir, müzik açmam.","Telefonumu bağlar, kişisel listemi açarım.","Telefonumu bağlar, sesi kısık tutarım.","Bir konuktan telefonunu bağlamasını rica ederim."],"dogru":0,"aciklama":"Halka açık yerde müzik için hak sahiplerini temsil eden meslek birliklerinden izin gerekir; kişisel uygulama bu izni karşılamaz. Sesin kısık olması ya da telefonun başkasına ait olması izin sorununu çözmez."},{"id":"mg-6-s23","tur":"senaryo","durum":"Restoranda stajdasın. Saat 21.30, bir ailenin doğum günü kutlamasında çok güzel bir an yakalıyorsun. Yanındaki stajyer “Telefonunla çek, kendi hesabında paylaş, otelin reklamı olur” diyor.","soru":"Ne yaparsın?","secenekler":["Çeker, yüzler az seçilen kareyi paylaşırım.","Çeker, yalnız yakın arkadaşlarımın gördüğü hesapta paylaşırım.","Çeker, paylaşıp aileye sonradan haber veririm.","Önce aileden açık izin isterim, vermezlerse paylaşmam."],"dogru":3,"aciklama":"Tanınan konuğun görüntüsü yalnız açık izinle paylaşılır. Gizli hesap, az görünen yüz ya da sonradan haber vermek izin yerine geçmez."},{"id":"mg-6-s24","tur":"senaryo","durum":"Bir seyahat acentesinde stajdasın. Saat 14.00, şefin senden acentenin sayfası için bir Kapadokya turu tanıtım yazısı istiyor. Rakip bir acentenin sitesinde çok iyi yazılmış bir metin görüyorsun.","soru":"Nasıl davranırsın?","secenekler":["Metni kopyalar, acentenin adını değiştiririm.","Tur programına bakarak yazıyı kendi cümlelerimle yazarım.","Metni kopyalar, birkaç sözcüğünü eş anlamlısıyla değiştiririm.","Metni kopyalar, şefim sorarsa kendim yazdığımı söylerim."],"dogru":1,"aciklama":"Kendi cümlelerinle yazmak hem intihalden hem de dürüst rekabet kuralını ihlal etmekten kaçınmanı sağlar. Adı ya da birkaç sözcüğü değiştirmek metni özgün yapmaz; “kendim yazdım” demek ayrıca yalandır."},{"id":"mg-6-s25","tur":"senaryo","durum":"Ön büroda stajdasın. Saat 11.00, bir bilgisayara ofis programı kurulması gerekiyor. Bir iş arkadaşın “Bende şifresi kırılmış kopyası var, beş dakikada kurarız, kimse anlamaz” diyor.","soru":"Ne yaparsın?","secenekler":["Kopyayı kurar, işi hızlıca bitiririm.","Kopyayı önce kendi bilgisayarımda deneyip bakarım.","Kurmam; lisans gerektiğini şefime söylerim.","Kurulumu arkadaşıma bırakır, karışmam."],"dogru":2,"aciklama":"Şifresi kırılmış kopya korsandır ve otel için hak ihlali demektir. Başka bilgisayarda denemek ya da karışmamak sorunu ortadan kaldırmaz; lisans yönetimin kararıdır."},{"id":"mg-6-s26","tur":"senaryo","durum":"Okulda grubunla birlikte, garsonların tepsiyi tek elle daha güvenli taşımasını sağlayan yeni bir düzenek geliştirdiniz. Bir arkadaşın “Çalışma videosunu bütün ayrıntısıyla hemen sosyal medyada paylaşalım” diyor. Henüz hiçbir başvuru yapılmadı.","soru":"İlk adımın ne olur?","secenekler":["Paylaşmayı erteler, önce başvuruyu araştırmayı öneririm.","Videoyu paylaşır, ilgi görürse başvuru yaparım.","Videoyu paylaşır, altına “fikir bize aittir” yazarım.","Düzeneği bir firmaya ayrıntısıyla gösterir, görüşünü alırım."],"dogru":0,"aciklama":"Buluş başvurudan önce kamuya açıklanırsa yenilik şartı kaybolabilir ve başkaları fikri kopyalayabilir. Altına not yazmak koruma sağlamaz; ayrıntıyı başkasına göstermek de açıklamadır."},{"id":"mg-6-s27","tur":"senaryo","durum":"Otelin restoranında stajdasın. Saat 12.00, yeni menü hazırlanıyor. Tatlı bölümüne “Antep baklavası” yazılmış; oysa mutfağa gelen baklavanın başka bir şehirdeki bir imalathaneden alındığını ve etiketinde bu adın geçmediğini fark ediyorsun.","soru":"Nasıl davranırsın?","secenekler":["Menüdeki adı kendi kararımla silip “baklava” yazarım.","Karışmam; menüyü yazan kişiye güvenirim.","Konuk sorarsa Gaziantep’ten geldiğini söylerim.","Fark ettiğim uyumsuzluğu şefime bildiririm."],"dogru":3,"aciklama":"Antep baklavası adı, tescildeki malzeme ve yönteme uyan ürün için kullanılabilen bir coğrafi işarettir. Doğru yol uyumsuzluğu yetkili kişiye bildirmektir; kendi başına menüyü değiştirmek yetkinin dışındadır, konuğa yanlış bilgi vermek de doğru değildir."},{"id":"mg-6-s28","tur":"coktan-secmeli","soru":"Bir öğrenci grubu, “hiç enerji almadan sonsuza kadar çalışan” bir bavul taşıma makinesi icat ettiğini söyleyip patent başvurusu yapıyor. Makine doğa yasalarına aykırı olduğu için üretilemiyor. Bu başvuru hangi ölçütü karşılamaz?","secenekler":["Yenilik","Sanayiye uygulanabilirlik","Buluş basamağı","Ayırt edici nitelik"],"dogru":1,"aciklama":"Üretilemeyen ya da kullanılamayan bir buluş sanayiye uygulanabilirlik şartını karşılamaz. Ayırt edici nitelik marka ve tasarım için aranan bir özelliktir, patent ölçütü değildir."},{"id":"mg-6-s29","tur":"coktan-secmeli","soru":"Bir otel, lobide çalınacak şarkılar ve broşüre basılacak fotoğraflar için hak sahiplerinden izin alıyor. Bu izinler eser sahibinin hangi haklarıyla ilgilidir?","secenekler":["Manevi haklar","Mali haklar","Rüçhan hakları","Tescil hakları"],"dogru":1,"aciklama":"Eseri çoğaltmak ve halka açık yerde kullanmak, eser sahibine gelir sağlayan mali haklardandır; bu yüzden izne bağlıdır."},{"id":"mg-6-s30","tur":"coktan-secmeli","soru":"Hangisi patentle korunamayan bir keşif örneğidir?","secenekler":["Bavulun altına tekerlek takılması","Kart çıkarınca elektriği kesen oda düzeneği","Tepsinin kaymasını önleyen tutma düzeneği","Doğada var olan bir bitkinin bulunması"],"dogru":3,"aciklama":"Doğada zaten var olan bir şeyi bulmak keşiftir ve patentle korunmaz; buluş ise teknik bir soruna getirilen yeni bir çözümdür."},{"id":"mg-6-s31","tur":"coktan-secmeli","soru":"Bir seyahat acentesinin adı, acentenin sunduğu tur ve rezervasyon işlerini rakiplerinin işlerinden ayırıyor. Bu ad hangi tür markadır?","secenekler":["Hizmet markası","Ticaret markası","Coğrafi işaret","Geleneksel ürün adı"],"dogru":0,"aciklama":"Turizm işletmeleri mal değil hizmet sattığı için acente, otel ve restoran adları hizmet markasıdır."},{"id":"mg-6-s32","tur":"coktan-secmeli","soru":"Bir girişimci oteline yalnızca “Deniz Manzaralı Otel” adını verip bunu marka olarak tescil ettirmek istiyor. Bu ad hangi eksiklik nedeniyle tescilde sorun yaşayabilir?","secenekler":["Yenilik şartını taşımaması","Sanayiye uygulanabilir olmaması","Ayırt edici nitelik taşımaması","Coğrafi kökeni göstermemesi"],"dogru":2,"aciklama":"Yalnızca hizmetin niteliğini anlatan, herkesin kullanabileceği bir söz oteli öbürlerinden ayırmaz; ayırt edici nitelik taşımadığı için tek başına marka olarak tescil edilmez."},{"id":"mg-6-s33","tur":"coktan-secmeli","soru":"Bir otel restoranının imza sosunun tarifini yalnız aşçıbaşı ve yardımcısı biliyor; tarif hiçbir kuruma kaydedilmemiş. Bu bilgi hangi kavramla anlatılır?","secenekler":["Patent","Ticari sır","Telif hakkı","Faydalı model"],"dogru":1,"aciklama":"İşletmeye rekabette üstünlük sağlayan ve gizli tutulan bilgi ticari sırdır; tescil edilmez, gizli kaldığı sürece korunur."},{"id":"mg-6-s34","tur":"coktan-secmeli","soru":"Bir otel, tanıtım filminde yüzyıllar önce yaşamış bir bestecinin eserini yeni yapılmış bir orkestra kaydından kullanmak istiyor. Eserin koruma süresi çoktan dolmuş. Hangisi doğrudur?","secenekler":["Eser de kayıt da serbesttir, izin gerekmez.","Kaydı yapan orkestra eserin sahibi olur.","Eser korunduğu için bestecinin ailesinden izin alınır.","Eser serbesttir, kaydı ise ayrıca korunuyor olabilir."],"dogru":3,"aciklama":"Koruma süresi dolan eser kamu malıdır ve izinsiz kullanılabilir; ancak o eserin bugün yapılmış kaydı üzerinde orkestranın ayrı hakları olabilir."},{"id":"mg-6-s35","tur":"dogru-yanlis","soru":"Bir logonun yanında ® ya da ™ simgesi bulunmaması, o logonun herkesçe serbestçe kullanılabileceğini gösterir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Türkiye’de bu simgeleri kullanmak zorunlu değildir; simgenin olmaması, adın ya da görselin serbest olduğu anlamına gelmez."},{"id":"mg-6-s36","tur":"coktan-secmeli","soru":"Bir yatırımcı kendi binasında, uluslararası bir otel zincirinin adını ve standartlarını kullanarak, bedel karşılığında otel işletiyor. Bu iş yapma biçimi hangisidir?","secenekler":["İsim hakkı (franchise)","Marka ön araştırması","Marka tescilinin yenilenmesi","Endüstriyel tasarım"],"dogru":0,"aciklama":"Tanınmış bir markanın adını ve iş yapma biçimini, kurallara uyma koşuluyla ve bedel karşılığında başka bir işletmeye kullandırmasına isim hakkı (franchise) denir."},{"id":"mg-6-s37","tur":"dogru-yanlis","soru":"Bir fotoğrafı otelin ticari broşüründe kullanmak için fotoğrafı çekenin adını yazmak tek başına yeterlidir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kaynak göstermek intihali önler ama kullanım izni yerine geçmez; ticari bir broşür için fotoğrafı çekenin izni de alınmalıdır."},{"id":"mg-6-s38","tur":"coktan-secmeli","soru":"Bir yayınevi, bastığı her kitap için yazarına düzenli ödeme yapıyor. Eserin izinli kullanımı karşılığında hak sahibine yapılan bu ödemeye ne denir?","secenekler":["Rüçhan bedeli","Tescil harcı","Telif ücreti","Yenileme bedeli"],"dogru":2,"aciklama":"Bir eseri, markayı ya da buluşu izinle kullananın hak sahibine ödediği bedel telif ücretidir; sektörde “royalty” denir."},{"id":"mg-6-s39","tur":"coktan-secmeli","soru":"Bir patent belgesinde koruma sınırını çizen, yazılmayan bir özelliğin korunmadığı bölüm hangisidir?","secenekler":["Özet","İstemler","Tarifname","Çizimler"],"dogru":1,"aciklama":"İstemler, buluşun hangi teknik özellikleri için koruma istendiğini madde madde belirtir; istemlerde yazılmayan özellik korunmaz."},{"id":"mg-6-s40","tur":"dogru-yanlis","soru":"PCT başvurusu tek bir uluslararası patent vermez; patenti verip vermemeye yine her ülkenin ya da bölgenin kendi ofisi karar verir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"PCT birçok ülkeye aynı anda başvurmayı kolaylaştırır, ama patenti her ülkenin ya da bölgenin kendi ofisi verir."},{"id":"mg-6-s41","tur":"coktan-secmeli","soru":"Avrupa Patent Ofisi (EPO) için hangisi doğrudur?","secenekler":["Bir Avrupa Birliği kurumudur.","Merkezi Cenevre’dedir.","Yalnız marka başvurusu alır.","Merkezi Münih’tedir."],"dogru":3,"aciklama":"EPO’nun merkezi Münih’tedir; Avrupa Patent Sözleşmesi’ne taraf ülkeler için patent verir ve bir Avrupa Birliği kurumu değildir. Cenevre ise WIPO’nun merkezidir."},{"id":"mg-6-s42","tur":"coktan-secmeli","soru":"Bir otel, kendi adına çok benzeyen bir marka başvurusunun resmî bültende yayımlandığını görüyor. Otel ne yapabilir?","secenekler":["Belirli süre içinde kuruma itiraz eder.","Başvuranın tabelasını kendisi indirir.","Kendi markasının yenilemesini bırakır.","Hiçbir şey yapamaz; bülten kesin karardır."],"dogru":0,"aciklama":"İncelemeden geçen marka başvurusu bültende duyurulur ve hakkı zarar görecek kişiler belirli süre içinde itiraz edebilir; benzer başvuruları izlemek hak sahibinin işidir."},{"id":"mg-6-s43","tur":"dogru-yanlis","soru":"Türkiye’de yaşayan bir girişimci, patent ya da marka başvurusunu vekil tutmadan kendisi de yapabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Türkiye’de yaşayan kişiler için vekil tutmak zorunlu değildir; ancak patentte istemler yanlış yazılırsa koruma daralabileceği için uzman desteği önerilir."}],"siralamalar":[{"id":"mg-6-r01","konu":"6.3","baslik":"Bu fikri biri benden önce buldu mu?","yonerge":"Bir buluş fikri için patent araştırmasının adımlarını doğru sıraya koy.","adimlar":["Araştıracağın teknoloji alanını belirle.","Bu alanı anlatan uygun anahtar sözcükleri seç.","TÜRKPATENT, WIPO Patentscope ve Espacenet gibi veri tabanlarında tarama yap.","Bulduğun belgenin bilgilerini kaydet; konunla ilgili ve diğer kaynaklarla tutarlı mı, değerlendir.","Mevcut teknolojiyle kendi fikrini karşılaştır ve aradaki temel farkı yaz."],"aciklama":"Anahtar sözcükler araştırılacak alana göre seçilir, tarama bu sözcüklerle yapılır; karşılaştırma ise ancak bulunan belgeler kaydedilip güvenilirliği tartıldıktan sonra yapılabilir."},{"id":"mg-6-r02","konu":"6.4","baslik":"Fikrini koruma altına almanın yolu","yonerge":"Fikrî ve sınai mülkiyet başvuru sürecinin adımlarını doğru sıraya koy.","adimlar":["Ürününün ya da hizmetinin hangi özelliğini korumak istediğini tek tek belirle.","Bu özelliğin niteliğine uygun fikrî ya da sınai mülkiyet hakkını seç.","Benzer bir marka, tasarım ya da teknik çözüm olup olmadığını araştır.","Seçtiğin hak türünün güncel kılavuzuna göre başvuru belgelerini hazırla.","Başvurunu TÜRKPATENT’in elektronik başvuru sistemi üzerinden yap.","Kurumun istediği işlemleri süresi içinde yerine getir ve başvuru kayıtlarını sakla."],"aciklama":"Neyin korunacağı bilinmeden hak türü seçilemez. Başvuru öncesi ön araştırma, belgelerin hazırlanmasından önce yapılır; çünkü benzer çözümlerin görülmesi başvurunun nasıl ifade edileceğini etkiler. Takip, başvuru yapıldıktan sonra başlar."},{"id":"mg-6-r03","konu":"6.4","baslik":"Küçük bir sorundan yeni bir ürüne","yonerge":"İş yerinde fark edilen bir sorundan özgün bir çözüm fikrine giden adımları doğru sıraya koy.","adimlar":["İş yerinde güvensiz, yavaş ya da yetersiz kalan bir işi fark et.","Sorunun kimleri etkilediğini, neden çıktığını ve var olan çözümlerin neden yetmediğini incele.","Bu ihtiyacı karşılayacak özgün çözüm seçenekleri üret.","Fikrinin mevcut ürünlerden hangi yönüyle ayrıldığını açıkça ortaya koy."],"aciklama":"Ürün geliştirme bir sorunun fark edilmesiyle başlar; mevcut durum incelenmeden doğru çözüm üretilemez. Bir fikrin yalnız farklı görünmesi yetmez, mevcut ürünlerden farkı en sonda açıkça gösterilmelidir."}],"acikSorular":[{"id":"mg-6-y01","konu":"6.1","soru":"Yeni açılan bir butik otel adını ve logosunu tabelasına, broşürdeki tanıtım fotoğraflarını ise internet sitesine koyacaktır. Adın ve logonun hangi hakla, broşür fotoğraflarının ise hangi hakla korunduğunu yazınız. İki hakkın doğuş biçimi bakımından farkını açıklayınız.","olcut":[{"metin":"Otel adı ve logosunun marka (sınai mülkiyet) hakkıyla korunduğunu belirtir.","puan":20},{"metin":"Broşürdeki fotoğrafların telif hakkıyla (fikrî mülkiyet) korunduğunu belirtir.","puan":20},{"metin":"Markanın korumasının kural olarak tescille elde edildiğini açıklar.","puan":25},{"metin":"Telif hakkının eser ortaya çıktığı anda kendiliğinden doğduğunu, tescil gerektirmediğini açıklar.","puan":35}],"ornek":"Otelin adı ve logosu marka olarak korunur; marka sınai mülkiyet hakkıdır. Broşürdeki fotoğraflar ise eser olduğu için telif hakkıyla korunur. İki hak arasındaki fark doğuş biçimindedir: marka koruması kural olarak TÜRKPATENT’e başvurup tescil ettirmekle elde edilir. Telif hakkı ise eser ortaya çıktığı anda kendiliğinden doğar, ayrıca bir kuruma başvurmak gerekmez. Bu yüzden otel adını tescil ettirmezse kaybetme riskiyle karşılaşabilir.","ipucu":"Korumanın nasıl elde edildiğine bakın: biri bir kuruma başvuru ister, öteki istemez."},{"id":"mg-6-y02","konu":"6.4","soru":"Pansiyon açmak isteyen bir aile tabela ve broşür bastırmadan önce düşündükleri adı TÜRKPATENT’te araştırmamıştır. Aynı ad daha önce başkası adına tescilli çıkarsa ne olacağını açıklayınız. Başvurudan önce yapılması gereken ön araştırmayı ve başvuruyu geciktirmenin sakıncasını yazınız.","olcut":[{"metin":"Marka ön araştırmasını (adın aynısının ya da benzerinin tescilli olup olmadığının kontrolünü) tanımlar.","puan":20},{"metin":"Araştırmanın, markanın tescil edileceği mal ve hizmet sınıflarına göre yapıldığını belirtir.","puan":15},{"metin":"Adın başkasına ait çıkması hâlinde tabela, broşür ve site giderlerinin boşa gideceğini açıklar.","puan":25},{"metin":"İlk başvuran ilkesine göre başvuruyu geciktirmenin başkasının önce tescil almasına yol açabileceğini açıklar.","puan":40}],"ornek":"Marka ön araştırması, seçilen adın aynısının ya da benzerinin daha önce tescil edilip edilmediğini başvurudan önce kontrol etmektir. Markalar kullanılacakları mal ve hizmet sınıflarına göre tescil edildiği için araştırma ilgili sınıflarda yapılır. Araştırma yapılmaz ve ad başkasına ait çıkarsa tabela, broşür ve internet sitesi için harcanan emek ve para boşa gider. Aynı ad için birden çok kişi başvurursa hak ilk başvurana tanındığından, başvuruyu geciktiren aile adı başkasına kaptırabilir.","ipucu":"Hakkı ilk düşünenin mi, ilk başvuranın mı kazandığını ve masrafın ne zaman yapıldığını düşünün."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":7,"baslik":"Teknolojik Gelişmeler ve Endüstriyel Dönüşüm","onay":true,"kazanimlar":["Endüstriyel dönüşümün ve teknolojik gelişmelerin, iş gücü piyasasındaki etkileri üzerine çıkarım yapabilme.","Dijital ve endüstriyel dönüşüm süreçlerinin ortaya çıkardığı yeni çalışma biçimlerini ve etkilerini yorumlayabilme.","Yenilikçi bir ürün veya hizmet modeli geliştirme deneyimlerini yansıtabilme."],"soz":"Teknoloji işlemi hızlandırır; konuğu ağırlayan yine insandır.","dersler":[{"baslik":"Teknoloji İşi Nasıl Değiştirir?","ilk":"mg-7-001"},{"baslik":"Buhardan Bilgisayara","ilk":"mg-7-005"},{"baslik":"Merkezde Makine mi, İnsan mı?","ilk":"mg-7-009"},{"baslik":"Resepsiyonda Ne Değişti?","ilk":"mg-7-013"},{"baslik":"Düşünen Yazılım, Konuşan Oda","ilk":"mg-7-017"},{"baslik":"Veri Ne İşe Yarar?","ilk":"mg-7-021"},{"baslik":"Hangi İşler Değişiyor?","ilk":"mg-7-066"},{"baslik":"Robotun Yapamadığı","ilk":"mg-7-047"},{"baslik":"Fabrika Akıllanınca","ilk":"mg-7-051"},{"baslik":"Gitmeden Görmek","ilk":"mg-7-055"},{"baslik":"Robot Yanında, Veri Elinde","ilk":"mg-7-061"},{"baslik":"Arıza Çıkmadan Önce","ilk":"mg-7-072"},{"baslik":"Ofis Nerede?","ilk":"mg-7-023"},{"baslik":"Başında Kimse Yokken","ilk":"mg-7-028"},{"baslik":"Ekranda da Aynı İnsan","ilk":"mg-7-032"},{"baslik":"Konuğun Verisi Emanettir","ilk":"mg-7-036"},{"baslik":"Dijital Kapıda Güvenlik","ilk":"mg-7-039"},{"baslik":"Altı Şapka, Tek Takvim","ilk":"mg-7-074"},{"baslik":"Kullanan mı, Üreten mi?","ilk":"mg-7-059"},{"baslik":"Fikrini Kâğıda Dök","ilk":"mg-7-063"},{"baslik":"Kime, Ne Sunuyoruz?","ilk":"mg-7-077"},{"baslik":"Fabrikanın Gözü","ilk":"mg-7-081"}],"kavramlar":[{"id":"mg-7-001","konu":"7.1","terim":"Teknoloji","ingilizce":"Technology","tanim":"İnsanların bir işi daha kolay, hızlı ya da güvenli yapmak için bilgiyi kullanarak geliştirdiği araç, yöntem ve sistemlerin bütünüdür.","ornek":"Eskiden resepsiyonda oda anahtarları duvardaki panoya asılırdı; bugün aynı iş kartlı kilit ve bilgisayar ekranıyla yapılıyor.","sektor":"Teknoloji amaç değil, araçtır: otelde asıl amaç konuğun rahat etmesidir. İyi teknoloji çalışana zaman kazandırır; çalışan bu zamanı konukla ilgilenmeye ayırır.","iliskili":["mg-7-002","mg-7-003","mg-7-011"],"kontrol":null,"gorsel":"m6-telefon-parcalari"},{"id":"mg-7-002","konu":"7.1","terim":"Endüstriyel dönüşüm","ingilizce":"Industrial transformation","tanim":"Yeni teknolojilerin üretim ve hizmet biçimini, kullanılan araçları ve çalışanlardan beklenen becerileri köklü biçimde değiştirmesidir.","ornek":"Bir seyahat acentesinde biletler eskiden elle yazılırdı; bugün aynı bilet birkaç dakikada ekrandan kesilip yolcunun telefonuna gönderiliyor.","sektor":"Dönüşüm yalnız fabrikayı değil, oteli ve acenteyi de değiştirir. Değişimi izleyen çalışan aranan kişi olur; “Ben böyle öğrendim” deyip duran geride kalır.","iliskili":["mg-7-001","mg-7-003","mg-7-004"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-003","konu":"7.1","terim":"Sanayi Devrimi","ingilizce":"Industrial Revolution","tanim":"Üretimin el emeğinden ve küçük atölyelerden makinelere ve fabrikalara geçmesiyle başlayan, ekonomiyi ve günlük yaşamı kökten değiştiren süreçtir.","ornek":"Tarih dersinde gördüğün sahne: bir yanda tezgâhında elle kumaş dokuyan usta, öbür yanda aynı kumaşı makineyle çok daha hızlı üreten fabrika.","sektor":"18. yüzyılda İngiltere’de başladığı kabul edilir. Sonraki büyük değişimler de birer devrim sayıldığı için bugün Endüstri 1.0’dan Endüstri 4.0’a uzanan bir sıradan söz edilir.","iliskili":["mg-7-005","mg-7-006","mg-7-007"],"kontrol":null,"cizim":"enerji"},{"id":"mg-7-004","konu":"7.1","terim":"İş gücü piyasası","ingilizce":"Labour market","tanim":"İş arayanlar ile çalışan arayan işverenlerin buluştuğu, hangi mesleğe ve beceriye ne kadar ihtiyaç olduğunu gösteren ortamdır.","ornek":"Sezon öncesinde bir tatil beldesindeki oteller “yabancı dil bilen, rezervasyon programı kullanabilen ön büro personeli” arayan ilanlar yayımlar.","sektor":"Teknoloji bu piyasayı sürekli değiştirir: bazı işlere ihtiyaç azalır, yenileri ortaya çıkar. İlanlarda hangi becerilerin arandığına bakmak, kendini neye hazırlaman gerektiğini gösterir.","iliskili":["mg-7-002","mg-7-043","mg-7-045"],"kontrol":null},{"id":"mg-7-005","konu":"7.1","terim":"Endüstri 1.0","ingilizce":"Industry 1.0 (First Industrial Revolution)","tanim":"Su ve buhar gücüyle çalışan makinelerin üretimde kullanılmaya başlandığı ilk sanayi devrimidir.","ornek":"Buhar makinesiyle çalışan dokuma fabrikası ve raylarda giden buharlı lokomotif bu dönemin simgeleridir.","sektor":"18. yüzyılın sonlarında, buhar gücünün üretimde kullanılmaya başlanmasıyla ortaya çıktığı kabul edilir. Kas gücünün yerini makine gücü aldı; buharlı tren ve gemi sayesinde insanlar daha uzağa, daha kısa sürede gidebildi.","iliskili":["mg-7-003","mg-7-006","mg-7-007"],"kontrol":null,"gorsel":"lokomotif"},{"id":"mg-7-006","konu":"7.1","terim":"Endüstri 2.0","ingilizce":"Industry 2.0 (Second Industrial Revolution)","tanim":"Elektriğin üretime girmesi ve üretim bandı sayesinde aynı ürünün çok sayıda ve hızlı üretildiği, yani seri üretimin başladığı dönemdir.","ornek":"Bant üzerinde ilerleyen otomobil gövdesine her işçinin yalnız kendi parçasını taktığı fabrika.","sektor":"19. yüzyılın sonlarından başlayarak yayıldığı kabul edilir. Seri üretim ürünleri ucuzlattı; elektrikli aydınlatma ve elektrikli asansör de yüksek katlı otel binalarını kullanışlı hâle getirdi.","iliskili":["mg-7-005","mg-7-007","mg-7-003"],"kontrol":null,"gorsel":"m6-elektrik-turbini"},{"id":"mg-7-007","konu":"7.1","terim":"Endüstri 3.0","ingilizce":"Industry 3.0 (Third Industrial Revolution)","tanim":"Elektronik ve bilgisayarın üretime girmesiyle makinelerin programlanarak kendi kendine çalışmaya başladığı dönemdir.","ornek":"Fabrikada programlanmış bir makinenin aynı parçayı her seferinde aynı ölçüde kesmesi; otelde rezervasyonların defter yerine bilgisayara işlenmesi.","sektor":"20. yüzyılın ikinci yarısında başladığı kabul edilir; “Dijital Devrim” diye de anılır. Bilgisayar ve internet bu dönemde yaygınlaştı; bugünkü rezervasyon sistemlerinin temeli burada atıldı.","iliskili":["mg-7-006","mg-7-008","mg-7-011"],"kontrol":null},{"id":"mg-7-008","konu":"7.1","terim":"Endüstri 4.0","ingilizce":"Industry 4.0","tanim":"Makinelerin, ürünlerin ve bilgisayarların internet üzerinden birbirine bağlanıp veri paylaşarak üretimi büyük ölçüde kendi kendine yönettiği dönemdir.","ornek":"Üretim bandındaki makine bir parçasının aşındığını algılar, bakım ekibine haber verir ve yedek parça siparişi kendiliğinden açılır.","sektor":"Programın anahtar kavramlarındandır. Kavram 2010’lu yılların başında Almanya’da ortaya atıldı. Yapay zekâ, nesnelerin interneti, büyük veri ve robotik bu dönemin temel teknolojileridir; aynı teknolojiler otelde akıllı oda, sohbet robotu ve dinamik fiyatlama olarak karşına çıkar.","iliskili":["mg-7-007","mg-7-009","mg-7-051"],"kontrol":null,"cizim":"yapay-zeka"},{"id":"mg-7-009","konu":"7.1","terim":"Toplum 5.0","ingilizce":"Society 5.0","tanim":"Teknolojinin yalnız üretimi hızlandırmak için değil, insanın yaşamını kolaylaştırmak ve toplumun sorunlarını çözmek için kullanılmasını savunan anlayıştır.","ornek":"Görme engelli bir konuğun telefonuna otelin içinde sesli yön tarifi veren bir uygulama: teknoloji burada insanın hayatını kolaylaştırmak için çalışır.","sektor":"Programın anahtar kavramlarındandır. Japonya’da ortaya atılmıştır. Programdaki tartışma cümlesi akılda tutulur: Endüstri 4.0 makinenin verimine, Toplum 5.0 insana odaklanır. Otelcilik zaten insanı merkeze alan bir iştir.","iliskili":["mg-7-008","mg-7-010","mg-7-061"],"kontrol":null},{"id":"mg-7-010","konu":"7.1","terim":"Endüstri 5.0","ingilizce":"Industry 5.0","tanim":"İnsanı yeniden merkeze alan, insan ile akıllı makinenin yan yana ve iş birliği içinde çalıştığı üretim anlayışıdır.","ornek":"Atölyede ağır parçayı robot kol kaldırır, ince işçiliği ve son kontrolü usta yapar; ikisi aynı tezgâhta birlikte çalışır.","sektor":"Programın anahtar kavramlarından; program onu Toplum 5.0 ile birlikte anar. Ayrı bir sanayi devrimi sayılıp sayılmayacağı hâlâ tartışılır; ortak fikir, teknolojinin insanın yerine değil, insanla birlikte çalışmasıdır.","iliskili":["mg-7-008","mg-7-009","mg-7-052"],"kontrol":null,"gorsel":"m6-ur16e-cobot"},{"id":"mg-7-011","konu":"7.1","terim":"Otomasyon","ingilizce":"Automation","tanim":"Bir işin insan eli değmeden ya da çok az insan müdahalesiyle makineler ve yazılımlar tarafından kendiliğinden yapılmasıdır.","ornek":"Konuk çıkış yaptığında sistemin faturayı kendiliğinden hazırlayıp e-postayla göndermesi; koridor ışıklarının hareket algılayınca yanması.","sektor":"Programın anahtar kavramlarındandır. Otomasyon tekrar eden, rutin işleri üstlenir; çalışana konukla ilgilenecek zaman kalır. Sistem durduğunda işi elle yürütebilmek için işin mantığını bilmek yine gerekir.","iliskili":["mg-7-012","mg-7-014","mg-7-052"],"kontrol":null},{"id":"mg-7-012","konu":"7.1","terim":"Dijitalleşme","ingilizce":"Digitalisation","tanim":"Kâğıt üzerinde ya da elle yürütülen işlerin bilgisayar, telefon ve internet gibi dijital araçlarla yürütülür hâle getirilmesidir.","ornek":"Restoranda basılı menü yerine masadaki karekodun okutulması; konuk kayıt formunun kâğıt yerine tablette doldurulması.","sektor":"Bilgi hızlı bulunur, kâğıt azalır, yapılan işlem izlenebilir. Ama dijital kayıt da emanettir: ekranı açık bırakmak, kâğıdı masada unutmakla aynı hatadır.","iliskili":["mg-7-011","mg-7-013","mg-7-037"],"kontrol":null,"gorsel":"m6-dokunmatik-ekran"},{"id":"mg-7-013","konu":"7.1","terim":"Çevrim içi rezervasyon","ingilizce":"Online booking","tanim":"Konuğun otel odasını, uçak biletini ya da turu internet sitesi veya uygulama üzerinden kendisinin ayırtmasıdır.","ornek":"Gece 23.40, İzmir’de bir aile telefondan Kapadokya’daki bir otelin sitesine girer, tarihleri seçer ve odayı birkaç dakikada ayırtır.","sektor":"Rezervasyon artık mesai saatine bağlı değildir; konuk fiyatları ve yorumları karşılaştırarak gelir. Bu yüzden sitede gördüğüyle otelde bulduğu aynı olmalıdır.","iliskili":["mg-7-012","mg-7-015","mg-7-022"],"kontrol":null},{"id":"mg-7-014","konu":"7.1","terim":"Self check-in kiosku","ingilizce":"Self check-in kiosk","tanim":"Konuğun, resepsiyon görevlisine uğramadan giriş işlemini dokunmatik ekrandan kendisinin yaptığı cihazdır.","ornek":"Gece 02.00, bir havalimanı otelinin lobisi: konuk rezervasyon numarasını ekrana girer, bilgilerini onaylar ve oda kartını cihazdan alır.","sektor":"Havalimanlarındaki biniş kartı kiosklarının oteldeki karşılığıdır; yoğun saatte sırayı kısaltır. Cihazın yakınında yardıma hazır, güler yüzlü bir personelin bulunması konuğu yalnız bırakmaz.","iliskili":["mg-7-011","mg-7-015","mg-7-050"],"kontrol":null,"kitapDisi":true,"gorsel":"m6-otel-kiosk"},{"id":"mg-7-015","konu":"7.1","terim":"Mobil check-in","ingilizce":"Mobile check-in","tanim":"Konuğun otele gelmeden önce giriş işlemlerini telefonundaki uygulama ya da kendisine gönderilen bağlantı üzerinden tamamlamasıdır.","ornek":"Varıştan bir gün önce konuğun telefonuna bir bağlantı gelir; konuk bilgilerini doldurur ve tahminî geliş saatini bildirir.","sektor":"Konuk resepsiyonda form doldurmakla vakit kaybetmez; görevli de ekrana değil konuğa bakarak “Hoş geldiniz” diyebilir. İşlem telefonda başlasa da konuğun kimliği otelde yine doğrulanır.","iliskili":["mg-7-013","mg-7-014","mg-7-016"],"kontrol":null,"kitapDisi":true},{"id":"mg-7-016","konu":"7.1","terim":"Dijital anahtar","ingilizce":"Digital key","tanim":"Oda kapısının kart ya da metal anahtar yerine konuğun telefonuyla açılmasını sağlayan sistemdir.","ornek":"Konuk telefonunu kapı kilidine yaklaştırır, kilit açılır; ayrılış günü geldiğinde anahtarın geçerliliği kendiliğinden sona erer.","sektor":"Kaybolan kart sorunu azalır. Güvenlik kuralı ise değişmez: kimliği doğrulanmayan kişiye kart da dijital anahtar da verilmez.","iliskili":["mg-7-015","mg-7-020","mg-7-039"],"kontrol":null,"kitapDisi":true},{"id":"mg-7-017","konu":"7.1","terim":"Yapay zekâ","ingilizce":"Artificial intelligence (AI)","tanim":"Bilgisayarların ve yazılımların öğrenme, anlama, tahmin etme ve karar verme gibi insan zekâsı gerektiren işleri yapabilmesini sağlayan teknolojidir.","ornek":"Bir çeviri uygulamasının konuğun yabancı dildeki mesajını anında Türkçeye çevirmesi; bir sistemin geçmiş yıllara bakarak otelin hangi hafta dolacağını tahmin etmesi.","sektor":"Programın anahtar kavramlarındandır. Yapay zekâ hızlıdır ama yanılabilir ve sorumluluk almaz: ürettiği bilgiyi kontrol etmek ve son kararı vermek insanın işidir. Konuk verisi bu araçlara gelişigüzel yazılmaz.","iliskili":["mg-7-018","mg-7-021","mg-7-035"],"kontrol":null,"gorsel":"m6-poppy-robot"},{"id":"mg-7-018","konu":"7.1","terim":"Sohbet robotu","ingilizce":"Chatbot","tanim":"Konukların yazdığı sorulara internet sitesinde ya da mesajlaşma uygulamasında kendiliğinden cevap veren yazılımdır.","ornek":"Gece 03.00’te bir konuk otelin sitesine “Kahvaltı kaçta başlıyor?” diye yazar; sohbet robotu saati hemen bildirir.","sektor":"Sık sorulan soruları günün her saatinde cevaplar. Şikâyet, özel istek ya da üzgün bir konuk söz konusuysa görüşme bir insana devredilmelidir; orada anlayış gerekir.","iliskili":["mg-7-017","mg-7-011","mg-7-050"],"kontrol":null,"gorsel":"m6-sanal-asistan"},{"id":"mg-7-019","konu":"7.1","terim":"Nesnelerin interneti","ingilizce":"Internet of Things (IoT)","tanim":"Günlük eşyaların ve cihazların internete bağlanarak birbirleriyle ve bir merkezle veri alışverişi yapmasıdır.","ornek":"Odadaki klimanın, pencerenin açıldığını algılayınca kendiliğinden kapanması; minibarın eksilen ürünü sisteme bildirmesi.","sektor":"Programın anahtar kavramlarındandır. Enerji tasarrufu sağlar ve arızayı konuk fark etmeden haber verebilir. İnternete bağlı her cihaz aynı zamanda korunması gereken bir kapıdır.","iliskili":["mg-7-020","mg-7-008","mg-7-039"],"kontrol":null},{"id":"mg-7-020","konu":"7.1","terim":"Akıllı oda","ingilizce":"Smart room","tanim":"Işık, klima, perde ve televizyon gibi donanımların birbirine bağlı olduğu ve tek bir ekrandan, telefondan ya da sesle yönetilebildiği otel odasıdır.","ornek":"Konuk kartını yuvaya takınca perdeler açılır, ışıklar yanar, klima ayarlanan sıcaklığa geçer; konuk çıkınca hepsi kapanır.","sektor":"Konuk için konfor, otel için enerji tasarrufu demektir. Her konuk teknolojiye alışık değildir: düğmeleri nazikçe göstermek hâlâ personelin işidir.","iliskili":["mg-7-019","mg-7-016","mg-7-050"],"kontrol":null,"kitapDisi":true},{"id":"mg-7-021","konu":"7.1","terim":"Büyük veri","ingilizce":"Big data","tanim":"Çok sayıda kaynaktan sürekli gelen, elle incelenemeyecek kadar büyük olan ve ancak özel yazılımlarla çözümlenebilen veri yığınıdır.","ornek":"Bir otel zincirinin yıllar boyunca biriken rezervasyon, konaklama süresi ve konuk yorumu kayıtlarının birlikte incelenmesi.","sektor":"Programın anahtar kavramlarındandır. Veri doğru okunursa otel hangi dönemde kimin geldiğini, konukların nelerden şikâyet ettiğini görür ve hazırlığını ona göre yapar. Yanlış girilen kayıt yanlış karara götürür; kaydı doğru girmek senin işindir.","iliskili":["mg-7-017","mg-7-022","mg-7-023"],"kontrol":null,"gorsel":"m6-sunucu-salonu"},{"id":"mg-7-022","konu":"7.1","terim":"Dinamik fiyatlama","ingilizce":"Dynamic pricing","tanim":"Oda ya da bilet fiyatının talebe, tarihe ve doluluğa göre yazılım yardımıyla sürekli güncellenmesidir.","ornek":"Aynı oda, şehirde büyük bir kongrenin yapıldığı hafta daha yüksek, sakin bir kış haftasında daha düşük fiyatla satışa çıkar.","sektor":"Hava yolları ve oteller yaygın olarak kullanır. Konuk “Arkadaşım aynı odayı neden daha ucuza aldı?” diye sorabilir; fiyatın tarihe ve doluluğa göre değiştiği dürüstçe, sakin bir dille açıklanır.","iliskili":["mg-7-021","mg-7-013","mg-7-043"],"kontrol":null,"kitapDisi":true,"cizim":"para-butce"},{"id":"mg-7-066","konu":"7.1","terim":"Tarım Devrimi","ingilizce":"Agricultural Revolution","tanim":"İnsanların avcılık ve toplayıcılıktan yerleşik yaşama geçip tarım ve hayvancılık yapmaya başladığı, ekonomik ve toplumsal yaşamı kökten değiştiren dönüşümdür.","ornek":"Anadolu’da Konya yakınlarındaki Çatalhöyük gibi yerleşimlerde insanlar tarım ve hayvancılıkla yerleşik düzene geçmiştir.","sektor":"Her büyük dönüşümde bazı işler azalmış, yenileri doğmuştur. Tarım Devrimi, Sanayi Devrimi ve dijital dönüşümle birlikte düşünüldüğünde Endüstri 4.0 ve Toplum 5.0, “değişim ve süreklilik” içinde anlaşılır; bugünkü dijital dönüşüm bu çizginin devamıdır.","iliskili":["mg-7-003","mg-7-002","mg-7-011"],"kontrol":null,"cizim":"doga"},{"id":"mg-7-042","konu":"7.1","terim":"Geleneksel iş rolü","ingilizce":"Traditional job role","tanim":"Uzun süredir bilinen araç ve yöntemlerle, çoğunlukla elle ve yüz yüze yürütülen görev tanımıdır.","ornek":"Rezervasyonları telefonla alıp büyük bir deftere tek tek yazan rezervasyon memuru.","sektor":"Geleneksel rol çoğu zaman yok olmaz, biçim değiştirir: defter gider, ekran gelir; konuğu doğru anlamak ve kaydı hatasız tutmak aynı kalır.","iliskili":["mg-7-043","mg-7-044","mg-7-002"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-043","konu":"7.1","terim":"Yeni iş rolü","ingilizce":"Emerging job role","tanim":"Teknolojik gelişmelerin ortaya çıkardığı, daha önce bulunmayan ya da içeriği büyük ölçüde değişmiş görev tanımıdır.","ornek":"Otelin sosyal medya hesaplarını yöneten, internetteki konuk yorumlarını cevaplayan ya da oda fiyatlarını veriye bakarak belirleyen çalışan.","sektor":"Otellerde çevrim içi satış, gelir yönetimi ve dijital pazarlama gibi alanlarda çalışanlar bulunur. Bu roller hem otelciliği hem dijital araçları bilen kişi ister.","iliskili":["mg-7-042","mg-7-044","mg-7-004"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-044","konu":"7.1","terim":"Geleceğin meslekleri","ingilizce":"Jobs of the future","tanim":"Teknolojideki ve toplumdaki değişimler nedeniyle önümüzdeki yıllarda ihtiyacın artması beklenen meslekler ve uzmanlık alanlarıdır.","ornek":"Mesleki gelişim dersinde gruplar, turizmde teknolojiyle birlikte hangi işlere ihtiyaç duyulabileceğini araştırıp sınıfa sunar.","sektor":"Hangi mesleğin ne kadar büyüyeceğini kimse kesin bilemez; listeler sık değişir. Güvenli yol tek bir unvana değil, öğrenmeyi sürdürmeye ve insanlarla iyi çalışmaya yatırım yapmaktır.","iliskili":["mg-7-043","mg-7-045","mg-7-047"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-045","konu":"7.1","terim":"Yetkinlik","ingilizce":"Competence","tanim":"Bir işi başarıyla yapmak için gereken bilgi, beceri ve tutumun bütünüdür.","ornek":"İyi bir resepsiyon görevlisi sistemi kullanmayı bilir (bilgi), konuğu hızlı ve hatasız kaydeder (beceri), güler yüzlü ve sabırlıdır (tutum).","sektor":"Teknoloji bilgi ve beceri kısmını sık sık değiştirir; doğru tutum ise her dönemde aranır. İş ilanları unvandan çok yetkinlik sayar.","iliskili":["mg-7-046","mg-7-047","mg-7-004"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-046","konu":"7.1","terim":"Dijital yetkinlik","ingilizce":"Digital competence","tanim":"İş hayatının gerektirdiği dijital araçları doğru, verimli ve güvenli kullanabilmek için gereken bilgi, beceri ve tutumun bütünüdür.","ornek":"Stajyer, bir konuğun sorduğu müzenin açılış saatini müzenin resmî sitesinden doğrulayarak söyler; ilk gördüğü yoruma güvenmez.","sektor":"Telefonda vakit geçirmeyi bilmek dijital yetkinlik demek değildir. Otelde beklenen şudur: sistemi doğru kullanmak, bilgiyi doğrulamak ve veriyi korumak.","iliskili":["mg-7-045","mg-7-033","mg-7-048"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-047","konu":"7.1","terim":"Meslekte sürekli öğrenme","ingilizce":"Continuous professional learning","tanim":"Çalışanın mesleğe başladıktan sonra da değişen araç ve yöntemleri izleyerek bilgi ve becerisini yenilemeyi sürdürmesidir.","ornek":"Yıllardır çalışan bir resepsiyon şefi, otel yeni bir sisteme geçince eğitime katılır; boş zamanında ikinci yabancı dilini ilerletir.","sektor":"Yaşam boyu öğrenmenin iş hayatındaki karşılığıdır. Teknoloji değiştikçe dün öğrenilen yöntem eskir. Kendini yenileyen çalışan değişimden korkmaz; yeniliği ilk öğrenen, ekipte danışılan kişi olur.","iliskili":["mg-7-048","mg-7-049","mg-7-045"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-7-048","konu":"7.1","terim":"Beceri yenileme","ingilizce":"Reskilling and upskilling","tanim":"Çalışanın değişen işe uyum sağlamak için mevcut becerilerini geliştirmesi ya da yeni bir beceri kazanmasıdır.","ornek":"Otel kâğıt formdan tablete geçince kat hizmetleri ekibine oda durumunu tabletten bildirmeyi öğreten kısa bir eğitim verilir.","sektor":"Sektörde mevcut beceriyi geliştirmeye “upskilling”, yeni bir alanda beceri kazanmaya “reskilling” denir. İşletmeler bunun için hizmet içi eğitim düzenler; eğitime istekle katılmak profesyonelliktir.","iliskili":["mg-7-047","mg-7-049","mg-7-046"],"kontrol":null,"kitapDisi":true,"cizim":"egitim-kariyer"},{"id":"mg-7-049","konu":"7.1","terim":"Uyum yeteneği","ingilizce":"Adaptability","tanim":"Kişinin yeni koşullara, araçlara ve çalışma biçimlerine direnmeden, kısa sürede alışabilmesidir.","ornek":"Sistemin değiştiği hafta “Eskisi daha iyiydi” diye yakınmak yerine yeni ekranı deneyen ve öğrendiğini arkadaşlarına da gösteren görevli.","sektor":"Turizmde değişim süreklidir: yeni sistem, yeni konuk beklentisi, yeni kural. Uyum sağlayan çalışan ekibin yükünü hafifletir.","iliskili":["mg-7-047","mg-7-048","mg-7-050"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-050","konu":"7.1","terim":"İnsani dokunuş","ingilizce":"Human touch","tanim":"Hizmette makinenin veremediği; güler yüz, içten ilgi, anlayış ve kişiye özel özenle kurulan insan ilişkisidir.","ornek":"Konuk girişini kiosktan yapar; lobideki görevli yine de yanına gidip “Hoş geldiniz, yolculuğunuz nasıl geçti?” diye sorar ve valizine yardım eder.","sektor":"Sektörde “human touch” denir. Teknoloji işlemi hızlandırır, konuğu ağırlayan ise insandır: yorgun konuğu fark etmek, üzgün olanı sakinleştirmek, adıyla hitap etmek. Rutin işi makine üstlendikçe bu beceri daha değerli olur.","iliskili":["mg-7-014","mg-7-018","mg-7-053"],"kontrol":null,"kitapDisi":true},{"id":"mg-7-051","konu":"7.1","terim":"Akıllı üretim","ingilizce":"Smart manufacturing","tanim":"Makinelerin algılayıcılar ve yazılımlar aracılığıyla veri toplayıp birbirleriyle haberleşerek üretimi izlediği, ayarladığı ve hataları erkenden haber verdiği üretim biçimidir.","ornek":"Bir fabrikada üretim hattı, hatalı çıkan ürünü kamerayla fark edip ayırır ve makinenin ayarını kendiliğinden düzeltir.","sektor":"Programın anahtar kavramlarından; Endüstri 4.0’ın fabrikadaki görünüşüdür. Büyük otel mutfakları ve çamaşırhaneleri de sıcaklığı, süreyi ve tüketimi izleyen bağlantılı makineler kullanabilir.","iliskili":["mg-7-008","mg-7-052","mg-7-055"],"kontrol":null,"gorsel":"m6-robot-uretim-hatti"},{"id":"mg-7-052","konu":"7.1","terim":"Robotik","ingilizce":"Robotics","tanim":"Belirli işleri kendiliğinden yapabilen programlanabilir makinelerin, yani robotların tasarlanması, üretilmesi ve kullanılmasıyla ilgilenen teknoloji alanıdır.","ornek":"Otomobil fabrikasında kaynak yapan robot kollar; depoda rafların arasında koli taşıyan robot araçlar.","sektor":"Programın anahtar kavramlarındandır. Robot tekrar eden, ağır ya da tehlikeli işte güçlüdür ve yorulmaz; beklenmedik durumu yorumlamakta ve insanı anlamakta ise zayıftır.","iliskili":["mg-7-053","mg-7-011","mg-7-010"],"kontrol":null},{"id":"mg-7-053","konu":"7.1","terim":"Hizmet robotu","ingilizce":"Service robot","tanim":"Fabrikada üretim yapmak yerine temizlik, taşıma ya da bilgi verme gibi işlerle insanlara doğrudan hizmet eden robottur.","ornek":"Bir otelin lobisinde gece boyunca zemini silen temizlik robotu; restoranda tabakları masanın yanına kadar taşıyan robot.","sektor":"Bazı otel ve restoranlarda temizlik ve taşıma işlerinde kullanılır. Robot taşıma işini yapar; konuğa “Afiyet olsun” demek ve masadaki eksiği fark etmek yine personelin işidir.","iliskili":["mg-7-052","mg-7-050","mg-7-011"],"kontrol":null,"kitapDisi":true,"gorsel":"ek-otel-servis-robotu"},{"id":"mg-7-054","konu":"7.1","terim":"3D yazıcı","ingilizce":"3D printer (additive manufacturing)","tanim":"Bilgisayarda tasarlanan bir nesneyi, malzemeyi katman katman üst üste ekleyerek üreten makinedir.","ornek":"Okulun atölyesinde öğrenciler, kırılan bir makine düğmesinin aynısını bilgisayarda çizip 3D yazıcıdan çıkarır.","sektor":"Programın anahtar kavramlarından; “3B yazıcı” da denir, bu üretim biçiminin adı ise eklemeli imalattır. Az sayıda ve kişiye özel parça üretmeyi kolaylaştırır: kalıp gerekmez, tasarım değişince ürün de değişir.","iliskili":["mg-7-051","mg-7-055","mg-7-062"],"kontrol":null,"gorsel":"sektor-3b-yazici"},{"id":"mg-7-055","konu":"7.1","terim":"Dijital ikiz","ingilizce":"Digital twin","tanim":"Gerçek bir makinenin, binanın ya da sistemin bilgisayar ortamında oluşturulan ve ondan gelen verilerle güncellenen sanal kopyasıdır.","ornek":"Bir otel binasının sanal modeli üzerinde, klima sistemindeki bir ayar değişikliğinin enerji tüketimini nasıl etkileyeceği önce bilgisayarda denenir.","sektor":"Programın anahtar kavramlarındandır. Denemeyi gerçeğinde yapmadan önce kopyasında yapmak zaman ve para kazandırır, riski azaltır.","iliskili":["mg-7-051","mg-7-019","mg-7-057"],"kontrol":null,"gorsel":"f3e-dijital-ikiz-tarama"},{"id":"mg-7-056","konu":"7.1","terim":"Artırılmış gerçeklik","ingilizce":"Augmented reality (AR)","tanim":"Telefon ya da gözlük aracılığıyla gerçek görüntünün üzerine yazı, resim ya da üç boyutlu model gibi dijital bilgilerin eklenmesidir.","ornek":"Ören yerinde ziyaretçi telefonunu yıkık bir tapınağa tutar; ekranda yapının sağlam hâli gerçek görüntünün üzerine çizilir.","sektor":"Programın anahtar kavramlarındandır. Kişi gerçek ortamı görmeye devam eder; sanal gerçeklikten farkı budur. Müzelerde ve ören yerlerinde ziyareti zenginleştirmek için kullanılır.","iliskili":["mg-7-057","mg-7-058","mg-7-055"],"kontrol":null,"gorsel":"mg-artirilmis-gerceklik"},{"id":"mg-7-057","konu":"7.1","terim":"Sanal gerçeklik","ingilizce":"Virtual reality (VR)","tanim":"Özel bir gözlükle kişinin gerçek ortamdan ayrılıp bütünüyle bilgisayarda oluşturulmuş bir ortamın içindeymiş gibi hissetmesini sağlayan teknolojidir.","ornek":"Turizm fuarında bir ziyaretçi gözlüğü takar ve kendini bir sıcak hava balonunda, Kapadokya vadilerinin üzerinde bulur.","sektor":"Programın anahtar kavramlarındandır. Tanıtımda ve eğitimde kullanılır: personel, yangın tatbikatı ya da konuk karşılama gibi durumları sanal ortamda güvenle deneyebilir.","iliskili":["mg-7-056","mg-7-058","mg-7-055"],"kontrol":null,"gorsel":"t14e-vr-gozluk"},{"id":"mg-7-058","konu":"7.1","terim":"Sanal tur","ingilizce":"Virtual tour","tanim":"Bir otelin, müzenin ya da ören yerinin internet üzerinden, çevreye her yöne bakılabilen görüntülerle uzaktan gezilmesidir.","ornek":"Rezervasyon yapmadan önce bir aile, otelin sitesindeki sanal turda odayı, havuzu ve restoranı ekrandan gezer.","sektor":"Konuk ne alacağını önceden görür; beklenti ile gerçek arasındaki fark azalır. Sanal tur yolculuğun yerini tutmaz, gitme isteği uyandırmak için kullanılır; görüntülerin güncel ve gerçeğe uygun olması dürüstlük gereğidir.","iliskili":["mg-7-056","mg-7-057","mg-7-013"],"kontrol":null,"kitapDisi":true,"gorsel":"f3f-sanal-tur-gozluk"},{"id":"mg-7-061","konu":"7.1","terim":"Toplumsal refah","ingilizce":"Social welfare","tanim":"Bir toplumdaki insanların gelir, sağlık, eğitim ve güvenlik bakımından iyi ve huzurlu yaşama düzeyidir.","ornek":"Bir kasabaya turizmle gelen gelir yeni iş alanı açar; gençler çalışmak için büyük şehre göç etmek zorunda kalmaz.","sektor":"Programda yeni bir teknoloji değerlendirilirken sorulan sorulardan biridir: “Bundan yalnız işletme mi kazanıyor, toplum da mı?” Otomasyon bazı işleri azaltacaksa çalışanların yeni işlere hazırlanması da düşünülmelidir.","iliskili":["mg-7-059","mg-7-009","mg-7-035"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-070","konu":"7.1","terim":"İş birlikçi robot","ingilizce":"Collaborative robot (cobot)","tanim":"İnsanın yanında, aynı ortamda güvenle çalışacak biçimde tasarlanmış, tehlikeli ya da yorucu işleri üstlenen robottur.","ornek":"Bir atölyede ağır parçayı iş birlikçi robot kaldırır, parçanın ince ayarını ve son kontrolünü usta yapar.","sektor":"Toplum 5.0 anlayışında robot insanın yerini almak için değil, çalışanı daha güvenli koşullarda çalıştırmak için kullanılır.","iliskili":["mg-7-009","mg-7-052","mg-7-050"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-7-071","konu":"7.1","terim":"Veri okuryazarlığı","ingilizce":"Data literacy","tanim":"Verilerin ne anlama geldiğini okuyabilme, yorumlayabilme ve karar verirken doğru kullanabilme becerisidir.","ornek":"Otel yöneticisi doluluk grafiğine bakıp haziran ayında hangi hafta boş oda kaldığını görür ve o haftaya özel kampanya önerir.","sektor":"Yeni iş rollerinde mesleki bilgi ile veri okuryazarlığı birlikte aranır; veriyi okuyamayan çalışan dijital sistemin sunduğu fırsatı göremez.","iliskili":["mg-7-021","mg-7-046","mg-7-044"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-072","konu":"7.1","terim":"Önleyici bakım","ingilizce":"Predictive maintenance","tanim":"Makinelerden gelen verilerle arızanın olmadan önce fark edilip sorun büyümeden müdahale edilmesidir.","ornek":"Otel çamaşırhanesindeki kurutma makinesinin sıcaklık sensörü olağan dışı yükselince sistem bakım ekibini uyarır; makine bozulmadan ayarlanır.","sektor":"Geleneksel anlayışta arıza çıkınca müdahale edilir; veriye dayalı bakımda ise veriler izlenir, sorun önceden fark edilir. Kitap bu anlayışa “önleyici bakım” der; uluslararası literatürde veriyle arızayı önceden kestiren bakıma predictive maintenance (kestirimci bakım), takvime göre yapılan düzenli bakıma ise preventive maintenance denir.","iliskili":["mg-7-073","mg-7-051","mg-7-019"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-073","konu":"7.1","terim":"Algılayıcı (sensör)","ingilizce":"Sensor","tanim":"Sıcaklık, titreşim, hareket ya da ışık gibi çevredeki değişimi ölçüp bilgiyi bir sisteme ileten cihazdır.","ornek":"Soğuk hava deposundaki algılayıcı sıcaklık belirlenen aralığın dışına çıktığında mutfak görevlisinin telefonuna uyarı gönderir.","sektor":"Nesnelerin interneti ve akıllı üretimin temel parçalarından biridir; soğuk hava deposunda ve üretim hattında sıcaklık, titreşim gibi değerleri izlemek için kullanılır.","iliskili":["mg-7-019","mg-7-072","mg-7-020"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-023","konu":"7.2","terim":"Bulut bilişim","ingilizce":"Cloud computing","tanim":"Verilerin ve programların iş yerindeki bilgisayarda değil, internet üzerinden erişilen uzak sunucularda saklanması ve çalıştırılmasıdır.","ornek":"Satış müdürü, şehir dışındaki bir fuarda dizüstü bilgisayarından otelin rezervasyon sistemine girip doluluk durumuna bakar.","sektor":"Bilgiye her yerden erişilir; tek bir cihaz bozulsa da kayıt kaybolmaz. Her yerden erişim parolanın önemini artırır: parolayı ele geçiren de her yerden girebilir.","iliskili":["mg-7-021","mg-7-024","mg-7-040"],"kontrol":null,"gorsel":"mg-veri-merkezi"},{"id":"mg-7-024","konu":"7.2","terim":"Uzaktan çalışma","ingilizce":"Remote working","tanim":"Çalışanın işini iş yerine gitmeden, evinden ya da başka bir yerden bilgisayar ve internet aracılığıyla yapmasıdır.","ornek":"Bir seyahat acentesinin çağrı merkezi çalışanı evindeki bilgisayarından müşterilerin tur sorularını cevaplar.","sektor":"Turizmde her iş uzaktan yapılamaz: oda temizliği, servis ve karşılama konuğun yanında olmayı gerektirir. Rezervasyon, satış, sosyal medya ve muhasebe gibi işler ise kısmen uzaktan yürütülebilir.","iliskili":["mg-7-025","mg-7-026","mg-7-029"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-025","konu":"7.2","terim":"Esnek çalışma","ingilizce":"Flexible working","tanim":"Çalışma saatlerinin ya da çalışılan yerin, işin gereğine göre işveren ile çalışanın anlaşmasıyla ayarlanabildiği çalışma düzenidir.","ornek":"Bir satış temsilcisinin, toplam çalışma süresini doldurmak koşuluyla işe başlama saatini amiriyle birlikte belirlemesi.","sektor":"Esneklik başıboşluk değil, güvene dayalı bir düzendir: saat değişir, işin zamanında ve eksiksiz teslim edilmesi değişmez. Otelin vardiyalı bölümlerinde saatleri konuğun ihtiyacı belirler.","iliskili":["mg-7-024","mg-7-026","mg-7-031"],"kontrol":null,"gorsel":"m6-ortak-calisma"},{"id":"mg-7-026","konu":"7.2","terim":"Hibrit çalışma","ingilizce":"Hybrid working","tanim":"Çalışanın haftanın bir bölümünde iş yerinde, bir bölümünde uzaktan çalıştığı karma düzendir.","ornek":"Bir otel zincirinin pazarlama ekibi haftanın belirli günlerinde genel merkezde toplanır, kalan günlerde evden çalışır.","sektor":"Programın anahtar kavramlarındandır. Yüz yüze günler ekip bağını, uzaktan günler sessiz ve odaklı çalışmayı destekler. Kimin hangi gün nerede olacağının önceden bilinmesi gerekir.","iliskili":["mg-7-024","mg-7-025","mg-7-027"],"kontrol":null},{"id":"mg-7-027","konu":"7.2","terim":"Video konferans","ingilizce":"Video conferencing","tanim":"Farklı yerlerdeki kişilerin internet üzerinden birbirini görerek ve duyarak yaptığı toplantıdır.","ornek":"Saat 10.00, otelin toplantı odası: satış müdürü, yurt dışındaki bir tur operatörüyle sezon anlaşmasını ekran üzerinden görüşür.","sektor":"Yüz yüze toplantının kuralları burada da geçerlidir: zamanında bağlan, sessiz bir yer seç, konuşmadığında mikrofonunu kapat, kıyafetine ve arkanda görünenlere dikkat et.","iliskili":["mg-7-026","mg-7-028","mg-7-032"],"kontrol":null,"cizim":"toplanti-sunum"},{"id":"mg-7-028","konu":"7.2","terim":"İş e-postası","ingilizce":"Business email","tanim":"İş yerinde resmî yazışma, bilgi verme ve kayıt bırakma amacıyla gönderilen elektronik iletidir.","ornek":"Rezervasyon görevlisi konuğa onay e-postası yazar: konu satırı açık, hitap “Sayın” ile, tarihler ve oda tipi eksiksiz, sonda ad ve unvan.","sektor":"E-posta yazılı kayıttır; sen silsen de karşı tarafta kalır. Göndermeden önce alıcıyı, eki ve yazımı kontrol et: yanlış kişiye giden bir konuk listesi veri ihlalidir.","iliskili":["mg-7-027","mg-7-032","mg-7-037"],"kontrol":null,"cizim":"sosyal-medya"},{"id":"mg-7-029","konu":"7.2","terim":"Dijital öz yönetim","ingilizce":"Digital self-management","tanim":"Kişinin dijital ortamda zamanını, dikkatini, işlerini ve davranışlarını başında biri olmadan kendisinin planlayıp denetlemesidir.","ornek":"Evden çalışan rezervasyon görevlisi sabah yapılacaklar listesini çıkarır, gereksiz bildirimleri kapatır, mesajlara belirlediği saatlerde bakar.","sektor":"Programın anahtar kavramlarındandır. Uzaktan çalışmada şef omzunun üzerinden bakmaz; işin bitip bitmediğini sonuç gösterir. Ödevini telefona bakmadan bitirebilmek bu becerinin ilk alıştırmasıdır.","iliskili":["mg-7-030","mg-7-031","mg-7-024"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-030","konu":"7.2","terim":"Öz disiplin","ingilizce":"Self-discipline","tanim":"Evden ya da iş yeri dışından çalışan kişinin, başında denetleyen biri olmasa da işine zamanında başlaması ve yapması gerekeni ertelemeden bitirmesidir.","ornek":"Evden çalıştığı gün rezervasyon görevlisi saat 09.00’da masasına oturur; televizyonu açmaz, işini bitirmeden sosyal medyaya girmez.","sektor":"Dijital öz yönetimin temelidir: plan yapmak kolaydır, plana uymak öz disiplin ister. Zamanını iyi kullanan çalışana daha büyük sorumluluk verilir.","iliskili":["mg-7-029","mg-7-031","mg-7-047"],"kontrol":null,"cizim":"deniz-kumsal"},{"id":"mg-7-031","konu":"7.2","terim":"İş-yaşam dengesi","ingilizce":"Work–life balance","tanim":"Kişinin işine ayırdığı zaman ve enerji ile ailesine, dinlenmeye ve kendine ayırdığı zaman arasında sağlıklı bir denge kurmasıdır.","ornek":"Evden çalışan bir satış temsilcisi mesaisi bitince bilgisayarını kapatır; akşam yemeğinde iş mesajlarına bakmaz.","sektor":"Anlık iletişim işi cebe taşır: mesai bitse de mesaj gelir. Sınır konmazsa yorgunluk birikir; yorgun çalışan da konuğa güler yüz gösteremez.","iliskili":["mg-7-029","mg-7-030","mg-7-025"],"kontrol":null,"cizim":"saglik-kalp"},{"id":"mg-7-032","konu":"7.2","terim":"Dijital iletişim etiği","ingilizce":"Digital communication ethics","tanim":"E-posta, mesaj, video görüşmesi ve sosyal medya gibi dijital ortamlarda iletişim kurarken saygılı, dürüst ve özenli davranma ilkeleridir.","ornek":"Ekibin mesaj grubunda bir arkadaşının hatasını herkesin önünde yazmak yerine konuyu şefle ayrıca konuşmak.","sektor":"Yüz yüze söylemeyeceğin sözü ekrana da yazma. Başkasının mesajını ya da ekran görüntüsünü izinsiz paylaşmamak, iş grubuna gece yarısı gereksiz mesaj atmamak bu etiğin parçasıdır.","iliskili":["mg-7-028","mg-7-033","mg-7-035"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-033","konu":"7.2","terim":"Dijital vatandaşlık","ingilizce":"Digital citizenship","tanim":"İnterneti ve dijital araçları hak ve sorumluluklarını bilerek, güvenli, saygılı ve yasalara uygun biçimde kullanmaktır.","ornek":"Bir öğrenci, gördüğü haberi paylaşmadan önce kaynağına bakar; başkasının fotoğrafını izin almadan yayımlamaz.","sektor":"Programın anahtar kavramlarındandır. İnternetteki davranışının sorumluluğu da gerçek hayattaki kadar sana aittir. Bir otel hakkında doğrulanmamış bir söylentiyi paylaşmak, orada çalışan insanların emeğine zarar verebilir.","iliskili":["mg-7-032","mg-7-034","mg-7-046"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-034","konu":"7.2","terim":"Dijital ayak izi","ingilizce":"Digital footprint","tanim":"Kişinin internette yaptığı paylaşım, yorum, beğeni ve aramaların geride bıraktığı, kolay kolay silinmeyen izlerin bütünüdür.","ornek":"Staj başvurusu yapan bir öğrencinin adı internette aratıldığında karşıya çıkan eski paylaşımlar ve yorumlar.","sektor":"İşverenler adayın herkese açık paylaşımlarına bakabilir. Üniformayla, iş yerinde ya da konukların göründüğü bir fotoğrafı izinsiz paylaşmak hem senin hem otelin adına iz bırakır.","iliskili":["mg-7-033","mg-7-032","mg-7-036"],"kontrol":null,"cizim":"el-yikama"},{"id":"mg-7-035","konu":"7.2","terim":"Teknoloji etiği","ingilizce":"Technology ethics","tanim":"Bir teknolojiyi geliştirirken ve kullanırken insanlara, topluma ve çevreye zarar vermemeyi, dürüst ve adil davranmayı gözeten ilkelerdir.","ornek":"Otel, güvenlik kameralarını yalnız ortak alanlara yerleştirir ve kayıt yapıldığını levhayla bildirir; odalarda kamera bulunmaz.","sektor":"Programın anahtar kavramlarındandır. “Yapabilir miyiz?” sorusundan sonra “Yapmalı mıyız?” sorusu gelir. Konuğun güvenini zedeleyen bir teknoloji otele kazandırmaz, kaybettirir.","iliskili":["mg-7-032","mg-7-017","mg-7-037"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-036","konu":"7.2","terim":"Kişisel veri","ingilizce":"Personal data","tanim":"Kimliği belli olan ya da belirlenebilen bir kişiyle ilgili her türlü bilgidir.","ornek":"Resepsiyondaki kayıt ekranında görünenler: konuğun kimlik numarası, adı ve soyadı, telefonu, e-posta adresi ve kredi kartı bilgisi.","sektor":"Otel, işi gereği çok sayıda kişisel veri toplar. Bu bilgiler konuğa aittir; otel yalnız emanetçidir.","iliskili":["mg-7-037","mg-7-038","mg-7-034"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-037","konu":"7.2","terim":"Veri gizliliği","ingilizce":"Data privacy","tanim":"Kişilere ve işletmeye ait bilgilerin yalnız yetkili kişilerce, yalnız gerekli amaçla görülmesi ve yetkisiz kimseyle paylaşılmamasıdır.","ornek":"Resepsiyon ekranı konukların göremeyeceği açıda durur; görevli bankodan ayrılırken ekranı kilitler.","sektor":"Programın anahtar kavramlarındandır. Konuk listesini fotoğraflayıp bir mesaj grubuna atmak, kâğıt listeyi lobide unutmaktan daha hızlı yayılan bir ihlaldir. Bir verinin sızdığından şüphelenirsen hemen amirine bildir.","iliskili":["mg-7-036","mg-7-038","mg-7-039"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-038","konu":"7.2","terim":"KVKK (Kişisel Verilerin Korunması Kanunu)","ingilizce":"Personal Data Protection Law (KVKK)","tanim":"Türkiye’de kişisel verilerin hangi koşullarda toplanıp kullanılabileceğini belirleyen ve kişilerin kendi verileri üzerindeki haklarını koruyan 6698 sayılı kanundur.","ornek":"Otelin kayıt formunda ve internet sitesinde, konuğun hangi bilgisinin hangi amaçla alındığını açıklayan bir aydınlatma metni yer alır.","sektor":"Genel ilke şudur: veri hukuka uygun biçimde, belirli bir amaç için ve gerektiği kadar alınır; amaç dışında kullanılmaz, yetkisiz kişiye verilmez. Ayrıntıyı işletmenin yetkilisi bilir; emin olmadığın bir veri isteğinde amirine sor.","iliskili":["mg-7-036","mg-7-037","mg-7-035"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-039","konu":"7.2","terim":"Siber güvenlik","ingilizce":"Cyber security","tanim":"Bilgisayarların, ağların ve içlerindeki verilerin izinsiz erişime, hırsızlığa ve zarar verilmesine karşı korunmasıdır.","ornek":"Otelin bilgi işlem sorumlusu programları günceller ve yedek alır; personel sisteme yalnız kendi kullanıcı adı ve parolasıyla girer.","sektor":"Programın anahtar kavramlarındandır. Rezervasyon ve ödeme sistemleri durursa otel çalışamaz; konuk verisi çalınırsa güven sarsılır. En zayıf halka çoğu zaman dikkatsiz bir tıklamadır; bu yüzden güvenlik herkesin işidir.","iliskili":["mg-7-040","mg-7-041","mg-7-037"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-040","konu":"7.2","terim":"Güçlü parola","ingilizce":"Strong password","tanim":"Yeterince uzun olan ve harf, rakam ile işaretlerden oluşan, tahmin edilmesi zor, başka hesaplarda kullanılmayan paroladır.","ornek":"Stajyere otel sisteminde kendi kullanıcısı açılır; parolasını kimseye söylemez, kâğıda yazıp ekranın kenarına yapıştırmaz.","sektor":"Sistemde senin kullanıcınla yapılan her işlem senin adına kaydedilir. Parolanı arkadaşına vermek, anahtarını ve imzanı vermek gibidir.","iliskili":["mg-7-039","mg-7-041","mg-7-023"],"kontrol":null},{"id":"mg-7-041","konu":"7.2","terim":"Oltalama e-postası","ingilizce":"Phishing email","tanim":"Güvenilir bir kurumdan gelmiş gibi görünen ve kişinin parolasını ya da kart bilgisini ele geçirmek amacıyla gönderilen sahte e-postadır.","ornek":"Resepsiyonun e-posta kutusuna, bilinen bir firmanın adını taşıyan şu ileti düşer: “Rezervasyon sisteminiz kapatılacak, parolanızı doğrulamak için tıklayın.”","sektor":"Bu dolandırıcılık yöntemine oltalama, sektörde “phishing” denir; aynı tuzak mesajla ya da sahte siteyle de kurulur. İşaretleri: acele ettirme, tanımadığın bir bağlantı, parola ya da kart bilgisi isteği. Bağlantıya tıklanmaz, cevap yazılmaz; ileti amire ya da bilgi işlem sorumlusuna bildirilir.","iliskili":["mg-7-039","mg-7-040","mg-7-028"],"kontrol":null,"kitapDisi":true,"cizim":"sosyal-medya"},{"id":"mg-7-074","konu":"7.2","terim":"Dijital görev takip sistemi","ingilizce":"Digital task management system","tanim":"Ekip üyelerinin görevlerinin kimde olduğunu, ne zaman teslim edileceğini ve ne durumda olduğunu ortak ekrandan izlemesini sağlayan yazılımdır.","ornek":"Pazarlama ekibi, otelin yaz kampanyası görevlerini ortak panoya yazar; kimin hangi işi ne zaman bitireceği herkesçe görülür.","sektor":"Uzaktan ve hibrit çalışmada ekip aynı yerde olmadığı için görev takibinde kullanılır.","iliskili":["mg-7-024","mg-7-026"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-075","konu":"7.2","terim":"Veri ihlali","ingilizce":"Data breach","tanim":"Kişisel ya da kurumsal bilgilerin yetkisiz kişilerin eline geçmesi veya yetkisiz biçimde paylaşılmasıdır.","ornek":"Bir görevli, konuk listesini yanlışlıkla yanlış e-posta adresine gönderir; konukların adları ve telefonları yetkisiz kişide kalır.","sektor":"Gizli bir dosyanın kişisel e-postaya gönderilmesi ya da güvenli olmayan bir ağdan paylaşılması veri ihlaline yol açabilir.","iliskili":["mg-7-036","mg-7-038","mg-7-039"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-059","konu":"7.3","terim":"Millî Teknoloji Hamlesi","ingilizce":"National Technology Initiative","tanim":"Türkiye’nin, ihtiyaç duyduğu teknolojileri kendi insan gücü ve imkânlarıyla geliştirip üretmesini, teknolojiyi yalnız kullanan değil üreten bir ülke olmasını amaçlayan anlayıştır.","ornek":"Bir meslek lisesinde öğrenciler, okul atölyesindeki bir sorunu çözen cihazı kendileri tasarlayıp bir teknoloji yarışmasına hazırlar.","sektor":"Programın anahtar kavramlarındandır. Program senden teknolojiyi yalnız tüketen değil, ona yön veren, yetkin ve erdemli bir birey olmanı bekler. Turizm öğrencisi için karşılığı: mesleğindeki bir soruna teknolojiyle çözüm düşünebilmek.","iliskili":["mg-7-060","mg-7-061","mg-7-062"],"kontrol":null,"cizim":"dijital"},{"id":"mg-7-060","konu":"7.3","terim":"Yerli teknoloji","ingilizce":"Home-grown technology","tanim":"Tasarımı, geliştirilmesi ve üretimi ülkenin kendi mühendisleri, teknisyenleri ve kuruluşları tarafından yapılan teknolojidir.","ornek":"Bir işletme, Türkiye’de geliştirilmiş bir rezervasyon yazılımı kullanır; ihtiyaç duyduğu yeni bir özelliği doğrudan yazılımı geliştiren ekibe iletebilir.","sektor":"Teknolojiyi üreten ülke dışarıya daha az bağımlı olur, nitelikli iş alanı açar ve ürettiğini satarak kazanır. Bu yalnız mühendislerin işi değildir: iyi yetişmiş her meslek sahibi katkı verir.","iliskili":["mg-7-059","mg-7-061","mg-7-062"],"kontrol":null},{"id":"mg-7-062","konu":"7.3","terim":"Yenilikçi ürün veya hizmet modeli","ingilizce":"Innovative product or service model","tanim":"Bir sorunu ya da ihtiyacı, daha önce denenmemiş ya da var olandan daha iyi bir yolla çözmek için tasarlanan ürün veya hizmet taslağıdır.","ornek":"Bir grup turizm öğrencisi, yabancı konukların otelde yön bulmakta zorlandığını fark eder ve tabelalara çok dilli sesli anlatım açan karekodlar eklemeyi önerir.","sektor":"İyi model gösterişli teknolojiden değil, gerçek bir sorundan yola çıkar. Değerlendirirken üç şeye bakılır: işe yarıyor mu, uygulanabilir mi, kimseye zarar veriyor mu?","iliskili":["mg-7-063","mg-7-064","mg-7-065"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-7-063","konu":"7.3","terim":"Kök neden analizi","ingilizce":"Root cause analysis","tanim":"Bir sorunun görünen belirtisiyle yetinmeyip onu asıl doğuran nedeni adım adım arayıp bulma çalışmasıdır.","ornek":"Grup bir balık kılçığı diyagramı çizer: balığın başına “Sabah check-out kuyruğu” yazılır; kılçıklara “personel”, “sistem”, “yöntem” gibi başlıklar, altlarına da olası nedenler eklenir.","sektor":"Programda bu iş için balık kılçığı diyagramı kullanılır. Çözüm aramadan önce sorunu anlamayı öğretir: kuyruğun nedeni personel azlığı değil de yavaş çalışan bir yazıcıysa alınacak önlem de değişir.","iliskili":["mg-7-062","mg-7-064","mg-7-065"],"kontrol":null,"cizim":"grafik"},{"id":"mg-7-064","konu":"7.3","terim":"Proje fikri kanvası","ingilizce":"Project idea canvas","tanim":"Bir proje fikrini tek sayfada, belirli başlıklar altında özetleyen planlama şablonudur.","ornek":"Grup, büyük bir kâğıdı sekiz kutuya böler: problem, hedef kitle, çözüm fikri, kullanılacak teknoloji, etik ilkeler, siber güvenlik önlemleri, iş gücüne etkisi ve toplumsal refaha katkı.","sektor":"Kitaptaki sekiz başlık fikrin eksiğini hemen gösterir: hedef kitlesi belli olmayan, siber güvenliği ya da etik yönü düşünülmemiş fikir henüz hazır değildir. Otelde bir öneriyi müdüre sunarken de aynı sorular sorulur.","iliskili":["mg-7-062","mg-7-063","mg-7-065"],"kontrol":null,"gorsel":"m6-yapiskan-notlar"},{"id":"mg-7-065","konu":"7.3","terim":"Proje pazarı","ingilizce":"Project fair","tanim":"Grupların hazırladıkları proje fikirlerini sergileyip kısaca sunduğu, diğerlerinin de yatırımcı ya da kullanıcı gözüyle inceleyip geri bildirim verdiği etkinliktir.","ornek":"Sınıfın duvarlarına proje kanvasları asılır; her grup fikrini birkaç dakikada anlatır, arkadaşları “Yenilikçi mi, uygulanabilir mi?” diye değerlendirir.","sektor":"Fikrini kısa ve açık anlatmak, eleştiriyi dinleyip fikri geliştirmek iş hayatının temel becerilerindendir. Arkadaşının projesine saygılı ve yapıcı geri bildirim vermek de değerlendirmenin parçasıdır.","iliskili":["mg-7-062","mg-7-064","mg-7-063"],"kontrol":null},{"id":"mg-7-077","konu":"7.3","terim":"Beyin fırtınası","ingilizce":"Brainstorming","tanim":"Bir sorunun çözümü için gruptaki herkesin fikirlerini eleştirmeden hızlıca ortaya koyduğu yaratıcı düşünme çalışmasıdır.","ornek":"Resepsiyon ekibi check-out kuyruğunu kısaltmak için kısa sürede çok fikir yazar; sonra maliyet ve uygulanabilirliğe göre en iyisini seçer.","sektor":"Toplanan fikirler sonradan maliyet, kullanıcı yararı, güvenlik, uygulanabilirlik ve yenilikçilik ölçütleriyle elenir.","iliskili":["mg-7-062","mg-7-064"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-7-079","konu":"7.3","terim":"Ürün modeli","ingilizce":"Product model","tanim":"Somut ya da dijital bir çözümün hedef kitlesini, çalışma biçimini, teknolojisini ve yararını gösteren tasarımdır.","ornek":"Öğrenciler kaybolan el aletlerini izleyen küçük bir etiketli takip cihazı tasarlar.","sektor":"Unutulan eşyayı konuğa ulaştıran bir otel uygulaması düşünen öğrenci modeli dört soruyla yazabilir: kimin için (konuk ve resepsiyon), nasıl çalışır (eşyanın fotoğrafı ve kaydı), hangi teknolojiyle (mobil uygulama), ne yarar sağlar (hızlı ve kayıtlı teslim). Fikrin başkasına anlatılabilir bir ürün hâline gelmesi için model yazıya dökülmelidir.","iliskili":["mg-7-080","mg-7-062"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-7-080","konu":"7.3","terim":"Hizmet modeli","ingilizce":"Service model","tanim":"Bir ihtiyacın belirli bir süreç izlenerek karşılanmasını gösteren tasarımdır.","ornek":"Otel, yaşlı konuklar için kioskun yanında yardım eden bir karşılama görevlisi hizmeti tasarlar.","sektor":"Geç saatte gelen konuk için hazırlanan karşılama süreci bir hizmet modelidir: kapıda karşılama, kimlik kaydı, anahtar teslimi ve odaya kadar eşlik sırayla ve kimin yapacağı belli olarak tasarlanır. Ürün modelinde tasarımın ağırlığı bir araçtadır; hizmet modelinde ise doğru sırayla işleyen adımlardadır.","iliskili":["mg-7-079","mg-7-062"],"kontrol":null,"cizim":"zil-hizmet"},{"id":"mg-7-081","konu":"7.3","terim":"Siber-fiziksel sistem","ingilizce":"Cyber-physical system","tanim":"Fiziksel makinelerin yazılımla ve ağla birbirine bağlanarak birlikte çalıştığı sistemdir.","ornek":"Üretim hattındaki robot kollar, algılayıcılardan gelen veriye göre yazılımla hızını kendiliğinden ayarlar.","sektor":"Otel odasında hareket sensörü odanın boş olduğunu algılar, yazılım bunu değerlendirir ve klimayı kısar: fiziksel cihaz ile yazılım birlikte karar verip iş yapar. Bu cihazlar ağa bağlı olduğu için siber saldırıya da açıktır; bu yüzden parola ve yazılım güncellemesi teknik servisin bakım işinin parçasıdır.","iliskili":["mg-7-051","mg-7-019","mg-7-082"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-7-082","konu":"7.3","terim":"Görüntü işleme","ingilizce":"Image processing","tanim":"Kamera görüntülerinin yazılımla çözümlenip içindeki nesnenin ya da hatanın fark edilmesidir.","ornek":"Üretim hattındaki kamera, yapay zekâ destekli görüntü işleme ile kusurlu ürünü ayırır.","sektor":"Kalite hatalarında yapay zekâ destekli görüntü işleme sistemlerinden yararlanılabilir.","iliskili":["mg-7-017","mg-7-051","mg-7-081"],"kontrol":null,"cizim":"egitim-kariyer"}],"sorular":[{"id":"mg-7-s01","tur":"coktan-secmeli","soru":"Bir dokuma fabrikasında kumaşı artık tezgâhta usta değil, buhar gücüyle çalışan makineler dokuyor. Fabrika hangi dönemdedir?","secenekler":["Endüstri 2.0","Endüstri 1.0","Endüstri 3.0","Endüstri 4.0"],"dogru":1,"aciklama":"Su ve buhar gücüyle çalışan makineler Endüstri 1.0’ın simgesidir. En yakın çeldirici Endüstri 2.0’dır; o dönemde ise elektrik ve üretim bandı öne çıkar."},{"id":"mg-7-s02","tur":"coktan-secmeli","soru":"Bir fabrikada elektrikle çalışan makineler var; ürün bant üzerinde ilerliyor ve her işçi yalnız kendi parçasını takıyor. Bu üretim hangi döneme aittir?","secenekler":["Endüstri 1.0","Endüstri 3.0","Endüstri 2.0","Endüstri 4.0"],"dogru":2,"aciklama":"Elektrik ve üretim bandıyla aynı ürünün çok sayıda ve hızlı üretilmesi seri üretimdir, yani Endüstri 2.0. Endüstri 3.0’da ise bilgisayarla programlanan makineler vardır."},{"id":"mg-7-s03","tur":"coktan-secmeli","soru":"Endüstri 3.0 ile Endüstri 4.0 arasındaki temel fark hangisidir?","secenekler":["Endüstri 4.0’da makineler internetle birbirine bağlanıp veri paylaşır.","Endüstri 4.0’da üretimde elektrik ilk kez kullanılır ve seri üretim başlar.","Endüstri 3.0’da makineler internetle birbirine bağlanıp veri paylaşarak üretimi yönetir.","Endüstri 3.0’da üretim bandı ve elektrik sayesinde seri üretim başlar."],"dogru":0,"aciklama":"Endüstri 3.0’da makineler programlanır ve kendi başına çalışır; Endüstri 4.0’da bunlar internetle birbirine bağlanıp veri paylaşır. Elektrik ve üretim bandı ise Endüstri 2.0’a aittir."},{"id":"mg-7-s04","tur":"coktan-secmeli","soru":"Bir otel, görme engelli konuklar için telefonda otelin içinde sesli yön tarifi veren bir uygulama hazırlıyor. Bu çalışma hangi anlayışa en yakındır?","secenekler":["Endüstri 4.0","Akıllı üretim","Otomasyon","Toplum 5.0"],"dogru":3,"aciklama":"Toplum 5.0, teknolojiyi insanın yaşamını kolaylaştırmak ve toplumun sorunlarını çözmek için kullanmayı savunur. Endüstri 4.0 ise makinelerin bağlanıp üretimi yönetmesine odaklanır."},{"id":"mg-7-s05","tur":"coktan-secmeli","soru":"Bir otel, kâğıt konuk kayıt formunu kaldırıp aynı formu tablette doldurtmaya başlıyor. Bu uygulama hangi kavramla en iyi açıklanır?","secenekler":["Dijitalleşme","Otomasyon","Büyük veri","Dinamik fiyatlama"],"dogru":0,"aciklama":"Kâğıtla yürüyen işin dijital araçla yürütülmesi dijitalleşmedir. Otomasyonda ise işi insan müdahalesi olmadan makine ve yazılım yapar; burada form hâlâ konuk tarafından dolduruluyor."},{"id":"mg-7-s06","tur":"coktan-secmeli","soru":"Otel odasında pencere açılınca klima kendiliğinden kapanıyor; pencere ve klima birbirine bağlı çalışıyor. Bu durum hangi teknolojiyle açıklanır?","secenekler":["Dijital ikiz","Nesnelerin interneti","Sanal tur","Bulut bilişim"],"dogru":1,"aciklama":"Cihazların internete bağlanıp birbirleriyle ve bir merkezle veri alışverişi yapması nesnelerin internetidir. Bulut bilişim verinin uzak sunucularda saklanmasıdır; burada asıl konu cihazların haberleşmesidir."},{"id":"mg-7-s07","tur":"coktan-secmeli","soru":"Aynı otel odası, şehirde büyük bir kongrenin yapıldığı hafta sakin bir kış haftasına göre çok daha pahalıya satılıyor. Bu fark hangi uygulamayla açıklanır?","secenekler":["Çevrim içi rezervasyon","Mobil check-in","Dinamik fiyatlama","Büyük veri"],"dogru":2,"aciklama":"Dinamik fiyatlamada oda fiyatı talebe, tarihe ve doluluğa göre yazılımla sürekli güncellenir. Büyük veri bu kararı besleyebilir ama fiyatın değişmesinin adı değildir."},{"id":"mg-7-s08","tur":"coktan-secmeli","soru":"Satış müdürü şehir dışındaki bir fuarda dizüstü bilgisayarından otelin rezervasyon sistemine girip doluluğa bakıyor. Bu erişimi hangi teknoloji sağlar?","secenekler":["Nesnelerin interneti","Dijital ayak izi","Önleyici bakım","Bulut bilişim"],"dogru":3,"aciklama":"Bulut bilişimde veri ve programlar internetle erişilen uzak sunucularda durur; bu yüzden müdür otelde olmasa da sisteme girebilir. Nesnelerin interneti ise cihazların birbirine bağlanmasıdır."},{"id":"mg-7-s09","tur":"coktan-secmeli","soru":"Yapay zekâ araçlarının iş yerinde kullanımıyla ilgili hangisi yanlıştır?","secenekler":["Çıktısı doğru olduğundan kontrolsüz kullanılabilir.","Hızlı çalışır ama yanılabilir, bu yüzden kontrol gerekir.","Son kararı ve sorumluluğu insan taşımaya devam eder.","Konuk adı ve telefonu gibi veriler araca yazılmaz."],"dogru":0,"aciklama":"Yapay zekâ hızlıdır ama yanılabilir ve sorumluluk almaz; bu yüzden çıktısı kontrol edilmeli, son kararı insan vermelidir. Konuk verisinin araca yazılmaması da veri gizliliğinin gereğidir."},{"id":"mg-7-s10","tur":"coktan-secmeli","soru":"Bir otel zincirinin pazarlama ekibi haftanın belirli günlerinde genel merkezde çalışıyor, kalan günlerde evden çalışıyor. Bu çalışma düzeni hangisidir?","secenekler":["Uzaktan çalışma","Hibrit çalışma","Vardiyalı çalışma","Video konferans"],"dogru":1,"aciklama":"İş yerinde ve uzaktan çalışmanın birlikte uygulandığı karma düzene hibrit çalışma denir. Uzaktan çalışmada çalışan işini tamamen iş yerine gitmeden yapar."},{"id":"mg-7-s11","tur":"coktan-secmeli","soru":"Evden çalışan bir görevli sabah yapılacaklar listesini çıkarıyor, gereksiz bildirimleri kapatıyor ve mesajlara belirlediği saatlerde bakıyor. Bu davranış neyi gösterir?","secenekler":["Dijital öz yönetim","Dijital ayak izi","Dijital vatandaşlık","Dijital iletişim etiği"],"dogru":0,"aciklama":"Zamanını, dikkatini ve işlerini dijital ortamda başında biri olmadan kendisi planlayıp denetlemek dijital öz yönetimdir. Dijital iletişim etiği ise başkalarıyla yazışırken saygılı ve dürüst olmakla ilgilidir."},{"id":"mg-7-s12","tur":"coktan-secmeli","soru":"Staj için başvuran bir öğrencinin adı internette aratıldığında yıllar önce yaptığı uygunsuz paylaşımlar karşıya çıkıyor. Bu durum hangi kavramla açıklanır?","secenekler":["Dijital vatandaşlık","Veri ihlali","Dijital ikiz","Dijital ayak izi"],"dogru":3,"aciklama":"İnternette yapılan paylaşım, yorum ve aramalar kolay silinmeyen izler bırakır; buna dijital ayak izi denir. Veri ihlali ise bilgilerin yetkisiz kişilere geçmesidir."},{"id":"mg-7-s13","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi kişisel veri sayılmaz?","secenekler":["Konuğun kayıtlı e-posta adresi","Otelin ortak alan temizlik saatleri","Konuğun kredi kartı bilgileri","Konuğun cep telefonu numarası"],"dogru":1,"aciklama":"Kişisel veri, kimliği belli olan ya da belirlenebilen bir kişiyle ilgili bilgidir. E-posta, kart ve telefon bilgisi konuğa aittir; temizlik saatleri ise otelin genel bilgisidir."},{"id":"mg-7-s14","tur":"coktan-secmeli","soru":"Resepsiyonun e-posta kutusuna “Hesabınız kapanacak, hemen tıklayıp parolanızı doğrulayın” yazan bir ileti düşüyor. Bu iletiyi şüpheli yapan özellik hangisidir?","secenekler":["Bir firmanın adını taşıması","Resepsiyon adresine gelmesi","Acele ettirip parola istemesi","Rezervasyon sisteminden söz etmesi"],"dogru":2,"aciklama":"Oltalama e-postaları acele ettirir ve tıklatarak parola ya da kart bilgisi almaya çalışır. Firma adı ya da sistemden söz etmek tek başına şüpheli değildir; sahte iletiler bunları taklit eder."},{"id":"mg-7-s15","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi kişisel verilerin korunması ilkesine aykırıdır?","secenekler":["Konaklama için yalnız gerekli bilgileri istemek","Bankodan ayrılırken bilgisayar ekranını kilitlemek","Konuğu hangi verisinin neden alındığı konusunda bilgilendirmek","Konuktan alınan bilgiyi toplanma amacı dışında bir kampanyada kullanmak"],"dogru":3,"aciklama":"Veri belirli bir amaç için ve gerektiği kadar alınır; amaç dışında kullanılmaz. Aydınlatma metniyle konuğu bilgilendirmek ise KVKK’nın gereğidir."},{"id":"mg-7-s16","tur":"coktan-secmeli","soru":"Bir resepsiyon görevlisi sistemi kullanmayı biliyor, konuğu hatasız kaydediyor ve sabırlı davranıyor. Bu bilgi, beceri ve tutumun bütününe ne denir?","secenekler":["Yetkinlik","Uyum yeteneği","Öz disiplin","İnsani dokunuş"],"dogru":0,"aciklama":"Yetkinlik bilgi, beceri ve tutumun bütünüdür. Uyum yeteneği yeni koşullara kısa sürede alışmaktır; burada ise işi iyi yapmanın üç boyutu anlatılıyor."},{"id":"mg-7-s17","tur":"coktan-secmeli","soru":"Müzede bir ziyaretçi telefonunu eski bir heykele tutuyor ve ekranda heykelin ilk hâlini gerçek görüntünün üzerinde görüyor. Aynı ziyaretçi fuarda gözlük takıp kendini bir balonda hissediyor. Bu iki teknoloji sırasıyla hangileridir?","secenekler":["Sanal gerçeklik – artırılmış gerçeklik","Dijital ikiz – sanal gerçeklik","Artırılmış gerçeklik – sanal gerçeklik","Artırılmış gerçeklik – dijital ikiz"],"dogru":2,"aciklama":"Gerçek görüntünün üzerine dijital bilgi eklemek artırılmış gerçekliktir; kişiyi gerçek ortamdan ayırıp tümüyle bilgisayar ortamına sokmak sanal gerçekliktir. Sıra ters yazılırsa tanımlar yer değiştirir."},{"id":"mg-7-s18","tur":"coktan-secmeli","soru":"Bir grup proje fikri kanvasını hazırlıyor. Aşağıdakilerden hangisi kanvasta ayrı bir başlık olarak yer almaz?","secenekler":["Etik ilkeler","Tahmini maliyet ve kâr","Siber güvenlik önlemleri","İş gücüne etkisi"],"dogru":1,"aciklama":"Kanvasın başlıkları şunlardır: problem, hedef kitle, çözüm fikri, kullanılacak teknoloji, etik ilkeler, siber güvenlik önlemleri, iş gücüne etkisi ve toplumsal refaha katkı. Maliyet bu listede yoktur."},{"id":"mg-7-s19","tur":"dogru-yanlis","soru":"Okul atölyesinde kırılan bir makine düğmesi bilgisayarda çizilip 3D yazıcıdan çıkarılıyor; yazıcı malzemeyi katman katman üst üste ekleyerek üretim yapıyor.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"3D yazıcı bilgisayarda tasarlanan nesneyi, malzemeyi katman katman ekleyerek üretir. Üretimin malzemeden parça kesip oyarak yapıldığını düşünmek yaygın bir yanılgıdır."},{"id":"mg-7-s20","tur":"dogru-yanlis","soru":"Artırılmış gerçeklikte kişi gerçek ortamdan ayrılır ve bütünüyle bilgisayarda oluşturulmuş bir ortamın içindeymiş gibi hisseder.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Bu tanım sanal gerçekliğe aittir. Artırılmış gerçeklikte kişi gerçek ortamı görmeye devam eder; yalnız görüntünün üzerine yazı, resim ya da model eklenir."},{"id":"mg-7-s21","tur":"dogru-yanlis","soru":"Millî Teknoloji Hamlesi, Türkiye’nin ihtiyaç duyduğu teknolojileri yurt dışından satın alarak kullanmasını hedefler.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Hamlenin amacı teknolojiyi yalnız kullanan değil üreten bir ülke olmaktır: ihtiyaç duyulan teknolojiler kendi insan gücü ve imkânlarıyla geliştirilir."},{"id":"mg-7-s22","tur":"dogru-yanlis","soru":"Otele self check-in kiosku konsa bile yardıma ihtiyaç duyan konuk için personelin güler yüzlü ilgisi önemini korur.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Kiosk işlemi hızlandırır ama her konuk ona alışık değildir; konuğu ağırlayan yine insandır. Teknolojinin insani dokunuşun yerini aldığını düşünmek yaygın bir yanılgıdır."},{"id":"mg-7-s23","tur":"senaryo","durum":"Ön büroda staj yapıyorsun. Saat 09.20, resepsiyonun e-posta kutusuna bilinen bir firmanın adını taşıyan bir ileti düşüyor: “Rezervasyon sisteminiz bugün kapatılacak, parolanızı doğrulamak için hemen tıklayın.” Resepsiyon görevlisi o sırada bir konukla ilgileniyor.","soru":"Ne yaparsın?","secenekler":["Sistem kapanmasın diye bağlantıya tıklar, istenen bilgileri girerim.","Bağlantıya tıklamam; iletiyi görevliye ve şefime bildiririm.","İletiye cevap yazıp gönderenin gerçekten o firma olup olmadığını sorarım.","Bağlantıyı kendi telefonumda açıp sitenin gerçek olup olmadığına bakarım."],"dogru":1,"aciklama":"Acele ettiren, bağlantıya tıklatıp parola isteyen ileti oltalamanın tipik işaretlerini taşır. Bağlantıya tıklanmaz, cevap yazılmaz; ileti amire ya da bilgi işlem sorumlusuna bildirilir. Bağlantıyı başka cihazda denemek de aynı riski taşır."},{"id":"mg-7-s24","tur":"senaryo","durum":"Rezervasyon bölümünde stajdasın ve otel sisteminde kendi kullanıcın var. Saat 14.10, öteki stajyer yanına geliyor: “Benim kullanıcım kilitlendi, şef toplantıda. Parolanı söyle, iki kayıt girip çıkacağım.”","soru":"Nasıl davranırsın?","secenekler":["Parolamı söylerim, işi bitince hemen değiştiririm.","Parolamı kâğıda yazıp veririm, kimseye göstermemesini isterim.","Kendi kullanıcımla girip bilgisayarı ona bırakır, molaya çıkarım.","Parolamı vermem; durumu birlikte şefe bildirmeyi öneririm."],"dogru":3,"aciklama":"Sistemde senin kullanıcınla yapılan her işlem senin adına kaydedilir; parolanı vermek imzanı vermek gibidir. Oturumu açıp bilgisayarı bırakmak da aynı sonucu doğurur. Kilitlenen kullanıcıyı yetkili kişi açar; durum şefe iletilir."},{"id":"mg-7-s25","tur":"senaryo","durum":"Lobide stajdasın. Saat 16.30, yaşlı bir konuk self check-in kioskunun önünde duruyor; ekrana birkaç kez dokunuyor, sonra çaresizce çevresine bakıyor. Resepsiyonda sıra var.","soru":"Ne yaparsın?","secenekler":["Yanına gider, güler yüzle yardım teklif ederim.","Kiosk konuğun kendi kullanması için olduğundan karışmam.","Uzaktan “Ekrandaki talimatları izleyin” diye seslenirim.","Kioskun zor olduğunu söyleyip konuğu sıranın sonuna gönderirim."],"dogru":0,"aciklama":"Teknoloji işlemi hızlandırır ama her konuk ona alışık değildir. Konuğu cihazla yalnız bırakmak ya da uzaktan seslenmek ağırlamak değildir; yanına gidip nazikçe yardım etmek insani dokunuştur."},{"id":"mg-7-s26","tur":"senaryo","durum":"Stajının ilk günü. Saat 11.00, üniformanla lobide çektiğin fotoğraf çok güzel çıkmış; ama arkada oturan iki konuğun yüzü ve resepsiyon ekranı da görünüyor. Arkadaşın “Hemen paylaş!” diye mesaj atıyor.","soru":"Ne yaparsın?","secenekler":["Konuklar herkese açık bir alanda oturduğu için fotoğrafı paylaşırım.","Fotoğrafı güvendiğim yakın arkadaş grubuma gönderirim.","Paylaşmam; otelin paylaşım kuralını şefime sorarım.","Fotoğrafı paylaşır, konuklar görürse sileceğimi düşünürüm."],"dogru":2,"aciklama":"Konukların yüzü ve ekrandaki bilgiler onlara aittir; izinsiz paylaşmak veri gizliliğini çiğner ve hem senin hem otelin dijital ayak izinde kalır. “Yalnız arkadaşlarıma” demek bunu değiştirmez: gönderilen görüntü kontrolünden çıkar. İş yerinde çekilen fotoğrafın paylaşımını işletmenin kuralı belirler."},{"id":"mg-7-s27","tur":"senaryo","durum":"Resepsiyonda staj yapıyorsun. Saat 13.00, giriş yapan bir konuk telefonunu gösteriyor: “Arkadaşım aynı odayı geçen hafta daha ucuza almış. Bu nasıl oluyor?” Sesi gergin, resepsiyon görevlisi yanında.","soru":"Hangisi doğru davranıştır?","secenekler":["Arkadaşının yanlış hatırladığını, fiyatların aynı olduğunu söylerim.","Fiyatın tarihe ve doluluğa göre değiştiğini sakince söyler, görevliye yönlendiririm.","Fiyatları ben belirlemediğim için bu konuda yapabileceğim hiçbir şey olmadığını söylerim.","Konuğun gönlü olsun diye aradaki farkın iade edileceğine dair söz veririm."],"dogru":1,"aciklama":"Dinamik fiyatlamada fiyat talebe, tarihe ve doluluğa göre değişir; bu dürüstçe ve sakin bir dille açıklanır. Konuğu yalanlamak ya da “Ben karışmam” demek güveni zedeler; iade sözü vermek stajyerin yetkisinde değildir. Talebi yetkili görevli değerlendirir."},{"id":"mg-7-s28","tur":"senaryo","durum":"Staj yaptığın otel zinciri yeni rezervasyon sistemi için sabah 09.00’da çevrim içi bir eğitim toplantısı düzenliyor. Toplantıya evden, video konferansla katılacaksın; genel merkezden eğitmen ve öteki otellerden stajyerler de olacak.","soru":"Nasıl hazırlanırsın?","secenekler":["Kameram kapalı olacağı için yataktan, telefonumdan bağlanırım.","Çevrim içi toplantı geç başlar diye birkaç dakika geç girerim.","Toplantı açıkken telefonda başka işlerle ilgilenir, kaydını sonra izlerim.","Sessiz bir yerden zamanında bağlanır, mikrofonumu kapalı tutarım."],"dogru":3,"aciklama":"Video konferansta yüz yüze toplantının kuralları geçerlidir: zamanında bağlanmak, sessiz bir yer seçmek, konuşmadığında mikrofonu kapatmak. Başında kimse yokken de dikkatini toplantıda tutmak dijital öz yönetimin gereğidir."},{"id":"mg-7-s29","tur":"senaryo","durum":"Konuk ilişkilerinde stajdasın. Saat 15.00, şefin yarın gelecek grup için kısa bir karşılama mesajı taslağı hazırlamanı istiyor. Yanındaki stajyer “Uğraşma, konuk listesini adları ve telefonlarıyla bir yapay zekâ sohbet aracına yapıştır, mesajı o yazsın” diyor.","soru":"Ne yaparsın?","secenekler":["Konuk bilgisi girmeden taslağı hazırlar, şefime gösteririm.","Listeyi araca yapıştırır, çıkan mesajı hiç okumadan doğrudan şefime iletirim.","Listeyi araca yapıştırırım ama yalnız konukların telefon numaralarını silerim.","Listeyi kendi telefonuma gönderir, mesajı akşam evde hazırlayıp getiririm."],"dogru":0,"aciklama":"Konuğun adı ve telefonu kişisel veridir; işletme dışındaki bir araca yapıştırmak ya da kendi telefonuna göndermek veri gizliliğini çiğner. Bir araç kullanılsa bile konuk verisi girilmez, çıkan metin kontrol edilir ve son kararı insan verir."},{"id":"mg-7-s30","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi teknolojinin ortaya çıkardığı yeni bir iş rolüne örnektir?","secenekler":["Konuk yorumlarını internette yanıtlayan çalışan","Rezervasyonları telefonla alıp deftere yazan memur","Konuk kayıtlarını kâğıt kartlara yazan görevli","Gün sonu hesabını elle toplayıp makbuz yazan kasiyer"],"dogru":0,"aciklama":"Yeni iş rolü, teknolojinin ortaya çıkardığı ya da içeriğini büyük ölçüde değiştirdiği görevdir; internetteki konuk yorumlarını yanıtlamak bunun örneğidir. Diğer şıklar elle ve yüz yüze yürütülen geleneksel rollerdir."},{"id":"mg-7-s31","tur":"coktan-secmeli","soru":"Otel çamaşırhanesindeki kurutma makinesinin sıcaklığı olağan dışı yükselince sistem bakım ekibini uyarıyor; makine bozulmadan ayarlanıyor. Bu uygulama hangisidir?","secenekler":["Dijital ikiz","Önleyici bakım","Görüntü işleme","Akıllı oda"],"dogru":1,"aciklama":"Makineden gelen veriyle arızanın olmadan önce fark edilip sorun büyümeden müdahale edilmesi önleyici bakımdır."},{"id":"mg-7-s32","tur":"coktan-secmeli","soru":"Gece 03.00’te bir konuk otelin sitesindeki sohbet robotuna kahvaltı saatini soruyor ve cevabı hemen alıyor. Ardından odasındaki gürültüden şikâyet ediyor. Bu durumda ne yapılmalıdır?","secenekler":["Şikâyeti de sohbet robotu kendi başına çözer.","Konuğa, sabah resepsiyonu araması gerektiği yazılır.","Görüşme bir çalışana devredilir.","Sohbet robotu konuşmayı sonlandırır."],"dogru":2,"aciklama":"Sohbet robotu sık sorulan soruları cevaplar; şikâyet ya da üzgün bir konuk söz konusu olduğunda anlayış gerekir ve görüşme bir insana devredilir."},{"id":"mg-7-s33","tur":"coktan-secmeli","soru":"Otel yöneticisi doluluk grafiğine bakıp haziranda hangi haftada boş oda kaldığını görüyor ve o haftaya özel bir kampanya öneriyor. Yönetici hangi beceriyi kullanmıştır?","secenekler":["Dijital öz yönetim","Uyum yeteneği","Öz disiplin","Veri okuryazarlığı"],"dogru":3,"aciklama":"Grafikteki veriyi okuyup yorumlamak ve kararı ona göre vermek veri okuryazarlığıdır."},{"id":"mg-7-s34","tur":"coktan-secmeli","soru":"Otel kâğıt formdan tablete geçince kat hizmetleri ekibine, oda durumunu tabletten bildirmeyi öğreten kısa bir eğitim veriliyor. Bu eğitim hangi kavrama örnektir?","secenekler":["Beceri yenileme","Uyum yeteneği","Dijital öz yönetim","İnsani dokunuş"],"dogru":0,"aciklama":"Çalışanların değişen işe uyum sağlamak için yeni bir beceri kazanması beceri yenilemedir; işletmeler bunun için hizmet içi eğitim düzenler. Uyum yeteneği ise kişinin yeni koşullara direnmeden alışabilme tutumudur, eğitimin kendisi değildir."},{"id":"mg-7-s35","tur":"dogru-yanlis","soru":"Rutin işleri makineler üstlendikçe güler yüz, içten ilgi ve konuğu fark etme gibi insani dokunuş becerilerinin değeri artar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Teknoloji işlemi hızlandırır ama konuğu ağırlayan insandır; rutin işi makine aldıkça insani dokunuş daha değerli hâle gelir."},{"id":"mg-7-s36","tur":"coktan-secmeli","soru":"Bir atölyede ağır parçayı robot kol kaldırıyor; ince işçiliği ve son kontrolü usta yapıyor. İkisi aynı tezgâhta birlikte çalışıyor. Bu çalışma biçimi hangi anlayışı yansıtır?","secenekler":["Endüstri 1.0","Endüstri 2.0","Endüstri 3.0","Endüstri 5.0"],"dogru":3,"aciklama":"Endüstri 5.0, insanı yeniden merkeze alır ve insanla akıllı makinenin yan yana, iş birliği içinde çalışmasını öngörür."},{"id":"mg-7-s37","tur":"coktan-secmeli","soru":"Bir otel, klima ayarındaki bir değişikliğin enerji tüketimini nasıl etkileyeceğini önce binanın, gerçek verilerle güncellenen bilgisayardaki kopyası üzerinde deniyor. Bu kopyaya ne denir?","secenekler":["Sanal tur","Dijital ikiz","Sanal gerçeklik","Artırılmış gerçeklik"],"dogru":1,"aciklama":"Gerçek bir binanın ya da sistemin, ondan gelen verilerle güncellenen sanal kopyası dijital ikizdir; deneme önce bu kopyada yapılarak risk azaltılır."},{"id":"mg-7-s38","tur":"coktan-secmeli","soru":"Evden çalışan bir satış temsilcisi mesaisi bitince bilgisayarını kapatıyor ve akşam yemeğinde iş mesajlarına bakmıyor. Bu davranış neyi korumaya yöneliktir?","secenekler":["İş-yaşam dengesini","Veri gizliliğini","Dijital ayak izini","Siber güvenliği"],"dogru":0,"aciklama":"İşe ayrılan zamanla dinlenmeye ve aileye ayrılan zaman arasına sınır koymak iş-yaşam dengesini korur; sınır konmazsa yorgunluk birikir."},{"id":"mg-7-s39","tur":"coktan-secmeli","soru":"Bir otel güvenlik kameralarını yalnız ortak alanlara yerleştiriyor, kayıt yapıldığını levhayla bildiriyor ve odalara kamera koymuyor. Otel bu kararda neyi gözetmiştir?","secenekler":["Teknoloji etiği","Dijital öz yönetim","Dijital iletişim etiği","Beceri yenileme"],"dogru":0,"aciklama":"Bir teknolojiyi kullanırken insanlara zarar vermemeyi, dürüst ve adil davranmayı gözetmek teknoloji etiğidir; konuğun güveni korunur."},{"id":"mg-7-s40","tur":"dogru-yanlis","soru":"Bir görevlinin konuk listesini yanlışlıkla yanlış e-posta adresine göndermesi, kasıtlı olmadığı için veri ihlali sayılmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Kişisel bilgilerin yetkisiz kişinin eline geçmesi, yanlışlıkla olsa da veri ihlalidir; konukların adları ve telefonları yetkisiz kişide kalmıştır."},{"id":"mg-7-s41","tur":"coktan-secmeli","soru":"Sabah check-out kuyruğunun asıl nedeninin personel azlığı değil, yavaş çalışan bir yazıcı olduğu, olası nedenler adım adım incelenerek bulunuyor. Bu çalışma hangisidir?","secenekler":["Beyin fırtınası","Proje pazarı","Kök neden analizi","Proje fikri kanvası"],"dogru":2,"aciklama":"Sorunun görünen belirtisiyle yetinmeyip onu doğuran asıl nedeni adım adım bulmak kök neden analizidir."},{"id":"mg-7-s42","tur":"dogru-yanlis","soru":"Beyin fırtınasında fikirler ortaya atılırken hemen eleştirilir ve zayıf görülenler o anda elenir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Beyin fırtınasında herkes fikrini eleştirilmeden hızlıca söyler; fikirler ancak sonradan maliyet, uygulanabilirlik gibi ölçütlerle elenir."},{"id":"mg-7-s43","tur":"coktan-secmeli","soru":"Otel, geç saatte gelen konuklar için kapıda karşılama, kimlik kaydı, anahtar teslimi ve odaya kadar eşlik adımlarını sırayla ve her adımı kimin yapacağını belirleyerek tasarlıyor. Bu tasarım hangisine örnektir?","secenekler":["Ürün modeli","Hizmet modeli","Kök neden analizi","Proje pazarı"],"dogru":1,"aciklama":"Bir ihtiyacın belirli bir süreç izlenerek karşılanmasını gösteren tasarım hizmet modelidir; ağırlık bir araçta değil, doğru sırayla işleyen adımlardadır."}],"siralamalar":[{"id":"mg-7-r01","konu":"7.1","baslik":"Tarladan akıllı fabrikaya","yonerge":"Üretimin tarih boyunca geçirdiği dönüşüm evrelerini doğru sıraya koy.","adimlar":["Tarım toplumunda üretim daha çok insan ve hayvan gücüne dayanır.","Buhar gücü dokuma tezgâhlarını, gemileri ve trenleri çalıştırır; fabrika üretimi doğar.","Elektrik fabrikalarda yaygınlaşır, montaj hatları kurulur ve seri üretim güçlenir.","Elektronik, bilgisayar ve programlanabilir sistemler sanayide kullanılmaya başlar.","Yapay zekâ, büyük veri, algılayıcılar ve nesnelerin interneti üretimde birlikte çalışır."],"aciklama":"Tarım toplumunun ardından buhar (18. yüzyılın sonları), elektrik ve seri üretim (19. yüzyılın sonları), elektronik ve bilgisayar (1970’ler) ve dijital teknolojiler (2011’den günümüze) gelir. Her dönem bir öncekinin kurduğu altyapının üzerine yükselir."},{"id":"mg-7-r02","konu":"7.1","baslik":"Arıza çıkmadan yakala","yonerge":"Bir atölyede geleneksel bakımdan önleyici bakıma geçişin aşamalarını doğru sıraya koy.","adimlar":["Makine bozulur, bakım ekibi ancak arıza ortaya çıkınca müdahale eder.","Makineye takılan algılayıcılar çalışma sıcaklığını ve titreşimi sürekli izler.","Sistem olağan dışı bir değer görünce sorunu fark eder ve çalışanı uyarır.","Çalışan sorun büyümeden bakımı yapar; arızayı beklemeyen önleyici bakım yerleşir."],"aciklama":"Veri izlenmeden sorun önceden fark edilemez, fark edilmeden de arızaya erken müdahale edilemez. Ders kitabı bu geçişi geleneksel bakımdan veriye dayalı bakıma uzanan dört halkalı bir zincirle gösterir."},{"id":"mg-7-r03","konu":"7.3","baslik":"Fikirden proje pazarına","yonerge":"Mesleki bir soruna teknoloji destekli yenilikçi bir çözüm geliştirirken izleyeceğin adımları doğru sıraya koy.","adimlar":["Meslek alanında bir sorun seç; kimleri etkilediğini ve neden çözülmesi gerektiğini açıkla.","Balık kılçığı diyagramıyla sorunun görünen belirtilerini kök nedenlerinden ayır.","Gereken dijital teknolojiyi ya da otomasyon sistemini belirle; grupça beyin fırtınasıyla fikirleri maliyet, yarar ve güvenlik açısından tartıp birini seç.","Seçtiğin fikirle ürün ya da hizmet modelini tasarla, proje fikri kanvasına yaz ve gözden geçir.","Kanvasını kullanarak proje pazarında modelini 3–5 dakikada tanıt.","Arkadaşlarından yenilikçilik, uygulanabilirlik ve etkiler hakkında geri bildirim al ve kaydet."],"aciklama":"Sorunun nedeni bilinmeden doğru teknoloji seçilemez, fikirler tartılmadan da model tasarlanamaz. Model sunulduktan sonra alınan geri bildirim onu geliştirmenin yolunu açar; kitaptaki performans görevi bu sırayı izler."}],"acikSorular":[{"id":"mg-7-y01","konu":"7.1","soru":"Bir otelde konuklar giriş işlemlerini self check-in kiosku ve mobil check-in ile kendileri yapmaya başlamıştır. Bu gelişmenin resepsiyon görevlisinin iş rolünü nasıl değiştirdiğini açıklayınız. Görevlinin bu değişime uyum sağlamak için kazanması gereken bir dijital yetkinliği ve konukla ilişkisinde öne çıkacak insani dokunuşu örnekle yazınız; ayrıca becerilerini yenilemesinin neden gerekli olduğunu belirtiniz.","olcut":[{"metin":"Self check-in kiosku ve mobil check-in uygulamasını kısaca tanımlar.","puan":15},{"metin":"Teknolojinin resepsiyon görevlisinin geleneksel iş rolünü nasıl değiştirdiğini belirtir.","puan":25},{"metin":"Gereken bir dijital yetkinliği örnekle yazar.","puan":15},{"metin":"İnsani dokunuşun gerektiği bir durumu örnekle belirtir.","puan":15},{"metin":"Beceri yenilemenin neden gerekli olduğunu, değişen iş rolüyle ilişkilendirerek açıklar.","puan":30}],"ornek":"Self check-in kiosku, konuğun resepsiyona uğramadan giriş işlemini dokunmatik ekrandan yapmasıdır; mobil check-in ise bu işlemin otele gelmeden telefonla tamamlanmasıdır. Bu sayede görevli artık yalnızca kayıt yapan kişi olmaktan çıkar; sistemi izler, sorun yaşayan konuğa yardım eder. Dijital yetkinlik olarak kiosk ve rezervasyon yazılımını doğru ve güvenli kullanabilmesi gerekir. İnsani dokunuş olarak yardıma ihtiyacı olan konuğu güler yüzle karşılayıp ona özel ilgi gösterebilir. Çünkü iş rolü değiştiği için görevlinin becerilerini yenilemesi gerekir; yenilemezse yeni işe uyum sağlayamaz.","ipucu":"Makine işlemi hızlandırır; makinenin veremediği şeyin görevliye nasıl yeni bir değer kattığını düşünün."},{"id":"mg-7-y02","konu":"7.2","soru":"Bir acentede uzaktan çalışan bir personel, müşteri bilgilerini içeren bir dosyayı çalışmaya devam edebilmek için kendi kişisel e-posta hesabına göndermiştir. Bu davranışın hangi riske yol açabileceğini veri gizliliği kavramıyla açıklayınız. Veri güvenliğini sağlamak için yapılması gereken iki uygulamayı yazınız ve bu davranışın müşteriye ve kuruma etkisini nedenleriyle belirtiniz.","olcut":[{"metin":"Veri gizliliğini doğru tanımlar.","puan":20},{"metin":"Kurumsal dosyanın kişisel e-postaya gönderilmesinin veri ihlaline yol açabileceğini belirtir.","puan":20},{"metin":"Veri güvenliği için bir koruma uygulaması yazar.","puan":15},{"metin":"Birincisinden farklı, ikinci bir koruma uygulaması yazar.","puan":15},{"metin":"Bu davranışın müşteri güvenine ve kuruma etkisini nedenleriyle açıklar.","puan":30}],"ornek":"Veri gizliliği, kişisel veya kurumsal bilgilerin yalnızca yetkili kişilerce ve belirlenen amaç doğrultusunda kullanılmasıdır. Müşteri bilgilerini kişisel e-postaya göndermek, bilgilerin yetkisiz kişilerin eline geçmesine, yani veri ihlaline yol açabilir. Koruma için birincisi güçlü parola kullanılmalı, ikincisi kurumun onayladığı iletişim araçları tercih edilmeli ve alıcı adresleri kontrol edilmelidir. Bilgileri yetkisiz kişilere ulaşan müşteri acenteye güvenmeyebilir ve kurum itibar kaybedebilir; bu yüzden uzaktan çalışırken de etik sorumluluk sürer.","ipucu":"Bilginin kurumun kontrolünden çıkınca neler olabileceğini ve müşterinin bundan nasıl etkileneceğini düşünün."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":8,"baslik":"İnovasyonla Öğrenme Alışkanlıklarını Dönüştürme","onay":true,"kazanimlar":["Geleneksel öğrenme yöntemleri ile yenilikçi öğrenme yaklaşımlarını karşılaştırabilme.","Mesleki gelişim hedefleri doğrultusunda yetkinlik dönüşüm ihtiyaçlarına yönelik çıkarım yapabilme.","Mesleki gelişim hedeflerine yönelik öğrenme rotası yapılandırabilme."],"soz":"Diploma bir kez alınır; meslek her gün yeniden öğrenilir.","dersler":[{"baslik":"Öğrenmenin de Yenisi Olur mu?","ilk":"mg-8-001"},{"baslik":"Dinleyen mi, Yapan mı?","ilk":"mg-8-005"},{"baslik":"Cebindeki Okul","ilk":"mg-8-029"},{"baslik":"Yapay Zekâ Hocan Olur mu?","ilk":"mg-8-040"},{"baslik":"Sen Nasıl Öğrenirsin?","ilk":"mg-8-064"},{"baslik":"Bilmek Yetmez: Yetkinlik","ilk":"mg-8-016"},{"baslik":"Direksiyon Sende","ilk":"mg-8-023"},{"baslik":"Kariyerde Sıradaki Basamak","ilk":"mg-8-061"},{"baslik":"Seni Masaya Ne Oturtur?","ilk":"mg-8-042"},{"baslik":"Önce Hangisi?","ilk":"mg-8-046"},{"baslik":"Planın Cebinde","ilk":"mg-8-051"},{"baslik":"Başarının Perde Arkası","ilk":"mg-8-069"},{"baslik":"Seni Güçlü Kılan Özellikler","ilk":"mg-8-074"},{"baslik":"Yarının Mesleği Senden Ne İster?","ilk":"mg-8-079"},{"baslik":"Ders Evde, Uygulama Sınıfta","ilk":"mg-8-010"},{"baslik":"Bilmek, Yapmak, Tavır Almak","ilk":"mg-8-014"},{"baslik":"Akılda Kalmanın Yolları","ilk":"mg-8-027"},{"baslik":"Kısa, Oyunlu, Akıllı","ilk":"mg-8-032"},{"baslik":"Kendi Rotanı Çiz","ilk":"mg-8-053"},{"baslik":"Değişim Geldi, Ne Öğreneceksin?","ilk":"mg-8-084"},{"baslik":"Anlatarak Öğren","ilk":"mg-8-088"},{"baslik":"İlerlediğini Nereden Bilirsin?","ilk":"mg-8-092"}],"kavramlar":[{"id":"mg-8-001","konu":"8.1","terim":"Öğrenme","ingilizce":"Learning","tanim":"Kişinin yaşantı, çalışma ve deneyim yoluyla bilgi, beceri ya da davranışında kalıcı bir değişiklik kazanmasıdır.","ornek":"Ekim ayı, uygulama oteli: ilk gün tepsiyi iki eliyle zor taşıyan öğrenci, bir ay sonra tek eliyle dengede taşır. Arada olan şey öğrenmedir.","sektor":"Otelde öğrenme okul bitince bitmez: yeni bir sistem, yeni bir konuk profili, yeni bir standart sürekli gelir. Hızlı ve doğru öğrenen çalışan ekipte en çabuk güvenilen kişi olur.","iliskili":["mg-8-002","mg-8-007","mg-8-008"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-002","konu":"8.1","terim":"Öğrenme alışkanlığı","ingilizce":"Learning habit","tanim":"Kişinin ders çalışırken ya da yeni bir şey öğrenirken düşünmeden tekrarladığı, yerleşmiş çalışma biçimidir.","ornek":"Her akşam 20.00’de masasına oturup önce o günün kartlarını tekrar eden öğrenci ile yalnız sınavdan önceki gece çalışan öğrencinin alışkanlıkları farklıdır.","sektor":"Programın anahtar kavramlarındandır. Alışkanlık iyi de olabilir kötü de; önce fark edilir, sonra değiştirilir. Okulda düzenli çalışmayı alışkanlık edinen kişi işte de yeni standardı öğrenmek için kendiliğinden çalışır.","iliskili":["mg-8-001","mg-8-003","mg-8-024"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-003","konu":"8.1","terim":"Öğrenmede inovasyon","ingilizce":"Innovation in learning","tanim":"Öğrenme biçimini yeni yöntem ve araçlarla değiştirerek daha etkili, daha kalıcı ya da daha kolay ulaşılır hâle getirmektir.","ornek":"Kelime listesini defterden art arda okumak yerine telefondaki kartlarla kendini sınayarak çalışmaya başlayan öğrenci kendi öğrenmesinde bir yenilik yapmıştır.","sektor":"Programın anahtar kavramlarındandır. İnovasyon (yenilik) yalnız ürün ya da hizmette olmaz; çalışma biçiminde de olur. Yenilik amaç değil araçtır: işe yarıyorsa, yani daha iyi öğretiyorsa değerlidir.","iliskili":["mg-8-002","mg-8-005","mg-8-032"],"kontrol":null,"gorsel":"m6-vr-gozlugu"},{"id":"mg-8-004","konu":"8.1","terim":"Geleneksel öğrenme yaklaşımı","ingilizce":"Traditional learning approach","tanim":"Bilgiyi çoğunlukla öğretmenin anlattığı, öğrencinin dinleyip not aldığı ve herkesin aynı konuyu aynı hızda işlediği öğrenme biçimidir.","ornek":"Salı 09.00, sınıf: öğretmen tahtada ön büro bölümlerini anlatır, öğrenciler deftere yazar, hafta sonunda yazılı sınav yapılır.","sektor":"Değersiz değildir: temel bilgiyi kısa sürede, düzenli ve herkese aynı biçimde verir. Otelde de yeni personele verilen ilk bilgilendirme toplantısı böyle yapılır. Eksik kaldığı yer çoğu zaman uygulamadır.","iliskili":["mg-8-005","mg-8-006","mg-8-010"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-005","konu":"8.1","terim":"Yenilikçi öğrenme yaklaşımı","ingilizce":"Innovative learning approach","tanim":"Öğrencinin araştırarak, uygulayarak ve teknolojiden yararlanarak etkin rol aldığı, öğretmenin yol gösterici olduğu öğrenme biçimidir.","ornek":"Öğretmen “Bir otelin giriş işlemini adım adım siz çıkarın” der; gruplar video izler, kaynak tarar, sınıfta resepsiyon canlandırması yapar.","sektor":"Geleneksel yaklaşımla ortak yanı çoktur: ikisinde de hedef, emek ve tekrar vardır. Fark öğrencinin rolünde, bilgiye ulaşma yolunda ve kullanılan araçlardadır. İkisi birbirinin düşmanı değil, tamamlayıcısıdır.","iliskili":["mg-8-004","mg-8-006","mg-8-003"],"kontrol":null},{"id":"mg-8-006","konu":"8.1","terim":"Aktif öğrenme","ingilizce":"Active learning","tanim":"Öğrencinin yalnız dinlemek yerine soru sorarak, tartışarak, uygulayarak ve üreterek öğrenme sürecine katılmasıdır.","ornek":"Kahvaltı servisini yalnız slayttan izlemek yerine sınıfta masayı kendisi kuran, arkadaşına servis yapan ve hatasını tartışan öğrenci aktif öğrenir.","sektor":"Otelcilik bir uygulama mesleğidir: konuk karşılamak okuyarak değil, yaparak öğrenilir. Stajda “Ben deneyebilir miyim?” diye soran stajyer işi daha çabuk kavrar.","iliskili":["mg-8-005","mg-8-012","mg-8-031"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-007","konu":"8.1","terim":"Yaşam boyu öğrenme","ingilizce":"Lifelong learning","tanim":"Öğrenmenin okulla bitmediğini kabul ederek kişinin bilgi ve becerilerini hayatı boyunca yenilemeyi sürdürmesidir.","ornek":"Yirmi yıllık bir resepsiyon şefi, otel yeni rezervasyon programına geçince eğitime katılır; akşamları da ikinci yabancı dili için kursa gider.","sektor":"Programın anahtar kavramlarındandır. Turizmde konuk beklentisi, teknoloji ve standartlar değişir; öğrenmeyi bırakan çalışan yerinde sayar. Kariyer basamaklarını çıkanlar öğrenmeyi sürdürenlerdir.","iliskili":["mg-8-008","mg-8-020","mg-8-022"],"kontrol":null},{"id":"mg-8-008","konu":"8.1","terim":"Öğrenmeyi öğrenme","ingilizce":"Learning to learn","tanim":"Kişinin nasıl daha iyi öğrendiğini fark etmesi ve kendi öğrenmesini planlayıp yönetebilmesidir.","ornek":"Elif, İngilizce kalıp cümleleri sessizce okuyunca unuttuğunu, sesli söyleyip arkadaşıyla canlandırınca hatırladığını fark eder ve çalışma biçimini buna göre değiştirir.","sektor":"İşte kimse sana ders programı vermez: yeni bir görevi nasıl öğreneceğine çoğu zaman kendin karar verirsin. Hangi yöntemin işe yaradığını bilen kişi her yeni işi daha kısa sürede kavrar.","iliskili":["mg-8-007","mg-8-024","mg-8-026"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-009","konu":"8.1","terim":"Kişiselleştirilmiş öğrenme","ingilizce":"Personalised learning","tanim":"Öğrenme hızının, içeriğinin ve yolunun öğrencinin ihtiyacına, düzeyine ve hedefine göre ayarlandığı öğrenme biçimidir.","ornek":"Bu uygulamada bildiğin kart daha seyrek, bilemediğin kart daha sık karşına çıkar; aynı sınıftaki iki öğrencinin tekrar listesi birbirinden farklıdır.","sektor":"Programın anahtar kavramlarındandır. Otelde de eğitim kişiye göre planlanır: dili iyi olan stajyer sistem kullanımına, sistemi bilen stajyer telefon görüşmesine ağırlık verir. Zaman, eksik olan yere harcanır.","iliskili":["mg-8-010","mg-8-023","mg-8-055"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-029","konu":"8.1","terim":"Not alma","ingilizce":"Note-taking","tanim":"Dinlenen ya da okunan bilginin önemli noktalarının, kişinin kendi kısa cümleleriyle yazıya dökülmesidir.","ornek":"Staj, sabah toplantısı: şef günün gruplarını ve özel istekleri söylerken stajyer cep defterine yazar: “10.30 grup girişi, 204 ek yatak, 310 geç çıkış.”","sektor":"Söyleneni kelimesi kelimesine yazmak değil, ana fikri kendi cümlenle yazmaktır. Otelde not almayan çalışan konuğun isteğini unutur; cep defteri profesyonelin hafızasıdır.","iliskili":["mg-8-030","mg-8-026","mg-8-057"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-034","konu":"8.1","terim":"Öğrenme yönetim sistemi","ingilizce":"Learning management system (LMS)","tanim":"Derslerin, ödevlerin ve sınavların çevrim içi sunulduğu, öğrencinin ilerlemesinin de kayıt altında tutulduğu yazılım platformudur.","ornek":"Öğretmen ödevi platforma yükler; öğrenci evden girip videoyu izler, testi çözer, ödevini gönderir. Öğretmen kimin hangi konuyu tamamladığını ekranda görür.","sektor":"Programın anahtar kavramlarından; kısaca LMS denir. Otel zincirleri personel eğitimlerini çoğu zaman böyle bir sistem üzerinden verir: her çalışan kendi hesabıyla girer, tamamladığı eğitimler kaydedilir.","iliskili":["mg-8-035","mg-8-032","mg-8-010"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-035","konu":"8.1","terim":"Çevrim içi kurs","ingilizce":"Online course","tanim":"İnternet üzerinden izlenen; video, okuma ve alıştırmalardan oluşan ve katılımcının çoğu zaman kendi hızında tamamladığı eğitim programıdır.","ornek":"Yaz tatilinde evden katılınan “Otelcilik İngilizcesi” kursu: her hafta birkaç video, bir alıştırma ve bölüm sonu testi vardır.","sektor":"Yer ve saat serbestliği sağlar; vardiyalı çalışan biri için büyük kolaylıktır. Öbür yüzü: başında kimse olmadığı için yarım bırakmak kolaydır. Kursu bitirmek öz disiplin ister.","iliskili":["mg-8-034","mg-8-036","mg-8-025"],"kontrol":null,"cizim":"sosyal-medya"},{"id":"mg-8-039","konu":"8.1","terim":"Güvenilir kaynak","ingilizce":"Reliable source","tanim":"Bilgiyi kimin, ne zaman ve neye dayanarak verdiği belli olan, uzmanlığı ve doğruluğu denetlenebilen bilgi kaynağıdır.","ornek":"Vize kurallarını araştıran öğrenci, bir sosyal medya paylaşımına değil, ilgili ülkenin resmî kurumunun sitesine bakar.","sektor":"Konuğa yanlış bilgi vermek hiç bilgi vermemekten kötüdür: konuk müzeye kapalı günde gider, uçağını kaçırır. Profesyonel, bilgiyi resmî ve güncel kaynaktan doğrular; emin değilse “Teyit edip döneyim” der.","iliskili":["mg-8-033","mg-8-040"],"kontrol":null},{"id":"mg-8-040","konu":"8.1","terim":"Yapay zekâ destekli öğrenme","ingilizce":"AI-assisted learning","tanim":"Konu açıklaması, örnek soru ya da çalışma planı gibi destekleri yapay zekâ araçlarından alarak yapılan öğrenmedir.","ornek":"Öğrenci bir yapay zekâ aracına “Bana resepsiyonda geçen İngilizce bir konuşma yaz, sonra beni sına” der; çıkan cümleleri öğretmenine gösterip doğrulatır.","sektor":"Yapay zekâ ikna edici bir dille yanlış bilgi de verebilir; verdiği bilgi güvenilir kaynaktan doğrulanır. Ödevi ona yazdırıp kendi işin gibi sunmak dürüstlüğe aykırıdır ve sana bir şey öğretmez. Araç yardımcıdır, öğrenen sensin.","iliskili":["mg-8-039","mg-8-033","mg-8-032"],"kontrol":null},{"id":"mg-8-057","konu":"8.1","terim":"Öğrenme günlüğü","ingilizce":"Learning journal","tanim":"Kişinin ne öğrendiğini, nasıl öğrendiğini ve nerede zorlandığını düzenli olarak yazdığı kişisel kayıttır.","ornek":"Cuma, dersten sonra: “Bu hafta masa düzenini öğrendim. Çatal bıçak sırasını karıştırdım; fotoğrafını çekip üç gün baktım, işe yaradı. Haftaya bardak dizilişi.”","sektor":"Yazmak düşünmeyi yavaşlatır ve netleştirir. Haftalar sonra geri dönüp okuduğunda ne kadar yol aldığını ve hangi yöntemin sende işe yaradığını görürsün.","iliskili":["mg-8-058","mg-8-029","mg-8-059"],"kontrol":null,"gorsel":"m6-gunluk-defter"},{"id":"mg-8-058","konu":"8.1","terim":"Yansıtma","ingilizce":"Reflection","tanim":"Kişinin yaşadığı bir öğrenme deneyimini durup düşünerek ne yaptığını, neyin işe yaradığını ve bir dahaki sefere neyi farklı yapacağını değerlendirmesidir.","ornek":"Staj dönüşü servis otobüsünde: “Bugün bir konuğun sorusunu anlamadım ve panikledim. Yarın anlamadığımda kibarca tekrar etmesini isteyeceğim.”","sektor":"Deneyim tek başına öğretmez; üzerine düşünülen deneyim öğretir. Aynı hatayı her gün yineleyen ile her gün biraz düzelten çalışan arasındaki fark budur.","iliskili":["mg-8-057","mg-8-024","mg-8-060"],"kontrol":null},{"id":"mg-8-063","konu":"8.1","terim":"Etkileşimli materyal","ingilizce":"Interactive learning material","tanim":"Öğrencinin yalnız okuyup izlemekle kalmayıp tıklayarak, cevap vererek ve deneyerek katıldığı dijital ya da basılı öğrenme kaynağıdır.","ornek":"Salı 10.30, bilgisayar atölyesi: öğrenci, otel odası planında tıkladığı bölümün adını gören bir uygulamayla oda türlerini çalışır.","sektor":"Yenilikçi öğrenmenin araçlarındandır; personel eğitimlerinde konuk karşılama adımlarını tıklayarak deneten programlar da bu türdendir.","iliskili":["mg-8-067","mg-8-005","mg-8-004"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-064","konu":"8.1","terim":"Öğrenme analiz formu","ingilizce":"Learning analysis form","tanim":"Kişinin nasıl öğrendiğini, nerede zorlandığını ve neyin kendisini motive ettiğini sorularla gözden geçirmesini sağlayan formdur.","ornek":"Ekim ayının ilk haftası, sınıf: Ece formdaki “Yeni konuyu en kolay hangi yöntemle öğrenirim?” sorusuna “Önce izleyip sonra kendim denerim” yazar.","sektor":"Kendini tanımak, hangi yöntemin işe yaradığını görmenin ilk adımıdır; kendi öğrenmesini bilen çalışan yeni bir sistemi daha çabuk kavrar.","iliskili":["mg-8-008","mg-8-007","mg-8-014"],"kontrol":null,"cizim":"belge-form"},{"id":"mg-8-065","konu":"8.1","terim":"Öğretmen rehberliği","ingilizce":"Teacher guidance","tanim":"Öğretmenin konuyu açıklaması, yol göstermesi ve öğrencinin çalışmasına dönüt vermesiyle öğrenmeyi yönlendirmesidir.","ornek":"Perşembe 14.00, servis atölyesi: öğretmen tepsi taşıma hareketini yavaş yavaş gösterir, sonra öğrencinin elini düzeltir.","sektor":"Dijital araçlar öğretmen rehberliğinin yerini almaz, onu destekler; doğru kaynağı seçmeyi de çoğu zaman öğretmen gösterir.","iliskili":["mg-8-005","mg-8-006","mg-8-066"],"kontrol":null,"cizim":"acente"},{"id":"mg-8-066","konu":"8.1","terim":"İş birlikli öğrenme","ingilizce":"Collaborative learning","tanim":"Öğrencilerin ortak bir amaca ulaşmak için görev ve sorumlulukları paylaşarak birlikte çalıştığı öğrenme biçimidir.","ornek":"Pazartesi 3. ders: dört kişilik grup, bir otelin açılış haftası programını hazırlar; biri araştırır, biri yazar, biri çizer, biri sunar.","sektor":"Otelde de iş ekiple yürür; okulda görev paylaşmayı öğrenen kişi ön büro, mutfak ve kat hizmetleri arasındaki iş birliğine daha kolay uyum sağlar.","iliskili":["mg-8-019","mg-8-065","mg-8-078"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-8-067","konu":"8.1","terim":"Dijital kaynak","ingilizce":"Digital resource","tanim":"Bilgiye ekranlı cihazlar üzerinden ulaşılan; e-kitap, video, çevrim içi ders ve uygulama gibi öğrenme kaynaklarının genel adıdır.","ornek":"Cumartesi 15.00, evde: öğrenci bir otelin tanıtım videosunu izler, ardından konuyla ilgili e-kitap bölümünü okur.","sektor":"Çok sayıda dijital kaynak bulunur ama hepsi güvenilir değildir; kaynağın kim tarafından, ne zaman ve neye dayanarak hazırlandığına bakmak gerekir.","iliskili":["mg-8-010","mg-8-035","mg-8-039"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-016","konu":"8.2","terim":"Mesleki yetkinlik","ingilizce":"Professional competence","tanim":"Bir işi istenen düzeyde yapabilmek için gereken bilgi, beceri ve tutumun bir arada bulunmasıdır.","ornek":"İyi bir resepsiyon görevlisi oda tiplerini bilir (bilgi), giriş işlemini hatasız yapar (beceri) ve yorgun konuğu güler yüzle karşılar (tutum).","sektor":"Üçü birlikte olmalıdır: bilen ama yapamayan, yapan ama özen göstermeyen çalışan yetkin sayılmaz. İş ilanlarında aranan şey de çoğu zaman bu üçünün bileşimidir.","iliskili":["mg-8-017","mg-8-018","mg-8-019"],"kontrol":null},{"id":"mg-8-020","konu":"8.2","terim":"Yetkinlik dönüşümü","ingilizce":"Skills transformation","tanim":"Mesleğin değişen ihtiyaçlarına ayak uydurmak için kişinin bilgi, beceri ve tutumlarını yenilemesi ve geliştirmesidir.","ornek":"Rezervasyonların çoğu internetten gelmeye başlayınca, yıllarca telefonla kayıt alan görevli çevrim içi rezervasyon ekranını ve konuk yorumlarına cevap yazmayı öğrenir.","sektor":"Meslek aynı kalsa da işin yapılış biçimi değişir. Kendine şunu sor: “Sektör yarın benden ne isteyecek, bugün bende ne eksik?” Bu soruya verdiğin cevap öğrenme planının başlangıcıdır.","iliskili":["mg-8-021","mg-8-022","mg-8-023"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-021","konu":"8.2","terim":"Yeniden beceri kazanma","ingilizce":"Reskilling","kitapDisi":true,"tanim":"Kişinin farklı bir işi ya da görevi yapabilmek için kendisinde bulunmayan yeni bir beceri alanını öğrenmesidir.","ornek":"Yıllarca santralde çalışan bir görevli otelin sosyal medya hesaplarını yönetmek üzere dijital içerik hazırlama eğitimi alır ve yeni görevine geçer.","sektor":"Sektörde İngilizcesiyle söylenir: reskilling. Bir görev teknolojiyle azaldığında işletme, deneyimli çalışanını kaybetmek yerine ona yeni bir alan öğretir; çalışan da mesleğin içinde kalır.","iliskili":["mg-8-022","mg-8-020","mg-8-007"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-022","konu":"8.2","terim":"Beceri geliştirme","ingilizce":"Upskilling","kitapDisi":true,"tanim":"Kişinin hâlen yaptığı işi daha iyi yapabilmek için mevcut becerilerini ilerletmesi ve üstüne yenilerini eklemesidir.","ornek":"Yıllardır serviste çalışan bir garson kahve hazırlama ve servisi eğitimine katılır; aynı işi artık daha üst düzeyde yapar.","sektor":"Sektörde İngilizcesiyle söylenir: upskilling. Yeniden beceri kazanmada alan değişir; burada alan aynıdır, düzey yükselir. Terfi çoğu zaman bu yolla gelir.","iliskili":["mg-8-021","mg-8-020","mg-8-007"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-023","konu":"8.2","terim":"Gelişime açık yön","ingilizce":"Area for development","tanim":"Kişinin hedefine ulaşabilmesi için henüz yeterli olmadığı ve güçlendirmesi gereken bilgi, beceri ya da tutumdur.","ornek":"Staj değerlendirmesinde şef yazar: “Konukla iletişimi çok iyi. Telefonda İngilizce konuşurken çekiniyor; geliştirmeli.” İkinci cümle gelişime açık yöndür.","sektor":"“Zayıf yön” demek yerine böyle söylenir, çünkü değişebilir. Mevcut yetkinlik ile hedefin istediği yetkinlik arasındaki fark bulunmadan plan yapılamaz; eksiğini bilen çalışan nereye çalışacağını da bilir.","iliskili":["mg-8-020","mg-8-053","mg-8-056"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-024","konu":"8.2","terim":"Öz düzenleme","ingilizce":"Self-regulation","tanim":"Kişinin kendi öğrenmesini başkası söylemeden planlaması, çalışırken kendini izlemesi ve sonucu değerlendirip gerekirse yöntemini değiştirmesidir.","ornek":"Deniz pazar akşamı haftanın çalışma planını yapar, çarşamba günü geride kaldığını görür, perşembe planını yeniden düzenler.","sektor":"Programın anahtar kavramlarındandır. Üç adımı vardır: hedef koy ve planla, uygularken izle, sonunda değerlendir. Otelde şef her an yanında olmaz; kendi işini kendi denetleyen çalışana sorumluluk verilir.","iliskili":["mg-8-025","mg-8-008","mg-8-058"],"kontrol":null,"cizim":"etik-terazi"},{"id":"mg-8-025","konu":"8.2","terim":"Öğrenmede öz disiplin","ingilizce":"Self-discipline in learning","tanim":"Kişinin, canı istemese de ve başında denetleyen biri olmasa da çalışma planına uyup öğrenmeyi sürdürebilmesidir.","ornek":"Cumartesi sabahı arkadaşları dışarıdayken önce planındaki yarım saatlik İngilizce çalışmasını bitirip sonra onlara katılan öğrenci.","sektor":"Sabah 06.00 vardiyasına her gün zamanında gelmek, kimse bakmasa da standardı eksiksiz uygulamak öz disiplindir. Yetenek başlatır, öz disiplin sürdürür.","iliskili":["mg-8-024","mg-8-044","mg-8-045"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-026","konu":"8.2","terim":"Öğrenme stratejisi","ingilizce":"Learning strategy","tanim":"Bilgiyi daha kolay anlamak, akılda tutmak ve gerektiğinde hatırlamak için bilerek seçilen çalışma yoludur.","ornek":"Aynı konuyu çalışan iki öğrenci: biri metni üç kez baştan okur, öteki kartlarla kendini sınar ve bilemediklerini ertesi gün yeniden çalışır.","sektor":"Çok çalışmak ile doğru çalışmak aynı şey değildir. Metni yalnızca yeniden okumak “biliyorum” duygusu verir ama çoğu zaman kalıcı olmaz; kendini sınamak ve tekrarı zamana yaymak daha kalıcıdır.","iliskili":["mg-8-027","mg-8-028","mg-8-008"],"kontrol":null},{"id":"mg-8-061","konu":"8.2","terim":"Kariyer basamağı","ingilizce":"Career step","tanim":"Kişinin mesleki yaşamında bir görevden daha yüksek sorumluluklu bir göreve doğru ilerlerken geçtiği her bir aşamadır.","ornek":"Otelde stajyer olarak başlayan bir genç sırasıyla resepsiyon görevlisi, ön büro şefi ve ön büro müdürü olabilir; her görev bir kariyer basamağıdır.","sektor":"Basamaklar kendiliğinden çıkılmaz; her basamak yeni bir yetkinlik, öz disiplin ve sorumluluk bilinci gerektirir. Eylem planı bu basamaklar düşünülerek yapılır.","iliskili":["mg-8-016","mg-8-020","mg-8-025"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-062","konu":"8.2","terim":"Mesleki eğilim","ingilizce":"Vocational interest","tanim":"Kişinin hangi tür işlerden hoşlandığını ve hangilerinde kendini güçlü hissettiğini gösteren, meslek seçimini etkileyen kişisel ilgi ve yatkınlıktır.","ornek":"İnsanlarla konuşmaktan hoşlanan bir öğrenci ön büroya ve satışa, düzen ve ayrıntıya düşkün bir öğrenci kat hizmetlerine ya da mutfağa daha yatkın olabilir.","sektor":"Kişisel ilgi ve özelliklerle uyumsuz bir meslek kişiyi mutsuz edebilir. Eğilimini bilmek, sektörün gelecekte isteyeceği yetkinliklerden hangisini önce geliştireceğini seçmeye yarar.","iliskili":["mg-8-016","mg-8-020","mg-8-041"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-033","konu":"8.2","terim":"Dijital okuryazarlık","ingilizce":"Digital literacy","tanim":"Bilgiye dijital araçlarla ulaşma, bilginin doğruluğunu sorgulama, içerik üretme ve bunları güvenli biçimde yapabilme becerisidir.","ornek":"Ödev için arama yapan öğrenci ilk çıkan sonucu kopyalamaz; kaynağın kim olduğuna bakar, bilgiyi ikinci bir kaynakla karşılaştırır ve kendi cümleleriyle yazar.","sektor":"Programın anahtar kavramlarındandır. Otelde rezervasyon sistemi, e-posta, çevrim içi konuk yorumları ve dijital ödeme her gün kullanılır. Dijital okuryazar çalışan aracı yalnız kullanmaz; konuk bilgisini de korur.","iliskili":["mg-8-032","mg-8-039","mg-8-040"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-041","konu":"8.2","terim":"Öğrenme motivasyonu","ingilizce":"Motivation to learn","tanim":"Kişiyi öğrenmeye başlatan ve zorlandığında da sürdürmesini sağlayan istek ve nedendir.","ornek":"Yazın yabancı konukların geldiği bir otelde staj yapacağını öğrenen Ayşe o güne kadar ertelediği İngilizce çalışmasına kendiliğinden başlar.","sektor":"Motivasyona güdülenme de denir. Çoğu zaman beklenerek gelmez, başlayınca gelir: “Neden öğreniyorum?” sorusunun cevabını bilen kişi masaya daha kolay oturur.","iliskili":["mg-8-042","mg-8-043","mg-8-044"],"kontrol":null,"cizim":"lider"},{"id":"mg-8-042","konu":"8.2","terim":"İçsel motivasyon","ingilizce":"Intrinsic motivation","tanim":"Kişinin bir işi ödül ya da zorunluluk için değil, merak ettiği, sevdiği ya da kendisi için anlamlı bulduğu için yapmasıdır.","ornek":"Kahve yapımını merak eden öğrenci, kimse ödev vermediği hâlde hafta sonu videolar izler ve evde dener.","sektor":"Dışarıdan ödül gelmediğinde de sürer; bu yüzden uzun yolda daha dayanıklıdır. Mesleğini seven çalışanın özeni konuğa da geçer.","iliskili":["mg-8-041","mg-8-043","mg-8-044"],"kontrol":null,"cizim":"lider"},{"id":"mg-8-043","konu":"8.2","terim":"Dışsal motivasyon","ingilizce":"Extrinsic motivation","tanim":"Kişinin bir işi not, ödül, övgü ya da ceza gibi dışarıdan gelen bir sonuç nedeniyle yapmasıdır.","ornek":"Sınavdan yüksek not almak, ayın personeli seçilmek ya da ailesinin söz verdiği ödülü kazanmak için çalışan öğrenci.","sektor":"Kötü değildir: maaş, prim ve takdir belgesi de dışsal kaynaklardır ve işe yarar. Zayıf yanı, ödül ortadan kalkınca isteğin de azalabilmesidir; en sağlamı ikisinin birlikte olmasıdır.","iliskili":["mg-8-041","mg-8-042","mg-8-038"],"kontrol":null,"gorsel":"m6-kupa-odul"},{"id":"mg-8-044","konu":"8.2","terim":"Azim","ingilizce":"Perseverance","tanim":"Zorlukla ya da başarısızlıkla karşılaşıldığında vazgeçmeyip hedefe doğru çalışmayı sürdürme kararlılığıdır.","ornek":"İlk canlandırmada İngilizce cümleleri karıştırıp utanan öğrenci bırakmaz; her gün birkaç dakika prova yapar, üç hafta sonra aynı sahneyi takılmadan oynar.","sektor":"Otelcilikte ustalık zaman ister: ilk haftada her şeyi doğru yapan stajyer yoktur. Hatasından sonra yeniden deneyen kişi ilerler; kariyer basamakları tek tek çıkılır.","iliskili":["mg-8-025","mg-8-041","mg-8-045"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-8-045","konu":"8.2","terim":"Erteleme","ingilizce":"Procrastination","tanim":"Yapılması gereken bir işi, yapılabilecek durumdayken sonraya bırakma alışkanlığıdır.","ornek":"İki hafta süresi olan performans görevine “Yarın başlarım” diye diye son geceye kalan ve sabaha karşı yarım yamalak bitiren öğrenci.","sektor":"İş büyük ve belirsiz göründüğünde ertelenir. Çaresi işi küçük parçalara bölmek ve ilk parçaya hemen başlamaktır. Otelde ertelenen iş kaybolmaz; bir sonraki vardiyaya ya da bekleyen konuğa yük olur.","iliskili":["mg-8-046","mg-8-050","mg-8-025"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-8-046","konu":"8.2","terim":"Dikkat dağıtıcı","ingilizce":"Distraction","tanim":"Kişinin o an yaptığı işten dikkatini çekip başka yöne kaydıran ses, bildirim, kişi ya da düşüncedir.","ornek":"Akşam 19.00, ders masası: telefona bildirim gelir, “Bir bakıp bırakacağım” denir; yarım saat sonra kitap hâlâ aynı sayfadadır.","sektor":"Çalışırken telefonu sessize alıp başka odaya bırakmak en basit önlemdir. Otelde de konukla ilgilenirken telefona bakmak hem hataya yol açar hem de konuğa “Benimle ilgilenmiyor” duygusu verir.","iliskili":["mg-8-045","mg-8-050","mg-8-032"],"kontrol":null,"cizim":"telefon"},{"id":"mg-8-047","konu":"8.2","terim":"Zaman yönetimi teknikleri","ingilizce":"Time management techniques","tanim":"Zamanı planlı kullanmak ve işleri vaktinde bitirmek için uygulanan önceliklendirme, listeleme ve süre tutma gibi pratik yöntemlerdir.","ornek":"Pazar akşamı haftalık planını yapan, her gün yapılacaklar listesi yazan ve ders çalışırken süre tutan öğrenci üç ayrı teknik kullanır.","sektor":"Herkesin günü aynı uzunluktadır; farkı planlama yaratır. Otelde giriş, kahvaltı ve transfer saatleri değişmez: zamanını yönetemeyen çalışan konuğu bekletir.","iliskili":["mg-8-048","mg-8-050","mg-8-052"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-8-048","konu":"8.2","terim":"Önceliklendirme","ingilizce":"Prioritisation","tanim":"Yapılacak işleri önem ve aciliyetlerine göre sıraya koyarak önce hangisinin yapılacağına karar vermektir.","ornek":"Akşam üç işin var: yarın teslim edilecek ödev, gelecek haftaki sınavın tekrarı ve oda toplama. Önce ödevi, sonra tekrarı yaparsın; oda en sona kalır.","sektor":"Resepsiyonda aynı anda telefon çalar, konuk bekler, e-posta gelir: karşındaki konuk önce gelir. Her işi aynı anda yapmaya çalışan hiçbirini iyi yapamaz.","iliskili":["mg-8-049","mg-8-047","mg-8-051"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-8-049","konu":"8.2","terim":"Eisenhower matrisi","ingilizce":"Eisenhower matrix","kitapDisi":true,"tanim":"İşleri “acil mi?” ve “önemli mi?” sorularına göre dört kutuya ayırarak hangisinin önce yapılacağını gösteren önceliklendirme aracıdır.","ornek":"Yarın teslim edilecek ödev: acil ve önemli, hemen yap. Gelecek ayki sınava hazırlık: önemli ama acil değil, takvime yaz. Sürekli gelen grup mesajları: acil görünür ama önemli değil, kısa tut. Amaçsız video kaydırma: ikisi de değil, bırak.","sektor":"Adını, zamanını böyle planladığı anlatılan ABD Başkanı Dwight D. Eisenhower’dan alır. En çok ihmal edilen kutu “önemli ama acil değil” kutusudur: dil öğrenmek, tekrar yapmak. Kariyeri büyüten işler çoğu zaman o kutudadır.","iliskili":["mg-8-048","mg-8-047","mg-8-052"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-8-050","konu":"8.2","terim":"Pomodoro tekniği","ingilizce":"Pomodoro Technique","kitapDisi":true,"tanim":"Çalışmayı, kesintisiz odaklanılan kısa bölümlere ve aralarındaki kısa molalara ayıran zaman yönetimi tekniğidir.","ornek":"Saat 18.00: telefonun sayacını kurarsın ve bir bölüm boyunca yalnız İngilizce kalıp cümlelere çalışırsın. Sayaç çalınca kalkıp su içersin; birkaç bölümden sonra daha uzun bir mola verirsin.","sektor":"Tekniği İtalyan Francesco Cirillo geliştirmiştir; adı, kullandığı domates biçimli mutfak sayacından gelir (pomodoro, İtalyanca domates). “Yalnızca bir bölüm çalışacağım” demek başlamayı kolaylaştırır; bölüm sırasında telefona bakılmaz.","iliskili":["mg-8-045","mg-8-046","mg-8-047"],"kontrol":null,"gorsel":"t13f-mutfak-sayaci"},{"id":"mg-8-051","konu":"8.2","terim":"Kontrol listesi","ingilizce":"Checklist","tanim":"Yapılacak işlerin ya da bir işin adımlarının alt alta yazıldığı, tamamlanan maddenin tek tek işaretlendiği listedir.","ornek":"Sabah yazdığın liste: “1. Matematik ödevi 2. Bugünün kartları 3. Staj dosyasını imzalat.” Akşam üçünün de yanında işaret vardır.","sektor":"Otelde her yerde karşına çıkar: kat görevlisinin oda kontrol listesi, açılış ve kapanış listeleri. Hafızaya güvenmek yerine listeye bakılır; böylece yoğun günde bile adım atlanmaz.","iliskili":["mg-8-048","mg-8-052","mg-8-047"],"kontrol":null,"cizim":"belge-form"},{"id":"mg-8-052","konu":"8.2","terim":"Haftalık çalışma planı","ingilizce":"Weekly study plan","tanim":"Bir haftanın gün ve saatlerine hangi dersin ya da işin çalışılacağının önceden yerleştirildiği zaman çizelgesidir.","ornek":"Pazar akşamı hazırlanan tablo: “Pazartesi 19.00–19.30 İngilizce kalıp cümleler, salı 19.00–19.30 kart tekrarı, çarşamba staj günü: yalnız 10 dakika tekrar.”","sektor":"Plan kendi saatlerine göre yapılır: staj gününe uzun çalışma yazmak gerçekçi değildir. Otelde vardiya çizelgesi aynı işi görür: kim, ne zaman, nerede olacağını önceden bilir.","iliskili":["mg-8-047","mg-8-051","mg-8-055"],"kontrol":null,"cizim":"takvim"},{"id":"mg-8-056","konu":"8.2","terim":"Bireysel gelişim eylem planı","ingilizce":"Personal development plan","tanim":"Kişinin gelişime açık yönlerini, bunlar için koyduğu hedefleri, yapacağı çalışmaları ve tarihlerini bir arada gösteren yazılı plandır.","ornek":"Dönem başında doldurulan bir sayfa: “Geliştireceğim yön: telefonda İngilizce. Hedefim: … Yapacaklarım: … Bitiş tarihi: … Kimden destek alacağım: İngilizce öğretmenim.”","sektor":"Kitapta “bireysel gelişim eylem planı” adıyla geçer. Birçok işletme çalışanıyla belli aralıklarla böyle bir plan yapar ve değerlendirme görüşmesinde ona bakar. Öğrenme rotası tek bir hedefin yoludur; gelişim planı kişinin bütün gelişim alanlarını bir arada gösterir.","iliskili":["mg-8-023","mg-8-055","mg-8-054"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-068","konu":"8.2","terim":"Çıkış kartı","ingilizce":"Exit card","tanim":"Dersin ya da ünitenin sonunda öğrencinin ne öğrendiğini, neyi geliştirmesi gerektiğini ve ne yapacağını kısa notlarla yazdığı karttır.","ornek":"Ders bitmeden hemen önce öğrenci kartına “Geliştirmem gereken yön: zamanı planlamak” yazar ve öğretmene bırakır.","sektor":"Kısa yazılı değerlendirme alışkanlığı, iş yerinde vardiya sonu notu bırakmaya benzer; gün içinde öğrenileni görünür kılar.","iliskili":["mg-8-056","mg-8-057","mg-8-044"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-069","konu":"8.2","terim":"Öğrenme performansı","ingilizce":"Learning performance","tanim":"Kişinin öğrenme sürecinde gösterdiği çabayı, ilerlemeyi ve elde ettiği sonuçları birlikte anlatan kavramdır.","ornek":"Mert iki hafta her akşam düzenli çalışır, sınav notu ise henüz yükselmemiştir; çabası ve ilerlemesi öğrenme performansının parçasıdır.","sektor":"Öğrenme performansı ile akademik başarı ilişkilidir ama aynı şey değildir; yöntem yanlışsa çok çalışmak yine de beklenen sonucu getirmeyebilir.","iliskili":["mg-8-070","mg-8-047","mg-8-025"],"kontrol":null,"cizim":"doga"},{"id":"mg-8-070","konu":"8.2","terim":"Akademik başarı","ingilizce":"Academic achievement","tanim":"Derslerde belirlenen hedeflere ne ölçüde ulaşıldığını gösteren, genellikle not ve değerlendirmelerle ölçülen düzeydir.","ornek":"Dönem sonunda Elif’in Genel Turizm dersinde hedeflenen kazanımların çoğunu karşıladığı karnesinde görülür.","sektor":"Akademik başarı yalnız çabaya bağlı değildir; kullanılan yöntem, zaman yönetimi ve çalışma alışkanlıkları da etkiler.","iliskili":["mg-8-069","mg-8-071","mg-8-047"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-071","konu":"8.2","terim":"Öğrenme tercihi","ingilizce":"Learning preference","tanim":"Kişinin duruma ve konuya göre şema izleyerek, dinleyerek ya da uygulayarak öğrenmeyi daha çok seçmesidir.","ornek":"Salı 11.00, mutfak atölyesi: Ali makine parçalarını şemadan öğrenir, makineyi kullanmayı ise uygulayarak öğrenir.","sektor":"Bunlar değişmez “öğrenme tipleri” değildir; konu değişince tercih de değişebilir, bu yüzden farklı yollar birlikte denenir.","iliskili":["mg-8-007","mg-8-008","mg-8-064"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-072","konu":"8.2","terim":"İlgi ve merak","ingilizce":"Interest and curiosity","tanim":"Kişinin bir konuya yönelmesini, soru sormasını ve araştırmasını sağlayan istektir.","ornek":"Cuma 13.00, kütüphane: Zeynep resepsiyonda kullanılan programı merak ettiği için kendiliğinden araştırır.","sektor":"İlgi ve merak öğrenme performansını etkileyen bir özelliktir; merak eden çalışan yeni teknolojiyi çabuk öğrenir.","iliskili":["mg-8-032","mg-8-033","mg-8-073"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-073","konu":"8.2","terim":"Dikkat ve odaklanma","ingilizce":"Attention and focus","tanim":"Kişinin bir işe zihnini verip dağılmadan sürdürebilme becerisidir.","ornek":"Perşembe 19.00, ders masası: Sena telefonu çantaya koyar ve ders boyunca yalnızca rezervasyon formuna çalışır.","sektor":"Dikkat ve odaklanma, bilgilerin anlaşılmasına ve görevlerin hatasız tamamlanmasına katkı sağlar; kasada ya da resepsiyonda hata payını azaltır.","iliskili":["mg-8-037","mg-8-036","mg-8-038"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-074","konu":"8.2","terim":"Sorumluluk bilinci","ingilizce":"Sense of responsibility","tanim":"Kişinin görevlerinin ve tercihlerinin sonuçlarını sahiplenmesi ve üzerine düşeni zamanında yapmasıdır.","ornek":"Pazartesi 08.00: stajyer Burak teslim tarihi yarın olan staj dosyasını bu akşam bitireceğini şefine söyler ve bitirir.","sektor":"Sorumluluk bilinci öğrenmenin ve eylem planının sürdürülmesinin temelidir; zamanında bitmeyen görevin kariyere etkisi Zıt Panel etkinliğinde tartışılır.","iliskili":["mg-8-025","mg-8-026","mg-8-075"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-075","konu":"8.2","terim":"Özgüven","ingilizce":"Self-confidence","tanim":"Kişinin kendi yapabileceğine inanması ve yeni görevleri denemeye cesaret etmesidir.","ornek":"Salı 09.30, ön büro atölyesi: Derya hiç yapmadığı check-in canlandırmasında gönüllü olur.","sektor":"Özgüven yeni görevleri denemeyi ve zorluklarla baş etmeyi etkiler; deneyen çalışan geri bildirim alır ve gelişir.","iliskili":["mg-8-077","mg-8-073","mg-8-076"],"kontrol":null,"cizim":"is-birligi"},{"id":"mg-8-076","konu":"8.2","terim":"Problem çözme","ingilizce":"Problem solving","tanim":"Karşılaşılan bir sorunu anlamak, seçenekleri düşünmek ve uygun çözümü uygulamak becerisidir.","ornek":"Akşam 18.00, otel lobisi: asansör bozulduğunda valiz taşıyan görevli, konuğu merdiven yerine hizmet asansörüne yönlendirir.","sektor":"Problem çözme hem öğrenme sırasındaki güçlüklere farklı çözüm bulmak hem de geleceğin mesleki yetkinliği olarak önem taşır.","iliskili":["mg-8-078","mg-8-079","mg-8-053"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-077","konu":"8.2","terim":"Fiziksel ve duygusal durum","ingilizce":"Physical and emotional state","tanim":"Kişinin uyku, beslenme, stres ve duygu gibi etkenlerle şekillenen genel iyilik hâlidir.","ornek":"Sabah 07.30: önceki gece çok az uyuyan öğrenci derste dikkatini toplamakta zorlanır.","sektor":"Uyku, beslenme, stres ve duygular öğrenmeye ayrılan dikkati etkiler; yoğun sezonda dinlenmiş çalışan konuğa da daha iyi hizmet verir.","iliskili":["mg-8-073","mg-8-074","mg-8-024"],"kontrol":null,"cizim":"kalp-empati"},{"id":"mg-8-078","konu":"8.2","terim":"İş birliği ve iletişim","ingilizce":"Collaboration and communication","tanim":"Kişinin başkalarıyla görev paylaşıp bilgi alışverişi yaparak ortak amaca ulaşmasıdır.","ornek":"Cumartesi 20.00, restoran: servis görevlisi masa hazır olunca mutfağa haber verir, mutfak tabağı zamanında çıkarır.","sektor":"İş birliği; akranlardan öğrenmeye, görev paylaşmaya ve ortak ürün oluşturmaya katkı verir ve geleceğin yetkinliklerindendir.","iliskili":["mg-8-066","mg-8-019","mg-8-079"],"kontrol":null,"cizim":"konusma"},{"id":"mg-8-079","konu":"8.2","terim":"Geleceğin mesleki yetkinlikleri","ingilizce":"Future professional competencies","tanim":"Dijitalleşme, yapay zekâ, otomasyon ve sürdürülebilir üretim gibi gelişmeler nedeniyle gelecekte çalışanlardan beklenecek bilgi, beceri ve tutumlardır.","ornek":"Otelin tüm rezervasyonlarını çevrim içi alması, ön büro çalışanından dijital okuryazarlık ve yeni sistemi hızlı öğrenme beklentisi doğurur.","sektor":"Dijital okuryazarlık, teknoloji kullanımı, problem çözme, iş birliği ve iletişim, zaman yönetimi, öz disiplin, sorumluluk bilinci, yeni şeyler öğrenme isteği ve alana özgü teknik yetkinlik bunların örnekleridir.","iliskili":["mg-8-076","mg-8-078","mg-8-080"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-080","konu":"8.2","terim":"Alana özgü teknik yetkinlik","ingilizce":"Occupation-specific technical competence","tanim":"Bir meslek alanında işin gerektirdiği özel bilgi ve uygulama becerisidir.","ornek":"Pazartesi 09.00, resepsiyon: görevli konuk kaydını otel rezervasyon programında hatasız açar.","sektor":"Teknik yetkinlik tek başına yetmez ama gelecekte de gereklidir; diğer yetkinliklerle birlikte aranır.","iliskili":["mg-8-079","mg-8-016","mg-8-081"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-081","konu":"8.2","terim":"Kariyer varsayımı","ingilizce":"Career assumption","tanim":"Kişinin mesleki geleceğine dair başlangıçta kurduğu ve gelişim verileriyle sınadığı ön düşüncedir.","ornek":"Ece “Birkaç yıl sonra ön büro şefi olabilirim” varsayımını yazar, sonra güçlü ve gelişime açık yönlerine bakarak sınar.","sektor":"Varsayım, kişinin güçlü yönleriyle ve gelişime açık yönleriyle karşılaştırılarak değerlendirilir.","iliskili":["mg-8-082","mg-8-025","mg-8-029"],"kontrol":null,"cizim":"egitim-kariyer"},{"id":"mg-8-082","konu":"8.2","terim":"Gelişim örüntüsü","ingilizce":"Development pattern","tanim":"Kişinin bir yetkinlikte uyumlu mu yoksa geliştirilmesi gerekli mi olduğunu gösteren tablodaki işaretlemedir.","ornek":"Tabloda “iş birliği ve iletişim” yanına uyumlu, “zaman yönetimi” yanına geliştirilmeli yazılır.","sektor":"İşaretleme, kişisel eğilimle gelecekte aranan yetkinlik eşleştirildikten sonra yapılır; gelişime açık yönler buradan belirlenir.","iliskili":["mg-8-081","mg-8-025","mg-8-079"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-083","konu":"8.2","terim":"Zıt panel","ingilizce":"Opposing-panel discussion","tanim":"Sınıfın soru soranlar ve cevaplayanlar diye iki gruba ayrıldığı, görüşlerin gerekçeyle sorgulandığı tartışma etkinliğidir.","ornek":"Perşembe 4. ders: bir grup eylem planlarını anlatır, diğer grup bu planların uygulanabilirliğini sorgular.","sektor":"Etkinlikte görüşler açık, saygılı ve gerekçeli ifade edilir; tercihlerin olası sonuçları düşünülür.","iliskili":["mg-8-078","mg-8-074","mg-8-056"],"kontrol":null,"cizim":"toplanti-sunum"},{"id":"mg-8-010","konu":"8.3","terim":"Harmanlanmış öğrenme","ingilizce":"Blended learning","tanim":"Sınıfta yüz yüze yapılan dersle çevrim içi öğrenmenin planlı biçimde birlikte kullanıldığı öğrenme biçimidir.","ornek":"Hafta içi sınıfta masa düzeni uygulaması yapılır; hafta sonu öğrenciler evde konunun kısa videosunu izler ve çevrim içi testini çözer.","sektor":"Programın anahtar kavramlarındandır. Birçok otel yeni personel eğitimini böyle yürütür: kurallar ve ürün bilgisi çevrim içi derste, konuk karşılama uygulaması iş başında bir ustanın yanında öğrenilir.","iliskili":["mg-8-011","mg-8-004","mg-8-035"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-011","konu":"8.3","terim":"Ters yüz edilmiş sınıf","ingilizce":"Flipped classroom","tanim":"Konu anlatımının evde video ya da okuma ile öğrenildiği, sınıftaki zamanın ise uygulama, soru ve tartışmaya ayrıldığı öğrenme modelidir.","ornek":"Öğretmen pazartesi akşamı için “peçete katlama” videosunu gönderir; salı günü derste anlatım yapılmaz, herkes peçetesini katlar, öğretmen masaları dolaşıp düzeltir.","sektor":"Programın anahtar kavramlarındandır. Adı buradan gelir: alışılmış düzende ders okulda, alıştırma evdedir; burada yer değiştirirler. Derse hazırlıksız gelen öğrenci uygulamada geride kalır; sorumluluk öğrencidedir.","iliskili":["mg-8-010","mg-8-006","mg-8-025"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-012","konu":"8.3","terim":"Proje tabanlı öğrenme","ingilizce":"Project-based learning","tanim":"Öğrencilerin belli bir sürede araştırıp planlayarak ortaya somut bir ürün çıkardıkları ve konuyu bu çalışma sırasında öğrendikleri öğrenme biçimidir.","ornek":"Dört kişilik grup üç hafta çalışır ve kendi şehirleri için iki günlük bir gezi programı ile tanıtım broşürü hazırlayıp sınıfa sunar.","sektor":"Programın anahtar kavramlarındandır. İş hayatı projelerle yürür: bir açılış daveti, bir tur programı, yeni bir kahvaltı menüsü. Proje planlama, görev paylaşımı ve teslim tarihine uyma alışkanlığı kazandırır.","iliskili":["mg-8-013","mg-8-006","mg-8-059"],"kontrol":null},{"id":"mg-8-013","konu":"8.3","terim":"Probleme dayalı öğrenme","ingilizce":"Problem-based learning","tanim":"Öğrenmenin gerçek hayattan alınmış bir sorunla başladığı, öğrencilerin çözüm ararken gereken bilgiyi kendilerinin araştırıp bulduğu öğrenme biçimidir.","ornek":"Öğretmen sorar: “Otelde aynı odaya iki ayrı rezervasyon alınmış ve iki konuk da resepsiyonda. Ne yapılır?” Gruplar araştırır, çözüm önerilerini tartışır.","sektor":"Programın anahtar kavramlarındandır. Proje tabanlı öğrenmede hedef bir ürün ortaya koymaktır; burada hedef bir soruna çözüm bulmaktır. Otelde her gün önceden bilinmeyen bir sorun çıkar; çözüm aramaya alışkın olan çalışan paniğe kapılmaz.","iliskili":["mg-8-012","mg-8-006","mg-8-014"],"kontrol":null},{"id":"mg-8-014","konu":"8.3","terim":"Akran öğrenmesi","ingilizce":"Peer learning","tanim":"Aynı düzeydeki kişilerin birbirine anlatarak, soru sorarak ve birlikte çalışarak öğrenmesidir.","ornek":"Öğle arası, kantin: Mert oda tiplerini Zeynep’e anlatır, Zeynep de ona İngilizce karşılama cümlelerini çalıştırır; ikisi de anlatırken kendi eksiğini fark eder.","sektor":"Bir konuyu başkasına anlatmaya çalışmak onu ne kadar anladığını sana da gösterir. Otelde de yeni gelen stajyere çoğu zaman bir önceki dönemin stajyeri yol gösterir; anlatan kişi kendi bilgisini de pekiştirir.","iliskili":["mg-8-015","mg-8-060","mg-8-028"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-015","konu":"8.3","terim":"İş başında öğrenme","ingilizce":"On-the-job learning","tanim":"Bir işin, gerçek çalışma ortamında deneyimli bir çalışanın yanında izleyerek ve yaparak öğrenilmesidir.","ornek":"Staj, sabah 09.00: kat şefi yatağın nasıl yapılacağını bir kez gösterir, sonra stajyer yapar; şef izler ve köşeleri düzelttirir.","sektor":"Usta-çırak geleneğinin bugünkü hâlidir; staj bunun okuldaki karşılığıdır. İzle, dene, geri bildirim al, yeniden dene: mesleğin inceliği kitaptan çok ustanın yanında öğrenilir.","iliskili":["mg-8-014","mg-8-006","mg-8-031"],"kontrol":null},{"id":"mg-8-017","konu":"8.3","terim":"Bilgi","ingilizce":"Knowledge","tanim":"Kişinin bir konuda öğrendiği ve gerektiğinde hatırlayıp kullanabildiği olgular, kavramlar ve kurallardır.","ornek":"Otelin kahvaltı saatlerini, oda tiplerini ve çıkış saatini ezbere bilen stajyer konuğun sorusuna kimseye sormadan cevap verir.","sektor":"Yetkinliğin “Ne biliyorum?” sorusuna verilen cevabıdır. Konuk soru sorduğunda “Bilmiyorum” diyen çalışan güven kaybettirir; doğrusu “Hemen öğrenip size bilgi vereyim” demektir.","iliskili":["mg-8-016","mg-8-018","mg-8-019"],"kontrol":null,"gorsel":"m6-graz-kutuphane"},{"id":"mg-8-018","konu":"8.3","terim":"Beceri","ingilizce":"Skill","tanim":"Bir işi doğru, hızlı ve güvenli biçimde yapabilme gücüdür.","ornek":"Üç tabağı tek kolda taşımak, telefonda rezervasyon almak ya da yatağı birkaç dakikada kırışıksız yapmak birer beceridir.","sektor":"Yetkinliğin “Ne yapabiliyorum?” sorusuna verilen cevabıdır. Beceri okuyarak değil, provayla gelişir; bu yüzden uygulama dersi ve staj mesleğin kalbidir.","iliskili":["mg-8-016","mg-8-017","mg-8-031"],"kontrol":null},{"id":"mg-8-019","konu":"8.3","terim":"Tutum","ingilizce":"Attitude","tanim":"Kişinin bir işe, insana ya da duruma karşı takındığı ve davranışlarına yansıyan yaklaşımdır.","ornek":"Vardiyanın bitmesine beş dakika kala gelen konuğa “Mesaim bitti” demeyip yardımcı olan görevli işine karşı olumlu bir tutum gösterir.","sektor":"Yetkinliğin “Nasıl yaklaşıyorum?” sorusuna verilen cevabıdır. Bilgi ve beceri eğitimle kazandırılır; isteklilik, özen ve güler yüz ise kişinin kendi tutumudur. Konuk en çok bunu hatırlar.","iliskili":["mg-8-016","mg-8-017","mg-8-025"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-027","konu":"8.3","terim":"Aralıklı tekrar","ingilizce":"Spaced repetition","kitapDisi":true,"tanim":"Öğrenilen bilginin tek seferde uzun süre çalışılması yerine, araları giderek açılan kısa tekrarlarla pekiştirilmesidir.","ornek":"Bu uygulamada bildiğin kart bir gün sonra, yine bilirsen birkaç gün sonra, sonra daha uzun aralıkla yeniden gelir; bilemediğin kart başa döner.","sektor":"Sınavdan önceki gece yapılan uzun çalışma ertesi gün işe yarar ama çabuk unutulur. Meslekte bilgi sınav günü değil, aylar sonra bir konuk sorduğunda gerekir; kalıcı olması için tekrar zamana yayılır.","iliskili":["mg-8-028","mg-8-026","mg-8-036"],"kontrol":null},{"id":"mg-8-028","konu":"8.3","terim":"Kendini sınama","ingilizce":"Self-testing (retrieval practice)","kitapDisi":true,"tanim":"Kişinin, öğrendiği bilgiyi kaynağa bakmadan hatırlamaya çalışarak kendi kendini yoklamasıdır.","ornek":"Kartın ön yüzünde “check-in” yazar; arkasını çevirmeden önce tanımını kendi kendine söylersin, sonra çevirip kontrol edersin.","sektor":"Hatırlamaya çalışmak bilgiyi güçlendirir; ayrıca neyi bilmediğini gösterir. Resepsiyonda konuk karşındayken deftere bakamazsın: bilgi, bakmadan söyleyebildiğin zaman senindir.","iliskili":["mg-8-027","mg-8-026","mg-8-014"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-030","konu":"8.3","terim":"Zihin haritası","ingilizce":"Mind map","tanim":"Ana konunun ortaya yazıldığı, ilgili alt başlıkların ondan çıkan dallar hâlinde çizildiği görsel not biçimidir.","ornek":"Kâğıdın ortasına “Otel bölümleri” yazılır; ön büro, kat hizmetleri, yiyecek içecek birer dal olur; her dalın ucuna o bölümün görevleri eklenir.","sektor":"Bütünü tek sayfada gösterir ve kavramların birbirine nasıl bağlandığını ortaya koyar. Sınav öncesi konu tekrarında da bir etkinlik ya da tur planı çıkarırken de kullanılır.","iliskili":["mg-8-029","mg-8-026"],"kontrol":null,"cizim":"fikir-inovasyon"},{"id":"mg-8-031","konu":"8.3","terim":"Bilinçli alıştırma","ingilizce":"Deliberate practice","kitapDisi":true,"tanim":"Bir becerinin zayıf kalan kısmına odaklanarak, belli bir hedefle ve geri bildirim alarak yapılan tekrarlı çalışmadır.","ornek":"Servis provası, saat 14.00: Can çorba servisinde elinin titrediğini bilir. Bütün servisi baştan yapmak yerine yalnız o hareketi on kez tekrarlar; öğretmeni izler ve düzeltir.","sektor":"Bildiğini tekrar etmek rahattır ama geliştirmez; gelişme, zorlandığın noktayı çalışınca gelir. Usta personel bir hareketi alışkanlık olana kadar prova etmiştir; konuk yalnız akıcı sonucu görür.","iliskili":["mg-8-018","mg-8-015","mg-8-006"],"kontrol":null,"cizim":"grafik"},{"id":"mg-8-032","konu":"8.3","terim":"Öğrenme teknolojileri","ingilizce":"Learning technologies","tanim":"Öğrenmeyi desteklemek için kullanılan dijital araçların, uygulamaların ve platformların bütünüdür.","ornek":"Sınıftaki akıllı tahta, telefondaki kavram kartı uygulaması, ders videoları ve çevrim içi testler birer öğrenme teknolojisidir.","sektor":"Programın anahtar kavramlarındandır. Araç tek başına öğretmez: telefon aynı anda hem ders aracı hem dikkat dağıtıcıdır. Farkı onu hangi amaçla ve ne kadar planlı kullandığın yaratır.","iliskili":["mg-8-033","mg-8-034","mg-8-003"],"kontrol":null,"gorsel":"m6-braille-dizustu"},{"id":"mg-8-036","konu":"8.3","terim":"Mikro öğrenme","ingilizce":"Microlearning","kitapDisi":true,"tanim":"Bir konunun, her biri tek bir bilgi ya da beceriye odaklanan birkaç dakikalık küçük parçalar hâlinde öğrenilmesidir.","ornek":"Servis otobüsünde, okul yolunda: beş dakikada bu uygulamadan bir ders bitirirsin; ders yalnızca birkaç kavramdan oluşur.","sektor":"Otelde uzun eğitime zaman bulmak zordur; vardiya öncesi birkaç dakikalık kısa bilgilendirmeler bu yüzden yaygındır. Küçük parça kolay başlanır, kolay bitirilir; düzenli yapıldığında büyük bir birikime dönüşür.","iliskili":["mg-8-027","mg-8-035","mg-8-038"],"kontrol":null},{"id":"mg-8-037","konu":"8.3","terim":"Simülasyon","ingilizce":"Simulation","tanim":"Gerçek bir iş ortamının ya da durumun, hata yapmanın zarar vermeyeceği biçimde taklit edilerek üzerinde alıştırma yapılmasıdır.","ornek":"Uygulama dersinde sınıfın bir köşesi resepsiyon olur: bir öğrenci konuk, biri görevlidir; giriş işlemi baştan sona canlandırılır. Bilgisayarda deneme amaçlı kurulmuş bir rezervasyon ekranında kayıt açmak da simülasyondur.","sektor":"Pilotların uçuş simülatöründe çalışması en bilinen örneğidir. Otelcilikte de şikâyet karşılama ve yangın tatbikatı önce canlandırılır: hata gerçek konuğun önünde değil, provada yapılır ve düzeltilir.","iliskili":["mg-8-038","mg-8-031","mg-8-006"],"kontrol":null,"gorsel":"m6-ucus-simulatoru"},{"id":"mg-8-038","konu":"8.3","terim":"Oyunlaştırma","ingilizce":"Gamification","kitapDisi":true,"tanim":"Puan, seviye, rozet ve sıralama gibi oyun ögelerinin, oyun olmayan bir işi daha çekici kılmak için kullanılmasıdır.","ornek":"Bu uygulamada ders bitirdikçe puan toplarsın, Stajyer basamağından başlayıp otel kariyeri basamaklarında yükselirsin.","sektor":"Oyunlaştırma başlamayı ve sürdürmeyi kolaylaştırır; ama puan araçtır, amaç öğrenmektir. Yalnız puan için tıklayan kişi bilgiyi değil, puanı kazanır.","iliskili":["mg-8-042","mg-8-043","mg-8-036"],"kontrol":null},{"id":"mg-8-053","konu":"8.3","terim":"Öğrenme ihtiyacı","ingilizce":"Learning need","tanim":"Mesleki hedefe ulaşmak için kişinin edinmesi gereken bilgi, beceri ve tutumlardır.","ornek":"Hedef: yazın yabancı konukların geldiği bir otelin resepsiyonunda staj. Bugünkü durum: İngilizce selamlaşabiliyor ama telefonda konuşamıyor. İhtiyaç: telefonda İngilizce görüşme.","sektor":"Plan ihtiyaçtan doğar, hevesten değil. İhtiyacını doğru belirlemek için öz değerlendirme yap, öğretmeninin ve staj amirinin geri bildirimine, sektörün aradığı yetkinliklere bak.","iliskili":["mg-8-054","mg-8-023","mg-8-055"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-054","konu":"8.3","terim":"Öğrenme hedefi","ingilizce":"Learning goal","tanim":"Kişinin belli bir süre sonunda neyi bilmek ya da neyi yapabilmek istediğini açıkça söyleyen ifadedir.","ornek":"“Mayıs sonuna kadar telefonda İngilizce oda rezervasyonu alma konuşmasını deftere bakmadan yapabileceğim.”","sektor":"İyi öğrenme hedefi 1. ünitede öğrendiğin SMART ölçütlerine uyar: belirli, ölçülebilir, ulaşılabilir, gerçekçi ve zamana bağlıdır. SMART hedefler programın bu ünitedeki anahtar kavramlarındandır. “İngilizcemi geliştireceğim” bir dilektir; ne zamana kadar neyi yapabileceğini söylemez.","iliskili":["mg-8-053","mg-8-055","mg-8-056"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-055","konu":"8.3","terim":"Öğrenme rotası","ingilizce":"Learning pathway","tanim":"Kişinin öğrenme hedefine ulaşmak için hangi adımları, hangi sırayla, hangi yöntem ve araçlarla, ne kadar sürede atacağını gösteren kişiye özel yol planıdır.","ornek":"Hedef: telefonda İngilizce rezervasyon almak. Rota: ilk iki hafta kalıp cümle kartları, üçüncü hafta arkadaşla canlandırma, dördüncü hafta öğretmenle deneme görüşmesi; her gün 20 dakika.","sektor":"Dört şeyi birleştirir: hedef, yöntem, dijital araç ve zaman planı. Navigasyon gibidir: varış noktası aynı kalır, yol kapanırsa rota yeniden çizilir. Başkasının rotası sana uymayabilir; rota kişiye özeldir.","iliskili":["mg-8-054","mg-8-056","mg-8-052"],"kontrol":null,"cizim":"harita-rota"},{"id":"mg-8-059","konu":"8.3","terim":"Portfolyo","ingilizce":"Portfolio","tanim":"Kişinin zaman içinde yaptığı çalışmalardan seçtiği örnekleri, belgelerini ve gelişimini gösteren düzenli dosyadır.","ornek":"Dört yılın sonunda dosyada: hazırladığın tur programı, kurduğun masanın fotoğrafı, staj değerlendirme formların ve kurs belgelerin vardır.","sektor":"İş görüşmesinde “Yapabilirim” demek ile yaptığını gösterebilmek arasındaki farktır. Portfolyo son gün hazırlanmaz; 9. sınıftan başlayarak her iyi çalışma dosyaya eklenir.","iliskili":["mg-8-057","mg-8-012","mg-8-056"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-060","konu":"8.3","terim":"Akran değerlendirmesi","ingilizce":"Peer assessment","tanim":"Öğrencilerin birbirlerinin çalışmasını belirlenmiş ölçütlere göre inceleyip yapıcı geri bildirim vermesidir.","ornek":"İki arkadaş öğrenme rotalarını değiş tokuş eder. Biri ötekine şöyle der: “Hedefin açık, bu çok iyi. Ama staj günlerine de bir saat yazmışsın; o günler için süreyi kısaltmayı düşünebilirsin.”","sektor":"Amaç not vermek ya da kusur aramak değildir: önce iyi olanı söyle, sonra somut bir öneri getir, kişiyi değil çalışmayı konuş. Geri bildirimi kırmadan verebilmek ve dinleyebilmek ekip çalışmasının temelidir.","iliskili":["mg-8-014","mg-8-058","mg-8-055"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-084","konu":"8.3","terim":"Teknolojik yenilik","ingilizce":"Technological innovation","tanim":"Bir meslek alanında iş yapış biçimini değiştiren yeni bir araç, yazılım ya da yöntemdir.","ornek":"Otellerde dijital oda anahtarı yaygınlaşınca, ön büro görevlisinin kart basma işi azalır, konuk yönlendirme işi artar.","sektor":"Yeniliği incelerken yalnız adı öğrenilmez: hangi işlerde kullanıldığı, hangi becerileri beklediği ve iş süreçlerini nasıl değiştirdiği araştırılır.","iliskili":["mg-8-085","mg-8-086","mg-8-087"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-085","konu":"8.3","terim":"Bireysel gelişim ihtiyacı","ingilizce":"Individual development need","tanim":"Kişinin mevcut yetkinlikleri ile ulaşmak istediği hedefin gerektirdiği yetkinlikler arasındaki farktır.","ornek":"Hedef: otel rezervasyon programını kullanmak. Program daha önce hiç kullanılmadıysa temel özellikleri öğrenmek bir gelişim ihtiyacıdır.","sektor":"Programı temel düzeyde bilen ama karmaşık işlemleri yapamayan kişi için ileri uygulama becerisi de bir gelişim ihtiyacıdır.","iliskili":["mg-8-086","mg-8-087","mg-8-084"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-086","konu":"8.3","terim":"Mesleki hedef","ingilizce":"Professional goal","tanim":"Kişinin gelecekte ulaşmak istediği çalışma ya da yetkinlik düzeyidir.","ornek":"Öğrenci, iki yıl içinde yabancı konuklara İngilizce hizmet verebilen ön büro görevlisi olmayı hedefler.","sektor":"Mesleki hedef, öğrenme ihtiyacının belirlenmesinde ilk adımdır; hedef belli olmazsa neyin öğrenileceği de belli olmaz.","iliskili":["mg-8-085","mg-8-087","mg-8-054"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-087","konu":"8.3","terim":"Hedef-ihtiyaç ilişkisi","ingilizce":"Goal-need relationship","tanim":"Mesleki alandaki bir değişimin yeni bir yetkinlik ihtiyacı doğurması, bunun öğrenme hedefine ve planlı çalışmaya dönüşerek mesleki gelişim sağlamasıdır.","ornek":"Otelde yeni bir sistem gelir, yeni yetkinlik gerekir, çalışan öğrenme hedefi koyar, çalışma planlar ve gelişir.","sektor":"Zincir şöyle işler: değişim, ihtiyaç, hedef, plan, gelişim.","iliskili":["mg-8-084","mg-8-085","mg-8-086"],"kontrol":null,"cizim":"hedef-basari"},{"id":"mg-8-088","konu":"8.3","terim":"Feynman tekniği","ingilizce":"Feynman Technique","tanim":"Bir konuyu alanı bilmeyen birine anlatıyormuş gibi sade bir dille açıklayıp, zorlanılan yerleri yeniden çalışarak öğrenme tekniğidir.","ornek":"Akşam 20.00: öğrenci “check-in nedir?” konusunu annesine sade cümlelerle anlatır, tıkandığı yeri tekrar çalışıp yeniden anlatır.","sektor":"Açıklamakta zorlanılan bölümler öğrenme eksiklerini gösterir.","iliskili":["mg-8-089","mg-8-008","mg-8-028"],"kontrol":null,"cizim":"kitap-ogrenme"},{"id":"mg-8-089","konu":"8.3","terim":"Uygulama ve geri bildirim","ingilizce":"Practice and feedback","tanim":"Bilgiyi uygulayıp ortaya çıkan çalışmayı inceleyerek öğretmenden, uzmandan ya da akranından dönüt alarak gelişmektir.","ornek":"Cuma 14.00, atölye: öğrenci yatak yapma işlemini yapar, öğretmeni hatasını gösterir, öğrenci yeniden dener.","sektor":"Mesleki yetkinlik yalnız bilgi edinmekle gelişmez; uygulama ve dönüt gerekir.","iliskili":["mg-8-088","mg-8-018","mg-8-065"],"kontrol":null,"cizim":"konusma"},{"id":"mg-8-090","konu":"8.3","terim":"Dijital not uygulaması","ingilizce":"Digital note-taking app","tanim":"Notların telefonda ya da bilgisayarda yazılıp düzenlendiği ve kolay aranabildiği uygulamadır.","ornek":"Pazartesi 12.00: öğrenci dersteki kavramları telefonundaki not uygulamasına başlıklarla kaydeder.","sektor":"Öğrenme rotası için seçilebilecek dijital araçlardan biridir.","iliskili":["mg-8-091","mg-8-009","mg-8-029"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-091","konu":"8.3","terim":"E-kitap","ingilizce":"E-book","tanim":"Telefon, tablet ya da bilgisayarda okunabilen dijital kitaptır.","ornek":"Otobüste öğrenci ders kitabının e-kitap sürümünü telefonda açıp okur.","sektor":"Öğrenme rotası için seçilebilecek dijital araçlardan biridir; kaynağın güvenilir olması gerekir.","iliskili":["mg-8-090","mg-8-067","mg-8-092"],"kontrol":null,"cizim":"su-tasarrufu"},{"id":"mg-8-092","konu":"8.3","terim":"Dijital kaynakta etik kullanım","ingilizce":"Ethical use of digital sources","tanim":"Bilginin kaynağını belirtmeyi, başkasının çalışmasını kendi işi gibi sunmamayı ve doğruluğunu kontrol etmeyi içeren davranış ilkesidir.","ornek":"Öğrenci bulduğu yazıyı sunuma eklerken kaynağını yazar ve kendi cümleleriyle özetler.","sektor":"Seçilen dijital kaynak güvenilirlik, doğruluk ve etik kullanım açısından değerlendirilir.","iliskili":["mg-8-091","mg-8-067","mg-8-039"],"kontrol":null,"cizim":"dijital"},{"id":"mg-8-093","konu":"8.3","terim":"Performans görevi","ingilizce":"Performance task","tanim":"Öğrencinin öğrendiklerini gerçek bir ürün ortaya koyarak göstermesini isteyen ve ölçütlerle değerlendirilen uzun görevdir.","ornek":"Grup, “Mesleki Geleceğim İçin Kişisel Öğrenme Rotam” adlı görevi birlikte hazırlar.","sektor":"Görev, öz ve akran değerlendirme formlarıyla tamamlanır.","iliskili":["mg-8-094","mg-8-059","mg-8-060"],"kontrol":null,"cizim":"tarihi-yapi"},{"id":"mg-8-094","konu":"8.3","terim":"Analitik dereceli puanlama anahtarı","ingilizce":"Analytic rubric","tanim":"Bir çalışmanın her ölçütünün ayrı ayrı ve derece derece puanlandığı değerlendirme aracıdır.","ornek":"Öğretmen rotanın hedef, yöntem ve zaman planı bölümlerini ayrı puanlarla değerlendirir.","sektor":"Öğrenci anahtara önceden bakarsa neyin beklendiğini bilir.","iliskili":["mg-8-093","mg-8-060","mg-8-059"],"kontrol":null,"cizim":"kalite-yildiz"}],"sorular":[{"id":"mg-8-s01","tur":"coktan-secmeli","soru":"İki sınıf aynı konuyu işliyor: birinde öğretmen anlatıp öğrenciler not alıyor, ötekinde öğrenciler araştırıp bir otelin giriş işlemini kendileri çıkarıyor. İkinci sınıf hangi yaklaşımı yansıtır?","secenekler":["Geleneksel öğrenme yaklaşımı","Mikro öğrenme","Yenilikçi öğrenme yaklaşımı","Kişiselleştirilmiş öğrenme"],"dogru":2,"aciklama":"Öğrencinin araştırıp uygulayarak etkin rol aldığı, öğretmenin yol gösterdiği düzen yenilikçi yaklaşımdır. Geleneksel yaklaşımda bilgiyi öğretmen anlatır; kişiselleştirilmiş öğrenmede ise herkes aynı işi yapmaz, yol öğrencinin ihtiyacına göre ayarlanır."},{"id":"mg-8-s02","tur":"coktan-secmeli","soru":"Salı günü derste peçete katlama anlatılmıyor; anlatım önceki akşam videoyla izlenmiş, ders saati uygulamaya ve sorulara ayrılmış. Bu model hangisidir?","secenekler":["Ters yüz edilmiş sınıf","Akran öğrenmesi","Mikro öğrenme","Probleme dayalı öğrenme"],"dogru":0,"aciklama":"Konu anlatımı evde, uygulama ve tartışma sınıfta yapılıyorsa model ters yüz edilmiş sınıftır. Akran öğrenmesinde öğrenciler birbirine anlatır; probleme dayalı öğrenme ise gerçek bir sorunla başlar."},{"id":"mg-8-s03","tur":"coktan-secmeli","soru":"Yüz yüze dersle çevrim içi öğrenmenin planlı biçimde bir arada kullanılmasına ne denir?","secenekler":["Çevrim içi kurs","Dijital kaynak","Mikro öğrenme","Harmanlanmış öğrenme"],"dogru":3,"aciklama":"Harmanlanmış öğrenme, sınıftaki ders ile çevrim içi öğrenmeyi bir plana göre birleştirir. Çevrim içi kurs yalnız internet üzerinden izlenir; mikro öğrenme ise süreyle ilgilidir, ortamla değil."},{"id":"mg-8-s04","tur":"coktan-secmeli","soru":"Öğretmen “Otelde aynı odaya iki ayrı rezervasyon alınmış, iki konuk da resepsiyonda; ne yapılır?” sorusunu veriyor. Gruplar çözümü araştırıp tartışıyor. Bu çalışma hangi öğrenme biçimine girer?","secenekler":["Proje tabanlı öğrenme","Probleme dayalı öğrenme","Akran öğrenmesi","İş başında öğrenme"],"dogru":1,"aciklama":"Öğrenme gerçek hayattan bir sorunla başlıyor ve bilgiyi öğrenciler kendileri araştırıyor; bu, probleme dayalı öğrenmedir. Proje tabanlı öğrenmede amaç belli bir sürede somut bir ürün (broşür, program) ortaya koymaktır."},{"id":"mg-8-s05","tur":"coktan-secmeli","soru":"Aşağıdakilerden hangisi yaşam boyu öğrenmeye örnektir?","secenekler":["Öğrencinin sınavdan önceki gece sabaha kadar çalışması","Garsonun staj sonunda belgesini dosyasına koyması","Resepsiyon şefinin otel yeni programa geçince eğitime katılması","Stajyerin kat şefinin gösterdiği yatak düzenini bir kez yapması"],"dogru":2,"aciklama":"Yaşam boyu öğrenme, okul bitse de bilgi ve becerileri hayat boyu yenilemeyi sürdürmektir; yıllardır çalışan şefin yeni sisteme geçerken öğrenmesi bunu gösterir. Yatak yapmayı iş başında öğrenmek bir yöntemdir ama süregelen yenilenmeyi anlatmaz."},{"id":"mg-8-s06","tur":"coktan-secmeli","soru":"Resepsiyon görevlisi oda tiplerini iyi biliyor, giriş işlemini hatasız yapıyor; ancak yorgun gelen konuğa soğuk davranıyor. Bu görevli için hangisi söylenebilir?","secenekler":["Bilgisi ve becerisi yeterli, tutumu gelişime açık","Bilgisi ve tutumu yeterli, becerisi gelişime açık","Becerisi ve tutumu yeterli, bilgisi gelişime açık","Tutumu ve becerisi gelişime açık, bilgisi yeterli"],"dogru":0,"aciklama":"Oda tiplerini bilmek bilgi, girişi hatasız yapmak beceri, konuğa yaklaşım ise tutumdur; eksik olan tutumdur. Mesleki yetkinlik bu üçünün bir arada bulunmasıdır."},{"id":"mg-8-s07","tur":"coktan-secmeli","soru":"Yıllardır serviste çalışan garson kahve eğitimi alıp aynı işi daha üst düzeyde yapıyor. Santral görevlisi ise sosyal medya eğitimi alıp otelin hesaplarını yönetmeye geçiyor. Bu iki durum nasıl adlandırılır?","secenekler":["İkisi de beceri geliştirme","İkisi de yeniden beceri kazanma","Garson yeniden beceri kazanma, santral görevlisi beceri geliştirme","Garson beceri geliştirme, santral görevlisi yeniden beceri kazanma"],"dogru":3,"aciklama":"Aynı işi daha iyi yapmak için mevcut becerileri ilerletmek beceri geliştirmedir; farklı bir görev için kendinde olmayan yeni bir alan öğrenmek yeniden beceri kazanmadır. Bu yüzden iki durumun adı farklıdır."},{"id":"mg-8-s08","tur":"coktan-secmeli","soru":"Deniz pazar akşamı haftalık çalışma planını yapıyor, çarşamba günü geride kaldığını fark ediyor, perşembe günü planını yeniden düzenliyor. Deniz’in kullandığı beceri hangisidir?","secenekler":["Öz disiplin","Öz düzenleme","Önceliklendirme","Yansıtma"],"dogru":1,"aciklama":"Planlama, çalışırken kendini izleme ve gerekirse yöntemi değiştirme öz düzenlemedir. Öz disiplin, canı istemese de plana uymaktır; Deniz ise planın işlemediğini görüp planı değiştirmiştir."},{"id":"mg-8-s09","tur":"coktan-secmeli","soru":"Uygulamadaki Tekrar bölümünde bildiğin kart bir gün sonra, yine bilirsen birkaç gün sonra, daha da sonra yeniden gelir. Bu sistem aralıklı tekrarın hangi özelliğine dayanır?","secenekler":["Her kartı her gün aynı sıklıkla çalıştırmaya","Konuyu sınavdan önceki akşam art arda tekrar ettirmeye","Bilinen kartları bilinmeyenlerle aynı sayıda göstermeye","Bilinen kartların tekrar aralığını giderek açmaya"],"dogru":3,"aciklama":"Aralıklı tekrarda bilgi pekiştikçe tekrarların arası açılır, bilinmeyen kart ise başa döner; bu sayede çalışma zamanı zor kartlara kalır. Art arda yoğun tekrar bu yöntem değildir."},{"id":"mg-8-s10","tur":"coktan-secmeli","soru":"Ayşe, “check-in” kartının arka yüzünü çevirmeden önce tanımı kendi sözleriyle söylüyor, sonra çevirip kontrol ediyor. Hangi stratejiyi uyguluyor?","secenekler":["Kendini sınama","Zihin haritası","Dijital not uygulaması","Öğrenme günlüğü"],"dogru":0,"aciklama":"Bilgiyi kaynağa bakmadan hatırlamaya çalışıp sonra kontrol etmek kendini sınamadır. Zihin haritası ana konudan çıkan dalları çizmektir; öğrenme günlüğü ise yaşananları yazılı kayda geçirir."},{"id":"mg-8-s11","tur":"coktan-secmeli","soru":"Öğretmen ödevi çevrim içi bir platforma yüklüyor; öğrenci evden girip videoyu izliyor, testi çözüyor, ödevini gönderiyor. Öğretmen kimin hangi konuyu tamamladığını da ekranda görüyor. Bu platform hangisidir?","secenekler":["E-kitap","Dijital not uygulaması","Öğrenme yönetim sistemi","Etkileşimli materyal"],"dogru":2,"aciklama":"Dersleri, ödevleri ve sınavları sunan, öğrencinin ilerlemesini de kaydeden yazılım öğrenme yönetim sistemidir. E-kitap yalnız okunan dijital bir kitaptır; ödev, sınav ve ilerleme takibi yapan bir platform değildir."},{"id":"mg-8-s12","tur":"coktan-secmeli","soru":"Bir öğrenci kursu hafta sonu tek seferde izlemek yerine, her biri tek bir beceriyi anlatan beş dakikalık videolara bölüp günde birini izliyor. Bu öğrenme biçimi hangisidir?","secenekler":["Harmanlanmış öğrenme","Mikro öğrenme","Simülasyon","Ters yüz edilmiş sınıf"],"dogru":1,"aciklama":"Konunun, her biri tek bir bilgi ya da beceriye odaklanan kısa parçalarla öğrenilmesi mikro öğrenmedir. Harmanlanmış öğrenme ise ortamların (sınıf ve çevrim içi) birleşimidir."},{"id":"mg-8-s13","tur":"coktan-secmeli","soru":"Sınıfın bir köşesi resepsiyona çevriliyor; bir öğrenci konuk, biri görevli olup giriş işlemini baştan sona oynuyor. Gerçek konuk olmadığı için hata kimseye zarar vermiyor. Bu etkinlik hangisidir?","secenekler":["Simülasyon","İş başında öğrenme","Akran değerlendirmesi","Çevrim içi kurs"],"dogru":0,"aciklama":"Gerçek bir iş durumunun hata yapmanın zarar vermeyeceği biçimde taklit edilmesi simülasyondur. İş başında öğrenme ise gerçek çalışma ortamında, deneyimli bir çalışanın yanında olur."},{"id":"mg-8-s14","tur":"coktan-secmeli","soru":"Dört öğrenci İngilizce çalışıyor. Hangisinin motivasyonu içseldir?","secenekler":["Sınavdan düşük not alıp yeniden sınava girmemek için çalışan Ece","Ailesi ödül vereceği için ödevini bitiren Can","Ayın personeli seçilmek için fazla çalışan Mert","Konuklarla rahat konuşmayı sevdiği için video izleyip prova yapan Sena"],"dogru":3,"aciklama":"İçsel motivasyonda kişi işi merakı ya da kendisi için anlamlı bulduğu için yapar. Not, ödül ve unvan dışarıdan gelen sonuçlardır; bunlar dışsal motivasyondur."},{"id":"mg-8-s15","tur":"coktan-secmeli","soru":"Eisenhower matrisine göre “acil görünür ama önemli değil” kutusuna hangisi girer?","secenekler":["Yarın teslim edilecek ödevi bitirmek","Sürekli gelen grup mesajlarına cevap vermek","Gelecek ayki sınava hazırlanmak","Amaçsız video kaydırmak"],"dogru":1,"aciklama":"Sürekli gelen grup mesajları hemen cevap istiyormuş gibi görünür ama hedefe katkısı azdır; kısa tutulur. Gelecek ayki sınav önemlidir ama acil değildir; takvime yazılır."},{"id":"mg-8-s16","tur":"coktan-secmeli","soru":"Pomodoro tekniğini uygularken hangisi yanlıştır?","secenekler":["Sayacı kurup bir bölüm boyunca yalnız tek işe odaklanarak çalışmak","Bölüm bitince kalkıp su içmek gibi kısa bir mola vermek","Sayaç çalınca molayı atlayıp aynı hızla çalışmaya devam etmek","Birkaç bölümden sonra daha uzun bir mola vermeyi planlamak"],"dogru":2,"aciklama":"Pomodoro tekniği, kesintisiz odaklanılan kısa bölümleri kısa molalarla ayırır; molayı atlayıp çalışmaya devam etmek tekniğin dayandığı düzeni bozar. Birkaç bölümden sonra uzun mola vermek ise tekniğin parçasıdır."},{"id":"mg-8-s17","tur":"coktan-secmeli","soru":"Hedef: telefonda İngilizce oda rezervasyonu almak. “İlk iki hafta kalıp cümle kartları, üçüncü hafta arkadaşla canlandırma, dördüncü hafta öğretmenle deneme görüşmesi; her gün 20 dakika.” Bu ifade neyi gösterir?","secenekler":["Öğrenme rotasını","Öğrenme ihtiyacını","Öğrenme hedefini","Öğrenme performansını"],"dogru":0,"aciklama":"Hedefe hangi adımlarla, hangi yöntem, araç ve sürede ulaşılacağını gösteren plan öğrenme rotasıdır. Hedef ulaşılmak istenen sonucu söyler, ihtiyaç ise bugünkü durumla hedef arasındaki eksiği."},{"id":"mg-8-s18","tur":"dogru-yanlis","soru":"Yenilikçi öğrenme yaklaşımında öğretmenin rolü ortadan kalkar; öğrenci süreci tek başına yürütür.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Yenilikçi yaklaşımda öğrenci etkin rol alır, ancak öğretmen yol gösterici olarak sürecin içinde kalır."},{"id":"mg-8-s19","tur":"dogru-yanlis","soru":"Kişiselleştirilmiş öğrenmede aynı sınıftaki iki öğrencinin çalışma yolu ve hızı birbirinden farklı olabilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. Kişiselleştirilmiş öğrenmede hız, içerik ve yol öğrencinin ihtiyacına, düzeyine ve hedefine göre ayarlanır."},{"id":"mg-8-s20","tur":"dogru-yanlis","soru":"Öz disiplin ile öz düzenleme aynı şeydir; ikisi de yalnızca plana uymak demektir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yanlış. Öz disiplin, canı istemese de plana uymayı sürdürmektir; öz düzenleme ise planlamayı, kendini izlemeyi ve gerekirse yöntemi değiştirmeyi kapsar."},{"id":"mg-8-s21","tur":"dogru-yanlis","soru":"Yapay zekâ aracı çok emin bir dille cevap verse bile bilgi, güvenilir bir kaynakla doğrulanmadan ödevde kullanılmamalıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Doğru. Cevabın emin bir dille yazılması doğru olduğunu göstermez; bilginin kimden geldiği ve neye dayandığı kontrol edilmelidir."},{"id":"mg-8-s22","tur":"senaryo","durum":"Bugün pazartesi. Cuma günü İngilizce dersinde resepsiyonda kullanılan 20 kalıp cümleden sözlü sınav olacaksın. Akşam 19.00’da masandasın ve haftayı nasıl kullanacağını düşünüyorsun.","soru":"Hangisi en doğru çalışma biçimidir?","secenekler":["Her akşam yirmi cümleyi baştan sona sessizce okuyup geçerim.","Perşembe akşamı bütün cümleleri üst üste birkaç kez okuyarak çalışırım.","Önce kolay on cümleyi bitirir, zor olanları perşembe akşamına bırakırım.","Her akşam kısa çalışır, cümleleri bakmadan söyler, bilemediklerimi tekrarlarım."],"dogru":3,"aciklama":"Tekrarı günlere yaymak (aralıklı tekrar) ve bakmadan söylemek (kendini sınama) bilgiyi kalıcı kılar. Yalnız okumak kendini sınamak değildir; zor cümleleri en sona bırakmak ise asıl çalışılması gereken yeri ertelemektir."},{"id":"mg-8-s23","tur":"senaryo","durum":"Ön büroda stajdasın. Otel gelecek ay yeni bir rezervasyon programına geçecek; şefin, personel için açılan çevrim içi kursun bağlantısını sana da gönderiyor. Kurs birkaç saatlik videodan oluşuyor.","soru":"Ne yaparsın?","secenekler":["Kursu planıma bölüp bitirir, takıldığım yeri şefime sorarım.","Stajyer olduğum için kurs bana değil, kadrolu personele aittir; açmam.","Programa geçildiğinde işin içinde öğrenirim, o güne kadar beklerim.","Bütün videoları son gün hızlandırıp tek oturuşta izlemeyi düşünürüm."],"dogru":0,"aciklama":"Kursu önceden ve parça parça bitirmek, yeni sisteme hazır girmeni sağlar; anlamadığını sormak da öğrenmeyi tamamlar. Yeni sistem gelmeden hazırlanmayı ertelemek ya da tek oturuşta hızlıca izlemek bilgiyi kalıcı kılmaz."},{"id":"mg-8-s24","tur":"senaryo","durum":"Performans görevin için bir yapay zekâ aracına bir ülkenin vize kurallarını sordun. Araç çok emin bir dille, madde madde cevap verdi. Görevi yarın sabah sınıfta sunacaksın.","soru":"İlk adımın ne olur?","secenekler":["Bilgiyi sunuma koyar, kaynak olarak aracın adını yazarım.","Aynı soruyu başka bir yapay zekâ aracına da sorar, ikisi aynıysa doğru kabul ederim.","Bilgiyi ilgili ülkenin resmî kurumunun sitesinden kontrol eder, farklıysa resmî kaynağı kullanırım.","Cevabı kendi cümlelerimle yeniden yazar, kaynağı belirtmeden sunarım."],"dogru":2,"aciklama":"Yapay zekâ yanlış bilgiyi de emin bir dille verebilir; bilgi, kim tarafından ve neye dayanarak verildiği belli bir güvenilir kaynakla doğrulanmalıdır. İki aracın aynı şeyi söylemesi doğruluk kanıtı değildir, kaynağı gizlemek de etik kullanıma aykırıdır."},{"id":"mg-8-s25","tur":"senaryo","durum":"Kişisel öğrenme planı görevinin teslimine iki hafta var. Her akşam “Yarın başlarım” diyorsun; iş gözünde büyüyor. Bu akşam saat 20.00, masandasın ama telefonuna sürekli bildirim geliyor.","soru":"Ne yaparsın?","secenekler":["Çalışma isteğim gelene kadar beklerim, istek gelince hemen başlarım.","Telefonu başka odaya bırakır, sayaç kurup ilk küçük parçayı yazarım.","Görevi hafta sonuna bırakır, o gün tamamını bir oturuşta yazarım.","Telefonu masada tutar, bildirimlere hemen bakıp sonra işe dönerim."],"dogru":1,"aciklama":"Ertelemeyi kırmanın yolu işi küçük parçaya bölmek, süre tutmak ve dikkat dağıtıcıyı uzaklaştırmaktır. İstek beklemek ya da görevi son güne bırakmak ertelemeyi sürdürür; bildirime bakıp dönmek dikkati her seferinde böler."},{"id":"mg-8-s26","tur":"senaryo","durum":"Çarşamba akşamı, saat 18.30. Önünde dört iş var: yarın sabah teslim edilecek ödev, üç hafta sonraki sınav için kart tekrarı, sınıf grubunda süren mesajlaşma ve dün yarım kalan bir dizi bölümü.","soru":"İşleri hangi sırayla ele alırsın?","secenekler":["Önce grup mesajlarına cevap veririm; bildirimler bitmeden derse oturamam.","Önce kart tekrarını bitiririm; ödeve kalan zamanda bakarım.","Önce dizinin bölümünü izlerim; kafam rahatlayınca ödeve otururum.","Önce ödevi bitirir, sonra kısa kart tekrarı yapar, mesajlara ve diziye sonra bakarım."],"dogru":3,"aciklama":"Yarın teslim edilecek ödev hem acil hem önemlidir, önce o yapılır. Üç hafta sonraki sınav önemlidir ama acil değildir; ödevden sonra kısa bir tekrar yeter. Mesajlar acil görünür ama önemli değildir."},{"id":"mg-8-s27","tur":"senaryo","durum":"Servis provasında, saat 14.00. Şefin seni izliyor ve “Tabağı konuğun yanlış tarafından koyuyorsun, bileğin de çok gergin” diyor. Arkadaşlarının önünde düzeltildiğin için canın sıkılıyor.","soru":"Nasıl davranırsın?","secenekler":["Zaten iyi yaptığım bardak dizilişine geçip o konuda kendimi gösteririm.","Teşekkür eder, tabağı doğru tarafa koyup bileğimi gevşeterek tekrarlar, şefin yeniden izlemesini isterim.","Geçen hafta bana farklı gösterildiğini söyler, hangisinin doğru olduğunu o anda tartışırım.","Bir şey demem; sonraki provada servis sırasını başka bir arkadaşıma bırakırım."],"dogru":1,"aciklama":"Geri bildirim, uygulamayı düzeltip yeniden denemek için fırsattır; hatalı hareketi tekrar edip izletmek gelişmeyi hızlandırır. Konuyu değiştirmek, tartışmak ya da geri çekilmek eksik yönü olduğu gibi bırakır."},{"id":"mg-8-s28","tur":"senaryo","durum":"Derste öğrenme rotaları değiş tokuş edildi. Arkadaşının planında “Her gün dört saat İngilizce” yazıyor; oysa haftanın üç günü stajda olduğunu biliyorsun. Öğretmen birbirinize geri bildirim vermenizi istiyor.","soru":"Hangisi doğru davranıştır?","secenekler":["Planın güçlü yanını söyler, staj günleri için süreyi kısaltmasını öneririm.","Planın çalışmayacağını açıkça söyler, baştan yapmasını isterim.","Kırılmasın diye iyi yanlarını anlatır, süre konusunu hiç açmam.","Plana bir şey yazmam; hatayı öğretmenin bulmasını beklerim."],"dogru":0,"aciklama":"Yapıcı akran geri bildirimi önce iyi yanı söyler, sonra somut bir öneri getirir ve kişiyi değil çalışmayı konuşur. Sadece övmek ya da sert eleştirmek arkadaşını geliştirmez; sessiz kalmak ise planın ilk yoğun haftada bozulmasına yol açar."},{"id":"mg-8-s29","tur":"coktan-secmeli","soru":"Kahvaltı servisi dersinde hangi öğrencinin davranışı aktif öğrenmeye örnektir?","secenekler":["Slaytları dikkatle izleyip hiç soru sormayan Ali","Masayı kendisi kurup arkadaşına servis yapan Ece","Öğretmenin anlattıklarını deftere aynen yazan Can","Ders videosunu evde iki kez baştan izleyen Mert"],"dogru":1,"aciklama":"Aktif öğrenmede öğrenci yalnız dinlemez; uygulayarak ve üreterek sürece katılır. Videoyu iki kez izlemek de hâlâ yalnız izlemektir."},{"id":"mg-8-s30","tur":"coktan-secmeli","soru":"Elif, İngilizce kalıp cümleleri sessizce okuyunca unuttuğunu, sesli söyleyip canlandırınca hatırladığını fark ediyor ve çalışma biçimini buna göre değiştiriyor. Bu durum hangi kavramla açıklanır?","secenekler":["Aralıklı tekrar","Akran öğrenmesi","Bilinçli alıştırma","Öğrenmeyi öğrenme"],"dogru":3,"aciklama":"Elif, nasıl daha iyi öğrendiğini fark edip öğrenmesini buna göre yönetiyor. Aralıklı tekrar ise tekrarların zamana yayılmasıdır; Elif’in fark ettiği şey tekrar aralığı değil, yöntemdir."},{"id":"mg-8-s31","tur":"dogru-yanlis","soru":"Etkili not almada dinlenen her cümle kelimesi kelimesine deftere yazılır.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Not almak söyleneni aynen yazmak değil, önemli noktaları kişinin kendi kısa cümleleriyle yazmasıdır."},{"id":"mg-8-s32","tur":"coktan-secmeli","soru":"Staj dönüşü servis otobüsünde bir öğrenci şöyle düşünüyor: “Bugün konuğun sorusunu anlamayınca panikledim. Yarın anlamadığımda kibarca tekrar etmesini isteyeceğim.” Öğrencinin yaptığı hangisidir?","secenekler":["Yansıtma","Kendini sınama","Önceliklendirme","Not alma"],"dogru":0,"aciklama":"Öğrenci yaşadığı deneyimi durup düşünüyor ve bir dahaki sefere neyi farklı yapacağına karar veriyor; bu yansıtmadır. Kendini sınama ise bilgiyi kaynağa bakmadan hatırlamaya çalışmaktır."},{"id":"mg-8-s33","tur":"coktan-secmeli","soru":"Dört kişilik grup bir otelin açılış haftası programını hazırlıyor: biri araştırıyor, biri yazıyor, biri çiziyor, biri sunuyor. Bu çalışma hangi öğrenme biçimini yansıtır?","secenekler":["Kişiselleştirilmiş öğrenme","Mikro öğrenme","İş birlikli öğrenme","Ters yüz edilmiş sınıf"],"dogru":2,"aciklama":"Öğrenciler ortak bir amaç için görev ve sorumlulukları paylaşarak birlikte çalışıyor. Kişiselleştirilmiş öğrenme ise yolun tek bir öğrencinin ihtiyacına göre ayarlanmasıdır."},{"id":"mg-8-s34","tur":"dogru-yanlis","soru":"Öğrenmede yeni bir araç kullanmak, öğrenmeyi iyileştirmese bile tek başına değerli bir yeniliktir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Öğrenmede inovasyonda yenilik amaç değil araçtır; ancak daha iyi, daha kalıcı ya da daha kolay öğretiyorsa değerlidir."},{"id":"mg-8-s35","tur":"coktan-secmeli","soru":"Staj değerlendirmesinde şef şunu yazıyor: “Konukla iletişimi çok iyi. Telefonda İngilizce konuşurken çekiniyor; geliştirmeli.” İkinci cümle stajyerin hangi özelliğini gösterir?","secenekler":["Mesleki eğilimini","Gelişime açık yönünü","Alana özgü yetkinliğini","Öğrenme tercihini"],"dogru":1,"aciklama":"Şefin işaret ettiği nokta, stajyerin henüz yeterli olmadığı ve güçlendirmesi gereken bir beceridir. Mesleki eğilim ise kişinin hangi işlerden hoşlandığını gösterir."},{"id":"mg-8-s36","tur":"coktan-secmeli","soru":"Rezervasyonların çoğu internetten gelmeye başlayınca, yıllarca telefonla kayıt alan görevli çevrim içi rezervasyon ekranını ve konuk yorumlarına cevap yazmayı öğreniyor. Bu süreç hangisidir?","secenekler":["Yetkinlik dönüşümü","Kariyer varsayımı","Mesleki eğilim","Öğrenme motivasyonu"],"dogru":0,"aciklama":"Görevli, mesleğin değişen ihtiyacına ayak uydurmak için bilgi ve becerisini yeniliyor. Kariyer varsayımı ise kişinin geleceğine dair kurduğu ön düşüncedir."},{"id":"mg-8-s37","tur":"coktan-secmeli","soru":"Bir öğrenci sınava yalnızca metni üç kez baştan okuyarak hazırlanıyor. Bu çalışma yolunun zayıf yanı nedir?","secenekler":["Çok zaman aldığı için öğrenciyi derse geç bırakır","Yalnız sözel derslerde işe yarar, sayısal derslerde yaramaz","Konunun ana fikrini görmeyi tümüyle engeller","“Biliyorum” duygusu verir ama çoğu zaman kalıcı olmaz"],"dogru":3,"aciklama":"Yalnızca yeniden okumak bilgiyi tanıdık gösterir ama kalıcılık sağlamaz. Kendini sınamak ve tekrarı zamana yaymak daha kalıcı bir öğrenme stratejisidir."},{"id":"mg-8-s38","tur":"dogru-yanlis","soru":"Mert iki hafta her akşam düzenli çalışmış ama sınav notu henüz yükselmemiştir. Mert’in gösterdiği çaba ve ilerleme yine de öğrenme performansının parçasıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Öğrenme performansı yalnız sonucu değil, çabayı ve ilerlemeyi de kapsar. Not ise akademik başarıyı gösterir; ikisi ilişkilidir ama aynı şey değildir."},{"id":"mg-8-s39","tur":"coktan-secmeli","soru":"Ödev için arama yapan öğrenci ilk çıkan sonucu kopyalamıyor; kaynağın kim olduğuna bakıyor, bilgiyi ikinci bir kaynakla karşılaştırıp kendi cümleleriyle yazıyor. Öğrenci hangi beceriyi gösteriyor?","secenekler":["Öğrenmede öz disiplin","Alana özgü teknik yetkinlik","Dijital okuryazarlık","Önceliklendirme"],"dogru":2,"aciklama":"Bilgiye dijital araçla ulaşıp doğruluğunu sorgulamak ve içeriği güvenli biçimde üretmek dijital okuryazarlıktır. Öz disiplin ise canı istemese de plana uyabilmektir."},{"id":"mg-8-s40","tur":"coktan-secmeli","soru":"İlk canlandırmada İngilizce cümleleri karıştırıp utanan öğrenci vazgeçmiyor; her gün birkaç dakika prova yapıyor ve üç hafta sonra sahneyi takılmadan oynuyor. Bu davranışı en iyi anlatan kavram hangisidir?","secenekler":["Dışsal motivasyon","Azim","Erteleme","Özgüven"],"dogru":1,"aciklama":"Başarısızlığa rağmen vazgeçmeyip hedefe doğru çalışmayı sürdürmek azimdir. Özgüven yeni bir görevi denemeye cesaret etmektir; burada öne çıkan, hatadan sonra çalışmayı sürdürmektir."},{"id":"mg-8-s41","tur":"coktan-secmeli","soru":"Çarşamba günleri stajda olan bir öğrenci haftalık çalışma planını hazırlıyor. Planındaki hangi satır gerçekçi olmadığı için değiştirilmelidir?","secenekler":["Pazartesi akşamı yarım saat kalıp cümle","Salı akşamı yarım saat kart tekrarı","Çarşamba akşamı üç saat yeni konu","Perşembe akşamı yarım saat okuma"],"dogru":2,"aciklama":"Haftalık plan kişinin kendi saatlerine göre yapılır; staj gününe uzun çalışma yazmak gerçekçi değildir. O gün için kısa bir tekrar yeterlidir."},{"id":"mg-8-s42","tur":"coktan-secmeli","soru":"Öğrenme rotası ile bireysel gelişim eylem planı arasındaki fark hangisidir?","secenekler":["Rota tek hedefin yoludur; eylem planı tüm gelişim alanlarını gösterir","Rotayı öğretmen hazırlar; eylem planını ise öğrenci kendisi yazar","Rota tüm gelişim alanlarını gösterir; eylem planı tek hedefe odaklanır","Rota yazılı hazırlanır; eylem planı yalnız sözlü olarak paylaşılır"],"dogru":0,"aciklama":"Öğrenme rotası tek bir öğrenme hedefine giden yolu gösterir; bireysel gelişim eylem planı ise kişinin bütün gelişime açık yönlerini, hedeflerini ve tarihlerini bir arada toplar."},{"id":"mg-8-s43","tur":"coktan-secmeli","soru":"Proje tabanlı öğrenmeyi probleme dayalı öğrenmeden ayıran temel fark hangisidir?","secenekler":["Proje tabanlı öğrenmede hedef bir soruna çözüm bulmak, probleme dayalı öğrenmede somut bir ürün ortaya koymaktır","Proje tabanlı öğrenme yalnız bireysel, probleme dayalı öğrenme yalnız grupla birlikte yapılabilir","Proje tabanlı öğrenme yalnız sınıfta, probleme dayalı öğrenme yalnız evde yürütülebilir","Proje tabanlı öğrenmede hedef somut bir ürün ortaya koymak, probleme dayalı öğrenmede bir soruna çözüm aramaktır"],"dogru":3,"aciklama":"Proje tabanlı öğrenmede öğrenciler somut bir ürün (gezi programı, broşür) ortaya koyar; probleme dayalı öğrenmede ise gerçek bir soruna çözüm arar."},{"id":"mg-8-s44","tur":"coktan-secmeli","soru":"Stajda kat şefi yatağın nasıl yapılacağını bir kez gösteriyor; ardından stajyer yapıyor, şef izleyip köşeleri düzelttiriyor. Bu öğrenme biçimi hangisidir?","secenekler":["Simülasyon","İş başında öğrenme","Ters yüz edilmiş sınıf","Mikro öğrenme"],"dogru":1,"aciklama":"İş, gerçek çalışma ortamında deneyimli bir çalışanın yanında izlenerek ve yapılarak öğreniliyor. Simülasyonda ise gerçek ortam taklit edilir; burada ortam otelin kendisidir."},{"id":"mg-8-s45","tur":"coktan-secmeli","soru":"Can, çorba servisinde elinin titrediğini biliyor. Hangisi bilinçli alıştırmaya uygun bir çalışmadır?","secenekler":["Bütün servisi baştan sona birkaç kez tekrar etmek","Zaten iyi yaptığı bardak servisini daha çok çalışmak","Yalnız o hareketi öğretmen izlerken birkaç kez tekrarlamak","Servis videosunu izleyip uygulamayı ertesi haftaya bırakmak"],"dogru":2,"aciklama":"Bilinçli alıştırma zayıf kalan kısma odaklanır ve geri bildirimle yapılır. Bütün servisi baştan tekrar etmek zorlanılan noktayı öne çıkarmaz."},{"id":"mg-8-s46","tur":"dogru-yanlis","soru":"Oyunlaştırmada puan ve rozet bir araçtır; asıl amaç öğrenmektir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Oyun ögeleri başlamayı ve sürdürmeyi kolaylaştırır; yalnız puan için tıklayan kişi bilgiyi değil, puanı kazanır."},{"id":"mg-8-s47","tur":"coktan-secmeli","soru":"Hangisi iyi yazılmış bir öğrenme hedefidir?","secenekler":["Bu yıl boyunca çok çalışıp İngilizcede sınıftaki herkesten daha iyi olmaya çalışacağım.","Telefonda İngilizce konuşmayı bir gün mutlaka ve kusursuz biçimde öğrenmiş olacağım.","Her gün biraz İngilizce çalışarak kendimi elimden geldiğince ve sürekli geliştireceğim.","Mayıs sonuna kadar telefonda İngilizce rezervasyon almayı deftere bakmadan yapacağım."],"dogru":3,"aciklama":"İyi bir öğrenme hedefi neyin, ne zamana kadar yapılabileceğini açıkça söyler; yani belirli, ölçülebilir ve zamana bağlıdır. Öteki ifadeler birer dilektir, bitiş tarihi ya da ölçütü yoktur."},{"id":"mg-8-s48","tur":"coktan-secmeli","soru":"Hedef-ihtiyaç ilişkisinde zincirin doğru sırası hangisidir?","secenekler":["Değişim → ihtiyaç → hedef → plan → gelişim","İhtiyaç → değişim → plan → hedef → gelişim","Hedef → plan → değişim → ihtiyaç → gelişim","Değişim → hedef → ihtiyaç → gelişim → plan"],"dogru":0,"aciklama":"Mesleki alandaki bir değişim yeni bir yetkinlik ihtiyacı doğurur; bu ihtiyaç öğrenme hedefine, hedef planlı çalışmaya, plan da gelişime dönüşür."},{"id":"mg-8-s49","tur":"dogru-yanlis","soru":"Portfolyo son gün toplu olarak hazırlanmaz; 9. sınıftan başlayarak her iyi çalışma dosyaya eklenir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Portfolyo kişinin zaman içindeki çalışmalarını ve gelişimini gösterir; bu yüzden yıllar boyunca düzenli olarak biriktirilir."},{"id":"mg-8-s50","tur":"coktan-secmeli","soru":"Öğrenci “check-in nedir?” konusunu annesine sade cümlelerle anlatıyor, tıkandığı yeri yeniden çalışıp tekrar anlatıyor. Feynman tekniğinde öğrencinin tıkandığı yerler neyi gösterir?","secenekler":["Konunun gereksiz bölümlerini","Dinleyicinin dikkatsizliğini","Kendi öğrenme eksiklerini","Kaynağın güvenilmez olduğunu"],"dogru":2,"aciklama":"Feynman tekniğinde açıklamakta zorlanılan bölümler, konunun henüz iyi öğrenilmemiş yerleridir; öğrenci bu yerleri yeniden çalışır."}],"siralamalar":[{"id":"mg-8-r01","konu":"8.2","baslik":"Kendini tanımaktan eylem planına","yonerge":"Gelişime açık yönünü bulup onu dönüştürecek bir plan hazırlarken izleyeceğin adımları doğru sıraya koy.","adimlar":["Kendi öğrenme alışkanlıklarını ve meslek alanında geleceğin isteyeceği yetkinlikleri ayrı ayrı incele.","Her yetkinliği kendi eğilimine göre eşleştir; “uyumlu” mu “geliştirilmeli” mi, işaretle.","Kariyer varsayımını bu işaretlerle karşılaştır ve gelişime açık yönlerini belirle.","Gelişime açık yönün için yöntemi, kaynakları ve süresi belli bir bireysel gelişim eylem planı hazırla.","Planını danışman rolündeki arkadaşına sun; geleceğin yetkinlikleriyle uyumunu değerlendirsin."],"aciklama":"Her adım bir öncekinin sonucunu kullanır: kendini ve geleceğin beklentilerini tanımadan eşleştirme, eşleştirmeden gelişime açık yön, açık yön belli olmadan da plan yapılamaz; plan hazır olunca başkasının gözüyle sınanır."},{"id":"mg-8-r02","konu":"8.3","baslik":"Değişimden gelişime giden zincir","yonerge":"Mesleki hedef ile öğrenme ihtiyacı arasındaki neden-sonuç zincirinin halkalarını doğru sıraya koy.","adimlar":["Meslek alanında bir değişim ortaya çıkar.","Çalışanlarda yeni bir yetkinliğe ihtiyaç doğar.","Kişi bu ihtiyaca göre kendi öğrenme hedefini belirler.","Hedefe ulaştıracak öğrenme çalışmaları planlanır.","Planlı çalışmayla mesleki gelişim sağlanır."],"aciklama":"Zincirin her halkası bir öncekinin sonucudur: değişim yeni bir ihtiyaç doğurur, ihtiyaç hedefe, hedef plana, plan da gelişime dönüşür."},{"id":"mg-8-r03","konu":"8.3","baslik":"Feynman tekniğiyle bir konuyu çözmek","yonerge":"Feynman tekniğinin adımlarını doğru sıraya koy.","adimlar":["Öğrenmek istediğin konuyu belirle.","Konuyu, alanı hiç bilmeyen birine anlatıyormuş gibi sade bir dille açıkla.","Açıklarken takıldığın bölümleri bul; bunlar öğrenme eksiklerini gösterir.","Takıldığın bölümleri yeniden çalış.","Yeniden çalıştığın bölümleri de katarak konuyu tekrar sade bir dille açıkla."],"aciklama":"Eksikler ancak konuyu anlatmaya çalışınca ortaya çıkar; o bölümler çalışıldıktan sonra yapılan ikinci anlatım, konunun gerçekten öğrenilip öğrenilmediğini gösterir."}],"acikSorular":[{"id":"mg-8-y01","konu":"8.2","soru":"Stajyer öğrenci Elif, hem staj görevlerini hem okul ödevlerini sürekli erteliyor ve çalışırken telefon bildirimleri dikkatini dağıtıyor. Elif’e önceliklendirme için Eisenhower matrisini ve odaklanmak için Pomodoro tekniğini önerdiğinizi varsayarak bu iki yöntemi açıklayınız ve Elif’in erteleme sorununa nasıl yardımcı olacağını yazınız.","olcut":[{"metin":"Erteleme ve dikkat dağıtıcıyı Elif’in sorunu olarak tanımlar.","puan":15},{"metin":"Eisenhower matrisinin işleri “acil mi?” ve “önemli mi?” sorularına göre dört kutuya ayırdığını belirtir.","puan":25},{"metin":"Pomodoro tekniğinin kesintisiz kısa çalışma bölümleri ve aralarındaki kısa molalardan oluştuğunu belirtir.","puan":25},{"metin":"İki yöntemin erteleme ve dikkat dağınıklığını nasıl azalttığını nedenleriyle açıklar.","puan":35}],"ornek":"Elif’in sorunu, yapılması gereken işleri sonraya bırakması yani erteleme ve telefon bildirimleri gibi dikkat dağıtıcılardır. Eisenhower matrisi işleri “acil mi?” ve “önemli mi?” sorularına göre dört kutuya ayırır; Elif böylece hangi işi önce yapacağını görür. Pomodoro tekniğinde ise kısa süre kesintisiz çalışılır ve araya kısa mola verilir. Önceliği belli olan iş ve kısa odak süresi işe başlamayı kolaylaştırır, telefon da bu sürede kapalı kaldığı için erteleme ve dikkat dağınıklığı azalır.","ipucu":"Birinin neyi, diğerinin nasıl çalışmayı düzenlediğini ayırın ve ikisinin erteleme üzerindeki etkisini bağlayın."},{"id":"mg-8-y02","konu":"8.3","soru":"Resepsiyon staj sınavına hazırlanan Burak, bütün konuları sınavdan bir gün önce uzun süre okuyarak çalışmayı planlıyor. Burak’a aralıklı tekrar ve kendini sınama yöntemlerini açıklayınız ve bu yöntemlerin neden tek seferlik uzun çalışmadan daha etkili olduğunu yazınız.","olcut":[{"metin":"Burak’ın planındaki sorunu (tek seferde uzun çalışma) belirtir.","puan":15},{"metin":"Aralıklı tekrarın, araları giderek açılan kısa tekrarlarla pekiştirme olduğunu belirtir.","puan":25},{"metin":"Kendini sınamanın, bilgiyi kaynağa bakmadan hatırlamaya çalışmak olduğunu belirtir.","puan":25},{"metin":"İki yöntemin bilginin kalıcı olmasına ve eksiklerin görülmesine nasıl yardım ettiğini nedenleriyle açıklar.","puan":35}],"ornek":"Burak’ın planında bütün konular tek seferde, sınavdan bir gün önce çalışılıyor. Oysa aralıklı tekrar, öğrenilen bilginin araları giderek açılan kısa tekrarlarla pekiştirilmesidir. Kendini sınama ise bilgiyi kaynağa bakmadan hatırlamaya çalışmaktır. Burak konuları günlere yayıp her tekrarda kendini sınarsa neyi hatırlayamadığını görür ve yalnız o yeri çalışır. Böylece bilgi kısa süreli ezber olmaktan çıkar ve daha kalıcı olur.","ipucu":"Tekrarların zamana yayılmasının ve kaynağa bakmadan hatırlamanın bilgiye ve eksiklerin fark edilmesine etkisini düşünün."}]},{"ders":"mesleki-gelisim","sinif":9,"unite":9,"baslik":"Yeşil Dönüşüm, Dijital Dönüşüm ve İkiz Dönüşüm","onay":true,"kazanimlar":["Yeşil, dijital ve ikiz dönüşümün iş gücü piyasasına ve çalışma hayatına olası etkilerini yorumlayabilme.","Yeşil, dijital ve ikiz dönüşümün iş gücü piyasası üzerindeki etkilerini tartışabilme.","Bir iş sürecini yeşil, dijital ve ikiz dönüşüm bağlamında çözümleyebilme.","Bir iş modelini yeşil, dijital ve ikiz dönüşüm bağlamında yapılandırabilme."],"soz":"Ölçmediğini azaltamazsın; korumadığını da satamazsın.","dersler":[{"baslik":"Yarına Ne Kalacak?","ilk":"mg-9-002"},{"baslik":"Yeşile Dönmek Ne Demek?","ilk":"mg-9-009"},{"baslik":"Yeşil mi, Yeşil Görünen mi?","ilk":"mg-9-021"},{"baslik":"Kâğıttan Ekrana","ilk":"mg-9-026"},{"baslik":"Makine Yapar, İnsan Yönetir","ilk":"mg-9-033"},{"baslik":"Yarının İş İlanı","ilk":"mg-9-039"},{"baslik":"Kimse Geride Kalmasın","ilk":"mg-9-047"},{"baslik":"İki Dönüşüm, Tek Yol","ilk":"mg-9-057"},{"baslik":"Parlak Teknolojinin Gölgesi","ilk":"mg-9-061"},{"baslik":"Her Damla Sayılır","ilk":"mg-9-007"},{"baslik":"Konuk Çıkınca Işık Söner","ilk":"mg-9-013"},{"baslik":"Merdivenin Hangi Basamağındayız?","ilk":"mg-9-027"},{"baslik":"Karekodla Gelen Değişim","ilk":"mg-9-037"},{"baslik":"Süreci Röntgenle","ilk":"mg-9-066"},{"baslik":"İş Fikri Doğuyor","ilk":"mg-9-001"},{"baslik":"Akıllı Bina, Akıllı Karar","ilk":"mg-9-043"},{"baslik":"Yeni Modele Not Verelim","ilk":"mg-9-071"}],"kavramlar":[{"id":"mg-9-002","konu":"9.1","terim":"Çevresel sürdürülebilirlik","ingilizce":"Environmental sustainability","tanim":"Havanın, suyun, toprağın ve canlı çeşitliliğinin kendini yenileyebileceği sınırlar içinde kullanılması ve korunmasıdır.","ornek":"Saat 11.00, boş bir oda: kat görevlisi açık kalmış klimayı kapatır, damlatan musluğu teknik servise bildirir.","sektor":"Sürdürülebilirliğin üç boyutundan biridir; öteki ikisi ekonomik ve sosyal boyuttur. Enerji, su ve atık otelin başlıca çevre etkileridir; üçü de aynı zamanda faturadır. Çevreyi koruyan davranış çoğu zaman gideri de düşürür.","iliskili":["mg-9-001","mg-9-003","mg-9-004"],"kontrol":null},{"id":"mg-9-003","konu":"9.1","terim":"Ekonomik sürdürülebilirlik","ingilizce":"Economic sustainability","tanim":"Bir işletmenin ya da ekonominin, kaynaklarını tüketmeden uzun yıllar boyunca kazanç sağlamayı ve iş vermeyi sürdürebilmesidir.","ornek":"Bir butik otel kış aylarında da açık kalabilmek için yürüyüş ve yöresel mutfak programları düzenler; personel bütün yıl çalışır.","sektor":"Sürdürülebilirliğin üç boyutundan biridir. Para kazanamayan işletme çevre yatırımı da yapamaz, personelini de tutamaz. Hedef kısa sürede çok kazanıp tükenmek değil, yıllarca ayakta kalmaktır.","iliskili":["mg-9-001","mg-9-002","mg-9-004"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-9-004","konu":"9.1","terim":"Sosyal sürdürülebilirlik","ingilizce":"Social sustainability","tanim":"İnsanların adil çalışma koşullarına, eşit fırsatlara ve sağlıklı bir yaşama sahip olmasını, yerel kültürün ve toplumun korunmasını gözeten anlayıştır.","ornek":"Kapadokya’daki bir otel personelinin çoğunu çevre köylerden alır, lobisinde yöredeki çömlek ustalarının ürünlerini sergiler.","sektor":"Sürdürülebilirliğin üç boyutundan biridir. Yöre halkı turizmden pay almazsa turiste de sıcak bakmaz. Adil ücret, güvenli iş ortamı ve yerel kültüre saygı güler yüzlü hizmetin arkasındaki görünmeyen temeldir.","iliskili":["mg-9-001","mg-9-002","mg-9-003"],"kontrol":null,"cizim":"doga"},{"id":"mg-9-005","konu":"9.1","terim":"Sürdürülebilir Kalkınma Amaçları","ingilizce":"Sustainable Development Goals (SDGs)","tanim":"Birleşmiş Milletler üyesi ülkelerin yoksulluğu bitirmek, gezegeni korumak ve herkes için daha iyi bir yaşam sağlamak üzere birlikte kabul ettiği 17 küresel amaçtır.","ornek":"Bir zincir otelin lobisindeki panoda renkli kutucuklar görürsün: otel hangi çalışmasının hangi amaca katkıda bulunduğunu bu kutucuklarla gösterir.","sektor":"İngilizce kısaltması SDGs. Çevreyi, ekonomiyi ve toplumu birlikte gözeten kalkınma anlayışına sürdürülebilir kalkınma denir; bu amaçlar onun yol haritasıdır. Temiz su, temiz enerji, insana yakışır iş, sorumlu üretim ve tüketim, iklim eylemi gibi başlıklar otelin günlük işiyle doğrudan ilgilidir. Numaralarını ezberlemen gerekmez; toplam 17 amaç olduğunu bil.","iliskili":["mg-9-001","mg-9-021","mg-9-020"],"kontrol":null,"gorsel":"m9-wikimania-2019-sustainable-d"},{"id":"mg-9-006","konu":"9.1","terim":"Sistem","ingilizce":"System","tanim":"Ortak bir amaç için birlikte çalışan ve birbirini etkileyen parçaların oluşturduğu bütündür.","ornek":"Otelde çamaşırhanenin kazanı arızalanır; temiz havlu çıkmaz, odalar hazırlanamaz, resepsiyon konuğu bekletir: tek parçadaki sorun bütüne yayılır.","sektor":"Programın anahtar kavramlarındandır. Dönüşüm tek bir cihazı değiştirmek değildir; enerji, su, satın alma, personel ve konuk birbirine bağlıdır. Bir parçayı değiştirirken bütünü düşünmeye sistem düşüncesi denir.","iliskili":["mg-9-007","mg-9-008","mg-9-052"],"kontrol":null},{"id":"mg-9-009","konu":"9.1","terim":"İşletmede yeşil dönüşüm","ingilizce":"Green transition in business","tanim":"Bir işletmenin üretim ve hizmet biçimini daha az kaynak harcayan, daha az kirleten ve iklime daha az zarar veren bir yapıya dönüştürmesidir.","ornek":"Bir otel sırayla çatısına güneş paneli kurar, tek kullanımlık plastikleri kaldırır, mutfak atığını ayrıştırır ve personeline bu konularda eğitim verir.","sektor":"Yeşil dönüşüm programın anahtar kavramlarındandır. Tek bir proje değil, işin yapılış biçimindeki kalıcı değişimdir: satın almadan temizliğe, mutfaktan ön büroya her bölümün işi değişir. Bu yüzden her çalışanı ilgilendirir.","iliskili":["mg-9-010","mg-9-012","mg-9-041"],"kontrol":null,"gorsel":"m9-field-of-solar-panels"},{"id":"mg-9-010","konu":"9.1","terim":"İklim değişikliğinin turizme etkisi","ingilizce":"Impact of climate change on tourism","tanim":"Sıcaklık ve yağış düzenindeki kalıcı değişimin turizm sezonlarını, doğal güzellikleri ve işletmelerin giderlerini etkilemesidir.","ornek":"Bir kayak merkezinde kar geç yağar ve erken erir; otelin sezonu kısalır.","sektor":"Turizm iklime en bağımlı sektörlerdendir: kar yağmazsa kış sezonu, aşırı sıcak ya da orman yangını olursa yaz sezonu etkilenir. Otelci için iklim değişikliği uzak bir haber değil, doğrudan iş konusudur.","iliskili":["mg-9-011","mg-9-012","mg-9-021"],"kontrol":null,"cizim":"doga"},{"id":"mg-9-017","konu":"9.1","terim":"İşletmede döngüsel ekonomi","ingilizce":"Circular economy","tanim":"Ürün ve malzemelerin kullanılıp atılması yerine onarılarak, yeniden kullanılarak ve geri dönüştürülerek olabildiğince uzun süre ekonomide tutulduğu üretim ve tüketim modelidir.","ornek":"Otel eskiyen çarşafları atmaz, temizlik bezi olarak keser; mutfaktan çıkan sebze artıkları bahçe için komposta dönüşür.","sektor":"Döngüsel ekonomi programın anahtar kavramlarındandır. Tersi “al, kullan, at” düzenidir. Döngüsel düşünen işletme için atık, yanlış yerde duran bir kaynaktır: çöpe giden her şey bir kez de satın alınmıştır.","iliskili":["mg-9-018","mg-9-008","mg-9-019"],"kontrol":null},{"id":"mg-9-020","konu":"9.1","terim":"Yeşil büyüme","ingilizce":"Green growth","tanim":"Ekonominin, doğal kaynakları tüketmeden ve çevreyi kirletmeden büyümesini hedefleyen kalkınma yaklaşımıdır.","ornek":"Bir otel zinciri yeni otel açarken sıcak suyunu güneşle ısıtan, yağmur suyunu bahçe için toplayan binalar yapar: oda sayısı artarken oda başına tüketim düşer.","sektor":"Programın anahtar kavramlarındandır. “Ya çevre ya kazanç” ikilemini kabul etmez: doğru yatırımla ikisi birlikte olabilir. Yeni teknolojiler, yeni iş kolları ve yeni meslekler bu büyümenin ürünüdür.","iliskili":["mg-9-005","mg-9-009","mg-9-046"],"kontrol":null,"gorsel":"m9-plant-a-sapling-for"},{"id":"mg-9-021","konu":"9.1","terim":"Paris Anlaşması","ingilizce":"Paris Agreement","tanim":"Ülkelerin, iklim değişikliğiyle mücadele etmek için sera gazı salımlarını azaltma sözü verdiği ve küresel ısınmayı sınırlamayı amaçlayan uluslararası anlaşmadır.","ornek":"Haberlerde “Ülkeler iklim zirvesinde bir araya geldi” dendiğinde, masadaki konu çoğu zaman bu anlaşmada verilen sözlerdir.","sektor":"Birleşmiş Milletler çatısı altında kabul edilmiştir; Türkiye de taraftır. Ülkelerin verdiği sözler zamanla işletmelere kural ve hedef olarak yansır: enerji, ulaşım ve turizm bundan payını alır.","iliskili":["mg-9-010","mg-9-011","mg-9-022"],"kontrol":null},{"id":"mg-9-022","konu":"9.1","terim":"Avrupa Yeşil Mutabakatı","ingilizce":"European Green Deal","tanim":"İklime zarar vermeyen bir ekonomiye geçmek için Avrupa Birliğinin açıkladığı kapsamlı dönüşüm ve büyüme stratejisidir.","ornek":"Avrupa’ya ürün satan bir Türk firması alıcılarının isteğiyle ürününü üretirken ne kadar karbon saldığını hesaplayıp belgelemeye başlar.","sektor":"Yalnız Avrupa’yı ilgilendirmez: Avrupa Türkiye’nin önemli bir ticaret ortağı ve turist pazarıdır. Avrupalı tur şirketleri ve konuklar çalıştıkları otelden çevre konusunda daha fazlasını bekleyebilir.","iliskili":["mg-9-021","mg-9-020","mg-9-009"],"kontrol":null,"gorsel":"m9-berlaymont-building-of-europ"},{"id":"mg-9-023","konu":"9.1","terim":"Yeşil Anahtar","ingilizce":"Green Key","tanim":"Çevreye duyarlı biçimde işletilen konaklama tesislerine ve benzeri turizm işletmelerine verilen uluslararası çevre etiketidir.","ornek":"Otelin girişinde, resepsiyonun yanında asılı Yeşil Anahtar plaketi; yanında otelin çevre politikası yazılıdır.","sektor":"Türkiye’de Türkiye Çevre Eğitim Vakfı (TÜRÇEV) yürütür. Etiket denetimle verilir ve düzenli olarak yenilenmesi gerekir; bir kez alınıp unutulmaz. Konuk için otelin çevre sözünün kanıtıdır.","iliskili":["mg-9-024","mg-9-025","mg-9-002"],"kontrol":null,"kitapDisi":true,"gorsel":"t12u-green-key-levhasi"},{"id":"mg-9-024","konu":"9.1","terim":"Mavi Bayrak","ingilizce":"Blue Flag","tanim":"Belirli çevre, temizlik ve güvenlik koşullarını sağlayan plajlara, marinalara ve turizm teknelerine verilen uluslararası çevre ödülüdür.","ornek":"Otel plajının girişinde dalgalanan mavi bayrak ve yanındaki bilgi panosu.","sektor":"Türkiye’de TÜRÇEV yürütür. Ödül her yıl yeniden değerlendirilir: koşullar bozulursa bayrak indirilir. Deniz tatili arayan konuk için güçlü bir güven işaretidir.","iliskili":["mg-9-023","mg-9-002","mg-9-025"],"kontrol":null,"kitapDisi":true,"gorsel":"g3-mavi-bayrak"},{"id":"mg-9-026","konu":"9.1","terim":"Dijital dönüşüm","ingilizce":"Digital transformation","tanim":"Bir işletmenin, dijital teknolojileri kullanarak iş yapma biçimini, hizmetini ve müşteriyle ilişkisini baştan düşünüp değiştirmesidir.","ornek":"Otel, rezervasyondan çıkışa bütün yolu yeniden kurar: konuk telefonundan oda seçer, kaydını önceden yapar, faturasını e-postayla alır.","sektor":"Programın anahtar kavramlarındandır. Bilgisayar almak tek başına dönüşüm değildir; onu dönüşüm yapan, işin yapılış biçiminin değişmesidir. Amaç teknolojiyi göstermek değil, konuğa daha hızlı ve hatasız hizmet verip personele konukla ilgilenecek zaman kazandırmaktır.","iliskili":["mg-9-027","mg-9-028","mg-9-041"],"kontrol":null},{"id":"mg-9-030","konu":"9.1","terim":"Veri analizi","ingilizce":"Data analysis","tanim":"Toplanan verinin düzenlenip karşılaştırılarak içinden karar vermeye yarayacak sonuçların çıkarılmasıdır.","ornek":"Teknik müdür aylık su tüketimini doluluk oranıyla yan yana koyar; konuk sayısı düştüğü hâlde su artmışsa bir yerde kaçak olduğundan şüphelenir.","sektor":"Programın anahtar kavramlarındandır. “Bana öyle geliyor” yerine “veri bunu gösteriyor” demeyi sağlar. Otelde tahmin, satın alma, personel planı ve enerji yönetimi giderek daha çok veriye dayanır.","iliskili":["mg-9-029","mg-9-018","mg-9-043"],"kontrol":null,"cizim":"grafik"},{"id":"mg-9-031","konu":"9.1","terim":"İş süreçlerinde otomasyon","ingilizce":"Process automation","tanim":"Tekrarlayan bir işin, insan her seferinde elle yapmadan, makine ya da yazılım tarafından kendiliğinden yürütülmesidir.","ornek":"Bahçe sulama sistemi gece saatinde kendiliğinden açılır, toprak nemliyse çalışmaz; kimse vana çevirmez.","sektor":"Otomasyon programın anahtar kavramlarındandır. Rutin işi makine alınca personele konukla ilgilenmek, sorun çözmek ve sistemi izlemek kalır. Otomasyon çoğu zaman mesleği yok etmez, işin içeriğini değiştirir; bu yüzden çalışanın yeni beceriler öğrenmesi gerekir.","iliskili":["mg-9-032","mg-9-050","mg-9-042"],"kontrol":null},{"id":"mg-9-032","konu":"9.1","terim":"Endüstri 4.0 ve dönüşüm","ingilizce":"Industry 4.0","tanim":"Makinelerin, sensörlerin ve yazılımların birbirine bağlanıp veri paylaşarak üretimi kendi kendine ayarlayabildiği, dördüncü sanayi devrimi olarak anılan dönemdir.","ornek":"Büyük bir çamaşır yıkama tesisinde makineler yük miktarını kendi ölçer, suyu ve deterjanı ona göre ayarlar, bakım zamanı yaklaşınca ekibe haber verir.","sektor":"Endüstri 4.0 programın anahtar kavramlarındandır. Fabrikada başlayan bu düşünce hizmet sektörüne de geçti: bağlı cihazlar, anlık veri, kendini ayarlayan sistemler. Daha az fire ve daha az enerji sağladığı için yeşil dönüşümün de aracıdır.","iliskili":["mg-9-031","mg-9-033","mg-9-041"],"kontrol":null,"gorsel":"m9-makerbot-print-area"},{"id":"mg-9-033","konu":"9.1","terim":"Nesnelerin interneti ile kaynak izleme","ingilizce":"Internet of Things (IoT) monitoring","tanim":"İnternete bağlı sensör ve cihazların enerji, su ve sıcaklık gibi değerleri ölçüp bu veriyi kendiliğinden merkeze iletmesidir.","ornek":"Soğuk hava deposundaki sensör sıcaklık yükselince mutfak şefinin telefonuna uyarı gönderir; yiyecekler bozulmadan müdahale edilir.","sektor":"Nesnelerin interneti programın anahtar kavramlarındandır; kısaca IoT denir. Akıllı sensör kimsenin gidip bakmasına gerek kalmadan ölçer. Su kaçağı, açık kalmış pencere, bozulan soğutucu erken fark edilir: hem kaynak hem ürün kurtulur.","iliskili":["mg-9-029","mg-9-043","mg-9-032"],"kontrol":null,"gorsel":"m9-raspberry-pi-2-model"},{"id":"mg-9-035","konu":"9.1","terim":"Binanın dijital ikizi","ingilizce":"Digital twin of a building","tanim":"Bir binanın, sensörlerden gelen verilerle sürekli güncellenen ve değişikliklerin önce üzerinde denendiği bilgisayardaki sanal kopyasıdır.","ornek":"Otelin teknik ekibi binanın ekrandaki modelinde “Üçüncü katın soğutmasını biraz kısarsak ne olur?” sorusunu önce sanal olarak dener.","sektor":"Dijital ikiz programın anahtar kavramlarındandır; makinelerin ve süreçlerin de dijital ikizi olabilir. Adı “ikiz dönüşüm” ile karıştırılmamalı: dijital ikiz bir teknolojidir, ikiz dönüşüm ise yeşil ile dijitalin birlikte yürümesidir. Deneme sanal ortamda yapıldığı için gerçek kaynak harcanmaz.","iliskili":["mg-9-033","mg-9-042","mg-9-041"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-055","konu":"9.1","terim":"Sensör","ingilizce":"Sensor","tanim":"Sıcaklık, hareket, ışık ya da nem gibi çevredeki bir değişimi algılayıp veriye çeviren ve bu veriyi bir yazılıma ileten algılayıcıdır.","ornek":"Odaya girildiğini ya da odanın boş kaldığını algılayan hareket sensörü, boş odada klimayı kısar.","sektor":"Sensör, dijital dönüşümün gözüdür: sensör ölçer, yazılım yorumlar, karar uygulanır. Nesnelerin interneti, dijital ikiz, akıllı bina ve enerji izleme sensörün topladığı veriye dayanır.","iliskili":["mg-9-033","mg-9-035","mg-9-029"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-041","konu":"9.1","terim":"İkiz dönüşüm","ingilizce":"Twin transition","tanim":"Yeşil dönüşüm ile dijital dönüşümün ayrı ayrı değil, birbirini destekleyecek biçimde birlikte planlanıp yürütülmesidir.","ornek":"Otel odalara sensör ve akıllı termostat takar (dijital adım); boş odada klima kendiliğinden kısılır, enerji tüketimi düşer (yeşil sonuç).","sektor":"Programın anahtar kavramlarındandır. Dijital teknoloji ölçer ve yönetir, yeşil hedef neyin ölçüleceğini söyler: biri ötekinin aracıdır. Ölçmeden yapılan tasarruf da amaçsız kullanılan teknoloji de eksik kalır.","iliskili":["mg-9-009","mg-9-026","mg-9-053"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-049","konu":"9.1","terim":"Dijital beceri","ingilizce":"Digital skills","tanim":"Bilgisayar, telefon ve yazılımları işini yapmak, bilgiye ulaşmak, iletişim kurmak ve veriyi güvenle kullanmak için etkili biçimde kullanabilme yeterliliğidir.","ornek":"Ön büro stajyeri rezervasyon sistemine kayıt girer, bir e-postaya düzgün yanıt yazar, tabloda günün geliş listesini süzer.","sektor":"Sosyal medyada gezinmek dijital beceri sayılmaz; aracı iş için kullanabilmek sayılır. Otelde hemen her bölüm bir yazılımla çalışır: yeni bir sistemi çabuk öğrenebilmek en değerli dijital becerilerdendir.","iliskili":["mg-9-048","mg-9-050","mg-9-045"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-056","konu":"9.1","terim":"Dijital etik","ingilizce":"Digital ethics","tanim":"Teknolojiyi dürüst, güvenli ve başkalarının haklarına saygılı biçimde kullanma ilkesidir.","ornek":"Bir otelde stajyer, konuk listesinin ekran görüntüsünü arkadaşına göndermez; sistemde gördüğü bilgiyi yalnız işi için kullanır.","sektor":"Dijital etik, otelde ekranın başındayken de sürer: işi olmayan bir konuğun kaydını merakla açmamak, kendi otelini öven sahte yorum yazmamak, yapay zekâyla üretilmiş görseli gerçek oda gibi sunmamak buna girer. Konuk ekranın arkasındakini göremez; güveni kuran şey orada gösterilen dürüstlüktür.","iliskili":["mg-9-049","mg-9-030","mg-9-039"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-039","konu":"9.2","terim":"Konuk verisinin korunması","ingilizce":"Guest data protection","tanim":"Otelin dijital sistemlerinde tutulan konuk bilgilerinin yalnız gerektiği kadar toplanması, güvenle saklanması ve izinsiz paylaşılmamasıdır.","ornek":"Resepsiyon görevlisi bankodan ayrılırken ekranını kilitler; konuk bilgilerinin göründüğü sayfayı açık bırakmaz.","sektor":"Kimin otelde kalacağı, kimlik ve ödeme bilgisi kişisel veridir ve Kişisel Verilerin Korunması Kanunu (KVKK) ile korunur. Dijitalleşme arttıkça otelin elindeki veri de artar. Şifreni kimseyle paylaşma, konuk bilgisinin fotoğrafını çekme, listeyi kimseye gönderme.","iliskili":["mg-9-029","mg-9-054","mg-9-037"],"kontrol":null,"gorsel":"m9-secured-laptop"},{"id":"mg-9-040","konu":"9.2","terim":"Dijital karbon ayak izi","ingilizce":"Digital carbon footprint","tanim":"Telefon, bilgisayar gibi cihazların üretimi ve kullanımı ile verilerin saklandığı veri merkezlerinin harcadığı enerji nedeniyle ortaya çıkan sera gazı salımıdır.","ornek":"Otelin güvenlik kameralarının gece gündüz kaydettiği görüntüler sürekli çalışan bilgisayarların bulunduğu bir veri merkezinde saklanır.","sektor":"Dijital olan her şey kendiliğinden yeşil değildir: ekranlar, sunucular ve cihazlar da elektrik harcar, eskiyen cihaz elektronik atık olur. İkiz dönüşümün çelişkili yanıdır; çözüm, dijitali gerektiği kadar ve verimli kullanmaktır.","iliskili":["mg-9-012","mg-9-041","mg-9-014"],"kontrol":null,"kitapDisi":true,"cizim":"enerji"},{"id":"mg-9-045","konu":"9.2","terim":"İş gücü piyasasında dönüşüm","ingilizce":"Labour market transformation","tanim":"Yeşil ve dijital dönüşümle birlikte bazı işlerin azalması, bazılarının içeriğinin değişmesi ve yeni iş rollerinin ortaya çıkmasıdır.","ornek":"Bir kariyer sitesindeki otel ilanı: “Rezervasyon sistemlerini kullanabilen, çevre uygulamalarına duyarlı ön büro personeli aranıyor.”","sektor":"İş gücü piyasası, iş arayanlarla çalışan arayan işverenlerin buluştuğu ortamdır. İlanlarda istenen becerilere bakmak, piyasanın nereye gittiğini görmenin kolay yoludur: bugün birçok ilanda dijital beceri aranır.","iliskili":["mg-9-046","mg-9-048","mg-9-049"],"kontrol":null},{"id":"mg-9-046","konu":"9.2","terim":"Dönüşümde yeşil meslekler","ingilizce":"Green job","tanim":"Çevrenin korunmasına, kaynakların verimli kullanılmasına ya da kirliliğin azaltılmasına doğrudan katkı sağlayan meslek ve iştir.","ornek":"Büyük bir otelde sürdürülebilirlik sorumlusu enerji, su ve atık verisini izler, personel eğitimlerini düzenler, çevre belgelerinin denetimine hazırlık yapar.","sektor":"4. ünitede “yeşil iş” adıyla öğrendiğin kavramla aynı fikirdir; burada dönüşümün yarattığı meslekler ve yeşillenen mevcut meslekler açısından bakılır. Güneş enerjisi teknisyenliği, atık yönetimi ve enerji yöneticiliği bilinen örneklerdir. Var olan meslekler de yeşillenir: aşçı israfı azaltmayı, kat şefi temizlik kimyasalını doğru dozda kullanmayı öğrenir.","iliskili":["mg-9-047","mg-9-048","mg-9-020"],"kontrol":null,"cizim":"doga"},{"id":"mg-9-047","konu":"9.2","terim":"Yeşil yakalı çalışan","ingilizce":"Green-collar worker","tanim":"Çevreyi korumaya ve sürdürülebilirliğe katkı sağlayan işlerde çalışan kişidir.","ornek":"Otelin çatısındaki güneş panellerinin bakımını yapan teknisyen.","sektor":"Beden gücüyle çalışana “mavi yakalı”, ofiste çalışana “beyaz yakalı” denmesine benzetilerek türetilmiş bir addır. Yeşil dönüşüm ilerledikçe bu alanlarda yetişmiş çalışana duyulan ihtiyaç artar.","iliskili":["mg-9-046","mg-9-048","mg-9-045"],"kontrol":null,"gorsel":"f3f-solar-panel-teknisyeni"},{"id":"mg-9-048","konu":"9.2","terim":"Yeşil beceri","ingilizce":"Green skills","tanim":"Bir işi çevreye daha az zarar vererek ve kaynakları verimli kullanarak yapabilmek için gereken bilgi, beceri ve tutumlardır.","ornek":"Mutfak stajyeri atığı doğru kutuya ayırır, sebzeyi az fireyle doğrar, musluğu boşa akıtmaz.","sektor":"Yalnız çevre uzmanlarına değil, her çalışana gerekir. İş görüşmesinde “Atık ayrıştırmayı ve enerji tasarrufu kurallarını biliyorum” diyebilmek bir artıdır.","iliskili":["mg-9-049","mg-9-046","mg-9-050"],"kontrol":null},{"id":"mg-9-050","konu":"9.2","terim":"Dönüşümde beceri güncelleme","ingilizce":"Reskilling and upskilling","tanim":"İşi yeşil ya da dijital dönüşümle değişen çalışanın, yeni görevini yapabilmek için eğitim alarak becerilerini yenilemesi ve geliştirmesidir.","ornek":"Otel kâğıtsız check-in’e geçer; resepsiyon ekibi yeni sistemi ve konuğa nasıl yardım edeceğini öğrenmek için eğitim alır.","sektor":"Sektörde yeni bir iş için beceri edinmeye “reskilling”, mevcut işte beceriyi yükseltmeye “upskilling” denir. Dönüşümde yerini koruyanlar öğrenmeyi sürdürenlerdir; okul bitince öğrenme bitmez.","iliskili":["mg-9-049","mg-9-048","mg-9-051"],"kontrol":null,"kitapDisi":true,"cizim":"dijital"},{"id":"mg-9-051","konu":"9.2","terim":"Adil geçiş","ingilizce":"Just transition","tanim":"Yeşil ve dijital dönüşüm yapılırken işi değişen ya da ortadan kalkan çalışanların eğitim ve yeni iş imkânlarıyla desteklenmesini, yükün ve kazancın hakça paylaşılmasını savunan ilkedir.","ornek":"Otel çamaşırhanesini otomatik sisteme geçirirken çalışanlarına eğitim verir; onları yeni sistemin kullanımında ve başka bölümlerde görevlendirir.","sektor":"Dönüşümün fırsatları kadar tehditleri de vardır: herkes yeni teknolojiye aynı hızla uyum sağlayamaz. Kimseyi geride bırakmamak, sürdürülebilirliğin sosyal boyutunun gereğidir.","iliskili":["mg-9-050","mg-9-004","mg-9-054"],"kontrol":null,"kitapDisi":true,"cizim":"konusma"},{"id":"mg-9-057","konu":"9.2","terim":"Dijital dönüşüm odaklı iş rolleri","ingilizce":"Digital-focused job roles","tanim":"Veri, yazılım, güvenlik, otomasyon ve yapay zekâ alanlarında dijitalleşmeyle ortaya çıkan görevlerdir.","ornek":"Bir otel zinciri, rezervasyon verilerini inceleyerek doluluk raporu hazırlayan bir veri analisti arar.","sektor":"Dijital görevler otelde gelir yöneticisi (revenue manager), çevrim içi satış ve sosyal medya uzmanı ya da bilgi işlem sorumlusu gibi unvanlarla karşına çıkar. Bunlar otelcilik bilgisini dijital araçlarla birleştiren işlerdir.","iliskili":["mg-9-031","mg-9-049","mg-9-058"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-058","konu":"9.2","terim":"İkiz dönüşüm odaklı yetkinlikler","ingilizce":"Twin transition competencies","tanim":"Hem yeşil hem dijital becerileri birlikte gerektiren; teknik yeterliğin yanında çevresel ve etik sorumluluğu da içeren bilgi ve becerilerdir.","ornek":"Bir otelin teknik servis çalışanı, enerji izleme ekranını okuyabilir ve verinin gösterdiği israfı gidermek için ne yapılacağını önerebilir.","sektor":"Mutfak şefinin günlük israf kaydını okuyup ertesi günün üretim miktarını buna göre ayarlaması bir ikiz yetkinliktir: dijital veriyi okur, çevresel sonucu düşünür. Bu yetkinlik yalnız aracı kullanmayı değil, kullanılan verinin doğaya etkisini de düşünmeyi gerektiren bir bakıştır.","iliskili":["mg-9-041","mg-9-048","mg-9-049","mg-9-057"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-059","konu":"9.2","terim":"Dönüşen ve azalan işler","ingilizce":"Changing and declining jobs","tanim":"Otomasyon ve yapay zekâ yaygınlaştıkça rutin, tekrara dayalı ve kolay otomatikleştirilebilen görevlerde insan emeğine duyulan ihtiyacın azalması ya da işin yapılış biçiminin değişmesidir.","ornek":"Bir otelde elle yazılan oda listesi tabletten tutulmaya başlayınca kat görevlisinin işi kalkmaz, ama tableti kullanmayı öğrenmesi gerekir.","sektor":"Eskiden santral görevlisinin tek tek arayarak yaptığı uyandırma servisi (wake-up call) birçok otelde artık sistemle yapılır; görevli bu zamanı konuğun özel isteklerine ve sorunlarına ayırabilir. Azalan, işin kendisinden çok tekrarlayan kısmıdır: yeni sistemi öğrenen çalışanın işi değişir, ama bitmez; asıl risk öğrenmeyi bırakmaktır.","iliskili":["mg-9-060","mg-9-064","mg-9-050"],"kontrol":null,"cizim":"enerji"},{"id":"mg-9-060","konu":"9.2","terim":"Değişime direnç","ingilizce":"Resistance to change","tanim":"Çalışanın, yeni sistemin işini elinden alacağı korkusuyla ya da alışkanlığıyla değişime karşı çıkmasıdır.","ornek":"Yıllardır kâğıt listeyle çalışan görevli yeni uygulamayı “bu sistem işimi alacak” diyerek kullanmak istemez; eğitim ve açıklama bu kaygıyı azaltır.","sektor":"Otel yeni yazılıma geçerken en tecrübeli çalışanın “Ben defterimle daha hızlıyım” demesi olağan bir tepkidir; eğitim, deneme süresi ve açık bir dinleme bu direnci yumuşatır. Direncin altında çoğu zaman inat değil, işini kaybetme ya da yetersiz görünme endişesi vardır.","iliskili":["mg-9-059","mg-9-050","mg-9-051"],"kontrol":null,"cizim":"enerji"},{"id":"mg-9-061","konu":"9.2","terim":"İkiz dönüşümde çelişkili durumlar","ingilizce":"Contradictions in twin transition","tanim":"Bir çözümün teknolojik açıdan yararlı görünürken çevresel ya da toplumsal açıdan yeni sorun yaratabildiği durumlardır.","ornek":"Bir otel her odaya sensör taktırır; enerji tasarrufu sağlanır, ama sensörlerin ömrü dolunca elektronik atık oluşur.","sektor":"Yeni bir sistem alınırken yalnız “ne kazandırır?” diye değil, “yan etkisi ne olur?” diye de sorulur: otelde kâğıtsız check-in kâğıt tasarrufu sağlar, ama dijital işlemden çekinen konuğu zorlayabilir. İyi karar çelişkiyi görüp önlem alanın kararıdır.","iliskili":["mg-9-062","mg-9-063","mg-9-064","mg-9-041"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-062","konu":"9.2","terim":"Doğal kaynak tüketimi çelişkisi","ingilizce":"Natural resource contradiction","tanim":"Dijital cihaz ve bataryaların üretiminde değerli madenlerin gerekmesi, bu madenlerin çıkarılmasının da çevresel ve toplumsal sorun yaratabilmesidir.","ornek":"Otelin tüm odalarına tablet alması konforu artırır, ama her tabletin yapımı için maden çıkarılmıştır.","sektor":"Bir otelin her yenilemede yeni tablet, televizyon ya da sensör alması bu cihazların yapımında kullanılan madenlere duyulan ihtiyacı artırır. Satın alma bölümü cihazı yalnız fiyatına değil, kaç yıl kullanılabileceğine ve onarılıp onarılamayacağına da bakarak seçerse bu çelişki küçülür; ömrü uzatmak en sade çevresel katkıdır.","iliskili":["mg-9-061","mg-9-040","mg-9-046"],"kontrol":null,"cizim":"doga"},{"id":"mg-9-063","konu":"9.2","terim":"Küçük işletmeler için maliyet çelişkisi","ingilizce":"Cost contradiction for small businesses","tanim":"İkiz dönüşümün sensör, yazılım ve verimli makine gibi yatırımlar gerektirmesi nedeniyle büyük işletmelerin bunu kolay, küçük işletmelerin zor yapabilmesidir.","ornek":"Küçük bir pansiyon bütçesi yetmediği için enerji izleme sistemi alamazken zincir otel aynı sistemi tüm şubelerine kurar.","sektor":"Küçük bir pansiyon enerji izleme sistemi alamasa da LED aydınlatma, sayaç okuma defteri, ayrı atık kutuları ve havlu yeniden kullanım kartı gibi düşük maliyetli adımlarla dönüşüme başlayabilir. Önemli olan sistemin büyüklüğü değil, atılan adımın gerçek ve sürekli olmasıdır.","iliskili":["mg-9-061","mg-9-051","mg-9-064"],"kontrol":null,"cizim":"para-butce"},{"id":"mg-9-064","konu":"9.2","terim":"İstihdam ve verimlilik çelişkisi","ingilizce":"Employment and productivity contradiction","tanim":"Otomasyonun üretimi hızlandırıp hatayı azaltırken bazı çalışanların görevlerinin azalmasına ya da değişmesine yol açabilmesidir.","ornek":"Bir restoranda siparişler tabletten alınınca hata azalır, ama sipariş yazmakla görevli kişinin işi değişir; servis ya da konuk ilişkilerine yönlendirilir.","sektor":"Kiosk ve mobil check-in yaygınlaşınca resepsiyonda kayıt işlemine harcanan zaman azalır; iyi yönetilen otelde bu zaman konuğu karşılamaya, sorun çözmeye ve özel isteklere ayrılır. Verimlilik kazancı çalışan yeni görevine hazırlandığında herkesin kazancıdır.","iliskili":["mg-9-059","mg-9-061","mg-9-031"],"kontrol":null,"cizim":"enerji"},{"id":"mg-9-007","konu":"9.3","terim":"Kaynak tüketimi","ingilizce":"Resource consumption","tanim":"Bir iş sürecinde kullanılan su, elektrik, yakıt, hammadde, yardımcı malzeme, zaman ve iş gücü miktarıdır.","ornek":"Kat şefi ay sonunda tabloya bakar: çamaşırhanede yıkanan çarşaf sayısı, harcanan su ve deterjan.","sektor":"Bir iş sürecini incelerken ilk sorulan sorudur: bu işte ne, ne kadar harcanıyor? Ölçülmeyen tüketim azaltılamaz; oteller bu yüzden sayaç okur ve kayıt tutar.","iliskili":["mg-9-008","mg-9-052","mg-9-006"],"kontrol":null,"gorsel":"sektor-damlayan-musluk"},{"id":"mg-9-008","konu":"9.3","terim":"İş sürecinde kaynak verimliliği","ingilizce":"Resource efficiency","tanim":"Aynı işin daha az kaynak kullanarak, daha az atık oluşturarak ve kaliteyi düşürmeden yapılabilmesidir.","ornek":"Otel, eski duş başlıklarını su tasarruflu olanlarla değiştirir: konuk aynı rahatlıkta duş alır, harcanan su azalır.","sektor":"Kaynak verimliliği programın anahtar kavramlarındandır. Tasarruf konuğu rahatsız ederek yapılmaz: verimlilik, konuk farkı hissetmeden daha az kaynak harcamaktır. İşletme için daha düşük fatura, çevre için daha az yük demektir.","iliskili":["mg-9-007","mg-9-014","mg-9-006"],"kontrol":null},{"id":"mg-9-011","konu":"9.3","terim":"Sera gazı salımı","ingilizce":"Greenhouse gas emissions","tanim":"Karbondioksit ve metan gibi atmosferde ısıyı tutan gazların, yakıt yakılması ve benzeri faaliyetler sonucunda havaya verilmesidir.","ornek":"Otelin jeneratörü mazot yaktığında, servis aracı yakıt harcadığında havaya karbondioksit karışır.","sektor":"Atmosferde ısıyı tutarak yeryüzünün ısınmasına yol açan gazlara sera gazı denir. Kömür, petrol ve doğal gaz gibi fosil yakıtlar yakıldıkça miktarları artar. Çöpe giden yemek de çürürken metan çıkarır.","iliskili":["mg-9-010","mg-9-012","mg-9-013"],"kontrol":null,"gorsel":"m9-industry-smoke"},{"id":"mg-9-012","konu":"9.3","terim":"İş sürecinin karbon ayak izi","ingilizce":"Carbon footprint of a process","tanim":"Bir işin baştan sona yapılması sırasında harcanan enerji, yakıt ve malzeme nedeniyle atmosfere verilen sera gazı miktarının ölçüsüdür.","ornek":"Bir otel odasında bir gecelik konaklamanın karbon ayak izi hesaplanırken ısıtma, soğutma, aydınlatma, çamaşır ve kahvaltı birlikte düşünülür.","sektor":"Karbon ayak izi programın anahtar kavramlarındandır; karbondioksit cinsinden ifade edilir. Otelde büyük payı çoğu zaman enerji alır: ısıtma, soğutma, sıcak su. Bir iş sürecini çözümlerken kaynak tüketimi ve dijitalleşme düzeyiyle birlikte bakılan üç şeyden biridir.","iliskili":["mg-9-011","mg-9-007","mg-9-040"],"kontrol":null,"cizim":"enerji"},{"id":"mg-9-013","konu":"9.3","terim":"Yenilenebilir enerji kullanımı","ingilizce":"Use of renewable energy","tanim":"İşletmenin ihtiyaç duyduğu ısının ya da elektriğin bir bölümünü güneş ve rüzgâr gibi kendini sürekli yenileyen kaynaklardan karşılamasıdır.","ornek":"Ege’de bir otelin çatısındaki güneş kolektörleri odaların sıcak suyunu ısıtır; güneşli günde kazan daha az çalışır.","sektor":"Güneş, rüzgâr, akarsu ve yer altı ısısı yenilenebilir kaynaklardır; kömür, petrol ve doğal gaz ise tükenen fosil yakıtlardır. Türkiye güneşi bol bir ülkedir: birçok otel sıcak suyunu güneşle ısıtır. Yakıt gideri ve karbon ayak izi birlikte düşer.","iliskili":["mg-9-011","mg-9-014","mg-9-012"],"kontrol":null,"gorsel":"t13e-cati-gunes-paneli"},{"id":"mg-9-014","konu":"9.3","terim":"Enerji verimliliği önlemleri","ingilizce":"Energy efficiency measures","tanim":"Aynı ısıtma, soğutma ve aydınlatma hizmetini daha az enerjiyle vermek için yapılan yalıtım, verimli cihaz ve doğru kullanım gibi uygulamalardır.","ornek":"Otel koridorlarındaki ampuller LED ile değiştirilir, hareket sensörü takılır: koridor boşken ışık kısılır, biri geçerken açılır.","sektor":"En temiz enerji, hiç harcanmayan enerjidir. Konfordan ödün verilmez; boşa giden enerji kesilir. Boş salonun klimasını kapatmak gibi küçük alışkanlıklar da bu önlemlerin parçasıdır.","iliskili":["mg-9-008","mg-9-015","mg-9-043"],"kontrol":null,"gorsel":"m9-led-bulbs"},{"id":"mg-9-015","konu":"9.3","terim":"Kart anahtarlı enerji tasarrufu","ingilizce":"Key card energy-saving switch","tanim":"Oda kartı kapının yanındaki yuvaya takıldığında odanın elektriğini açan, kart çıkarılınca kısa süre sonra kesen sistemdir.","ornek":"Konuk saat 10.00’da kartını alıp plaja iner; odada açık kalan lambalar ve klima kısa süre sonra kendiliğinden kapanır.","sektor":"Sektörde “energy saver” denir. Konuk odada yokken harcanan enerjiyi önler. Yuvaya başka bir kart bırakmak sistemi boşa çıkarır; kat görevlisi boş odada böyle bir kart görürse kendi başına karar vermez, şefine bildirir.","iliskili":["mg-9-014","mg-9-044","mg-9-016"],"kontrol":null,"kitapDisi":true,"gorsel":"t12l-kart-kapi-kilidi"},{"id":"mg-9-016","konu":"9.3","terim":"Havlu ve çarşaf yeniden kullanım programı","ingilizce":"Towel and linen reuse programme","tanim":"Konuğa, havlusunun ve çarşafının her gün değil, kendisi istediğinde değiştirilmesi seçeneğinin sunulduğu uygulamadır.","ornek":"Banyodaki kartta yazar: “Havlunuzu askıya asarsanız yeniden kullanacağınızı, yere bırakırsanız değiştirilmesini istediğinizi anlarız.”","sektor":"Daha az yıkama; daha az su, enerji ve deterjan demektir. Kural iki yönlüdür: kat görevlisi asılı havluyu değiştirmez, yerdeki havluyu mutlaka değiştirir. Konuğun tercihi her zaman önce gelir.","iliskili":["mg-9-008","mg-9-015","mg-9-025"],"kontrol":null,"kitapDisi":true,"gorsel":"t14zb-havlu-yeniden-kullanim"},{"id":"mg-9-018","konu":"9.3","terim":"Gıda israfı takibi","ingilizce":"Food waste tracking","tanim":"Mutfakta ve restoranda çöpe giden yiyeceğin tartılarak ya da kaydedilerek hangi aşamada ve neden israf olduğunun izlenmesidir.","ornek":"Açık büfe kahvaltı bittiğinde mutfak ekibi kalan yiyecekleri türüne göre tartar; her gün en çok artan ürün ertesi gün daha az çıkarılır.","sektor":"Açık büfe, otelde israfın en görünür olduğu yerdir. Kaydı tutulan israf azalır: aşçıbaşı ne kadar üreteceğini tahmine göre değil, veriye göre belirler. Kayıt gerçek rakamla tutulursa işe yarar.","iliskili":["mg-9-017","mg-9-030","mg-9-034"],"kontrol":null,"cizim":"gastronomi"},{"id":"mg-9-019","konu":"9.3","terim":"Yerel tedarik","ingilizce":"Local sourcing","tanim":"İşletmenin ihtiyaç duyduğu ürün ve hizmetleri olabildiğince yakın çevresindeki üreticilerden ve satıcılardan almasıdır.","ornek":"Ayvalık’taki bir otel zeytinyağını ilçedeki üreticiden, sebzesini haftalık köy pazarından alır; menüde ürünün nereden geldiği yazar.","sektor":"Ürün daha kısa yoldan gelir: taşımadan kaynaklanan salım azalır, ürün daha taze olur. Para yörede kalır, konuk da bölgenin gerçek lezzetini tadar. Çevresel, ekonomik ve sosyal boyutun buluştuğu yerdir.","iliskili":["mg-9-004","mg-9-003","mg-9-012"],"kontrol":null,"gorsel":"mg-yerel-pazar"},{"id":"mg-9-027","konu":"9.3","terim":"Dijitalleşme basamakları","ingilizce":"Stages of digitalisation","tanim":"Bir işin önce bilgilerinin dijital ortama aktarılması, sonra dijital araçlarla yürütülmesi, en sonunda bütünüyle yeniden tasarlanması biçiminde ilerleyen yoldur.","ornek":"Kat hizmetlerinde oda durumları eskiden kâğıt listeye yazılırdı; şimdi kat görevlisi tabletten “oda hazır” der, resepsiyon aynı anda görür.","sektor":"İlk basamağa sayısallaştırma, ikincisine dijitalleşme, sonuncusuna dijital dönüşüm denir. Kâğıt formu tarayıp bilgisayara atmak ilk basamaktır; işin akışı değişmedikçe dönüşümden söz edilmez.","iliskili":["mg-9-026","mg-9-028","mg-9-036"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-028","konu":"9.3","terim":"Dijitalleşme düzeyi","ingilizce":"Level of digitalisation","tanim":"Bir iş sürecindeki adımların ne kadarının dijital araçlarla, ne kadarının elle ve kâğıtla yürütüldüğünü gösteren ölçüdür.","ornek":"Bir pansiyonda rezervasyonlar internetten gelir, ama deftere elle yazılır, hesap elle kesilir: süreç yarı dijitaldir.","sektor":"Bir iş sürecini çözümlerken kaynak tüketimi ve karbon ayak iziyle birlikte bakılır. Düşük düzey kusur değil, fırsat demektir: nerede elle iş, çift kayıt ve kâğıt varsa orada iyileştirme payı vardır.","iliskili":["mg-9-027","mg-9-052","mg-9-007"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-029","konu":"9.3","terim":"Veri","ingilizce":"Data","tanim":"Ölçüm, sayım ya da kayıt yoluyla elde edilen; işlenip yorumlandığında bilgiye dönüşen ham sayılar, metinler ve kayıtlardır.","ornek":"Otelin elektrik sayacının her saat kaydettiği değer, restoranda bir günde kaç kişinin yemek yediği, hangi odanın saat kaçta boşaldığı.","sektor":"Dijital dönüşümün hammaddesidir. Tek başına bir sayı pek bir şey söylemez; karşılaştırıldığında anlam kazanır. Yanlış girilen veri yanlış karara götürür: sisteme yazdığın her kayıt bu yüzden önemlidir.","iliskili":["mg-9-030","mg-9-039","mg-9-033"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-9-036","konu":"9.3","terim":"Kâğıtsız ofis","ingilizce":"Paperless office","tanim":"Belge, form ve yazışmaların kâğıda basılmadan dijital ortamda hazırlandığı, onaylandığı ve saklandığı çalışma düzenidir.","ornek":"Otelin muhasebesi faturayı e-fatura olarak gönderir; vardiya raporu çıktı alınmadan ortak sistemde paylaşılır.","sektor":"Kâğıt, toner ve arşiv alanı azalır; aranan belge çabuk bulunur. Dijital adım aynı zamanda yeşil bir adımdır: ikiz dönüşümün en kolay görülen örneğidir. Gerekmedikçe çıktı almamak her çalışanın katkısıdır.","iliskili":["mg-9-027","mg-9-037","mg-9-038"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-037","konu":"9.3","terim":"Kâğıtsız check-in","ingilizce":"Paperless check-in","tanim":"Konuğun giriş kaydının, basılı form doldurulmadan telefon, tablet ya da ekran üzerinden tamamlanmasıdır.","ornek":"Konuk yoldayken otelden gelen bağlantıya tıklar, bilgilerini onaylar; otele vardığında resepsiyonda kimliğini gösterip anahtarını alır.","sektor":"Sıra kısalır, basılı form azalır; görevli ekrana veri girmek yerine konuğu karşılamaya zaman ayırır. Dijital yolu kullanmak istemeyen ya da zorlanan konuğun kaydı her zaman bankoda yapılır.","iliskili":["mg-9-036","mg-9-038","mg-9-039"],"kontrol":null,"kitapDisi":true},{"id":"mg-9-038","konu":"9.3","terim":"Dijital menü","ingilizce":"Digital menu","tanim":"Restoran menüsünün basılı kart yerine, konuğun telefonuyla karekod okutarak ya da bir ekrandan görüntülediği biçimidir.","ornek":"Havuz barındaki masada küçük bir karekod durur; konuk okutur, menüyü kendi dilinde görür.","sektor":"Fiyat ya da ürün değişince yeniden baskı gerekmez: kâğıt ve maliyet azalır, biten ürün menüden hemen kaldırılabilir. Telefon kullanmak istemeyen ya da zorlanan konuk için basılı menü hazır tutulur.","iliskili":["mg-9-036","mg-9-037","mg-9-027"],"kontrol":null,"cizim":"gastronomi"},{"id":"mg-9-052","konu":"9.3","terim":"İş süreci analizi","ingilizce":"Business process analysis","tanim":"Bir işin baştan sona hangi adımlardan oluştuğunu, her adımda hangi kaynağın harcandığını ve nerede iyileştirme yapılabileceğini inceleme çalışmasıdır.","ornek":"Kahvaltı servisi adım adım yazılır: satın alma, depolama, hazırlık, büfe, toplama, bulaşık. Her adımın yanına harcanan enerji, su ve çıkan atık not edilir.","sektor":"Dönüşüm açısından üç şeye bakılır: kaynak tüketimi, dijitalleşme düzeyi ve karbon ayak izi. Balık kılçığı diyagramı gibi araçlar sorunun nedenlerini başlıklara ayırmaya yarar.","iliskili":["mg-9-007","mg-9-028","mg-9-053"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-9-065","konu":"9.3","terim":"İş süreci","ingilizce":"Business process","tanim":"Bir ürünün üretilmesi ya da bir hizmetin sunulması için izlenen aşamaların bütünüdür.","ornek":"Otelde kahvaltı süreci: hazırlık, malzeme kullanımı, servis, kontrol, kayıt ve atık yönetimi aşamalarından oluşur.","sektor":"Konuk çıkış yaptıktan sonra odanın temizlenmesi, kat şefi tarafından kontrol edilmesi ve resepsiyona “hazır” bilgisinin ulaşması bir iş sürecidir. Süreçte bir adım gecikirse sıradaki konuk bekler; bu yüzden süreci iyileştirmenin ilk adımı aşamaları sırayla görmektir.","iliskili":["mg-9-052","mg-9-066","mg-9-069","mg-9-070"],"kontrol":null,"cizim":"saat-zaman"},{"id":"mg-9-066","konu":"9.3","terim":"Fire oranı","ingilizce":"Wastage rate","tanim":"Üretim sırasında kullanılan malzemenin ne kadarının işe yaramaz hâle gelip kaybolduğunu gösteren orandır.","ornek":"Sabah 09.00, otel mutfağında aşçı kahvaltı için sebze doğrar; kabukları ince soyarsa çöpe giden kısım azalır ve fire oranı düşer.","sektor":"Mutfak şefi aynı ürünün fire oranını farklı zamanlarda ya da farklı kesim yöntemlerinde karşılaştırırsa, oranın yüksek çıktığı yerde kesme tekniği, saklama koşulu ya da ürün kalitesi sorgulanır. Fireyi ölçmeyen mutfak israfı da azaltamaz; ölçüm bu yüzden ilk adımdır.","iliskili":["mg-9-065","mg-9-008","mg-9-018"],"kontrol":null,"cizim":"yangin"},{"id":"mg-9-067","konu":"9.3","terim":"Plansız dijitalleşme","ingilizce":"Unplanned digitalisation","tanim":"İhtiyaç gözetilmeden yapılan, işletmeye mali yük getiren ve gereksiz elektronik atığa yol açabilen dijitalleşmedir.","ornek":"Küçük bir pansiyon, kimsenin kullanmadığı pahalı bir otel yazılımı alır; para boşa gider, eski bilgisayarlar da atıl kalır.","sektor":"Mutfak, kat ve resepsiyon birbiriyle konuşmayan ayrı programlar alırsa otelde aynı bilgi üç yere elle girilir; para yanında zaman da boşa gider. Dijitalleşme kararı “Hangi sorunu çözüyor?” sorusuyla başlamalıdır.","iliskili":["mg-9-070","mg-9-068","mg-9-028"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-068","konu":"9.3","terim":"Dijital kayıt sistemi","ingilizce":"Digital record system","tanim":"Bilgilerin kâğıt yerine bilgisayar ya da bulut ortamında kaydedildiği ve izlenebildiği sistemdir.","ornek":"Kat görevlisi odanın hazır olduğunu tabletten girer; resepsiyon aynı anda görür.","sektor":"Konuğun bildirdiği klima arızası ya da bulunan bir eşya otelin dijital sistemine girildiğinde gece ekibinin notu sabah ekibine eksiksiz ulaşır ve kimse aynı soruyu konuğa ikinci kez sormaz. Kaydın yapılması kadar doğru girilmesi de önemlidir: yanlış yazılmış bir oda numarası işi yanlış kapıya götürebilir, bu yüzden kaydı dikkatle girmek işin parçasıdır.","iliskili":["mg-9-037","mg-9-029","mg-9-036"],"kontrol":null,"cizim":"resepsiyon"},{"id":"mg-9-069","konu":"9.3","terim":"Yeşil dönüşüm potansiyeli","ingilizce":"Green transition potential","tanim":"Bir iş sürecinin çevreye daha az zarar verecek ve kaynakları daha verimli kullanacak biçimde iyileştirilebilme imkânıdır.","ornek":"Otelin çamaşırhanesinde suyu ve enerjiyi azaltacak bir makine değişikliği, o sürecin yeşil dönüşüm potansiyelidir.","sektor":"Yeşil dönüşüm potansiyeli bir otelde en çok sıcak su, elektrik ve su harcanan süreçlerde aranır: çamaşırhane, mutfak ve havuz ısıtması gibi. Havuzu geceleri örtüyle kapatmak kadar basit bir değişiklik bile ısı kaybını azaltabildiği için potansiyelin ilk kaynağı büyük yatırım değil, dikkatli gözlemdir.","iliskili":["mg-9-065","mg-9-070","mg-9-012"],"kontrol":null,"cizim":"doga"},{"id":"mg-9-070","konu":"9.3","terim":"Dijital dönüşüm potansiyeli","ingilizce":"Digital transformation potential","tanim":"Bir iş sürecinin dijital teknolojilerle daha hızlı, güvenilir, ölçülebilir ve verimli hâle getirilebilme imkânıdır.","ornek":"Kâğıtla yürütülen oda temizlik takibinin tabletle yapılması, o sürecin dijital dönüşüm potansiyelidir.","sektor":"Her dijital çözüm her işletmeye uygun değildir; ihtiyaç, maliyet, çalışan becerisi ve beklenen fayda birlikte değerlendirilir (ders kitabına göre).","iliskili":["mg-9-069","mg-9-067","mg-9-026"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-001","konu":"9.4","terim":"İşletmede sürdürülebilirlik","ingilizce":"Sustainability in business","tanim":"Bir işletmenin, bugünkü kazancı uğruna çevreyi, çalışanını ve yöresini tüketmeden, gelecekte de var olabilecek biçimde çalışması anlayışıdır.","ornek":"Bir sahil otelinin önündeki koy: otel atık suyunu arıtmadan denize verirse birkaç yıl sonra o koyda yüzülmez, konuk da gelmez.","sektor":"Sürdürülebilirlik programın anahtar kavramlarındandır: bugünün ihtiyaçlarını, gelecek kuşakların imkânlarını tüketmeden karşılamak demektir. Üç boyutu vardır: çevresel, ekonomik, sosyal. Turizm sattığı şeyi doğadan ve kültürden alır; bunlar tükenirse otelin satacak bir şeyi kalmaz.","iliskili":["mg-9-002","mg-9-003","mg-9-004"],"kontrol":null,"gorsel":"m9-esolarhotel"},{"id":"mg-9-025","konu":"9.4","terim":"İşletmede yeşil yıkama riski","ingilizce":"Greenwashing","tanim":"Bir işletmenin, gerçekte yapmadığı ya da çok az yaptığı çevre çalışmalarını abartarak kendini çevre dostu gibi göstermesidir.","ornek":"Broşürüne “doğa dostu otel” yazan ama atığını ayırmayan, enerji ve su tüketimini hiç ölçmeyen bir işletme.","sektor":"Sektörde “greenwashing” denir. 4. ünitede “yeşil yıkama” adıyla öğrendiğin kavramın aynısıdır; yeşil aklama da denir. İşletmede en çok broşür, reklam ve sosyal medya duyurularında karşına çıkar. Dürüstlük ilkesine aykırıdır ve konuğu yanıltır; fark edildiğinde güven bir anda gider. Doğrusu, yalnız gerçekten yapılanı ve kanıtlanabileni söylemektir.","iliskili":["mg-9-023","mg-9-054","mg-9-016"],"kontrol":null,"kitapDisi":true,"cizim":"doga"},{"id":"mg-9-034","konu":"9.4","terim":"Kaynak yönetiminde yapay zekâ","ingilizce":"Artificial intelligence (AI) in resource management","tanim":"Geçmiş verilerden öğrenerek tahmin yapabilen yazılımların enerji, su ve malzeme kullanımını planlamak için kullanılmasıdır.","ornek":"Yazılım geçmiş doluluk verisine ve hava durumuna bakıp yarınki kahvaltıda kaç kişilik hazırlık gerektiğini önerir; mutfak gereğinden fazla üretmez.","sektor":"Yapay zekâ programın anahtar kavramlarındandır. Önerir, sorumluluk almaz: son sözü işi bilen insan söyler. Tahmin, beslendiği verinin doğruluğu kadar iyidir.","iliskili":["mg-9-030","mg-9-018","mg-9-029"],"kontrol":null,"cizim":"yapay-zeka"},{"id":"mg-9-042","konu":"9.4","terim":"Akıllı bina","ingilizce":"Smart building","tanim":"Aydınlatma, ısıtma, soğutma ve güvenlik gibi sistemleri sensörler ve yazılımla izleyip ihtiyaca göre kendiliğinden ayarlayan binadır.","ornek":"Toplantı salonu boşaldığında ışıklar söner, havalandırma kısılır; ertesi sabahki toplantıdan önce salon kendiliğinden hazırlanır.","sektor":"Otelde bu işi gören yazılıma bina yönetim sistemi denir; teknik servis bütün binayı tek ekrandan izler. Konfor aynı kalırken boşa harcanan enerji azalır: ikiz dönüşümün binadaki hâlidir.","iliskili":["mg-9-043","mg-9-044","mg-9-035"],"kontrol":null},{"id":"mg-9-043","konu":"9.4","terim":"Enerji izleme sistemi","ingilizce":"Energy monitoring system","tanim":"Bir binanın ya da bölümün ne zaman, nerede, ne kadar enerji harcadığını sayaç ve sensörlerle ölçüp ekranda gösteren sistemdir.","ornek":"Teknik müdür sabah ekrana bakar: gece 03.00’te mutfağın tüketimi olağandan yüksek görünür; nedeni açık unutulan bir fırındır.","sektor":"Fatura ay sonunda yalnız toplamı söyler; izleme sistemi tüketimin yerini ve saatini gösterir. İsrafın nerede olduğunu bilen ekip çözümü de bulur. Ekranda olağan dışı bir şey gören stajyer kendi başına müdahale etmez, amirine bildirir.","iliskili":["mg-9-042","mg-9-014","mg-9-030"],"kontrol":null},{"id":"mg-9-044","konu":"9.4","terim":"Akıllı termostat","ingilizce":"Smart thermostat","tanim":"Oda sıcaklığını, odada biri olup olmadığına ve belirlenen programa göre kendiliğinden ayarlayan, uzaktan da yönetilebilen sıcaklık kontrol cihazıdır.","ornek":"Konuk çıkış yapınca sistem odayı “boş” gösterir; termostat klimayı tasarruf konumuna alır, yeni konuk gelmeden önce odayı yeniden hazırlar.","sektor":"Boş odayı gereksiz yere ısıtıp soğutmayı önler. Konuk odadayken sıcaklığı yine kendisi seçer: tasarruf konforun önüne geçmez.","iliskili":["mg-9-042","mg-9-015","mg-9-041"],"kontrol":null,"gorsel":"t14e-duvar-termostat"},{"id":"mg-9-053","konu":"9.4","terim":"İkiz dönüşüm odaklı iş modeli","ingilizce":"Twin transition business model","tanim":"Bir işletmenin nasıl değer ürettiğini ve nasıl kazandığını anlatan planın, yeşil ve dijital çözümler birlikte kullanılarak kurulmuş biçimidir.","ornek":"Küçük bir otel planını yazar: sıcak su güneşten, rezervasyon ve kayıt dijital, kahvaltı yerel üreticiden, israf her hafta ölçülür.","sektor":"İnovasyon, yani yeni ve işe yarar bir fikri hayata geçirmek, böyle bir modelin çekirdeğidir. İyi model üç soruya birlikte cevap verir: uygulanabilir mi, verimli mi, sürdürülebilir mi?","iliskili":["mg-9-041","mg-9-052","mg-9-020"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-054","konu":"9.4","terim":"Dönüşümde etik","ingilizce":"Ethics in transition","tanim":"Yeşil ve dijital dönüşüm kararları alınırken dürüstlüğün, insan haklarının, veri gizliliğinin ve doğaya karşı sorumluluğun gözetilmesidir.","ornek":"Otel yönetimi enerji tasarrufu için odalara doluluk sensörü taktırır; sensörlerin görüntü ya da ses kaydetmediğini konuklara açıkça bildirir.","sektor":"Etik, programın bu ünitedeki anahtar kavramlarındandır. Üç soru yol gösterir: Verdiğimiz çevre sözü doğru mu (yoksa yeşil yıkama mı)? Topladığımız veriyi koruyor muyuz? Değişimden etkilenen çalışanı gözetiyor muyuz?","iliskili":["mg-9-025","mg-9-039","mg-9-051"],"kontrol":null,"cizim":"dijital"},{"id":"mg-9-071","konu":"9.4","terim":"Yapay zekâ destekli talep tahmini","ingilizce":"AI-supported demand forecasting","tanim":"Hangi ürünün ne kadar gerekeceğini geçmiş verilere bakarak daha doğru kestirmek için yapay zekâdan yararlanılmasıdır.","ornek":"Otel mutfağı, geçmiş doluluk verisinden yarınki kahvaltı miktarını tahmin eder; fazla üretim ve israf azalır.","sektor":"Geçmiş yılların doluluğu, hafta sonları, bayramlar ve etkinlikler birlikte okunursa kaç konuk geleceği daha doğru tahmin edilir; mutfak ona göre üretir, kat hizmetleri ve çamaşırhane ona göre personel planlar. Tahmin yapay zekâdan gelse de son karar verinin doğruluğunu bilen insana aittir.","iliskili":["mg-9-034","mg-9-072","mg-9-018"],"kontrol":null,"cizim":"yapay-zeka"},{"id":"mg-9-072","konu":"9.4","terim":"Veriyle lojistik planlama","ingilizce":"Data-driven logistics planning","tanim":"Tedarik, taşıma ve dağıtım süreçlerinin veri analiziyle planlanıp daha kısa ve ekonomik rotaların seçilmesidir.","ornek":"Otelin temizlik malzemesini getiren araç, siparişleri tek rotada toplayınca yakıt harcaması azalır.","sektor":"Havalimanı transferi yapan bir otel ya da acente, uçuş saatlerine ve yolcu sayısına bakarak birkaç gelişi tek araçta birleştirebilir; böylece yakıt, sürücü zamanı ve karbon salımı azalır. Ancak birleştirme yolcunun beklemesini uzatabilir; bu yüzden planlamada maliyet kadar yolcunun bekleme süresi de hesaba katılır.","iliskili":["mg-9-071","mg-9-012","mg-9-019"],"kontrol":null,"cizim":"veri-guvenlik"},{"id":"mg-9-073","konu":"9.4","terim":"İş modelini değerlendirme ölçütleri","ingilizce":"Business model evaluation criteria","tanim":"Bir iş modelinin uygulanabilirlik, verimlilik ve sürdürülebilirlik açısından sınanmasında kullanılan üç ölçüttür.","ornek":"Bir kafenin güneş enerjili plan önerisi için sorulur: bugün yapılabilir mi, kaynak tasarrufu sağlar mı, yıllarca sürer mi?","sektor":"Otel yönetimi yeni bir öneriyi, örneğin tüm odalara enerji tasarruf sistemi kurmayı, “güzel fikir” diye kabul etmez; bugün bütçeyle yapılabilir mi, faturayı gerçekten düşürür mü, yıllarca işler mi diye sorar. Üç sorudan biri yanıtsız kalmışsa öneri eksiktir.","iliskili":["mg-9-053","mg-9-074"],"kontrol":null,"cizim":"enerji"},{"id":"mg-9-074","konu":"9.4","terim":"Geleneksel iş modeli","ingilizce":"Traditional business model","tanim":"Kaynakların ölçülmeden kullanıldığı, atığın süreç sonunda ortaya çıkan yük sayıldığı ve kayıtların kâğıt ya da elle tutulduğu iş modelidir.","ornek":"Enerji ve su faturasını yalnız ay sonunda toplam olarak gören, kayıtları defterde tutan küçük bir otel.","sektor":"Küçük bir otelde su ve elektrik sayacını ay sonunda bir kez okuyup deftere yazan yönetim fazla harcamayı ancak fatura gelince fark eder; kaçağın hangi gün başladığı, hangi bölümden geldiği bilinmediği için haftalarca sürebilir. Geleneksel modelin sorunu eski olması değil, ölçmeden yönetmesidir.","iliskili":["mg-9-053","mg-9-073"],"kontrol":null,"cizim":"enerji"}],"sorular":[{"id":"mg-9-s01","tur":"coktan-secmeli","soru":"Bugünün ihtiyaçlarını, gelecek kuşakların imkânlarını tüketmeden karşılama anlayışı hangisidir?","secenekler":["Yeşil büyüme","Kaynak verimliliği","Sürdürülebilirlik","Döngüsel ekonomi"],"dogru":2,"aciklama":"Sürdürülebilirlik, bugünü yaşarken yarının imkânlarını tüketmemektir. Yeşil büyüme ekonominin büyüme biçimini, döngüsel ekonomi ürünlerin kullanım ömrünü anlatır; ikisi de buna hizmet eder ama anlayışın kendisi değildir."},{"id":"mg-9-s02","tur":"coktan-secmeli","soru":"Hangisi sürdürülebilirliğin ekonomik boyutuna örnektir?","secenekler":["Butik otelin kışın da program düzenleyip personeli çalıştırması","Boş odada açık kalan klimanın kat görevlisince kapatılması","Yöredeki çömlek ustalarının ürünlerinin otel lobisinde sergilenmesi","Damlatan musluğun fark edilip teknik servise bildirilmesi"],"dogru":0,"aciklama":"Ekonomik boyut, işletmenin yıllarca kazanç sağlayıp iş vermeyi sürdürebilmesidir. Klima ve musluk örnekleri çevresel, çömlek sergisi ise sosyal boyuta girer."},{"id":"mg-9-s03","tur":"coktan-secmeli","soru":"Sürdürülebilir Kalkınma Amaçları için hangisi doğrudur?","secenekler":["Yalnız turizm işletmeleri için yazılmış 17 kural listesidir.","Avrupa Birliğinin yalnız üye ülkeler için belirlediği 17 hedeftir.","BM üyesi ülkelerin imzaladığı 12 maddelik iklim belgesidir.","BM üyesi ülkelerin ortak olarak kabul ettiği 17 küresel amaçtır."],"dogru":3,"aciklama":"Amaçlar yoksulluğu bitirmek ve gezegeni korumak için BM üyesi ülkelerce birlikte kabul edilmiş 17 küresel hedeftir; her sektörü ilgilendirir. İklim sözleşmesi Paris Anlaşması’dır, ayrı bir kavramdır."},{"id":"mg-9-s04","tur":"coktan-secmeli","soru":"Hangisi kaynak verimliliğine örnektir?","secenekler":["Aylık su faturasını yalnız kayıt için dosyada saklamak","Eski duş başlıklarını su tasarruflu modellerle değiştirmek","Konuğa duşta geçireceği süreyi kısaltmasını şart koşmak","Havuzun suyunu daha sık yenileyerek temizlik düzeyini artırmak"],"dogru":1,"aciklama":"Kaynak verimliliği, aynı işi kaliteyi düşürmeden daha az kaynakla yapmaktır. Faturayı saklamak yalnızca kayıttır; konuğu kısıtlamak ise konforu düşürerek tasarruf etmektir."},{"id":"mg-9-s05","tur":"coktan-secmeli","soru":"Hangi faaliyet doğrudan sera gazı salımına yol açar?","secenekler":["Güneş kolektörüyle sıcak su elde edilmesi","Havlunun konuk isteğiyle yeniden kullanılması","Jeneratörde mazot yakılarak elektrik üretimi","Mutfak atığının ayrı kutularda toplanması"],"dogru":2,"aciklama":"Mazot gibi yakıtlar yandığında havaya karbondioksit karışır ve atmosfer ısıyı daha çok tutar. Güneş enerjisi yakıt yakmadan çalışır; havlu ve atık ayırma uygulamaları ise bu salımı artırmaz."},{"id":"mg-9-s06","tur":"coktan-secmeli","soru":"Bir otel odasında tek gecelik konaklamanın ısıtma, soğutma, aydınlatma, çamaşır ve kahvaltı kalemlerinden doğan toplam sera gazı ölçüsüne ne denir?","secenekler":["İş sürecinin karbon ayak izi","Kaynak tüketimi","Enerji verimliliği","İş sürecinde kaynak verimliliği"],"dogru":0,"aciklama":"Karbon ayak izi harcamaların atmosfere verdiği sera gazını ölçer. Kaynak tüketimi ise kullanılan su, elektrik gibi miktarları gösterir; salımı değil."},{"id":"mg-9-s07","tur":"coktan-secmeli","soru":"Bir otel, sıcak su ihtiyacının bir bölümünü yenilenebilir enerjiyle karşılamak istiyor. Hangisini yapmalıdır?","secenekler":["Eski kazanı daha verimli bir doğal gaz kazanıyla değiştirmelidir.","Çatıya güneş kolektörleri kurup suyu güneşle ısıtmalıdır.","Koridor ampullerini LED ampullerle değiştirmelidir.","Odalara kart anahtarlı enerji sistemi kurmalıdır."],"dogru":1,"aciklama":"Yenilenebilir enerji güneş ve rüzgâr gibi kendini yenileyen kaynaklardan gelir. Diğer üç uygulama enerjiyi daha az harcamayı sağlar (enerji verimliliği) ama kaynağı değiştirmez."},{"id":"mg-9-s08","tur":"coktan-secmeli","soru":"Hangisi döngüsel ekonomi anlayışına uygun bir uygulamadır?","secenekler":["Eskiyen çarşafları her sezon yenisiyle değiştirip çöpe atmak","Çarşaf sayısını azaltıp yıkama sıklığını artırmak","Tek kullanımlık çarşafa geçmek","Eskiyen çarşafları kesip temizlik bezi olarak kullanmak"],"dogru":3,"aciklama":"Döngüsel ekonomi, malzemeyi atmak yerine yeniden kullanarak ekonomide tutar. Çarşafı atmak ya da tek kullanımlığa geçmek “al, kullan, at” düzenidir; yıkamayı artırmak ise kaynak tüketimini yükseltir."},{"id":"mg-9-s09","tur":"coktan-secmeli","soru":"Hangi işletmenin davranışı yeşil yıkama riski taşır?","secenekler":["Atığını ayırıp bunu internet sitesinde hiç duyurmayan otel","Yeşil Anahtar başvurusu yapıp sonucu bekleyen, henüz duyuru yapmayan otel","“Doğa dostu” yazan ama atığını ayırmayan, tüketimini ölçmeyen otel","Su ve enerji tüketimini ölçüp her yıl rapor eden otel"],"dogru":2,"aciklama":"Yeşil yıkama, yapılmayan çevre çalışmalarını yapılmış gibi göstermektir. Duyurmamak, başvuruyu beklemek ya da ölçüm yapmak yanıltıcı değildir."},{"id":"mg-9-s10","tur":"coktan-secmeli","soru":"Bir otelin plajına verilen uluslararası çevre işareti hangisidir?","secenekler":["Mavi Bayrak","Yeşil Anahtar etiketi","Paris Anlaşması","Avrupa Yeşil Mutabakatı"],"dogru":0,"aciklama":"Mavi Bayrak, çevre, temizlik ve güvenlik koşullarını sağlayan plajlara, marinalara ve turizm teknelerine verilir. Yeşil Anahtar konaklama tesislerine verilen etikettir; diğer ikisi etiket değil, iklim anlaşması ve stratejisidir."},{"id":"mg-9-s11","tur":"coktan-secmeli","soru":"Bir otelde hangisi, yalnızca bilgisayar almaktan öte gerçek bir dijital dönüşümdür?","secenekler":["Defterdeki rezervasyon kayıtlarının taranıp bilgisayarda klasörde saklanması","Resepsiyona ikinci bir bilgisayar konularak iki kişinin aynı anda çalışması","Rezervasyonların yine deftere yazılıp yalnız adlarının tabloya da geçirilmesi","Oda seçimi, kayıt ve faturanın telefondan yürüyecek biçimde kurulması"],"dogru":3,"aciklama":"Dijital dönüşüm, işin dijital araçlarla baştan düşünülüp değiştirilmesidir. Defteri taramak yalnız ilk basamaktır; bilgisayar eklemek ya da kaydı iki kez tutmak işi değiştirmez."},{"id":"mg-9-s12","tur":"coktan-secmeli","soru":"Teknik müdür aylık su tüketimini doluluk oranıyla karşılaştırıyor; konuk sayısı düşmüş ama su artmış. Bu çalışmanın adı nedir?","secenekler":["Veri","Veri analizi","Otomasyon","Dijital karbon ayak izi"],"dogru":1,"aciklama":"Verinin düzenlenip karşılaştırılarak karar için sonuç çıkarılması veri analizidir. Veri ise yalnız ham sayılardır; karşılaştırma yapılınca bilgiye dönüşür."},{"id":"mg-9-s13","tur":"coktan-secmeli","soru":"Teknik ekip, üçüncü katın soğutmasını kısarsa ne olacağını gerçek sistemi değiştirmeden önce bilgisayardaki bir modelde deniyor. Kullandıkları yapı hangisidir?","secenekler":["Akıllı bina sistemi","Gelişmiş enerji izleme sistemi","Binanın dijital ikizi","Akıllı termostat"],"dogru":2,"aciklama":"Dijital ikiz, sensör verisiyle güncellenen sanal kopyadır ve değişiklikler önce onda denenir. Akıllı bina ve termostat gerçek binayı yönetir, izleme sistemi yalnız ölçüp gösterir."},{"id":"mg-9-s14","tur":"coktan-secmeli","soru":"Otel odalara sensör ve akıllı termostat takıyor; boş odada klima kısılıyor ve tüketim düşüyor. Bu örneği ikiz dönüşüm yapan özellik hangisidir?","secenekler":["Dijital aracın, çevresel kazanç için birlikte planlanması","Cihazların pahalı olması ve çok sayıda odaya kurulmuş olması","Klimanın insan eli değmeden kendiliğinden çalışması","Enerji faturasının önceki aya göre düşmüş olması"],"dogru":0,"aciklama":"İkiz dönüşümde dijital adım ve yeşil sonuç birlikte planlanır. Kendiliğinden çalışma otomasyondur, fatura düşüşü ise yalnız sonucu gösterir."},{"id":"mg-9-s15","tur":"coktan-secmeli","soru":"Hangisi ikiz dönüşümdeki çelişkilere örnek değildir?","secenekler":["Odalara takılan sensörlerin ömrü dolunca elektronik atık oluşması","Tabletlerin yapımı için maden çıkarılması","Küçük pansiyonun bütçesi yetmediği için izleme sistemi alamaması","Otelin güneş paneli kurarak elektrik faturasını düşürmesi"],"dogru":3,"aciklama":"Çelişki, bir çözümün yarar sağlarken yeni bir çevresel ya da toplumsal sorun doğurmasıdır. Güneş paneli burada yalnız kazanç sağlar; diğer üç örnek atık, maden ve maliyet sorununu gösterir."},{"id":"mg-9-s16","tur":"coktan-secmeli","soru":"Teknik müdür, gece 03.00’te mutfağın enerji tüketiminin olağandan yüksek olduğunu görmek istiyor. Hangi sistem işine yarar?","secenekler":["Akıllı termostat","Enerji izleme sistemi","Kart anahtarlı enerji sistemi","Dijital menü"],"dogru":1,"aciklama":"Enerji izleme sistemi enerjinin ne zaman, nerede, ne kadar harcandığını sayaç ve sensörle gösterir. Termostat yalnız sıcaklığı, kart sistemi yalnız oda elektriğini yönetir."},{"id":"mg-9-s17","tur":"coktan-secmeli","soru":"Mutfak stajyeri atığı doğru kutuya ayırıyor, sebzeyi az fireyle doğruyor, musluğu boşa akıtmıyor. Gösterdiği yeterlik hangisidir?","secenekler":["Dijital beceri","Adil geçiş","Yeşil beceri","Yeşil yakalı çalışan"],"dogru":2,"aciklama":"Yeşil beceri, işi çevreye az zarar vererek yapabilmektir. Yeşil yakalı çalışan bir kişidir, beceri değildir; dijital beceri ve etik ise teknoloji kullanımıyla ilgilidir."},{"id":"mg-9-s18","tur":"coktan-secmeli","soru":"Bir otel çamaşırhanesini otomatik sisteme geçiriyor. Adil geçiş ilkesine en uygun adım hangisidir?","secenekler":["Çalışanlara eğitim verip başka bölümlerde de görevlendirmek","Sistem kurulunca çamaşırhane çalışanlarını işten çıkarmak","Çalışanları sistem kurulana kadar ücretsiz izne ayırmak","Çalışanlardan yeni sistemi kendi imkânlarıyla öğrenmelerini istemek"],"dogru":0,"aciklama":"Adil geçiş, işi değişen çalışanın eğitim ve yeni iş imkânıyla desteklenmesidir. Diğer seçenekler yükü yalnız çalışana yükler."},{"id":"mg-9-s19","tur":"dogru-yanlis","soru":"Güvenlik kameralarının görüntülerini bir veri merkezinde saklamak da sera gazı salımına yol açar.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Veri merkezleri ve cihazlar enerji harcar; buna dijital karbon ayak izi denir. Dijital olmak kendiliğinden çevre dostu olmak demek değildir."},{"id":"mg-9-s20","tur":"dogru-yanlis","soru":"Otomasyon rutin işleri makineye bıraktığı için çalışanların yeni beceri öğrenmesine gerek kalmaz.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Otomasyonla işler çoğu zaman kalkmaz, değişir; çalışan yeni araçları kullanmayı öğrenmelidir. Bu yüzden beceri güncelleme gerekir."},{"id":"mg-9-s21","tur":"dogru-yanlis","soru":"Kaynak verimliliği, konuğun konforunu düşürerek daha az enerji ve su harcamak demektir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Verimlilik, kaliteyi düşürmeden aynı işi daha az kaynakla yapmaktır. Konforu kısmak tasarruf olsa da verimlilik sayılmaz."},{"id":"mg-9-s22","tur":"dogru-yanlis","soru":"Yeşil Anahtar konaklama tesislerine verilen çevre etiketidir; Mavi Bayrak ise plajlara, marinalara ve turizm teknelerine verilir.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"İki etiket de uluslararasıdır ama verildikleri yer farklıdır: Yeşil Anahtar tesise, Mavi Bayrak plaj, marina ve tekneye."},{"id":"mg-9-s23","tur":"senaryo","durum":"Kat hizmetlerinde stajdasın. Saat 10.30, konaklaması süren bir konuğun odasını topluyorsun. Banyoda iki havlu askıya asılmış, biri yere bırakılmış. Aynanın yanındaki kartta “Asılı havlu yeniden kullanılır, yerdeki havlu değiştirilir” yazıyor.","soru":"Ne yaparsın?","secenekler":["Konuk memnun kalsın diye üç havluyu da yenisiyle değiştiririm.","Asılı havluları bırakır, yerdekini değiştiririm.","Tasarruf olsun diye üç havluyu da yerinde bırakırım.","Üçünü de katlayıp rafa dizer, yanlarına temiz havlu eklerim."],"dogru":1,"aciklama":"Yeniden kullanım programında kural iki yönlüdür: asılı havlu konuğun “yeniden kullanacağım” demesidir ve değiştirilmez, yerdeki havlu mutlaka değiştirilir. Hepsini değiştirmek programı anlamsız kılar; hiçbirini değiştirmemek konuğun tercihini çiğner."},{"id":"mg-9-s24","tur":"senaryo","durum":"Saat 11.00, konuğu plaja inmiş bir odayı topluyorsun. Kapının yanındaki enerji yuvasında oda kartı değil, konuğa ait bir mağaza kartı takılı; klima ve bütün ışıklar açık kalmış.","soru":"Ne yaparsın?","secenekler":["Kartı yuvadan çıkarıp çöpe atarım.","Kartı çıkarır, konuğa bir uyarı notu yazıp bırakırım.","Görmemiş gibi yapar, odayı toplayıp çıkarım.","Karta dokunmam; durumu kat şefime bildiririm."],"dogru":3,"aciklama":"Yuvaya başka kart bırakmak enerji tasarrufu sistemini boşa çıkarır; ama kart konuğun eşyasıdır ve konuğa not yazmak stajyerin kararı değildir. Görmezden gelmek israfı sürdürür. Doğrusu durumu şefe bildirmek ve otelin kuralına göre davranmaktır."},{"id":"mg-9-s25","tur":"senaryo","durum":"Otelin satış ofisinde stajdasın. Saat 14.00, senden sosyal medyada yayınlaman istenen paylaşımda “Otelimiz Yeşil Anahtar sahibidir” yazıyor. Oysa dünkü toplantıda başvurunun henüz sonuçlanmadığını duymuştun.","soru":"Ne yaparsın?","secenekler":["Yayınlamadan önce durumu sorumlu yöneticiye sorarım.","Belge nasılsa alınacak diye düşünür, paylaşımı hemen yayınlarım.","Cümleyi kendi kararımla siler, paylaşımı öyle yayınlarım.","Yazıyı ben hazırlamadığım için karışmam, söyleneni yaparım."],"dogru":0,"aciklama":"Alınmamış bir belgeyi alınmış gibi duyurmak yeşil yıkamadır: konuğu yanıltır ve dürüstlüğe aykırıdır. Metni kendi başına değiştirmek ya da susmak da doğru değildir; duyduğun bilgi eksik olabilir. Doğrusu yayınlamadan önce yetkiliye sormaktır."},{"id":"mg-9-s26","tur":"senaryo","durum":"Mutfakta stajdasın. Kahvaltı büfesi 10.30’da kapandı; şef artan yiyeceklerin türüne göre tartılıp forma yazılmasını istemişti. Mutfak yoğun, yanındaki komi “Tartmadan dök, rakamı kafadan yazarız” diyor.","soru":"Ne yaparsın?","secenekler":["Tartmadan döker, formu geçen günkü rakamlara bakarak doldururum.","Formu bugün boş bırakır, yarın iki günü birlikte yaklaşık yazarım.","Tartıp gerçek rakamı yazarım; yetişmezse şefe haber veririm.","Artanları tartmadan personel yemekhanesine götürüp orada bırakırım."],"dogru":2,"aciklama":"Gıda israfı takibi gerçek rakamla tutulursa işe yarar: aşçıbaşı ertesi günün üretimini bu veriye göre belirler. Uydurma rakam yanlış karara götürür. İş yetişmiyorsa çözüm kaydı atlamak değil, şefe haber vermektir."},{"id":"mg-9-s27","tur":"senaryo","durum":"Ön büroda stajdasın. Saat 15.10, yaşlı bir konuk yanına geliyor: telefonuna gelen kâğıtsız check-in bağlantısını bir türlü açamamış, yorgun ve biraz mahcup görünüyor.","soru":"Nasıl davranırsın?","secenekler":["Sistem böyle çalıştığı için bağlantıyı açana kadar lobide beklemesini söylerim.","Kaydın bankoda da yapılabildiğini söyler, görevliye yönlendiririm.","Telefonunu elinden alır, kimlik bilgilerini onun yerine kendim girip onaylarım.","Lobideki başka bir konuktan kendisine yardım etmesini rica ederim."],"dogru":1,"aciklama":"Dijital dönüşümün amacı konuğa kolaylık sağlamaktır, konuğu zorlamak değil. Dijital yolu kullanamayan konuğun kaydı her zaman bankoda yapılır. Konuğun telefonunu alıp kişisel bilgilerini girmek ya da onu başka bir konuğa bırakmak hem hizmet hem veri gizliliği açısından yanlıştır."},{"id":"mg-9-s28","tur":"senaryo","durum":"Resepsiyonda stajdasın. Saat 22.00, okuldan bir arkadaşın mesaj atıyor: “Yarınki geliş listesinin fotoğrafını at, tanıdık var mı bakayım.” Liste önündeki ekranda açık.","soru":"Ne yaparsın?","secenekler":["Yalnız adların göründüğü kısmın fotoğrafını çekip gönderirim.","Fotoğraf göndermem, ama listedeki adları mesajla tek tek yazarım.","Gönderir, baktıktan sonra hemen silmesini isterim.","Göndermem; konuk bilgisini paylaşamayacağımı yazarım."],"dogru":3,"aciklama":"Kimin otelde kalacağı kişisel veridir ve izinsiz paylaşılamaz; fotoğraf yerine mesajla yazmak ya da “sonra sil” demek bunu değiştirmez. Dijitalleşme arttıkça veriyi korumak her çalışanın sorumluluğudur."},{"id":"mg-9-s29","tur":"senaryo","durum":"Teknik serviste stajdasın. Saat 16.00, enerji izleme ekranında bugün hiç kullanılmayan toplantı salonunun klimasının sabahtan beri çalıştığını fark ediyorsun. Yanında çalıştığın usta başka bir arızaya gitmiş.","soru":"İlk adımın ne olur?","secenekler":["Gördüğümü not alır, vardiya amirine hemen bildiririm.","Pano odasına gidip salonun şalterini kendim indiririm.","Ekranı kapatır, kendi işime dönerim.","Akşam vardiya devrinde aklıma gelirse söylerim."],"dogru":0,"aciklama":"Enerji izleme sistemi israfın yerini ve saatini gösterir; görülen sorun bekletilmez. Ama stajyer elektrik panosuna kendi başına müdahale etmez: bu hem tehlikelidir hem yetkisi dışındadır. Doğrusu durumu hemen yetkiliye bildirmektir."},{"id":"mg-9-s30","tur":"senaryo","durum":"Staj yaptığın otel, kat hizmetlerinde oda durumlarını tabletten bildirmeye geçiyor. Saat 09.00, eğitim başlamak üzere. Deneyimli bir kat görevlisi sana “Ben kâğıt listemden şaşmam, sen de boşuna uğraşma” diyor.","soru":"Nasıl davranırsın?","secenekler":["Ben de kâğıt listeyle devam eder, eğitimi daha sonraya bırakırım.","Eğitime girerim, ama katta uygulamayı kullanmam, listeden şaşmam.","Eğitime katılır, takıldığım yeri şefime sorarım.","Görevliye yanıldığını ekibin önünde söyler, onu ikna etmeye çalışırım."],"dogru":2,"aciklama":"Dönüşümde yerini koruyanlar öğrenmeyi sürdürenlerdir; yeni bir sistemi çabuk öğrenebilmek değerli bir dijital beceridir. Eğitimi atlamak ya da uygulamayı kullanmamak işi aksatır; deneyimli bir çalışanla ekibin önünde tartışmak da stajyerin işi değildir."},{"id":"mg-9-s31","tur":"coktan-secmeli","soru":"Bir otelde çamaşırhanenin kazanı arızalanınca temiz havlu çıkmıyor, odalar hazırlanamıyor, resepsiyon konuğu bekletmek zorunda kalıyor. Bu durumu en iyi açıklayan kavram hangisidir?","secenekler":["İş süreçlerinde otomasyon","Sistem","Binanın dijital ikizi","İşletmede döngüsel ekonomi"],"dogru":1,"aciklama":"Sistem, birbirini etkileyen parçaların oluşturduğu bütündür; tek parçadaki arıza bu yüzden bütün otele yayılır. Otomasyon ise işin makineyle kendiliğinden yürümesidir, parçaların birbirine bağlılığını anlatmaz."},{"id":"mg-9-s32","tur":"coktan-secmeli","soru":"Soğuk hava deposundaki bir cihaz, sıcaklık yükselince kimse gidip bakmadan mutfak şefinin telefonuna uyarı gönderiyor. Burada kullanılan teknoloji hangisidir?","secenekler":["Binanın dijital ikizi","Kaynak yönetiminde yapay zekâ","Nesnelerin interneti","Sayısallaştırma"],"dogru":2,"aciklama":"İnternete bağlı sensörün ölçtüğü değeri kendiliğinden merkeze iletmesi nesnelerin internetidir (IoT). Dijital ikiz değişikliklerin önce denendiği sanal kopyadır; burada deneme değil, anlık uyarı vardır."},{"id":"mg-9-s33","tur":"coktan-secmeli","soru":"Bir otel zinciri yeni otellerinde sıcak suyu güneşle ısıtıyor, yağmur suyunu bahçe için topluyor; oda sayısı artarken oda başına tüketim düşüyor. Bu yaklaşım hangisidir?","secenekler":["Yeşil büyüme","Ekonomik sürdürülebilirlik","İşletmede yeşil yıkama","Geleneksel iş modeli"],"dogru":0,"aciklama":"Yeşil büyüme, ekonominin doğal kaynakları tüketmeden ve çevreyi kirletmeden büyümesidir: işletme büyürken çevreye yükü azalır. Ekonomik sürdürülebilirlik ise uzun yıllar kazanç ve iş sağlamayı anlatır, çevre yükünün azalmasını içermez."},{"id":"mg-9-s34","tur":"dogru-yanlis","soru":"Yapay zekâyla üretilmiş bir görseli otelin gerçek odası gibi sunmak dijital etiğe aykırıdır.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Dijital etik teknolojiyi dürüst kullanmayı gerektirir. Konuk ekranın arkasını göremediği için gerçek olmayan görsel onu yanıltır ve güveni zedeler."},{"id":"mg-9-s35","tur":"coktan-secmeli","soru":"Otel kâğıtsız check-in’e geçiyor ve resepsiyon ekibi yeni sistemi öğrenmek için eğitim alıyor. Bu durum hangi kavrama örnektir?","secenekler":["Değişime direnç","İkiz dönüşüm odaklı yetkinlikler","Yeşil beceri","Dönüşümde beceri güncelleme"],"dogru":3,"aciklama":"İşi dönüşümle değişen çalışanın eğitim alarak becerisini yenilemesi beceri güncellemedir. Değişime direnç ise yeni sisteme karşı çıkmaktır; burada ekip sistemi öğreniyor."},{"id":"mg-9-s36","tur":"dogru-yanlis","soru":"Uyandırma servisi sistemle yapılmaya başlayınca santral görevlisinin işi tamamen ortadan kalkar.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Azalan, işin tekrarlayan kısmıdır; görevli kazandığı zamanı konuğun özel isteklerine ve sorunlarına ayırabilir. Yeni sistemi öğrenen çalışanın işi değişir, ama bitmez."},{"id":"mg-9-s37","tur":"dogru-yanlis","soru":"Satın alma bölümünün cihaz seçerken kaç yıl kullanılabileceğine ve onarılıp onarılamayacağına bakması, doğal kaynak tüketimi çelişkisini küçültür.","secenekler":["Doğru","Yanlış"],"dogru":0,"aciklama":"Cihazın ömrü uzadıkça yenisinin yapımı için maden çıkarma ihtiyacı azalır. Ömrü uzatmak bu çelişkiyi küçültmenin en sade yoludur."},{"id":"mg-9-s38","tur":"coktan-secmeli","soru":"Bir otel kâğıt rezervasyon formlarını tarayıp bilgisayara aktarıyor, ama iş eskisi gibi yürüyor. Bu adım dijitalleşmenin hangi basamağıdır?","secenekler":["Dijital dönüşüm","Sayısallaştırma","Dijitalleşme","İş süreçlerinde otomasyon"],"dogru":1,"aciklama":"Bilgilerin dijital ortama aktarılması ilk basamak olan sayısallaştırmadır. İşin akışı değişmediği için dijital dönüşümden söz edilemez."},{"id":"mg-9-s39","tur":"coktan-secmeli","soru":"Plansız dijitalleşmeden kaçınmak isteyen bir pansiyon, yazılım almadan önce ilk olarak hangi soruyu sormalıdır?","secenekler":["Rakip oteller hangi yazılımı kullanıyor?","Piyasadaki en yeni sürüm hangisi?","Bu yazılım hangi sorunumuzu çözecek?","Kaç bilgisayara birden kurulabilir?"],"dogru":2,"aciklama":"Plansız dijitalleşme ihtiyaç gözetilmeden yapılır ve parayı boşa harcatır; karar bu yüzden çözülecek sorunla başlar. Rakibin ya da en yeninin seçilmesi işletmenin ihtiyacını göstermez."},{"id":"mg-9-s40","tur":"coktan-secmeli","soru":"Ayvalık’taki bir otel zeytinyağını ilçedeki üreticiden, sebzesini köy pazarından alıyor. Bu yerel tedarik uygulamasının çevreye yararı hangisidir?","secenekler":["Fiyat değişince menü yeniden basılmaz.","Boş odada elektrik harcanmaz.","Yıkanan havlu sayısı azalır.","Taşımadan doğan salım azalır."],"dogru":3,"aciklama":"Ürün kısa yoldan geldiği için taşımada harcanan yakıt ve salım azalır. Öteki şıklar dijital menünün, kart anahtarlı sistemin ve havlu yeniden kullanım programının yararlarıdır."},{"id":"mg-9-s41","tur":"coktan-secmeli","soru":"Bir iş süreci dönüşüm açısından çözümlenirken hangi üç şeye bakılır?","secenekler":["Kaynak tüketimi, dijitalleşme düzeyi, karbon ayak izi","Uygulanabilirlik, verimlilik, sürdürülebilirlik","Çevresel, ekonomik ve sosyal boyut","Konuk memnuniyeti, doluluk oranı, ortalama gecelik fiyat"],"dogru":0,"aciklama":"İş süreci analizinde dönüşüm açısından kaynak tüketimi, dijitalleşme düzeyi ve karbon ayak izi incelenir. Uygulanabilirlik, verimlilik ve sürdürülebilirlik ise iş modelini değerlendirme ölçütleridir."},{"id":"mg-9-s42","tur":"coktan-secmeli","soru":"Otel yönetimi tüm odalara enerji tasarruf sistemi kurma önerisini değerlendirirken “Bugünkü bütçemizle bu yapılabilir mi?” diye soruyor. Bu soru hangi ölçüte aittir?","secenekler":["Verimlilik","Uygulanabilirlik","Sürdürülebilirlik","Kaynak tüketimi"],"dogru":1,"aciklama":"Bugün eldeki imkânla yapılıp yapılamayacağı uygulanabilirlik ölçütüdür. Faturayı düşürüp düşürmeyeceği verimliliği, yıllarca işleyip işlemeyeceği sürdürülebilirliği sorar."},{"id":"mg-9-s43","tur":"dogru-yanlis","soru":"Yapay zekâ destekli talep tahmini kullanan bir otel mutfağında üretim miktarına ilişkin son kararı yazılım verir.","secenekler":["Doğru","Yanlış"],"dogru":1,"aciklama":"Yapay zekâ geçmiş veriden tahmin önerir; son karar verinin doğruluğunu bilen insana aittir."},{"id":"mg-9-s44","tur":"coktan-secmeli","soru":"Su ve elektrik sayacını ay sonunda bir kez okuyup deftere yazan küçük bir otel, bir su kaçağını haftalar sonra fatura gelince fark ediyor. Bu otelin iş modelindeki asıl sorun hangisidir?","secenekler":["Tüketimi zamanında ölçmeden yönetmesi","Eski bir binada hizmet veren küçük bir otel olması","Personelinin sayıca az olması","Faturalarını yalnız ay sonunda ödemesi"],"dogru":0,"aciklama":"Ölçüm yalnız ay sonunda yapıldığı için kaçağın ne zaman ve hangi bölümde başladığı görülemez. Geleneksel modelin sorunu eskilik ya da küçüklük değil, ölçmeden yönetmektir."}],"siralamalar":[{"id":"mg-9-r01","konu":"9.1","baslik":"Al, üret, tüket, at: doğrusal yolculuk","yonerge":"Geleneksel üretim anlayışında bir ürünün yolculuğunu doğru sıraya koy.","adimlar":["Hammadde doğadan alınır.","Ham maddeden ürün üretilir.","Ürün satın alınır ve kullanılır.","Kullanılan ürün çöpe atılır, atık oluşur."],"aciklama":"Geleneksel üretim “al, üret, tüket ve at” anlayışına dayanır: kaynak alınır, ürüne dönüşür, kullanılır ve sonunda atık olur. İkiz dönüşüm bu atığı yeni üretim için kaynak olarak görür."},{"id":"mg-9-r02","konu":"9.3","baslik":"Bir iş sürecini masaya yatır","yonerge":"Okuldaki bir atölyenin iş sürecini yeşil, dijital ve ikiz dönüşüm açısından çözümleme adımlarını doğru sıraya koy.","adimlar":["Okulundaki bir atölyeden inceleyeceğin mesleki iş sürecini seç.","Sürecin aşamalarını, kullandığı kaynakları, oluşan atıkları ve teknolojileri araştır, gözlemle.","Balık kılçığı diyagramıyla verimsizliğin ve çevresel etkinin nedenlerini çıkar.","Bulduğun sorunlar için yeşil, dijital ve ikiz dönüşüm fırsatlarını belirle.","Üç yaklaşımı kıyasla ve atölye için en uygulanabilir olanı gerekçesiyle seç.","Grup değerlendirme formunu doldurarak grubunun çalışmasını değerlendir."],"aciklama":"Önce süreç seçilip tanınır, sonra sorunların nedenleri bulunur; çözüm fırsatları ancak nedenler belli olunca belirlenir, en uygun yaklaşım da fırsatlar kıyaslanarak seçilir."},{"id":"mg-9-r03","konu":"9.4","baslik":"Eski atölyeden yeni iş modeline","yonerge":"Geleneksel bir atölyeyi ikiz dönüşüm iş modeline taşıyan performans görevinin adımlarını doğru sıraya koy.","adimlar":["Atölyedeki israf, enerji, atık ve üretim takibi sorunlarını belirle.","Sorunlar için yeşil ve dijital çözüm yollarını yaz.","Yeşil ve dijital çözümlerin birbirini nasıl desteklediğini açıkla.","Atölyeyi geleceğe taşıyacak özgün bir iş modeli geliştir.","İş modelini proje fikri kanvasında problem, hedef kitle, çözüm ve maliyet bölümleriyle yapılandır; altı şapkalı düşünme tekniğiyle farklı açılardan sına.","Sınıfça en uygulanabilir modeli belirle ve modelini dijital sunumla anlat."],"aciklama":"Sorun bilinmeden çözüm yazılmaz; yeşil ve dijital çözümler bağlanınca iş modeli kurulur, kanvasta yapılandırılıp sınanır, en son sınıfça değerlendirilir ve sunulur."}],"acikSorular":[{"id":"mg-9-y01","konu":"9.3","soru":"Bir otelin yönetimi, konuk memnuniyetini düşürmeden su ve enerji giderlerini azaltmak istiyor. Havlu ve çarşaf yeniden kullanım programı ile kart anahtarlı enerji tasarrufu uygulamalarının işleyişini yazınız ve bunların kaynak verimliliğine nasıl katkı sağladığını açıklayınız.","olcut":[{"metin":"Havlu ve çarşaf yeniden kullanım programında konuğun değiştirme tercihini kendisinin belirlediğini yazar.","puan":20},{"metin":"Kart anahtarlı sistemde kart yuvadan çıkınca odanın elektriğinin kısa süre sonra kesildiğini yazar.","puan":20},{"metin":"İki uygulamada da hangi kaynakların (su, enerji, deterjan) azaldığını belirtir.","puan":20},{"metin":"Kaynak verimliliğinin, kaliteyi ve konuk konforunu düşürmeden daha az kaynak kullanmak olduğunu bağlayarak uygulamaların buna nasıl katkı sağladığını açıklar.","puan":40}],"ornek":"Havlu ve çarşaf programında konuk, havlusunu asarsa yeniden kullanacağını, yere bırakırsa değiştirilmesini istediğini belirtir; karar konuğundur. Kart anahtarlı sistemde konuk kartı yuvadan alıp odadan çıkınca lambalar ve klima kısa süre sonra kendiliğinden kapanır. Birinci uygulama daha az yıkama sayesinde su, enerji ve deterjan tüketimini, ikincisi odada kimse yokken harcanan enerjiyi azaltır. Kaynak verimliliği aynı hizmeti daha az kaynakla ve kaliteyi düşürmeden sunmaktır; konuk bu uygulamalarda konforundan bir şey kaybetmediği için otel hem faturayı hem çevreye verdiği yükü azaltmış olur.","ipucu":"Konuğun bu uygulamalarda neyi kaybedip neyi kaybetmediğini düşünün; verimliliğin tasarruftan farkı burada saklı."},{"id":"mg-9-y02","konu":"9.2","soru":"Bir otel kâğıtsız check-in sistemine ve otomatik çamaşırhane sistemine geçiyor. Bu dönüşümün çalışanlar üzerindeki iki olası etkisini yazınız ve adil geçiş ilkesinin otelde nasıl uygulanabileceğini nedenleriyle açıklayınız.","olcut":[{"metin":"Dönüşümün bazı işlerin içeriğini değiştirdiği ya da azalttığına dair bir etki yazar.","puan":20},{"metin":"Dönüşümün çalışanlar için yeni becerilere veya yeni görevlere dair bir fırsat yarattığını yazar.","puan":20},{"metin":"Adil geçişin işi değişen çalışanın eğitim ve yeni görev imkânıyla desteklenmesi olduğunu belirtir.","puan":20},{"metin":"Otelde uygulanabilecek somut bir adım (eğitim verme, başka bölümde görevlendirme) örnek verir.","puan":15},{"metin":"Çalışanın desteklenmesinin, dönüşümün sosyal sürdürülebilirlik boyutu için neden gerekli olduğunu açıklar.","puan":25}],"ornek":"Kâğıtsız check-in ile resepsiyonda form doldurma işi azalır, otomatik çamaşırhane ile de çamaşırhane çalışanlarının görevi değişir; birinci etki budur. Öte yandan çalışanlar yeni sistemi kullanmayı öğrenerek yeni beceriler kazanabilir ve konuk karşılama gibi görevlere yönelebilir. Adil geçiş, işi değişen ya da azalan çalışanın eğitim ve yeni iş imkânıyla desteklenmesidir. Otel, çamaşırhane çalışanlarına eğitim verip onları yeni sistemin kullanımında veya başka bölümlerde görevlendirebilir. Herkes yeni teknolojiye aynı hızla uyum sağlayamayacağı için kimseyi geride bırakmamak gerekir; bu, sürdürülebilirliğin sosyal boyutunun da gereğidir.","ipucu":"Dönüşümden yalnız işletmenin değil, çalışanın da kazançlı çıkması için otelin neyi önceden yapması gerektiğini düşünün."}]}]`),r=JSON.parse(`[{"ders":"mesleki-gelisim","onay":true,"diyaloglar":[{"id":"mg-d01","unite":1,"baslik":"Uykusuz Gecenin Sabahı","rol":"Stajyer resepsiyonist","sahne":"Saat 09.15, resepsiyon. 512 numaralı odada kalan Selma Aydın bankoya geliyor; gözleri yorgun, sesi gergin. Gece boyunca üst kattan gelen gürültü yüzünden uyuyamamış; ön büroda o an yalnız stajyer var.","kavramlar":["mg-1-061","mg-1-039","mg-1-040","mg-1-043","mg-1-060"],"adimlar":[{"konuk":"Günaydın demeyeceğim, çünkü hiç uyuyamadım. Bütün gece üst kattan gürültü geldi.","ingilizce":"I won't say good morning, because I didn't sleep at all. There was noise from upstairs all night.","secenekler":[{"metin":"(Kalemi bırakıp döner.) Sizi dinliyorum Selma Hanım. Ne zaman başladı?","ingilizce":"I'm listening, Ms Aydın. When did it start?","puan":2,"tepki":"Konuk derin bir nefes alıp anlatmaya başlar. LAST yaklaşımının ilk adımı dinlemektir; tam dikkat ve açık bir soru, konuğa derdinin önemsendiğini gösterir."},{"metin":"Anlıyorum efendim. Oda numaranızı alayım, sistemden bir bakayım. (Ekrana döner.)","puan":1,"tepki":"Konuk cümlesini yarıda bırakır, ekrana bakan stajyere kaşlarını çatar. Niyet iyi, ama dinlemeden işleme geçmek konuğa “beni duymuyor” dedirtir."},{"metin":"Ama gece kimse resepsiyonu aramadı ki, biz nereden bilelim efendim?","puan":0,"tepki":"Konuğun sesi yükselir: “Şimdi suçlu ben miyim?” Şikâyete savunmayla karşılık vermek misafiri daha çok kızdırır; şikâyet kişisel alınmaz."}]},{"konuk":"Gece birden sonra başladı, üçe kadar sürdü. Bugün önemli bir toplantım var, gözlerimi zor açıyorum.","ingilizce":"It started after one and went on until three. I have an important meeting today and I can barely keep my eyes open.","secenekler":[{"metin":"Özür dilerim efendim, kalabalık gecelerde bazen böyle şeyler oluyor maalesef, elimizde değil.","puan":1,"tepki":"Konuk “Bazen mi?” diye sorar, hâlâ gergindir. Özür var, ama “bazen oluyor” sözü yaşadığını küçültür; konuk anlaşıldığını hissetmez."},{"metin":"Yani birden üçe kadar uyuyamadınız, bugün de önemli bir gününüz var. Çok üzgünüm.","ingilizce":"So you couldn't sleep from one until three, and you have an important day ahead. I'm very sorry.","puan":2,"tepki":"Konuk başını sallar: “Evet, tam olarak bu.” Söyleneni kendi cümlesiyle tekrarlamak yanlış anlamayı önler; ardından gelen özür konuğa anlaşıldığını hissettirir."},{"metin":"Üst katta çocuklu bir aile kalıyor; misafirlerimize de pek bir şey diyemiyoruz efendim.","puan":0,"tepki":"Konuk şaşırır: “Yani bu gece de mi böyle?” Sorumluluğu başka misafire atmak ve “bir şey yapamayız” demek, şikâyeti düzeltme fırsatını kaçırmaktır."}]},{"konuk":"Özrünüz güzel, ama bu gece de aynı şey olursa ne olacak?","ingilizce":"Thank you for the apology, but what happens if it's the same again tonight?","secenekler":[{"metin":"Bu konuda bir şey yapamam efendim, ben burada stajyerim.","puan":0,"tepki":"Konuk kollarını kavuşturur: “O zaman kiminle konuşacağım?” Yetki yetmiyorsa konuk geri çevrilmez; şikâyet bekletmeden amire iletilir."},{"metin":"Bu akşam üst kattaki odayı uyarırız, içiniz rahat olsun; bir daha kesinlikle olmaz efendim.","puan":1,"tepki":"Konuk biraz rahatlar ama emin değildir. Uyarı iyi bir adım, fakat “bir daha kesinlikle olmaz” tutulamayabilecek bir sözdür; yetkini aşan söz verilmez."},{"metin":"Hemen daha sessiz bir oda var mı bakıyorum. Yoksa durumu ön büro müdürümüze iletip size dönüş yapacağız.","ingilizce":"I'll check right away whether we have a quieter room. If not, I'll pass this on to our front office manager and we'll get back to you.","puan":2,"tepki":"Konuk “Tamam, bakın lütfen” der, omuzları gevşer. Çözüm somut, söz verilen şey yapılabilir; yetkiyi aşan kısım için amire iletileceği açıkça söylendi."}]},{"konuk":"Siz bakarken söyleyeyim: akşam altı gibi dönerim. Eşyalarımı da kendim toplamak isterim.","ingilizce":"While you're checking, let me tell you: I'll be back around six. And I'd like to pack my things myself.","secenekler":[{"metin":"Hiç uğraşmayın efendim, siz toplantıdayken eşyalarınızı biz toplayıp yeni odanıza taşırız.","puan":0,"tepki":"Konuk sertleşir: “Az önce kendim toplayacağım dedim.” İyi niyetli de olsa konuğun açıkça söylediğini duymamak, ilk adımdaki dinlemeyi boşa çıkarır."},{"metin":"Özetle: sessiz oda ayarlanırsa altıda hazır, eşyalarınızı dönünce siz toplarsınız. Deftere not ediyorum.","ingilizce":"To summarise: if we arrange a quieter room, it will be ready at six, and you'll pack your things when you're back. I'm noting it in the logbook.","puan":2,"tepki":"Konuk “Evet, anlaştık” der. Özetleme konuğun neyin yapılacağını bilerek ayrılmasını sağlar; kayıt sayesinde akşam vardiyası konuğa derdini ikinci kez anlattırmaz."},{"metin":"Tamam efendim, hepsini not ettim; siz toplantınıza gidin, hiç merak etmeyin, biz hallederiz.","puan":1,"tepki":"Konuk tereddüt eder: “Neyi not ettiniz?” Cevap nazik, ama varılan çözüm toparlanmadığı için konuk neyin yapılacağından emin olamaz."}]},{"konuk":"Teşekkürler. Açıkçası, dinlendiğimi hissettim.","ingilizce":"Thank you. To be honest, I felt listened to.","secenekler":[{"metin":"Rica ederim efendim, ne demek; size iyi günler ve kolay gelsin.","puan":1,"tepki":"Konuk gülümseyip ayrılır. Kapanış kibar, ama LAST’in son adımı eksik kaldı: şikâyeti bildirdiği için konuğa teşekkür edilmedi."},{"metin":"Önemli değil efendim. Ama gece hemen resepsiyonu arasaydınız sabah bu kadar uğraşmazdık.","puan":0,"tepki":"Konuğun yüzündeki rahatlama kaybolur. Son cümle akılda kalır; konuğu suçlayan bir kapanış bütün emeği boşa çıkarır."},{"metin":"Bize haber verdiğiniz için asıl biz teşekkür ederiz. Toplantınızda başarılar dilerim.","ingilizce":"Thank you for letting us know. I wish you every success in your meeting.","puan":2,"tepki":"Konuk içtenlikle teşekkür eder ve rahatlamış olarak çıkar. Şikâyet eden misafir sorunu düzeltme fırsatı verir; bu yüzden teşekkür, LAST’in son adımıdır."}]}]},{"id":"mg-d02","unite":1,"baslik":"Devirde Kaybolan Bilgi","rol":"Stajyer resepsiyonist","karsi":"İş arkadaşı","sahne":"Saat 15.50, ön büro. Dün 204 numaralı odanın geç çıkış bilgisi vardiya devrinde aktarılmadığı için kat görevlisi odaya erken girmiş, misafir rahatsız olmuştu. Sabah vardiyasının resepsiyonisti Kerem, lobide misafirler beklerken stajyere yaklaşıyor.","kavramlar":["mg-1-124","mg-1-028","mg-1-129","mg-1-106","mg-1-105"],"adimlar":[{"konuk":"Dün 204’te bir olay olmuş diyorlar. Ne oldu, anlatsana?","ingilizce":"I heard something happened in 204 yesterday. What was it? Go on, tell me.","secenekler":[{"metin":"Anlatırım, ama burada değil. Devirden sonra arka ofiste konuşalım mı?","ingilizce":"I'll tell you, but not here. Shall we talk in the back office after the handover?","puan":2,"tepki":"Kerem “Olur” der. Konuşma, iş akışı aksamadan ve misafir görmeden yapılacak; sakin bir yerde taraflar birbirini dinleyebilir."},{"metin":"Ne olacak, senin yüzünden dün misafir herkesin önünde bana bağırdı!","puan":0,"tepki":"Kerem kızarır, bekleyen misafirler başlarını çevirir. Anlaşmazlık lobide, misafirin önünde konuşulmaz; suçlama da tartışmayı büyütür."},{"metin":"Boş ver, önemli bir şey değildi; geçti gitti artık, hiç kafana takma.","puan":1,"tepki":"Kerem omuz silker ve işine döner. Ortam sakin kaldı, ama sorun hiç konuşulmadığı için aynı aksaklık bir sonraki devirde yine yaşanabilir."}]},{"konuk":"Tamam, buradayız. Söyle bakalım.","ingilizce":"Right, we're here. Let's hear it.","secenekler":[{"metin":"204’te biraz karışıklık oldu işte, misafir de bozuldu; neyse, bir dahakine hepimiz dikkat ederiz.","puan":1,"tepki":"Kerem “Ne karışıklığı?” diye sorar. Suçlama yok, ama mesaj belirsiz kaldı; ne olduğu ve neye ihtiyaç duyulduğu açıkça söylenmedi."},{"metin":"Sen devirde hep bir şeyleri unutuyorsun, zaten hiç dikkat etmiyorsun; dün de yine aynısı oldu.","puan":0,"tepki":"Kerem hemen kollarını kavuşturur. “Hep”, “zaten”, “hiç” sen dilinin işaretidir; suçlanan kişi çözüm aramayı bırakıp kendini savunur."},{"metin":"Dün 204’ün geç çıkış bilgisi bana ulaşmadı; kat görevlisi odaya girince misafirin önünde zor durumda kaldım.","ingilizce":"Yesterday the late check-out for 204 didn't reach me, so when the room attendant went in, I was put in a difficult position in front of the guest.","puan":2,"tepki":"Kerem dikkatle dinler, kaşları düşünceli. Ben dili kişiyi değil sorunu konuşturur; olan biten ve hissedilen suçlamadan anlatıldı."}]},{"konuk":"Ben söyledim ama! Sen o sırada telefondaydın, dinlemedin.","ingilizce":"But I did tell you! You were on the phone at the time and didn't listen.","secenekler":[{"metin":"Olabilir, o an telefondaydım; belki yarım duydum. Demek ki yalnız sözlü devir ikimizi de korumuyor.","ingilizce":"That's possible. I was on the phone, so maybe I only half heard it. So a spoken handover alone doesn't protect either of us.","puan":2,"tepki":"Kerem’in sesi yumuşar. Karşıdakinin bakışını görmek ve suçu geri atmamak savunmacı tutumu azaltır; konuşma yeniden çözüme döner."},{"metin":"Söylemedin, yalan söyleme! İstersen o saatte lobide olan herkese tek tek sorarım.","puan":0,"tepki":"Kerem sesini yükseltir, konuşma kavgaya döner. Savunmaya karşı suçlamayla gitmek iki tarafı da dinlemekten uzaklaştırır."},{"metin":"Peki, tamam, haklısın, benim hatam olsun; uzatmayalım, konu burada kapansın artık.","puan":1,"tepki":"Kerem rahatlar, ama sorun yerinde durur. Tartışma bitti, fakat bilginin neden kaybolduğu konuşulmadığı için çözüm bulunmadı."}]},{"konuk":"Haklısın, o kalabalıkta ben de emin olamıyorum. Peki ne yapalım?","ingilizce":"Fair enough, I can't be sure either with all that going on. So what shall we do?","secenekler":[{"metin":"Bundan sonra seninle devir yapmayayım; bilgileri vardiya amirinden ya da başka birinden alırım.","puan":0,"tepki":"Kerem bozulur. Devirden kaçmak bilgiyi daha çok kaybettirir; vardiya devri bekleyen işlerin bir sonraki vardiyaya doğrudan aktarılmasıdır."},{"metin":"Bekleyen işleri devirde söyleyip kayıt defterine de yazalım, sonra birlikte okuyup teyit edelim.","ingilizce":"Let's go over the pending jobs at handover and write them in the logbook too, then read them through together to confirm.","puan":2,"tepki":"Kerem “Bu iş görür” der. Söz uçar, yazı kalır: devirde unutulan bilgi defterde durur ve kimin ne yazdığı belli olduğu için tartışma da önlenir."},{"metin":"Bir dahaki sefere sen biraz daha yüksek sesle ve yavaş söylersin, ben de dikkat ederim, olur biter.","puan":1,"tepki":"Kerem “Yani yine ben mi?” diye düşünür. Öneri yükü tek tarafa yüklüyor ve bilgi yine yalnız sözlü kalıyor; aynı sorun tekrarlanabilir."}]},{"konuk":"İyi fikir. Şefe de söyleyelim mi, yoksa aramızda mı kalsın?","ingilizce":"Good idea. Shall we tell the supervisor as well, or keep it between us?","secenekler":[{"metin":"Birlikte söyleyelim; herkes böyle yaparsa kimse “Bana söylenmedi” demez. Konuştuğumuz için sağ ol.","ingilizce":"Let's tell the supervisor together. If everyone does this, nobody can say no one told them. And thanks for talking it through.","puan":2,"tepki":"Kerem gülümser: “Ben de teşekkür ederim.” Devirde aktarılmayan bilgi ekipte “Bana kimse söylemedi” tartışması demektir; ortak yöntem bunu herkes için önler."},{"metin":"Aramızda kalsın, şefi hiç uğraştırmayalım; ikimiz uygularız, bu bize yeter.","puan":1,"tepki":"Kerem kabul eder. İkisi için sorun çözüldü, ama öteki vardiyalar aynı yöntemi bilmediği için bilgi başka devirlerde yine kaybolabilir."},{"metin":"Şefe ben tek başıma gidip dün senin unuttuğunu anlatırım, ne yapılacağına o karar versin.","puan":0,"tepki":"Kerem’in yüzü asılır; az önce kurulan güven bir anda kaybolur. Birlikte bulunan çözümü tek taraflı suçlamaya çevirmek iş ilişkisini bozar."}]}]},{"id":"mg-d03","unite":2,"baslik":"Mal Kabul Kapısındaki Hediye","rol":"Mutfak stajyeri","karsi":"Tedarikçi","sahne":"Saat 07.30, otelin mal kabul kapısı. Sebze getiren tedarikçi aceleyle kasaları indiriyor. Mutfak şefi toplantıda; kasaları sayıp kontrol etme işini stajyere vermiş, teslim belgesini kendisi imzalayacak.","kavramlar":["mg-2-040","mg-2-048","mg-2-024","mg-2-017","mg-2-025"],"adimlar":[{"konuk":"Günaydın! Çok acelem var, kasaları bırakıp çıkıyorum. Saymana gerek yok, her zamanki gibi tam.","ingilizce":"Morning! I'm in a real hurry, so I'll just drop the crates and go. No need to count them; it's all there as usual.","secenekler":[{"metin":"Peki, acelenizi anlıyorum. Yalnız kasa sayısına bakayım, içlerini açmayayım o zaman.","puan":1,"tepki":"Tedarikçi “Tamam, çabuk ol” der. Sayı doğru çıkar, ama malın kendisine bakılmadı; kalite kontrol yalnız saymak değil, standarda uygunluğu denetlemektir."},{"metin":"Hoş geldiniz. Şefim kasaları sayıp kontrol etmemi istedi; birkaç dakika sürer.","ingilizce":"Welcome. My chef asked me to count and check the crates; it'll only take a few minutes.","puan":2,"tepki":"Tedarikçi saatine bakar ama bekler. Kalite kontrol, gelen malın standarda uyup uymadığını denetlemektir; acele bu adımı atlatmamalıdır."},{"metin":"Tamam, size güveniyorum. Bırakın gidin, ben şefime her şey tam geldi derim.","puan":0,"tepki":"Tedarikçi hızla çıkmaya hazırlanır. Görmediğin bir şeye “tam” demek şefe yanlış bilgi vermektir; kontrolü yapılmayan mal sonra konuğun tabağına gider."}]},{"konuk":"Şu domates kasasının alt sırası biraz ezik, ama üstü güzel. Karıştırırsınız, kimse fark etmez.","ingilizce":"The bottom layer of this tomato crate is a bit bruised, but the top is fine. Just mix them in; nobody will notice.","secenekler":[{"metin":"Bu sefer alalım, ama bir dahaki teslimatta lütfen daha dikkatli olun.","puan":1,"tepki":"Tedarikçi gülümser: “Tabii, tabii.” Ama kusurlu malı kabul etme kararı stajyerin değil şefin işidir; şef haberdar olmadan sorun tekrar eder."},{"metin":"Haklısınız, üstteki güzellerin arasına karıştırırım, mutfakta kimse anlamaz.","puan":0,"tepki":"Tedarikçi rahatlar. Kusuru saklamak hiledir; ezik domates salataya girerse bedelini konuk, sonra da otelin adı öder."},{"metin":"Ezik olanları ayıralım ve teslim belgesine not düşelim; kararı şefim versin.","ingilizce":"Let's set the bruised ones aside and note it on the delivery note; my chef can decide.","puan":2,"tepki":"Tedarikçi biraz bozulur ama itiraz edemez. Malın kusuru gizlenmeden açıkça belirtilir; hilesiz alışveriş satan kadar alanın da sorumluluğudur."}]},{"konuk":"Sen işini biliyorsun, beğendim. Bak, bu paket senin. Şefine yeni firmayı değil bizi önerirsen her ay bir tane daha var.","ingilizce":"You know what you're doing, I like that. Look, this package is for you. Recommend us to your chef instead of the new supplier, and there's another one every month.","secenekler":[{"metin":"Çok sağ olun, alırım. Şefime de sizden iyi firma olmadığını söylerim.","puan":0,"tepki":"Tedarikçi paketi uzatır. Bu hediye hizmete teşekkür değil, öneriyi satın alma teklifidir; artık öneri mutfağın değil, stajyerin çıkarına göre şekillenir."},{"metin":"Teşekkürler, ama kabul edemem. Hangi firmayı önereceğime kalite karar verir.","ingilizce":"Thank you, but I can't accept it. Quality decides which supplier I recommend.","puan":2,"tepki":"Tedarikçi paketi geri çeker, şaşırmış görünür. Kişisel çıkar karşılığında öneri istemek çıkar çatışması doğurur; böyle bir teklif nazikçe ama net reddedilir."},{"metin":"Şimdi alamam, şefim görürse başım derde girer; lütfen paketi geri alın.","puan":1,"tepki":"Tedarikçi paketi geri çeker ama göz kırpar: “Şef görmezken konuşuruz.” Teklif reddedildi ama yanlış nedenle: etik dışı davranış kimse görmese de etik dışıdır, sorun “görülmek” değildir."}]},{"konuk":"Peki peki, anladım. Ama bu konuşma aramızda kalsın; şefine anlatmana gerek yok, değil mi?","ingilizce":"All right, all right, I get it. But let's keep this between us; there's no need to tell your chef, is there?","secenekler":[{"metin":"Merak etmeyin, aramızda kalır. Zaten küçük bir şeydi, büyütmeye gerek yok.","puan":0,"tepki":"Tedarikçi memnun ayrılmaya hazırlanır. Görülen yanlışı saklamak sorumluluktan kaçmaktır; “küçük bir şey” diye başlayan sorunlar büyür."},{"metin":"Anlatmam, ama bir daha bana böyle bir teklifte bulunmayın lütfen.","puan":1,"tepki":"Tedarikçi rahatlar. Teklif geri çevrildi, ama şef bilmezse aynı teklif yarın başka bir çalışana yapılır; bildirilmeyen sorun büyür."},{"metin":"Size kızgın değilim, ama bu teklifi şefime anlatmam gerekiyor; bu benim görevim.","ingilizce":"I'm not upset with you, but I do need to tell my chef about the offer; that's part of my job.","puan":2,"tepki":"Tedarikçi omuz silker: “Sen bilirsin.” Kuralı çiğnetmeye yönelik teklif reddedilir ve amire bildirilir; amaç kimseyi küçük düşürmek değil, mutfağı zarardan korumaktır."}]},{"konuk":"Tamam, ezik kasanın yerine yarın sabah yenisini getiririm. Belgeyi kim imzalayacak?","ingilizce":"Fine, I'll bring a replacement for the bruised crate tomorrow morning. Who's signing the delivery note?","secenekler":[{"metin":"Şefim imzalayacak, birazdan gelir. Ezik kasa notunu ona gösteririm. İyi günler.","ingilizce":"My chef will sign it; she'll be here in a few minutes. I'll show her the note about the bruised crate. Have a good day.","puan":2,"tepki":"Şef gelir, notu ve teklifi dinler, belgeyi imzalar ve stajyere teşekkür eder. Kontrol eksiksiz yapıldı, kusur kayda geçti, teklif bildirildi: şef bu stajyere işini rahatça emanet eder."},{"metin":"Şimdi ben imzalarım. Ezik kasayı yazmayalım, yarın getireceksiniz zaten.","puan":0,"tepki":"Tedarikçi hemen kabul eder. Kusur kayda geçmezse kalite kontrol yapılmamış sayılır; yarın kasa gelmezse kimse bir şey kanıtlayamaz."},{"metin":"Ben imzalayayım, şefi beklemeyelim; nasılsa her şeyi tek tek saydım.","puan":1,"tepki":"Tedarikçi kalemi uzatır. Kontrol iyi yapıldı, ama imza şefe aitti; kendine verilmeyen yetkiyi kullanmak, iyi niyetle de olsa işin düzenini bozar."}]}]},{"id":"mg-d04","unite":2,"baslik":"Arkadaşlık mı, Doğruluk mu?","rol":"Resepsiyon stajyeri","karsi":"İş arkadaşı","sahne":"Saat 14.00, kalabalık bir şehir otelinin resepsiyonu. Aynı okuldan iki stajyer yan yana çalışıyor; yakın arkadaş Deniz gün boyunca birkaç kez kuralı esnetmek istiyor. Ön büro şefi birkaç adım ötede telefonla konuşuyor.","kavramlar":["mg-2-015","mg-2-022","mg-2-037","mg-2-013","mg-2-020"],"adimlar":[{"konuk":"Bak, sıradaki dördüncü konuk annemin arkadaşı. Onu öne alalım, ötekiler biraz bekler.","ingilizce":"Look, the fourth guest in the queue is my mum's friend. Let's bring her forward; the others can wait a bit.","secenekler":[{"metin":"Tamam, onu hemen öne alalım. Bu kalabalıkta kimse fark etmez zaten.","puan":0,"tepki":"Deniz sevinir, ama sıradaki bir konuk kaşlarını çatar: “Biz daha önce gelmiştik.” Sırada bekleyen, başkasının öne alındığını hemen fark eder; güven orada sarsılır."},{"metin":"Bilmiyorum, önce gidip şefe soralım; o ne derse biz de öyle yaparız.","puan":1,"tepki":"Deniz homurdanır: “Şefi bununla mı meşgul edeceğiz?” Danışmak kötü değil, ama burada kural zaten açık: sıra herkese sıradır."},{"metin":"Sıra herkese sıra; onu da sırasıyla karşılayalım. İstersen git, bir selam ver.","ingilizce":"Everyone waits their turn, so let's welcome her in order. You could go and say hello, though.","puan":2,"tepki":"Deniz bir an duraksar, sonra başını sallar. Kişisel yakınlığa göre değil herkese aynı ölçüyle davranmak tarafsızlıktır; selam vermek ise kimsenin hakkını yemez."}]},{"konuk":"Peki. Bu arada sabah tanınmış bir sporcu giriş yaptı. Oda numarasını sınıfın grubuna yazayım mı? Bir de fotoğraf çekerim.","ingilizce":"Fine. By the way, a well-known athlete checked in this morning. Shall I post the room number in our class group chat? I could take a photo too.","secenekler":[{"metin":"Yazma lütfen. Kimin kaldığı ve oda numarası konuğun özeli; dışarı çıkmaz.","ingilizce":"Please don't. Who's staying here and their room number are private; that never leaves the hotel.","puan":2,"tepki":"Deniz telefonunu cebine koyar: “Haklısın, düşünmemiştim.” İş sırasında öğrenilen konuk bilgisi yetkisi olmayan hiç kimseyle paylaşılmaz; gizlilik konuğun güvenidir."},{"metin":"Yaz bence, ama bu bilgiyi benden duyduğunu kimseye söyleme lütfen.","puan":0,"tepki":"Deniz yazmaya başlar. Kimin kaldığı ve oda numarası konuğun özelidir; bilgi bir kez gruba düşerse kimin elinde olduğunu kimse bilemez."},{"metin":"Oda numarasını yazma bence, ama uzaktan bir fotoğraf çekersen sorun olmaz.","puan":1,"tepki":"Deniz telefonunu çıkarır. Oda numarası korunmuş olur, ama tanınmış bir konuğun fotoğrafını çekip paylaşmak da gizliliği çiğner."}]},{"konuk":"Of, bir şey itiraf edeyim: sabah bir konuğun hesabına yanlışlıkla iki kahve fazla yazmışım. Konuk fark etmeden çıktı. Söylersek başım yanar, boş ver.","ingilizce":"Oh, I have to admit something: this morning I accidentally charged a guest for two extra coffees. He checked out without noticing. If we say anything, I'll get in trouble, so forget it.","secenekler":[{"metin":"Bir dahaki sefere dikkat et. Bu seferlik olan oldu, yapacak bir şey yok.","puan":1,"tepki":"Deniz rahatlar. Uyarı yerinde, ama hata yerinde kaldı: konuk içmediği iki kahvenin parasını ödedi ve bu düzeltilmedi."},{"metin":"Şefe birlikte söyleyelim. Hata düzeltilir, konuktan fazla alınan para da ona geri döner.","ingilizce":"Let's tell the supervisor together. The mistake can be put right, and the guest gets back what he was overcharged.","puan":2,"tepki":"Deniz yutkunur ama dinler. Konuğa verilmeyen hizmetin parası alınmaz; bildirilen hata düzeltilir, saklanan hata büyür."},{"metin":"Haklısın, konuk zaten fark etmedi. Aramızda kalsın, kimseye söylemeyiz.","puan":0,"tepki":"Deniz gülümser, ama içi rahat değildir. Konuğun hakkı yenmiş olarak kalır; fark edilmemesi yanlışı doğru yapmaz."}]},{"konuk":"Ama sen benim arkadaşım değil misin? Beni şefe şikâyet mi edeceksin şimdi?","ingilizce":"But aren't you my friend? Are you going to report me to the supervisor now?","secenekler":[{"metin":"Arkadaşınım, o yüzden yanındayım. Şikâyete değil, hatayı düzeltmeye gidiyoruz.","ingilizce":"I am your friend, and that's why I'm with you. We're not going to report you; we're going to put the mistake right.","puan":2,"tepki":"Deniz derin bir nefes alır: “Peki.” Etik ikilemde arkadaşlık ile dürüstlük çatışır gibi görünür; doğru olanı birlikte yapmak ikisini de korur."},{"metin":"Tamam, haklısın. Arkadaşlık her şeyden önce gelir; bu konuyu unut gitsin.","puan":0,"tepki":"Deniz rahatlar, konu kapanır. İkilemde arkadaşlık seçildi, dürüstlük bırakıldı; şefinin yanında da aynı kararı verir miydin sorusu cevapsız kaldı."},{"metin":"Şikâyet etmem. Ama sen söylemezsen, ben de hiçbir şey duymamış olurum.","puan":1,"tepki":"Deniz sessiz kalır, karar ona kalır. Arkadaşını suçlamadın, ama gördüğün yanlışı dile getirmemek de sorumluluktan kaçmaktır."}]},{"konuk":"Tamam, şef telefonu kapattı, birlikte gidelim. Ama sen başlar mısın? Çok utanıyorum.","ingilizce":"OK, the supervisor's off the phone, let's go together. But could you start? I'm so embarrassed.","secenekler":[{"metin":"Ben anlatırım, sen hiç konuşma. Şef bana nasılsa pek kızmaz, merak etme.","puan":1,"tepki":"Deniz minnetle bakar. İyi niyetli bir destek, ama hata Deniz’indir; şef, hatasını kendisi söyleyen personele güvenir."},{"metin":"Yanında dururum, ama olanı en iyi sen biliyorsun. Sen anlat, ben destek olurum.","ingilizce":"I'll stand by you, but you know best what happened. You explain, and I'll back you up.","puan":2,"tepki":"Deniz anlatır; şef hesabı düzeltir ve ikisine de teşekkür eder. Hatayı sahiplenmek zayıflık değil, profesyonelliktir; arkadaşlık da zarar görmedi."},{"metin":"Ben anlatayım; hesabı ben yazdım derim, böylece sana hiçbir şey olmaz.","puan":0,"tepki":"Deniz şaşırır: “Ama sen yazmadın ki.” Arkadaşı korumak için yalan söylemek ikinci bir yanlıştır; dürüstlük, kimseyi aldatmamaktır."}]}]},{"id":"mg-d05","unite":3,"baslik":"Bulaşıkhanede Kıl Payı","rol":"Mutfak stajyeri","karsi":"Şef","sahne":"Saat 14.20, öğle servisi bitmek üzere. Mutfak stajyeri Ece bulaşıkhanede kayıyor, son anda tezgâha tutunup düşmüyor; zemin günlerdir bulaşık makinesinin sızdıran hortumu yüzünden ıslak. Sesi duyan şef içeri giriyor.","kavramlar":["mg-3-006","mg-3-010","mg-3-087","mg-3-034","mg-3-031"],"adimlar":[{"konuk":"Bir ses duydum. Ne oldu, iyi misin?","ingilizce":"I heard a noise. What happened? Are you all right?","secenekler":[{"metin":"Önemli değil şefim, burası hep ıslak zaten. Hepimiz alıştık artık, dikkat ederek yürüyoruz.","puan":0,"tepki":"Şef kaşlarını çatar: “Alışmak, bir gün düşmek demek.” Tehlikeye alışmak riski küçültmez; kıl payı atlatılan olay ciddiye alınmazsa sıradaki gerçek bir kaza olur."},{"metin":"İyiyim şefim, bir şey yok. Biraz kaydım ama düşmedim, o kadar; işime devam ediyorum.","puan":1,"tepki":"Şef “Tamam” deyip çıkmak üzeredir; olay unutulmaya yüz tutar. Ramak kala olay “bir şey olmadı” diye geçilirse aynı yerde bir dahaki sefer biri gerçekten düşer."},{"metin":"İyiyim şefim, kaydım ama tezgâha tutundum. Kimse yaralanmadı; yine de söyleyeyim dedim.","ingilizce":"I'm fine, Chef. I slipped but caught hold of the counter. Nobody was hurt, but I wanted to tell you anyway.","puan":2,"tepki":"Şef rahatlar: “İyi ki söyledin.” Kimsenin yaralanmadığı kıl payı olay da ramak kala olaydır ve amire bildirilir; kazanın bedava gelen uyarısıdır."}]},{"konuk":"Peki şimdi ne yapalım? Birazdan komiler elleri tepsiyle buradan geçecek.","ingilizce":"So what shall we do now? The commis will be coming through here with trays any minute.","secenekler":[{"metin":"Zemini hemen silip kurutayım şefim; kuruyunca kimse kaymaz, tepsiler de rahat geçer.","puan":1,"tepki":"Şef başını sallar ama sorar: “Sen silerken geçen kayarsa?” Zemin kurutulur, doğru; fakat ıslak zemin levhası silmeye başlamadan önce konur ki kuruyana kadar gelip geçen uyarılsın."},{"metin":"Önce ıslak zemin levhasını alanın iki ucuna koyayım, sonra zemini silip kurutayım.","ingilizce":"I'll put the wet floor signs at both ends first, then mop and dry the floor.","puan":2,"tepki":"Şef “Doğru sıra” der. Levha silmeye başlamadan konur, zemin kuruyunca kaldırılır; böylece silme sırasında da kimse habersiz kaygan zemine basmaz."},{"metin":"Levhayı koyarım şefim, zemin bir saate kendiliğinden kurur.","puan":0,"tepki":"Şef itiraz eder: “Levha zemini kurutmaz.” Levha yalnız kuruyana kadar uyarır; ıslak zemin silinmeden bırakılırsa tepsiyle geçen biri yine kayabilir."}]},{"konuk":"Sence bu zemin neden sürekli ıslanıyor?","ingilizce":"Why do you think this floor keeps getting wet?","secenekler":[{"metin":"Mutfak böyle bir yer şefim; bulaşıkhane hiçbir zaman tam kuru olmaz, her mutfakta böyledir.","puan":0,"tepki":"Şef ikna olmaz: “Böyle diye bırakırsak biri düşecek.” Tehlike işin doğasında olabilir ama kontrol altına alınır; nedeni sorgulanmayan kaza aynı yerde tekrar olur."},{"metin":"Komiler acele ederken yere su sıçratıyor; biraz daha yavaş ve dikkatli olsunlar yeter.","puan":1,"tepki":"Şef “Olabilir, ama tek neden bu mu?” diye sorar. Acele de bir etkendir, fakat kazayı yalnız dikkatsizliğe bağlamak arkadaki asıl nedeni gözden kaçırır."},{"metin":"Makinenin hortumu günlerdir sızdırıyor şefim. Asıl sorun bu; onarılmazsa biri yine kayar.","ingilizce":"The dishwasher hose has been leaking for days, Chef. That's the real problem. If it isn't repaired, someone will slip again.","puan":2,"tepki":"Şef hortuma eğilip bakar: “Haklısın.” Kayma olay, ıslak zemin doğrudan neden; bakımı yapılmayan hortum ise kök nedendir ve giderilmezse kaza tekrarlanır."}]},{"konuk":"Peki herkese “Burada dikkat edin” desek yeter mi?","ingilizce":"So would it be enough to tell everyone to be careful here?","secenekler":[{"metin":"Bence yetmez şefim; hortum onarılırsa zemin ıslanmaz. Teknik servise arıza kaydı açalım mı?","ingilizce":"I don't think so, Chef. If the hose is repaired, the floor won't get wet. Shall we report the fault to technical service?","puan":2,"tepki":"Şef telefona uzanır. Sızdıran hortumu onarmak, herkesten sürekli dikkat beklemekten daha güvenilirdir; çünkü insan yorulur, unutur, acele eder."},{"metin":"Yeter şefim; ıslak zemin levhasını da buraya sürekli koyarız, gelen geçen herkes görür ve hatırlar.","puan":1,"tepki":"Şef “Bir süre sonra kimse bakmaz” der. Uyarı geçici bir önlemdir; hep orada duran levha zamanla ciddiye alınmaz, sorunun kendisi ise yerinde kalır."},{"metin":"Yeter bence. Hortumu onarmak benim işim değil, ben kendi işime bakayım.","puan":0,"tepki":"Şef durur: “Onarmak senin işin değil, ama görmek ve söylemek senin işin.” Sorumluluğu başkasına atmak tehlikeyi yerinde bırakır."}]},{"konuk":"Tamam, kaydı açıyorum. Az önceki kaymayı da yazayım mı, yoksa gerek yok mu?","ingilizce":"Right, I'm opening the report. Shall I also write down your slip from earlier, or is there no need?","secenekler":[{"metin":"Siz bilirsiniz şefim; kimse yaralanmadığı için belki gerek yoktur.","puan":1,"tepki":"Şef yine de yazar ama kararı ona bıraktığın için biraz şaşırır. Ramak kala olay da kaydedilir; kayıt, aynı olayın tekrarını önleyecek önlemin alınmasını sağlar."},{"metin":"Lütfen yazmayın şefim; staj dosyama kötü bir not düşer, herkes beni sakar bilir diye çekiniyorum.","puan":0,"tepki":"Şef gülümser: “Kayıt suçlu aramak için değil.” Saklanan olay bir sonrakini hazırlar; ekibin işi suçlu aramak değil, nedeni bulmaktır."},{"metin":"Lütfen yazın şefim: saat 14.20, bulaşıkhane, kimse yaralanmadı. Kayıt aynı olayın tekrarını önler.","ingilizce":"Please do, Chef: 2.20 p.m., the dishwashing area, nobody hurt. A record helps stop it happening again.","puan":2,"tepki":"Şef notu saatiyle ve yeriyle yazar, sonra elini omzuna koyar: “Bugün belki bir kazanın önünü kestin.” Bildirilen ve kaydedilen ramak kala olay, gerçek kazanın önüne geçer."}]}]},{"id":"mg-d06","unite":3,"baslik":"Alarm Çaldığında Üçüncü Kat","rol":"Kat hizmetleri stajyeri","sahne":"Saat 10.40, üçüncü kat koridoru. Kat hizmetleri stajyeri Deniz oda temizliğindeyken yangın alarmı çalmaya başlıyor. Bir konuk telaşla odasından çıkıyor ve asansöre doğru yürüyor.","kavramlar":["mg-3-056","mg-3-057","mg-3-058","mg-3-106","mg-3-055"],"adimlar":[{"konuk":"Bu ses de ne? Asansörle aşağı inip neler olduğuna bakayım.","ingilizce":"What's that noise? I'll take the lift down and see what's going on.","secenekler":[{"metin":"Yangın alarmı efendim. Lütfen asansörü kullanmayın, beni izleyin; merdiven bu tarafta.","ingilizce":"It's the fire alarm, sir. Please don't use the lift. Follow me; the stairs are this way.","puan":2,"tepki":"Konuk asansör düğmesinden elini çeker ve peşine düşer. Tahliyede asansör kullanılmaz; personelin sakin sesi ve net cümlesi konuktaki paniği azaltır."},{"metin":"Muhtemelen tatbikattır efendim, odanızda bekleyebilirsiniz.","puan":0,"tepki":"Konuk kararsız kalıp odasına döner. Alarmın gerçek mi, tatbikat mı olduğu ilk anda bilinmez; doğru tutum tahmin yürütmek değil, alarmı gerçek sayıp binayı boşaltmaktır."},{"metin":"Yangın alarmı galiba efendim; asansör yerine merdiveni kullansanız daha iyi olur sanırım.","puan":1,"tepki":"Konuk duraksar: “Galiba mı?” Yön doğru, ama kararsız söz konuğu da kararsız bırakır; acil durumda kısa ve net cümleler kurulur."}]},{"konuk":"Bir dakika! Pasaportum ve bilgisayarım odada kaldı, koşup alayım.","ingilizce":"Hang on! My passport and laptop are still in the room. Let me dash back and get them.","secenekler":[{"metin":"Tabii efendim, siz alın; ben merdivenden iniyorum, arkamdan gelirsiniz.","puan":0,"tepki":"Konuk odaya döner ve koridorda yalnız kalır. Tahliyede eşya almak için geri dönülmez; konuğu tehlikede bırakıp gitmek yol gösterme görevini de boşa çıkarır."},{"metin":"Lütfen geri dönmeyin efendim, önce sizin güvenliğiniz. Tehlike geçince odanıza dönebilirsiniz.","ingilizce":"Please don't go back, sir. Your safety comes first. You can return to your room once it's safe.","puan":2,"tepki":"Konuk bir an odasına bakar, sonra “Haklısınız” deyip yürür. Eşya için geri dönmek tahliyeyi geciktirir ve kişiyi tehlikeye sokar; eşya yerine konur, can yerine konmaz."},{"metin":"Yalnız pasaportunuzu alın, bilgisayarı bırakın lütfen; ama çok hızlı olun, ben kapıda bekliyorum.","puan":1,"tepki":"Konuk koşup pasaportunu alır, ikiniz de koridorda vakit kaybedersiniz. İyi niyetli bir orta yol gibi görünse de tahliyede eşya için geri dönülmez."}]},{"konuk":"Bakın, merdiven kapısının önünde bir kat arabası duruyor, geçemiyoruz!","ingilizce":"Look, there's a housekeeping trolley in front of the stairwell door. We can't get through!","secenekler":[{"metin":"Hemen kenara çekiyorum efendim, buyurun geçin. Bunu sonra amirime de bildireceğim.","ingilizce":"I'm moving it out of the way right now, sir. Please go ahead. I'll report this to my supervisor later.","puan":2,"tepki":"Konuk geçer, kapı içeriden tek hareketle açılır. Acil çıkışın önüne hiçbir şey bırakılmaz; önü kapalı bir çıkış gören kişi engeli kaldırır ve amirine bildirir."},{"metin":"Koridorun öbür ucunda bir merdiven daha var efendim, oraya yürüyelim.","puan":1,"tepki":"Konuk peşinden gelir ama yol uzar ve araba yerinde kalır. Başka çıkış olabilir, ancak arkadan gelenler de aynı engele takılır; önü kapalı acil çıkışta engel kaldırılır."},{"metin":"Arabanın yanından yan dönüp sıkışarak geçebiliriz efendim, acele edelim.","puan":0,"tepki":"Konuk arabaya sürtünerek geçer, çantası takılır. Daraltılmış kaçış yolu itişmeye ve düşmeye yol açar; acil çıkışın önü her zaman tamamen boş olmalıdır."}]},{"konuk":"Dışarı çıktık, çok şükür. Ben arabama gidip biraz uzaklaşayım, olur mu?","ingilizce":"We're out, thank goodness. I'll go to my car and drive off for a bit, all right?","secenekler":[{"metin":"Olur efendim, yalnız gitmeden önce adınızı ve oda numaranızı söyler misiniz, ben not alayım?","puan":1,"tepki":"Konuk bilgisini verip uzaklaşır. Bilgi almak iyi bir düşünce, ama sayım toplanma alanında yapılır; kimse alanı haber vermeden terk etmemelidir."},{"metin":"Lütfen benimle toplanma alanına gelin efendim. Orada sayım yapılıyor; sizi göremezlerse içeride ararlar.","ingilizce":"Please come with me to the assembly point, sir. There's a headcount there, and if they can't see you, they'll search for you inside.","puan":2,"tepki":"Konuk “Bunu hiç düşünmemiştim” deyip seninle gelir. Toplanma alanındaki sayım, içeride kimse kalıp kalmadığını anlamanın tek yoludur."},{"metin":"Tabii efendim, artık dışarıdasınız; istediğiniz yere gidebilirsiniz.","puan":0,"tepki":"Konuk otoparktan çıkar, sayımda eksik görünür. Ekipler olmayan birini içeride aramak zorunda kalır; toplanma alanından haber vermeden ayrılmak bu yüzden yanlıştır."}]},{"konuk":"Peki içeri ne zaman dönebiliriz? Ben duman falan görmedim ki.","ingilizce":"So when can we go back in? I didn't see any smoke, you know.","secenekler":[{"metin":"Duman görmediyseniz yanlış alarmdır herhalde; isterseniz şimdi girebilirsiniz.","puan":0,"tepki":"Konuk binaya doğru yürür, güvenlik görevlisi onu kapıda durdurur. Duman görülmemesi tehlikenin olmadığını göstermez; “tehlike geçti” denmeden binaya dönülmez."},{"metin":"Birazdan döneriz herhalde efendim, bu tür şeyler genelde uzun sürmez, çok beklemezsiniz.","puan":1,"tepki":"Konuk “Birazdan ne kadar?” diye sorar. Söz nazik, ama tahmine dayanıyor; olayın nasıl gelişeceği bilinmezken süre verilmez, yetkililerin kararı beklenir."},{"metin":"Yetkililer “tehlike geçti” dediğinde efendim. Teşekkür ederim; haber gelince size ileteceğim.","ingilizce":"As soon as the all-clear is given, sir. Thank you; I'll let you know the moment I hear anything.","puan":2,"tepki":"Konuk sakinleşir ve teşekkür eder: “İyi ki yanımdaydınız.” Kimin, ne zaman binaya döneceğine yetkililer karar verir; personelin işi konuğu bilgilendirip yanında kalmaktır."}]}]},{"id":"mg-d07","unite":4,"baslik":"Gece Kapanışında Atık Yağ","rol":"Mutfak stajyeri","karsi":"İş arkadaşı","sahne":"Saat 23.00. Otel restoranının mutfağı kapanıyor; şef çıkmış, mutfakta stajyerle deneyimli komi Emre kalmış. Fritözdeki kızartma yağı artık kullanılamayacak durumda ve Emre bir an önce eve gitmek istiyor.","kavramlar":["mg-4-010","mg-4-099","mg-4-078","mg-4-071","mg-4-065"],"adimlar":[{"konuk":"Yağı bekleyecek vaktim yok. Şunu lavaboya dökelim, sıcak suyla akıp gider.","ingilizce":"I haven’t got time to wait for the oil. Let’s pour it down the sink; hot water will wash it away.","secenekler":[{"metin":"Sen bilirsin abi, ama ben dökmeyeyim; ben gidip bulaşıklara bakayım.","puan":1,"tepki":"Emre omuz silker ve tencereyi lavaboya götürür. Hatayı görüp sessizce uzaklaşmak yetmez; neden yanlış olduğunu söylemek de işin parçasıdır."},{"metin":"Dökmeyelim, boruyu tıkar, suyu kirletir. Soğusun, kapaklı bidona süzelim.","ingilizce":"If we pour it down the sink, it’ll block the pipes and pollute the water. Let it cool, then we’ll strain it into the lidded drum.","puan":2,"tepki":"Emre durur: “Haklısın, geçen ay gider tıkanmıştı zaten.” Atık yağ lavaboya ya da gidere dökülmez; soğuduktan sonra kapaklı atık yağ bidonunda biriktirilir."},{"metin":"Olur, arkasından bol sıcak su akıtırız; boruda iz kalmaz, kimse de anlamaz.","puan":0,"tepki":"Yağ gidere gider. Sıcak su yağı yalnız biraz ileri taşır; boruda soğuyunca tıkar ve suya karışarak kirletir."}]},{"konuk":"Kim görecek ki? Şef çoktan çıktı, kamera da lavaboyu görmüyor.","ingilizce":"Who’s going to see? Chef left ages ago, and the camera can’t see the sink.","secenekler":[{"metin":"Şef yarın sorabilir; yakalanırsak ikimizin de başı yanar, uğraşmayalım.","puan":1,"tepki":"Emre ikna olur, ama yalnız yakalanmaktan korktuğu için. Etik, denetçi görsün diye değil, doğru olduğu için doğru davranmaktır."},{"metin":"Haklısın, kimse bakmıyorsa bir defadan bir şey olmaz.","puan":0,"tepki":"Emre yağı döker. Kimse görmedi diye kural değişmez; gidere dökülen bir kova yağ bile boruyu tıkar ve atık su arıtmayı zorlar."},{"metin":"Kimse görmese de doğrusu bu. Ben süzerim, sen tezgâhı sil; çabuk biter.","ingilizce":"Even if no one sees, this is the right way. I’ll strain the oil, you wipe the counter; it won’t take long.","puan":2,"tepki":"Emre gülümser: “Tamam, iş bölümü yaptık.” Kimse bakmıyorken atık yağı gidere dökmemek mesleki etiğin en sade örneğidir."}]},{"konuk":"Yağ soğudu ama bidon dolmuş. Kalanı yemek artığı kovasına boşaltsak?","ingilizce":"The oil’s cooled down, but the drum is full. Shall we just tip the rest into the food waste bin?","secenekler":[{"metin":"Kovaya olmaz; kapaklı bir kaba koyup üstüne yazalım, sabah şefe söyleriz.","ingilizce":"Not the bin. Let’s put it in a lidded container, label it and tell Chef in the morning.","puan":2,"tepki":"Emre kabı bulur, sen üstüne “atık yağ” yazarsın. Atık yağ genel kovaya değil, etiketli ve kapaklı özel kaba konur; bu kural torbayı taşıyan çalışanı da korur."},{"metin":"Tencerede ağzı açık kalsın, sabahçılar gelince ne yapacaklarını bilir zaten.","puan":1,"tepki":"Yağ kovaya karışmadı, ama açık tencere devrilebilir ve sabahçılar içinde ne olduğunu bilmeyebilir. Atık yağ kapaklı ve etiketli kapta durmalıdır."},{"metin":"Olur, sonuçta mutfak atığı; yemek artığıyla aynı torbaya gider.","puan":0,"tepki":"Ertesi gün torba yağ sızdırır; taşıyan arkadaşın eli ve koridor yağ olur. Atık yağ özel toplama gerektirir; yemek artığına karıştırılmaz."}]},{"konuk":"Peki bu biriken yağ sonra ne oluyor? Sonunda yine çöpe gitmiyor mu?","ingilizce":"So what happens to all this oil? Doesn’t it end up in the rubbish anyway?","secenekler":[{"metin":"Bilmiyorum açıkçası, ama bidona koymamız gerektiğini biliyorum.","puan":1,"tepki":"Emre “Neden bu kadar uğraşıyoruz o zaman?” diye düşünür. Kuralın nedenini bilen çalışan onu daha kolay uygular ve arkadaşına da anlatabilir."},{"metin":"Evet, belediye kamyonu hepsini aynı çöplüğe döküyor; ayırmamız boşuna, inan.","puan":0,"tepki":"Bu bilgi yanlış ve Emre’nin bir sonraki kapanışta kuralı çiğnemesine yol açar. Atık yağ belediye çöpüne değil, yetkili toplayıcıya gider."},{"metin":"Hayır, yetkili toplayıcı alıyor; yağ başka ürünlerin üretiminde kullanılıyor.","ingilizce":"No, a licensed collector picks it up, and the oil is used to make other products.","puan":2,"tepki":"Emre şaşırır: “Demek boşa gitmiyor.” Ayrı biriktirilen atık yağ yetkili toplayıcıya teslim edilir ve başka ürünlerin üretiminde değerlendirilir."}]},{"konuk":"Bardan şu boş cam şişeler geldi. Çöp torbasına atıyorum, torbayı da ben taşırım.","ingilizce":"These empty glass bottles have just come from the bar. I’ll throw them in the rubbish bag and carry it out myself.","secenekler":[{"metin":"Cam kutusuna atalım; geri dönüşüme gider, kimsenin eline de cam batmaz.","ingilizce":"Let’s put them in the glass bin; they’ll be recycled, and no one will cut their hand.","puan":2,"tepki":"Emre şişeleri cam kutusuna taşır. Cam şişeyi ayrı kutuya atmak hem geri dönüşümü sağlar hem de torbayı taşıyanın eline cam batmasını önler."},{"metin":"Torbaya at gitsin; kırılan olursa yarın süpürürüz.","puan":0,"tepki":"Torbayı taşıyan Emre’nin eline kırık cam batar. Cam şişeler çöp torbasına değil cam kutusuna atılır; bu aynı zamanda bir iş güvenliği önlemidir."},{"metin":"Torbayı çift yapalım bari, en azından yolda yırtılmaz, şişeler de dökülmez.","puan":1,"tepki":"Torba sağlam olur, ama şişeler yine çöpe gider ve kırılırsa torbanın içinden ele batabilir. Cam, ayrı cam kutusuna atılmalıydı."}]},{"konuk":"Tamam, bitti. Işıkları ve davlumbazı sabahçılar kapatır, hadi çıkalım.","ingilizce":"Right, we’re done. The morning shift can switch off the lights and the extractor hood. Let’s go.","secenekler":[{"metin":"Haklısın, ne de olsa faturayı otel ödüyor. İyi geceler.","puan":0,"tepki":"Davlumbaz ve ışıklar sabaha kadar boşa çalışır. Boşa harcanan enerjinin parasını işletme öder; çevre bilinci olan çalışan bu gideri kendiliğinden azaltır."},{"metin":"Çıkarken kapatalım; şu musluk da damlıyor, tam kapatıp not bırakayım. İyi geceler!","ingilizce":"Let’s switch them off on our way out. That tap is dripping too; I’ll turn it off properly and leave a note. Good night!","puan":2,"tepki":"Emre ışıkları kapatır: “Sayende kapanış düzgün bitti, yarın görüşürüz.” Çevre bilinci, kimse denetlemese de musluğu ve ışığı kapatan günlük davranıştır."},{"metin":"Işıkları kapatayım bari, musluğa sabahçılar bakar. İyi geceler.","puan":1,"tepki":"Işıklar kapandı, ama musluk bütün gece damlar. Musluğu tam kapatmak da kapanışın parçasıdır."}]}]},{"id":"mg-d08","unite":4,"baslik":"Broşürdeki Yeşil Yaprak","rol":"Ön büro stajyeri","sahne":"Saat 17.30, resepsiyon. Çevreye duyarlı bir konuk, broşürde “doğa dostu otel” yazısını görmüş ve soruları var. Otel atıklarını türüne göre ayrı topluyor, sıcak suyunun bir bölümünü çatıdaki güneş sisteminden alıp kalanını kazanla ısıtıyor ve banyodaki ile kahvaltı salonundaki küçük kartlarla konukları nazikçe davet ediyor; bir çevre etiketi yok.","kavramlar":["mg-4-052","mg-4-098","mg-4-051","mg-4-013","mg-4-105"],"adimlar":[{"konuk":"Broşürünüzde “doğa dostu otel” yazıyor. Tam olarak ne yapıyorsunuz?","ingilizce":"Your brochure says “eco-friendly hotel”. What exactly do you do?","secenekler":[{"metin":"Atıkları türüne göre ayırıyoruz; sıcak suyun bir bölümü de çatıdaki güneşten geliyor.","ingilizce":"We separate our waste by type, and part of our hot water comes from the solar system on the roof.","puan":2,"tepki":"Konuk ilgiyle dinler: “Somut bir şeyler duymak hoşuma gitti.” Yapılanı olduğu kadar anlatmak, büyük ama boş bir sözden değerlidir."},{"metin":"Çevreye çok önem veriyoruz efendim, her konuda elimizden gelenin en iyisini yapıyoruz.","puan":1,"tepki":"Konuk kibarca gülümser ama bir şey öğrenemez. Genel ve boş bir söz güven vermez; yapılan somut adımlar anlatılmalıdır."},{"metin":"Her şeyimiz doğal ve çevreci; enerjimizin hepsini güneşten alıyoruz.","puan":0,"tepki":"Konuk çatıdaki paneli görmüştür ve şüphelenir. Gerçekte olmayanı çevreci diye anlatmak yeşil yıkamadır ve fark edildiğinde güveni yıkar."}]},{"konuk":"Yani duş suyumun tamamı güneşle mi ısınıyor?","ingilizce":"So is all my shower water heated by the sun?","secenekler":[{"metin":"Evet, tamamı güneşten; hiç yakıt kullanmıyoruz efendim.","puan":0,"tepki":"Bu söz gerçek değil; konuğa yalan söylenmiş olur. Sıcak suyun bir bölümü güneşten geliyorsa “tamamı” denmez; abartılı söz yeşil yıkamadır."},{"metin":"Bir bölümü güneşten geliyor, kalanı için kazanımızı kullanıyoruz.","ingilizce":"Part of it comes from the sun, and we use our boiler for the rest.","puan":2,"tepki":"Konuk başını sallar: “Dürüst bir cevap, teşekkürler.” Temiz enerji anlatılırken yalnız gerçek söylenir: bir bölümü güneşten geliyorsa “bir bölümü” denir."},{"metin":"Bir kısmı güneşten efendim, kısmen öyle diyebiliriz.","puan":1,"tepki":"Bilgi doğru, ama konuk kalanın nereden geldiğini merak etmeye devam eder. Eksik kalan kısmı da açıklayan kısa cevap daha çok güven verir."}]},{"konuk":"Otelinizin bir çevre belgesi var mı? Girişte hiçbir işaret göremedim.","ingilizce":"Does the hotel have an eco-label? I couldn’t see any sign at the entrance.","secenekler":[{"metin":"Var tabii efendim, belgemiz yenilendi, birkaç gün içinde girişe asılacak.","puan":0,"tepki":"Konuk ertesi gün belgeyi sorar ve gerçeği öğrenir. Çevre etiketi bağımsız bir kuruluşun denetimiyle verilir; olmayan belge varmış gibi anlatılmaz."},{"metin":"Bilemiyorum efendim, bunu yönetime sormam gerekiyor; öğrenip size akşam dönerim.","puan":1,"tepki":"Konuk bekler, ama ön büro bu bilgiyi bilmeliydi. Otelin hangi belgeye sahip olduğunu önceden öğrenmek ön büro çalışanının işidir."},{"metin":"Şu an yok. Etiketi bağımsız kuruluşlar denetimle veriyor; biz yaptığımızı anlatıyoruz.","ingilizce":"Not at the moment. Eco-labels are awarded by independent bodies after an inspection; we simply tell you what we really do.","puan":2,"tepki":"Konuk etkilenir: “Bunu açıkça söylemeniz güzel.” Çevre etiketi bir denetim sonunda verilir; olmadığı yerde dürüst olmak güveni artırır."}]},{"konuk":"Ben de katkı vermek isterim. Havlularımı her gün değiştirmenize gerek yok.","ingilizce":"I’d like to do my bit too. You don’t need to change my towels every day.","secenekler":[{"metin":"Teşekkürler, zaten konukların çoğu havluyu boşu boşuna kirletiyor, bize de iş çıkıyor.","puan":0,"tepki":"Konuk rahatsız olur; başka konuklar hakkında suçlayıcı konuşulmuştur. Otelde çevre bilgisi suçlayarak değil, nazik bir davetle verilir."},{"metin":"Teşekkür ederiz! Havluyu askıya asarsanız o gün değişmez; banyodaki kartta da yazıyor.","ingilizce":"Thank you! If you hang your towel on the rail, it won’t be changed that day; there’s a card in the bathroom about it.","puan":2,"tepki":"Konuk memnun olur: “Ne kadar kolaymış.” Askıdaki havlu o gün yıkanmaz; su ve deterjan harcanmaz, konuğun konforu da aynı kalır."},{"metin":"Nasıl isterseniz efendim, kat görevlisine söylerim, merak etmeyin.","puan":1,"tepki":"İstek yerine gelir, ama konuk askı ve kart düzenini öğrenmez. Konuğa seçimini kendisinin nasıl yapacağını göstermek daha kalıcıdır."}]},{"konuk":"Bu sabah kahvaltıda bazı konuklar tabaklarında çok yemek bıraktı. Onlara bir şey söylüyor musunuz?","ingilizce":"At breakfast this morning, some guests left a lot of food on their plates. Do you say anything to them?","secenekler":[{"metin":"Evet, tabağında yemek bırakanı uyarıyoruz, gerekirse ek ücret bile istiyoruz efendim.","puan":0,"tepki":"Bu söz hem gerçek değil hem de konuğu ürkütür. Konuk ağırlanan kişidir; çevre davranışı suçluluk hissettirmeden, nazik bir davetle yaygınlaştırılır."},{"metin":"Pek bir şey diyemiyoruz efendim, konuklar istediği kadar alabiliyor.","puan":1,"tepki":"Konuk biraz hayal kırıklığına uğrar. Konuğu zorlamamak doğru, ama otelin kartlarla yaptığı nazik bilgilendirme anlatılabilirdi."},{"metin":"Zorlamıyoruz; salondaki küçük kartlarla yemeği ihtiyaç kadar almayı rica ediyoruz.","ingilizce":"We don’t force anyone; small cards in the breakfast room kindly ask guests to take only what they need.","puan":2,"tepki":"Konuk “Bu çok zarif bir yol” der. Kahvaltı salonundaki küçük kartlar, konuğu suçlamadan yemeği ihtiyacı kadar almaya davet eder."}]},{"konuk":"Dürüst cevaplarınız için teşekkürler. Burada kendimi iyi hissediyorum.","ingilizce":"Thank you for your honest answers. I feel good staying here.","secenekler":[{"metin":"Biz teşekkür ederiz. Bir öneriniz olursa bize iletebilirsiniz; iyi akşamlar dileriz.","ingilizce":"Thank you. If you have any suggestions, please let us know. Have a lovely evening.","puan":2,"tepki":"Konuk gülümseyerek ayrılır. Az ama gerçek bir adımı dürüstçe anlatan otel, büyük ama boş sözlerle anlatan otelden daha çok güven kazanır."},{"metin":"Rica ederim efendim, ne demek; iyi akşamlar dilerim.","puan":1,"tepki":"Konuk teşekkür eder ama sohbet soğuk biter. Konuğun ilgisine teşekkür edip önerisini sormak, iyi bir sohbeti güzel kapatır."},{"metin":"Bir dahaki sefere broşürü daha dikkatli okur, soruları da önceden hazırlarsınız o zaman.","puan":0,"tepki":"Konuk şaşırır ve kırılır. Broşürdeki abartının sorumluluğu konuğa atılamaz; nazik hitap ve teşekkür, iyi geçen bir görüşmeyi korur."}]}]},{"id":"mg-d09","unite":5,"baslik":"Kahvaltıya Yetişemeyen Konuklar","rol":"Stajyer (yiyecek içecek)","karsi":"Amir","sahne":"Saat 07.20, otelin kahvaltı salonu. Stajyer Deniz, sabah erken yola çıkan tur konuklarının üç gündür kahvaltıya oturmadan otelden ayrıldığını fark etmiş. Restoran şefi Nuray Hanım, salonun kapısına bakıp duran stajyerin yanına geliyor.","kavramlar":["mg-5-006","mg-5-035","mg-5-088","mg-5-039","mg-5-040"],"adimlar":[{"konuk":"Deniz, üç gündür gözün hep kapıda. Bir sorun mu var?","ingilizce":"Deniz, you've been watching the door for three days. Is something wrong?","secenekler":[{"metin":"Konuklar aç gidiyor; yarın kimseye sormadan kapıya bir paket masası kuracağım.","puan":0,"tepki":"Şefin yüzü asılır: “Kimseye sormadan mı?” İç girişimcilik, fikrin yönetimin onayıyla hayata geçirilmesidir; tek başına karar vermek ekibi zor durumda bırakır."},{"metin":"Yok bir şey şefim, öylesine bakıyordum. Kusura bakmayın, hemen işimin başına dönüyorum.","puan":1,"tepki":"Şef omuz silker ve gider. Kabalık yok, ama fark edilen bir aksaklık söylenmeyince işletme bir fırsatı kaçırır."},{"metin":"Şefim, erken çıkan konuklar kahvaltısız gidiyor. Gördüklerimi anlatabilir miyim?","ingilizce":"Chef, the guests who leave early are going without breakfast. May I tell you what I've noticed?","puan":2,"tepki":"Şef ilgiyle dinlemeye hazırlanır. İç girişimcilikte doğru yol, fark edilen aksaklığı ve fikri önce amire götürmektir."}]},{"konuk":"Anlat bakalım. Sence asıl sorun ne?","ingilizce":"Go on, then. What do you think the real problem is?","secenekler":[{"metin":"Üç sabah not tuttum: çoğu konuk salon açılmadan çıkıyor. Sorun beğeni değil, zaman.","ingilizce":"I took notes for three mornings: most guests leave before the restaurant opens. It isn't the food; it's the time.","puan":2,"tepki":"Şef başını sallar: “Bunu hiç böyle düşünmemiştim.” Gözlemleyerek ve dinleyerek kullanıcıyı anlamak, asıl problemi görünür kılar."},{"metin":"Bence menümüz az şefim; çeşidi artırırsak konuklar oturur, kahvaltısını yapıp öyle çıkar.","puan":1,"tepki":"Şef düşünür: “Emin misin?” Bu bir tahmin; görünen sorun ile asıl problem farklı olabilir, önce gözlem gerekir."},{"metin":"Konuklar aceleci ve sabırsız şefim; bu onların sorunu, bizim değil.","puan":0,"tepki":"Şef kaşlarını çatar. Konuğun yerine kendini koymadan sorunu ona yüklemek, empati kurmanın tam tersidir."}]},{"konuk":"Peki ne öneriyorsun? Büyük bir masraf yapamayız, bilirsin.","ingilizce":"So what do you suggest? We can't spend a lot, you know.","secenekler":[{"metin":"Salonu yarından itibaren her gün bir saat erken açalım, bütün vardiyaları da ona göre değiştirelim.","puan":1,"tepki":"Şef tereddüt eder: “Bu, bütün ekibin düzenini değiştirir.” Fikir denenmeden büyük bir değişikliğe gitmek, yanılırsak pahalıya mal olur."},{"metin":"Önce küçük deneyelim: yarın birkaç konuğa basit bir paket kahvaltı hazırlayalım.","ingilizce":"Let's start small: tomorrow we could prepare a simple packed breakfast for a few guests.","puan":2,"tepki":"Şef gülümser: “Bu masrafı kaldırırız.” Prototip hızlı ve ucuz bir ilk örnektir; fikrin işe yarayıp yaramadığını az kayıpla gösterir."},{"metin":"Bütün gruba paket hazırlayalım, ücretini de sormadan odalara ekleyelim.","puan":0,"tepki":"Şef hemen itiraz eder: “Konuğa sormadan ücret mi yazacağız?” Konuğun onayını almadan ücret eklemek güveni bozar; fikir önce küçük bir denemeyle sınanmalıdır."}]},{"konuk":"Tamam, yarın on paketle deneyelim. Deneme bitince ne yapacaksın?","ingilizce":"All right, let's try it with ten packs tomorrow. What will you do once the trial is over?","secenekler":[{"metin":"Paketi alanlara ne eksik, ne fazla diye soracağım; cevaplara göre düzeltiriz.","ingilizce":"I'll ask the guests who take a pack what was missing or unnecessary, and we'll improve it based on their feedback.","puan":2,"tepki":"Şef memnun olur: “İşte bu.” Prototipi gerçek kullanıcıların denemesine sunup geri bildirime göre düzeltmek, test etme aşamasının ta kendisidir."},{"metin":"Konuklar ne derse desin, ben paketin iyi olacağından eminim şefim.","puan":0,"tepki":"Şef ciddileşir. Test bir sınav değil, öğrenme fırsatıdır; kullanıcıyı dinlemeye kapalı olan, fikrini geliştiremez."},{"metin":"Paketlerin hepsi biterse deneme başarılı sayılır; ertesi gün bütün konuklara başlarız.","puan":1,"tepki":"Şef ekler: “Bitti diye beğenildi mi demek?” Paketin alınması tek başına yetmez; kullanıcının görüşü sorulmadan neyin düzeltileceği bilinmez."}]},{"konuk":"Dün paket alan konuklardan biri “Su yoktu, meyve de ezilmişti” demiş. Ne düşünüyorsun?","ingilizce":"One of the guests who took a pack yesterday said, “There was no water, and the fruit was squashed.” What do you think?","secenekler":[{"metin":"Doğrusu biraz üzüldüm şefim, ama olsun; bence paket yine de gayet iyiydi, böyle kalsın.","puan":1,"tepki":"Şef “Peki, neyi değiştireceğiz?” diye sorar. Üzülmek doğal, ama geri bildirimden bir düzeltme çıkarılmazsa deneme yarım kalır."},{"metin":"Çok işime yaradı şefim. Su ekleyip meyveyi kutuya koyalım, yarın yeniden deneyelim.","ingilizce":"That's really useful, Chef. Let's add water, put the fruit in a box and try again tomorrow.","puan":2,"tepki":"Şef onaylar: “Yarın yine bakarız.” Eleştiri fikri güçlendirir; gerekirse prototip yenilenip yeniden denenir."},{"metin":"O konuk her şeye kusur bulur; bu yorumu hiç saymayalım bence.","puan":0,"tepki":"Şef kabul etmez: “Eksik gerçekse eksiktir.” Kullanıcının söylediğini yok saymak, denemenin amacını boşa çıkarır."}]},{"konuk":"Güzel iş, Deniz. Önerini müdüre götüreceğim; toplantıda sen de anlatır mısın?","ingilizce":"Good work, Deniz. I'll take your idea to the manager; would you present it at the meeting too?","secenekler":[{"metin":"Olur şefim, ama kalabalık önünde çok heyecanlanırım; siz anlatsanız bence daha iyi olur.","puan":1,"tepki":"Şef anlayışla karşılar ama biraz hayal kırıklığına uğrar. Fikri geliştiren kişinin kendi gözlemlerini anlatması öneriyi güçlendirir."},{"metin":"Fikir benim şefim; müdüre doğrudan ben giderim, aradan size gerek kalmaz bence.","puan":0,"tepki":"Şefin yüzü değişir. İç girişimcilikte fikir önce amire götürülür ve yönetimin onayıyla ilerler; amiri atlamak ekip içindeki güveni zedeler."},{"metin":"Memnuniyetle şefim. Notlarımı ve konukların sözlerini kısa bir sayfada toplarım.","ingilizce":"With pleasure, Chef. I'll put my notes and the guests' comments together on one page.","puan":2,"tepki":"Şef gururla gülümser: “Yarın sabah toplantıda görüşürüz.” Gözlemden denemeye uzanan bu yol, bir stajyerin bile işletmeye değer katabileceğini gösterir."}]}]},{"id":"mg-d10","unite":5,"baslik":"Pansiyon Hayalinin Hesabı","rol":"Resepsiyonist","karsi":"Usta","sahne":"Ekim akşamı, sezon yeni kapanmış. Genç resepsiyonist Efe, kasabasında küçük bir pansiyon açmayı düşünüyor. Yıllardır kendi pansiyonunu işleten Selim Usta ile bahçede çay içerken fikrini anlatıyor.","kavramlar":["mg-5-042","mg-5-050","mg-5-016","mg-5-066","mg-5-084"],"adimlar":[{"konuk":"Pansiyon açacakmışsın, duydum. Kimi ağırlamayı düşünüyorsun?","ingilizce":"I hear you're planning to open a guesthouse. Who do you want to host?","secenekler":[{"metin":"Herkesi usta! Fiyatı kasabanın en ucuzu yaparım, kim gelirse gelsin, yeter ki oda dolsun.","puan":0,"tepki":"Usta güler: “Herkese satan kimseye tam uyamaz.” Hedef kitle belli olmadan fiyat, sunum ve tanıtım doğru seçilemez."},{"metin":"Hafta sonu şehirden gelen, doğa yürüyüşü seven çiftleri. Patika tam arkamızda.","ingilizce":"Couples from the city who come at the weekend and love hiking. The trail starts right behind us.","puan":2,"tepki":"Usta başını sallar: “Ne istediklerini de bilirsin o zaman.” Hedef kitle belli olunca fiyat, sunum ve tanıtım ona göre seçilir."},{"metin":"Çiftleri düşündüm ama aileler, gruplar da gelsin; kimseyi kaçırmayayım.","puan":1,"tepki":"Usta “Hepsine birden nasıl uyacaksın?” diye sorar. Başlangıç doğru, ama hedef kitle daraltılmazsa işletme kimseye tam uyamaz."}]},{"konuk":"Peki hesabını yaptın mı? Bu iş kendini döndürür mü?","ingilizce":"Have you done the sums, then? Will this business pay for itself?","secenekler":[{"metin":"Birikimim ve bir krediyle açılışı karşılarım; gerisini konuk gelince düşünürüm.","puan":1,"tepki":"Usta kaşlarını kaldırır: “Ya konuk geç gelirse?” Açılış parası bir başlangıçtır; işin kendini çevirip çevirmeyeceği ayrıca hesaplanmalıdır."},{"metin":"Hesaba gerek yok usta; kasabada herkes pansiyondan kazanıyor.","puan":0,"tepki":"Usta ciddileşir: “Herkesin kazandığını nereden biliyorsun?” Fizibilite iyimser tahminle değil, araştırmadan gelen gerçek bilgiyle yapılır."},{"metin":"Kuruluş giderini, aylık giderleri ve beklediğim geliri alt alta yazıyorum.","ingilizce":"I'm writing down the start-up costs, the monthly expenses and the income I expect, one under the other.","puan":2,"tepki":"Usta memnun olur: “Tutmazsa da üzülme, o da bir sonuçtur.” Finansal fizibilite, işe başlamadan önce işin yapılabilir ve kazançlı olup olmadığını hesaplamaktır."}]},{"konuk":"Açılış günü masraf bitmez ki. İlk konuk gelene kadar kirayı, faturayı, ücreti de ödersin. Onları yazdın mı?","ingilizce":"The spending doesn't stop on opening day. Until the first guests arrive, you still pay rent, bills and wages. Have you included those?","secenekler":[{"metin":"Yazmamıştım. İlk ayların kira, fatura ve ücretlerini ekleyip yeniden hesaplayacağım.","ingilizce":"I hadn't. I'll add the first few months' rent, bills and wages and redo the figures.","puan":2,"tepki":"Usta rahatlar: “Çoğu kişi tam burada yanılıyor.” Finansal kaynak yalnız açılış için değil, ilk ayların giderleri için de gerekir."},{"metin":"Gerekirse çalışanların maaşını birkaç ay geciktiririm; iş açılınca öderim, anlarlar nasılsa.","puan":0,"tepki":"Usta sert çıkar: “Emeğinin karşılığını bekleyen insanı mağdur mu edeceksin?” Girişimci çalışanlarına karşı da dürüst ve güvenilir olmak zorundadır."},{"metin":"Yazmadım ama ailemden biraz borç alırım, bir şekilde idare ederiz.","puan":1,"tepki":"Usta sorar: “Ne kadar alacaksın, ne zaman ödeyeceksin?” Aileden alınan borç bir finansal kaynaktır, ama tutarı hesaplanmadan alınırsa sorun yalnız ertelenir."}]},{"konuk":"Yazın bir kat görevlisi alacaksın. Kuzenin “sigortasız çalışırım” diyormuş, ucuza gelir.","ingilizce":"You'll need a room attendant for the summer. Your cousin says he'll work without insurance; it would be cheaper.","secenekler":[{"metin":"Bilmiyorum usta, muhasebeciye sorarım; o ne derse onu yaparım.","puan":1,"tepki":"Usta hatırlatır: “Bu senin sorumluluğun.” Yardım almak iyidir, ama çalıştırdığı kişiyi SGK’ya bildirmek işverenin kendi bilmesi gereken zorunluluktur."},{"metin":"Ucuza geliyorsa olur; aile içinde kimse şikâyet etmez zaten.","puan":0,"tepki":"Usta başını iki yana sallar: “Ya merdivenden düşerse?” Sigortasız çalıştırmak yasaya aykırıdır ve çalışanı iş kazasında korumasız bırakır."},{"metin":"Olmaz usta. Kim olursa olsun işe başlamadan SGK’ya bildiririm.","ingilizce":"No way. Whoever it is, I'll register them with the Social Security Institution before they start work.","puan":2,"tepki":"Usta onaylar: “Doğrusu bu.” İşveren çalıştırdığı her kişiyi SGK’ya bildirmek zorundadır; bu, çalışanı iş kazasında ve hastalıkta korur."}]},{"konuk":"Bir de internetteki fotoğraflar. Komşu pansiyon başka bir yerin deniz manzarasını koymuş, odaları dolmuş.","ingilizce":"And the photos online. The guesthouse next door posted a sea view from somewhere else, and now they're fully booked.","secenekler":[{"metin":"Odaların gerçek fotoğrafını koyarım; konuk geldiğinde ilandakini görmeli.","ingilizce":"I'll post real photos of the rooms; when guests arrive, they should see exactly what was advertised.","puan":2,"tepki":"Usta gülümser: “Konuk bir daha gelir, arkadaşını da getirir.” Müşteriyi yanıltmadan kazanılan güven, işletmenin itibarını korur."},{"metin":"Gerçek fotoğrafları koyarım ama filtreyle biraz güzelleştiririm, herkes yapıyor.","puan":1,"tepki":"Usta uyarır: “Konuk gelince farkı görür.” Gerçeği temel almak doğru, ama abartılan görüntü konuğun beklentisini boşa çıkarabilir."},{"metin":"Ben de yaparım; konuk bir kez geldi mi zaten geri dönmez.","puan":0,"tepki":"Usta üzülür: “Kötü yorumlar da arkasından gelir.” Müşteriyi yanıltarak elde edilen kısa vadeli kazanç, güven kaybına ve itibarın zarar görmesine yol açar."}]},{"konuk":"Aferin sana. Hesabı bitirince getir, birlikte bakalım.","ingilizce":"Well done. Bring the figures when you've finished, and we'll go through them together.","secenekler":[{"metin":"Sağ olun usta, bir ara getiririm; acelesi yok nasılsa, kış uzun, daha çok vaktim var.","puan":1,"tepki":"Usta “Sen bilirsin” der. Nazik bir cevap, ama deneyimli birinin desteğini ertelemek, hesaptaki eksikleri geç görmek demektir."},{"metin":"Teşekkür ederim usta. Hesabı yazıp önümüzdeki hafta getiririm.","ingilizce":"Thank you. I'll write up the figures and bring them over next week.","puan":2,"tepki":"Usta çayını tazeler: “Bekliyorum.” Hesabı yazıya dökmek ve deneyimli birine göstermek, iyimser tahminleri gerçekle sınamayı sağlar."},{"metin":"Gerek yok usta, kafamda her şey hazır; hiç beklemeden hemen başlayacağım.","puan":0,"tepki":"Usta sessizce çayını içer. Yazıya dökülmeyen ve kimseye gösterilmeyen hesap, işe başlamadan önce yapılması gereken fizibiliteyi atlamak demektir."}]}]},{"id":"mg-d11","unite":6,"baslik":"Kahvaltı Paylaşımı Kimin Karesiyle?","rol":"Satış ve pazarlama stajyeri","karsi":"Amir","sahne":"Saat 16.00, otelin satış ve pazarlama ofisi. Yeni kahvaltı menüsü yarın sabah otelin sosyal medya hesabında duyurulacak. Satış müdürü, paylaşımı hazırlama işini stajyere veriyor.","kavramlar":["mg-6-037","mg-6-038","mg-6-007","mg-6-039","mg-6-004"],"adimlar":[{"konuk":"Yarın sabah yeni kahvaltıyı duyuracağız. İnternetten güzel bir kahvaltı fotoğrafı bul, paylaşıma koy.","ingilizce":"We're announcing the new breakfast tomorrow morning. Find a nice breakfast photo online and put it in the post.","secenekler":[{"metin":"İnternetteki fotoğrafların çoğunun sahibi var; kahvaltımızı kendim çekeyim.","ingilizce":"Most photos online belong to someone; let me photograph our own breakfast.","puan":2,"tepki":"Müdür başını sallar: “Doğru, başka yerin kahvaltısı konuğu yanıltır zaten.” “İnternette buldum” demek “kullanabilirim” demek değildir; en güvenli yol fotoğrafı kendin çekmektir."},{"metin":"Tamam, bulurum. Yalnız kullanmadan önce fotoğrafın sahibi kim, bir bakarım.","puan":1,"tepki":"Müdür “olur” der, ama paylaşım yine başka bir yerin kahvaltısını gösterecektir. Sahibini sormak doğru yönde bir adım; yine de kendi ürünümüzü kendimiz çekmek hem güvenli hem dürüst olurdu."},{"metin":"Rakip otelin sitesinde çok güzel bir kahvaltı karesi var, hemen onu indiriyorum.","puan":0,"tepki":"Müdürün kaşları çatılır: “Bizim masamız öyle değil ki!” Başkasının fotoğrafını izinsiz kullanmak hem telif hakkını çiğner hem de konuğa başka yerin kahvaltısını göstererek onu yanıltır."}]},{"konuk":"Güzel kareler çekmişsin. Pencere kenarında kahvaltı eden bir aile de görünüyor, yüzleri belli. En sıcak kare bu, bunu paylaşalım.","ingilizce":"These are lovely shots. There's a family having breakfast by the window, and you can see their faces. This is the warmest shot, so let's post it.","secenekler":[{"metin":"Fotoğrafı ben çektim, yani paylaşma hakkı da bizde; hemen yüklüyorum, merak etmeyin.","puan":0,"tepki":"Müdür durur: “Aile bunu görürse ne der?” Fotoğrafı çekmiş olmak paylaşma hakkı vermez; karede tanınan kişinin kendi görüntüsü üzerinde hakkı vardır ve açık izni gerekir."},{"metin":"Önce aileye sorayım; izin vermezlerse yüzlerin görünmediği kareyi kullanırız.","ingilizce":"Let me ask the family first; if they say no, we'll use the shot without their faces.","puan":2,"tepki":"Aile gülümseyerek izin verir, hatta paylaşımı görmek istediklerini söyler. Konuğun tanınabildiği bir kare yalnız onun açık izniyle yayımlanır; izin vermeyenin görüntüsü kullanılmaz."},{"metin":"Yüzlerin görünmediği ikinci kareyi kullanalım, o zaman kimseye sormamız gerekmez.","puan":1,"tepki":"Müdür kabul eder, ama ikinci kare daha soğuktur. Sorunsuz bir yol seçildi; yine de aileden açık izin istemek en sevilen kareyi de kurtarabilirdi."}]},{"konuk":"Aile izin verdi, harika. Videoya da fon müziği koyalım; telefonumdaki müzik uygulamasında çok sevdiğim bir şarkı var.","ingilizce":"The family said yes, brilliant. Let's add some background music to the video too; there's a song I love on the music app on my phone.","secenekler":[{"metin":"Uygulamaya üyesiniz, şarkıyı satın almış sayılırsınız. Doğrudan videoya ekliyorum.","puan":0,"tepki":"Müdür emin olamaz: “Gerçekten öyle mi?” Bir şarkıyı dinleme hakkı almak seni onun sahibi yapmaz; şarkıyı kendi paylaşımında yaymak için hak sahibinin izni gerekir."},{"metin":"Bu şarkıyı koymayalım bence; videoyu hiç müzik koymadan, sessiz paylaşırız.","puan":1,"tepki":"Müdür biraz hayal kırıklığına uğrar: “Sessiz video sönük kalır.” Kural çiğnenmedi, ama nedeni anlatılmadı ve izinli müzik bulma yolu hiç önerilmedi."},{"metin":"Şarkıyı paylaşıma koymak izne bağlı; izinli, serbest bir müzik bulayım.","ingilizce":"Putting that song in our post needs permission; let me find some openly licensed music.","puan":2,"tepki":"Müdür “Haklısın, başımız ağrımasın” der. Bir şarkıyı paylaşıma koyup herkese ulaştırmak, eser sahibinin mali haklarındandır ve izne bağlıdır."}]},{"konuk":"Buldun mu bir şey? Bir müzik sitesinde “CC BY” yazıyormuş. Bu ne demek, açıklamaya bir şey yazmamız gerekiyor mu?","ingilizce":"Did you find anything? A music site says “CC BY”. What does that mean? Do we need to write anything in the caption?","secenekler":[{"metin":"CC zaten serbest demek, koşullarına bakmadım. Açıklamaya bir şey yazmaya gerek yok.","puan":1,"tepki":"Müdür tedirgin olur: “Emin misin?” CC lisanslarının koşulları birbirinden farklıdır; bazıları ticari kullanıma izin vermez. Otelin tanıtım paylaşımından önce lisansın koşulu okunmalıydı."},{"metin":"Besteciyi anmak şartıyla kullanabiliyoruz; adını ve lisansı yazıyorum.","ingilizce":"We can use it as long as we credit the composer; I'm adding their name and the licence.","puan":2,"tepki":"Müdür açıklamayı okur ve onaylar. Creative Commons’ta eser sahibi koşullarını önceden ilan eder; CC BY’de koşul adını belirtmektir ve okunarak uygulanır."},{"metin":"Bestecinin adını yazmasak da olur bence; açıklama çok kalabalık görünür sonra.","puan":0,"tepki":"Müdür itiraz eder: “Ama kural bu değil miydi?” CC BY’nin koşulu eser sahibinin adını belirtmektir; adı yazmadan kullanmak, izin verilen yolun dışına çıkmaktır."}]},{"konuk":"Bugün az kalsın birkaç hata yapıyorduk. Eline sağlık, paylaşım çok güzel oldu.","ingilizce":"We nearly made a few mistakes today. Well done, the post looks great.","secenekler":[{"metin":"Teşekkürler. Aile fotoğrafı çok güzel oldu, kendi hesabımda da paylaşayım.","puan":0,"tepki":"Müdürün yüzü değişir: “Olmaz, aile otele izin verdi, sana değil.” Stajyer konukları kişisel hesabında paylaşmaz; verilen izin yalnız otelin paylaşımı içindir."},{"metin":"Rica ederim. Ama açıkçası bu kadar kurala gerçekten gerek var mıydı, bilemedim.","puan":1,"tepki":"Müdür gülümser ama kısaca anlatır: her fotoğrafın ve şarkının arkasında birinin emeği vardır. Doğru işi yaptın; emeğe saygının nedenini görmek de işin parçasıdır."},{"metin":"Teşekkür ederim. İzinleri ve lisansı bir dosyaya not edeyim, sonra işe yarar.","ingilizce":"Thank you. I'll note the permissions and the licence in a file; it'll come in handy.","puan":2,"tepki":"Müdür “Bunu ekibe de örnek göstereceğim” der. Hangi görselin ve müziğin hangi izinle kullanıldığını bilmek, “bilmiyordum” durumuna düşmemenin yoludur."}]}]},{"id":"mg-d12","unite":6,"baslik":"Kat Arabasındaki Raf Kimin?","rol":"Kat hizmetleri stajyeri","karsi":"Tedarikçi","sahne":"Saat 10.30, otelin üçüncü katı. Kat hizmetleri stajyeri, havluların yere düşmesini önlemek için kat arabasına kendi tasarladığı katlanır bir raf eklemiş. Kat arabalarının bakımına gelen tedarikçi firma temsilcisi rafı fark ediyor.","kavramlar":["mg-6-013","mg-6-060","mg-6-052","mg-6-057","mg-6-011"],"adimlar":[{"konuk":"Günaydın, arabaların bakımı için geldim. Bu katlanır raf ne? Havlular hiç düşmüyor, böylesini ilk kez görüyorum.","ingilizce":"Good morning, I'm here to service the trolleys. What's this folding shelf? The towels don't fall at all; I've never seen anything like it.","secenekler":[{"metin":"Teşekkürler, denediğim bir fikir. Ayrıntısı için önce amirime danışmalıyım.","ingilizce":"Thanks, it's an idea I'm trying out. I need to speak to my supervisor before sharing the details.","puan":2,"tepki":"Temsilci saygıyla “Anlıyorum” der. Nazik bir dille fikir sahiplenildi ve korunmaya değer bir fikrin ayrıntısı başvurudan önce paylaşılmadı."},{"metin":"Havlular düşmesin diye arabaya bir raf ekledim, o kadar. Başka bir şey yok.","puan":1,"tepki":"Temsilci “Ama çok işe yarıyor!” diye ısrar eder. Fikri genel hatlarıyla söylemek sorun değil; yine de konunun amire danışılacağını belirtmek sonraki soruları baştan yönetirdi."},{"metin":"Benim buluşum! Gelin, nasıl yaptığımı adım adım göstereyim, her parçasını anlatırım.","puan":0,"tepki":"Temsilci not almaya başlar. Fikrin bütün ayrıntısını başvurudan önce anlatmak risklidir: başkası senden önce başvurabilir, fikir de yeniliğini yitirebilir."}]},{"konuk":"Bence biz bunu üretebiliriz. Ölçülerini ve çizimini bana e-postayla atar mısın? Satış ekibimize göstereyim.","ingilizce":"I think we could manufacture this. Could you email me the measurements and a drawing? I'd like to show our sales team.","secenekler":[{"metin":"Tabii, akşam çizimleri atarım. Fikrin kimden çıktığı nasılsa belli, sorun olmaz.","puan":0,"tepki":"Temsilci sevinir, ama stajyer büyük bir risk aldı. İlk başvuran ilkesine göre hak, fikri ilk düşünene değil, başvurusunu ilk yapana tanınır."},{"metin":"Çizimi şimdilik atmayayım; ama isterseniz telefonumdan birkaç fotoğrafını çekebilirsiniz.","puan":1,"tepki":"Temsilci fotoğrafları çeker. Yarım bir önlem alındı: rafın fotoğrafları da nasıl çalıştığını büyük ölçüde gösterir."},{"metin":"Önce fikir korunmalı; başvurudan önce çizim paylaşırsam yeniliğini yitirebilir.","ingilizce":"The idea needs protecting first; if I share drawings before applying, it could lose its novelty.","puan":2,"tepki":"Temsilci “Mantıklı” der ve ısrar etmez. Başvurudan önce kamuya açıklanan buluş yeni sayılmayabilir; ayrıca başkası senden önce başvurabilir."}]},{"konuk":"Anladım. Ama böyle küçük bir eklentiye koruma verilir mi? Sıfırdan bir buluş değil ki bu.","ingilizce":"I see. But would a small add-on like this really get protection? It's hardly a brand-new invention.","secenekler":[{"metin":"Sıfırdan değil, ama var olan arabaya pratik yarar katıyor; faydalı modelle korunabilir.","ingilizce":"It isn't from scratch, but it adds a practical benefit to an existing trolley; it could be protected as a utility model.","puan":2,"tepki":"Temsilci etkilenir: “Bunu bilmiyordum.” Faydalı model, mevcut bir ürüne kullanım kolaylığı katan yeni çözümleri korur; patentten farklı olarak buluş basamağı aranmaz."},{"metin":"Küçük de olsa her fikir kendiliğinden korunur; kuruma başvurmaya hiç gerek yok.","puan":0,"tepki":"Temsilci şaşırır: “Öyleyse herkes kopyalayabilir mi?” Kendiliğinden doğan koruma telif hakkıdır; teknik çözümlerde koruma kural olarak tescille elde edilir."},{"metin":"Bilmiyorum açıkçası; ben yalnızca kat stajyeriyim, bu işleri uzmanlar bilir.","puan":1,"tepki":"Temsilci omuz silker. Uzmana danışmak doğru, ama mucit kendi fikrini küçümsememeli: mevcut araçtaki pratik iyileştirmeler için faydalı model diye bir koruma vardır."}]},{"konuk":"Peki ya aynısı zaten satılıyorsa? Yurt dışındaki bir fuarda benzer bir raf görmüş olabilirim.","ingilizce":"But what if the same thing is already on sale? I may have seen a similar shelf at a trade fair abroad.","secenekler":[{"metin":"Türkiye’de hiç görmedim; o yüzden burada yeni sayılır diye düşünüyorum doğrusu.","puan":1,"tepki":"Temsilci emin olamaz. Yenilik yalnız Türkiye’ye göre değil, bütün dünyaya göre değerlendirilir; yurt dışındaki fuarda sergilenen ürün de hesaba girer."},{"metin":"Önce patent veri tabanlarına bakalım; dünyada açıklanmışsa yeni sayılmaz.","ingilizce":"Let's search the patent databases first; if it's been made public anywhere in the world, it isn't new.","puan":2,"tepki":"Temsilci “Akıllıca” der. Patent araştırması aynı şeyi yeniden icat etmeyi önler ve fikrin gerçekten yeni olup olmadığını başvurudan önce gösterir."},{"metin":"Görmüş olsanız da fark etmez. Ben kendi kafamdan buldum, o yüzden benim sayılır.","puan":0,"tepki":"Temsilci gülümser ama ikna olmaz. Kendi başına bulmak yetmez: aynısı dünyada daha önce açıklanmışsa buluş yeni sayılmaz ve koruma alamaz."}]},{"konuk":"Anlaştık. Koruma işi netleşince bizi arayın, üretimi konuşuruz. Kartımı bırakıyorum.","ingilizce":"Agreed. Once the protection side is sorted, give us a call and we'll talk about production. I'll leave you my card.","secenekler":[{"metin":"Teşekkürler. Kartınızı amirime iletirim; süreç bitince sizi ararız.","ingilizce":"Thank you. I'll pass your card to my supervisor, and we'll call you once the process is complete.","puan":2,"tepki":"Temsilci memnun ayrılır. Fikrin ayrıntısı korundu, iş fırsatı da kaçmadı; doğru sıra önce koruma, sonra iş birliğidir."},{"metin":"Tamam, bir ara ben sizi ararım; kartınız bende kalsın, iyi günler.","puan":1,"tepki":"Temsilci kartı bırakıp gider. Görüşme kibar bitti, ama teşekkür eksik kaldı ve kartın amire iletileceği söylenmedi."},{"metin":"Aslında beklemeye gerek yok. Arabayı bir günlüğüne götürün, rahatça inceleyin.","puan":0,"tepki":"Temsilci şaşkınlıkla arabaya bakar. Ürünü incelemeye vermek bütün ayrıntıyı vermek demektir; bütün dikkat bir anda boşa gider."}]}]},{"id":"mg-d13","unite":7,"baslik":"Gece Vardiyasında Gelen Acil İleti","rol":"Stajyer resepsiyonist","karsi":"İş arkadaşı","sahne":"Saat 01.30, şehir otelinin resepsiyonu. Gece görevlisi Burak, ekranda “Rezervasyon sisteminiz kapatılacak, parolanızı doğrulamak için tıklayın.” yazan bir e-posta görür. Fareyi bağlantının üzerine götürmüş, yanındaki stajyere dönüp sorar.","kavramlar":["mg-7-041","mg-7-040","mg-7-037","mg-7-075","mg-7-039"],"adimlar":[{"konuk":"Şuna bak, sistem bu gece kapatılacakmış. Hemen tıklayıp parolamı gireyim mi?","ingilizce":"Look at this, they say the system will be shut down tonight. Shall I click and enter my password right now?","secenekler":[{"metin":"Hemen gir bence, sistem kapanırsa gece gelen konukların girişini yapamayız, sonra başımız ağrır.","puan":0,"tepki":"Burak tıklamak üzeredir. Acele ettirip parola isteyen ileti oltalamanın tipik işaretidir; korkuyla tıklamak tuzağın ta kendisidir."},{"metin":"Dur, tıklamayalım. Acele ettiriyor ve parola istiyor; bu bir oltalama iletisi olabilir.","ingilizce":"Wait, let's not click it. It's rushing us and asking for a password; this could be a phishing email.","puan":2,"tepki":"Burak elini fareden çeker: “Haklısın, gerçek bir firma parolayı e-postayla istemez.” Oltalamanın işaretlerini tanımak, en zayıf halka olan dikkatsiz tıklamayı önler."},{"metin":"Tıklama ama gece gece uğraşmayalım; sabah gündüz ekibi gelince sorarız, acelesi yok.","puan":1,"tepki":"Burak tıklamaz, ama ileti saatlerce kimseye bildirilmeden kalır. Aynı ileti başka çalışanlara da gelmiş olabilir; şüpheli ileti beklemeden amire bildirilir."}]},{"konuk":"Tamam, tıklamadım. Peki ne yapacağız, gece müdüründen başka kimse yok.","ingilizce":"All right, I didn't click it. So what do we do? There's nobody here except the night manager.","secenekler":[{"metin":"Silelim gitsin, kimseye söylemeye gerek yok; tıklamadık nasılsa, uzatmayalım şimdi.","puan":0,"tepki":"İleti kaybolur, kimsenin haberi olmaz. Oltalama iletisine cevap yazılmaz, tıklanmaz ve amire ya da bilgi işlem sorumlusuna bildirilir; susmak başkasını savunmasız bırakır."},{"metin":"Ekran görüntüsünü alıp ekibin mesaj grubuna atalım, herkes görsün ve dikkat etsin.","puan":1,"tepki":"Ekip uyarılmış olur, ama önlem alabilecek kişi resmî olarak haberdar edilmez. Bildirimin doğru adresi amir ya da bilgi işlem sorumlusudur."},{"metin":"İletiye dokunmadan gece müdürüne haber verelim; o da bilgi işlem sorumlusuna iletsin.","ingilizce":"Let's leave the email alone and tell the night manager; then they can pass it on to IT.","puan":2,"tepki":"Burak gece müdürünü arar, müdür hemen bilgi işleme yazar. Siber güvenlik herkesin işidir; şüpheli iletiyi doğru kişiye bildirmek bu işin parçasıdır."}]},{"konuk":"Bir sorun daha var: az önce yanlış parola denemekten kullanıcım kilitlendi. Senin parolanla girsem olur mu?","ingilizce":"There's another problem: my account got locked after I tried the wrong password. Could I log in with your password?","secenekler":[{"metin":"Olur, parolam ekranın kenarındaki kâğıtta yazıyor, oradan bakabilirsin.","puan":0,"tepki":"Burak kâğıdı okur; parola artık bankoya yaklaşan herkesin elinde. Parola kimseye söylenmez, kâğıda yazılıp ekrana yapıştırılmaz; vermek anahtarını ve imzanı vermek gibidir."},{"metin":"Parolamı veremem; sistem her işlemi kullanıcının adına yazar. Gece müdürü seninkini açtırsın.","ingilizce":"I can't share my password; the system records every action under the user who made it. The night manager can get yours unlocked.","puan":2,"tepki":"Burak başını sallar: “Doğru, sonra kim ne yaptı belli olmaz.” Her çalışanın kendi kullanıcısıyla girmesi, yapılan işin izlenebilir kalmasını sağlar."},{"metin":"Şimdilik ben gireyim, sen işlemi söyle ben yapayım; sabah kendi kullanıcını açtırırsın.","puan":1,"tepki":"İş yürür, parola da paylaşılmaz. Ama kilitlenen kullanıcı bildirilmediği için sorun sabaha kalır; bunu gece müdürünün bilmesi gerekir."}]},{"konuk":"Sistem gerçekten çökerse diye konuk listesini telefonuma fotoğraflayayım, elimizde dursun.","ingilizce":"In case the system really does crash, I'll take a photo of the guest list on my phone, just to have it.","secenekler":[{"metin":"Fotoğrafla, ekip grubuna da at; kime lazım olursa açar bakar, iş kolaylaşır.","puan":0,"tepki":"Konukların adları ve telefonları onlarca telefona dağılır. Konuk listesini fotoğraflayıp mesaj grubuna atmak, lobide unutulan kâğıttan daha hızlı yayılan bir veri ihlalidir."},{"metin":"Fotoğrafla ama sistem düzelince hemen sil, kimseye de gösterme, tamam mı?","puan":1,"tepki":"Niyet iyi, ama konuk verisi yine kişisel telefona geçmiş olur ve silinip silinmediğini kimse bilemez. Kişisel veri, işletmenin izin verdiği yolla korunur."},{"metin":"Telefonda kalırsa veri ihlaline yol açabilir. Yedek liste gerekirse gece müdürü karar versin.","ingilizce":"If it stays on your phone, it could lead to a data breach. If we need a backup list, the night manager should decide.","puan":2,"tepki":"Burak telefonunu cebine koyar. Konuk verisi yalnız yetkili kişilerce, gerekli amaçla görülür; emin olunmayan bir veri işinde amire sorulur."}]},{"konuk":"Gece müdürü yazdı: ileti sahteymiş, bilgi işlem engellemiş. İyi ki durdurdun beni.","ingilizce":"The night manager has just messaged: the email was fake, and IT have blocked it. Good thing you stopped me.","secenekler":[{"metin":"Birlikte fark ettik. Sabah ekibe de anlatalım: acele ettiren, parola isteyen iletiye tıklanmaz.","ingilizce":"We spotted it together. Let's tell the team in the morning: never click an email that rushes you and asks for a password.","puan":2,"tepki":"Burak gülümser: “Sabah toplantısında ben anlatırım.” Kimseyi suçlamadan öğrenileni ekiple paylaşmak, aynı tuzağa ikinci kez düşülmesini önler."},{"metin":"Neyse, geçti gitti artık. Ben dosyalarıma dönüyorum, yapacak çok işim var.","puan":1,"tepki":"Gece sakin biter, ama öğrenilen ders ikisinde kalır. Gündüz ekibine aynı ileti gelirse onlar uyarılmamış olur."},{"metin":"Bir dahakine tıklasan da sorun olmaz, bilgi işlem nasılsa düzeltir, büyütmeye gerek yok.","puan":0,"tepki":"Burak şaşırır: “Ama az önce tam tersini söyledin.” Konuk verisi bir kez çalınırsa güven sarsılır; en zayıf halka dikkatsiz bir tıklamadır ve güvenlik herkesin işidir."}]}]},{"id":"mg-d14","unite":7,"baslik":"Kioskun Önünde Yorgun Bir Çift","rol":"Stajyer ön büro görevlisi","sahne":"Saat 23.50, havalimanına yakın bir otelin lobisi. Yaşlı bir çift, self check-in kioskunun ekranına bakıp kalmış; Nermin Hanım çevresine yardım arar gibi bakıyor. Bankodaki stajyer onları fark ediyor.","kavramlar":["mg-7-014","mg-7-050","mg-7-016","mg-7-022","mg-7-020"],"adimlar":[{"konuk":"Bu makine bir şey soruyor, anlamadım. Burada bize yardım edecek kimse yok mu?","ingilizce":"This machine is asking me something and I don't understand. Is there anyone here who can help us?","secenekler":[{"metin":"Ekranda yazıyor efendim: rezervasyon numaranızı girin, sonra onaylayın.","puan":1,"tepki":"Nermin Hanım ekrana yeniden bakar ama yine çözemez. Bilgi doğru, fakat bankodan seslenmek yalnız bırakmaktır; kioskun yanındaki personel konuğun yanına gider."},{"metin":"Girişi kendiniz yapmanız gerekiyor efendim, gece bankoda işlem yapılmıyor maalesef.","puan":0,"tepki":"Nermin Hanım kırgın bir sesle “Biz bunu bilmeyiz ki.” der. Bu bir kural değildir; makineyi bahane edip konuğu yalnız bırakmak hizmeti bitirir."},{"metin":"İyi akşamlar. Hemen yardım edeyim; isterseniz girişinizi bankoda ben yapayım.","ingilizce":"Good evening. Let me help you straight away; if you like, I can check you in at the desk myself.","puan":2,"tepki":"Çiftin yüzü aydınlanır: “Ah, çok iyi olur.” Kiosk sırayı kısaltmak içindir; teknolojiye alışık olmayan konuğu güler yüzle karşılamak hâlâ personelin işidir."}]},{"konuk":"Oğlum telefondan her şeyi doldurduğunu söyledi. Kimliğimizi yine göstermemiz gerekiyor mu?","ingilizce":"My son said he filled everything in on his phone. Do we still need to show our ID?","secenekler":[{"metin":"Evet efendim, kısa bir kimlik kontrolü yapacağım; gerisi oğlunuz sayesinde çok çabuk.","ingilizce":"Yes, madam, I just need a quick look at your ID. Thanks to your son, the rest will be very quick.","puan":2,"tepki":"Nermin Hanım kimliğini rahatça uzatır. Mobil check-in form doldurma zamanını kazandırır; kimlik doğrulaması ise konuğun da güvenliği için otelde yapılır."},{"metin":"Evet, kimlik lazım. Kurallar böyle, ben karışamam; kimliğinizi verin lütfen.","puan":1,"tepki":"Nermin Hanım kimliğini uzatır ama azarlanmış gibi hisseder. Bilgi doğru, fakat nedeni nazikçe söylenseydi konuk kurala değil, özene dikkat ederdi."},{"metin":"Gerek yok efendim, adınız sistemde görünüyor; kartınızı hemen basıyorum, uzatmayalım.","puan":0,"tepki":"Çift sevinir, ama güvenlik kuralı çiğnenmiştir. Giriş telefonda başlasa da kimlik otelde doğrulanır; kimliği doğrulanmayan kişiye oda kartı verilmez."}]},{"konuk":"Oğlum odayı telefonla açabileceğimizi söyledi. Bizim öyle işlerle aramız yok; kart da olur mu?","ingilizce":"My son told us we could open the room with our phone. We're not very good with that sort of thing; is a card all right too?","secenekler":[{"metin":"Telefonla açmak çok daha pratik, bence bu gece öğrenmeniz iyi olur.","puan":1,"tepki":"Çift birbirine bakar; gecenin bu saatinde yeni bir şey öğrenmek istemedikleri belli. Dijital anahtar kolaylık içindir; konuğa zorla benimsetilmez."},{"metin":"Elbette, oda kartınızı hazırlıyorum. Kapıdaki kilide yaklaştırmanız yeterli.","ingilizce":"Of course, I'm preparing your key card now. You just need to hold it near the lock on the door.","puan":2,"tepki":"Nermin Hanım rahatlar: “Kart bize daha tanıdık.” Teknoloji amaç değil araçtır; konuğun kendini rahat hissettiği yolu seçmek iyi hizmettir."},{"metin":"Artık kart vermiyoruz, uygulamayı indirmeniz şart.","puan":0,"tepki":"Çift telaşlanır: “Gece yarısı ne yapacağız?” Kiosk da banko da oda kartı verebildiği hâlde yanlış bilgi vermek konuğun güvenini sarsar."}]},{"konuk":"Bir de şunu sorayım: kızım geçen ay aynı odayı bizden ucuza almış. Bu neden böyle?","ingilizce":"May I ask one more thing? My daughter booked the same room last month for less than us. Why is that?","secenekler":[{"metin":"Fiyatlar tarihe ve doluluğa göre değişebiliyor. İsterseniz satış ekibimiz yarın ayrıntıyı anlatsın.","ingilizce":"Rates can change with the dates and how full the hotel is. If you like, our sales team can explain it tomorrow.","puan":2,"tepki":"Nermin Hanım başını sallar: “Uçak biletinde de öyle oluyor.” Dinamik fiyatlama dürüstçe ve sakin bir dille açıklanınca konuk kendini kandırılmış hissetmez."},{"metin":"Bilmiyorum efendim, fiyatlara ben bakmıyorum; satış ekibi bilir, yarın gelip sorarsanız size anlatırlar.","puan":1,"tepki":"Dürüst bir cevap, ama konuk sorusunu cevapsız kalmış hisseder. Fiyatın tarihe ve doluluğa göre değiştiği sakin bir dille açıklanabilirdi."},{"metin":"Sistem hata yapmış olmalı, merak etmeyin, ben size de kızınızla aynı indirimi hemen yaparım.","puan":0,"tepki":"Nermin Hanım sevinir, ama verilen söz tutulamaz. Stajyerin fiyat indirme yetkisi yoktur; nedeni bilmeden “hata” demek de doğru değildir."}]},{"konuk":"Odada ışıkları nasıl yakacağız peki? Oğlum bu otellerde her şey ekranla diyor.","ingilizce":"And how do we turn the lights on in the room? My son says everything is done with a screen in these hotels.","secenekler":[{"metin":"Odadaki tablette her şey yazıyor, oradan bakarsınız; zor bir şey değil.","puan":1,"tepki":"Bilgi yanlış değil, ama ekrandan çekinen konuk yine ekrana yönlendirilir. Her konuk teknolojiye alışık değildir; göstermek personelin işidir."},{"metin":"Valizinize yardım edip odaya eşlik edeyim; ışıkları ve klimayı orada birlikte açalım.","ingilizce":"Let me help with your luggage and walk you to your room; we can switch on the lights and air conditioning together.","puan":2,"tepki":"Çift gülümser ve asansöre birlikte yürürler. Akıllı odanın düğmelerini nazikçe göstermek ve valize yardım etmek, makinenin veremediği insani dokunuştur."},{"metin":"Çok kolay, artık herkes kullanıyor; bir yerine basarsınız, açılır, merak etmeyin.","puan":0,"tepki":"Nermin Hanım utanır ve soru sormaktan vazgeçer. Konuğu küçümseyen bir söz, en hızlı girişin bıraktığı iyi izlenimi bile siler."}]},{"konuk":"Ne iyi ettiniz evladım. O makine bunu yapmazdı, çok teşekkür ederiz.","ingilizce":"That was very kind of you, dear. That machine couldn't have done this. Thank you so much.","secenekler":[{"metin":"Önemli değil efendim. Yarın kendiniz kiosktan yaparsınız artık, nasılsa öğrendiniz.","puan":1,"tepki":"Çift nazikçe gülümser, ama veda hoş geldin sıcaklığını taşımaz. Son cümle akılda kalır; iyi dilek ve gerektiğinde yardıma hazır olduğunu söylemek eksik kaldı."},{"metin":"Rica ederim, ama bir dahaki sefere oğlunuz size öğretsin; gece çok yoğun oluyoruz.","puan":0,"tepki":"Nermin Hanım’ın yüzündeki gülümseme söner. Konuğa yük olduğunu hissettirmek, bütün gece verilen emeği boşa çıkarır."},{"metin":"Rica ederim. Bir şeye ihtiyacınız olursa odadaki telefondan resepsiyonu arayın; iyi geceler.","ingilizce":"You're welcome. If you need anything, just call reception from the phone in your room. Good night.","puan":2,"tepki":"Çift odaya mutlu girer. Teknoloji işlemi hızlandırdı, konuğu ağırlayan ise insan oldu; rutin işi makine üstlendikçe bu beceri daha değerli olur."}]}]},{"id":"mg-d15","unite":8,"baslik":"Köşeler Yine Gevşek","rol":"Stajyer kat görevlisi","karsi":"Kat şefi","sahne":"Saat 09.10, üçüncü kat. Stajın ikinci haftası; kat şefi Nuran Hanım dün yatağın nasıl yapılacağını göstermişti. Bugün stajyerin hazırladığı ilk odaya giriyor ve yatağın köşelerine bakıyor.","kavramlar":["mg-8-015","mg-8-089","mg-8-031","mg-8-058","mg-8-057"],"adimlar":[{"konuk":"Günaydın. Yatak toplu görünüyor, ama köşeler yine gevşek. Ne yapalım sence?","ingilizce":"Good morning. The bed looks tidy, but the corners are loose again. What do you think we should do?","secenekler":[{"metin":"Anladım şefim, bir sonraki odada daha dikkatli yaparım.","puan":1,"tepki":"Şef başını sallar ama “Neyi farklı yapacaksın?” diye sorar. Niyet iyi, ama hatanın nedeni görülmeden denenen iş çoğu zaman aynı biçimde tekrarlanır."},{"metin":"Bir kez daha gösterir misiniz? Sonra ben yapayım, siz izleyip düzeltin.","ingilizce":"Could you show me once more? Then I'll do it and you can watch and correct me.","puan":2,"tepki":"Nuran Hanım gülümser: “İşte böyle öğrenilir.” İş başında öğrenmenin yolu izle, dene, geri bildirim al, yeniden dene döngüsüdür; ustanın gözü önünde denemek en hızlı yoldur."},{"metin":"Konuk fark etmez şefim, örtüyü üstüne çekince köşeler görünmüyor.","puan":0,"tepki":"Şefin yüzü ciddileşir: “Konuk yattığı an fark eder.” Eksiği küçümsemek, geri bildirimi kapatır; gelişme ancak eksik kabul edilince başlar."}]},{"konuk":"Bak, böyle. Şimdi sen yap. (İzler.) Bu köşe güzel oldu, şu köşe olmadı. Sence neden?","ingilizce":"Look, like this. Now you do it. (She watches.) This corner is good, that one isn't. Why do you think that is?","secenekler":[{"metin":"Çarşaf kısa gelmiş şefim, çamaşırhane yanlış boy göndermiş olmalı.","puan":0,"tepki":"Şef çarşafı açıp gösterir: boyu doğrudur. Hatayı başkasına yüklemek, ne yapıldığını düşünmeyi engeller; yansıtma önce kendi yaptığına bakmaktır."},{"metin":"Bilmiyorum şefim, ben hep aynı şekilde yaptığımı sanıyordum.","puan":1,"tepki":"Şef sabırla iki köşeyi yan yana gösterir. Dürüst bir cevap, ama fark aranmadığı için geri bildirimden çıkacak ders yarım kalır."},{"metin":"Bu köşede çarşafı germeden sıkıştırdım galiba; acele ettim.","ingilizce":"I think I tucked the sheet in without pulling it tight on this corner. I rushed it.","puan":2,"tepki":"Şef “Doğru tespit” der. Ne yaptığını durup düşünmek ve neyin işe yaramadığını söylemek yansıtmadır; nedeni bilen kişi düzeltmeyi de bilir."}]},{"konuk":"Öğleye kadar on odan var. Köşeler için nasıl bir yol izleyeceksin?","ingilizce":"You've got ten rooms before lunch. How are you going to work on the corners?","secenekler":[{"metin":"Her yatakta önce gevşek köşeye odaklanırım; ilk ikisine bakar mısınız?","ingilizce":"On every bed I'll focus on the loose corner first. Could you check the first two?","puan":2,"tepki":"Şef “Olur, ilk ikisine gelirim” der. Zorlanılan noktaya odaklanıp hedefle ve geri bildirim alarak tekrar etmek bilinçli alıştırmadır; gelişme oradan gelir."},{"metin":"Bütün yatakları baştan sona hızlıca yaparım; yaptıkça kendiliğinden oturur.","puan":1,"tepki":"Şef “Belki” der, pek ikna olmamıştır. Bildiğini tekrar etmek rahattır ama geliştirmez; zayıf kalan kısım hedeflenmezse aynı hata on kez tekrarlanabilir."},{"metin":"Köşeleri Serkan yapsın şefim, ben yastık ve havlulara bakayım.","puan":0,"tepki":"Şef kaşlarını kaldırır: “Sen ne zaman öğreneceksin?” Zorlanılan işten kaçmak, onu hiç öğrenmemek demektir; stajın amacı tam da o işi ustanın yanında öğrenmektir."}]},{"konuk":"Saat on iki. Son odalardaki köşeler düzelmiş. Yarın neye bakalım?","ingilizce":"It's twelve o'clock. The corners in the last rooms are much better. What should we look at tomorrow?","secenekler":[{"metin":"Artık oldu şefim, öğrendim; yarın kontrol etmenize gerek kalmaz.","puan":0,"tepki":"Şef güler: “Bir sabahta usta olunmaz.” Becerinin yerleşmesi tekrar ve dönüt ister; geri bildirimi erken kesmek gelişmeyi de keser."},{"metin":"Siz hangisini uygun görürseniz şefim, ben ona göre çalışırım.","puan":1,"tepki":"Şef “Sen ne düşünüyorsun?” diye sorar. Saygılı bir cevap, ama kendi gelişimini değerlendirmeyen kişi öğrenmesini başkasına bırakmış olur."},{"metin":"Sorun germeden sıkıştırmaktı, tekrar edince düzeldi. Yarın yastık kılıfına geçelim mi?","ingilizce":"The problem was not pulling the sheet tight, and practising fixed it. Shall we move on to pillowcases tomorrow?","puan":2,"tepki":"Şef memnun olur: “Yarın yastık kılıfı.” Neyin sorun olduğunu, neyin işe yaradığını ve sıradaki adımı söylemek yansıtmadır; ilerleme böyle görünür hâle gelir."}]},{"konuk":"Bugün iyi iş çıkardın. Yarın sabah dokuzda görüşürüz.","ingilizce":"You did a good job today. See you tomorrow at nine.","secenekler":[{"metin":"Teşekkür ederim şefim. Akşam bugünü öğrenme günlüğüme kısaca yazacağım.","ingilizce":"Thank you. This evening I'll write a short note about today in my learning journal.","puan":2,"tepki":"Şef “Güzel alışkanlık” der. Ne öğrenildiğini ve nerede zorlanıldığını düzenli yazmak, öğrenme günlüğünün işidir; ertesi gün nereden devam edileceği bellidir."},{"metin":"Sağ olun ama sabah her köşeyi düzelttirmeseniz işim daha erken biterdi.","puan":0,"tepki":"Şefin yüzündeki memnuniyet kaybolur. Geri bildirim emeği bir yük gibi görülürse usta da göstermekten vazgeçer; düzeltme, öğrenmenin kendisidir."},{"metin":"Sağ olun şefim, size de kolay gelsin; yarın dokuzda buradayım.","puan":1,"tepki":"Şef başını sallayıp çıkar. Kapanış kibar, ama günün dersi bir yere kaydedilmedi; yazılmayan ayrıntı ertesi gün kolayca unutulur."}]}]},{"id":"mg-d16","unite":8,"baslik":"Çok Çabuk Biten Bilgi Notu","rol":"Stajyer resepsiyonist","karsi":"Ön büro şefi","sahne":"Saat 16.30, ön büro. Ön büro şefi Kerem Bey, stajyerden ertesi gün konuklara verilecek kısa bir müze bilgi notu istemişti. Stajyer notu yarım saatte bir yapay zekâ aracıyla hazırladı; şef kâğıdı eline alıyor.","kavramlar":["mg-8-040","mg-8-039","mg-8-092","mg-8-033"],"adimlar":[{"konuk":"Bilgi notu hazır mı? Çok çabuk bitmiş. Nasıl hazırladın?","ingilizce":"Is the information sheet ready? That was quick. How did you put it together?","secenekler":[{"metin":"Kendim yazdım şefim, öğle arasında oturup tek tek uğraştım.","puan":0,"tepki":"Şef ekrandaki yapay zekâ penceresini görür ve susar. Aracın yazdığını kendi işin gibi sunmak dürüstlüğe aykırıdır; güven bir kez sarsılınca zor onarılır."},{"metin":"Taslağı yapay zekâ aracıyla çıkardım; bilgileri henüz doğrulamadım.","ingilizce":"I made the draft with an AI tool. I haven't checked the facts yet.","puan":2,"tepki":"Şef “Dürüst olman iyi” der ve notu birlikte okumaya başlarlar. Yapay zekâ yardımcı olabilir, ama ikna edici bir dille yanlış bilgi de verebilir; doğrulanmadan konuğa gitmez."},{"metin":"Yapay zekâ yazdı şefim, çok düzgün çıktı; bence olduğu gibi kullanabiliriz.","puan":1,"tepki":"Şef “Düzgün görünmesi doğru olduğunu gösterir mi?” diye sorar. Açık sözlü bir cevap, ama düzgün dil doğruluk kanıtı değildir; araç yardımcıdır, sorumluluk çalışandadır."}]},{"konuk":"Notta müzenin pazartesi kapalı olduğu yazıyor. Bundan emin misin?","ingilizce":"The sheet says the museum is closed on Mondays. Are you sure about that?","secenekler":[{"metin":"Emin değilim. Müzenin kendi resmî sitesine bakıp teyit edeyim.","ingilizce":"I'm not sure. Let me check the museum's official website and confirm.","puan":2,"tepki":"Şef “Bak bakalım” der. Kapalı günü yanlış öğrenen konuk boşuna yola çıkar; bilgi, kimin verdiği belli ve güncel olan resmî kaynaktan doğrulanır."},{"metin":"Yapay zekâ böyle yazdıysa doğrudur şefim, o çok kaynağa bakıyor.","puan":0,"tepki":"Şef başını iki yana sallar. Aracın verdiği bilgi sorgulanmadan kabul edildi; dijital okuryazarlık bilginin doğruluğunu sorgulamayı da içerir."},{"metin":"Bir sosyal medya paylaşımında da öyle yazıyordu şefim, iki kaynak da aynı.","puan":1,"tepki":"Şef “O paylaşımı kim yazmış?” diye sorar. Bilgiyi karşılaştırmak iyi bir adım, ama kimin, ne zaman yazdığı belli olmayan bir paylaşım güvenilir kaynak sayılmaz."}]},{"konuk":"Resmî sitede kapalı gün başka yazıyormuş, iyi ki baktın. Peki şu uzun tarih paragrafı nereden geldi?","ingilizce":"The official website gives a different closing day. Good thing you checked. And where did this long history paragraph come from?","secenekler":[{"metin":"Bir siteden kopyaladım ama kimse anlamaz şefim, altına otelin adını yazarız.","puan":0,"tepki":"Şef notu masaya bırakır: “Başkasının yazısına bizim adımızı mı koyacağız?” Kaynağı gizleyip emeği sahiplenmek etik dışıdır ve işletmenin adını da riske atar."},{"metin":"Bir gezi yazısından aldım. Kendi cümlelerimle kısaltıp kaynağını altına yazayım.","ingilizce":"I took it from a travel article. I'll shorten it in my own words and add the source at the bottom.","puan":2,"tepki":"Şef onaylar: “Böyle daha temiz.” Başkasının yazısını kendi işi gibi sunmamak ve kaynağı belirtmek, dijital kaynakta etik kullanımın temelidir."},{"metin":"Bir siteden aldım şefim; adresi aklımda, konuk sorarsa söylerim.","puan":1,"tepki":"Şef “Konuk sormazsa ne olacak?” der. Niyet kötü değil, ama kaynak notta yazılı olmadıkça okuyan kişi bilginin kime ait olduğunu bilemez."}]},{"konuk":"Güzel. Bir dahaki sefere böyle bir notu nasıl hazırlarsın?","ingilizce":"Good. Next time, how will you prepare a sheet like this?","secenekler":[{"metin":"Daha iyi bir yapay zekâ aracı bulurum şefim, o böyle hata yapmaz.","puan":0,"tepki":"Şef iç çeker: “Hiçbir araç hatasız değil.” Sorun araçta değil, doğrulama adımının atlanmasındaydı; araç değişse de bu adım değişmez."},{"metin":"Bundan sonra yapay zekâyı hiç kullanmam şefim, her şeyi elle yazarım.","puan":1,"tepki":"Şef güler: “O kadar da değil.” Dikkatli olmak doğru, ama aracı tümden bırakmak gereksiz; doğru kullanılan yapay zekâ işi hızlandıran bir yardımcıdır."},{"metin":"Aracı taslakta kullanırım; bilgiyi resmî kaynaktan doğrular, kaynağı yazarım.","ingilizce":"I'll use the tool for the draft, check the facts against an official source and add the sources.","puan":2,"tepki":"Şef “Tam olarak bu” der. Dijital araçla bilgiye ulaşmak, doğruluğunu sorgulamak ve etik biçimde kullanmak birlikte dijital okuryazarlıktır."}]},{"konuk":"Yarın sabah notu konuklara sen dağıt, İngilizce sorulara da sen cevap ver.","ingilizce":"Tomorrow morning you hand the sheet out to the guests and answer their questions in English.","secenekler":[{"metin":"Olur şefim, ama siz de yanımda olursanız içim daha rahat eder.","puan":1,"tepki":"Şef “Yakında olacağım” der. Destek istemek ayıp değil, ama görevi sahiplenen bir cümle şefe daha çok güven verirdi."},{"metin":"Memnuniyetle. Emin olmadığım bir soru gelirse “Teyit edip döneyim” derim.","ingilizce":"With pleasure. If I'm asked something I'm not sure about, I'll say, \\"Let me check and get back to you.\\"","puan":2,"tepki":"Şef gülümser: “İşte profesyonel cevap.” Konuğa yanlış bilgi vermek hiç bilgi vermemekten kötüdür; emin olunmayan yerde teyit sözü vermek güveni korur."},{"metin":"Tamam şefim, emin olmadığım soruya da aklıma ne gelirse söylerim.","puan":0,"tepki":"Şef ciddileşir: “Bugün neyi konuştuk?” Tahminle verilen bilgi konuğu yanlış yere gönderebilir; bütün günün dersi tek cümlede boşa gider."}]}]},{"id":"mg-d17","unite":9,"baslik":"Gece 03.00’te Kim Fırını Açık Bıraktı?","rol":"Teknik servis stajyeri","karsi":"Teknik müdür","sahne":"Saat 08.00, otelin teknik servis odası. Stajyer sabah ilk iş enerji izleme ekranına bakmış; gece mutfağın tüketiminde garip bir yükselme var. Teknik müdür Selim Bey kahvesiyle içeri giriyor.","kavramlar":["mg-9-043","mg-9-030","mg-9-015","mg-9-014","mg-9-041"],"adimlar":[{"konuk":"Günaydın. Enerji ekranına baktın mı? Gece olağan dışı bir şey var mı?","ingilizce":"Good morning. Have you checked the energy screen? Anything unusual overnight?","secenekler":[{"metin":"Bir yerde yükselme vardı galiba ama saatini ve bölümünü not almadım.","puan":1,"tepki":"Selim Bey ekranı kendisi açıp aramaya başlar. Fark etmek iyi bir başlangıç, ama sistemin asıl gücü tüketimin nerede ve ne zaman olduğunu göstermesidir; bu bilgi not edilmeliydi."},{"metin":"Yüksek bir şey gördüm, mutfağa gidip ana şalteri kendim kapattım, sorun çözüldü.","puan":0,"tepki":"Selim Bey irkilir: “Soğuk hava deposu da o hatta!” Ekranda olağan dışı bir şey gören stajyer kendi başına müdahale etmez, önce amirine bildirir."},{"metin":"Baktım. Gece 03.00’te mutfağın tüketimi olağandan yüksek; size göstermek için bekliyordum.","ingilizce":"I have. Kitchen consumption was unusually high at 3 a.m.; I was waiting to show you.","puan":2,"tepki":"Selim Bey ekrana eğilir: “Güzel yakalamışsın.” İzleme sistemi tüketimin yerini ve saatini gösterir; olağan dışı bir şey gören stajyer amirine bildirir."}]},{"konuk":"Peki sence neden olabilir? Bunu nasıl anlarız?","ingilizce":"So what do you think caused it? How can we find out?","secenekler":[{"metin":"Dün geceyle karşılaştıralım, yükselmenin saatini mutfağın kapanış saatiyle yan yana koyalım.","ingilizce":"Let's compare it with last night and put the time of the spike next to the kitchen's closing time.","puan":2,"tepki":"Selim Bey başını sallar: “Tam böyle.” Tek bir sayı az şey söyler; karşılaştırıldığında anlam kazanır ve karara yarayan sonuç çıkar."},{"metin":"Bana öyle geliyor ki sistem bozuk; bu ekranlar sık sık yanlış gösterir.","puan":0,"tepki":"Selim Bey kaşlarını kaldırır: “Kanıtın ne?” Veri analizi “bana öyle geliyor” yerine “veri bunu gösteriyor” demeyi sağlar; veri bakılmadan çöpe atılmaz."},{"metin":"Mutfaktakilere soralım; kim ne hatırlıyorsa ona göre karar veririz.","puan":1,"tepki":"Selim Bey “Sorarız, ama önce elimizdekine bakalım” der. Sormak yararlıdır, ama hafıza yanıltabilir; elde ölçülmüş veri varken önce o incelenir."}]},{"konuk":"Bu arada dün 214’te arıza bakımı yaptın. Oda boştu, değil mi? İçerisi nasıldı?","ingilizce":"By the way, you did a repair in 214 yesterday. The room was empty, wasn't it? How did you find it?","secenekler":[{"metin":"Kart yuvasında başka bir kart takılıydı, klima açıktı; klimayı kapattım ama kimseye söylemedim.","puan":1,"tepki":"Selim Bey “Klima yine açılacak, kart orada duruyor” der. Enerji o an kurtuldu, ama yuvadaki kart sistemi boşa çıkarmaya devam eder; durum şefe bildirilmeliydi."},{"metin":"Yuvada bir kart vardı; çıkarıp cebime koydum, nasılsa konuk fark etmez.","puan":0,"tepki":"Selim Bey ciddileşir: “O kart konuğun eşyası olabilir.” Odada bulunan bir şeyi almak güveni bozar; boş odada böyle bir kart görülünce şefe bildirilir, karar ona bırakılır."},{"metin":"Yuvaya başka bir kart takılmıştı, ışık ve klima açıktı. Kartı yerinde bıraktım, kat şefine bildirdim.","ingilizce":"Another card was left in the slot, with the lights and air conditioning on. I left it there and told the housekeeping supervisor.","puan":2,"tepki":"Selim Bey memnun olur: “Doğrusu bu.” Yuvaya bırakılan kart kart anahtarlı sistemi boşa çıkarır; boş odada böyle bir kart gören kendi başına karar vermez, şefine bildirir."}]},{"konuk":"Mutfağa baktık: büyük fırın gece açık unutulmuş. Ne öneririz? Kimseyi suçlamak istemiyorum.","ingilizce":"We checked the kitchen: the big oven was left on overnight. What do we suggest? I don't want to blame anyone.","secenekler":[{"metin":"Mutfak kapanış listesine fırın kontrolü ekleyelim, ekranı da her sabah okuyalım.","ingilizce":"Let's add an oven check to the kitchen closing list and read the screen every morning.","puan":2,"tepki":"Selim Bey not alır: “Bunu şefle konuşuyorum.” Boşa giden enerjiyi kesen doğru kullanım alışkanlığı da bir enerji verimliliği önlemidir; ölçüm de sorunu erken yakalar."},{"metin":"Mutfak kapısına büyük harflerle sert bir uyarı yazısı asalım, herkes görsün.","puan":1,"tepki":"Selim Bey “Belki, ama yazı bir hafta sonra görünmez olur” der. Uyarı iyi niyetlidir, ama kalıcı bir kontrol adımı ve düzenli ölçüm olmadan alışkanlık değişmez."},{"metin":"Bir kere olmuş, büyütmeyelim; fatura zaten her ay yüksek geliyor.","puan":0,"tepki":"Selim Bey iç çeker: “İşte fatura bu yüzden yüksek.” Fatura ay sonunda yalnız toplamı söyler; israfın yerini bilen ekip onu gidermezse aynı kayıp her gece sürer."}]},{"konuk":"Güzel iş çıkardın. Bugün öğrendiğini tek cümleyle söyle bakalım.","ingilizce":"Well done. Tell me what you learnt today in one sentence.","secenekler":[{"metin":"Fırın kapandı, mesele bitti; ekrana arada bir göz atmak yeter.","puan":1,"tepki":"Selim Bey gülümser: “Arada bir değil, her gün.” Bu seferki sorun çözüldü, ama ölçüm sürekli olmazsa bir sonraki israf yine geç fark edilir."},{"metin":"Dijital ekran israfın yerini gösterdi, biz önlemi aldık: ölçmek tasarrufa yol açtı.","ingilizce":"The digital screen showed us where the waste was, and we acted: measuring led to saving.","puan":2,"tepki":"Selim Bey elini omzuna koyar: “İşte ikiz dönüşüm bu.” Dijital teknoloji ölçer ve yönetir, yeşil hedef neyin ölçüleceğini söyler; biri ötekinin aracıdır."},{"metin":"Ekran olunca insana pek iş kalmıyor; sistem sorunu kendisi çözüyor.","puan":0,"tepki":"Selim Bey başını sallar: “Fırını sistem kapatmadı, biz kapattık.” Teknoloji ölçer ve gösterir; neyin yapılacağına karar veren ve uygulayan yine insandır."}]}]},{"id":"mg-d18","unite":9,"baslik":"Defter mi, Tablet mi?","rol":"Ön büro stajyeri","karsi":"Kıdemli resepsiyonist","sahne":"Saat 08.30, resepsiyon. Otel bir hafta önce kâğıtsız check-in’e geçti; stajyer yeni sistemin eğitimini almış. Yirmi yıllık resepsiyonist Nermin Hanım tableti bir kenara itiyor.","kavramlar":["mg-9-060","mg-9-037","mg-9-039","mg-9-056","mg-9-050"],"adimlar":[{"konuk":"Bu tablet işi bana göre değil. Ben defterimle daha hızlıyım; bu sistem sonunda işimizi elimizden alacak.","ingilizce":"This tablet business isn't for me. I'm faster with my notebook; this system will end up taking our jobs.","secenekler":[{"metin":"Sizi anlıyorum. Ben eğitimi aldım; isterseniz ilk kayıtları birlikte yapalım.","ingilizce":"I understand. I've had the training; shall we do the first few check-ins together?","puan":2,"tepki":"Nermin Hanım biraz yumuşar: “Peki, bir deneyelim.” Değişime direnç olağan bir tepkidir; açık bir dinleme ve birlikte deneme bu direnci azaltır."},{"metin":"Alışırsınız Nermin Hanım, artık her yerde böyle; yapacak bir şey yok.","puan":1,"tepki":"Nermin Hanım omuz silker, tableti yine eline almaz. Söz yanlış değil, ama kaygısı dinlenmedi; direncin altında çoğu zaman işini kaybetme ya da yetersiz görünme endişesi vardır."},{"metin":"Haklısınız; siz deftere yazmaya devam edin, ben sonra sisteme geçiririm.","puan":0,"tepki":"Nermin Hanım rahatlar, ama otelde aynı bilgi iki yere girilmeye başlar. Çift kayıt hem zaman kaybıdır hem hataya açıktır; direnç böyle geçiştirilirse değişim hiç olmaz."}]},{"konuk":"Bak, şu yaşlı bey telefondan kaydını yapamamış, bankoya geliyor. Şimdi ne yapacağız?","ingilizce":"Look, that elderly gentleman couldn't check in on his phone and he's coming to the desk. What do we do now?","secenekler":[{"metin":"Artık kâğıtsızız; telefondan yapması gerektiğini nazikçe kendisine söyleyelim.","puan":0,"tepki":"Nermin Hanım “Görüyor musun, ben demiştim” der. Dijital yolu kullanmak istemeyen ya da zorlanan konuğun kaydı her zaman bankoda yapılır; sistem konuğu dışarıda bırakmaz."},{"metin":"Kaydını bankoda yapalım; siz ekrana girin, ben yanınızda adımları göstereyim.","ingilizce":"Let's check him in at the desk. You enter it on the screen, and I'll show you the steps.","puan":2,"tepki":"Konuk birkaç dakikada anahtarını alır, Nermin Hanım da sistemi ilk kez kendisi kullanır. Zorlanan konuğun kaydı bankoda yapılır; görevli de veri girmek yerine konuğa zaman ayırır."},{"metin":"Bağlantıyı telefonuna bir daha gönderelim, bankonun önünde yeniden denesin.","puan":1,"tepki":"Konuk telefonuyla uğraşırken arkasında sıra oluşur. Yardım etme isteği var, ama zorlanan konuğu dijital yola zorlamak yerine kaydı bankoda yapmak gerekirdi."}]},{"konuk":"Oldu bak, sandığımdan kolaymış. Ben kahve molasına çıkıyorum, ekran açık kalsın, hemen dönerim.","ingilizce":"There, it's easier than I thought. I'm going for a coffee break; leave the screen on, I'll be right back.","secenekler":[{"metin":"Şifrenizi bana söyleyin, ekran kilitlenirse ben açarım hemen.","puan":0,"tepki":"Nermin Hanım duraksar: “Şifre kişiye özeldir.” Konuk bilgileri güvenle saklanmalıdır; şifre kimseyle paylaşılmaz, sistemde kimin ne yaptığı ancak böyle bilinir."},{"metin":"Tamam, ben bankodayım; ekrana göz kulak olurum, merak etmeyin.","puan":1,"tepki":"Nermin Hanım çıkar; bir dakika sonra stajyer bir konuğa yol göstermek için bankodan ayrılır ve ekran açık kalır. Bankodan ayrılırken konuk bilgilerinin göründüğü ekran kilitlenir."},{"metin":"Ekranı kilitleyelim; konuk bilgileri açık kalmasın, dönünce açarsınız.","ingilizce":"Let's lock the screen so guest details aren't left open; you can unlock it when you're back.","puan":2,"tepki":"Nermin Hanım ekranı kilitler: “Bunu ben söylemeliydim.” Konuk bilgileri yalnız gerektiği kadar görünür olmalı ve güvenle saklanmalıdır; bankodan ayrılırken ekran kilitlenir."}]},{"konuk":"Duydun mu, tanınmış bir oyuncu gelmiş! Kaydını açıp oda numarasına bakalım mı? Kızım çok sever, bir fotoğraf atsam…","ingilizce":"Have you heard? A famous actor has arrived! Shall we open his record and see his room number? My daughter loves him; if I could send her a photo…","secenekler":[{"metin":"Önce müdüre soralım; izin verirse bir bakarız, vermezse bakmayız.","puan":1,"tepki":"Nermin Hanım “Müdür ne der, belli” der. Sormak, kendi başına yapmaktan iyidir; ama cevap zaten açıktır: kayıt yalnız iş için açılır, merak bunun gerekçesi olamaz."},{"metin":"Yapmayalım; kayıtları yalnız işimiz için açarız. Konuğun bilgisi bize emanet.","ingilizce":"Let's not. We only open records for work. A guest's details are entrusted to us.","puan":2,"tepki":"Nermin Hanım hemen geri adım atar: “Haklısın, heyecana kapıldım.” İşi olmayan bir konuğun kaydını merakla açmamak dijital etiktir; konuk verisi izinsiz paylaşılmaz."},{"metin":"Olur, ben açarım; ekran görüntüsünü alıp telefonunuza gönderirim.","puan":0,"tepki":"Nermin Hanım bile duraksar: “Bu iş başımıza dert olur.” Konuk bilgisinin fotoğrafı çekilmez, kimseye gönderilmez; kişisel veri Kişisel Verilerin Korunması Kanunu ile korunur."}]},{"konuk":"İyi ki varsın. Bu sistemi bana sen öğrettin. Yarınki ikinci eğitime ben de katılayım mı?","ingilizce":"I'm glad you're here. You taught me this system. Shall I join tomorrow's second training session too?","secenekler":[{"metin":"Boşuna yorulmayın; nasılsa birkaç yıla sistem her şeyi kendi yapacak.","puan":0,"tepki":"Nermin Hanım yeniden kaygılanır: “O zaman ben ne olacağım?” Bu söz değişime direnci büyütür; dönüşümde öğrenmeyi bırakmak, çalışanı geride bırakır."},{"metin":"Siz artık sistemi biliyorsunuz; bence gitmenize pek gerek yok.","puan":1,"tepki":"Nermin Hanım kararsız kalır. Bugünkü adım iyiydi, ama tek günde öğrenilen yetmez; işi değişen çalışanın becerisini eğitimle yenilemesi gerekir."},{"metin":"Çok iyi olur, ben de katılacağım. Sistem değiştikçe öğrenmek ikimizin de işi.","ingilizce":"That would be great; I'm going too. As the system changes, learning is part of both our jobs.","puan":2,"tepki":"Nermin Hanım gülümser: “Yirmi yıl sonra stajyerden ders aldım.” Dönüşümde yerini koruyanlar öğrenmeyi sürdürenlerdir; okul bitince öğrenme bitmez."}]}]},{"id":"mg-d19","unite":10,"baslik":"İlk Maaş Günü","rol":"Resepsiyon görevlisi","karsi":"İnsan kaynakları uzmanı","sahne":"Ayın ilk iş günü, saat 10.00, otelin insan kaynakları ofisi. Bir ay önce işe başlayan genç resepsiyon görevlisi ilk maaşını almış, ama hesabına yatan tutar iş ilanındaki rakamdan az. Elinde telefonu ve bordrosuyla kapıyı çalıyor.","kavramlar":["mg-10-014","mg-10-015","mg-10-016","mg-10-009","mg-10-006"],"adimlar":[{"konuk":"Günaydın, gel otur. Yüzünden bir şey olduğu belli, nasıl yardımcı olabilirim?","ingilizce":"Good morning, come and sit down. I can see something is on your mind. How can I help?","secenekler":[{"metin":"Günaydın. Hesabıma yatan tutar ilandakinden az; bordromu birlikte okuyabilir miyiz?","ingilizce":"Good morning. The amount paid into my account is lower than in the job advert. Could we go through my payslip together?","puan":2,"tepki":"Uzman gülümseyip bordroyu masaya açar. Sorun sakin ve belgeyle anlatıldı; bordroda anlaşılmayan satırı insan kaynaklarına sormak çalışanın en doğal hakkıdır."},{"metin":"Maaşımı eksik yatırmışsınız, bu düpedüz haksızlık. Böyle devam edecekse ben burada çalışmam.","puan":0,"tepki":"Uzman kaşlarını kaldırır: “Önce bir bakalım istersen.” Neyin eksik olduğu öğrenilmeden suçlamak konuşmayı zorlaştırır; önce bordro okunur, sonra soru sorulur."},{"metin":"Günaydın. Maaşta bir tuhaflık var galiba, bir bakabilir misiniz acaba?","puan":1,"tepki":"Uzman “Hangi tutar, neyle karşılaştırdın?” diye sorar. Kibar bir başlangıç, ama sorun belirsiz anlatıldığı için ilk dakikalar ne sorulduğunu anlamaya gider."}]},{"konuk":"İlandaki rakam brüt ücretti, hesabına ise net ücret yatar. Arada ne olduğunu biliyor musun?","ingilizce":"The figure in the advert was gross pay, but what goes into your account is net pay. Do you know what happens in between?","secenekler":[{"metin":"Bir şeyler kesiliyor herhalde, ama tam olarak ne kesildiğini hiç bilmiyorum, kimse de anlatmadı.","puan":1,"tepki":"Uzman açıklamaya başlar. Dürüst bir cevap, ama brüt ile net arasındaki farkı bilmek işe başlamadan önce sorulması gereken temel bilgidir."},{"metin":"Bence kesinti olmamalı; ilanda ne yazıyorsa elime o geçmeliydi, başka bir şey kabul etmem.","puan":0,"tepki":"Uzman sabırla “Her çalışanın ücretinden yasal kesinti yapılır” der. Bu bir yanılgıdır: ilandaki brüt ücretten vergi ve prim düşülür, ele geçen tutar her zaman daha azdır."},{"metin":"Brüt, kesintilerden önceki tutar; vergi ve sosyal güvenlik primi düşülünce net kalıyor, değil mi?","ingilizce":"Gross is the amount before deductions; once tax and social security contributions are taken off, what is left is net, isn't it?","puan":2,"tepki":"Uzman “Aynen öyle” der ve başını sallar. Brüt ücret yasal kesintilerden önceki, net ücret ele geçen tutardır; farkı bilen çalışan bordrosunu kendisi okuyabilir."}]},{"konuk":"Peki o kesilen para nereye gidiyor sence? Bazıları “boşa gidiyor” diye düşünüyor.","ingilizce":"So where do you think the deducted money goes? Some people think it is simply lost.","secenekler":[{"metin":"Prim sağlığım ve emekliliğim için; vergi de yol, okul gibi kamu hizmetlerine gider.","ingilizce":"The contributions are for my health and my pension, and the tax goes to public services such as roads and schools.","puan":2,"tepki":"Uzman memnun kalır: “Bunu bilen az.” Kesintinin ne işe yaradığını bilen çalışan bordrosuna kaybını değil, hakkını görerek bakar."},{"metin":"Bir kısmı devlete gidiyor sanırım, gerisini pek düşünmedim açıkçası.","puan":1,"tepki":"Uzman “Yarısını bildin” der. Vergi kamu hizmetlerine gider, doğru; ama prim de çalışanın kendi sağlık ve emeklilik hakkı içindir, bu kısım unutulmamalı."},{"metin":"Valla bilmiyorum, ama kesildiğine göre benim için kaybolmuş, bir daha görmeyeceğim bir para.","puan":0,"tepki":"Uzman “Hiç de öyle değil” der. Kesilen para kaybolmaz: sosyal güvenlik primi çalışanın sağlık ve emeklilik hakkı içindir, vergi kamu hizmetlerine gider."}]},{"konuk":"Güzel. Şimdi net tutarın elinde. Bu ayı nasıl planlayacaksın?","ingilizce":"Good. Now you know your net pay. How are you going to plan this month?","secenekler":[{"metin":"Dikkatli harcarım, ay sonunda ne kalırsa onu da kenara koyarım.","puan":1,"tepki":"Uzman gülerek “Ay sonunda çoğu zaman bir şey kalmaz” der. Niyet doğru, ama ayrılacak para ay başında ayrılmazsa günlük harcamaların içinde erir."},{"metin":"Yol, yemek ve telefonu yazacağım; bir kısmını da daha ilk gün birikime ayıracağım.","ingilizce":"I will write down transport, food and my phone bill, and I will put part of it into savings on the very first day.","puan":2,"tepki":"Uzman “İşte bütçe bu” der. Bütçe net ücrete göre yapılır, zorunlu giderler önce yazılır ve birikim ay başında ayrılır; tasarrufun sırrı budur."},{"metin":"İlk iş konser bileti ve yeni kulaklık; kalanıyla ayı bir şekilde çıkarırım.","puan":0,"tepki":"Uzman “Yol ve yemek ne olacak?” diye sorar. İstekler zorunlu giderlerden önce karşılanırsa bütçe açık verir ve ay sonu borçla kapanır."}]},{"konuk":"Başka sorun olursa kapım açık. İlk maaşın hayırlı olsun!","ingilizce":"If you have any other questions, my door is always open. Congratulations on your first salary!","secenekler":[{"metin":"Çok teşekkür ederim. Bundan sonra bordromu her ay kendim okuyup kontrol edeceğim.","ingilizce":"Thank you very much. From now on, I will read and check my payslip myself every month.","puan":2,"tepki":"Uzman “Ne güzel” der ve kapıya kadar eşlik eder. Bordro emeğin hesabıdır; çalışılan gün, fazla mesai ve kesintiler orada görünür, okumadan bir kenara atılmaz."},{"metin":"Sağ olun. Ama yine de ilandaki rakamı alamamak açıkçası biraz canımı sıktı, ne yalan söyleyeyim.","puan":1,"tepki":"Uzman anlayışla başını sallar. Görüşme kibar bitti; ama brüt ile net farkı artık bilindiği için kırgınlık yersiz kaldı, öğrenilen bilgi kapanışa yansımadı."},{"metin":"Teşekkürler. Arkadaşlara da söyleyeyim, burada herkesin maaşı eksik yatıyor.","puan":0,"tepki":"Uzmanın yüzü düşer: “Eksik yatan bir şey yok ki.” Yanlış bilgiyi yaymak ekip içinde boş yere huzursuzluk yaratır; öğrenilen doğru bilgi paylaşılmalıydı."}]}]},{"id":"mg-d20","unite":10,"baslik":"Molada Gelen Mesaj","rol":"Garson","karsi":"İş arkadaşı","sahne":"Ağustos, saat 15.30, sahil otelinin personel dinlenme odası. Öğle servisinden yeni çıkan iki garsondan Emre telefonuna gelen bir mesajı heyecanla gösteriyor. Sezon sonuna iki ay kaldı ve Emre yaz boyunca biriktirdiği parayı düşünüyor.","kavramlar":["mg-10-060","mg-10-059","mg-10-055","mg-10-011","mg-10-053"],"adimlar":[{"konuk":"Bak, bankadan mesaj geldi: “Hesabınız kapatılacak, hemen bu bağlantıdan bilgilerinizi güncelleyin.” Hemen girip şifremi yazayım mı?","ingilizce":"Look, I have got a text from the bank: 'Your account will be closed; update your details through this link at once.' Shall I go in and type my password right away?","secenekler":[{"metin":"Bilemedim, bana pek güvenli gelmedi açıkçası; ama sonuçta senin hesabın, kararı sen verirsin.","puan":1,"tepki":"Emre kararsız kalır, parmağı hâlâ bağlantının üstündedir. Şüphe doğru, ama arkadaşı açık bir uyarı ve güvenli bir yol duymadan riskle baş başa kaldı."},{"metin":"Dur, bağlantıya dokunma. Bankaya kendi resmî uygulamasından ya da kartın arkasındaki numaradan bakalım.","ingilizce":"Wait, don't touch the link. Let's check with the bank through its official app or the number on the back of your card.","puan":2,"tepki":"Emre telefonu masaya bırakır. Mesajdaki bağlantıya tıklanmaz; bankaya her zaman kendi resmî kanalından ulaşılır, oltalamanın tuzağı tam da o bağlantıdır."},{"metin":"Gir tabii, hesabın kapanırsa maaşın yatmaz. Bekleme, hemen hallet.","puan":0,"tepki":"Emre bağlantıya dokunmak üzereyken duraksar. Bu tavsiye dolandırıcının istediği şeydir: korkutup acele ettirmek, düşünmeye zaman bırakmamak."}]},{"konuk":"Ama mesajda bankanın adı yazıyor, açılan sayfada logosu bile var. Nasıl sahte olsun?","ingilizce":"But the bank's name is in the message, and the page even has its logo. How could it be fake?","secenekler":[{"metin":"Haklısın, logosu ve adı varsa sorun yoktur. Bilgilerini yaz da işin bir an önce bitsin.","puan":0,"tepki":"Emre neredeyse şifresini yazacaktır. Logoya güvenmek oltalamanın en sık tuzağıdır; sahte sayfalar gerçeğine çok benzeyecek biçimde hazırlanır."},{"metin":"Logo varsa belki gerçektir, ama yine de emin olamayız bence.","puan":1,"tepki":"Emre “O zaman girebilirim” diye düşünür. Belirsiz cevap şüpheyi azalttı; logo ve ad güven ölçüsü değildir, kolayca taklit edilir."},{"metin":"Ad ve logo kolayca kopyalanır. Gerçek banka mesajla şifre ya da onay kodu istemez.","ingilizce":"A name and a logo are easy to copy. A real bank never asks for a password or a verification code by text.","puan":2,"tepki":"Emre şaşırır: “Bunu bilmiyordum.” Sahte sayfa bankanınkine çok benzer; banka müşterisinden mesajla ya da telefonda kart şifresini ve onay kodunu istemez."}]},{"konuk":"Tamam, girmiyorum. Bir de şuna bak: biri sosyal medyada “Bir ayda paranı ikiye katlarım, hiç risk yok” diyor. Yaz parasını oraya mı koysam?","ingilizce":"All right, I won't go in. And look at this: someone on social media says, 'I will double your money in a month, with no risk at all.' Should I put my summer money there?","secenekler":[{"metin":"Kaçırma bence! Herkes bir yerden kazanıyor, ben de biraz para koyarım.","puan":0,"tepki":"Emre heyecanlanır, ama içi rahat değildir. Büyük kazanç vaadi dolandırıcının yöntemidir; bu teklif fırsat değil, uyarı işaretidir."},{"metin":"Yüksek kazanç ile sıfır risk aynı teklifte olmaz. Bu söz tek başına bir uyarı işareti.","ingilizce":"High returns and zero risk never come in the same offer. That claim alone is a warning sign.","puan":2,"tepki":"Emre düşünür: “Doğru ya, kimse bedava kazandırmaz.” Beklenen kazanç yükseldikçe kaybetme olasılığı da yükselir; “garantili yüksek kazanç” bu ilişkiyle çelişir."},{"metin":"Hepsini koyma, biraz dene; tutarsa gerisini sonra koyarsın.","puan":1,"tepki":"Emre “Az koyarsam bir şey olmaz” der. Tutarı küçültmek temkinli görünür, ama teklifin kendisi şüpheliyse az para da gider; önce teklif sorgulanır."}]},{"konuk":"Haklısın. Ama ekimde otel kapanınca maaş da duruyor. Bu parayı ne yapayım?","ingilizce":"You are right. But when the hotel closes in October, the wages stop too. What should I do with this money?","secenekler":[{"metin":"Bankada dursun işte, kışın lazım oldukça ne kadar gerekiyorsa oradan çekip harcarsın.","puan":1,"tepki":"Emre “Olur” der ama planı yoktur. Paranın durması iyi, ama ayrı bir hedefe ayrılmayan birikim günlük harcamaların içinde erimeye başlar."},{"metin":"Kışın kredi kartıyla idare edersin, asgari ödemeyi yatırırsın; kartın var ya, hiç merak etme.","puan":0,"tepki":"Emre bir an rahatlar, sonra durur. Asgari ödeme yalnız gecikmeyi önler, kalan borca faiz işlemeye devam eder; kışı kartla geçirmek borcu büyütür."},{"metin":"Kışın giderini hesapla, o kadarını acil durum fonu olarak ayır; günlük harcamaya katma.","ingilizce":"Work out what the winter will cost and set that much aside as an emergency fund; don't use it for everyday spending.","puan":2,"tepki":"Emre hemen telefonuna bir not yazar. Sezonun erken kapanması önceden haber vermez; kenarda birkaç aylık gideri karşılayacak para, zor günde borca girmeyi önler."}]},{"konuk":"İyi ki sana gösterdim. O sahte mesajı ne yapayım, silip geçeyim mi?","ingilizce":"I'm glad I showed you. What should I do with that fake message? Just delete it and forget about it?","secenekler":[{"metin":"Önce bankana resmî numarasından haber ver, sonra sil. Bizim gruba da “tıklamayın” diye yaz.","ingilizce":"Tell your bank first through its official number, then delete it. And write in our group chat so no one clicks it.","puan":2,"tepki":"Emre teşekkür edip bankayı arar. Şüpheli bir durumda işlem yapılmaz, bankaya haber verilir; arkadaşları uyarmak da başkalarının aynı tuzağa düşmesini önler."},{"metin":"Silip geç, unut gitsin. Uğraşmaya değmez, nasılsa tıklamadın.","puan":1,"tepki":"Emre mesajı siler. Kendisi kurtuldu, ama banka habersiz kaldı ve aynı mesaj başka bir arkadaşın telefonuna da gelebilir."},{"metin":"Bağlantıyı gruba at, herkes girip baksın; belki birine gerçek gelir.","puan":0,"tepki":"Emre irkilir: “Ya biri girerse?” Sahte bağlantıyı yaymak dolandırıcının işini kolaylaştırır; bağlantı değil, uyarı paylaşılır."}]}]}]}]`);export{t};